// "THE WHEEL" — Hyperreal Coloured-Pencil Road Bicycle Hub inside a Flat-Coloured Tarot Frame

let CX = 600;
let CY = 538;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7319);
  noiseSeed(7319);
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Dark warm tabletop surround & card drop shadow
  drawTabletopAndShadow();

  // 2. Worn parchment-cream Tarot card base with rounded corners
  drawTarotCardBase();

  // 3. Hyperreal coloured-pencil close-up of the road bicycle hub & cassette
  drawHyperrealHubCenter();

  // 4. Flat-coloured symbolic Tarot frame, pen double-lines, corner rosettes & blank banner
  drawTarotFrameAndBanner();

  // 5. Final shuffling wear, corner scuffing, and aged patina
  drawCardAgingAndWear();

  noLoop();
}

// ============================================================================
// GEOMETRY & UTILITY HELPERS
// ============================================================================

function getRoundedRectPts(x, y, w, h, r, segsPerCorner = 8, jitter = 0) {
  let pts = [];
  let corners = [
    { cx: x + w - r, cy: y + r, startAng: -90, endAng: 0 },
    { cx: x + w - r, cy: y + h - r, startAng: 0, endAng: 90 },
    { cx: x + r, cy: y + h - r, startAng: 90, endAng: 180 },
    { cx: x + r, cy: y + r, startAng: 180, endAng: 270 }
  ];
  for (let c = 0; c < 4; c++) {
    let corner = corners[c];
    for (let i = 0; i <= segsPerCorner; i++) {
      let a = map(i, 0, segsPerCorner, corner.startAng, corner.endAng);
      let jx = jitter > 0 ? (noise(c * 20 + i * 0.4, 10) - 0.5) * jitter : 0;
      let jy = jitter > 0 ? (noise(c * 20 + i * 0.4, 90) - 0.5) * jitter : 0;
      pts.push([corner.cx + r * cos(a) + jx, corner.cy + r * sin(a) + jy]);
    }
  }
  return pts;
}

function drawPolyShape(pts, closeShape = true, curvature = 0) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape ? CLOSE : undefined);
}

function strokePolyOutline(pts, brushName, col, weight, closeShape = true) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  let n = closeShape ? pts.length : pts.length - 1;
  for (let i = 0; i < n; i++) {
    let p1 = pts[i];
    let p2 = pts[(i + 1) % pts.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

// 3D cylindrical projection for the slightly tilted road hub assembly
// r: radial distance from axle, ang: angle in degrees, z: position along hub axle
function hubPt(r, ang, z = 0) {
  let tiltDir = -24; // axle tilt direction in screen space
  let foreshorten = 0.92; // slight elliptical perspective (92% circular so it reads as The Wheel)
  let zShiftX = z * 0.42;
  let zShiftY = z * -0.24;

  let radA = ang - tiltDir;
  let u = r * cos(radA);
  let v = r * sin(radA) * foreshorten;

  let x = CX + zShiftX + u * cos(tiltDir) - v * sin(tiltDir);
  let y = CY + zShiftY + u * sin(tiltDir) + v * cos(tiltDir);
  return [x, y];
}

// ============================================================================
// 1. TABLETOP SURROUND & CARD DROP SHADOW
// ============================================================================

function drawTabletopAndShadow() {
  background("#140f0c");

  // Warm dark wood/tabletop washes
  brush.noStroke();
  brush.wash("#1b1410", 220);
  brush.rect(0, 0, 1200, 1200);

  // Subtle horizontal wood grain around the card edges
  brush.set("charcoal", "#241b15", 0.5);
  for (let i = 0; i < 65; i++) {
    let y = random(15, 1185);
    if (y > 85 && y < 1115) {
      // Only draw on left/right margins to save render budget
      brush.line(10, y, 255, y + random(-4, 4));
      brush.line(945, y, 1190, y + random(-4, 4));
    } else {
      brush.line(10, y, 1190, y + random(-6, 6));
    }
  }

  // Deep cast shadow beneath the rounded tarot card
  for (let s = 4; s >= 1; s--) {
    let expand = s * 5;
    let shPts = getRoundedRectPts(
      240 - expand * 0.4 + s * 2.5,
      60 - expand * 0.3 + s * 3.5,
      720 + expand * 0.8,
      1080 + expand * 0.8,
      44 + expand * 0.5,
      6,
      0
    );
    brush.noStroke();
    brush.wash("#080504", 65);
    drawPolyShape(shPts, true, 0);
  }
}

// ============================================================================
// 2. WORN PARCHMENT TAROT CARD BASE
// ============================================================================

function drawTarotCardBase() {
  let cardPts = getRoundedRectPts(240, 60, 720, 1080, 42, 10, 1.8);

  // Solid base parchment cream wash
  brush.noStroke();
  brush.wash("#efe1c6", 255);
  drawPolyShape(cardPts, true, 0);

  // Warm mottled parchment texture
  brush.fill("#e2cda6", 75);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.45, 0.25);
  drawPolyShape(cardPts, true, 0);
  brush.noFill();
  brush.noWash();
}

// ============================================================================
// 3. HYPERREAL COLOURED-PENCIL BICYCLE HUB & CASSETTE
// ============================================================================

function drawHyperrealHubCenter() {
  // Clip to the inner Tarot artwork window
  brush.clip([315, 135, 885, 975]);

  // 3A. Deep warm coloured-pencil atmospheric ground behind the spokes
  drawPencilBackdrop();

  // 3B. Rear-flange 3-cross spokes (background plane of spokes)
  drawSpokeWheelLayer(-34, 206, 16, 11, false);

  // 3C. Rear high-flange chrome rim peeking out behind the largest cog
  drawRearHubFlange(-26, 212);

  // 3D. 5 Stepped Cassette Cogs with machined bevels, cutouts & thick grease in teeth
  let cogs = [
    { z: -20, rInner: 150, rRoot: 185, rTip: 209, teeth: 28, phase: 0, cutouts: 8 },
    { z: -13, rInner: 130, rRoot: 162, rTip: 185, teeth: 24, phase: 6, cutouts: 7 },
    { z: -6,  rInner: 112, rRoot: 139, rTip: 161, teeth: 21, phase: 13, cutouts: 6 },
    { z: 1,   rInner: 96,  rRoot: 118, rTip: 138, teeth: 18, phase: 4, cutouts: 6 },
    { z: 8,   rInner: 82,  rRoot: 99,  rTip: 117, teeth: 15, phase: 11, cutouts: 0 }
  ];

  for (let c = 0; c < cogs.length; c++) {
    drawSingleCassetteCog(cogs[c], c);
  }

  // 3E. Central mirror-polished chrome hub shell, sky reflection, flange & quick-release
  drawChromeHubAndSkyReflection(16);

  // 3F. Foreground near-flange 3-cross polished spokes sweeping out from the central flange
  drawSpokeWheelLayer(16, 91, 8, 22, true);

  brush.noClip();
}

function drawPencilBackdrop() {
  // Rich warm dark sienna/umber base inside the window
  brush.noStroke();
  brush.wash("#261911", 255);
  brush.rect(315, 135, 570, 840);

  // Warm golden-ochre upper-left glow & deep sepia lower-right shadow
  brush.fill("#5c3c22", 110);
  brush.fillBleed(0.35, "out");
  brush.circle(470, 340, 240, 0.2);

  brush.fill("#875c34", 85);
  brush.fillBleed(0.35, "out");
  brush.circle(430, 280, 150, 0.2);

  brush.fill("#160e09", 140);
  brush.fillBleed(0.3, "out");
  brush.circle(740, 760, 260, 0.2);
  brush.noFill();
  brush.noWash();

  // Layered coloured-pencil cross-hatching for velvety photographic depth
  let hatchPasses = [
    { col: "#3d2719", ang: 32, spacing: 6.5, w: 0.45 },
    { col: "#24160e", ang: -42, spacing: 7.5, w: 0.45 },
    { col: "#543520", ang: 15, spacing: 9.0, w: 0.38 },
    { col: "#1b1418", ang: 75, spacing: 11.0, w: 0.35 }
  ];

  for (let p of hatchPasses) {
    brush.hatchStyle("cpencil", p.col, p.w);
    brush.hatch(p.spacing, p.ang, { rand: 0.08 });
    brush.noStroke();
    brush.rect(316, 136, 568, 838);
    brush.noHatch();
  }

  // Warm sunlit coloured-pencil tonal strokes in upper-left & golden halo around hub
  for (let i = 0; i < 160; i++) {
    let ang = random(0, 360);
    let rad = random(195, 440);
    let x = CX + rad * cos(ang);
    let y = CY + rad * sin(ang);
    let len = random(35, 85);

    // Lighter warm amber/terracotta in upper-left (180..300 deg), deep umber in lower-right
    let isLit = ang > 175 && ang < 310;
    let col = isLit
      ? random(["#7d532d", "#9c6b3b", "#b5834c", "#664022"])
      : random(["#2e1c11", "#3b2416", "#1f130c", "#472c1b"]);

    brush.set("cpencil", col, random(0.28, 0.52));
    let aStroke = ang + 90 + random(-25, 25);
    brush.line(
      x - ( len / 2 ) * cos(aStroke),
      y - ( len / 2 ) * sin(aStroke),
      x + ( len / 2 ) * cos(aStroke),
      y + ( len / 2 ) * sin(aStroke)
    );
  }
}

// Renders a 3-cross tangentially laced set of polished stainless-steel spokes
function drawSpokeWheelLayer(zFlange, rFlange, numPairs, basePhase, isForeground) {
  let rRim = 530;
  let crossAngle = 54; // tangential 3-cross sweep angle

  // Draw trailing ("heads-out") spokes first, then leading ("heads-in") spokes over them
  for (let pass = 0; pass < 2; pass++) {
    let dir = pass === 0 ? -1 : 1;

    for (let i = 0; i < numPairs; i++) {
      let holeAng = basePhase + i * (360 / numPairs) + (pass === 1 ? 360 / (numPairs * 2) : 0);
      let rimAng = holeAng + dir * crossAngle;

      let pStart = hubPt(rFlange, holeAng, zFlange);
      let pEnd = hubPt(rRim, rimAng, -45);

      // Spoke direction vector & normal vector
      let dx = pEnd[0] - pStart[0];
      let dy = pEnd[1] - pStart[1];
      let len = sqrt(dx * dx + dy * dy);
      let ux = dx / len;
      let uy = dy / len;
      let nx = -uy;
      let ny = ux;

      // Determine how light hits this spoke angle
      let spokeScreenAng = atan2(dy, dx);
      let lightFactor = abs(cos(spokeScreenAng - 135)); // brightest when perpendicular to upper-left light

      if (!isForeground) {
        // Rear-flange spokes: slightly softer warm pewter/steel behind the cassette
        brush.set("cpencil", "#19110b", 0.55);
        brush.line(pStart[0] + nx * 2.2, pStart[1] + ny * 2.2, pEnd[0] + nx * 2.2, pEnd[1] + ny * 2.2);

        brush.set("cpencil", "#6e5f50", 0.52);
        brush.line(pStart[0], pStart[1], pEnd[0], pEnd[1]);

        brush.set("2H", "#b8a894", 0.32);
        brush.line(pStart[0] - nx * 0.9, pStart[1] - ny * 0.9, pEnd[0] - nx * 0.9, pEnd[1] - ny * 0.9);

        if (lightFactor > 0.45) {
          brush.set("2H", "#ebe0cf", 0.22);
          brush.line(pStart[0] - nx * 1.1, pStart[1] - ny * 1.1, pEnd[0] - nx * 1.1, pEnd[1] - ny * 1.1);
        }
      } else {
        // Foreground near-flange spokes: hyper-crisp cylindrical stainless steel
        // 1. Cast shadow onto cassette cogs and backdrop below the spoke
        brush.set("cpencil", "#160f09", 0.62);
        brush.line(
          pStart[0] + 3.2,
          pStart[1] + 4.0,
          pEnd[0] + 4.5,
          pEnd[1] + 5.5
        );

        // 2. Dark shadow edge of the cylindrical spoke shaft
        brush.set("cpencil", "#2e2319", 0.48);
        brush.line(pStart[0] + nx * 2.1, pStart[1] + ny * 2.1, pEnd[0] + nx * 2.1, pEnd[1] + ny * 2.1);

        // 3. Warm reflected brass/earth bounce along the underside of the spoke
        brush.set("cpencil", "#9c784c", 0.42);
        brush.line(pStart[0] + nx * 0.9, pStart[1] + ny * 0.9, pEnd[0] + nx * 0.9, pEnd[1] + ny * 0.9);

        // 4. Core polished chrome/steel body
        brush.set("2H", "#c9bfb0", 0.48);
        brush.line(pStart[0], pStart[1], pEnd[0], pEnd[1]);

        // 5. Cool sky-tinted reflection along upper-facing spokes
        let skyReflect = (spokeScreenAng > -60 && spokeScreenAng < 60) || abs(spokeScreenAng) > 130;
        if (skyReflect) {
          brush.set("2H", "#9ec4db", 0.3);
          brush.line(pStart[0] - nx * 0.9, pStart[1] - ny * 0.9, pEnd[0] - nx * 0.9, pEnd[1] - ny * 0.9);
        }

        // 6. Razor-sharp specular highlight crest along the cylinder
        brush.set("rotring", "#fffdf7", 0.28 + lightFactor * 0.16);
        brush.line(pStart[0] - nx * 1.3, pStart[1] - ny * 1.3, pEnd[0] - nx * 1.3, pEnd[1] - ny * 1.3);

        // 7. J-bend spoke head seated in the countersunk flange hole
        drawSpokeHead(pStart[0], pStart[1], ux, uy, holeAng);
      }
    }
  }
}

function drawSpokeHead(x, y, ux, uy, ang) {
  // Countersunk dark hole rim in the flange
  brush.noStroke();
  brush.wash("#1c140e", 230);
  brush.circle(x - ux * 2.5, y - uy * 2.5, 4.8, 0.08);

  // Polished J-bend button head
  brush.wash("#b8afa0", 240);
  brush.circle(x, y, 4.0, 0.05);
  brush.noWash();

  // Tiny sky-blue & pure white glint on the curved J-bend elbow
  let isUpperLeft = ang > 160 && ang < 310;
  if (isUpperLeft) {
    brush.set("rotring", "#7ec4f2", 0.35);
    brush.arc(x, y, 2.8, 180, 320);
  }
  brush.set("rotring", "#ffffff", 0.32);
  brush.line(x - 1.5, y - 1.5, x + 1.2, y - 0.5);
}

function drawRearHubFlange(z, rOuter) {
  let ptsOuter = [];
  for (let a = 0; a < 360; a += 5) {
    ptsOuter.push(hubPt(rOuter, a, z));
  }
  brush.noStroke();
  brush.wash("#8a7d6d", 240);
  drawPolyShape(ptsOuter, true, 0);

  // Metallic rim highlights & spoke holes around the rear flange
  for (let a = 0; a < 360; a += 6) {
    let p1 = hubPt(rOuter - 8, a, z);
    let p2 = hubPt(rOuter, a, z);
    let isLit = a > 170 && a < 290;
    let col = isLit ? "#f2eadc" : (a < 95 ? "#3d3126" : "#a89985");
    brush.set("cpencil", col, 0.42);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 32 spoke holes on rear flange
  for (let i = 0; i < 32; i++) {
    let a = i * 11.25 + 5;
    let ph = hubPt(rOuter - 4.5, a, z);
    brush.set("cpencil", "#1f160f", 0.55);
    brush.circle(ph[0], ph[1], 2.8, 0.05);
    brush.set("2H", "#ffffff", 0.25);
    brush.arc(ph[0], ph[1], 3.0, 190, 310);
  }
}

// ============================================================================
// 3D. HYPERREAL CASSETTE COGS & GREASE CAUGHT IN TEETH
// ============================================================================

function drawSingleCassetteCog(cog, cogIdx) {
  let { z, rInner, rRoot, rTip, teeth, phase, cutouts } = cog;
  let step = 360 / teeth;
  let ptsCog = [];

  // Build exact toothed sprocket silhouette
  for (let i = 0; i < teeth; i++) {
    let a0 = i * step + phase;
    // Root valley (curved U-bottom between teeth)
    ptsCog.push(hubPt(rRoot, a0 - step * 0.44, z));
    ptsCog.push(hubPt(rRoot - 1.5, a0 - step * 0.33, z));
    ptsCog.push(hubPt(rRoot, a0 - step * 0.22, z));
    // Drive-side rising tooth flank
    ptsCog.push(hubPt(rRoot + (rTip - rRoot) * 0.55, a0 - step * 0.15, z));
    // Tooth top land (flat crest)
    ptsCog.push(hubPt(rTip, a0 - step * 0.08, z));
    ptsCog.push(hubPt(rTip, a0 + step * 0.08, z));
    // Non-drive falling flank with shift bevel
    ptsCog.push(hubPt(rRoot + (rTip - rRoot) * 0.55, a0 + step * 0.16, z));
    ptsCog.push(hubPt(rRoot, a0 + step * 0.24, z));
  }

  // 1. Cast shadow onto the larger cog behind this one
  let ptsShadow = ptsCog.map(p => [p[0] + 4.5, p[1] + 5.5]);
  brush.noStroke();
  brush.wash("#140d07", 170);
  drawPolyShape(ptsShadow, true, 0);

  // 2. 3D extruded metallic plate thickness (shifted slightly back along axle)
  let ptsBackEdge = ptsCog.map(p => [p[0] - 2.8, p[1] + 1.8]);
  brush.wash("#33281e", 255);
  drawPolyShape(ptsBackEdge, true, 0);

  // 3. Base warm nickel-steel wash for the cog face
  let baseCols = ["#918372", "#9e907e", "#877968", "#a89a88", "#948675"];
  brush.wash(baseCols[cogIdx % baseCols.length], 255);
  drawPolyShape(ptsCog, true, 0);
  brush.noWash();

  // 4. Radial & circumferential coloured-pencil metallic shading across the cog ring
  for (let a = 0; a < 360; a += 3) {
    let pIn = hubPt(rInner, a, z);
    let pOut = hubPt(rRoot - 1, a, z);

    // Anisotropic brushed metal sheen: two bright specular lobes (upper-left & lower-right)
    let sheen1 = exp(-pow(((a - 228 + 540) % 360) - 180, 2) / 1400);
    let sheen2 = exp(-pow(((a - 48 + 540) % 360) - 180, 2) / 2200) * 0.65;
    let darkLobe = exp(-pow(((a - 125 + 540) % 360) - 180, 2) / 1800);

    let col = "#7d6f5f";
    let w = 0.36;
    if (sheen1 > 0.65) {
      col = sheen1 > 0.85 ? "#f7f0e4" : "#d9cbb8";
      w = 0.42;
    } else if (sheen2 > 0.4) {
      col = "#cbb28b"; // warm golden bounce reflection
      w = 0.38;
    } else if (darkLobe > 0.5) {
      col = "#4a3d31";
      w = 0.42;
    } else if (a > 195 && a < 265) {
      col = "#b5cde0"; // faint cool sky tint on upper-left steel
    }

    brush.set("cpencil", col, w);
    brush.line(pIn[0], pIn[1], pOut[0], pOut[1]);
  }

  // 5. Weight-saving oval cutouts in the cog web (revealing the chrome hub barrel behind!)
  if (cutouts > 0) {
    let cutStep = 360 / cutouts;
    let rCutMid = (rInner + rRoot) * 0.5;
    let rCutHalf = (rRoot - rInner) * 0.28;
    for (let k = 0; k < cutouts; k++) {
      let aCut = k * cutStep + phase * 1.7;
      let cutPts = [];
      for (let t = 0; t < 360; t += 30) {
        let rr = rCutMid + rCutHalf * cos(t);
        let aa = aCut + (rCutHalf * 1.15 * sin(t) * 57.3) / rCutMid;
        cutPts.push(hubPt(rr, aa, z));
      }
      // Dark interior depth + glimpse of chrome barrel & sky reflection inside cutout
      brush.noStroke();
      let isSkyWindow = aCut > 205 && aCut < 265;
      brush.wash(isSkyWindow ? "#4689b8" : "#1c130c", 245);
      drawPolyShape(cutPts, true, 0);
      brush.noWash();

      // Inner bevel of the cutout hole
      strokePolyOutline(cutPts, "rotring", isSkyWindow ? "#d9f2ff" : "#524132", 0.26, true);
    }
  }

  // 6. Detailed individual Tooth Bevels, Shift Ramps, and GREASE CAUGHT IN TEETH
  for (let i = 0; i < teeth; i++) {
    let a0 = i * step + phase;
    let isUpperLit = a0 > 175 && a0 < 295;
    let isWarmLit = a0 > 20 && a0 < 95;

    let pRootL = hubPt(rRoot, a0 - step * 0.22, z);
    let pTipL = hubPt(rTip, a0 - step * 0.08, z);
    let pTipR = hubPt(rTip, a0 + step * 0.08, z);
    let pRootR = hubPt(rRoot, a0 + step * 0.24, z);
    let pRampMid = hubPt(rRoot + (rTip - rRoot) * 0.45, a0 + step * 0.02, z);

    // Machined shift-ramp facet on each tooth
    let facetPts = [pTipL, pTipR, pRootR, pRampMid];
    brush.noStroke();
    brush.wash(isUpperLit ? "#e8dfd1" : (isWarmLit ? "#bfa074" : "#5e5042"), 210);
    drawPolyShape(facetPts, true, 0);
    brush.noWash();

    // Crisp metallic outline & bevel crease of the tooth
    brush.set("2H", "#2b2017", 0.28);
    brush.line(pRootL[0], pRootL[1], pTipL[0], pTipL[1]);
    brush.line(pTipR[0], pTipR[1], pRootR[0], pRootR[1]);

    // Bright specular edge highlight on tooth crest & bevel
    brush.set("rotring", isUpperLit ? "#ffffff" : "#d9cab4", isUpperLit ? 0.32 : 0.2);
    brush.line(pTipL[0], pTipL[1], pTipR[0], pTipR[1]);
    brush.line(pTipL[0], pTipL[1], pRampMid[0], pRampMid[1]);

    // ---- GREASE CAUGHT IN THE CASSETTE TEETH ----
    // The U-valley sits between this tooth's falling flank (a0 + step*0.24)
    // and the next tooth's rising flank (a0 + step*0.78)
    let aValley = a0 + step * 0.5;
    let greaseAmt = noise(cogIdx * 7.3, i * 0.65);

    // Every tooth valley has dark road grease at the root; ~75% have thick amber-black blobs
    let gRoot1 = hubPt(rRoot - 2.0, aValley - step * 0.24, z);
    let gRootMid = hubPt(rRoot - 2.5, aValley, z);
    let gRoot2 = hubPt(rRoot - 1.5, aValley + step * 0.26, z);

    let climbDrive = rRoot + (rTip - rRoot) * (0.28 + greaseAmt * 0.48);
    let climbBack = rRoot + (rTip - rRoot) * (0.18 + greaseAmt * 0.32);
    let gFlank2 = hubPt(climbDrive, aValley + step * 0.22, z);
    let gMeniscus = hubPt(rRoot + (rTip - rRoot) * (0.12 + greaseAmt * 0.25), aValley + step * 0.04, z);
    let gFlank1 = hubPt(climbBack, aValley - step * 0.18, z);

    // Layer A: Translucent warm amber/molasses grease smear around the meniscus
    let amberPts = [gRoot1, gRootMid, gRoot2, gFlank2, gMeniscus, gFlank1];
    brush.noStroke();
    brush.wash("#6b4416", 210);
    drawPolyShape(amberPts, true, 0);

    // Layer B: Thick dark carbon-black / espresso grease pooled deep in the tooth valley
    let coreMeniscus = hubPt(rRoot + (rTip - rRoot) * (0.06 + greaseAmt * 0.16), aValley + step * 0.06, z);
    let coreFlank2 = hubPt(rRoot + (rTip - rRoot) * (0.18 + greaseAmt * 0.32), aValley + step * 0.21, z);
    let corePts = [gRoot1, gRootMid, gRoot2, coreFlank2, coreMeniscus];
    brush.wash("#170f07", 245);
    drawPolyShape(corePts, true, 0);
    brush.noWash();

    // Layer C: Viscous amber-brown pencil texture & sticky grease threads across the valley
    brush.set("cpencil", "#8c5b1e", 0.34);
    brush.line(gFlank1[0], gFlank1[1], gFlank2[0], gFlank2[1]);
    brush.set("cpencil", "#38220b", 0.38);
    brush.line(gRootMid[0], gRootMid[1], coreFlank2[0], coreFlank2[1]);

    // Layer D: Wet pinpoint specular highlight on the curved meniscus of the grease!
    brush.set("rotring", "#fff8e6", 0.28);
    brush.line(
      gMeniscus[0] - 1.2,
      gMeniscus[1] - 0.8,
      coreFlank2[0] * 0.4 + gMeniscus[0] * 0.6,
      coreFlank2[1] * 0.4 + gMeniscus[1] * 0.6
    );
  }

  // Inner step shadow of this cog
  let innerRingPts = [];
  for (let a = 0; a < 360; a += 8) {
    innerRingPts.push(hubPt(rInner, a, z));
  }
  strokePolyOutline(innerRingPts, "cpencil", "#2b1f15", 0.42, true);
}

// ============================================================================
// 3E. CENTRAL MIRROR-POLISHED CHROME HUB & SKY REFLECTION
// ============================================================================

function drawChromeHubAndSkyReflection(zHub) {
  // 1. Outer polished hub flange collar (R = 82..98)
  let flangePts = [];
  for (let a = 0; a < 360; a += 5) {
    flangePts.push(hubPt(98, a, zHub));
  }
  brush.noStroke();
  brush.wash("#cfc5b4", 255);
  drawPolyShape(flangePts, true, 0);
  brush.noWash();

  // Radial chrome shading on the outer flange collar (R = 80..98)
  for (let a = 0; a < 360; a += 3) {
    let p1 = hubPt(80, a, zHub);
    let p2 = hubPt(98, a, zHub);
    let col = "#9e9180";
    if (a > 200 && a < 265) col = "#ffffff";
    else if (a > 175 && a <= 200) col = "#b5daef";
    else if (a >= 265 && a < 310) col = "#ded4c3";
    else if (a > 25 && a < 85) col = "#e6cfa8";
    else if (a >= 85 && a <= 165) col = "#3b2c20";

    brush.set("cpencil", col, 0.38);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 2. Convex Mirror-Polished Chrome Hub Dome / Barrel (R = 30..81)
  // Base dark warm reflection wash for the mirror chrome
  let domePts = [];
  for (let a = 0; a < 360; a += 5) {
    domePts.push(hubPt(81, a, zHub + 3));
  }
  brush.noStroke();
  brush.wash("#241810", 255);
  drawPolyShape(domePts, true, 0);
  brush.noWash();

  // Circumferential coloured-pencil bands warping the world across the convex chrome
  for (let r = 31; r <= 80; r += 1.6) {
    for (let a = 0; a < 360; a += 6) {
      let p1 = hubPt(r, a, zHub + 3);
      let p2 = hubPt(r, a + 6.5, zHub + 3);

      let col = "#2a1c12";
      let w = 0.38;

      // THE TINY REFLECTION OF SKY GLINTING IN THE CHROME (Upper-left quadrant: a = 192..282, r = 40..76)
      let inSkyPatch = a >= 192 && a <= 282 && r >= 40 && r <= 76;
      // Secondary small sky reflection on opposite concave bezel (lower-right: a = 32..76, r = 70..79)
      let inSecondSky = a >= 32 && a <= 76 && r >= 70 && r <= 79;

      if (inSkyPatch) {
        // Distance from center of the sky glint at (r = 58, a = 236)
        let dr = (r - 58) / 18;
        let da = (a - 236) / 44;
        let distSq = dr * dr + da * da;

        if (distSq < 0.14) {
          col = "#ffffff"; // Blinding sun/cloud glint in the heart of the sky reflection
          w = 0.48;
        } else if (distSq < 0.35) {
          col = "#c8eeff"; // Luminous pale azure
          w = 0.44;
        } else if (distSq < 0.65) {
          col = "#5bb2eb"; // Vivid cerulean sky blue
          w = 0.42;
        } else {
          col = "#246da3"; // Deep zenith sky blue near the horizon frame
          w = 0.4;
        }
      } else if (inSecondSky) {
        col = r > 74 ? "#b8e6ff" : "#3d8cc2";
        w = 0.38;
      } else {
        // Warped dark horizon, warm workshop bench, and metallic chrome transitions
        if (a > 175 && a < 300) {
          // Dark silhouetted treeline/horizon framing the sky reflection
          col = r > 76 || r < 38 ? "#cfc3b2" : "#181210";
        } else if (a >= 300 || a < 30) {
          // Warm silver-gold transition
          col = r > 58 ? "#b8a48a" : "#594330";
        } else if (a >= 30 && a < 110) {
          // Warm sunlit earth/ochre reflection in lower-right chrome
          col = r > 45 && r < 68 ? "#b58347" : "#422c1a";
        } else {
          // Deep espresso shadow reflection
          col = r > 72 ? "#7a6855" : "#21150d";
        }
      }

      brush.set("cpencil", col, w);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // Crisp pure white specular star-glint & horizon line inside the chrome sky reflection
  let glintC = hubPt(58, 236, zHub + 4);
  let glintL = hubPt(58, 216, zHub + 4);
  let glintR = hubPt(58, 256, zHub + 4);
  brush.set("rotring", "#ffffff", 0.45);
  brush.line(glintL[0], glintL[1], glintR[0], glintR[1]);
  brush.line(glintC[0] - 8, glintC[1] + 5, glintC[0] + 8, glintC[1] - 5);

  // Outer & inner chrome bezel rings with cassette lockring notches (R = 81)
  for (let i = 0; i < 12; i++) {
    let a = i * 30;
    let pN1 = hubPt(79, a, zHub + 3);
    let pN2 = hubPt(84, a + 8, zHub + 3);
    brush.set("rotring", "#1a120c", 0.35);
    brush.line(pN1[0], pN1[1], pN2[0], pN2[1]);
  }

  // 3. Central Axle End-Cap & Quick-Release Skewer Assembly (R = 0..30)
  let capPts = [];
  for (let a = 0; a < 360; a += 10) {
    capPts.push(hubPt(30, a, zHub + 7));
  }
  brush.noStroke();
  brush.wash("#3b2f25", 255);
  drawPolyShape(capPts, true, 0);
  brush.noWash();

  // Knurled stainless quick-release nut (R = 18..30)
  for (let a = 0; a < 360; a += 10) {
    let p1 = hubPt(18, a, zHub + 8);
    let p2 = hubPt(30, a, zHub + 7);
    let isLit = a > 180 && a < 290;
    brush.set("2H", isLit ? "#f5eee2" : "#706050", 0.32);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Recessed hollow axle & dark greased hex socket at exact center (R = 0..17)
  let hexPts = [];
  for (let k = 0; k < 6; k++) {
    hexPts.push(hubPt(12, k * 60 + 15, zHub + 9));
  }
  brush.noStroke();
  brush.wash("#120b06", 255);
  drawPolyShape(hexPts, true, 0);
  brush.noWash();

  // Touch of golden grease & specular rim on the center hex broach
  strokePolyOutline(hexPts, "cpencil", "#87581d", 0.35, true);
  let pHexLit1 = hexPts[3];
  let pHexLit2 = hexPts[4];
  brush.set("rotring", "#ffffff", 0.32);
  brush.line(pHexLit1[0], pHexLit1[1], pHexLit2[0], pHexLit2[1]);
}

// ============================================================================
// 4. FLAT-COLOURED SYMBOLIC TAROT FRAME, CORNER ROSETTES & BLANK BANNER
// ============================================================================

function drawTarotFrameAndBanner() {
  let vermilion = "#c84c32";
  let ultramarine = "#284678";
  let cream = "#efe1c4";
  let ochre = "#d1a249";
  let ink = "#221913";

  // 4A. Flat-coloured border strips masking around the inner window (315..885, 135..975)
  // Outer border sits at (272..928, 92..1108)
  brush.noStroke();

  // First lay down clean parchment cream over the four border margins so flat colours are crisp
  brush.wash(cream, 255);
  brush.rect(242, 62, 716, 73);   // top margin
  brush.rect(242, 975, 716, 163); // bottom margin
  brush.rect(242, 135, 73, 840);  // left margin
  brush.rect(885, 135, 73, 840);  // right margin

  // Flat-coloured geometric panels inside the border track (width = 43px: 272..315 & 885..928)
  // Left & Right vertical border compartments alternating Faded Vermilion, Ultramarine, and Cream
  let vSegs = 9;
  let yStart = 150;
  let yEnd = 942;
  let segH = (yEnd - yStart) / vSegs;

  for (let i = 0; i < vSegs; i++) {
    let y0 = yStart + i * segH;
    let colL = i % 2 === 0 ? vermilion : ultramarine;
    let colR = i % 2 === 0 ? ultramarine : vermilion;

    // Left panel
    brush.wash(colL, 235);
    brush.rect(278, y0 + 5, 31, segH - 10);
    // Right panel
    brush.wash(colR, 235);
    brush.rect(891, y0 + 5, 31, segH - 10);

    // Small ochre/cream divider bars between panels
    brush.wash(ochre, 220);
    brush.rect(278, y0 - 2, 31, 5);
    brush.rect(891, y0 - 2, 31, 5);
  }

  // Top horizontal border compartments (x = 330..870, y = 98..129)
  let hSegs = 7;
  let xStart = 330;
  let xEnd = 870;
  let segW = (xEnd - xStart) / hSegs;
  for (let i = 0; i < hSegs; i++) {
    let x0 = xStart + i * segW;
    let colT = i % 2 === 0 ? ultramarine : vermilion;
    brush.wash(colT, 235);
    brush.rect(x0 + 5, 98, segW - 10, 31);

    brush.wash(ochre, 220);
    brush.rect(x0 - 2, 98, 5, 31);
  }

  // Bottom decorative frame zone behind the Blank Title Banner (x = 278..922, y = 981..1102)
  brush.wash(ultramarine, 230);
  brush.rect(278, 1010, 644, 86);
  brush.wash(vermilion, 230);
  brush.rect(286, 1018, 628, 70);
  brush.noWash();

  // Inner corner spandrels inside the artwork window corners (flat-coloured symbolic triangles)
  let spandrelSize = 44;
  let winCorners = [
    [[315, 135], [315 + spandrelSize, 135], [315, 135 + spandrelSize]],
    [[885, 135], [885 - spandrelSize, 135], [885, 135 + spandrelSize]],
    [[315, 975], [315 + spandrelSize, 975], [315, 975 - spandrelSize]],
    [[885, 975], [885 - spandrelSize, 975], [885, 975 - spandrelSize]]
  ];
  for (let s of winCorners) {
    brush.noStroke();
    brush.wash(cream, 255);
    drawPolyShape(s, true, 0);
    brush.wash(vermilion, 225);
    drawPolyShape(s, true, 0);
    brush.noWash();
    strokePolyOutline(s, "rotring", ink, 0.45, true);
  }

  // 4B. Pen-drawn Borders of Fine Double Lines
  // Outer double-line border
  drawDoubleLineRect(272, 92, 656, 1016, 6, ink, 0.48);
  // Inner window double-line border
  drawDoubleLineRect(312, 132, 576, 846, 5, ink, 0.48);
  // Divider double lines for every border compartment
  brush.set("rotring", ink, 0.35);
  for (let i = 0; i <= vSegs; i++) {
    let y0 = yStart + i * segH;
    brush.line(278, y0 - 2, 312, y0 - 2);
    brush.line(278, y0 + 3, 312, y0 + 3);
    brush.line(888, y0 - 2, 922, y0 - 2);
    brush.line(888, y0 + 3, 922, y0 + 3);
  }
  for (let i = 0; i <= hSegs; i++) {
    let x0 = xStart + i * segW;
    brush.line(x0 - 2, 98, x0 - 2, 132);
    brush.line(x0 + 3, 98, x0 + 3, 132);
  }

  // 4C. Four Corner Rosettes (Top-Left, Top-Right, Bottom-Left, Bottom-Right)
  let rosetteCenters = [
    [298, 118],
    [902, 118],
    [298, 976],
    [902, 976]
  ];
  for (let rc of rosetteCenters) {
    drawCornerRosette(rc[0], rc[1], 34, vermilion, ultramarine, cream, ochre, ink);
  }

  // 4D. Blank Title Banner at the Base
  drawBlankTitleBanner(600, 1046, vermilion, ultramarine, cream, ink);
}

function drawDoubleLineRect(x, y, w, h, gap, inkCol, weight) {
  brush.noFill();
  brush.noWash();
  brush.set("rotring", inkCol, weight);
  brush.rect(x, y, w, h, "corner");
  brush.rect(x + gap, y + gap, w - gap * 2, h - gap * 2, "corner");
}

function drawCornerRosette(cx, cy, halfSize, vermilion, ultramarine, cream, ochre, ink) {
  let s = halfSize;
  let sqOuter = [
    [cx - s, cy - s],
    [cx + s, cy - s],
    [cx + s, cy + s],
    [cx - s, cy + s]
  ];
  let sIn = s - 5;
  let sqInner = [
    [cx - sIn, cy - sIn],
    [cx + sIn, cy - sIn],
    [cx + sIn, cy + sIn],
    [cx - sIn, cy + sIn]
  ];

  // Square rosette ground in parchment cream + ultramarine inner square
  brush.noStroke();
  brush.wash(cream, 255);
  drawPolyShape(sqOuter, true, 0);
  brush.wash(ultramarine, 235);
  drawPolyShape(sqInner, true, 0);

  // Rosette circular wheel medallion
  brush.wash(cream, 255);
  brush.circle(cx, cy, sIn - 2, 0.04);

  // 8 outer rosette petals in faded vermilion
  let numPetals = 8;
  for (let i = 0; i < numPetals; i++) {
    let a = i * (360 / numPetals);
    let pTip = [cx + (sIn - 3) * cos(a), cy + (sIn - 3) * sin(a)];
    let pL = [cx + 12 * cos(a - 22), cy + 12 * sin(a - 22)];
    let pR = [cx + 12 * cos(a + 22), cy + 12 * sin(a + 22)];
    let pCenter = [cx, cy];
    brush.wash(vermilion, 235);
    drawPolyShape([pCenter, pL, pTip, pR], true, 0.2);
  }

  // 8 inner alternating petals in parchment cream / ochre
  for (let i = 0; i < numPetals; i++) {
    let a = i * (360 / numPetals) + 22.5;
    let pTip = [cx + (sIn - 9) * cos(a), cy + (sIn - 9) * sin(a)];
    let pL = [cx + 7 * cos(a - 18), cy + 7 * sin(a - 18)];
    let pR = [cx + 7 * cos(a + 18), cy + 7 * sin(a + 18)];
    brush.wash(cream, 250);
    drawPolyShape([[cx, cy], pL, pTip, pR], true, 0.15);
  }

  // Central hub eye of the rosette
  brush.wash(ochre, 245);
  brush.circle(cx, cy, 8, 0.04);
  brush.wash(ultramarine, 245);
  brush.circle(cx, cy, 4.5, 0.04);
  brush.noWash();

  // Crisp pen-drawn double-line borders & petal ink work
  strokePolyOutline(sqOuter, "rotring", ink, 0.48, true);
  strokePolyOutline(sqInner, "rotring", ink, 0.4, true);

  brush.set("rotring", ink, 0.36);
  brush.circle(cx, cy, sIn - 2, 0.03);
  brush.circle(cx, cy, 8, 0.03);
  brush.circle(cx, cy, 4.5, 0.03);

  for (let i = 0; i < numPetals; i++) {
    let a = i * (360 / numPetals);
    let pTip = [cx + (sIn - 3) * cos(a), cy + (sIn - 3) * sin(a)];
    let pL = [cx + 12 * cos(a - 22), cy + 12 * sin(a - 22)];
    let pR = [cx + 12 * cos(a + 22), cy + 12 * sin(a + 22)];
    brush.line(pL[0], pL[1], pTip[0], pTip[1]);
    brush.line(pR[0], pR[1], pTip[0], pTip[1]);
    brush.line(cx + 8 * cos(a), cy + 8 * sin(a), pTip[0], pTip[1]);
  }
}

function drawBlankTitleBanner(cx, cy, vermilion, ultramarine, cream, ink) {
  let bw = 460;
  let bh = 68;
  let xL = cx - bw / 2;
  let xR = cx + bw / 2;
  let yT = cy - bh / 2;
  let yB = cy + bh / 2;

  // 1. Left & Right Swallowtail Ribbon Ends (flat-coloured in faded vermilion & ultramarine)
  let leftTail = [
    [xL - 52, yT + 12],
    [xL + 12, yT + 12],
    [xL + 12, yB + 10],
    [xL - 52, yB + 10],
    [xL - 32, (yT + yB) / 2 + 5]
  ];
  let rightTail = [
    [xR + 52, yT + 12],
    [xR - 12, yT + 12],
    [xR - 12, yB + 10],
    [xR + 52, yB + 10],
    [xR + 32, (yT + yB) / 2 + 5]
  ];

  brush.noStroke();
  brush.wash(cream, 255);
  drawPolyShape(leftTail, true, 0);
  drawPolyShape(rightTail, true, 0);

  brush.wash(vermilion, 235);
  drawPolyShape(leftTail, true, 0);
  drawPolyShape(rightTail, true, 0);

  // Ribbon fold triangles in ultramarine
  let leftFold = [
    [xL, yB],
    [xL + 16, yB],
    [xL + 12, yB + 10],
    [xL, yB + 10]
  ];
  let rightFold = [
    [xR, yB],
    [xR - 16, yB],
    [xR - 12, yB + 10],
    [xR, yB + 10]
  ];
  brush.wash(ultramarine, 245);
  drawPolyShape(leftFold, true, 0);
  drawPolyShape(rightFold, true, 0);

  // 2. Main Blank Title Banner Plate in flat Parchment Cream
  let bannerOuter = [
    [xL, yT],
    [xR, yT],
    [xR, yB],
    [xL, yB]
  ];
  brush.wash(cream, 255);
  drawPolyShape(bannerOuter, true, 0);
  brush.noWash();

  // Subtle pen-hatched curl shading at the far left and right ends of the blank scroll
  brush.set("rotring", ink, 0.25);
  for (let yy = yT + 8; yy <= yB - 8; yy += 4.5) {
    brush.line(xL + 8, yy, xL + 26, yy);
    brush.line(xR - 26, yy, xR - 8, yy);
  }
  // Hatch shading on swallowtail ribbon ends
  for (let yy = yT + 16; yy <= yB + 6; yy += 5) {
    brush.line(xL - 22, yy, xL, yy);
    brush.line(xR, yy, xR + 22, yy);
  }

  // 3. Pen-drawn double-line border around the blank banner and ribbon tails
  strokePolyOutline(leftTail, "rotring", ink, 0.45, true);
  strokePolyOutline(rightTail, "rotring", ink, 0.45, true);
  strokePolyOutline(leftFold, "rotring", ink, 0.4, true);
  strokePolyOutline(rightFold, "rotring", ink, 0.4, true);

  drawDoubleLineRect(xL, yT, bw, bh, 6, ink, 0.48);

  // Small decorative corner flourishes inside the blank banner's inner corners
  let pad = 11;
  let flSize = 7;
  brush.set("rotring", ink, 0.36);
  // Top-left & bottom-left corner ticks
  brush.line(xL + pad, yT + pad + flSize, xL + pad + flSize, yT + pad);
  brush.line(xL + pad, yB - pad - flSize, xL + pad + flSize, yB - pad);
  // Top-right & bottom-right corner ticks
  brush.line(xR - pad, yT + pad + flSize, xR - pad - flSize, yT + pad);
  brush.line(xR - pad, yB - pad - flSize, xR - pad - flSize, yB - pad);
}

// ============================================================================
// 5. SHUFFLED DECK EDGE WEAR, ROUNDED CORNER SCUFFS & PATINA
// ============================================================================

function drawCardAgingAndWear() {
  let cardPts = getRoundedRectPts(240, 60, 720, 1080, 42, 12, 2.2);

  // 1. Warm thumb-wear & edge darkening from shuffling along the card perimeter
  let n = cardPts.length;
  for (let i = 0; i < n; i++) {
    let p1 = cardPts[i];
    let p2 = cardPts[(i + 1) % n];

    // Stronger wear at the 4 rounded corners and mid-side thumb zones
    let isCorner = i % 13 < 4 || i % 13 > 10;
    let isMidThumb = abs(p1[1] - 600) < 180;

    // Soft warm sepia/ochre edge patina
    brush.set("cpencil", "#b89058", isCorner ? 0.65 : 0.45);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    // Short inward scuff strokes at corners & thumb-hold zones
    if (isCorner || (isMidThumb && random() < 0.5)) {
      let toCenterX = (600 - p1[0]) * 0.035;
      let toCenterY = (600 - p1[1]) * 0.035;
      for (let k = 0; k < 4; k++) {
        let ox = random(-4, 4);
        let oy = random(-4, 4);
        brush.set("cpencil", random(["#c7a26b", "#a67e49", "#f7eed7"]), 0.35);
        brush.line(
          p1[0] + ox,
          p1[1] + oy,
          p1[0] + ox + toCenterX * random(0.4, 1.3),
          p1[1] + oy + toCenterY * random(0.4, 1.3)
        );
      }
    }
  }

  // 2. Crisp dark card-stock edge outline with natural paper irregularities
  strokePolyOutline(cardPts, "2B", "#3d2c1e", 0.42, true);

  // 3. Exposed pale paper fibers & tiny dog-eared creases on the 4 rounded corners
  let cornerArcs = [
    { cx: 240 + 42, cy: 60 + 42, a1: 185, a2: 265 },
    { cx: 960 - 42, cy: 60 + 42, a1: 275, a2: 355 },
    { cx: 960 - 42, cy: 1140 - 42, a1: 5, a2: 85 },
    { cx: 240 + 42, cy: 1140 - 42, a1: 95, a2: 175 }
  ];

  for (let c of cornerArcs) {
    // Pale frayed paper edge highlight
    brush.set("2H", "#faf2df", 0.45);
    brush.arc(c.cx, c.cy, 41.5, c.a1, c.a2);

    // Subtle diagonal corner crease lines from handling
    let midA = (c.a1 + c.a2) * 0.5;
    let px1 = c.cx + 38 * cos(midA - 18);
    let py1 = c.cy + 38 * sin(midA - 18);
    let px2 = c.cx + 38 * cos(midA + 18);
    let py2 = c.cy + 38 * sin(midA + 18);
    brush.set("2H", "#f7eed7", 0.3);
    brush.line(px1, py1, px2, py2);
    brush.set("cpencil", "#9e7948", 0.25);
    brush.line(px1 + 1.5, py1 + 1.5, px2 + 1.5, py2 + 1.5);
  }
}

