function drawWetSpecularRibbon(p1, p2, p3, scaleW = 1.0) {
  // Optical dark-amber & fiery-orange rim surrounding the blinding specular reflection
  brush.set("marker", PAL.cavityDark2, 1.15 * scaleW);
  brush.spline([
    [p1[0] + 1.8, p1[1] + 1.8],
    [p2[0] + 1.8, p2[1] + 1.8],
    [p3[0] + 1.8, p3[1] + 1.8]
  ], 0.5);

  brush.set("cpencil", PAL.causticGold, 1.1 * scaleW);
  brush.spline([
    [p1[0] - 1.2, p1[1] - 1.2],
    [p2[0] - 1.2, p2[1] - 1.2],
    [p3[0] - 1.2, p3[1] - 1.2]
  ], 0.5);

  // Cool sky-tinted reflection halo
  brush.set("rotring", PAL.specSky, 1.55 * scaleW);
  brush.spline([p1, p2, p3], 0.5);

  // Blinding pure white liquid meniscus core
  brush.set("rotring", PAL.specPure, 1.15 * scaleW);
  brush.spline([p1, p2, p3], 0.5);

  // Satellite micro-bead of light at one end of the meniscus
  let bx = p3[0] + (p3[0] - p2[0]) * 0.38;
  let by = p3[1] + (p3[1] - p2[1]) * 0.38;
  brush.set("rotring", PAL.specPure, 1.25 * scaleW);
  brush.line(bx, by, bx + 1.8, by + 1.2);
}

