function getOvalPoly(cx, cy, rx, ry, rot, steps = 12) {
  let pts = [];
  let c = Math.cos(rot), s = Math.sin(rot);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * TWO_PI;
    let lx = rx * Math.cos(a);
    let ly = ry * Math.sin(a);
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

function drawHyperrealDroplet(d) {
  let { x, y, rx, ry, rot, surface } = d;

  let shadCol = surface === "flesh" ? "#4f1203" : (surface === "rind" ? "#1e2918" : "#2b1612");
  let darkLensCol = surface === "flesh" ? "#7a2007" : (surface === "rind" ? "#334529" : "#702410");
  let causticCol = surface === "rind" ? "#dce388" : PAL.causticGold;
  let causticHot = surface === "rind" ? "#f5f2b8" : PAL.causticBright;

  // 1. Cast shadow thrown toward bottom-right (+0.74, +0.67)
  let sx = x + rx * 0.45;
  let sy = y + ry * 0.42;
  let shadPoly = getOvalPoly(sx, sy, rx * 0.95, ry * 0.88, rot, 10);
  brush.noStroke();
  brush.wash(shadCol, 175);
  drawPolyPrimitive(shadPoly, 0.15);

  // 2. Internal refracted caustic glow focusing into the lower-right of the droplet & shadow
  let cxGlow = x + rx * 0.24;
  let cyGlow = y + ry * 0.22;
  let glowPoly = getOvalPoly(cxGlow, cyGlow, rx * 0.78, ry * 0.72, rot, 10);
  brush.wash(causticCol, 210);
  drawPolyPrimitive(glowPoly, 0.15);

  let hotPoly = getOvalPoly(x + rx * 0.30, y + ry * 0.28, rx * 0.48, ry * 0.42, rot, 8);
  brush.wash(causticHot, 225);
  drawPolyPrimitive(hotPoly, 0.15);

  // 3. Upper-left internal lens shadow (gives intense contrast to the white specular highlight)
  let darkPoly = getOvalPoly(x - rx * 0.18, y - ry * 0.18, rx * 0.68, ry * 0.64, rot, 10);
  brush.wash(darkLensCol, 195);
  drawPolyPrimitive(darkPoly, 0.15);
  brush.noWash();

  // 4. Secondary bounce light arc along the bottom-right inner rim
  let b1 = [x + rx * 0.15, y + ry * 0.72];
  let b2 = [x + rx * 0.56, y + ry * 0.52];
  let b3 = [x + rx * 0.72, y + ry * 0.12];
  brush.set("rotring", PAL.specWarm, 0.75);
  brush.spline([b1, b2, b3], 0.45);

  // 5. Delicate Prussian indigo cloisonne rim around the droplet
  let dropPoly = getOvalPoly(x, y, rx, ry, rot, 12);
  brush.set("pen", PAL.indigoCore, rx > 8 ? 0.72 : 0.55);
  drawPolyPrimitive(dropPoly, 0.12);

  // 6. Primary blinding white specular reflection on the upper-left dome
  let hx = x - rx * 0.34;
  let hy = y - ry * 0.34;
  if (rx >= 7.5) {
    // Curved window/sky crescent reflection + pinpoint satellite dot
    let hA = [hx - rx * 0.22, hy + ry * 0.16];
    let hB = [hx - rx * 0.05, hy - ry * 0.15];
    let hC = [hx + rx * 0.24, hy - ry * 0.18];

    brush.set("rotring", PAL.specSky, 1.55);
    brush.spline([hA, hB, hC], 0.45);

    brush.set("rotring", PAL.specPure, 1.25);
    brush.spline([hA, hB, hC], 0.45);

    // Pinpoint secondary highlight dot
    brush.set("rotring", PAL.specPure, 1.1);
    brush.line(hx + rx * 0.38, hy + ry * 0.02, hx + rx * 0.42, hy + ry * 0.06);
  } else {
    // Crisp specular bead for smaller dewdrops
    brush.set("rotring", PAL.specSky, 1.25);
    brush.line(hx - 1.2, hy + 0.8, hx + 1.5, hy - 1.0);
    brush.set("rotring", PAL.specPure, 1.05);
    brush.line(hx - 0.8, hy + 0.5, hx + 1.2, hy - 0.8);
  }
}

