// =============================================================================
// GEOMETRY & DRAWING HELPERS
// =============================================================================

function ellipsePt(c, deg, radialOffset = 0) {
  let rx = c.rx + radialOffset;
  let ry = c.ry + radialOffset;
  // Slight off-axis perspective tilt (-2.5 degrees)
  let rot = -2.5;
  let px = rx * cos(deg);
  let py = ry * sin(deg);
  let x = c.x + px * cos(rot) - py * sin(rot);
  let y = c.y + px * sin(rot) + py * cos(rot);
  return [x, y];
}

function getEllipseArc(c, startDeg, endDeg, stepDeg = 3, radialOffset = 0) {
  let pts = [];
  if (startDeg <= endDeg) {
    for (let a = startDeg; a <= endDeg - 0.01; a += stepDeg) {
      pts.push(ellipsePt(c, a, radialOffset));
    }
    pts.push(ellipsePt(c, endDeg, radialOffset));
  } else {
    for (let a = startDeg; a >= endDeg + 0.01; a -= stepDeg) {
      pts.push(ellipsePt(c, a, radialOffset));
    }
    pts.push(ellipsePt(c, endDeg, radialOffset));
  }
  return pts;
}

function getRingSectorPts(cOuter, cInner, startDeg, endDeg, stepDeg = 2.5) {
  let outerArc = getEllipseArc(cOuter, startDeg, endDeg, stepDeg);
  let innerArc = getEllipseArc(cInner, endDeg, startDeg, stepDeg);
  return outerArc.concat(innerArc);
}

function wcPoly(pts, col, alpha, bleed = 0.35, tex = 0.68, border = 0.42, curv = 0.25, dir = "out") {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, dir);
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function wcOrganicBlob(cx, cy, rx, ry, rotDeg, numPts, jitter, col, alpha, bleed = 0.4, tex = 0.7, border = 0.45, dir = "out") {
  let pts = [];
  let seedOff = random(1000);
  for (let i = 0; i < numPts; i++) {
    let a = (i / numPts) * 360;
    let n = noise(seedOff + cos(a) * 1.3, seedOff + sin(a) * 1.3);
    let rMult = 1 + map(n, 0, 1, -jitter, jitter);
    let px = rx * rMult * cos(a);
    let py = ry * rMult * sin(a);
    let x = cx + px * cos(rotDeg) - py * sin(rotDeg);
    let y = cy + px * sin(rotDeg) + py * cos(rotDeg);
    pts.push([x, y]);
  }
  wcPoly(pts, col, alpha, bleed, tex, border, 0.35, dir);
}

function celFlatPoly(pts, col, alpha = 255, solidOpaque = true, hatchAngle = 35) {
  if (!pts || pts.length < 3) return;
  brush.noField();
  brush.noStroke();
  brush.noFill();
  if (solidOpaque) {
    brush.hatchStyle("cel_flat", col, 1.4);
    brush.hatch(5.5, hatchAngle, { rand: 0 });
  } else {
    brush.noHatch();
  }
  brush.wash(col, alpha);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
  brush.noHatch();

  // Second crisp wash pass for dead-flat cel opacity
  if (solidOpaque) {
    brush.wash(col, alpha);
    brush.beginShape(0);
    for (let i = 0; i < pts.length; i++) {
      brush.vertex(pts[i][0], pts[i][1]);
    }
    brush.endShape(true);
    brush.noWash();
  }
}

function celRingSector(cOuter, cInner, startDeg, endDeg, col, alpha = 255, solidOpaque = true) {
  // Split sectors wider than 55 degrees into sub-sectors so polygon stays strictly convex/simple
  let span = endDeg - startDeg;
  let numSlices = max(1, ceil(abs(span) / 50));
  let dSpan = span / numSlices;
  for (let i = 0; i < numSlices; i++) {
    let a1 = startDeg + i * dSpan;
    let a2 = startDeg + (i + 1) * dSpan + (i < numSlices - 1 ? 0.35 : 0);
    let pts = getRingSectorPts(cOuter, cInner, a1, a2, 2.5);
    celFlatPoly(pts, col, alpha, solidOpaque, (a1 + a2) * 0.5);
  }
}

function inkContourPts(pts, closed = false, weight = 1.35, col = CEL_INK, curv = 0.08) {
  if (!pts || pts.length < 2) return;
  brush.noField();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("ink_pen", col, weight);
  if (closed) {
    brush.beginShape(curv);
    for (let i = 0; i < pts.length; i++) {
      brush.vertex(pts[i][0], pts[i][1]);
    }
    brush.endShape(true);
  } else {
    brush.spline(pts, curv);
  }
}

function inkArc(c, startDeg, endDeg, weight = 1.4, col = CEL_INK, radialOffset = 0) {
  let pts = getEllipseArc(c, startDeg, endDeg, 2.5, radialOffset);
  inkContourPts(pts, false, weight, col, 0.12);
}

function inkLineSeg(x1, y1, x2, y2, weight = 1.3, col = CEL_INK) {
  brush.noField();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("ink_pen", col, weight);
  brush.line(x1, y1, x2, y2);
}

