function drawWovenDobbyBand(curve1, curve2, darkCol, lightCol) {
  brush.noField();
  // Highlight woven ridge
  brush.set("cpencil", lightCol, 1.8);
  brush.spline(curve1, 0.35);
  // Twin dark woven dobby grooves
  brush.set("2B", darkCol, 1.25);
  brush.spline(curve1.map(p => [p[0], p[1] + 3]), 0.35);
  brush.spline(curve2, 0.35);
  brush.set("cpencil", lightCol, 1.5);
  brush.spline(curve2.map(p => [p[0], p[1] + 3]), 0.35);
}

