function drawInteriorSteamAndCondensation() {
  // 1. Soft misty steam blooms clinging to the lower-left and upper-left inner glass bowl
  wcOrganicBlob(545, 650, 125, 165, 12, 16, 0.25, "#edf7fa", 38, 0.45, 0.5, 0.25);
  wcOrganicBlob(615, 385, 115, 85, -20, 16, 0.25, "#fff7f2", 34, 0.45, 0.5, 0.25);
  wcOrganicBlob(885, 795, 130, 95, -15, 16, 0.25, "#edf7fa", 32, 0.45, 0.5, 0.25);

  // 2. Curved condensation trickle tracks (where heavy drops rolled down the glass dome)
  let tricklePaths = [
    [[478, 495], [472, 555], [476, 615], [485, 672]],
    [[528, 540], [522, 605], [528, 668], [536, 722]],
    [[585, 420], [578, 475], [582, 532]],
    [[648, 695], [644, 755], [652, 812]],
    [[895, 645], [892, 705], [898, 762]],
    [[982, 560], [978, 622], [984, 678]],
    [[742, 745], [738, 805], [744, 858]]
  ];

  for (let path of tricklePaths) {
    // Faint dark shadow edge of rivulet
    brush.set("2H", "#1d2e3a", 0.7);
    brush.spline(path.map(p => [p[0] - 1.8, p[1]]), 0.3);
    // Lifted bright highlight track of rivulet
    brush.set("cpencil", "#ffffff", 1.15);
    brush.spline(path, 0.3);
    // Plump droplet at the bottom of the trickle track
    let endPt = path[path.length - 1];
    drawCondensationBead(endPt[0], endPt[1] + 5, random(6.5, 9.5));
  }

  // 3. Field of hyperreal condensation beads with tiny lifted highlights
  // Clustered naturally along the inner glass dome perimeter & scattered across the mid-field
  let beads = [];

  // Dense perimeter condensation zone (especially left, lower-left, upper-left, lower-right)
  for (let i = 0; i < 85; i++) {
    let a = random(35, 315);
    let rFrac = random(0.62, 0.94);
    let bx = C_GLASS_RIM.x + C_GLASS_RIM.rx * rFrac * cos(a);
    let by = C_GLASS_RIM.y + C_GLASS_RIM.ry * rFrac * sin(a);
    if (bx < 1140) {
      let rad = random(1) < 0.28 ? random(5.5, 9.2) : random(2.4, 5.2);
      beads.push({ x: bx, y: by, r: rad });
    }
  }

  // Interior dome scattered condensation beads over the blurred coral & mint towels
  for (let i = 0; i < 55; i++) {
    let a = random(360);
    let rFrac = random(0.12, 0.65);
    let bx = C_DOME_IN.x + C_DOME_IN.rx * rFrac * cos(a);
    let by = C_DOME_IN.y + C_DOME_IN.ry * rFrac * sin(a);
    if (bx < 1120) {
      let rad = random(1) < 0.22 ? random(5.0, 8.0) : random(2.2, 4.6);
      beads.push({ x: bx, y: by, r: rad });
    }
  }

  for (let b of beads) {
    drawCondensationBead(b.x, b.y, b.r);
  }
}

function drawCondensationBead(x, y, r) {
  let isOverCoral = (y > 560 && x > 580) || (y < 340 && x < 740);
  let shadowCol = isOverCoral ? "#361216" : "#0e2429";
  let refractCol = isOverCoral ? "#ffd8cc" : "#d4faee";

  // 1. Cast shadow crescent on lower-left / upper-left of bead
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(shadowCol, 155);
  brush.fillBleed(0.08, "out");
  brush.fillTexture(0.35, 0.3);
  brush.circle(x - r * 0.25, y + r * 0.25, r * 0.95, 0.15);
  brush.noFill();

  // 2. Refracted interior glow on lower-left interior of bead
  brush.noStroke();
  brush.wash(refractCol, 145);
  brush.circle(x - r * 0.12, y + r * 0.12, r * 0.78, 0.1);
  brush.noWash();

  // 3. Crisp tiny lifted white highlight on upper-right light-facing side
  let hx = x + r * 0.26;
  let hy = y - r * 0.26;
  let hr = max(1.6, r * 0.38);
  brush.noStroke();
  brush.wash("#ffffff", 250);
  brush.circle(hx, hy, hr, 0.05);
  brush.noWash();

  // Pinpoint specular spark
  brush.set("ink_pen", "#ffffff", max(0.8, r * 0.18));
  brush.line(hx - hr * 0.3, hy - hr * 0.2, hx + hr * 0.3, hy + hr * 0.2);

  // Delicate dark rim contour on shadow side of larger beads
  if (r > 4.5) {
    brush.set("2B", shadowCol, 0.65);
    brush.arc(x, y, r, 115, 245);
  }
}

// =============================================================================
// LAYER 4: CEL-ANIMATION ACETATE OVERLAY (CHROME PORTHOLE, HINGE & GLASS)
// =============================================================================

function drawCelChromePortholeRim() {
  // ---------------------------------------------------------------------------
  // 1. RING A: OUTER MOUNTING FLANGE (C_OUTER to C_FLANGE)
  // Shaded strictly in hard-edged angular bands of CEL_GREY_LIGHT, CEL_GREY_DARK, CEL_WHITE
  // ---------------------------------------------------------------------------
  const ringASectors = [
    { a1: 0,   a2: 65,  col: CEL_GREY_DARK },
    { a1: 65,  a2: 132, col: CEL_GREY_LIGHT },
    { a1: 132, a2: 156, col: CEL_WHITE },      // Aligned with specular slash axis
    { a1: 156, a2: 218, col: CEL_GREY_LIGHT },
    { a1: 218, a2: 268, col: CEL_GREY_DARK },
    { a1: 268, a2: 316, col: CEL_GREY_LIGHT },
    { a1: 316, a2: 334, col: CEL_WHITE },      // Aligned with lower-right specular axis
    { a1: 334, a2: 360, col: CEL_GREY_DARK }
  ];
  for (let s of ringASectors) {
    celRingSector(C_OUTER, C_FLANGE, s.a1, s.a2, s.col, 255, true);
  }

  // ---------------------------------------------------------------------------
  // 2. RING B1: MAIN CONVEX CHROME TORUS - OUTER SLOPE (C_FLANGE to C_TORUS_MID)
  // ---------------------------------------------------------------------------
  const ringB1Sectors = [
    { a1: 0,   a2: 48,  col: CEL_GREY_LIGHT },
    { a1: 48,  a2: 108, col: CEL_GREY_DARK },
    { a1: 108, a2: 136, col: CEL_GREY_LIGHT },
    { a1: 136, a2: 162, col: CEL_WHITE },      // Primary upper-left chrome specular glint
    { a1: 162, a2: 205, col: CEL_GREY_LIGHT },
    { a1: 205, a2: 252, col: CEL_GREY_DARK },
    { a1: 252, a2: 312, col: CEL_GREY_LIGHT },
    { a1: 312, a2: 332, col: CEL_WHITE },      // Lower-right chrome specular glint
    { a1: 332, a2: 360, col: CEL_GREY_LIGHT }
  ];
  for (let s of ringB1Sectors) {
    celRingSector(C_FLANGE, C_TORUS_MID, s.a1, s.a2, s.col, 255, true);
  }

  // ---------------------------------------------------------------------------
  // 3. RING B2: MAIN CONVEX CHROME TORUS - INNER SLOPE (C_TORUS_MID to C_RIDGE)
  // Offset angular cel planes create the unmistakable anime cylindrical chrome look
  // ---------------------------------------------------------------------------
  const ringB2Sectors = [
    { a1: 0,   a2: 58,  col: CEL_GREY_DARK },
    { a1: 58,  a2: 128, col: CEL_GREY_LIGHT },
    { a1: 128, a2: 142, col: CEL_GREY_DARK },
    { a1: 142, a2: 166, col: CEL_WHITE },
    { a1: 166, a2: 222, col: CEL_GREY_DARK },
    { a1: 222, a2: 278, col: CEL_GREY_LIGHT },
    { a1: 278, a2: 315, col: CEL_GREY_DARK },
    { a1: 315, a2: 336, col: CEL_WHITE },
    { a1: 336, a2: 360, col: CEL_GREY_DARK }
  ];
  for (let s of ringB2Sectors) {
    celRingSector(C_TORUS_MID, C_RIDGE, s.a1, s.a2, s.col, 255, true);
  }

  // ---------------------------------------------------------------------------
  // 4. RING C: STEPPED INNER CHROME BEVEL (C_RIDGE to C_BEVEL)
  // ---------------------------------------------------------------------------
  const ringCSectors = [
    { a1: 0,   a2: 75,  col: CEL_GREY_LIGHT },
    { a1: 75,  a2: 144, col: CEL_GREY_DARK },
    { a1: 144, a2: 164, col: CEL_WHITE },
    { a1: 164, a2: 245, col: CEL_GREY_DARK },
    { a1: 245, a2: 318, col: CEL_GREY_LIGHT },
    { a1: 318, a2: 335, col: CEL_WHITE },
    { a1: 335, a2: 360, col: CEL_GREY_LIGHT }
  ];
  for (let s of ringCSectors) {
    celRingSector(C_RIDGE, C_BEVEL, s.a1, s.a2, s.col, 255, true);
  }

  // ---------------------------------------------------------------------------
  // 5. RING D: INNER CLAMPING LIP / GASKET SEAT (C_BEVEL to C_GLASS_RIM)
  // ---------------------------------------------------------------------------
  const ringDSectors = [
    { a1: 0,   a2: 95,  col: CEL_GREY_DARK },
    { a1: 95,  a2: 146, col: CEL_GREY_LIGHT },
    { a1: 146, a2: 162, col: CEL_WHITE },
    { a1: 162, a2: 215, col: CEL_GREY_LIGHT },
    { a1: 215, a2: 295, col: CEL_GREY_DARK },
    { a1: 295, a2: 320, col: CEL_GREY_LIGHT },
    { a1: 320, a2: 336, col: CEL_WHITE },
    { a1: 336, a2: 360, col: CEL_GREY_DARK }
  ];
  for (let s of ringDSectors) {
    celRingSector(C_BEVEL, C_GLASS_RIM, s.a1, s.a2, s.col, 255, true);
  }

  // Thin dark cel shadow accent in the deepest mechanical groove (C_RIDGE & C_GLASS_RIM)
  celRingSector(
    { x: C_RIDGE.x, y: C_RIDGE.y, rx: C_RIDGE.rx + 4, ry: C_RIDGE.ry + 4 },
    { x: C_RIDGE.x, y: C_RIDGE.y, rx: C_RIDGE.rx - 4, ry: C_RIDGE.ry - 4 },
    168, 255, CEL_SHADOW_INK, 255, true
  );

  // ---------------------------------------------------------------------------
  // 6. CRISP UNIFORM TECHNICAL PEN CONTOURS ENCLOSING THE CHROME RIM
  // ---------------------------------------------------------------------------
  // Major concentric rim contours
  inkArc(C_OUTER,     0, 360, 2.2, CEL_INK);
  inkArc(C_FLANGE,    0, 360, 1.5, CEL_INK);
  inkArc(C_TORUS_MID, 0, 360, 1.15, CEL_INK);
  inkArc(C_RIDGE,     0, 360, 1.7, CEL_INK);
  inkArc(C_BEVEL,     0, 360, 1.4, CEL_INK);
  inkArc(C_GLASS_RIM, 0, 360, 2.2, CEL_INK);

  // Hard-edged radial cel-shading contour lines stepping across each ring
  for (let s of ringASectors) {
    let p1 = ellipsePt(C_OUTER, s.a1);
    let p2 = ellipsePt(C_FLANGE, s.a1);
    inkLineSeg(p1[0], p1[1], p2[0], p2[1], 1.15, CEL_INK);
  }
  for (let s of ringB1Sectors) {
    let p1 = ellipsePt(C_FLANGE, s.a1);
    let p2 = ellipsePt(C_TORUS_MID, s.a1);
    inkLineSeg(p1[0], p1[1], p2[0], p2[1], 1.1, CEL_INK);
  }
  for (let s of ringB2Sectors) {
    let p1 = ellipsePt(C_TORUS_MID, s.a1);
    let p2 = ellipsePt(C_RIDGE, s.a1);
    inkLineSeg(p1[0], p1[1], p2[0], p2[1], 1.1, CEL_INK);
  }
  for (let s of ringCSectors) {
    let p1 = ellipsePt(C_RIDGE, s.a1);
    let p2 = ellipsePt(C_BEVEL, s.a1);
    inkLineSeg(p1[0], p1[1], p2[0], p2[1], 1.1, CEL_INK);
  }
  for (let s of ringDSectors) {
    let p1 = ellipsePt(C_BEVEL, s.a1);
    let p2 = ellipsePt(C_GLASS_RIM, s.a1);
    inkLineSeg(p1[0], p1[1], p2[0], p2[1], 1.1, CEL_INK);
  }

  // ---------------------------------------------------------------------------
  // 7. COUNTERSUNK FLANGE RIVETS / SCREWS AROUND RING A
  // ---------------------------------------------------------------------------
  const boltAngles = [75, 118, 152, 208, 245, 290];
  let cBoltRing = {
    x: (C_OUTER.x + C_FLANGE.x) * 0.5,
    y: (C_OUTER.y + C_FLANGE.y) * 0.5,
    rx: (C_OUTER.rx + C_FLANGE.rx) * 0.5,
    ry: (C_OUTER.ry + C_FLANGE.ry) * 0.5
  };
  for (let ba of boltAngles) {
    let [bx, by] = ellipsePt(cBoltRing, ba);
    if (bx < 1185) {
      drawCelScrew(bx, by, 9, 10.5);
    }
  }
}

function drawCelScrew(cx, cy, rx, ry) {
  let cS = { x: cx, y: cy, rx: rx, ry: ry };
  let ptsTop = getEllipseArc(cS, 160, 340, 15);
  let ptsBot = getEllipseArc(cS, 340, 520, 15);
  celFlatPoly(ptsTop, CEL_GREY_DARK, 255, true);
  celFlatPoly(ptsBot, CEL_GREY_LIGHT, 255, true);
  inkArc(cS, 0, 360, 1.2, CEL_INK);
  inkLineSeg(cx - rx * 0.65, cy - ry * 0.25, cx + rx * 0.65, cy + ry * 0.25, 1.2, CEL_INK);
}

