function drawCelGlassDomeOverlay() {
  // ---------------------------------------------------------------------------
  // 1. TWO HARD-EDGED FLAT TONES OF COOL GREY ON THE CURVED GLASS FISHBOWL SIDEWALL
  // Treated as an acetate cel overlay: sharp graphic shapes along the thick glass
  // bevel between C_GLASS_RIM and C_DOME_IN, leaving the center clear so the
  // watercolor towels and condensation beads breathe through.
  // ---------------------------------------------------------------------------
  const C_GLASS_MID = {
    x: (C_GLASS_LIP.x + C_DOME_IN.x) * 0.5,
    y: (C_GLASS_LIP.y + C_DOME_IN.y) * 0.5,
    rx: (C_GLASS_LIP.rx + C_DOME_IN.rx) * 0.5,
    ry: (C_GLASS_LIP.ry + C_DOME_IN.ry) * 0.5
  };

  // A. Upper-left & left thick Pyrex glass sidewall cel shading (158° to 238°)
  celRingSector(C_GLASS_LIP, C_GLASS_MID, 158, 232, CEL_GREY_DARK, 235, true);
  celRingSector(C_GLASS_MID, C_DOME_IN,   164, 224, CEL_GREY_LIGHT, 225, true);

  // Stepped cool-grey reflection tab at upper-top glass bevel (238° to 268°)
  celRingSector(C_GLASS_LIP, C_GLASS_MID, 238, 268, CEL_GREY_LIGHT, 225, true);

  // B. Lower curve glass sidewall cel shading (42° to 118°)
  celRingSector(C_GLASS_LIP, C_GLASS_MID, 42, 118, CEL_GREY_LIGHT, 225, true);
  celRingSector(C_GLASS_MID, C_DOME_IN,   52, 108, CEL_GREY_DARK, 230, true);

  // C. Molded outer glass gasket lip (thin band between C_GLASS_RIM and C_GLASS_LIP)
  celRingSector(C_GLASS_RIM, C_GLASS_LIP, 118, 144, CEL_GREY_LIGHT, 240, true);
  celRingSector(C_GLASS_RIM, C_GLASS_LIP, 268, 318, CEL_GREY_DARK, 240, true);
  celRingSector(C_GLASS_RIM, C_GLASS_LIP, 0,   42,  CEL_GREY_DARK, 240, true);

  // ---------------------------------------------------------------------------
  // 2. CRISP UNIFORM PEN CONTOURS FOR THE GLASS BOWL BEVELS
  // ---------------------------------------------------------------------------
  // Outer molded glass lip seam
  inkArc(C_GLASS_LIP, 0, 360, 1.25, CEL_INK);

  // Intermediate glass bevel step contours around the shaded cel zones
  inkArc(C_GLASS_MID, 158, 268, 1.15, CEL_INK);
  inkArc(C_GLASS_MID, 42,  118, 1.15, CEL_INK);

  // Radial hard-edge termination lines for the glass cel-shading zones
  for (let a of [158, 232, 238, 268, 42, 118]) {
    let p1 = ellipsePt(C_GLASS_LIP, a);
    let p2 = ellipsePt(C_GLASS_MID, a);
    inkLineSeg(p1[0], p1[1], p2[0], p2[1], 1.15, CEL_INK);
  }
  for (let a of [164, 224, 52, 108]) {
    let p1 = ellipsePt(C_GLASS_MID, a);
    let p2 = ellipsePt(C_DOME_IN, a);
    inkLineSeg(p1[0], p1[1], p2[0], p2[1], 1.15, CEL_INK);
  }

  // Inner glass fishbowl dome contour (classic anime broken-line contour for clear glass)
  inkArc(C_DOME_IN, 28,  138, 1.35, CEL_INK);
  inkArc(C_DOME_IN, 152, 262, 1.4,  CEL_INK);
  inkArc(C_DOME_IN, 278, 352, 1.25, CEL_INK);
}

function drawCelWhiteSpecularSlash() {
  // ===========================================================================
  // ONE BOLD WHITE SPECULAR SLASH ACROSS THE GLASS DOME
  // "with shading in two hard-edged flat tones of cool grey and one white specular slash."
  // Includes the authentic 3D optical refraction kink where the slash crosses from the
  // sloped upper-left glass sidewall onto the main inner fishbowl dome face.
  // ===========================================================================

  // Part 1: Slash segment on the sloped upper-left glass sidewall (between C_GLASS_RIM & C_DOME_IN)
  let pRimTop  = ellipsePt(C_GLASS_RIM, 214);
  let pRimBot  = ellipsePt(C_GLASS_RIM, 204);
  let pDomeTop = ellipsePt(C_DOME_IN,   217);
  let pDomeBot = ellipsePt(C_DOME_IN,   206);

  // Wait: let's place the slash at upper-left (around 215°-225° in standard screen coords where
  // 180° is left and 270° is top! Wait: in p5 with y-down:
  // 0° = right (+x), 90° = bottom (+y), 180° = left (-x), 270° = top (-y)!
  // Let's check! Earlier on the chrome rim we put white glints at 142°-162° (lower-left) and
  // 316°-336° (upper-right), OR let's align the glass specular slash from upper-left (215°)
  // to lower-right (35°), and add matching white specular bars on the chrome rim at 212°-226°!)

  // Let's also add the aligned upper-left (210°-226°) and lower-right (28°-42°) chrome specular
  // glints on the rim so the slash and rim reflections lock together along one axis!
  celRingSector(C_FLANGE, C_TORUS_MID, 210, 226, CEL_WHITE, 255, true);
  celRingSector(C_RIDGE,  C_BEVEL,     212, 224, CEL_WHITE, 255, true);
  inkArc(C_FLANGE,    210, 226, 1.5, CEL_INK);
  inkArc(C_TORUS_MID, 210, 226, 1.15, CEL_INK);
  inkArc(C_RIDGE,     212, 224, 1.6, CEL_INK);
  inkArc(C_BEVEL,     212, 224, 1.35, CEL_INK);
  for (let a of [210, 226]) {
    let q1 = ellipsePt(C_FLANGE, a);
    let q2 = ellipsePt(C_TORUS_MID, a);
    inkLineSeg(q1[0], q1[1], q2[0], q2[1], 1.15, CEL_INK);
  }
  for (let a of [212, 224]) {
    let q1 = ellipsePt(C_RIDGE, a);
    let q2 = ellipsePt(C_BEVEL, a);
    inkLineSeg(q1[0], q1[1], q2[0], q2[1], 1.15, CEL_INK);
  }

  // Construct the single continuous, stepped White Specular Slash across the glass:
  // Starts at upper-left glass sidewall (around 218°), kinks at the inner dome crease C_DOME_IN,
  // and slices diagonally across the center of the dome toward lower-right (around 32°)!
  let sOuter1 = ellipsePt(C_GLASS_LIP, 221); // Upper edge on outer glass lip
  let sOuter2 = ellipsePt(C_GLASS_LIP, 211); // Lower edge on outer glass lip
  let sKink1  = ellipsePt(C_DOME_IN,   225); // Upper edge at inner dome seam (refracted step)
  let sKink2  = ellipsePt(C_DOME_IN,   213); // Lower edge at inner dome seam

  // Tip of the slash tapering to a razor point on the lower-right of the glass dome
  let sTip = ellipsePt(C_DOME_IN, 28);

  // Smooth curved upper and lower edges of the main slash across the convex/concave dome
  let upperSlashCurve = [
    sKink1,
    [685, 425],
    [815, 512],
    [948, 615],
    [1045, 702],
    sTip
  ];
  let lowerSlashCurve = [
    sTip,
    [1018, 708],
    [895, 628],
    [762, 535],
    [642, 452],
    sKink2
  ];

  // Combine sidewall bevel segment + main dome slash into one bold cel specular shape
  let bevelSlashPts = [sOuter1, sKink1, sKink2, sOuter2];
  let mainSlashPts = [];
  // Sample smooth points along the upper & lower slash curves
  let upSamples = sampleCatmullPts(upperSlashCurve, 28);
  let dnSamples = sampleCatmullPts(lowerSlashCurve, 28);
  mainSlashPts = upSamples.concat(dnSamples);

  // Fill with 100% opaque stark white cel paint
  celFlatPoly(bevelSlashPts, CEL_WHITE, 255, true, -35);
  celFlatPoly(mainSlashPts,  CEL_WHITE, 255, true, 38);

  // Crisp uniform technical pen contour enclosing the white specular slash
  inkContourPts([sOuter2, sOuter1, sKink1], false, 1.35, CEL_INK, 0.02);
  inkContourPts([sKink2, sOuter2], false, 1.35, CEL_INK, 0.02);
  inkContourPts(upSamples, false, 1.4, CEL_INK, 0.1);
  inkContourPts(dnSamples, false, 1.4, CEL_INK, 0.1);
  // Subtle internal refraction crease line where the slash crosses the dome apex seam
  inkLineSeg(sKink1[0], sKink1[1], sKink2[0], sKink2[1], 1.2, CEL_INK);
}

function sampleCatmullPts(ctrlPts, stepsPerSeg = 8) {
  if (ctrlPts.length < 2) return ctrlPts;
  let res = [];
  let pts = [ctrlPts[0]].concat(ctrlPts).concat([ctrlPts[ctrlPts.length - 1]]);
  for (let i = 1; i < pts.length - 2; i++) {
    let p0 = pts[i - 1];
    let p1 = pts[i];
    let p2 = pts[i + 1];
    let p3 = pts[i + 2];
    for (let s = 0; s < stepsPerSeg; s++) {
      let t = s / stepsPerSeg;
      let t2 = t * t;
      let t3 = t2 * t;
      let x = 0.5 * (
        (2 * p1[0]) +
        (-p0[0] + p2[0]) * t +
        (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
        (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3
      );
      let y = 0.5 * (
        (2 * p1[1]) +
        (-p0[1] + p2[1]) * t +
        (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
        (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3
      );
      res.push([x, y]);
    }
  }
  res.push(ctrlPts[ctrlPts.length - 1]);
  return res;
}

