// Helper to draw closed organic shapes safely with beginShape/vertex
function drawShapePoly(pts, curv = 0.35) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

//Shortest angular difference in degrees (-180 to 180)
function angDiff(a, b) {
  let d = (a - b) % 360;
  if (d < -180) d += 360;
  if (d > 180) d -= 360;
  return d;
}

// Skillet radial profile with classic opposite pour spouts
function skilletRadius(ang, baseR, spoutScale = 1.0) {
  let d1 = angDiff(ang, -48);
  let d2 = angDiff(ang, 132);
  let spout1 = exp(-pow(d1 / 11.5, 2)) * 34 * spoutScale;
  let spout2 = exp(-pow(d2 / 11.5, 2)) * 34 * spoutScale;
  let micro = (noise(cos(ang) * 1.5 + 10, sin(ang) * 1.5 + 10) - 0.5) * 3.5;
  return baseR + spout1 + spout2 + micro;
}

// Generate skillet body polygon
function makeSkilletPoly(cx, cy, baseR, spoutScale = 1.0, steps = 72) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let ang = (i / steps) * 360;
    let r = skilletRadius(ang, baseR, spoutScale);
    pts.push([cx + cos(ang) * r, cy + sin(ang) * r]);
  }
  return pts;
}

// Generate handle polygon pushing diagonally out of the frame
function makeHandlePoly(cx, cy, hAng, offsetX = 0, offsetY = 0, widthScale = 1.0) {
  let ux = cos(hAng), uy = sin(hAng);
  let vx = -sin(hAng), vy = cos(hAng);
  // Distances from skillet center along handle axis
  let dists = [382, 415, 445, 480, 530, 600, 680, 770, 860, 960, 1050];
  let halfWidths = [92, 66, 44, 34, 34, 38, 43, 48, 52, 55, 57];

  let leftSide = [];
  let rightSide = [];
  for (let i = 0; i < dists.length; i++) {
    let d = dists[i];
    let w = halfWidths[i] * widthScale;
    let bx = cx + offsetX + ux * d;
    let by = cy + offsetY + uy * d;
    leftSide.push([bx + vx * w, by + vy * w]);
    rightSide.unshift([bx - vx * w, by - vy * w]);
  }
  return leftSide.concat(rightSide);
}

// Generate an organic cauliflower/rust blob polygon
function makeRustBlob(cx, cy, rx, ry, rotDeg, irregularity = 0.35, steps = 32, seedOff = 0) {
  let pts = [];
  let c = cos(rotDeg), s = sin(rotDeg);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let nx = cos(a) * 1.3 + seedOff;
    let ny = sin(a) * 1.3 + seedOff * 1.7;
    let n1 = noise(nx, ny);
    let n2 = noise(nx * 2.8 + 30, ny * 2.8 + 30);
    // Cauliflower scalloped modulation
    let scallop = abs(sin(a * 5 + seedOff * 40)) * 0.14;
    let radMod = 0.72 + n1 * irregularity + n2 * (irregularity * 0.55) + scallop;
    let lx = cos(a) * rx * radMod;
    let ly = sin(a) * ry * radMod;
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

// Egg white radius function
function eggWhiteRadius(ang, scaleMul = 1.0, extraRough = 0) {
  let n1 = noise(cos(ang) * 1.2 + 5, sin(ang) * 1.2 + 5);
  let n2 = noise(cos(ang) * 3.0 + 25, sin(ang) * 3.0 + 25);
  let n3 = noise(cos(ang) * 7.5 + 80, sin(ang) * 7.5 + 80);
  // Natural asymmetric spread of albumen in a skillet
  let lobe1 = exp(-pow(angDiff(ang, 25) / 55, 2)) * 38;
  let lobe2 = exp(-pow(angDiff(ang, 155) / 65, 2)) * 26;
  let lobe3 = exp(-pow(angDiff(ang, -110) / 50, 2)) * 18;
  let indent = exp(-pow(angDiff(ang, -35) / 40, 2)) * -22;
  let base = 158 + lobe1 + lobe2 + lobe3 + indent + (n1 - 0.5) * 42 + (n2 - 0.5) * 20;
  let crispy = (n3 - 0.5) * extraRough;
  return (base + crispy) * scaleMul;
}

