    drawShapePoly(pts, 0.35);
    // Inner dry mineral tide line
    let innerPts = makeRustBlob(p.x, p.y, p.rx * 0.72, p.ry * 0.72, p.rot, 0.48, 36, p.seed + 2.5);
    brush.set("2H", "#e69a55", 0.45);
    drawShapePoly(innerPts, 0.35);
  }
  brush.noField();

  // Spray flecks adding pitted scale across the pan bed, walls, and handle
  let sprayConfigs = [
    { col: "#2b1b10", wt: 1.05, count: 65 }, // Deep raw umber pitting
    { col: "#8a3316", wt: 0.95, count: 75 }, // Burnt sienna oxidation flecks
    { col: "#d15c24", wt: 0.90, count: 75 }, // Mars orange scale
    { col: "#e69145", wt: 0.75, count: 45 }, // Fine bright ferric dust
    { col: "#141210", wt: 0.85, count: 55 }  // Pitted black steel scale
  ];

  for (let cfg of sprayConfigs) {
    brush.set("spray", cfg.col, cfg.wt);
    for (let i = 0; i < cfg.count; i++) {
      // Bias spray toward the right/lower-right/spouts and rust zones
      let ang = random(-110, 210);
      if (random() < 0.25) ang = random(0, 360);
      let d = random(70, R_OUT - 12);
      let x = SX + cos(ang) * d;
      let y = SY + sin(ang) * d;
      brush.flowLine(x, y, random(25, 75), random(360));
    }
    // Spray along handle
    for (let i = 0; i < cfg.count * 0.22; i++) {
      let hd = random(390, 920);
      let hw = random(-32, 32);
      let hx = SX + cos(H_ANG) * hd - sin(H_ANG) * hw;
      let hy = SY + sin(H_ANG) * hd + cos(H_ANG) * hw;
      if (hx < 1190 && hy < 1190) {
        brush.flowLine(hx, hy, random(20, 50), H_ANG + random(-25, 25));
      }
    }
  }

  // Hyperreal pitted scale islands & flaking iron crust (hundreds of micro-pits)
  for (let i = 0; i < 520; i++) {
    let ang = random(360);
    let r = random(55, R_LIP - 6);
    let px = FX + cos(ang) * r;
    let py = FY + sin(ang) * r;

    // Higher density in oxidized zones
    let inRust = (cos(ang - 25) > -0.2) || (abs(angDiff(ang, 132)) < 25) || (abs(angDiff(ang, -48)) < 25);
    if (!inRust && random() < 0.55) continue;

    let sz = random(2.5, 7.5);
    let colDark = random(["#1c140e", "#2e1c10", "#452310"]);
    let colLight = random(["#b84a1e", "#d96b31", "#e08948", "#8f3d20"]);

    // Dark pit shadow edge
    brush.set("2B", colDark, random(0.45, 0.8));
    brush.line(px, py, px + sz, py + random(-sz * 0.6, sz * 0.6));
    // Raised rust flake highlight edge
    brush.set("cpencil", colLight, random(0.4, 0.7));
    brush.line(px + 0.8, py + 1.2, px + sz + 0.8, py + 1.2);
  }

  // =========================================================================
  // 6. SKILLET RIM, POUR SPOUTS & DIAGONAL HANDLE SCULPTING
  // =========================================================================
  // Inner wall depth shading: dark overhang under upper-left lip, rusty lit slope on lower-right
  for (let a = 0; a < 360; a += 1.5) {
    let rLip = skilletRadius(a, R_LIP, 0.85);
    let rFlr = skilletRadius(a, R_FLOOR, 0.3);
    let x1 = SX + cos(a) * rLip;
    let y1 = SY + sin(a) * rLip;
    let x2 = FX + cos(a) * rFlr;
    let y2 = FY + sin(a) * rFlr;

    // Upper-left inner wall is in deep shadow
    let lightDot = cos(a - 45);
    if (lightDot < 0.1) {
      brush.set("charcoal", "#12100e", 0.95);
      brush.line(x1, y1, x2, y2);
    } else {
      // Lower-right inner wall catches oblique light & rust bloom
      let wallCol = random(["#3b281c", "#59351f", "#7d3d1d", "#9e4b22", "#2b231d"]);
      brush.set("2B", wallCol, 0.75);
      brush.line(x1, y1, x2, y2);
    }
  }

  // Top flat lip of the skillet rim (between R_LIP and R_OUT)
  for (let a = 0; a < 360; a += 1.2) {
    // Skip where handle merges
    if (abs(angDiff(a, H_ANG)) < 10) continue;

    let rOut = skilletRadius(a, R_OUT, 1.0);
    let rLip = skilletRadius(a, R_LIP, 0.85);
    let rm = (rOut + rLip) * 0.5;

    let isSpout = (abs(angDiff(a, -48)) < 16) || (abs(angDiff(a, 132)) < 16);
    let col;
    if (isSpout) {
      col = random(["#783519", "#9e4620", "#4d2c1c", "#b85828"]);
    } else if (cos(a + 135) > 0.2) {
      // Upper-left rim catches dull worn steel/graphite highlight
      col = random(["#59534d", "#6e675f", "#45403b", "#7a726a"]);
    } else {
      col = random(["#2e2925", "#3d312a", "#523626", "#24201d"]);
    }
    brush.set("2B", col, 0.8);
    brush.arc(SX, SY, rm + random(-6, 6), a, a + 2.2);
  }

  // Crisp inner & outer rim edge definition with graphite and burnt umber
  for (let step = 0; step < 2; step++) {
    let baseR = step === 0 ? R_OUT : R_LIP;
    let spScale = step === 0 ? 1.0 : 0.85;
    let pts = makeSkilletPoly(SX, SY, baseR, spScale, 90);
    brush.set("2B", "#141210", 0.75);
    drawShapePoly(pts, 0.35);
  }

  // Metallic graphite glint along the upper-left inner lip bevel
  brush.set("2H", "#948d84", 0.65);
  brush.arc(SX, SY, R_LIP + 2, 185, 295);
  brush.set("HB", "#aba398", 0.45);
  brush.arc(SX, SY, R_OUT - 2, 195, 280);

  // Sculpting the diagonal handle pushing out of the frame
  let ux = cos(H_ANG), uy = sin(H_ANG);
  let vx = -sin(H_ANG), vy = cos(H_ANG);

  // Recessed thumb-groove / channel down the center of the handle
  for (let d = 405; d < 1020; d += 5) {
    let t = map(d, 405, 950, 0, 1, true);
    let halfW = lerp(30, 48, t);
    if (d < 460) halfW = map(d, 405, 460, 62, 30);

    let bx = SX + ux * d;
    let by = SY + uy * d;

    // Upper-right ridge of handle (lit edge)
    brush.set("HB", random(["#5c554e", "#736a61", "#8c5230", "#47413c"]), 0.75);
    brush.line(bx - vx * (halfW - 4), by - vy * (halfW - 4), bx - vx * (halfW - 11), by - vy * (halfW - 11));

    // Lower-left ridge of handle (shadowed & crusted edge)
    brush.set("charcoal", random(["#171513", "#29221d", "#4a2916"]), 0.9);
    brush.line(bx + vx * (halfW - 3), by + vy * (halfW - 3), bx + vx * (halfW - 12), by + vy * (halfW - 12));

    // Inner valley of handle with oxidized crust
    if (random() < 0.75) {
      let cValley = random(["#3b2619", "#6e3419", "#9e4820", "#c25a27", "#261f1b"]);
      let off = random(-halfW * 0.55, halfW * 0.55);
      brush.set("cpencil", cValley, 0.65);
      brush.line(bx + vx * off, by + vy * off, bx + ux * 10 + vx * off, by + uy * 10 + vy * off);
    }
  }

  // Beginning of the teardrop hanging hole right at the bottom-right corner edge (d = 760..890)
  let holePts = [];
  for (let i = 0; i < 28; i++) {
    let a = (i / 28) * 360;
    let hd = 825 + cos(a) * 58;
    let hw = sin(a) * 18 * map(cos(a), -1, 1, 0.55, 1.15);
    holePts.push([SX + ux * hd + vx * hw, SY + uy * hd + vy * hw]);
  }
  // Concrete ground showing through the hanging hole near corner
  brush.noStroke();
  brush.wash("#7a7266", 255); // Shadowed concrete inside hole
  drawShapePoly(holePts, 0.35);
  let litConcreteHole = holePts.map(p => [p[0] + 6, p[1] + 6]);
  brush.wash("#cfc8ba", 230);
  drawShapePoly(litConcreteHole, 0.35);
  brush.noWash();
  brush.set("2B", "#141210", 0.85);
  drawShapePoly(holePts, 0.35);

  // =========================================================================
  // 7. FRESHLY FRIED EGG: SIZZLING OIL HALO & LACY BROWNED EDGES
  // =========================================================================
  const EX = 455;
  const EY = 495;
  const YX = 438;
  const YY = 478;
  const RY = 78;

  // Glossy hot oil / grease sheen surrounding the egg on the pan floor
  let oilPts = [];
  for (let i = 0; i < 48; i++) {
    let a = (i / 48) * 360;
    let r = eggWhiteRadius(a, 1.07, 6);
    oilPts.push([EX + cos(a) * r, EY + sin(a) * r]);
  }
  brush.noStroke();
  brush.fillBleed(0.15, "out");
  brush.fillTexture(0.4, 0.5);
  brush.fill("#14100d", 95);
  drawShapePoly(oilPts, 0.35);
  brush.noFill();

  // Outer ruffled perimeter for the crispy browned Maillard skirt
  let lacyOuterPts = [];
  let mainWhitePts = [];
  let stepsEgg = 96;
  for (let i = 0; i < stepsEgg; i++) {
    let a = (i / stepsEgg) * 360;
    let rOuter = eggWhiteRadius(a, 1.0, 18);
    let rInner = eggWhiteRadius(a, 0.935, 6);
    lacyOuterPts.push([EX + cos(a) * rOuter, EY + sin(a) * rOuter]);
    mainWhitePts.push([EX + cos(a) * rInner, EY + sin(a) * rInner]);
  }

  // Base wash for the toasted golden-brown lacy edge
  brush.noStroke();
  brush.wash("#8c4f20", 235);
  drawShapePoly(lacyOuterPts, 0.4);
  brush.wash("#c48845", 220);
  let midLacyPts = [];
  for (let i = 0; i < stepsEgg; i++) {
    let a = (i / stepsEgg) * 360;
    let rMid = eggWhiteRadius(a, 0.968, 12);
    midLacyPts.push([EX + cos(a) * rMid, EY + sin(a) * rMid]);
  }
  drawShapePoly(midLacyPts, 0.35);

  // =========================================================================
  // 8. EGG WHITE (ALBUMEN): CLEAN, SMOOTH PENCIL TOPOGRAPHY
  // =========================================================================
  // Solid clean ivory-white foundation so the albumen reads crisp and luminous
  brush.wash("#e3ddd1", 245); // Outer translucent albumen rim
  drawShapePoly(mainWhitePts, 0.35);

  let innerSolidWhitePts = [];
  for (let i = 0; i < 64; i++) {
    let a = (i / 64) * 360;
    let r = eggWhiteRadius(a, 0.87, 3);
    innerSolidWhitePts.push([EX + cos(a) * r, EY + sin(a) * r]);
  }
  brush.wash("#f4f1ea", 255);
  drawShapePoly(innerSolidWhitePts, 0.35);

  // Thick inner albumen plateau (the raised ring surrounding the yolk)
  let plateauPts = [];
  for (let i = 0; i < 48; i++) {
    let a = (i / 48) * 360;
    let n = noise(cos(a) * 1.5 + 40, sin(a) * 1.5 + 40);
    let r = 112 + (n - 0.5) * 24 + cos(a - 30) * 12;
    plateauPts.push([YX + 10 + cos(a) * r, YY + 12 + sin(a) * r]);
  }
  brush.wash("#fbf9f5", 255);
  drawShapePoly(plateauPts, 0.35);
  brush.noWash();

  // Smooth, clean pencil hatching across the albumen to model subtle 3D contours
  // 1) Outer translucent zone (2H warm grey-ivory)
  brush.hatchStyle("2H", "#cfc7b8", 0.55);
  brush.hatch(3.2, 35, { rand: 0.02 });
  brush.noStroke();
  drawShapePoly(mainWhitePts, 0.35);
  brush.noHatch();

  // 2) Cross-contour smooth pencil pass on the main egg white
  brush.hatchStyle("2H", "#ded8cc", 0.5);
  brush.hatch(3.5, -55, { rand: 0.015 });
  brush.noStroke();
  drawShapePoly(innerSolidWhitePts, 0.35);
  brush.noHatch();

  // 3) Soft shadow crescent on the lower-right side of the thick albumen plateau
  let plateauShadowPts = [];
  for (let i = 0; i <= 32; i++) {
    let a = map(i, 0, 32, -35, 145);
    let n = noise(cos(a) * 1.5 + 40, sin(a) * 1.5 + 40);
    let r = 112 + (n - 0.5) * 24 + cos(a - 30) * 12;
    plateauShadowPts.push([YX + 10 + cos(a) * r, YY + 12 + sin(a) * r]);
  }
  for (let i = 32; i >= 0; i--) {
    let a = map(i, 0, 32, -35, 145);
    let n = noise(cos(a) * 1.5 + 40, sin(a) * 1.5 + 40);
    let r = (112 + (n - 0.5) * 24 + cos(a - 30) * 12) * 0.76;
    plateauShadowPts.push([YX + 4 + cos(a) * r, YY + 6 + sin(a) * r]);
  }
  brush.hatchStyle("HB", "#c4bba9", 0.5);
  brush.hatch(2.6, 45, { rand: 0.02 });
  brush.noStroke();
  drawShapePoly(plateauShadowPts, 0.35);
  brush.noHatch();

  // Smooth concentric pencil contour lines modeling the silky albumen slope
  for (let ring = 0; ring < 28; ring++) {
    let t = ring / 28;
    let aStart = random(0, 360);
    let aSpan = random(45, 130);
    let pts = [];
    for (let a = aStart; a <= aStart + aSpan; a += 6) {
      let r = lerp(RY + 6, 155, t) + (noise(cos(a) + t * 3, sin(a) + t * 3) - 0.5) * 14;
      let px = lerp(YX, EX, t) + cos(a) * r;
      let py = lerp(YY, EY, t) + sin(a) * r;
      pts.push([px, py]);
    }
    // Shaded on lower-right, luminous on upper-left
    let midA = aStart + aSpan * 0.5;
    let isShadowSide = cos(midA - 45) > 0;
    let pCol = isShadowSide
      ? random(["#c7beae", "#b8ae9c", "#d6cfc2"])
      : random(["#ffffff", "#f7f5f0", "#ebe6dc"]);
    brush.set("2H", pCol, 0.5);
    brush.spline(pts, 0.35);
  }

  // Warm golden-amber subsurface glow reflected from the yolk onto the surrounding white
  for (let a = 0; a < 360; a += 3) {
    let r1 = RY + 1;
    let r2 = RY + random(14, 28);
    let cGlow = cos(a - 45) > 0 ? "#d9a773" : "#f2d2a7";
    brush.set("cpencil", cGlow, 0.55);
    brush.line(
      YX + cos(a) * r1,
      YY + sin(a) * r1,
      YX + cos(a) * r2,
      YY + sin(a) * r2
    );
  }

  // Delicate small steam/frying dimples in the outer flat egg white (rendered in 2H/HB pencil)
  let dimples = [
    { x: EX + 125, y: EY - 35, r: 9 },
    { x: EX + 142, y: EY - 12, r: 6 },
    { x: EX + 95, y: EY + 115, r: 11 },
    { x: EX + 118, y: EY + 98, r: 6.5 },
    { x: EX - 120, y: EY + 65, r: 8.5 },
    { x: EX - 95, y: EY + 95, r: 5.5 },
    { x: EX - 55, y: EY - 125, r: 7.5 },
    { x: EX + 45, y: EY - 118, r: 6 }
  ];
  for (let d of dimples) {
    brush.set("2H", "#b8afa0", 0.5);
    brush.arc(d.x, d.y, d.r, 120, 310);
    brush.set("2H", "#ffffff", 0.55);
    brush.arc(d.x, d.y, d.r, -60, 120);
  }

  // =========================================================================
  // 9. CRISP LACY BROWNED EDGES (INTRICATE PENCIL & BLISTER PERFORATIONS)
  // =========================================================================
  // Tiny perforated holes along the crispy edge where dark iron & rust peek through
  brush.noStroke();
  for (let i = 0; i < 115; i++) {
    let a = (i / 115) * 360 + random(-1.5, 1.5);
    let rBase = eggWhiteRadius(a, 0.965, 12);
    let bx = EX + cos(a) * (rBase + random(-7, 6));
    let by = EY + sin(a) * (rBase + random(-7, 6));
    let bRad = random(1.8, 5.2);

    // Dark iron/rust hole
    let holeCol = (cos(a - 25) > 0) ? random(["#3b2214", "#6e3219", "#241b16"]) : "#1f1b18";
    brush.wash(holeCol, 240);
    let holePoly = makeRustBlob(bx, by, bRad, bRad * random(0.7, 1.3), a, 0.25, 10, i * 3.1);
    drawShapePoly(holePoly, 0.3);
  }
  brush.noWash();

  // Crisp toasted protein filaments, curls, and browned blisters around the entire perimeter
  for (let i = 0; i < 360; i += 0.9) {
    let rOut = eggWhiteRadius(i, 1.0, 18);
    let rIn = eggWhiteRadius(i, 0.915, 5);
    let xOut = EX + cos(i) * rOut;
    let yOut = EY + sin(i) * rOut;
    let xIn = EX + cos(i) * rIn;
    let yIn = EY + sin(i) * rIn;
    let xMid = (xOut + xIn) * 0.5 + random(-3, 3);
    let yMid = (yOut + yIn) * 0.5 + random(-3, 3);

    // Outer charred/caramelized crisp tip
    let cDark = random(["#47200a", "#693212", "#87441b", "#57280e"]);
    brush.set("cpencil", cDark, random(0.45, 0.8));
    brush.line(xOut, yOut, xMid, yMid);

    // Golden-brown toasted transition into the smooth white
    let cGold = random(["#b0692c", "#cc8843", "#e0ad6c", "#f0d3a5"]);
    brush.set("cpencil", cGold, random(0.4, 0.65));
    brush.line(xMid, yMid, xIn, yIn);

    // Tiny white blister highlights along the crispy lace
    if (random() < 0.28) {
      brush.set("2H", "#fffdf7", 0.5);
      brush.line(xMid, yMid, xMid + cos(i) * 3, yMid + sin(i) * 3);
    }
  }

  // =========================================================================
  // 10. THE GLOSSY YOLK & SINGLE WET HIGHLIGHT
  // =========================================================================
  // Subtle ambient contact shadow where the yolk dome sits in the albumen cradle
  brush.noStroke();
  brush.fillBleed(0.12, "out");
  brush.fillTexture(0.3, 0.3);
  brush.fill("#b87b48", 95);
  drawShapePoly(makeRustBlob(YX + 5, YY + 6, RY + 4, RY + 4, 0, 0.04, 48, 90.1));
  brush.noFill();

  // Layered opaque washes building the rich, spherical, translucent-looking yolk dome
  // 1) Deep amber-vermilion outer base
  brush.wash("#bd4c14", 255);
  drawShapePoly(makeRustBlob(YX, YY, RY, RY, 0, 0.03, 56, 91.2));

  // 2) Warm Mars-cadmium orange main body
  brush.wash("#db6818", 245);
  drawShapePoly(makeRustBlob(YX - 3, YY - 3, RY * 0.93, RY * 0.93, 0, 0.03, 52, 92.3));

  // 3) Luminous golden-orange mid-dome shifted slightly toward upper-left light source
  brush.wash("#ed8422", 235);
  drawShapePoly(makeRustBlob(YX - 7, YY - 7, RY * 0.82, RY * 0.82, 0, 0.03, 48, 93.4));

  // 4) Radiant saffron-amber upper dome
  brush.wash("#f79f2e", 225);
  drawShapePoly(makeRustBlob(YX - 13, YY - 13, RY * 0.66, RY * 0.66, 0, 0.03, 44, 94.5));

  // 5) Bright golden subsurface crown right around the highlight zone
  brush.wash("#fcb944", 210);
  drawShapePoly(makeRustBlob(YX - 20, YY - 20, RY * 0.45, RY * 0.45, 0, 0.03, 40, 95.6));
  brush.noWash();

  // Ultra-smooth colored pencil shading sculpting the spherical curvature of the yolk
  // Radial and concentric curved strokes for seamless hyperreal gradation
  for (let r = RY - 1; r > 12; r -= 2.2) {
    let t = r / RY; // 1 at rim, 0 at center
    for (let a = 0; a < 360; a += 8) {
      let lightFactor = cos(a + 135); // +1 at upper-left (-135 deg), -1 at lower-right (45 deg)
      let col;
      if (t > 0.85) {
        // Outer membrane tension ring & lower-right bounce light
        col = lightFactor < -0.3 ? "#e88d2c" : "#a83e0f";
      } else if (lightFactor > 0.35) {
        col = t < 0.55 ? "#ffd166" : "#f7a833";
      } else if (lightFactor > -0.25) {
        col = t < 0.55 ? "#f59b2a" : "#e07019";
      } else {
        // Deep rich orange-sienna core shadow crescent on the lower-right dome
        col = t > 0.68 ? "#c25014" : "#b34310";
      }
      brush.set("cpencil", col, 0.55);
      let cxOff = lerp(YX - 16, YX, t);
      let cyOff = lerp(YY - 16, YY, t);
      brush.arc(cxOff, cyOff, r, a, a + 10);
    }
  }

  // Delicate vitelline membrane crease where yolk meets the thick egg white
  for (let a = 0; a < 360; a += 4) {
    let cRim = cos(a - 45) > 0 ? "#8f320b" : "#c75818";
    brush.set("cpencil", cRim, 0.5);
    brush.arc(YX, YY, RY, a, a + 4.5);
  }

  // SINGLE WET HIGHLIGHT ON THE YOLK
  // A crisp, curved window-reflection arc on the upper-left dome of the yolk
  let hlPts = [];
  let hlSteps = 32;
  // Curved band from angle 192 to 252 degrees
  for (let i = 0; i <= hlSteps; i++) {
    let a = map(i, 0, hlSteps, 194, 252);
    let r = RY * 0.64 + sin((i / hlSteps) * 180) * 4;
    hlPts.push([YX + cos(a) * r, YY + sin(a) * r]);
  }
  for (let i = hlSteps; i >= 0; i--) {
    let a = map(i, 0, hlSteps, 194, 252);
    let taper = sin((i / hlSteps) * 180);
    let r = RY * 0.64 - (13 * taper + 3.5);
    hlPts.push([YX + cos(a) * r, YY + sin(a) * r]);
  }

  // Subtle warm bloom halo around the wet highlight
  brush.noStroke();
  brush.wash("#ffe89e", 170);
  let hlHaloPts = hlPts.map(p => [
    YX + (p[0] - YX) * 1.04 - 1,
    YY + (p[1] - YY) * 1.04 - 1
  ]);
  drawShapePoly(hlHaloPts, 0.35);

  // Razor-crisp pure white wet specular highlight
  brush.wash("#ffffff", 255);
  drawShapePoly(hlPts, 0.35);
  brush.noWash();

  // Reinforce the crisp wet edge of the highlight with fine white pencil
  brush.set("2H", "#ffffff", 0.75);
  drawShapePoly(hlPts, 0.35);

  noLoop();
}

// ============================================================================
// HYPERREALISM MEETS NIANHUA (CHINESE NEW YEAR WOODBLOCK PRINT)
// A chubby toddler in a quilted crimson jacket hugging a wriggling golden carp
// ============================================================================

const PAL = {
  paperBase: "#efe2c9",
  paperWarm: "#e3cfa9",
  paperEdge: "#cbb084",
  // Nianhua flat woodblock pigments (earthy mineral brights)
  vermilion: "#cf3424",
  crimson: "#b22218",
  crimsonDark: "#6e120c",
  peach: "#ec9787",
  peachLight: "#f6bdb0",
  emerald: "#1d7a55",
  emeraldLight: "#33996f",
  emeraldDark: "#104730",
  lemon: "#e8be36",
  lemonLight: "#f6d762",
  ochre: "#c48425",
  keyline: "#1a1310",
  // Hyperreal watercolor tones (flesh, carp, water)
  fleshLight: "#fad8", // fallback-safe hex below
  skinBase: "#f7dfd0",
