function draw() {
  translate(-width / 2, -height / 2);

  // 1. Aged Mulberry / Xuan Paper Ground & Woodblock Print Frame
  drawAgedPaperAndFrame();

  // 2. Nianhua Flat Background: Auspicious Cloud Scrolls & Coin Motifs (Lotus-free)
