  // 5. Quilted Crimson Jacket Collar, Frogs & Sleeve Shoulders
  drawJacketCollarAndSleeves();

  // 6. The Wriggling Golden Carp: Hyperreal Watercolor Scales, Gaping Mouth & Fins
  drawHyperrealCarp();

  // 7. Toddler's Chubby Hands Clutching the Slippery Carp
  drawToddlerHands();

