}

// ============================================================================
// GEOMETRY & SHAPE HELPERS
// ============================================================================

function polyShape(pts, curvature = 0.2, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed ? CLOSE : undefined);
}

function makeEllipsePts(cx, cy, rx, ry, n = 28, rotDeg = 0) {
  let pts = [];
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    let lx = cos(a) * rx;
    let ly = sin(a) * ry;
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

