// 1. AGED PAPER GROUND & FRAME
// ============================================================================

function drawAgedPaperAndFrame() {
  brush.noField();
  brush.noStroke();

  // Subtle warm earth washes around edges to age the paper
  brush.fillBleed(0.45, "in");
  brush.fillTexture(0.55, 0.25);
  brush.fill(PAL.paperWarm, 65);
  polyShape([
    [20, 20], [1180, 20], [1180, 1180], [20, 1180]
  ], 0);

  // Corner warm earth vignettes
  brush.fill(PAL.paperEdge, 50);
  polyShape([[0, 0], [420, 0], [220, 220], [0, 420]], 0.3);
  polyShape([[1200, 0], [780, 0], [980, 220], [1200, 420]], 0.3);
  polyShape([[0, 1200], [420, 1200], [220, 980], [0, 780]], 0.3);
  polyShape([[1200, 1200], [780, 1200], [980, 980], [1200, 780]], 0.3);
  brush.noFill();

  // Fine paper fibers
  brush.set("2H", "#bfa37a", 0.35);
  for (let i = 0; i < 160; i++) {
    let x = random(40, 1160);
    let y = random(40, 1160);
    let a = random(360);
    let l = random(12, 38);
    brush.line(x, y, x + cos(a) * l, y + sin(a) * l);
  }

  // Flat Nianhua decorative border bands
  // Outer vermilion band, inner emerald & lemon corner blocks
  brush.noStroke();
  brush.wash(PAL.vermilion, 215);
  brush.rect(42, 42, 1116, 16, "corner");
  brush.rect(42, 1142, 1116, 16, "corner");
  brush.rect(42, 58, 16, 1084, "corner");
  brush.rect(1142, 58, 16, 1084, "corner");

  brush.wash(PAL.lemon, 220);
  brush.rect(58, 58, 1084, 8, "corner");
  brush.rect(58, 1134, 1084, 8, "corner");
  brush.rect(58, 66, 8, 1068, "corner");
  brush.rect(1134, 66, 8, 1068, "corner");
  brush.noWash();
}

// ============================================================================
// 2. NIANHUA BACKGROUND: AUSPICIOUS CLOUD SCROLLS & COIN MOTIFS (NO LOTUSES)
// ============================================================================

function drawAuspiciousCloud(cx, cy, sc, flipX, mainCol, innerCol, accentCol) {
  let dir = flipX ? -1 : 1;

  // Cloud tail ribbon
  let tailPts = [
    [cx - dir * 95 * sc, cy + 18 * sc],
    [cx - dir * 135 * sc, cy + 28 * sc],
    [cx - dir * 165 * sc, cy + 8 * sc],
    [cx - dir * 190 * sc, cy + 20 * sc],
    [cx - dir * 160 * sc, cy + 42 * sc],
    [cx - dir * 115 * sc, cy + 44 * sc],
    [cx - dir * 70 * sc, cy + 30 * sc]
  ];
  brush.noStroke();
  brush.wash(accentCol, 225);
  polyShape(tailPts, 0.35);
  brush.noWash();

  // Scalloped outer cloud lobes (constructed from overlapping circles + base)
  let lobes = [
    { x: cx, y: cy - 18 * sc, r: 46 * sc },
    { x: cx - dir * 46 * sc, y: cy - 6 * sc, r: 36 * sc },
    { x: cx + dir * 46 * sc, y: cy - 6 * sc, r: 36 * sc },
    { x: cx - dir * 74 * sc, y: cy + 14 * sc, r: 26 * sc },
    { x: cx + dir * 74 * sc, y: cy + 14 * sc, r: 26 * sc },
    { x: cx, y: cy + 12 * sc, r: 42 * sc }
  ];

  // Marker-flat wash for main cloud body
  brush.noStroke();
  brush.wash(mainCol, 230);
  for (let lb of lobes) {
    brush.circle(lb.x, lb.y, lb.r, 0.04);
  }
  brush.noWash();

  // Inner cloud cushion in contrasting Nianhua bright color
  let innerLobes = [
    { x: cx, y: cy - 12 * sc, r: 30 * sc },
    { x: cx - dir * 36 * sc, y: cy, r: 22 * sc },
    { x: cx + dir * 36 * sc, y: cy, r: 22 * sc },
    { x: cx, y: cy + 10 * sc, r: 26 * sc }
  ];
  brush.wash(innerCol, 235);
  for (let lb of innerLobes) {
    brush.circle(lb.x, lb.y, lb.r, 0.04);
  }
  brush.noWash();

  // Center ruyi heart
  brush.wash(accentCol, 235);
  brush.circle(cx, cy + 4 * sc, 16 * sc, 0.03);
  brush.noWash();

  // Crisp woodblock black keylines
  brush.set("woodblock_ink", PAL.keyline, 1.05);
  polyShape(tailPts, 0.35);

  // Outer scalloped arcs
  brush.arc(cx, cy - 18 * sc, 46 * sc, 195, 345);
  brush.arc(cx - dir * 46 * sc, cy - 6 * sc, 36 * sc, flipX ? 260 : 165, flipX ? 15 : 280);
  brush.arc(cx + dir * 46 * sc, cy - 6 * sc, 36 * sc, flipX ? 165 : 260, flipX ? 280 : 375);
  brush.arc(cx - dir * 74 * sc, cy + 14 * sc, 26 * sc, 120, 310);
  brush.arc(cx + dir * 74 * sc, cy + 14 * sc, 26 * sc, 230, 420);

  // Inner spiral volutes (classic ruyi cloud scroll lines)
  for (let s of [-1, 1]) {
    let sx = cx + s * 34 * sc;
    let sy = cy + 6 * sc;
    let sp = [];
    for (let a = 0; a <= 420; a += 30) {
      let rad = (20 - (a / 420) * 15) * sc;
      sp.push([sx + s * cos(a) * rad, sy + sin(a) * rad]);
    }
    brush.spline(sp, 0.5);
  }

  // Center trefoil keyline
  brush.arc(cx, cy - 12 * sc, 28 * sc, 200, 340);
  brush.arc(cx, cy + 16 * sc, 38 * sc, 25, 155);
}

function drawCoinMotif(cx, cy, r, rimCol, innerCol, ribbonCol) {
  // Festive hanging ribbon / cord behind coin
  brush.noStroke();
  brush.wash(ribbonCol, 225);
  let ribL = [
    [cx - r * 0.2, cy + r * 0.7],
    [cx - r * 0.85, cy + r * 1.45],
    [cx - r * 0.55, cy + r * 1.6],
    [cx - r * 0.05, cy + r * 0.85]
  ];
  let ribR = [
    [cx + r * 0.2, cy + r * 0.7],
    [cx + r * 0.85, cy + r * 1.45],
    [cx + r * 0.55, cy + r * 1.6],
    [cx + r * 0.05, cy + r * 0.85]
  ];
  polyShape(ribL, 0.2);
  polyShape(ribR, 0.2);

  // Outer round coin body
  brush.wash(rimCol, 238);
  brush.circle(cx, cy, r, 0.03);

  // Inner recessed circle
  brush.wash(innerCol, 235);
  brush.circle(cx, cy, r * 0.72, 0.03);

  // Square center hole (filled with paper ground color + subtle inner border)
  let h = r * 0.28;
  brush.wash(PAL.paperBase, 250);
  brush.rect(cx, cy, h * 2, h * 2, "center");
  brush.noWash();

  // Woodblock keylines
  brush.set("woodblock_ink", PAL.keyline, 1.0);
  polyShape(ribL, 0.2);
  polyShape(ribR, 0.2);
  brush.circle(cx, cy, r, 0.03);
  brush.circle(cx, cy, r * 0.72, 0.03);
  brush.rect(cx, cy, h * 2, h * 2, "center");
  brush.rect(cx, cy, h * 2.45, h * 2.45, "center");

  // Four auspicious coin seal marks around the square hole
  let d = r * 0.5;
  // Top & bottom chevrons, left & right ancient script strokes
  brush.line(cx - h * 0.6, cy - d, cx + h * 0.6, cy - d);
  brush.line(cx, cy - d - h * 0.35, cx, cy - d + h * 0.35);
  brush.line(cx - h * 0.6, cy + d, cx + h * 0.6, cy + d);
  brush.line(cx - d, cy - h * 0.5, cx - d, cy + h * 0.5);
  brush.line(cx + d, cy - h * 0.5, cx + d, cy + h * 0.5);
}

function drawCoinString(x, yTop, count, spacing, r) {
  // Red cord linking the coins vertically
  brush.set("flat_gouache", PAL.vermilion, 0.45);
  brush.line(x, yTop - 45, x, yTop + count * spacing + 25);
  brush.set("woodblock_ink", PAL.keyline, 0.9);
  brush.line(x - 3, yTop - 45, x - 3, yTop + count * spacing + 25);
  brush.line(x + 3, yTop - 45, x + 3, yTop + count * spacing + 25);

  // Decorative knot above top coin
  brush.noStroke();
  brush.wash(PAL.vermilion, 235);
  brush.circle(x, yTop - 26, 12, 0.05);
  brush.circle(x - 12, yTop - 26, 8, 0.05);
  brush.circle(x + 12, yTop - 26, 8, 0.05);
  brush.noWash();
  brush.set("woodblock_ink", PAL.keyline, 0.9);
  brush.circle(x, yTop - 26, 12, 0.05);

  let paletteCycle = [
    [PAL.lemon, PAL.peach, PAL.vermilion],
    [PAL.peach, PAL.lemon, PAL.emerald],
    [PAL.emeraldLight, PAL.lemon, PAL.vermilion],
    [PAL.lemon, PAL.emeraldLight, PAL.peach]
  ];

  for (let i = 0; i < count; i++) {
    let cols = paletteCycle[i % paletteCycle.length];
    drawCoinMotif(x, yTop + i * spacing, r, cols[0], cols[1], cols[2]);
  }
}

function drawBackgroundMotifs() {
  // Packed symmetrical background of auspicious clouds and hanging copper coins
  // Upper-left & upper-right hanging coin strings
  drawCoinString(145, 145, 4, 96, 36);
  drawCoinString(1055, 145, 4, 96, 36);

