// ============================================================================
// 6. THE WRIGGLING GOLDEN CARP: HYPERREAL WATERCOLOR SCALES, MOUTH & FINS
// ============================================================================

// Mathematical S-curve spine of the wriggling carp
function getCarpFrame(u) {
  // u in [0, 1]: 0 = gaping snout, 1 = caudal peduncle (tail base)
  // Using smooth cubic Bezier segments for an organic S-curve thrash
  let p0 = { x: 382, y: 458 };
  let p1 = { x: 495, y: 505 };
  let p2 = { x: 675, y: 615 };
  let p3 = { x: 545, y: 790 };
  let p4 = { x: 655, y: 928 };

  let x, y, dx, dy;
  if (u <= 0.5) {
    let t = u * 2;
    let mt = 1 - t;
    x = mt * mt * p0.x + 2 * mt * t * p1.x + t * t * p2.x;
    y = mt * mt * p0.y + 2 * mt * t * p1.y + t * t * p2.y;
    dx = 2 * mt * (p1.x - p0.x) + 2 * t * (p2.x - p1.x);
    dy = 2 * mt * (p1.y - p0.y) + 2 * t * (p2.y - p1.y);
  } else {
    let t = (u - 0.5) * 2;
    let mt = 1 - t;
    x = mt * mt * p2.x + 2 * mt * t * p3.x + t * t * p4.x;
    y = mt * mt * p2.y + 2 * mt * t * p3.y + t * t * p4.y;
    dx = 2 * mt * (p3.x - p2.x) + 2 * t * (p4.x - p3.x);
    dy = 2 * mt * (p3.y - p2.y) + 2 * t * (p4.y - p3.y);
  }

  let len = sqrt(dx * dx + dy * dy) || 1;
  let tx = dx / len;
  let ty = dy / len;
  // Normal pointing toward the dorsal (upper-right) side
  let nx = ty;
  let ny = -tx;

  // Anatomical carp half-width profile w(u), with realistic indentation around u=0.45 where hands squeeze!
  let baseW =
    u < 0.22
      ? lerp(44, 114, sin((u / 0.22) * 90))
      : lerp(114, 44, pow((u - 0.22) / 0.78, 1.15));
  let squeeze = 1.0 - 0.14 * exp(-pow((u - 0.44) / 0.12, 2));
  let w = baseW * squeeze;

  return { x, y, tx, ty, nx, ny, w };
}

function getCarpPoint(u, v) {
  let f = getCarpFrame(u);
  return [f.x + f.nx * v * f.w, f.y + f.ny * v * f.w];
}

function drawFinWithRays(basePts, tipPts, washCol1, washCol2, rayCount) {
  let outline = [...basePts, ...tipPts.slice().reverse()];

  // Translucent watercolor membrane
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.55, 0.3);
  brush.fill(washCol1, 155);
  polyShape(outline, 0.25);

  // Secondary warm tip bleed
  let tipZone = [];
  for (let i = 0; i < basePts.length; i++) {
    tipZone.push([
      lerp(basePts[i][0], tipPts[i][0], 0.45),
      lerp(basePts[i][1], tipPts[i][1], 0.45)
    ]);
  }
  for (let i = tipPts.length - 1; i >= 0; i--) {
    tipZone.push(tipPts[i]);
  }
  brush.fill(washCol2, 125);
  polyShape(tipZone, 0.25);
  brush.noFill();

  // Branching anatomical fin rays
  for (let i = 0; i <= rayCount; i++) {
    let t = i / rayCount;
    let idx = t * (basePts.length - 1);
    let i0 = floor(idx);
    let i1 = min(basePts.length - 1, i0 + 1);
    let frac = idx - i0;

    let bx = lerp(basePts[i0][0], basePts[i1][0], frac);
    let by = lerp(basePts[i0][1], basePts[i1][1], frac);
    let tx = lerp(tipPts[i0][0], tipPts[i1][0], frac);
    let ty = lerp(tipPts[i0][1], tipPts[i1][1], frac);
    let mx = (bx + tx) * 0.5 + (ty - by) * 0.08;
    let my = (by + ty) * 0.5 - (tx - bx) * 0.08;

    // Dark cartilaginous ray spine
    brush.set("2B", i === 0 ? PAL.carpUmber : "#8c3d19", i === 0 ? 1.4 : 0.65);
    brush.spline([[bx, by], [mx, my], [tx, ty]], 0.35);

    // Wet highlight along every third ray
    if (i % 3 === 0) {
      brush.set("specular_pen", "#fae8c8", 0.55);
      brush.line(bx, by, mx, my);
    }
  }

  // Crisp scalloped outer membrane edge
  brush.set("cpencil", "#6e2912", 0.75);
  polyShape(outline, 0.25);
}

function drawHyperrealCarp() {
  // --- A. CAST SHADOW OF CARP ON TODDLER'S CRIMSON JACKET ---
  let shadowPts = [];
  for (let u = 0.05; u <= 0.98; u += 0.06) {
    let p = getCarpPoint(u, 1.04);
    shadowPts.push([p[0] + 18, p[1] + 24]);
  }
  for (let u = 0.98; u >= 0.05; u -= 0.06) {
    let p = getCarpPoint(u, -1.04);
    shadowPts.push([p[0] + 18, p[1] + 24]);
  }
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fill("#3d0906", 115);
  polyShape(shadowPts, 0.3);
  brush.noFill();

  // --- B. FINS BEHIND THE BODY (Dorsal, Pectoral, Pelvic, Anal, Caudal) ---
  // 1. Long serrated Dorsal Fin rising along the arched upper-right ridge (u = 0.26..0.74)
  let dorsalBase = [];
  let dorsalTips = [];
  for (let i = 0; i <= 10; i++) {
    let u = lerp(0.26, 0.74, i / 10);
    let f = getCarpFrame(u);
    let bp = [f.x + f.nx * f.w * 0.92, f.y + f.ny * f.w * 0.92];
    let finH = i === 0 ? 82 : lerp(78, 42, i / 10) + sin(i * 45) * 6;
    let tp = [
      bp[0] + f.nx * finH - f.tx * 22,
      bp[1] + f.ny * finH - f.ty * 22
    ];
    dorsalBase.push(bp);
    dorsalTips.push(tp);
  }
  drawFinWithRays(dorsalBase, dorsalTips, PAL.carpGold, PAL.carpVermilion, 22);

  // 2. Left/Ventral Pectoral Fin flaring outward to viewer's left (u = 0.16..0.28)
  let pecLBase = [getCarpPoint(0.16, -0.82), getCarpPoint(0.22, -0.92), getCarpPoint(0.28, -0.88)];
  let pecLTips = [[295, 565], [272, 628], [328, 672]];
  drawFinWithRays(pecLBase, pecLTips, PAL.carpVermilion, PAL.peach, 16);

  // 3. Pelvic & Anal Fins on lower curve (u = 0.56..0.86)
  let pelvBase = [getCarpPoint(0.55, -0.88), getCarpPoint(0.62, -0.94), getCarpPoint(0.68, -0.88)];
  let pelvTips = [[425, 745], [408, 795], [452, 825]];
  drawFinWithRays(pelvBase, pelvTips, PAL.carpGold, PAL.peach, 12);

  let analBase = [getCarpPoint(0.76, -0.85), getCarpPoint(0.82, -0.9), getCarpPoint(0.88, -0.85)];
  let analTips = [[482, 888], [492, 942], [545, 955]];
  drawFinWithRays(analBase, analTips, PAL.carpVermilion, PAL.carpLemon, 11);

  // 4. Massive Bilobed Translucent Caudal (Tail) Fin whipping upward & right at bottom!
  let tailBase = [
    getCarpPoint(0.95, -0.85),
    getCarpPoint(0.98, -0.4),
    getCarpPoint(0.99, 0.0),
    getCarpPoint(0.98, 0.4),
    getCarpPoint(0.95, 0.85)
  ];
  let tailTips = [
    [575, 1108], // lower lobe tip
    [668, 1118], // lower lobe curve
    [712, 1022], // central fork notch
    [848, 1045], // upper lobe outer swell
    [885, 938]   // upper lobe tip whipping up!
  ];
  drawFinWithRays(tailBase, tailTips, PAL.carpVermilion, PAL.carpLemon, 32);

  // Extra luminous translucent streaks on the whipping tail fin
  brush.set("specular_pen", PAL.white, 0.75);
  brush.spline([tailBase[0], [580, 1030], [575, 1108]], 0.4);
  brush.spline([tailBase[4], [785, 930], [885, 938]], 0.4);

  // --- C. CARP BODY SILHOUETTE & HYPERREAL WATERCOLOR UNDERPAINTING ---
  let bodyOutline = [];
  for (let u = 0.0; u <= 1.0; u += 0.03) {
    bodyOutline.push(getCarpPoint(u, 1.0));
  }
  for (let u = 1.0; u >= 0.0; u -= 0.03) {
    bodyOutline.push(getCarpPoint(u, -1.0));
  }

  // Solid base wash so background jacket lines never show through the solid fish body
  brush.noStroke();
  brush.wash(PAL.carpBelly, 252);
  polyShape(bodyOutline, 0.25);

  // Warm golden-orange mid-body wash
  let flankBand = [];
  for (let u = 0.02; u <= 0.98; u += 0.04) flankBand.push(getCarpPoint(u, 1.0));
  for (let u = 0.98; u >= 0.02; u -= 0.04) flankBand.push(getCarpPoint(u, -0.35));
  brush.wash(PAL.carpGold, 220);
  polyShape(flankBand, 0.25);

  // Deep bronze-umber dorsal ridge wash
  let dorsalBand = [];
  for (let u = 0.04; u <= 0.98; u += 0.04) dorsalBand.push(getCarpPoint(u, 1.0));
  for (let u = 0.98; u >= 0.04; u -= 0.04) dorsalBand.push(getCarpPoint(u, 0.35));
  brush.wash(PAL.carpBronze, 215);
  polyShape(dorsalBand, 0.25);
  brush.noWash();

  // Wet watercolor mottling (vermilion-orange & deep umber patches along the back)
  brush.fillBleed(0.38, "in");
  brush.fillTexture(0.55, 0.28);
  brush.fill(PAL.carpVermilion, 130);
  for (let u of [0.24, 0.42, 0.64, 0.84]) {
    let patch = [
      getCarpPoint(u - 0.07, 0.85),
      getCarpPoint(u + 0.07, 0.85),
      getCarpPoint(u + 0.06, -0.15),
      getCarpPoint(u - 0.06, -0.25)
    ];
    polyShape(patch, 0.35);
  }

  brush.fill(PAL.carpUmber, 115);
  let darkDorsal = [];
  for (let u = 0.08; u <= 0.95; u += 0.05) darkDorsal.push(getCarpPoint(u, 0.98));
  for (let u = 0.95; u >= 0.08; u -= 0.05) darkDorsal.push(getCarpPoint(u, 0.58));
  polyShape(darkDorsal, 0.3);
  brush.noFill();

  // --- D. HUNDREDS OF INDIVIDUALLY RENDERED WET CYCLING SCALES ---
  // We precompute all scales from tail (u=0.96) to operculum (u=0.21) so we can batch fills by color,
  // then draw overlapping crescent scale rims and wet specular highlights!
  let uRows = 24;
  let vCols = 10;
  let scalesByBucket = {
    dorsal: [],
    goldFlank: [],
    vermilionFlank: [],
    lemonMid: [],
    belly: [],
    specular: []
  };
  let allScales = [];

  for (let r = 0; r < uRows; r++) {
    // Draw from tail to head so each anterior scale overlaps the posterior scale
    let uCenter = map(r, 0, uRows - 1, 0.95, 0.21);
    let du = 0.042;
    let stagger = (r % 2) * 0.5;

    for (let c = 0; c < vCols; c++) {
      let tCol = (c + stagger) / vCols;
      if (tCol > 0.96) continue;
      // Sine projection gives realistic 3D cylinder foreshortening near dorsal/ventral edges!
      let vCenter = sin(map(tCol, 0, 1, -78, 78));
      let dv = cos(map(tCol, 0, 1, -78, 78)) * 0.22;

      // Crescent shield polygon for this individual scale
      let pBackTop = getCarpPoint(uCenter + du * 0.72, vCenter + dv * 0.55);
      let pBackApex = getCarpPoint(uCenter + du * 1.05, vCenter);
      let pBackBot = getCarpPoint(uCenter + du * 0.72, vCenter - dv * 0.55);
      let pFrontBot = getCarpPoint(uCenter - du * 0.45, vCenter - dv * 0.78);
      let pFrontTop = getCarpPoint(uCenter - du * 0.45, vCenter + dv * 0.78);

      let pts = [pFrontTop, pBackTop, pBackApex, pBackBot, pFrontBot];
      let scaleObj = { pts, pBackTop, pBackApex, pBackBot, u: uCenter, v: vCenter };
      allScales.push(scaleObj);

      // Assign to color bucket based on 3D cylinder position + organic koi/carp variation
      let nVal = noise(r * 0.35, c * 0.45);
      if (vCenter > 0.48) {
        scalesByBucket.dorsal.push(scaleObj);
      } else if (vCenter > 0.05) {
        if (nVal > 0.52) scalesByBucket.vermilionFlank.push(scaleObj);
        else scalesByBucket.goldFlank.push(scaleObj);
      } else if (vCenter > -0.38) {
        scalesByBucket.lemonMid.push(scaleObj);
      } else {
        scalesByBucket.belly.push(scaleObj);
      }

      // Scales right along the 3D cylindrical specular ridge (v in [0.05, 0.36]) catch blinding wet light
      if (vCenter >= 0.02 && vCenter <= 0.38) {
        scalesByBucket.specular.push(scaleObj);
      }
    }
  }

  // Batch render scale color washes for rich pigment variation
  brush.noStroke();
  brush.wash(PAL.carpUmber, 145);
  for (let s of scalesByBucket.dorsal) polyShape(s.pts, 0.25);

  brush.wash(PAL.carpVermilion, 155);
  for (let s of scalesByBucket.vermilionFlank) polyShape(s.pts, 0.25);

  brush.wash(PAL.carpGold, 155);
  for (let s of scalesByBucket.goldFlank) polyShape(s.pts, 0.25);

  brush.wash(PAL.carpLemon, 150);
  for (let s of scalesByBucket.lemonMid) polyShape(s.pts, 0.25);

  brush.wash(PAL.carpPearl, 165);
  for (let s of scalesByBucket.belly) polyShape(s.pts, 0.25);
  brush.noWash();

  // Draw individual crescent scale pocket shadows & metallic rims from tail to head
  for (let s of allScales) {
    // Dark scale pocket crescent
    let col = s.v > 0.2 ? PAL.carpUmber : s.v > -0.3 ? "#8c3b14" : "#b87a58";
    let w = s.v > -0.3 ? 0.85 : 0.55;
    brush.set("cpencil", col, w);
    brush.spline([s.pBackTop, s.pBackApex, s.pBackBot], 0.45);
  }

  // Lateral line sensory pores along v = 0.12
  brush.set("rotring", PAL.carpUmber, 0.8);
  for (let u = 0.22; u <= 0.94; u += 0.03) {
    let p1 = getCarpPoint(u, 0.12);
    let p2 = getCarpPoint(u + 0.012, 0.12);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Blinding wet mucus specular glints along the 3D cylinder highlight ridge!
  brush.noStroke();
  brush.wash(PAL.white, 175);
  for (let s of scalesByBucket.specular) {
    let hlPts = [
      s.pBackTop,
      s.pBackApex,
      s.pBackBot,
      [
        (s.pBackTop[0] + s.pBackBot[0]) * 0.5,
        (s.pBackTop[1] + s.pBackBot[1]) * 0.5
      ]
    ];
    polyShape(hlPts, 0.2);
  }
  brush.noWash();

  for (let s of scalesByBucket.specular) {
    brush.set("specular_pen", PAL.white, 1.15);
    brush.spline([s.pBackTop, s.pBackApex, s.pBackBot], 0.45);
  }

  // --- E. HYPERREAL CARP HEAD, FLARING OPERCULUM, EYE, GAPING MOUTH & BARBELS ---
  // 1. Operculum (metallic bone gill plates from u = 0.07 to 0.21)
  let gillPlate = [
    getCarpPoint(0.08, 0.95),
    getCarpPoint(0.16, 0.98),
    getCarpPoint(0.21, 0.72),
    getCarpPoint(0.22, 0.05),
    getCarpPoint(0.20, -0.68),
    getCarpPoint(0.14, -0.92),
    getCarpPoint(0.08, -0.78)
  ];

  // Deep crimson raw gill filaments peeking behind flared operculum edge!
  let gillSlit = [
    getCarpPoint(0.19, 0.65),
    getCarpPoint(0.225, 0.25),
    getCarpPoint(0.22, -0.35),
    getCarpPoint(0.18, -0.65),
    getCarpPoint(0.20, 0.05)
  ];
  brush.noStroke();
  brush.wash("#9e1612", 240);
  polyShape(gillSlit, 0.3);

  // Metallic bronze-gold & pearly-peach operculum wash
  brush.fillBleed(0.25, "in");
  brush.fill(PAL.carpGold, 195);
  polyShape(gillPlate, 0.3);
  brush.fill(PAL.peachLight, 145);
  polyShape([
    getCarpPoint(0.11, 0.25),
    getCarpPoint(0.19, 0.35),
    getCarpPoint(0.19, -0.45),
    getCarpPoint(0.11, -0.45)
  ], 0.3);
  brush.noFill();

  // Operculum bone sutures & specular sheen
  brush.set("2B", PAL.carpUmber, 1.1);
  brush.spline([
    getCarpPoint(0.16, 0.92),
    getCarpPoint(0.21, 0.55),
    getCarpPoint(0.22, 0.0),
    getCarpPoint(0.19, -0.68),
    getCarpPoint(0.13, -0.90)
  ], 0.45);
  brush.set("cpencil", PAL.carpBronze, 0.85);
  brush.spline([
    getCarpPoint(0.11, 0.75),
    getCarpPoint(0.15, 0.15),
    getCarpPoint(0.13, -0.65)
  ], 0.45);
  brush.set("specular_pen", PAL.white, 1.25);
  brush.spline([
    getCarpPoint(0.13, 0.35),
    getCarpPoint(0.18, 0.12),
    getCarpPoint(0.17, -0.25)
  ], 0.45);

  // 2. Bulging Glassy Golden Carp Eye (around u = 0.09, v = 0.35)
  let eyePos = getCarpPoint(0.095, 0.32);
  let ex = eyePos[0];
  let ey = eyePos[1];

  // Dark orbital socket
  brush.noStroke();
  brush.wash(PAL.carpUmber, 225);
  brush.circle(ex, ey, 22, 0.04);
  // Metallic brassy-gold iris ring
  brush.wash(PAL.carpLemon, 248);
  brush.circle(ex, ey, 18, 0.03);
  brush.wash(PAL.carpVermilion, 180);
  brush.circle(ex + 2, ey + 2, 15, 0.03);
  // Deep black fish pupil
  brush.wash("#0a0705", 255);
  brush.circle(ex - 1, ey, 10.5, 0.02);
  // Curved glassy cornea reflection
  brush.wash(PAL.white, 255);
  polyShape(makeEllipsePts(ex - 4, ey - 5, 6.5, 3.2, 14, -28), 0.3);
  brush.circle(ex + 5, ey + 5, 2.5, 0.02);
  brush.noWash();
  brush.set("woodblock_ink", PAL.keyline, 1.0);
  brush.circle(ex, ey, 19, 0.03);

  // 3. Hyperreal Gaping Fish Mouth & Whipping Sensory Barbels (u = 0.0)
  // Protrusible telescopic carp lips gaping open toward upper-left!
  let mx = 376;
  let my = 456;

  // Outer fleshy maxillary lip collar
  let outerLip = makeEllipsePts(mx, my, 44, 30, 24, -48);
  let innerLip = makeEllipsePts(mx - 4, my - 3, 31, 20, 24, -48);
  let throatDeep = makeEllipsePts(mx - 1, my - 1, 21, 13, 20, -48);

  brush.noStroke();
  // Translucent fleshy golden-peach lip ring
  brush.wash(PAL.carpBelly, 245);
  polyShape(outerLip, 0.35);
  brush.fillBleed(0.25, "in");
  brush.fill(PAL.carpGold, 165);
  polyShape(outerLip, 0.35);
  brush.noFill();

  // Wet pink-ochre oral cavity & deep umber-crimson throat
  brush.wash("#c95a4e", 240);
  polyShape(innerLip, 0.35);
  brush.wash("#3b120e", 248);
  polyShape(throatDeep, 0.35);

  // Fleshy pink tongue on floor of gaping mouth
  brush.wash("#e88c82", 225);
  polyShape(makeEllipsePts(mx + 4, my + 6, 13, 7, 16, -48), 0.3);
  brush.noWash();

  // Cartilaginous lip folds & blinding wet mucus rim on the gaping mouth
  brush.set("2B", PAL.carpUmber, 1.1);
  polyShape(outerLip, 0.35);
  polyShape(innerLip, 0.35);
  brush.set("specular_pen", PAL.white, 1.45);
  brush.arc(mx - 3, my - 3, 34, 155, 295);
  brush.arc(mx, my, 43, 175, 275);

  // Two pairs of whipping sensory barbels (whiskers) trailing from the upper lip corners
  let barbels = [
    // Upper corner long barbel & short barbel
    { pts: [[398, 424], [372, 385], [335, 368], [305, 378]], w: 1.4 },
    { pts: [[390, 428], [362, 405], [338, 402]], w: 0.9 },
    // Lower corner long barbel & short barbel
    { pts: [[352, 482], [312, 502], [285, 538], [292, 572]], w: 1.4 },
    { pts: [[358, 476], [328, 488], [310, 512]], w: 0.9 }
  ];
  for (let b of barbels) {
    brush.set("flat_gouache", PAL.carpVermilion, b.w * 0.35);
    brush.spline(b.pts, 0.5);
    brush.set("woodblock_ink", PAL.carpUmber, b.w * 0.75);
    brush.spline(b.pts, 0.5);
    brush.set("specular_pen", PAL.white, b.w * 0.5);
    brush.spline(b.pts.slice(0, -1), 0.5);
  }

  // 4. Right/Dorsal Pectoral Fin splayed over the carp's upper flank (u = 0.18..0.28)
  let pecRBase = [getCarpPoint(0.18, 0.72), getCarpPoint(0.23, 0.85), getCarpPoint(0.27, 0.78)];
  let pecRTips = [[558, 442], [608, 468], [625, 518]];
  drawFinWithRays(pecRBase, pecRTips, PAL.carpVermilion, PAL.carpLemon, 14);

  // Crisp outer contour keyline along the carp body to tie it into the print
  brush.set("woodblock_ink", PAL.carpUmber, 1.15);
  polyShape(bodyOutline, 0.25);
}

