// 8. HYPERREAL SPLASHED WATER DROPLETS & REFRACTIVE BEADS
// ============================================================================

function drawHyperrealDroplet(x, y, rx, ry, angleDeg, onDarkSurface = false) {
  // 1. Cast shadow below-right of droplet
  let shPts = makeEllipsePts(x + 3.5, y + 4.5, rx * 0.95, ry * 0.9, 16, angleDeg);
  brush.noStroke();
  brush.wash(onDarkSurface ? "#2e0805" : "#8c6d53", 135);
  polyShape(shPts, 0.3);

  // 2. Main water body (subtle refractive tint)
  let bodyPts = makeEllipsePts(x, y, rx, ry, 18, angleDeg);
  brush.wash(onDarkSurface ? "#d4e8e2" : "#c8ded8", 95);
  polyShape(bodyPts, 0.35);

  // 3. Upper-left internal refractive shadow crescent
  let darkCres = makeEllipsePts(x - rx * 0.18, y - ry * 0.18, rx * 0.72, ry * 0.65, 14, angleDeg);
  brush.wash(PAL.waterShadow, 120);
  polyShape(darkCres, 0.3);

  // 4. Lower-right internal caustic glow
  let caustic = makeEllipsePts(x + rx * 0.22, y + ry * 0.22, rx * 0.58, ry * 0.48, 14, angleDeg);
  brush.wash("#fff9e6", 190);
  polyShape(caustic, 0.3);

  // 5. Razor-sharp pure white upper-left specular pinpoint highlight
  brush.wash(PAL.white, 255);
  brush.circle(x - rx * 0.32, y - ry * 0.32, max(2.2, rx * 0.28), 0.02);
  brush.noWash();

  // Subtle crisp rim on shadow side
  brush.set("rotring", "#2b3836", 0.55);
  brush.arc(x, y, max(rx, ry), angleDeg + 15, angleDeg + 165);
}

function drawSplashSheet(pts) {
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fill(PAL.waterCyan, 115);
  polyShape(pts, 0.35);
  brush.noFill();

  brush.wash(PAL.white, 210);
  polyShape(pts, 0.35);
  brush.noWash();

  brush.set("specular_pen", PAL.white, 1.15);
  polyShape(pts, 0.35);
}

