// Hyperreal Icon of Muddy Work Boots on Burnished Gold Ground
// Rendered with p5.js 2.x and p5.brush

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  brush.scaleBrushes(3);
  randomSeed(7391);
  noiseSeed(7391);

  // Custom micro-grain brush for crisp granular clay flakes and leather pores
  brush.add("flake", {
    type: "custom",
    weight: 1.8,
    scatter: 0.35,
    opacity: 210,
    spacing: 0.45,
    pressure: [0.8, 1.3, 0.7],
    tip: (_m) => {
      _m.rotate(25);
      _m.rect(-1.2, -0.7, 2.4, 1.4);
    },
    rotate: "random",
    markerTip: false,
    noise: 0.8
  });

  // Custom fine chisel brush for gold leaf burnish and leather highlights
  brush.add("burnish", {
    type: "default",
    weight: 2.2,
    scatter: 0.12,
    sharpness: 0.75,
    grain: 0.65,
    opacity: 95,
    spacing: 0.25,
    pressure: [0.3, 1.2, 0.3],
    rotate: "natural",
    noise: 0.5
  });

  // Subtle organic field for leather crease flow
  brush.addField("leather_flow", (t, field) => {
    for (let c = 0; c < field.length; c++) {
      for (let r = 0; r < field[0].length; r++) {
        let nx = c * 0.08;
        let ny = r * 0.08;
        field[c][r] = (noise(nx, ny, t) - 0.5) * 32;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm parchment & red-clay bole gesso undertone
  background("#e5be68");
  brush.set("HB", "#2b190c", 0.5);

  // 1. FLAT BURNISHED GOLD LEAF ICON GROUND
  let leafGrid = buildGoldLeafGrid();
  drawGoldGround(leafGrid);

  // 2. SUBTLE INCISED HALO ARC ABOVE THE BOOTS
  drawIncisedHalo(600, 525);

