// ============================================================================
// GEOMETRY & BATCH DRAWING HELPERS
// ============================================================================

function fillBatch(polyList, col, alpha, bleed = 0.2, tex = 0.65, border = 0.5, curv = 0.12) {
  if (!polyList || polyList.length === 0) return;
  brush.noStroke();
  brush.noHatch();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  for (let i = 0; i < polyList.length; i++) {
    let pts = polyList[i];
    if (!pts || pts.length < 3) continue;
    brush.beginShape(curv);
    for (let j = 0; j < pts.length; j++) {
      brush.vertex(pts[j][0], pts[j][1]);
    }
    brush.endShape(true);
  }
  brush.noFill();
  brush.set("HB", "#2b190c", 0.5);
}

function washBatch(polyList, col, alpha, curv = 0.08) {
  if (!polyList || polyList.length === 0) return;
  brush.noStroke();
  brush.noHatch();
  brush.wash(col, alpha);
  for (let i = 0; i < polyList.length; i++) {
    let pts = polyList[i];
    if (!pts || pts.length < 3) continue;
    brush.beginShape(curv);
    for (let j = 0; j < pts.length; j++) {
      brush.vertex(pts[j][0], pts[j][1]);
    }
    brush.endShape(true);
  }
  brush.noWash();
  brush.set("HB", "#2b190c", 0.5);
}

function hatchPoly(pts, bName, col, weight, dist, angle, opts = { rand: 0.06 }, curv = 0.12) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.hatchStyle(bName, col, weight);
  brush.hatch(dist, angle, opts);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noHatch();
  brush.set("HB", "#2b190c", 0.5);
}

function makeRectPoly(x, y, w, h, jitter = 2) {
  return [
    [x + random(-jitter, jitter), y + random(-jitter, jitter)],
    [x + w * 0.5, y + random(-jitter, jitter)],
    [x + w + random(-jitter, jitter), y + random(-jitter, jitter)],
    [x + w + random(-jitter, jitter), y + h * 0.5],
    [x + w + random(-jitter, jitter), y + h + random(-jitter, jitter)],
    [x + w * 0.5, y + h + random(-jitter, jitter)],
    [x + random(-jitter, jitter), y + h + random(-jitter, jitter)],
    [x + random(-jitter, jitter), y + h * 0.5]
  ];
}

function makeBlobPoly(cx, cy, rx, ry, nPts = 10, irregularity = 0.25, angleOffset = 0) {
  let pts = [];
  for (let i = 0; i < nPts; i++) {
    let a = (i / nPts) * 360 + angleOffset;
    let rMod = 1 + (noise(cx * 0.02 + cos(a), cy * 0.02 + sin(a)) - 0.48) * irregularity * 2;
    let px = cx + cos(a) * rx * rMod;
    let py = cy + sin(a) * ry * rMod;
    pts.push([px, py]);
  }
  return pts;
}

// ============================================================================
// 1. BURNISHED GOLD LEAF GROUND, SEAM SQUARES, SPRAY & CRAQUELURE
// ============================================================================

function buildGoldLeafGrid() {
  // 7x7 grid of gold leaf sheets across the 1200x1200 icon panel
  let xs = [48, 205, 368, 524, 682, 840, 998, 1152];
  let ys = [48, 198, 355, 512, 668, 825, 986, 1152];
  let nodes = [];
  for (let r = 0; r < ys.length; r++) {
    let row = [];
    for (let c = 0; c < xs.length; c++) {
      let jx = (c === 0 || c === xs.length - 1) ? 0 : random(-4, 4);
      let jy = (r === 0 || r === ys.length - 1) ? 0 : random(-4, 4);
      row.push([xs[c] + jx, ys[r] + jy]);
    }
    nodes.push(row);
  }
  return { xs, ys, nodes };
}

function drawGoldGround(grid) {
  let { nodes } = grid;
  let ochrePolys = [];
  let siennaPolys = [];
  let paleGoldPolys = [];
  let deepBolePolys = [];
  let overlapStrips = [];

  for (let r = 0; r < nodes.length - 1; r++) {
    for (let c = 0; c < nodes[0].length - 1; c++) {
      let p00 = nodes[r][c];
      let p10 = nodes[r][c + 1];
      let p11 = nodes[r + 1][c + 1];
      let p01 = nodes[r + 1][c];

      // Slight overlap margin (6-10px) where gold sheets lap over neighbors
      let lap = random(5, 11);
      let poly = [
        [p00[0] - 2, p00[1] - 2],
        [(p00[0] + p10[0]) * 0.5, p00[1] + random(-2, 2)],
        [p10[0] + lap, p10[1] - 2],
        [p10[0] + lap, (p10[1] + p11[1]) * 0.5],
        [p11[0] + lap, p11[1] + lap],
        [(p01[0] + p11[0]) * 0.5, p11[1] + lap],
        [p01[0] - 2, p01[1] + lap],
        [p00[0] - 2, (p00[1] + p01[1]) * 0.5]
      ];

      let cx = (p00[0] + p11[0]) * 0.5;
      let cy = (p00[1] + p11[1]) * 0.5;
      let distToHalo = dist(cx, cy, 600, 510);

      if (distToHalo < 390) {
        paleGoldPolys.push(poly);
        if (random() < 0.65) ochrePolys.push(makeRectPoly(p00[0] + 8, p00[1] + 8, p10[0] - p00[0] - 12, p01[1] - p00[1] - 12, 4));
      } else if (distToHalo < 560) {
        ochrePolys.push(poly);
        if (random() < 0.55) siennaPolys.push(makeRectPoly(p00[0] + 10, p00[1] + 10, (p10[0] - p00[0]) * 0.75, (p01[1] - p00[1]) * 0.75, 5));
      } else {
        siennaPolys.push(poly);
        if (random() < 0.45) deepBolePolys.push(makeRectPoly(p00[0] + 6, p00[1] + 6, (p10[0] - p00[0]) * 0.6, (p01[1] - p00[1]) * 0.6, 5));
      }

      // Narrow overlap seam strips along sheet edges
      if (c < nodes[0].length - 2) {
        overlapStrips.push(makeRectPoly(p10[0] - 5, p10[1], 13, p11[1] - p10[1], 1.5));
      }
      if (r < nodes.length - 2) {
        overlapStrips.push(makeRectPoly(p01[0], p01[1] - 5, p11[0] - p01[0], 13, 1.5));
      }
    }
  }

  // Outer recessed icon border (kovcheg margin)
  let borderPolys = [
    makeRectPoly(0, 0, 1200, 54, 1),
    makeRectPoly(0, 1146, 1200, 54, 1),
    makeRectPoly(0, 50, 54, 1100, 1),
    makeRectPoly(1146, 50, 54, 1100, 1)
  ];

  // Layered Yellow Ochre, Raw Sienna, Red Bole & Burnished Gold Washes
  fillBatch(ochrePolys, "#d99b26", 68, 0.28, 0.72, 0.48, 0.1);
  fillBatch(siennaPolys, "#b86b1b", 62, 0.32, 0.78, 0.55, 0.1);
  fillBatch(paleGoldPolys, "#f5cf67", 78, 0.22, 0.60, 0.42, 0.1);
  fillBatch(deepBolePolys, "#8f3f14", 48, 0.35, 0.82, 0.62, 0.12);
  fillBatch(overlapStrips, "#c47c1e", 56, 0.12, 0.65, 0.68, 0.05);
  fillBatch(borderPolys, "#6e3812", 88, 0.15, 0.75, 0.65, 0.04);

  // Subtle directional burnish grain across sheets
  for (let r = 0; r < nodes.length - 1; r++) {
    for (let c = 0; c < nodes[0].length - 1; c++) {
      if (random() < 0.55) {
        let p00 = nodes[r][c];
        let p11 = nodes[r + 1][c + 1];
        let sub = makeRectPoly(p00[0] + 12, p00[1] + 12, p11[0] - p00[0] - 24, p11[1] - p00[1] - 24, 2);
        let col = (r + c) % 2 === 0 ? "#f7dd88" : "#bd781c";
        let ang = (r + c) % 2 === 0 ? 12 : -78;
        hatchPoly(sub, "burnish", col, 0.55, 9, ang, { rand: 0.08 }, 0.05);
      }
    }
  }

  // Spray flecks along leaf seams and worn red-bole patches
  let sprayPalette = ["#6b360e", "#9e5a16", "#cf8c25", "#fce394", "#fff4c7"];
  for (let s = 0; s < sprayPalette.length; s++) {
    brush.set("spray", sprayPalette[s], random(0.45, 0.85));
    for (let i = 0; i < 28; i++) {
      let pickVert = random() < 0.5;
      if (pickVert) {
        let colIdx = floor(random(1, nodes[0].length - 1));
        let rowIdx = floor(random(0, nodes.length - 1));
        let pA = nodes[rowIdx][colIdx];
        let pB = nodes[rowIdx + 1][colIdx];
        let yA = lerp(pA[1], pB[1], random(0, 0.6));
        let yB = yA + random(35, 95);
        brush.line(pA[0] + random(-10, 10), yA, pB[0] + random(-10, 10), min(yB, 1140));
      } else {
        let rowIdx = floor(random(1, nodes.length - 1));
        let colIdx = floor(random(0, nodes[0].length - 1));
        let pA = nodes[rowIdx][colIdx];
        let pB = nodes[rowIdx][colIdx + 1];
        let xA = lerp(pA[0], pB[0], random(0, 0.6));
        let xB = xA + random(35, 95);
        brush.line(xA, pA[1] + random(-10, 10), min(xB, 1140), pB[1] + random(-10, 10));
      }
    }
  }

  // Fine pen lines tracing the leaf sheets and tiny overlap squares at intersections
  for (let r = 0; r < nodes.length; r++) {
    for (let c = 0; c < nodes[0].length; c++) {
      let pt = nodes[r][c];

      // Horizontal seam segment + parallel overlap line
      if (c < nodes[0].length - 1) {
        let ptR = nodes[r][c + 1];
        let lapOff = (r % 2 === 0 ? 7 : -7) + random(-1.5, 1.5);
        brush.set("rotring", "#6b3d10", 0.32);
        drawBrokenSeamLine(pt[0], pt[1], ptR[0], ptR[1], 5);
        if (r > 0 && r < nodes.length - 1) {
          brush.set("rotring", "#8c5519", 0.24);
          drawBrokenSeamLine(pt[0], pt[1] + lapOff, ptR[0], ptR[1] + lapOff, 4);
          brush.set("rotring", "#fff0b3", 0.25);
          drawBrokenSeamLine(pt[0], pt[1] + 1.4, ptR[0], ptR[1] + 1.4, 3);
        }
      }

      // Vertical seam segment + parallel overlap line
      if (r < nodes.length - 1) {
        let ptB = nodes[r + 1][c];
        let lapOff = (c % 2 === 0 ? 8 : -8) + random(-1.5, 1.5);
        brush.set("rotring", "#6b3d10", 0.32);
        drawBrokenSeamLine(pt[0], pt[1], ptB[0], ptB[1], 5);
        if (c > 0 && c < nodes[0].length - 1) {
          brush.set("rotring", "#8c5519", 0.24);
          drawBrokenSeamLine(pt[0] + lapOff, pt[1], ptB[0] + lapOff, ptB[1], 4);
          brush.set("rotring", "#fff0b3", 0.25);
          drawBrokenSeamLine(pt[0] + 1.4, pt[1], ptB[0] + 1.4, ptB[1], 3);
        }
      }

      // Tiny overlapping squares where 4 sheets of gold leaf meet
      if (r > 0 && r < nodes.length - 1 && c > 0 && c < nodes[0].length - 1) {
        let sqSz = random(11, 18);
        let sx = pt[0] - sqSz * 0.45 + random(-2, 2);
        let sy = pt[1] - sqSz * 0.45 + random(-2, 2);

        brush.set("rotring", "#59300a", 0.35);
        brush.rect(sx, sy, sqSz, sqSz, "corner");

        // Second tiny offset corner square from the fourth overlapping leaf corner
        let sqSz2 = sqSz * random(0.65, 0.9);
        brush.set("rotring", "#8a5218", 0.26);
        brush.rect(sx + random(3, 6), sy + random(3, 6), sqSz2, sqSz2, "corner");

        // Bright gold catch-light along two edges of the tiny overlap square
        brush.set("rotring", "#fff4c2", 0.28);
        brush.line(sx, sy, sx + sqSz, sy);
        brush.line(sx, sy, sx, sy + sqSz);
      }
    }
  }

  // Craquelure networks across the burnished gold ground
  for (let i = 0; i < 62; i++) {
    let cx = random(65, 1135);
    let cy = random(65, 920);
    // Keep slightly sparser inside the boots' lower center so budget focuses on visible gold
    if (cx > 320 && cx < 880 && cy > 580 && cy < 920 && random() < 0.65) continue;
    drawCraquelureTree(cx, cy, random(360), floor(random(4, 9)), random(10, 22), 2);
  }

  // Kovcheg recessed panel frame lines
  brush.set("rotring", "#3d1e07", 0.65);
  brush.rect(48, 48, 1104, 1104, "corner");
  brush.set("rotring", "#59300e", 0.42);
  brush.rect(58, 58, 1084, 1084, "corner");
  brush.set("rotring", "#ffefc2", 0.38);
  brush.line(59, 1142, 1142, 1142);
  brush.line(1142, 59, 1142, 1142);
}

function drawBrokenSeamLine(x1, y1, x2, y2, segs) {
  for (let i = 0; i < segs; i++) {
    if (random() < 0.16) continue;
    let t0 = i / segs;
    let t1 = (i + random(0.65, 0.96)) / segs;
    let ax = lerp(x1, x2, t0) + random(-0.7, 0.7);
    let ay = lerp(y1, y2, t0) + random(-0.7, 0.7);
    let bx = lerp(x1, x2, t1) + random(-0.7, 0.7);
    let by = lerp(y1, y2, t1) + random(-0.7, 0.7);
    brush.line(ax, ay, bx, by);
  }
}

function drawCraquelureTree(x, y, ang, steps, stepLen, depth) {
  if (steps <= 0 || depth <= 0) return;
  let pts = [[x, y, 0.4]];
  let cx = x;
  let cy = y;
  let curAng = ang;
  for (let i = 0; i < steps; i++) {
    curAng += random(-28, 28);
    let l = stepLen * random(0.6, 1.25);
    cx += cos(curAng) * l;
    cy += sin(curAng) * l;
    cx = constrain(cx, 55, 1145);
    cy = constrain(cy, 55, 1145);
    pts.push([cx, cy, map(i, 0, steps, 0.55, 0.15)]);

    if (depth > 1 && i === floor(steps * 0.45) && random() < 0.75) {
      let branchAng = curAng + (random() < 0.5 ? 1 : -1) * random(32, 68);
      drawCraquelureTree(cx, cy, branchAng, floor(steps * 0.6), stepLen * 0.75, depth - 1);
    }
  }
  brush.set("rotring", depth === 2 ? "#59320c" : "#7d4b18", depth === 2 ? 0.25 : 0.18);
  brush.spline(pts, 0.15);
}

// ============================================================================
// 2. SUBTLE INCISED HALO ARC & BYZANTINE/SIENESE PUNCHWORK
// ============================================================================

function drawIncisedHalo(hx, hy) {
  // Subtle luminous gold glow ring inside the halo band
  let haloBand = [];
  for (let a = 165; a <= 375; a += 14) {
    let rOut = 442;
    let rIn = 328;
    let aNext = a + 14;
    haloBand.push([
      [hx + cos(a) * rIn, hy + sin(a) * rIn],
      [hx + cos(a) * rOut, hy + sin(a) * rOut],
      [hx + cos(aNext) * rOut, hy + sin(aNext) * rOut],
      [hx + cos(aNext) * rIn, hy + sin(aNext) * rIn]
    ]);
  }
  fillBatch(haloBand, "#ffe891", 58, 0.18, 0.45, 0.3, 0.08);

  // Concentric incised compass arcs (dark incised groove + 1.8px offset gold bevel highlight)
  let radii = [322, 336, 434, 448, 456];
  for (let i = 0; i < radii.length; i++) {
    let r = radii[i];
    // Draw in fine arc segments so the incision looks hand-struck into gesso & leaf
    for (let a = 158; a < 382; a += 8) {
      if (random() < 0.06) continue;
      let a1 = a + random(-0.5, 0.5);
      let a2 = min(382, a + random(5.8, 7.8));
      // Incised shadow groove
      brush.set("rotring", "#542e09", i === 1 || i === 2 ? 0.48 : 0.34);
      brush.arc(hx, hy, r, a1, a2);
      // Burnished gold lower bevel rim
      brush.set("rotring", "#fff6c7", i === 1 || i === 2 ? 0.42 : 0.28);
      brush.arc(hx, hy + 1.8, r, a1, a2);
    }
  }

  // Delicate radial incised rays inside the main nimbus band (between r=338 and r=432)
  for (let a = 162; a <= 378; a += 2.5) {
    let isMajor = (round(a * 2) % 10 === 0);
    let rStart = isMajor ? 339 : 348;
    let rEnd = isMajor ? 431 : 416 + random(-8, 6);
    let x1 = hx + cos(a) * rStart;
    let y1 = hy + sin(a) * rStart;
    let x2 = hx + cos(a) * rEnd;
    let y2 = hy + sin(a) * rEnd;

    brush.set("2H", isMajor ? "#734210" : "#965b1b", isMajor ? 0.34 : 0.22);
    brush.line(x1, y1, x2, y2);

    if (isMajor) {
      let offA = a + 0.28;
      brush.set("rotring", "#fff4c2", 0.24);
      brush.line(hx + cos(offA) * rStart, hy + sin(offA) * rStart, hx + cos(offA) * rEnd, hy + sin(offA) * rEnd);
    }
  }

  // Sienese punchwork rosettes (punzonatura) along inner and outer borders of the halo
  let punchRings = [329, 441];
  for (let p = 0; p < punchRings.length; p++) {
    let pr = punchRings[p];
    for (let a = 164; a <= 376; a += 4.5) {
      let px = hx + cos(a) * pr;
      let py = hy + sin(a) * pr;

      // Tiny incised circular punch mark + 4 surrounding micro-stipples
      brush.set("rotring", "#4d2908", 0.38);
      brush.circle(px, py, 2.4, 0.15);
      brush.set("rotring", "#fff5c4", 0.30);
      brush.arc(px, py, 2.4, 20, 160);

      for (let k = 0; k < 4; k++) {
        let ka = k * 90 + 45;
        let dx = px + cos(ka) * 4.2;
        let dy = py + sin(ka) * 4.2;
        brush.set("rotring", "#5e340c", 0.32);
        brush.line(dx - 0.6, dy - 0.6, dx + 0.6, dy + 0.6);
      }
    }
  }

  // Subtle decorative scallop/quatrefoil punches inside the halo at 12-degree intervals
  for (let a = 170; a <= 370; a += 12) {
    let rx = hx + cos(a) * 385;
    let ry = hy + sin(a) * 385;
    brush.set("rotring", "#693b0e", 0.32);
    brush.circle(rx, ry, 5.5, 0.2);
    brush.set("rotring", "#fff3bf", 0.26);
    brush.arc(rx, ry, 5.5, 15, 165);
  }
}

// ============================================================================
// 3. HUMBLE ICON GROUND THRESHOLD & CAST SHADOWS
// ============================================================================

function drawHumbleGroundPlane() {
  // Subtle horizontal threshold where the gold ground meets the dusty earthen icon ledge
  let earthBands = [
    makeRectPoly(54, 845, 1092, 300, 4),
    makeBlobPoly(600, 945, 510, 125, 16, 0.18),
    makeBlobPoly(430, 955, 240, 75, 14, 0.22),
    makeBlobPoly(770, 960, 245, 78, 14, 0.22)
  ];
  fillBatch([earthBands[0]], "#b57a24", 46, 0.35, 0.78, 0.45, 0.08);
  fillBatch([earthBands[1]], "#8c561b", 52, 0.38, 0.82, 0.55, 0.15);

  // Cast shadows beneath and between the boots (burnt umber + charcoal watercolor washes)
  let umberShadows = [
    makeBlobPoly(432, 952, 185, 46, 16, 0.18),
    makeBlobPoly(768, 956, 190, 48, 16, 0.18),
    makeBlobPoly(600, 940, 145, 36, 14, 0.22),
    makeBlobPoly(445, 968, 155, 32, 14, 0.15),
    makeBlobPoly(755, 972, 160, 34, 14, 0.15)
  ];
  fillBatch(umberShadows, "#382110", 115, 0.32, 0.85, 0.68, 0.15);

  let deepCoreShadows = [
    makeBlobPoly(432, 948, 142, 24, 14, 0.12),
    makeBlobPoly(768, 952, 146, 25, 14, 0.12),
    makeBlobPoly(600, 938, 72, 20, 12, 0.18)
  ];
  fillBatch(deepCoreShadows, "#170d07", 155, 0.22, 0.78, 0.72, 0.12);

  // Dried ochre & raw umber clay smears on the floor around the boots
  let floorClayOchre = [];
  let floorClayUmber = [];
  for (let i = 0; i < 18; i++) {
    let fx = random(210, 990);
    let fy = random(915, 1065);
    let rx = random(16, 52);
    let ry = random(6, 18);
    if (i % 2 === 0) {
      floorClayOchre.push(makeBlobPoly(fx, fy, rx, ry, 9, 0.32));
    } else {
      floorClayUmber.push(makeBlobPoly(fx, fy, rx * 0.85, ry * 0.85, 9, 0.32));
    }
  }
  fillBatch(floorClayOchre, "#c98e32", 92, 0.25, 0.90, 0.85, 0.18);
  fillBatch(floorClayUmber, "#5c3b1c", 96, 0.22, 0.88, 0.82, 0.18);

  // Horizontal charcoal & 2B hatching grounding the boots to the plane
  for (let s = 0; s < 2; s++) {
    let bx = s === 0 ? 432 : 768;
    let by = s === 0 ? 952 : 956;
    let shPoly = makeBlobPoly(bx, by + 6, 168, 28, 14, 0.12);
    hatchPoly(shPoly, "charcoal", "#1c1008", 0.75, 4.2, 2, { rand: 0.08 }, 0.1);
    hatchPoly(shPoly, "2B", "#331d0e", 0.6, 5.5, -6, { rand: 0.08 }, 0.1);
  }

  // Incised threshold horizon line behind the ankles
  brush.set("rotring", "#63380e", 0.35);
  drawBrokenSeamLine(56, 845, 1144, 845, 14);
  brush.set("rotring", "#fae39c", 0.28);
  drawBrokenSeamLine(56, 846.8, 1144, 846.8, 12);
}

// ============================================================================
// 4. HYPERREAL WORK BOOT RENDERER (ANATOMICAL LAYERED CONSTRUCTION)
// ============================================================================

function drawWorkBoot(cfg) {
  let { cx, topY, soleY, side, tilt, seedOffset } = cfg;
  randomSeed(7391 + seedOffset);
  noiseSeed(7391 + seedOffset);

  // Key anatomical Y landmarks for the boot
  let collarY = topY + 34;       // ~396
  let ankleY = topY + 225;       // ~587 (narrowest waist)
  let throatY = topY + 348;      // ~710 (bottom of lace opening)
  let vampCreaseY = topY + 395;  // ~757 (deepest accordion flex zone)
  let toeCrownY = topY + 455;    // ~817 (bulbous steel-toe dome)
  let weltY = soleY - 62;        // ~890 (Goodyear welt shelf)

  // Slight horizontal perspective shift toward the toe
  let toeCx = cx + side * 10 + tilt * 3.5;

  // --------------------------------------------------------------------------
  // STEP A: COLLAR OPENING, DARK INTERIOR & GUSSETED TONGUE
  // --------------------------------------------------------------------------
  let collarRx = 88;
  let collarRy = 28;

  // Outer rolled leather collar silhouette
  let shaftPoly = [
    [cx - collarRx - 6, collarY],
    [cx - collarRx + 4, collarY - collarRy - 6],
    [cx, collarY - collarRy - 10],
    [cx + collarRx - 4, collarY - collarRy - 6],
    [cx + collarRx + 6, collarY],
    [cx + 84, ankleY - 60],
    [cx + 80, ankleY],
    [cx - 80, ankleY],
    [cx - 84, ankleY - 60]
  ];
  washBatch([shaftPoly], "#2b190e", 230, 0.12);

  // Dark interior abyss of the boot collar
  let interiorPoly = makeBlobPoly(cx, collarY + 2, collarRx - 12, collarRy - 6, 14, 0.08, tilt);
  washBatch([interiorPoly], "#120a06", 248, 0.12);

  // Gusseted leather tongue rising through the center of the collar & between quarters
  let tongueTopX = cx + side * 6;
  let tongueTopY = topY - 6;
  let tonguePoly = [
    [tongueTopX - 42, tongueTopY + 14],
    [tongueTopX - 18, tongueTopY - 4],
    [tongueTopX + 16, tongueTopY - 6],
    [tongueTopX + 44, tongueTopY + 12],
    [cx + 42, collarY + 45],
    [cx + 38, ankleY],
    [cx + 34, throatY + 18],
    [cx - 34, throatY + 18],
    [cx - 38, ankleY],
    [cx - 42, collarY + 45]
  ];
  washBatch([tonguePoly], "#472915", 235, 0.12);
  fillBatch([tonguePoly], "#6b3e1e", 115, 0.18, 0.72, 0.55, 0.12);

  // Horizontal compression folds on the leather tongue
  for (let ty = topY + 22; ty < throatY + 5; ty += 19) {
    let w = map(ty, topY, throatY, 36, 28);
    let sag = random(4, 10);
    let foldPts = [
      [cx - w, ty],
      [cx - w * 0.4, ty + sag],
      [cx + w * 0.4, ty + sag + random(-2, 2)],
      [cx + w, ty + random(-2, 2)]
    ];
    // Dark fold trough
    brush.set("charcoal", "#170c06", random(0.65, 0.95));
    brush.spline(foldPts, 0.35);
    // Warm ochre-brown ridge above trough
    let ridgePts = foldPts.map(p => [p[0], p[1] - 5.5]);
    brush.set("cpencil", "#9e622e", 0.7);
    brush.spline(ridgePts, 0.35);
  }

  // Padded collar rim modeling & vertical leather wrinkles
  for (let a = -15; a <= 195; a += 9) {
    let rad = a;
    let rx1 = cx + cos(rad) * (collarRx - 10);
    let ry1 = collarY + sin(rad) * (collarRy - 5);
    let rx2 = cx + cos(rad) * (collarRx + 7);
    let ry2 = collarY + sin(rad) * (collarRy + 14);
    brush.set("2B", "#1a0e07", 0.55);
    brush.line(rx1, ry1, rx2, ry2);
    brush.set("cpencil", "#8a5326", 0.45);
    brush.line(rx1 + 1.5, ry1, rx2 + 1.5, ry2);
  }

  // --------------------------------------------------------------------------
  // STEP B: HEAVY LUGGED RUBBER OUTSOLE & GOODYEAR WELT
  // --------------------------------------------------------------------------
  let soleW = 134; // half-width at widest forefoot
  let soleLeft = toeCx - soleW;
  let soleRight = toeCx + soleW;

  // Base silhouette of the thick vulcanized lug sole
  let soleBasePoly = [
    [soleLeft + 4, weltY - 8],
    [soleLeft - 4, weltY + 18],
    [soleLeft + 2, soleY - 18],
    [toeCx - 78, soleY - 2],
    [toeCx, soleY + 4],
    [toeCx + 78, soleY - 2],
    [soleRight - 2, soleY - 18],
    [soleRight + 4, weltY + 18],
    [soleRight - 4, weltY - 8],
    [toeCx, weltY + 16]
  ];
  washBatch([soleBasePoly], "#1c1510", 248, 0.08);

  // Subtle rear heel block peeking out on the inner/outer mid-foot behind the forefoot
  let heelSideX = side > 0 ? soleLeft - 14 : soleRight + 14;
  let heelPoly = [
    [heelSideX, weltY - 38],
    [heelSideX + (side > 0 ? 32 : -32), weltY - 38],
    [heelSideX + (side > 0 ? 32 : -32), soleY - 26],
    [heelSideX, soleY - 30]
  ];
  washBatch([heelPoly], "#140e0a", 240, 0.05);

  // Construct 11 chunky vertical rubber lug teeth around the frontal curve of the sole
  let numLugs = 11;
  let mudRecessPolys = [];
  for (let i = 0; i < numLugs; i++) {
    let t0 = i / numLugs;
    let t1 = (i + 0.68) / numLugs;
    let ang0 = lerp(172, 8, t0);
    let ang1 = lerp(172, 8, t1);

    let lx0 = toeCx + cos(ang0) * (soleW + 2);
    let lx1 = toeCx + cos(ang1) * (soleW + 2);
    let topLugY0 = weltY + 8 + sin(ang0) * 26;
    let topLugY1 = weltY + 8 + sin(ang1) * 26;
    let botLugY0 = topLugY0 + 38 + sin(ang0) * 8;
    let botLugY1 = topLugY1 + 38 + sin(ang1) * 8;

    let lugPoly = [
      [lx0, topLugY0],
      [lx1, topLugY1],
      [lx1, botLugY1],
      [lx0, botLugY0]
    ];
    // Dark rubber tooth
    hatchPoly(lugPoly, "charcoal", "#120d09", 0.75, 2.8, 88, { rand: 0.04 }, 0.03);

    // Highlight edge on each rubber lug
    brush.set("2H", "#544132", 0.45);
    brush.line(lx0 + 1, topLugY0 + 2, lx0 + 1, botLugY0 - 2);
    brush.line(lx0, botLugY0, lx1, botLugY1);

    // Recessed notch between lugs (packed with dried clay!)
    if (i < numLugs - 1) {
      let tNext = (i + 1) / numLugs;
      let angNext = lerp(172, 8, tNext);
      let lxNext = toeCx + cos(angNext) * (soleW + 2);
      let topNext = weltY + 8 + sin(angNext) * 26;
      let botNext = topNext + 34 + sin(angNext) * 8;
      mudRecessPolys.push([
        [lx1, topLugY1 + 2],
        [lxNext, topNext + 2],
        [lxNext, botNext - 3],
        [lx1, botLugY1 - 3]
      ]);
    }
  }

  // Goodyear Welt Shelf (protruding stitched leather rim above the lugs)
  let weltBand = [];
  for (let a = 176; a >= 4; a -= 12) {
    let wx = toeCx + cos(a) * (soleW + 3);
    let wy = weltY - 4 + sin(a) * 26;
    weltBand.push([wx, wy]);
  }
  for (let a = 4; a <= 176; a += 12) {
    let wx = toeCx + cos(a) * (soleW - 8);
    let wy = weltY - 18 + sin(a) * 24;
    weltBand.push([wx, wy]);
  }
  washBatch([weltBand], "#3b2312", 240, 0.08);
  fillBatch([weltBand], "#704521", 110, 0.15, 0.78, 0.65, 0.08);

  // Coarse waxed welt stitches along the Goodyear welt shelf
  for (let a = 170; a >= 10; a -= 4.2) {
    let aNext = a - 2.4;
    let sx1 = toeCx + cos(a) * (soleW - 2);
    let sy1 = weltY - 10 + sin(a) * 25;
    let sx2 = toeCx + cos(aNext) * (soleW - 2);
    let sy2 = weltY - 10 + sin(aNext) * 25;

    // Dark stitch hole recess
    brush.set("rotring", "#1a0e06", 0.55);
    brush.line(sx1 - 1, sy1 + 1, sx2 + 1, sy2 + 1);
    // Waxed cord stitch (some clean buff-ochre, some stained by clay)
    let stCol = random() < 0.6 ? "#dfc088" : "#9e7339";
    brush.set("rotring", stCol, 0.50);
    brush.line(sx1, sy1, sx2, sy2);
  }

  // --------------------------------------------------------------------------
  // STEP C: VAMP, SCARRED BULBOUS TOE BOX & ANKLE QUARTERS (BASE + FORM)
  // --------------------------------------------------------------------------
  // Complete upper leather body polygon (from ankle down to welt rim)
  let vampBodyPoly = [
    [cx - 80, ankleY - 10],
    [cx - 86, ankleY + 45],
    [cx - 106, throatY],
    [toeCx - 124, vampCreaseY],
    [toeCx - 130, toeCrownY],
    [toeCx - 125, weltY - 14],
    [toeCx - 65, weltY + 2],
    [toeCx, weltY + 6],
    [toeCx + 65, weltY + 2],
    [toeCx + 125, weltY - 14],
    [toeCx + 130, toeCrownY],
    [toeCx + 124, vampCreaseY],
    [cx + 106, throatY],
    [cx + 86, ankleY + 45],
    [cx + 80, ankleY - 10],
    [cx + 36, throatY + 12],
    [cx - 36, throatY + 12]
  ];

  // Solid opaque dark leather base wash so gold never bleeds through the boots
  washBatch([vampBodyPoly], "#29170c", 248, 0.12);

  // Layered oil-tanned leather watercolor midtones & warm saddle-ochre highlights
  let leatherMidPolys = [
    makeBlobPoly(toeCx, toeCrownY - 8, 108, 62, 16, 0.12),
    makeBlobPoly(cx - 58, ankleY + 55, 32, 85, 12, 0.15),
    makeBlobPoly(cx + 58, ankleY + 55, 32, 85, 12, 0.15)
  ];
  fillBatch(leatherMidPolys, "#5e361a", 135, 0.25, 0.75, 0.52, 0.15);

  let leatherWarmCrown = [
    makeBlobPoly(toeCx - 6 * side, toeCrownY + 4, 86, 46, 14, 0.14),
    makeBlobPoly(toeCx, vampCreaseY - 14, 78, 22, 12, 0.15)
  ];
  fillBatch(leatherWarmCrown, "#8c5225", 125, 0.28, 0.78, 0.55, 0.15);

  let leatherOchreScuffZone = [
    makeBlobPoly(toeCx - 8 * side, toeCrownY + 8, 58, 30, 12, 0.18),
    makeBlobPoly(toeCx + 22 * side, toeCrownY - 2, 36, 22, 10, 0.20)
  ];
  fillBatch(leatherOchreScuffZone, "#bd7c3a", 115, 0.25, 0.82, 0.62, 0.15);

  // Deep shadow under the bulbous toe nose (just above the Goodyear welt)
  let toeUndercutShadow = [];
  for (let a = 170; a >= 10; a -= 14) {
    toeUndercutShadow.push([toeCx + cos(a) * 126, weltY - 14 + sin(a) * 22]);
  }
  for (let a = 10; a <= 170; a += 14) {
    toeUndercutShadow.push([toeCx + cos(a) * 105, weltY - 34 + sin(a) * 16]);
  }
  fillBatch([toeUndercutShadow], "#140b06", 180, 0.20, 0.75, 0.65, 0.12);

  // Volumetric 3D cross-contour shading across the bulbous toe dome and side walls
  for (let ring = 0; ring < 28; ring++) {
    let t = ring / 27;
    let rx = lerp(24, 126, t);
    let ry = lerp(12, 56, t);
    let domeCy = lerp(toeCrownY + 6, toeCrownY - 12, t);

    // Left and right side-wall shadow strokes wrapping around the toe box
    for (let sideDir of [-1, 1]) {
      let aStart = sideDir < 0 ? 115 : 15;
      let aEnd = sideDir < 0 ? 195 : 65;
      let pts = [];
      for (let a = aStart; a <= aEnd; a += 12) {
        let px = toeCx + cos(a) * rx + random(-1.5, 1.5);
        let py = domeCy + sin(a) * ry + random(-1.5, 1.5);
        pts.push([px, py, map(t, 0, 1, 0.3, 0.95)]);
      }
      let col = t > 0.65 ? "#170c06" : (t > 0.35 ? "#381f0f" : "#6e401e");
      let bType = t > 0.6 ? "charcoal" : "2B";
      brush.set(bType, col, map(t, 0, 1, 0.45, 0.85));
      brush.spline(pts, 0.3);
    }
  }

  // Crown highlight & rough-out scuffed leather grain on the top of the steel toe
  for (let i = 0; i < 48; i++) {
    let ang = random(360);
    let radX = random(4, 68);
    let radY = random(3, 34);
    let sx = toeCx - 5 * side + cos(ang) * radX;
    let sy = toeCrownY + 6 + sin(ang) * radY;
    let len = random(6, 22);
    let scAng = random(-35, 35);
    let col = random() < 0.45 ? "#dfb071" : (random() < 0.6 ? "#b87939" : "#3b2110");
    brush.set(random() < 0.5 ? "cpencil" : "2H", col, random(0.35, 0.65));
    brush.line(sx, sy, sx + cos(scAng) * len, sy + sin(scAng) * len);
  }

  // --------------------------------------------------------------------------
  // STEP D: CHARCOAL-DENSE LEATHER CREASES & CRACKED RIDGES
  // --------------------------------------------------------------------------
  // 1. Deep accordion flex creases across the vamp (between throat and toe box)
  let vampCreases = [
    { y: throatY + 16, w: 94, sag: 16, weight: 0.95, fork: true },
    { y: throatY + 34, w: 106, sag: 22, weight: 1.15, fork: true },
    { y: vampCreaseY + 2, w: 114, sag: 26, weight: 1.25, fork: true },
    { y: vampCreaseY + 22, w: 118, sag: 20, weight: 1.05, fork: true },
    { y: vampCreaseY + 40, w: 112, sag: 14, weight: 0.80, fork: false }
  ];

  for (let cIdx = 0; cIdx < vampCreases.length; cIdx++) {
    let vc = vampCreases[cIdx];
    drawHyperrealLeatherCrease(
      toeCx - vc.w, vc.y + random(-4, 4),
      toeCx + vc.w, vc.y + side * 4 + random(-4, 4),
      vc.sag, vc.weight, vc.fork
    );
  }

  // 2. Ankle & shaft lateral compression creases (wrapping the left and right quarters)
  for (let qSide of [-1, 1]) {
    for (let k = 0; k < 6; k++) {
      let ky = lerp(collarY + 38, throatY - 12, k / 5.5);
      let outerX = cx + qSide * lerp(82, 102, k / 6);
      let innerX = cx + qSide * lerp(40, 34, k / 6);
      let x1 = min(outerX, innerX);
      let x2 = max(outerX, innerX);
      let yLeft = qSide < 0 ? ky - 8 : ky + 10;
      let yRight = qSide < 0 ? ky + 10 : ky - 8;
      drawHyperrealLeatherCrease(x1, yLeft, x2, yRight, random(6, 13), random(0.65, 0.95), false);
    }
  }

  // 3. Fine alligator/spider leather crackle networks across the stressed flex zones
  for (let i = 0; i < 38; i++) {
    let kx = toeCx + random(-105, 105);
    let ky = random(throatY + 10, toeCrownY + 38);
    let nSegs = floor(random(3, 6));
    let pts = [[kx, ky, 0.5]];
    let a = random(-30, 30) + (random() < 0.5 ? 90 : 0);
    for (let s = 0; s < nSegs; s++) {
      a += random(-42, 42);
      kx += cos(a) * random(5, 12);
      ky += sin(a) * random(5, 12);
      pts.push([kx, ky, 0.25]);
    }
    brush.set("rotring", "#120904", random(0.24, 0.42));
    brush.spline(pts, 0.2);
    // Tiny buff-ochre cracked lip edge beside the fissure
    brush.set("2H", "#b87b3e", 0.25);
    brush.line(pts[0][0] + 1, pts[0][1] - 1, pts[1][0] + 1, pts[1][1] - 1);
  }

  // --------------------------------------------------------------------------
  // STEP E: QUARTER FACINGS, TRIPLE STITCHING, EYELETS & BRASS SPEED HOOKS
  // --------------------------------------------------------------------------
  let laceStations = [];
  let numStations = 7; // 4 lower eyelets + 3 upper speed hooks

  for (let qSide of [-1, 1]) {
    let innerEdgePts = [];
    let stitchPts1 = [];
    let stitchPts2 = [];
    let outerSeamPts = [];

    for (let s = 0; s < numStations; s++) {
      let t = s / (numStations - 1); // 0 = bottom (near throat), 1 = top (near collar)
      let sy = lerp(throatY + 4, collarY + 26, t);
      // Gap between quarters widens slightly near ankle flex and narrows where pulled tight
      let halfGap = lerp(29, 36, sin(t * 180)) + (s === 6 ? 10 : 0) + random(-2, 2);
      let sx = cx + qSide * halfGap;

      innerEdgePts.push([sx, sy, 0.8]);
      stitchPts1.push([sx + qSide * 14, sy]);
      stitchPts2.push([sx + qSide * 19, sy]);
      outerSeamPts.push([cx + qSide * lerp(102, 82, t), sy + 12]);

      if (qSide === -1) {
        laceStations[s] = { left: [sx + qSide * 7, sy], right: null, isHook: s >= 4 };
      } else {
        laceStations[s].right = [sx + qSide * 7, sy];
      }
    }

    // Dark recessed shadow cast by the quarter facing onto the tongue
    let shadowEdge = innerEdgePts.map(p => [p[0] - qSide * 4, p[1] + 2, 0.9]);
    brush.set("charcoal", "#120905", 0.95);
    brush.spline(shadowEdge, 0.25);

    // Cut raw leather edge of the quarter facing (warm ochre-tan rawhide core)
    brush.set("cpencil", "#ad7036", 0.65);
    brush.spline(innerEdgePts, 0.25);
    brush.set("rotring", "#241308", 0.42);
    brush.spline(innerEdgePts, 0.25);

    // Double row of fine lock-stitching along the quarter facing
    drawStitchedCurve(stitchPts1, "#d9b47a", "#261409", 5.5);
    drawStitchedCurve(stitchPts2, "#b58b52", "#261409", 5.5);

    // Curved quarter-to-vamp side seam with heavy triple stitching
    let vampSeam = [
      [cx + qSide * 30, throatY + 8],
      [cx + qSide * 58, throatY + 18],
      [toeCx + qSide * 88, vampCreaseY + 6],
      [toeCx + qSide * 114, toeCrownY + 18],
      [toeCx + qSide * 118, weltY - 14]
    ];
    brush.set("charcoal", "#170c06", 0.75);
    brush.spline(vampSeam, 0.35);
    drawStitchedCurve(vampSeam, "#c99f63", "#1f1007", 5.8);
    let vampSeam2 = vampSeam.map(p => [p[0] + qSide * 4.5, p[1] - 2]);
    drawStitchedCurve(vampSeam2, "#ab8046", "#1f1007", 5.8);
  }

  // Render Tarnished Brass Eyelets & Speed Hooks at each station
  for (let s = 0; s < numStations; s++) {
    for (let sideKey of ["left", "right"]) {
      let pt = laceStations[s][sideKey];
      let ex = pt[0];
      let ey = pt[1];

      if (!laceStations[s].isHook) {
        // Brass grommet eyelet: dark hole + tarnished bronze ring + verdigris & gold glint
        brush.set("rotring", "#120a05", 0.75);
        brush.circle(ex, ey, 3.2, 0.1);
        brush.set("cpencil", "#9c7127", 0.65);
        brush.circle(ex, ey, 5.2, 0.12);
        // Verdigris / tarnish fleck
        if (random() < 0.5) {
          brush.set("rotring", "#5e6e46", 0.35);
          brush.arc(ex, ey, 5.2, 110, 220);
        }
        // Sacred overhead gold specular highlight on brass rim
        brush.set("rotring", "#fff4c2", 0.45);
        brush.arc(ex, ey, 4.8, 200, 330);
      } else {
        // Curved brass speed-hook
        let dir = sideKey === "left" ? -1 : 1;
        brush.set("charcoal", "#140b06", 0.65);
        brush.circle(ex + dir * 2, ey + 2, 4.5, 0.15);
        brush.set("cpencil", "#b5842f", 0.75);
        brush.line(ex, ey, ex + dir * 6, ey - 2);
        brush.set("rotring", "#fff4c2", 0.48);
        brush.arc(ex + dir * 2, ey - 1, 4.2, 180, 350);
      }
    }
  }

  // --------------------------------------------------------------------------
  // STEP F: DRIED CLAY IN UMBER & OCHRE WATERCOLOUR + CRISP GRANULAR FLAKES
  // --------------------------------------------------------------------------
  let clayUmberPolys = [];
  let clayOchrePolys = [];
  let claySiltPolys = [];

  // 1. Packed clay inside the sole lug recesses
  for (let i = 0; i < mudRecessPolys.length; i++) {
    if (i % 2 === 0) clayOchrePolys.push(mudRecessPolys[i]);
    else clayUmberPolys.push(mudRecessPolys[i]);
  }

  // 2. Heavy caked mud crust along the Goodyear welt, lower toe box, and side walls
  for (let i = 0; i < 16; i++) {
    let a = map(i, 0, 15, 174, 6);
    let rDist = random(82, 128);
    let mx = toeCx + cos(a) * rDist;
    let my = weltY - 18 + sin(a) * 28 + random(-18, 12);
    let rx = random(14, 34);
    let ry = random(8, 20);
    let blob = makeBlobPoly(mx, my, rx, ry, 9, 0.35);
    if (i % 3 === 0) clayUmberPolys.push(blob);
    else if (i % 3 === 1) clayOchrePolys.push(blob);
    else claySiltPolys.push(blob);
  }

  // 3. Splashed dried clay islands higher up on the vamp creases and ankle quarters
  for (let i = 0; i < 12; i++) {
    let mx = toeCx + random(-98, 98);
    let my = random(ankleY + 35, toeCrownY + 25);
    let rx = random(10, 26);
    let ry = random(6, 15);
    let blob = makeBlobPoly(mx, my, rx, ry, 8, 0.38);
    if (random() < 0.5) clayOchrePolys.push(blob);
    else clayUmberPolys.push(blob);
  }

  // Render the dried clay watercolor washes with strong tide-line border intensity!
  fillBatch(clayUmberPolys, "#4f3218", 138, 0.22, 0.92, 0.88, 0.16);
  fillBatch(clayOchrePolys, "#c78d30", 132, 0.24, 0.94, 0.90, 0.16);
  fillBatch(claySiltPolys, "#e3b868", 118, 0.18, 0.90, 0.86, 0.16);

  // Polygonal shrinkage cracks & crisp tide-line edges around dried clay crusts
  let allClayPolys = clayOchrePolys.concat(claySiltPolys);
  for (let i = 0; i < allClayPolys.length; i++) {
    let pts = allClayPolys[i];
    if (pts.length < 4) continue;
    let p0 = pts[0];
    let pMid = pts[floor(pts.length * 0.5)];
    let cxClay = (p0[0] + pMid[0]) * 0.5;
    let cyClay = (p0[1] + pMid[1]) * 0.5;

    // Dark shadow under the lifted dry clay crust edge
    brush.set("rotring", "#241409", 0.35);
    brush.line(p0[0], p0[1] + 1.5, pts[1][0], pts[1][1] + 1.5);
    // Pale dry silt rim on top edge
    brush.set("rotring", "#f2d699", 0.32);
    brush.line(p0[0], p0[1], pts[1][0], pts[1][1]);

    // Internal mud shrinkage crack
    brush.set("rotring", "#2e1a0b", 0.28);
    brush.line(cxClay - 5, cyClay - 2, cxClay + 6, cyClay + 3);
    brush.line(cxClay + 1, cyClay, cxClay - 2, cyClay + 6);
  }

  // Hundreds of crisp granular clay flakes clinging to the sole, welt, and leather
  let flakeColors = ["#f0d599", "#d9a246", "#b07625", "#593819", "#2b180b"];
  for (let f = 0; f < 135; f++) {
    let fx, fy;
    if (f < 85) {
      // Concentrated around the muddy welt, sole lugs, and lower toe box
      let a = random(5, 175);
      let r = random(65, 136);
      fx = toeCx + cos(a) * r + random(-8, 8);
      fy = weltY - 22 + sin(a) * 36 + random(-24, 28);
    } else {
      // Scattered up the vamp and lower quarters
      fx = toeCx + random(-105, 105);
      fy = random(ankleY + 40, toeCrownY + 30);
    }

    let fSize = random(1.8, 5.2);
    let fAng = random(360);
    let col = flakeColors[f % flakeColors.length];

    // Tiny dark shadow under each crisp granule
    brush.set("rotring", "#1a0e06", 0.38);
    brush.line(fx - 1, fy + 1.2, fx + cos(fAng) * fSize, fy + sin(fAng) * fSize + 1.2);

    // Crisp granular flake mark
    brush.set("flake", col, random(0.45, 0.95));
    brush.line(fx, fy, fx + cos(fAng) * fSize, fy + sin(fAng) * fSize);
  }

  // --------------------------------------------------------------------------
  // STEP G: FRAYED, WEATHERED RAWHIDE & COTTON LACES
  // --------------------------------------------------------------------------
  // Criss-crossing lace passes between stations
  for (let s = 0; s < numStations - 1; s++) {
    // On the right boot, top hook is left unlaced for lived-in asymmetry
    if (side > 0 && s === numStations - 2) continue;

    let L0 = laceStations[s].left;
    let R0 = laceStations[s].right;
    let L1 = laceStations[s + 1].left;
    let R1 = laceStations[s + 1].right;

    // Pass 1: Left bottom to Right top (under)
    drawTexturedLaceCord(L0[0], L0[1], R1[0], R1[1], random(4, 9));
    // Pass 2: Right bottom to Left top (over)
    drawTexturedLaceCord(R0[0], R0[1], L1[0], L1[1], random(4, 9));
  }

  // Bottom horizontal bar pass at station 0
  drawTexturedLaceCord(
    laceStations[0].left[0], laceStations[0].left[1],
    laceStations[0].right[0], laceStations[0].right[1],
    3.5
  );

  // Tangled work knot & long trailing frayed lace ends!
  let knotStation = side < 0 ? 5 : 4;
  let kx = cx + side * 4;
  let ky = laceStations[knotStation].left[1] + 6;

  // Draw the bulky knot core
  for (let k = 0; k < 5; k++) {
    let ka = random(360);
    drawTexturedLaceCord(
      kx + cos(ka) * 8, ky + sin(ka) * 5,
      kx - cos(ka) * 9, ky - sin(ka) * 5,
      random(-4, 4)
    );
  }

  // Loose bow loops
  drawLaceLoop(kx, ky, kx - 48, ky + 28, kx - 14, ky + 38);
  drawLaceLoop(kx, ky, kx + 44, ky + 34, kx + 12, ky + 42);

  // Long trailing lace tails spilling down over the vamp and onto the muddy welt/floor
  if (side < 0) {
    // Left Boot: one tail drapes down the inner vamp, one drapes down the outer vamp
    let tail1 = [
      [kx - 4, ky + 4],
      [cx - 34, throatY - 12],
      [toeCx - 54, vampCreaseY + 18],
      [toeCx - 68, toeCrownY + 32],
      [toeCx - 76, weltY - 2]
    ];
    let tail2 = [
      [kx + 6, ky + 4],
      [cx + 42, throatY + 6],
      [toeCx + 76, vampCreaseY + 26],
      [toeCx + 92, toeCrownY + 40],
      [toeCx + 104, weltY + 14]
    ];
    drawTrailingLaceAndFray(tail1, 24);
    drawTrailingLaceAndFray(tail2, 28);
  } else {
    // Right Boot: broken/knotted lace tail trailing all the way down onto the icon ground!
    let tail1 = [
      [kx - 6, ky + 4],
      [cx - 46, throatY - 4],
      [toeCx - 82, vampCreaseY + 32],
      [toeCx - 102, weltY + 8],
      [toeCx - 122, soleY - 4],
      [toeCx - 148, soleY + 8]
    ];
    let tail2 = [
      [kx + 5, ky + 4],
      [cx + 32, throatY - 18],
      [toeCx + 48, vampCreaseY + 12],
      [toeCx + 52, toeCrownY + 16]
    ];
    drawTrailingLaceAndFray(tail1, 32);
    drawTrailingLaceAndFray(tail2, 26);
  }
}

// ============================================================================
// HYPERREAL SUB-COMPONENTS (CREASES, STITCHING, LACES & FRAYED FIBERS)
// ============================================================================

function drawHyperrealLeatherCrease(x1, y1, x2, y2, sag, weightMult, addForks) {
  let mx = (x1 + x2) * 0.5 + random(-8, 8);
  let my = (y1 + y2) * 0.5 + sag;
  let q1x = lerp(x1, mx, 0.5);
  let q1y = lerp(y1, my, 0.62);
  let q2x = lerp(mx, x2, 0.5);
  let q2y = lerp(my, y2, 0.62);

  let troughPts = [
    [x1, y1, 0.25],
    [q1x, q1y, 0.85 * weightMult],
    [mx, my, 1.15 * weightMult],
    [q2x, q2y, 0.85 * weightMult],
    [x2, y2, 0.25]
  ];

  // 1. Upper ridge catch-light (sacred golden light hitting the top of the leather fold)
  let ridgePts = troughPts.map(p => [p[0], p[1] - 6.5 * weightMult, p[2] * 0.7]);
  brush.set("cpencil", "#c78640", 0.75 * weightMult);
  brush.spline(ridgePts, 0.35);

  let highRidgePts = troughPts.map(p => [p[0], p[1] - 8.2 * weightMult, p[2] * 0.5]);
  brush.set("2H", "#e6b877", 0.45 * weightMult);
  brush.spline(highRidgePts, 0.35);

  // 2. Shaded slope descending into the crease trough
  for (let offset = -4.2; offset <= -1.2; offset += 1.5) {
    let slopePts = troughPts.map(p => [p[0], p[1] + offset, p[2] * 0.8]);
    brush.set("2B", "#361d0d", 0.65 * weightMult);
    brush.spline(slopePts, 0.35);
  }

  // 3. Charcoal-dense crease core trough + razor-sharp rotring fissure
  brush.set("charcoal", "#120904", 0.95 * weightMult);
  brush.spline(troughPts, 0.35);
  brush.set("rotring", "#0d0603", 0.48 * weightMult);
  brush.spline(troughPts, 0.35);

  // 4. Lower reflected lip climbing out of the trough
  let lowerLipPts = troughPts.map(p => [p[0], p[1] + 2.8, p[2] * 0.6]);
  brush.set("cpencil", "#7a4620", 0.55 * weightMult);
  brush.spline(lowerLipPts, 0.35);

  // 5. Y-forked secondary compression folds at the ends of the crease
  if (addForks) {
    let fLeft = [
      [q1x, q1y, 0.6],
      [(x1 + q1x) * 0.5, q1y + 8, 0.4],
      [x1 + 6, y1 + 16, 0.15]
    ];
    let fRight = [
      [q2x, q2y, 0.6],
      [(x2 + q2x) * 0.5, q2y + 8, 0.4],
      [x2 - 6, y2 + 16, 0.15]
    ];
    brush.set("charcoal", "#170c06", 0.65 * weightMult);
    brush.spline(fLeft, 0.3);
    brush.spline(fRight, 0.3);
  }
}

function drawStitchedCurve(pts, threadCol, holeCol, stitchLen) {
  for (let i = 0; i < pts.length - 1; i++) {
    let pA = pts[i];
    let pB = pts[i + 1];
    let d = dist(pA[0], pA[1], pB[0], pB[1]);
    let steps = max(1, floor(d / stitchLen));
    for (let s = 0; s < steps; s++) {
      let t0 = (s + 0.15) / steps;
      let t1 = (s + 0.72) / steps;
      let x0 = lerp(pA[0], pB[0], t0);
      let y0 = lerp(pA[1], pB[1], t0);
      let x1 = lerp(pA[0], pB[0], t1);
      let y1 = lerp(pA[1], pB[1], t1);

      brush.set("rotring", holeCol, 0.42);
      brush.line(x0 - 0.8, y0 + 0.8, x1 - 0.8, y1 + 0.8);
      brush.set("rotring", threadCol, 0.36);
      brush.line(x0, y0, x1, y1);
    }
  }
}

function drawTexturedLaceCord(x1, y1, x2, y2, sag) {
  let mx = (x1 + x2) * 0.5;
  let my = (y1 + y2) * 0.5 + sag;

  // Cast shadow onto the tongue/leather beneath the lace
  let shadowPts = [
    [x1, y1 + 3.5, 0.7],
    [mx, my + 4.5, 0.95],
    [x2, y2 + 3.5, 0.7]
  ];
  brush.set("charcoal", "#120904", 0.85);
  brush.spline(shadowPts, 0.35);

  // Dark underside of the woven rawhide/cotton lace
  let underPts = [
    [x1, y1 + 1.4, 0.8],
    [mx, my + 1.6, 0.95],
    [x2, y2 + 1.4, 0.8]
  ];
  brush.set("2B", "#3d220e", 0.95);
  brush.spline(underPts, 0.35);

  // Main warm ochre-tan lace body
  let bodyPts = [
    [x1, y1, 0.85],
    [mx, my, 1.0],
    [x2, y2, 0.85]
  ];
  brush.set("cpencil", "#b8823b", 1.05);
  brush.spline(bodyPts, 0.35);

  // Top highlight & braided cord texture ticks
  let topPts = [
    [x1, y1 - 1.2, 0.5],
    [mx, my - 1.2, 0.75],
    [x2, y2 - 1.2, 0.5]
  ];
  brush.set("2H", "#ebd096", 0.55);
  brush.spline(topPts, 0.35);

  // Diagonal braid striations along the lace + micro-fuzz
  let steps = 9;
  for (let i = 1; i < steps; i++) {
    let t = i / steps;
    let bx = lerp(lerp(x1, mx, t), lerp(mx, x2, t), t);
    let by = lerp(lerp(y1, my, t), lerp(my, y2, t), t);
    brush.set("rotring", "#4a2a10", 0.28);
    brush.line(bx - 1.8, by - 1.5, bx + 1.8, by + 1.5);

    // Tiny frayed surface whiskers along the worn lace body
    if (random() < 0.55) {
      let wa = random(360);
      let wl = random(3.5, 8.5);
      brush.set("2H", "#e6c687", 0.24);
      brush.line(bx, by, bx + cos(wa) * wl, by + sin(wa) * wl);
    }
  }
}

function drawLaceLoop(x1, y1, ctrlX, ctrlY, x2, y2) {
  let shadowPts = [[x1, y1 + 3, 0.7], [ctrlX, ctrlY + 4, 0.9], [x2, y2 + 3, 0.7]];
  brush.set("charcoal", "#140a05", 0.75);
  brush.spline(shadowPts, 0.45);

  let mainPts = [[x1, y1, 0.8], [ctrlX, ctrlY, 1.0], [x2, y2, 0.8]];
  brush.set("2B", "#472810", 0.95);
  brush.spline(mainPts, 0.45);
  brush.set("cpencil", "#c48d44", 0.85);
  brush.spline(mainPts, 0.45);

  let hiPts = [[x1, y1 - 1.2, 0.5], [ctrlX, ctrlY - 1.2, 0.7], [x2, y2 - 1.2, 0.5]];
  brush.set("2H", "#edd298", 0.45);
  brush.spline(hiPts, 0.45);
}

function drawTrailingLaceAndFray(pts, numFilaments) {
  let shadowPts = pts.map(p => [p[0] + 2.5, p[1] + 3.5, 0.75]);
  brush.set("charcoal", "#140a05", 0.80);
  brush.spline(shadowPts, 0.35);

  let darkPts = pts.map(p => [p[0], p[1] + 1.2, 0.85]);
  brush.set("2B", "#42240e", 0.95);
  brush.spline(darkPts, 0.35);

  let midPts = pts.map(p => [p[0], p[1], 0.9]);
  brush.set("cpencil", "#bd863e", 0.90);
  brush.spline(midPts, 0.35);

  let hiPts = pts.map(p => [p[0] - 0.8, p[1] - 1.0, 0.55]);
  brush.set("2H", "#ebd094", 0.48);
  brush.spline(hiPts, 0.35);

  // Exploded, frayed rawhide & cotton fibers at the burst tip of the lace
  let tip = pts[pts.length - 1];
  let prev = pts[pts.length - 2];
  let baseAng = atan2(tip[1] - prev[1], tip[0] - prev[0]);

  for (let f = 0; f < numFilaments; f++) {
    let spread = map(f, 0, numFilaments - 1, -68, 68) + random(-12, 12);
    let ang1 = baseAng + spread * 0.55;
    let ang2 = baseAng + spread;
    let l1 = random(6, 15);
    let l2 = random(8, 20);

    let p1x = tip[0] + cos(ang1) * l1;
    let p1y = tip[1] + sin(ang1) * l1;
    let p2x = p1x + cos(ang2) * l2;
    let p2y = p1y + sin(ang2) * l2;

    // Shadow under frayed filament
    if (f % 2 === 0) {
      brush.set("rotring", "#1c0f07", 0.22);
      brush.spline([[tip[0], tip[1] + 1.5, 0.4], [p1x, p1y + 1.5, 0.25], [p2x, p2y + 1.5, 0.1]], 0.35);
    }

    // Individual wispy fiber strand
    let fCol = f % 3 === 0 ? "#f2dcab" : (f % 3 === 1 ? "#c79146" : "#6e431c");
    brush.set(f % 2 === 0 ? "rotring" : "2H", fCol, random(0.18, 0.34));
    brush.spline([[tip[0], tip[1], 0.45], [p1x, p1y, 0.3], [p2x, p2y, 0.1]], 0.38);
  }
}

// ============================================================================
// 5. SHARED FOREGROUND CLAY CRUMBS, GOLD LEAF GLINTS & FINAL ACCENTS
// ============================================================================

function drawSharedForegroundDetails() {
  randomSeed(9912);

  // Crisp granular clay crumbs and pebbles scattered across the floor between and in front of the soles
  let crumbPalette = ["#f2d89c", "#d9a143", "#a86e22", "#593617", "#241308"];
  for (let i = 0; i < 160; i++) {
    let cx = random(240, 960);
    let cy = random(925, 1055);
    let sz = random(2.0, 6.8);
    let ang = random(360);
    let col = crumbPalette[i % crumbPalette.length];

    // Tiny cast shadow beneath each fallen clay crumb
    brush.set("rotring", "#170c05", 0.42);
    brush.line(cx - 1, cy + 1.6, cx + cos(ang) * sz, cy + sin(ang) * sz + 1.6);

    // Crisp granular flake
    brush.set("flake", col, random(0.5, 1.0));
    brush.line(cx, cy, cx + cos(ang) * sz, cy + sin(ang) * sz);

    // Occasional larger angular clod of dried clay on the floor
    if (i < 22) {
      let clodPts = makeBlobPoly(cx, cy, random(4, 9), random(2.5, 5.5), 5, 0.35);
      brush.set("rotring", "#2b170a", 0.34);
      brush.beginShape(0.05);
      for (let k = 0; k < clodPts.length; k++) {
        brush.vertex(clodPts[k][0], clodPts[k][1]);
      }
      brush.endShape(true);
      brush.set("rotring", "#f2d89c", 0.30);
      brush.line(clodPts[0][0], clodPts[0][1], clodPts[1][0], clodPts[1][1]);
    }
  }

  // Sacred overhead gold-leaf rim light kissing the top leather edges of both boots
  let rimHighlights = [
    // Left boot collar & tongue top rim
    [[352, 384, 0.3], [392, 362, 0.7], [432, 355, 0.8], [472, 362, 0.6], [512, 384, 0.3]],
    // Right boot collar & tongue top rim
    [[686, 378, 0.3], [728, 356, 0.7], [772, 349, 0.8], [812, 358, 0.6], [850, 380, 0.3]]
  ];
  for (let r = 0; r < rimHighlights.length; r++) {
    brush.set("cpencil", "#fae093", 0.65);
    brush.spline(rimHighlights[r], 0.35);
    brush.set("rotring", "#fff6cc", 0.35);
    brush.spline(rimHighlights[r], 0.35);
  }
}

