// Rendered in p5.js 2.x + p5.brush (WEBGL)

const PALETTE_STOPS = [
  { t: 0.00, rgb: [4, 2, 8] },       // Abyssal obsidian-violet shadow
  { t: 0.12, rgb: [22, 6, 46] },     // Deep rosewood-indigo night
