function clamp01(v) {
  return Math.max(0, Math.min(1, v));
}

function rgbToHex(r, g, b) {
  const toH = (n) => Math.max(0, Math.min(255, Math.round(n))).toString(16).padStart(2, "0");
  return "#" + toH(r) + toH(g) + toH(b);
}

function specRGB(t) {
  const tc = clamp01(t);
  for (let i = 0; i < PALETTE_STOPS.length - 1; i++) {
    const a = PALETTE_STOPS[i];
    const b = PALETTE_STOPS[i + 1];
    if (tc >= a.t && tc <= b.t) {
      const f = (tc - a.t) / (b.t - a.t || 1);
      return [
        a.rgb[0] + (b.rgb[0] - a.rgb[0]) * f,
        a.rgb[1] + (b.rgb[1] - a.rgb[1]) * f,
        a.rgb[2] + (b.rgb[2] - a.rgb[2]) * f
      ];
    }
  }
  return PALETTE_STOPS[PALETTE_STOPS.length - 1].rgb;
}

function specHex(t) {
  const c = specRGB(t);
  return rgbToHex(c[0], c[1], c[2]);
}

function grimeHex(t, warmth = 0) {
  const c = specRGB(clamp01(t));
  const r = c[0] * 0.42 + 28 + warmth * 25;
  const g = c[1] * 0.34 + 16 + warmth * 14;
  const b = c[2] * 0.45 + 32;
  return rgbToHex(r, g, b);
}

function getStringY(s, x) {
  let y = s.yBase;
  if (s.idx === 3) {
    // Active pluck deflection centered around PLUCK_X
    const dx = x - PLUCK_X;
    const pull = 16.5 * Math.exp(-(dx * dx) / (2 * 210 * 210));
    const wave = 4.2 * Math.sin((x - 185) * 0.32) * Math.exp(-(dx * dx) / (2 * 380 * 380));
    y += pull + wave;
  } else if (s.idx === 2) {
    const dx = x - PLUCK_X;
    const wave = 2.8 * Math.sin((x - 185) * 0.45) * Math.exp(-(dx * dx) / (2 * 320 * 320));
    y += wave;
  }
  return y;
}

function fretProximity(x) {
  let minD = 9999;
  for (let i = 0; i < FRETS.length; i++) {
    const d = Math.abs(x - FRETS[i]);
    if (d < minD) minD = d;
  }
  return minD;
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7319);
