function draw() {
  translate(-width / 2, -height / 2);

  drawRosewoodNeck();
  drawInlayMarker();
  drawWoodGrainAndGrime();
  drawFretWires();
  drawStringShadows();

  // Draw top three strings (G, D, A)
  drawWoundString(STRINGS[0]);
  drawWoundString(STRINGS[1]);
  drawWoundString(STRINGS[2]);

  // Draw sideways background shimmer & vibrational ghost before main E string & fingertip
  drawSidewaysUnderShimmer();

  // Draw bottom plucked string (Low E)
  drawWoundString(STRINGS[3]);

  // Draw blurred plucking fingertip entering from bottom edge + foreground sideways colour smear
  drawPluckingFingertipAndShimmer();

  // Final high-contrast specular transients & time-marker calibration ticks
  drawSpectrogramTransients();

  noLoop();
}

// ============================================================================
// 1. ROSEWOOD NECK BASE & SPECTROGRAM THERMAL UNDERGLOW
// ============================================================================
function drawRosewoodNeck() {
  brush.noStroke();

  // Deep obsidian neck base wash
  brush.wash("#06020d", 250);
  brush.rect(0, NECK_TOP, 1200, NECK_BOT - NECK_TOP, "corner");
  brush.noWash();

  // Spectrogram thermal under-glow zones on the rosewood board
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.55, 0.25);

  // Batch fills from dark violet at bottom to warm orange/gold near top string
  const bands = [
    { y: 830, h: 310, col: specHex(0.16), op: 95 },
    { y: 580, h: 260, col: specHex(0.24), op: 85 },
    { y: 340, h: 250, col: specHex(0.34), op: 75 },
    { y: 110, h: 240, col: specHex(0.46), op: 70 }
  ];
  for (let b of bands) {
    brush.fill(b.col, b.op);
    brush.rect(0, b.y, 1200, b.h, "corner");
  }

  // Intense thermal bloom around the plucking zone & frets
  brush.fill(specHex(0.38), 90);
  brush.circle(PLUCK_X + 30, PLUCK_Y + 40, 320, 0.25);

  brush.fill(specHex(0.58), 75);
  brush.circle(PLUCK_X + 60, PLUCK_Y - 10, 190, 0.2);

  for (let fx of FRETS) {
    brush.fill(specHex(0.28), 60);
    brush.rect(fx - 45, NECK_TOP + 20, 90, NECK_BOT - NECK_TOP - 40, "corner");
  }

  brush.noFill();

  // Top & Bottom bevelled neck edges (abyssal frame)
  brush.wash("#020105", 255);
  brush.rect(0, 0, 1200, NECK_TOP, "corner");
  brush.rect(0, NECK_BOT, 1200, 1200 - NECK_BOT, "corner");
  brush.noWash();
}

// ============================================================================
// 2. FRETBOARD INLAY DOT (DARK IRIDESCENT SPECTROGRAM PEARL)
// ============================================================================
function drawInlayMarker() {
  const cx = (FRETS[0] + FRETS[1]) * 0.5;
  const cy = 568;
  const r = 56;

  // Recessed rim in rosewood
  brush.set("charcoal", "#020004", 1.1);
  brush.circle(cx, cy, r + 3, 0.08);

  // Subtle dark mother-of-pearl hatching inside the inlay
  for (let dy = -r; dy <= r; dy += 2.6) {
    const halfW = Math.sqrt(Math.max(0, r * r - dy * dy));
    if (halfW < 2) continue;
    const y = cy + dy;
    const n = noise(cx * 0.02, y * 0.05);
    const t = 0.16 + 0.26 * n + 0.12 * Math.sin(dy * 0.18);
    brush.set("micro_hatch", specHex(t), 0.75 + 0.4 * n);
    brush.line(cx - halfW, y, cx + halfW, y);
  }

  // Diagonal pearl shimmer bands
  for (let i = -14; i <= 14; i++) {
    const offset = i * 3.6;
    const halfW = Math.sqrt(Math.max(0, r * r - offset * offset));
    if (halfW < 6) continue;
    const t = 0.28 + 0.22 * noise(i * 0.3, 9.1);
    brush.set("razor_wire", specHex(t), 0.55);
    brush.line(cx - halfW * 0.7, cy + offset - halfW * 0.3, cx + halfW * 0.7, cy + offset + halfW * 0.3);
  }
}

// ============================================================================
// 3. ROSEWOOD GRAIN, OPEN PORES & FINGER GRIME HATCHING
// ============================================================================
function drawWoodGrainAndGrime() {
  // Horizontal directional rosewood grain lines across the entire fingerboard
  for (let y = NECK_TOP + 4; y < NECK_BOT - 4; y += 3.2) {
    const normY = 1.0 - (y - NECK_TOP) / (NECK_BOT - NECK_TOP); // 0 at bottom, 1 at top
    let x = 0;
    while (x < 1200) {
      const segLen = random(45, 150);
      const x2 = Math.min(1200, x + segLen);
      const xm = (x + x2) * 0.5;
      const n = noise(xm * 0.004, y * 0.028);
      const waveY = (noise(xm * 0.008, y * 0.015) - 0.5) * 6.5;

      // Boost spectrogram warmth near strings and near the pluck point
      let strProx = 0;
      for (let s of STRINGS) {
        const d = Math.abs(y - getStringY(s, xm));
        strProx = Math.max(strProx, Math.exp(-(d * d) / (2 * 52 * 52)));
      }
      const pluckDist = Math.hypot((xm - PLUCK_X) * 0.7, y - PLUCK_Y);
      const pluckBoost = 0.28 * Math.exp(-(pluckDist * pluckDist) / (2 * 240 * 240));

      const t = clamp01(0.04 + normY * 0.22 + n * 0.16 + strProx * 0.18 + pluckBoost);
      const w = 0.55 + n * 0.65;

      brush.set(n > 0.55 ? "coil_shade" : "micro_hatch", specHex(t), w);
      brush.line(x, y + waveY, x2, y + waveY * 0.85 + random(-1.2, 1.2));
      x = x2 + random(4, 18);
    }
  }

  // Deep sunken open rosewood wood pores (characteristic dark horizontal crevices with glowing rims)
  for (let i = 0; i < 420; i++) {
    const px = random(15, 1185);
    const py = random(NECK_TOP + 12, NECK_BOT - 12);
    const plen = random(18, 88);
    const normY = 1.0 - (py - NECK_TOP) / (NECK_BOT - NECK_TOP);

    // Pitch-black pore pit
    brush.set("charcoal", "#020005", random(0.45, 0.95));
    brush.line(px, py, px + plen, py + random(-1.0, 1.0));

    // Rim of finger grime / mineral glow caught in the lower lip of the pore
    const rimT = clamp01(0.14 + normY * 0.36 + random(-0.05, 0.12));
    brush.set("razor_wire", grimeHex(rimT, normY * 0.5), random(0.45, 0.8));
    brush.line(px + 2, py + 1.8, px + plen - 2, py + 1.8);
  }

  // Heavy photographic finger grime buildup packed along both sides of every fret wire
  for (let fx of FRETS) {
    for (let k = 0; k < 480; k++) {
      // Exponential distribution hugging the fret base tangs
      const side = random() < 0.5 ? -1 : 1;
      const dist = 16 + Math.pow(random(), 1.8) * 68;
      const gx = fx + side * dist;
      const gy = random(NECK_TOP + 8, NECK_BOT - 8);
      const normY = 1.0 - (gy - NECK_TOP) / (NECK_BOT - NECK_TOP);

      const len = random(6, 24);
      const ang = random(-18, 18) + (dist < 32 ? side * 55 : 0);
      const dx = Math.cos(ang * Math.PI / 180) * len;
      const dy = Math.sin(ang * Math.PI / 180) * len;

      const t = clamp01(0.10 + normY * 0.38 + random(-0.06, 0.10));
      const col = random() < 0.65 ? grimeHex(t, normY * 0.7) : specHex(t * 0.75);
      brush.set("micro_hatch", col, random(0.5, 1.05));
      brush.line(gx, gy, gx + dx, gy + dy);
    }

    // Fine organic grime stipple along the fret-board crease
    for (let s = 0; s < 55; s++) {
      const sy = random(NECK_TOP + 15, NECK_BOT - 15);
      const normY = 1.0 - (sy - NECK_TOP) / (NECK_BOT - NECK_TOP);
      const side = random() < 0.5 ? -1 : 1;
      const sx = fx + side * random(18, 46);
      brush.set("grime_dust", grimeHex(0.18 + normY * 0.42, 0.4), random(0.4, 0.85));
      brush.line(sx, sy, sx + random(-14, 14), sy + random(-8, 8));
    }
  }

  // Subtle vertical spectrogram time-grid subdivisions between frets
  for (let b = 0; b < 4; b++) {
    const xStart = b === 0 ? 0 : FRETS[b - 1];
    const xEnd = b === 3 ? 1200 : FRETS[b];
    const subCount = 5;
    for (let s = 1; s < subCount; s++) {
      const tx = xStart + ((xEnd - xStart) * s) / subCount;
      for (let y = NECK_TOP + 10; y < NECK_BOT - 10; y += 26) {
        const normY = 1.0 - (y - NECK_TOP) / (NECK_BOT - NECK_TOP);
        const t = 0.12 + normY * 0.28;
        brush.set("razor_wire", specHex(t), 0.38);
        brush.line(tx, y, tx, y + 14);
      }
    }
  }
}

// ============================================================================
// 4. VERTICAL FRET WIRES (3D CROWNED METAL + SPECTROGRAM TIME MARKERS)
// ============================================================================
function drawFretWires() {
  const halfW = 17.5;

  for (let fIdx = 0; fIdx < FRETS.length; fIdx++) {
    const fx = FRETS[fIdx];

    // 1. Deep shadow trenches & grime pocket on left and right of fret tang
    for (let y = NECK_TOP; y < NECK_BOT; y += 3.5) {
      brush.set("charcoal", "#020004", 0.85);
      brush.line(fx - halfW - 11, y, fx - halfW + 1, y + random(-1, 1));
      brush.line(fx + halfW - 1, y, fx + halfW + 14, y + random(-1, 1));
    }

    // 2. Solid dark metallic core wash under fret wire
    brush.noStroke();
    brush.wash("#080312", 245);
    brush.rect(fx - halfW, NECK_TOP, halfW * 2, NECK_BOT - NECK_TOP, "corner");
    brush.noWash();

    // 3. Fine horizontal contoured hatching across the cylindrical fret crown
    for (let y = NECK_TOP + 2; y < NECK_BOT - 2; y += 2.2) {
      const normY = 1.0 - (y - NECK_TOP) / (NECK_BOT - NECK_TOP);

      // Measure proximity to the 4 strings for intense specular & thermal reflection on the fret
      let strGlow = 0;
      for (let s of STRINGS) {
        const sy = getStringY(s, fx);
        const d = Math.abs(y - sy);
        strGlow = Math.max(strGlow, Math.exp(-(d * d) / (2 * 48 * 48)));
      }

      const baseT = clamp01(0.18 + normY * 0.48 + strGlow * 0.26);

      // Left dark bevel (-17.5 to -7)
      brush.set("micro_hatch", specHex(baseT * 0.42), 0.65);
      brush.line(fx - halfW, y, fx - 7, y);

      // Left reflective shoulder (-7 to -1.5)
      brush.set("micro_hatch", specHex( clamp01(baseT * 0.85 + 0.10) ), 0.72);
      brush.line(fx - 7, y, fx - 1.5, y);

      // Right warm shoulder (+2.5 to +11) catching glow from plucking side
      const rightBoost = fx <= PLUCK_X ? 0.14 : 0.06;
      brush.set("micro_hatch", specHex( clamp01(baseT * 0.78 + rightBoost) ), 0.68);
      brush.line(fx + 2.5, y, fx + 11, y);

      // Right dark edge (+11 to +17.5)
      brush.set("micro_hatch", specHex(baseT * 0.30), 0.65);
      brush.line(fx + 11, y, fx + halfW, y);

      // Crown peak highlight (-1.8 to +2.5)
      const crownT = clamp01(baseT + 0.22 + strGlow * 0.18);
      brush.set("razor_wire", specHex(crownT), 0.8 + strGlow * 0.45);
      brush.line(fx - 1.8, y, fx + 2.5, y);
    }

    // 4. Longitudinal vertical hatching along the fret wire ("The vertical frets read as time markers")
    const vOffsets = [-13, -9, -5, -2, 0, 1.5, 5, 9, 13];
    for (let dx of vOffsets) {
      const isCrown = Math.abs(dx) <= 2.2;
      let y = NECK_TOP;
      while (y < NECK_BOT) {
        const seg = random(32, 85);
        const y2 = Math.min(NECK_BOT, y + seg);
        const ym = (y + y2) * 0.5;
        const normY = 1.0 - (ym - NECK_TOP) / (NECK_BOT - NECK_TOP);

        let strGlow = 0;
        for (let s of STRINGS) {
          const d = Math.abs(ym - getStringY(s, fx));
          strGlow = Math.max(strGlow, Math.exp(-(d * d) / (2 * 45 * 45)));
        }

        let t = 0.16 + normY * 0.52 + strGlow * 0.24;
        if (isCrown) t = clamp01(t + 0.24);
        else if (Math.abs(dx) > 10) t *= 0.45;

        brush.set(isCrown ? "razor_wire" : "micro_hatch", specHex(t), isCrown ? 0.95 : 0.55);
        brush.line(fx + dx, y, fx + dx, y2);
        y = y2 + random(2, 8);
      }
    }

    // 5. Encroaching finger-grime whiskers overlapping the edges of the fret bevel
    for (let g = 0; g < 160; g++) {
      const gy = random(NECK_TOP + 6, NECK_BOT - 6);
      const normY = 1.0 - (gy - NECK_TOP) / (NECK_BOT - NECK_TOP);
      const side = random() < 0.5 ? -1 : 1;
      const gx1 = fx + side * (halfW + random(2, 10));
      const gx2 = fx + side * (halfW - random(2, 7));
      brush.set("razor_wire", grimeHex(0.15 + normY * 0.35, 0.3), 0.55);
      brush.line(gx1, gy, gx2, gy + random(-2.5, 2.5));
    }
  }
}

// ============================================================================
// 5. STRING CAST SHADOWS & THERMAL BOUNCE REFLECTIONS
// ============================================================================
function drawStringShadows() {
  for (let s of STRINGS) {
    const r = s.radius;
    // Deep occlusion shadow cast downward onto rosewood & frets
    for (let x = 0; x < 1200; x += 6) {
      const sy = getStringY(s, x);
      const shTop = sy + r * 0.55;
      const shBot = sy + r * 1.65;

      // Dark umbra lines
      for (let y = shTop; y < shBot; y += 2.4) {
        const u = (y - shTop) / (shBot - shTop);
        const w = (1.0 - Math.abs(u - 0.35)) * 1.15;
        brush.set("charcoal", "#020005", Math.max(0.35, w));
        brush.line(x, y, x + 7.5, y + random(-0.6, 0.6));
      }

      // Colored spectrogram thermal reflection below the shadow edge
      const refY = sy + r * 1.75 + random(-3, 5);
      const pluckBoost = s.idx >= 2 ? 0.16 * Math.exp(-Math.pow((x - PLUCK_X) / 260, 2)) : 0;
      const refT = clamp01(s.baseT * 0.72 + pluckBoost);
      brush.set("micro_hatch", specHex(refT), 0.6);
      brush.line(x, refY, x + 6.5, refY);
    }
  }
}

// ============================================================================
// 6. SIDEWAYS UNDER-SHIMMER & VIBRATIONAL ENVELOPES
// ============================================================================
function drawSidewaysUnderShimmer() {
  // Ghosted vibrational envelope of the plucked Low E string (and sympathetic A string)
  const eStr = STRINGS[3];
  for (let ghost = -1; ghost <= 1; ghost += 2) {
    for (let x = FRETS[0]; x < 1200; x += 4.5) {
      const env = Math.sin(((x - FRETS[0]) / (1200 - FRETS[0])) * Math.PI);
      const dy = ghost * (18 + 14 * env);
      const gy = getStringY(eStr, x) + dy;

      // Translucent violet-magma ghost windings
      const t = clamp01(0.24 + 0.38 * env);
      brush.set("shimmer_blur", specHex(t), 0.75);
      brush.line(x, gy - eStr.radius * 0.65, x + 14, gy - eStr.radius * 0.65);

      brush.set("micro_hatch", specHex(t + 0.18), 0.65);
      brush.line(x, gy - eStr.radius * 0.35, x + 3.5, gy + eStr.radius * 0.45);
    }
  }

  // Horizontal spectrogram smear ribbons sweeping sideways from the plucking region
  for (let i = 0; i < 240; i++) {
    const y = random(640, 1185);
    const normPluck = 1.0 - Math.min(1, Math.abs(y - PLUCK_Y) / 310);
    const xStart = PLUCK_X + random(-180, 90);
    const dir = random() < 0.68 ? 1 : -1;
    const len = random(85, 420) * (0.4 + 0.6 * normPluck);
    const xEnd = clamp01((xStart + dir * len) / 1200) * 1200;

    const t = clamp01(0.22 + normPluck * 0.56 + random(-0.08, 0.12));
    brush.set("shimmer_blur", specHex(t), random(0.55, 1.35));
    brush.line(xStart, y, xEnd, y + random(-4, 4));
  }
}

// ============================================================================
// 7. MACRO ROUNDWOUND BASS STRING RENDERER (DIRECTIONAL HATCHING & WINDINGS)
// ============================================================================
function drawWoundString(s) {
  const R = s.radius;
  const pitch = s.coilPitch;

  // 7A. Opaque dark core wash along the string path so background wood grain is fully occluded
  brush.noStroke();
  brush.wash("#05010a", 252);
  for (let x = 0; x < 1200; x += 24) {
    const sy = getStringY(s, x + 12);
    brush.rect(x, sy - R + 1, 25, R * 2 - 2, "corner");
  }
  brush.noWash();

  // 7B. Longitudinal directional flow hatching along the cylindrical contour of the string
  // (Flows horizontally from edge to edge, establishing 3D metallic volume & spectrogram glow)
  const vSteps = Math.round(R * 1.45);
  for (let step = -vSteps; step <= vSteps; step++) {
    const u = step / vSteps; // -1 (top edge) to +1 (bottom edge)
    const dy = u * (R - 0.8);

    // Cylindrical lighting profile: primary specular ridge around u = -0.36, core shadow around u = +0.42, bottom rim at u = +0.84
    const specDist = Math.abs(u - (-0.36));
    const specFactor = Math.exp(-(specDist * specDist) / (2 * 0.19 * 0.19));
    const shadowFactor = Math.exp(-Math.pow((u - 0.42) / 0.28, 2));
    const rimFactor = Math.exp(-Math.pow((u - 0.84) / 0.14, 2));

    let x = 0;
    while (x < 1200) {
      const seg = random(28, 64);
      const x2 = Math.min(1200, x + seg);
      const xm = (x + x2) * 0.5;

      const y1 = getStringY(s, x) + dy;
      const y2 = getStringY(s, x2) + dy;

      // Local spectrogram energy modulation (brighter over frets and near plucking finger)
      const fDist = fretProximity(xm);
      const fretBoost = 0.14 * Math.exp(-(fDist * fDist) / (2 * 38 * 38));
      const pDist = Math.hypot((xm - PLUCK_X) * 0.65, (y1 - PLUCK_Y));
      const pluckBoost = 0.26 * Math.exp(-(pDist * pDist) / (2 * 190 * 190));
      const waveMod = 0.05 * Math.sin(xm * 0.025 + s.idx * 1.7);

      let t = s.baseT + (s.peakT - s.baseT) * (0.35 + 0.65 * specFactor) - shadowFactor * 0.28 + rimFactor * 0.22;
      t = clamp01(t + fretBoost + pluckBoost + waveMod);
      if (shadowFactor > 0.65 && rimFactor < 0.2) {
        t = clamp01(s.shadowT + pluckBoost * 0.35);
      }

      const brushName = specFactor > 0.7 ? "razor_wire" : "micro_hatch";
      const weight = 0.55 + specFactor * 0.55;
      brush.set(brushName, specHex(t), weight);
      brush.line(x, y1, x2, y2);

      x = x2;
    }
  }

  // 7C. Individual Helical Winding Coils across the 1200px string
  // Rendered photographically through fine directional hatching along & across each winding
  const slant = pitch * 0.26; // Natural helical wrap angle of roundwound wire
  let coilIndex = 0;

  for (let xCoil = -pitch; xCoil < 1200 + pitch; xCoil += pitch) {
    coilIndex++;
    const xm = xCoil + pitch * 0.5;
    const yc = getStringY(s, xm);

    const fDist = fretProximity(xm);
    const fretBoost = 0.15 * Math.exp(-(fDist * fDist) / (2 * 34 * 34));
    const pDist = Math.hypot((xm - PLUCK_X) * 0.65, yc - PLUCK_Y);
    const pluckBoost = 0.28 * Math.exp(-(pDist * pDist) / (2 * 175 * 175));

    // Finger grime factor (heavier near frets and in finger-wear zones)
    const grimeNoise = noise(coilIndex * 0.18, s.idx * 10.3);
    const grimeAmount = clamp01((fDist < 75 ? 0.55 : 0.22) * grimeNoise + (grimeNoise > 0.68 ? 0.45 : 0));

    // 1. Deep helical groove between windings (curved spline following the 3D cylinder)
    const gxTop = xCoil - slant;
    const gxMid = xCoil - pitch * 0.12;
    const gxBot = xCoil + slant;

    brush.set("razor_wire", "#030106", 0.85);
    brush.spline([
      [gxTop, yc - R + 0.5, 0.5],
      [gxMid, yc - R * 0.15, 1.0],
      [gxBot, yc + R - 0.5, 0.5]
    ], 0.45);

    // Second dark shadow line on the trailing edge of the winding groove
    brush.set("micro_hatch", specHex(s.shadowT * 0.7), 0.65);
    brush.spline([
      [gxTop + 1.1, yc - R + 1.2, 0.4],
      [gxMid + 1.2, yc, 0.9],
      [gxBot + 1.1, yc + R - 1.2, 0.4]
    ], 0.45);

    // 2. Curved 3D contour strokes along the crown of this individual winding wire
    const cxTop = xCoil + pitch * 0.46 - slant;
    const cxMid = xCoil + pitch * 0.34;
    const cxBot = xCoil + pitch * 0.46 + slant;

    const midT = clamp01(s.baseT + 0.18 + fretBoost + pluckBoost - grimeAmount * 0.12);
    brush.set("micro_hatch", specHex(midT), 0.72);
    brush.spline([
      [cxTop, yc - R * 0.88, 0.4],
      [cxMid, yc - R * 0.12, 1.0],
      [cxBot * 0.5 + cxMid * 0.5, yc + R * 0.42, 0.5]
    ], 0.42);

    // 3. Fine longitudinal directional hatches bridging across the crown of this winding coil
    // (This creates the unmistakable woven metallic cylinder look of each roundwound coil)
    const sliceBands = [
      { u: -0.78, tMul: 0.68, w: 0.55 }, // Upper bevel
      { u: -0.54, tMul: 0.88, w: 0.72 }, // Upper specular shoulder
      { u: -0.34, tMul: 1.00, w: 0.98 }, // Primary blazing specular ridge
      { u: -0.14, tMul: 0.84, w: 0.75 }, // Lower specular shoulder
      { u:  0.10, tMul: 0.62, w: 0.65 }, // Mid cylindrical body
      { u:  0.38, tMul: 0.25, w: 0.65 }, // Core shadow belly
      { u:  0.64, tMul: 0.32, w: 0.60 }, // Lower shadow transition
      { u:  0.84, tMul: 0.72, w: 0.70 }  // Bottom reflected spectrogram rim
    ];

    for (let b of sliceBands) {
      const sy = yc + b.u * R;
      const tiltShift = b.u * slant - (1.0 - b.u * b.u) * pitch * 0.12;
      const x1 = xCoil + pitch * 0.18 + tiltShift;
      const x2 = xCoil + pitch * 0.84 + tiltShift;

      let localT;
      if (b.u > 0.25 && b.u < 0.70) {
        localT = clamp01(s.shadowT + pluckBoost * 0.25);
      } else if (b.u >= 0.70) {
        localT = clamp01(s.rimT + fretBoost * 0.8 + pluckBoost * 1.1);
      } else {
        localT = clamp01(s.baseT + (s.peakT - s.baseT) * b.tMul + fretBoost + pluckBoost - grimeAmount * 0.14);
      }

      const isSpec = Math.abs(b.u - (-0.34)) < 0.08;
      brush.set(isSpec ? "razor_wire" : "micro_hatch", specHex(localT), b.w);
      brush.line(x1, sy, x2, sy);

      // Extra hot core bead right on the specular ridge of each winding
      if (isSpec) {
        const hotT = clamp01(localT + 0.11);
        brush.set("razor_wire", specHex(hotT), 0.85);
        brush.line(x1 + pitch * 0.12, sy - 0.7, x2 - pitch * 0.12, sy - 0.7);
      }
    }

    // 4. Photographic finger grime crust lodged inside the winding crevices
    if (grimeAmount > 0.26) {
      const gCount = Math.floor(grimeAmount * 5) + 1;
      for (let g = 0; g < gCount; g++) {
        const gu = random(-0.65, 0.65);
        const gy = yc + gu * R;
        const gx = xCoil + gu * slant + random(-1.5, 2.2);
        const gt = clamp01(s.baseT * 0.65 + 0.08);
        brush.set("micro_hatch", grimeHex(gt, 0.35), random(0.55, 0.95));
        brush.line(gx - 2.2, gy + random(-1.2, 1.2), gx + 2.8, gy + random(-1.2, 1.2));
      }
    }
  }
}

// ============================================================================
// 8. BLURRED PLUCKING FINGERTIP & SIDEWAYS COLOUR SHIMMER
// ============================================================================
function drawPluckingFingertipAndShimmer() {
  const tipX = PLUCK_X;
  const tipTopY = 852;
  const tipBotY = 1200;

  // 8A. Soft motion-blurred translucent spectrogram washes for the fingertip & sideways trail
  brush.noStroke();
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.48, 0.18);

  const blurPasses = [
    { dx: 155, w: 230, topY: 878, col: specHex(0.28), op: 65 },
    { dx: -95, w: 210, topY: 882, col: specHex(0.34), op: 60 },
    { dx: 85,  w: 195, topY: 866, col: specHex(0.48), op: 80 },
    { dx: -40, w: 180, topY: 862, col: specHex(0.56), op: 85 },
    { dx: 25,  w: 165, topY: 856, col: specHex(0.68), op: 95 },
    { dx: 0,   w: 145, topY: 852, col: specHex(0.78), op: 105 }
  ];

  for (let p of blurPasses) {
    brush.fill(p.col, p.op);
    const cx = tipX + p.dx;
    const hw = p.w * 0.5;
    brush.beginShape(0.45);
    brush.vertex(cx - hw * 1.35, 1200);
    brush.vertex(cx - hw * 1.08, 1040);
    brush.vertex(cx - hw * 0.72, p.topY + 35);
    brush.vertex(cx, p.topY);
    brush.vertex(cx + hw * 0.78, p.topY + 30);
    brush.vertex(cx + hw * 1.15, 1030);
    brush.vertex(cx + hw * 1.48, 1200);
    brush.endShape(CLOSE);
  }
  brush.noFill();

  // 8B. Anatomical fingertip volume & horizontally smeared epidermal ridges (fingerprint whorls)
  // Concentric fingerprint arches centered around the distal pad (tipX, 955), smeared sideways
  const whorlCenterY = 965;
  for (let r = 8; r < 235; r += 3.1) {
    const normR = r / 235;
    const aStart = -168;
    const aEnd = -12;
    const stepA = 14;

    for (let a = aStart; a < aEnd; a += stepA) {
      const a1 = a * Math.PI / 180;
      const a2 = (a + stepA + 4) * Math.PI / 180;

      // Elliptical finger dome mapping
      const rx = 88 + normR * 42;
      const ry = 112 + normR * 35;

      const x1 = tipX + Math.cos(a1) * rx * (0.28 + 0.72 * normR);
      const y1 = whorlCenterY + Math.sin(a1) * ry * (0.28 + 0.72 * normR);
      const x2 = tipX + Math.cos(a2) * rx * (0.28 + 0.72 * normR);
      const y2 = whorlCenterY + Math.sin(a2) * ry * (0.28 + 0.72 * normR);

      if (y1 < tipTopY - 8 || y1 > 1200) continue;

      // Subsurface scattering spectrogram gradient: blazing yellow-orange at the string contact callus,
      // cooling through magma red and crimson to deep ultraviolet at the base and sides of the finger
      const dCallus = Math.hypot((x1 - tipX) * 0.85, (y1 - (tipTopY + 32)) * 1.1);
      const callusHeat = Math.exp(-(dCallus * dCallus) / (2 * 78 * 78));
      const edgeDark = Math.pow(Math.abs(x1 - tipX) / 145, 1.5);

      const ridgeMod = 0.08 * Math.sin(r * 1.35);
      const t = clamp01(0.24 + (1.0 - normR) * 0.34 + callusHeat * 0.42 - edgeDark * 0.26 + ridgeMod);

      // Draw crisp epidermal ridge segment
      brush.set("micro_hatch", specHex(t), 0.75 + callusHeat * 0.45);
      brush.line(x1, y1, x2, y2);

      // Sideways motion-blur echo of the ridge
      const smearShift = random(18, 95) * (random() < 0.72 ? 1 : -0.65);
      brush.set("coil_shade", specHex(clamp01(t - 0.12)), 0.55);
      brush.line(x1, y1, x2 + smearShift, y2 + random(-2.5, 2.5));
    }
  }

  // 8C. Aggressive Sideways Colour Shimmer (Spectrogram smear sweeping left and right from the fingertip & string)
  for (let i = 0; i < 420; i++) {
    const sy = random(tipTopY - 22, 1196);
    const distFromCallus = Math.abs(sy - (tipTopY + 36));
    const callusFactor = Math.exp(-(distFromCallus * distFromCallus) / (2 * 85 * 85));

    // Originate inside or near the fingertip pad and smear sideways
    const dir = random() < 0.74 ? 1 : -1;
    const x0 = tipX + random(-75, 75);
    const smearLen = random(65, 440) * (0.35 + 0.65 * callusFactor + random(0, 0.3));
    const x1 = clamp01((x0 + dir * smearLen) / 1200) * 1200;

    // Color transitions from hot yellow/orange near the finger to magma red and violet in the tail
    const segs = 4;
    for (let s = 0; s < segs; s++) {
      const f0 = s / segs;
      const f1 = (s + 1) / segs;
      const sx0 = x0 + (x1 - x0) * f0;
      const sx1 = x0 + (x1 - x0) * f1;
      const waveY = Math.sin(sx0 * 0.02 + i) * 2.5;

      const baseHeat = 0.34 + callusFactor * 0.60;
      const decayT = clamp01(baseHeat * (1.0 - f0 * 0.62) + random(-0.05, 0.05));

      const bName = s === 0 && callusFactor > 0.55 ? "razor_wire" : (random() < 0.45 ? "shimmer_blur" : "micro_hatch");
      const w = bName === "shimmer_blur" ? random(0.6, 1.3) : random(0.55, 1.05);

      brush.set(bName, specHex(decayT), w);
      brush.line(sx0, sy + waveY, sx1, sy + waveY + random(-1.8, 1.8));
    }
  }

  // 8D. Incandescent mechanical release flare where the fingertip callus snaps off the Low E string
  for (let k = 0; k < 110; k++) {
    const fx = tipX + random(-65, 95);
    const fy = tipTopY + random(-8, 42);
    const len = random(18, 115);
    const d = Math.hypot((fx - tipX) * 0.7, fy - (tipTopY + 14));
    const t = clamp01(0.98 - d / 120 + random(-0.04, 0.04));

    brush.set(k % 2 === 0 ? "razor_wire" : "micro_hatch", specHex(t), random(0.65, 1.25));
    brush.line(fx - len * 0.3, fy, fx + len * 0.7, fy + random(-2.2, 2.2));
  }

  // Fine harmonic spray dust dispersing sideways from the pluck
  for (let p = 0; p < 85; p++) {
    const px = tipX + random(-240, 380);
    const py = random(820, 1180);
    const d = Math.hypot((px - tipX) * 0.4, py - PLUCK_Y);
    const t = clamp01(0.88 - d / 340);
    brush.set("grime_dust", specHex(t), random(0.45, 0.95));
    brush.line(px, py, px + random(15, 55), py + random(-4, 4));
  }
}

// ============================================================================
// 9. SPECTROGRAM TIME-MARKER TICKS & PEAK SPECULAR TRANSIENTS
// ============================================================================
function drawSpectrogramTransients() {
  // Crisp time-marker calibration ticks along the top and bottom neck bevels
  for (let x = 15; x < 1200; x += 15) {
    const isFret = fretProximity(x) < 8;
    const isMajor = x % 75 === 0 || isFret;
    const tickLen = isFret ? 28 : (isMajor ? 16 : 8);
    const tTop = isFret ? 0.96 : (isMajor ? 0.72 : 0.42);
    const tBot = isFret ? 0.86 : (isMajor ? 0.55 : 0.28);

    // Top bevel ticks
    brush.set("razor_wire", specHex(tTop), isFret ? 1.05 : 0.55);
    brush.line(x, NECK_TOP - 2, x, NECK_TOP - 2 - tickLen);

    // Bottom bevel ticks
    brush.set("razor_wire", specHex(tBot), isFret ? 1.05 : 0.55);
    brush.line(x, NECK_BOT + 2, x, NECK_BOT + 2 + tickLen);
  }

  // Horizontal neck border hairline
  brush.set("razor_wire", specHex(0.62), 0.75);
  brush.line(0, NECK_TOP, 1200, NECK_TOP);
  brush.set("razor_wire", specHex(0.38), 0.75);
  brush.line(0, NECK_BOT, 1200, NECK_BOT);

  // Intense transient contact glints where each of the 4 strings crosses the 3 vertical fret wires
  for (let fx of FRETS) {
    for (let s of STRINGS) {
      const sy = getStringY(s, fx);
      const R = s.radius;
      const specY = sy - R * 0.34;

      // Vertical transient flare on fret crown above and below the string
      brush.set("razor_wire", specHex(clamp01(s.peakT + 0.06)), 1.05);
      brush.line(fx, sy - R - 18, fx, sy - R - 2);
      brush.line(fx, sy + R + 2, fx, sy + R + 18);

      // Horizontal white-hot node glint on the string winding directly over the fret
      for (let dx = -22; dx <= 22; dx += 4.5) {
        const falloff = 1.0 - Math.abs(dx) / 26;
        const t = clamp01(s.peakT + 0.08 * falloff);
        brush.set("razor_wire", specHex(t), 0.75 + 0.45 * falloff);
        brush.line(fx + dx - 1.8, specY, fx + dx + 1.8, specY);
      }
    }
  }
}

