// Helper: sanitize point list to prevent zero-length segments in splines/polygons
function cleanPts(pts, minDist = 0.6) {
  if (!pts || pts.length === 0) return [];
  let out = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let dx = pts[i][0] - out[out.length - 1][0];
    let dy = pts[i][1] - out[out.length - 1][1];
    if (Math.hypot(dx, dy) >= minDist) {
      out.push(pts[i]);
    }
  }
  return out;
}

// Helper: opaque mineral wash polygon
function polyWash(pts, col, alpha = 255) {
  let c = cleanPts(pts);
  if (c.length < 3) return null;
  let p = new brush.Polygon(c);
  p.wash(col, alpha);
  return p;
}

// Helper: translucent watercolor fill polygon (used for butter-tea steam)
function polyFill(pts, col, alpha = 90, bleed = 0.08, tex = 0.35) {
  let c = cleanPts(pts);
  if (c.length < 3) return null;
  let p = new brush.Polygon(c);
  p.fill(col, alpha, bleed, tex);
  return p;
}

// Helper: safe spline stroke with brush.set always called first
function strokeSpline(pts, col = PAL.GOLD_OCHRE, weight = 0.42, curvature = 0.25, close = false, brushName = "rotring") {
  let c = cleanPts(pts);
  if (c.length < 2) return;
  if (close) {
    let dx = c[0][0] - c[c.length - 1][0];
    let dy = c[0][1] - c[c.length - 1][1];
    if (Math.hypot(dx, dy) >= 0.6) c.push([c[0][0], c[0][1]]);
  }
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  if (c.length === 2) {
    brush.line(c[0][0], c[0][1], c[1][0], c[1][1]);
  } else {
    brush.spline(c, curvature);
  }
}

// Helper: layered opaque shape + optional mineral hatch + gold-ochre contour
function mineralShape(pts, washCol, washAlpha = 250, goldWeight = 0.42, curvature = 0.22, hatchCfg = null, goldCol = PAL.GOLD_OCHRE) {
  let p = polyWash(pts, washCol, washAlpha);
  if (p && hatchCfg) {
    brush.hatchStyle(hatchCfg.brush || "2H", hatchCfg.col, hatchCfg.weight || 0.28);
    p.hatch(hatchCfg.dist || 5, hatchCfg.angle || 35, { rand: hatchCfg.rand || 0.06 });
    brush.noHatch();
  }
  if (goldWeight > 0) {
    strokeSpline(pts, goldCol, goldWeight, curvature, true, "rotring");
  }
  return p;
}

// Helper: generate ellipse/circle polygon points
function ellipsePts(cx, cy, rx, ry, n = 36, rotDeg = 0, wobble = 0) {
  let pts = [];
  let rad = rotDeg * Math.PI / 180;
  let cr = Math.cos(rad), sr = Math.sin(rad);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let rMod = wobble > 0 ? 1 + (noise(cx * 0.02 + Math.cos(a) * 1.5, cy * 0.02 + Math.sin(a) * 1.5) - 0.5) * wobble : 1;
    let lx = Math.cos(a) * rx * rMod;
    let ly = Math.sin(a) * ry * rMod;
    pts.push([cx + lx * cr - ly * sr, cy + lx * sr + ly * cr]);
  }
  return pts;
}

// Helper: generate arc polygon or open spline points
function arcPts(cx, cy, rx, ry, startDeg, endDeg, n = 24) {
  let pts = [];
  for (let i = 0; i <= n; i++) {
    let a = (startDeg + (endDeg - startDeg) * (i / n)) * Math.PI / 180;
    pts.push([cx + Math.cos(a) * rx, cy + Math.sin(a) * ry]);
  }
  return pts;
}

// Helper: draw a Tibetan cloud scroll cluster (used for registers, landscape & steam)
function drawCloudCluster(cx, cy, scaleX, scaleY, mainCol, midCol, lightCol, goldCol = PAL.GOLD_OCHRE, isSteam = false) {
  let lobes = [
    { dx: -38, dy: 12, rx: 28, ry: 20 },
    { dx: 38, dy: 12, rx: 28, ry: 20 },
    { dx: -18, dy: -6, rx: 26, ry: 22 },
    { dx: 18, dy: -6, rx: 26, ry: 22 },
    { dx: 0, dy: -16, rx: 24, ry: 20 },
    { dx: 0, dy: 16, rx: 42, ry: 16 }
  ];
  // Base shadow lobes
  for (let l of lobes) {
    let pts = ellipsePts(cx + l.dx * scaleX, cy + l.dy * scaleY, l.rx * scaleX, l.ry * scaleY, 24, 0, 0.08);
    if (isSteam) {
      polyFill(pts, mainCol, 95, 0.12, 0.3);
    } else {
      polyWash(pts, mainCol, 245);
    }
  }
  // Midtone inner billows
  for (let l of lobes) {
    let pts = ellipsePts(cx + l.dx * scaleX, cy + (l.dy - 2) * scaleY, l.rx * 0.78 * scaleX, l.ry * 0.78 * scaleY, 20, 0, 0.05);
    if (isSteam) {
      polyFill(pts, midCol, 115, 0.08, 0.25);
    } else {
      polyWash(pts, midCol, 240);
    }
  }
  // Bright core highlights
  for (let i = 0; i < 5; i++) {
    let l = lobes[i];
    let pts = ellipsePts(cx + l.dx * scaleX, cy + (l.dy - 4) * scaleY, l.rx * 0.52 * scaleX, l.ry * 0.52 * scaleY, 16, 0, 0.03);
    polyWash(pts, lightCol, isSteam ? 175 : 230);
  }
  // Gold-ochre spiral cloud-volute contours
  for (let i = 0; i < 5; i++) {
    let l = lobes[i];
    let lx = cx + l.dx * scaleX;
    let ly = cy + l.dy * scaleY;
    let rx = l.rx * scaleX;
    let ry = l.ry * scaleY;
    let outerArc = arcPts(lx, ly, rx, ry, 160, 395, 18);
    strokeSpline(outerArc, goldCol, 0.42, 0.25, false, "rotring");
    // Inner volute spiral curl
    let spiral = [];
    for (let s = 0; s <= 16; s++) {
      let t = s / 16;
      let ang = (200 + t * 420) * Math.PI / 180;
      let radScale = (1 - t * 0.72) * 0.65;
      spiral.push([lx + Math.cos(ang) * rx * radScale, ly + Math.sin(ang) * ry * radScale]);
    }
    strokeSpline(spiral, goldCol, 0.32, 0.25, false, "rotring");
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4279);
  noiseSeed(4279);
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // 1. DEEP ABYSSAL GROUND & INNER LAPIS SKY
  drawBackgroundAndSky();

  // 2. LAYERED MALACHITE GREEN MINERAL LANDSCAPE
  drawMalachiteLandscape();

  // 3. CENTRAL MANDORLA, RUG THRONE & BACKGROUND BUTTER-TEA STEAM AUREOLE
  drawThroneAndMandorla();
  drawButterTeaSteamAureoleBack();

  // 4. CENTRAL ELDERLY WOMAN KNITTING (HYPERREAL)
  drawElderlyWoman();

  // 5. FOREGROUND BUTTER-TEA BOWL & ASCENDING STEAM TENDRILS
  drawButterTeaBowlAndFrontSteam();

  // 6. FOUR HIERARCHICAL REGISTERS (THERMOS, RADIO, PRAYER BEADS, SLEEPING DOG)
  drawRegisterThermos(268, 282);
  drawRegisterRadio(932, 282);
  drawRegisterPrayerBeads(268, 825);
  drawRegisterSleepingDog(932, 825);

  // 7. PAINTED SILK BROCADE MOUNT BORDER
  drawSilkBrocadeBorder();

  noLoop();
}

