function drawBackgroundAndSky() {
  // Full canvas abyssal lapis base
  polyWash([[0, 0], [1200, 0], [1200, 1200], [0, 1200]], PAL.LAPIS_ABYSS, 255);

  // Inner painting window (x: 136..1064, y: 116..1034)
  polyWash([[136, 116], [1064, 116], [1064, 1034], [136, 1034]], PAL.LAPIS_DEEP, 255);

  // Graded lapis lazuli strata in the upper ether
  let bands = [
    { y1: 116, y2: 280, col: PAL.LAPIS_ABYSS, a: 210 },
    { y1: 240, y2: 450, col: PAL.LAPIS_DEEP, a: 190 },
    { y1: 400, y2: 620, col: PAL.LAPIS_DARK, a: 210 },
    { y1: 550, y2: 700, col: PAL.LAPIS_MID, a: 185 }
  ];
  for (let b of bands) {
    polyWash([[136, b.y1], [1064, b.y1], [1064, b.y2], [136, b.y2]], b.col, b.a);
  }

  // Fine lapis mineral cross-hatching and gold-dust constellations in the upper sky
  brush.hatchStyle("2H", PAL.LAPIS_MID, 0.28);
  let skyPoly = new brush.Polygon([[140, 120], [1060, 120], [1060, 650], [140, 650]]);
  skyPoly.hatch(9, 25, { rand: 0.08 });
  brush.hatchStyle("2H", PAL.LAPIS_ABYSS, 0.28);
  skyPoly.hatch(11, -25, { rand: 0.08 });
  brush.noHatch();

  // Golden celestial rays & subtle clouds in the upper lapis sky
  brush.set("rotring", PAL.GOLD_DEEP, 0.22);
  for (let i = 0; i < 48; i++) {
    let ang = (195 + (i / 47) * 150) * Math.PI / 180;
    let r1 = 285, r2 = 520 + (i % 3) * 45;
    let x1 = 600 + Math.cos(ang) * r1;
    let y1 = 520 + Math.sin(ang) * r1;
    let x2 = 600 + Math.cos(ang) * r2;
    let y2 = 520 + Math.sin(ang) * r2;
    if (x2 > 142 && x2 < 1058 && y2 > 122 && y2 < 680) {
      brush.line(x1, y1, x2, y2);
    }
  }

  // Distant lapis-and-gold scrolling ether clouds
  drawCloudCluster(435, 168, 0.72, 0.55, PAL.LAPIS_DARK, PAL.LAPIS_MID, PAL.LAPIS_BRIGHT, PAL.GOLD_OCHRE, false);
  drawCloudCluster(765, 168, 0.72, 0.55, PAL.LAPIS_DARK, PAL.LAPIS_MID, PAL.LAPIS_BRIGHT, PAL.GOLD_OCHRE, false);
}

// ============================================================================
// 2. LAYERED MALACHITE GREEN MINERAL LANDSCAPE
// ============================================================================
function drawMalachiteLandscape() {
  // Helper to build a Tibetan mineral crag/mountain peak with layered malachite strata
  function drawCrag(cx, baseY, w, h, skew = 0) {
    let layers = [
      { scale: 1.00, col: PAL.MALA_ABYSS },
      { scale: 0.88, col: PAL.MALA_DEEP },
      { scale: 0.74, col: PAL.MALA_DARK },
      { scale: 0.58, col: PAL.MALA_MID },
      { scale: 0.42, col: PAL.MALA_BRIGHT },
      { scale: 0.26, col: PAL.MALA_VIVID },
      { scale: 0.13, col: PAL.MALA_LIGHT }
    ];
    for (let li = 0; li < layers.length; li++) {
      let L = layers[li];
      let cw = w * (0.45 + 0.55 * L.scale);
      let ch = h * L.scale;
      let shiftX = skew * (1 - L.scale) * 28;
      let pts = [];
      let steps = 14;
      for (let s = 0; s <= steps; s++) {
        let t = s / steps; // 0 (left base) -> 0.5 (peak) -> 1 (right base)
        let x = cx + shiftX + (t - 0.5) * cw;
        let arch = Math.sin(t * Math.PI);
        let jag = Math.sin(t * Math.PI * 5 + li) * 8 * arch;
        let y = baseY - Math.pow(arch, 0.75) * ch + jag;
        pts.push([x, y]);
      }
      pts.push([cx + cw * 0.5, baseY + 15]);
      pts.push([cx - cw * 0.5, baseY + 15]);
      polyWash(pts, L.col, 250);

      // Gold-ochre contour lines along each mineral stratum
      let ridgePts = pts.slice(0, steps + 1);
      strokeSpline(ridgePts, li >= 4 ? PAL.GOLD_BRIGHT : PAL.GOLD_OCHRE, li === 0 ? 0.5 : 0.32, 0.2, false, "rotring");
    }
    // Vertical mineral cleavage lines in gold-ochre & celadon
    for (let v = -3; v <= 3; v++) {
      let vx = cx + v * (w * 0.11);
      let vyTop = baseY - h * (1 - Math.abs(v) * 0.22) + 12;
      strokeSpline([
        [vx + skew * 8, vyTop],
        [vx + v * 5, (vyTop + baseY) * 0.5],
        [vx + v * 10, baseY]
      ], PAL.GOLD_OCHRE, 0.28, 0.2, false, "rotring");
    }
  }

  // Far horizon malachite crags
  drawCrag(255, 665, 240, 155, -0.4);
  drawCrag(430, 650, 220, 140, -0.2);
  drawCrag(770, 650, 220, 140, 0.2);
  drawCrag(945, 665, 240, 155, 0.4);

  // Midground rolling malachite hills
  let hills = [
    { cx: 310, cy: 745, rx: 220, ry: 95 },
    { cx: 890, cy: 745, rx: 220, ry: 95 },
    { cx: 600, cy: 755, rx: 340, ry: 105 },
    { cx: 250, cy: 890, rx: 190, ry: 110 },
    { cx: 950, cy: 890, rx: 190, ry: 110 },
    { cx: 600, cy: 960, rx: 490, ry: 135 }
  ];

  for (let h of hills) {
    let strata = [
      { dy: 0, s: 1.0, col: PAL.MALA_ABYSS },
      { dy: 6, s: 0.94, col: PAL.MALA_DEEP },
      { dy: 12, s: 0.86, col: PAL.MALA_DARK },
      { dy: 18, s: 0.76, col: PAL.MALA_MID },
      { dy: 24, s: 0.62, col: PAL.MALA_BRIGHT },
      { dy: 30, s: 0.44, col: PAL.MALA_VIVID }
    ];
    for (let st of strata) {
      let pts = arcPts(h.cx, h.cy + st.dy, h.rx * st.s, h.ry * st.s, 180, 360, 24);
      pts.push([h.cx + h.rx * st.s, 1034]);
      pts.push([h.cx - h.rx * st.s, 1034]);
      polyWash(pts, st.col, 245);
    }
    // Hatching on hills for mineral pigment granulation
    let topArc = arcPts(h.cx, h.cy, h.rx, h.ry, 185, 355, 24);
    strokeSpline(topArc, PAL.GOLD_OCHRE, 0.45, 0.25, false, "rotring");
    let secondArc = arcPts(h.cx, h.cy + 10, h.rx * 0.92, h.ry * 0.9, 190, 350, 20);
    strokeSpline(secondArc, PAL.MALA_LIGHT, 0.3, 0.25, false, "cpencil");
  }

  // Stylized Tibetan grass tufts & tiny cinnabar-and-gold alpine blossoms on foreground meadow
  let tuftPositions = [
    [415, 705], [785, 705], [380, 760], [820, 760],
    [435, 920], [765, 920], [490, 975], [710, 975],
    [395, 995], [805, 995]
  ];
  for (let [tx, ty] of tuftPositions) {
    for (let b = -3; b <= 3; b++) {
      let bx = tx + b * 4;
      let by = ty - 14 + Math.abs(b) * 2.5;
      strokeSpline([[tx + b * 1.5, ty], [tx + b * 3, ty - 7], [bx, by]], PAL.MALA_PALE, 0.35, 0.2, false, "rotring");
      strokeSpline([[tx + b * 1.5, ty], [tx + b * 3, ty - 7], [bx, by]], PAL.GOLD_OCHRE, 0.25, 0.2, false, "rotring");
    }
    // Tiny cinnabar jewel-blossom tips
    let flPts = ellipsePts(tx, ty - 16, 4.5, 4.5, 10);
    polyWash(flPts, PAL.CINN_VIVID, 250);
    strokeSpline(flPts, PAL.GOLD_BRIGHT, 0.3, 0.2, true, "rotring");
  }
}

