    { x: 512, y: 245, sx: 0.95, sy: 0.85 },
    { x: 688, y: 245, sx: 0.95, sy: 0.85 },
    // Crown apex aureole arch
    { x: 600, y: 222, sx: 1.15, sy: 0.92 }
  ];

  for (let st of stations) {
    drawCloudCluster(
      st.x, st.y, st.sx, st.sy,
      PAL.STEAM_WARM, PAL.STEAM_CREAM, "#FFFFFF",
      PAL.GOLD_OCHRE, true
    );
  }

  // Continuous golden-and-cream vapor ribbons weaving through the aureole
  for (let side of [-1, 1]) {
    for (let strand = 0; strand < 4; strand++) {
      let ribbon = [];
      for (let step = 0; step <= 28; step++) {
        let t = step / 28; // 0 (bottom) -> 1 (crown)
        let ang = (90 - t * 90) * Math.PI / 180;
        let radX = 248 - t * 45 + Math.sin(t * Math.PI * 5 + strand) * 22;
        let radY = 330;
        let rx = 600 + side * (Math.cos(ang * 0.4) * radX * (1 - Math.pow(t, 3.2) * 0.92));
        let ry = 820 - t * 600 + Math.cos(t * Math.PI * 4 + strand) * 14;
        ribbon.push([rx, ry]);
      }
      strokeSpline(ribbon, PAL.STEAM_CREAM, 0.85, 0.35, false, "cpencil");
      strokeSpline(ribbon, PAL.GOLD_BRIGHT, 0.35, 0.35, false, "rotring");
    }
  }
}

