    let cap = ellipsePts(nx, ny, 6.5, 6.5, 16);
    mineralShape(cap, PAL.MALA_VIVID, 255, 0.4, 0.2, null, PAL.GOLD_BRIGHT);
  }

  // Active wool loops along the needle shafts
  for (let side of [-1, 1]) {
    for (let st = 0; st < 11; st++) {
      let t = 0.42 + st * 0.048;
      let sx = (side === -1 ? 458 : 742) * (1 - t) + (side === -1 ? 608 : 592) * t;
      let sy = 566 * (1 - t) + 626 * t;
      let loopPts = ellipsePts(sx, sy, 2.8, 5.2, 12, side * 22);
      polyWash(loopPts, st % 2 === 0 ? PAL.CINN_VIVID : PAL.CINN_LIGHT, 255);
      strokeSpline(loopPts, PAL.GOLD_OCHRE, 0.28, 0.2, true, "rotring");
    }
  }

  // Helper to render each hyperreal hand with dorsal veins, tendons & chapped knuckles
  function drawHyperrealHand(side) {
    // Dorsal hand plate (metacarpal back of hand)
    let handBack = [
      [600 + side * 98, 614],
      [600 + side * 66, 598],
      [600 + side * 56, 636],
      [600 + side * 74, 658],
      [600 + side * 104, 648]
    ];
    mineralShape(handBack, PAL.SKIN_DARK, 255, 0.45, 0.22, null, PAL.GOLD_OCHRE);
    polyWash([
      [600 + side * 94, 616],
      [600 + side * 68, 603],
      [600 + side * 60, 634],
      [600 + side * 74, 652],
      [600 + side * 98, 644]
    ], PAL.SKIN_MID, 245);

    // Prominent dorsal blue-lapis veins & pale extensor tendons on back of hand
    for (let v = 0; v < 3; v++) {
      let vx1 = 600 + side * 96;
      let vy1 = 626 + v * 7;
      let vx2 = 600 + side * (66 + v * 4);
      let vy2 = 606 + v * 13;
      strokeSpline([[vx1, vy1], [(vx1 + vx2) * 0.5, (vy1 + vy2) * 0.5 - 2], [vx2, vy2]], PAL.LAPIS_MID, 0.45, 0.25, false, "cpencil");
      strokeSpline([[vx1, vy1 - 1.5], [vx2, vy2 - 1.5]], PAL.SKIN_HIGHLIGHT, 0.35, 0.25, false, "cpencil");
      strokeSpline([[vx1, vy1], [vx2, vy2]], PAL.GOLD_OCHRE, 0.22, 0.25, false, "rotring");
    }

    // Five anatomical fingers (Index, Middle, Ring, Little, Thumb)
    // Each finger defined by [MCP knuckle, PIP joint, DIP joint, Tip] + width
    let fingers = [
      // Little finger
      {
        joints: [
          [600 + side * 76, 650],
          [600 + side * 54, 658],
          [600 + side * 40, 656],
          [600 + side * 32, 650]
        ],
        w: 5.5
      },
      // Ring finger
      {
        joints: [
          [600 + side * 72, 636],
          [600 + side * 46, 645],
          [600 + side * 30, 642],
          [600 + side * 22, 634]
        ],
        w: 6.2
      },
      // Middle finger
      {
        joints: [
          [600 + side * 68, 620],
          [600 + side * 40, 629],
          [600 + side * 24, 626],
          [600 + side * 16, 618]
        ],
        w: 6.6
      },
      // Index finger (Right index raised slightly at y=590 to tension the cinnabar yarn!)
      {
        joints: side === 1 ? [
          [664, 604],
          [644, 586],
          [626, 588],
          [614, 598]
        ] : [
          [536, 604],
          [562, 608],
          [580, 613],
          [591, 618]
        ],
        w: 6.5
      },
      // Thumb stabilizing needle in front
      {
        joints: [
          [600 + side * 78, 618],
          [600 + side * 54, 616],
          [600 + side * 36, 621],
          [600 + side * 24, 624]
        ],
        w: 7.0
      }
    ];

    for (let f of fingers) {
      let J = f.joints;
      let w = f.w;
      // Build finger polygon around joint spine
      let upperEdge = [], lowerEdge = [];
      for (let i = 0; i < J.length; i++) {
        let taper = 1 - i * 0.14;
        // Swell slightly at MCP (i=0) and PIP (i=1) joints for arthritic/aged knuckles
        let swell = (i === 0 || i === 1) ? 1.25 : 1.0;
        let cw = w * taper * swell;
        upperEdge.push([J[i][0], J[i][1] - cw]);
        lowerEdge.unshift([J[i][0], J[i][1] + cw]);
      }
      let fPoly = [...upperEdge, [J[3][0] - side * w * 0.6, J[3][1]], ...lowerEdge];
      mineralShape(fPoly, PAL.SKIN_MID, 255, 0.42, 0.25, null, PAL.GOLD_OCHRE);

      // Dorsal finger highlight strip & shadow underside
      strokeSpline(upperEdge, PAL.SKIN_LIGHT, 0.55, 0.25, false, "cpencil");
      strokeSpline(lowerEdge, PAL.SKIN_DEEP, 0.45, 0.25, false, "rotring");
      strokeSpline(fPoly, PAL.GOLD_OCHRE, 0.38, 0.25, true, "rotring");

      // HYPERREAL CHAPPED KNUCKLES at MCP (i=0), PIP (i=1) & DIP (i=2)
      for (let jIdx = 0; jIdx < 3; jIdx++) {
        let [kx, ky] = J[jIdx];
        let kr = (jIdx === 0 ? w * 1.15 : (jIdx === 1 ? w * 1.05 : w * 0.82));
        // Raw reddish-cinnabar chapped skin patch on the knuckle
        polyWash(ellipsePts(kx, ky, kr, kr * 0.85, 16), PAL.CHAP_RED, 215);
        polyWash(ellipsePts(kx, ky - 0.8, kr * 0.72, kr * 0.6, 14), PAL.CHAP_ROSE, 230);

        // Concentric transverse skin folds & dry chapped fissures across every knuckle
        for (let cr = -2; cr <= 2; cr++) {
          let cyOff = cr * (kr * 0.28);
          let spanX = kr * (1 - Math.abs(cr) * 0.22);
          let crease = [
            [kx - spanX * 0.4, ky + cyOff - spanX * 0.6],
            [kx + side * 1.5, ky + cyOff],
            [kx - spanX * 0.4, ky + cyOff + spanX * 0.6]
          ];
          strokeSpline(crease, PAL.CHAP_DARK, 0.3, 0.25, false, "rotring");
          strokeSpline(crease.map(p => [p[0] + 0.8, p[1] + 0.5]), PAL.GOLD_OCHRE, 0.22, 0.25, false, "rotring");
          // Dry pale flaky skin specs on the chapped knuckle ridge
          strokeSpline([
            [kx - 1.5, ky + cyOff - 0.5],
            [kx + 1.5, ky + cyOff + 0.5]
          ], PAL.CHAP_FLAKE, 0.28, 0.1, false, "rotring");
        }
      }

      // Fingernail with pale lunula at tip J[3]
      let [tx, ty] = J[3];
      let nailPts = ellipsePts(tx - side * 1.5, ty - 1, w * 0.52, w * 0.38, 14);
      polyWash(nailPts, PAL.SKIN_HIGHLIGHT, 250);
      polyWash(ellipsePts(tx + side * 0.5, ty - 1, w * 0.22, w * 0.28, 10), PAL.SKIN_SPECULAR, 250);
      strokeSpline(nailPts, PAL.GOLD_OCHRE, 0.28, 0.2, true, "rotring");
    }
  }

  drawHyperrealHand(-1);
  drawHyperrealHand(1);

  // Working Cinnabar Yarn Strand stretching from Yarn Ball -> over Right Index Finger -> Needles
  let yarnStrandPath = [
    [562, 766], [585, 735], [618, 695], [638, 650],
    [646, 584], // Loops over top of right index PIP joint
    [626, 586], [614, 598], [600, 623]
  ];
  strokeSpline(yarnStrandPath, PAL.CINN_DARK, 1.15, 0.3, false, "rotring");
  strokeSpline(yarnStrandPath, PAL.CINN_VIVID, 0.75, 0.3, false, "rotring");
  strokeSpline(yarnStrandPath, PAL.GOLD_OCHRE, 0.32, 0.3, false, "rotring");

  // --- G. HYPERREAL FUZZ OF HER YARN (HALO OF FINE FIBERS) ---
  // 1. Fuzz halo along the working yarn strand
  for (let i = 0; i < 95; i++) {
    let t = i / 94;
    let idx = Math.min(yarnStrandPath.length - 2, Math.floor(t * (yarnStrandPath.length - 1)));
    let frac = t * (yarnStrandPath.length - 1) - idx;
    let bx = yarnStrandPath[idx][0] * (1 - frac) + yarnStrandPath[idx + 1][0] * frac;
    let by = yarnStrandPath[idx][1] * (1 - frac) + yarnStrandPath[idx + 1][1] * frac;
    let ang = random(360) * Math.PI / 180;
    let len = random(5, 14);
    let mx = bx + Math.cos(ang + 0.5) * len * 0.55;
    let my = by + Math.sin(ang + 0.5) * len * 0.55;
    let ex = bx + Math.cos(ang) * len;
    let ey = by + Math.sin(ang) * len;
    let fCol = i % 3 === 0 ? PAL.GOLD_LIGHT : (i % 2 === 0 ? PAL.CINN_PALE : PAL.CINN_LIGHT);
    strokeSpline([[bx, by], [mx, my], [ex, ey]], fCol, 0.22, 0.35, false, "rotring");
  }

  // 2. Fuzz halo around the perimeter and surface of the knitted garment panel
  for (let i = 0; i < 160; i++) {
    let side = i % 2 === 0 ? -1 : 1;
    let ry = random(624, 768);
    let tr = (ry - 624) / 144;
    let edgeX = 600 + side * (50 + tr * 11) + random(-6, 6);
    let ang = (side === -1 ? random(110, 250) : random(-70, 70)) * Math.PI / 180;
    let len = random(6, 16);
    let mx = edgeX + Math.cos(ang + 0.4) * len * 0.5;
    let my = ry + Math.sin(ang + 0.4) * len * 0.5;
    let ex = edgeX + Math.cos(ang) * len;
    let ey = ry + Math.sin(ang) * len;
    let fCol = i % 4 === 0 ? PAL.GOLD_BRIGHT : (i % 2 === 0 ? PAL.CINN_PALE : PAL.CINN_LIGHT);
    strokeSpline([[edgeX, ry], [mx, my], [ex, ey]], fCol, 0.22, 0.35, false, "rotring");
  }

  // 3. Fuzz halo around the wound yarn ball in her lap
  for (let i = 0; i < 85; i++) {
    let a = (i / 85) * Math.PI * 2;
    let bx = 562 + Math.cos(a) * 34;
    let by = 798 + Math.sin(a) * 31;
    let len = random(6, 15);
    let ex = bx + Math.cos(a + random(-0.5, 0.5)) * len;
    let ey = by + Math.sin(a + random(-0.5, 0.5)) * len;
    strokeSpline([
      [bx, by],
      [(bx + ex) * 0.5 + random(-3, 3), (by + ey) * 0.5 + random(-3, 3)],
      [ex, ey]
    ], i % 3 === 0 ? PAL.GOLD_LIGHT : PAL.CINN_PALE, 0.22, 0.35, false, "rotring");
  }
}

