// Shared helper: ornate hierarchical cloud-medallion register frame
function drawRegisterMedallion(cx, cy, rx, ry, innerCol = PAL.LAPIS_ABYSS, rimCol = PAL.CINN_MID) {
  // Outer cloud clusters cradling the register
  drawCloudCluster(cx - rx * 0.65, cy + ry * 0.78, 0.68, 0.55, PAL.MALA_DARK, PAL.MALA_MID, PAL.MALA_BRIGHT, PAL.GOLD_OCHRE, false);
  drawCloudCluster(cx + rx * 0.65, cy + ry * 0.78, 0.68, 0.55, PAL.MALA_DARK, PAL.MALA_MID, PAL.MALA_BRIGHT, PAL.GOLD_OCHRE, false);

  // Outer gold & cinnabar register aureole rings
  let outerPts = ellipsePts(cx, cy, rx + 10, ry + 10, 48);
  mineralShape(outerPts, PAL.GOLD_OCHRE, 255, 0.5, 0.2, null, PAL.GOLD_LIGHT);

  let midPts = ellipsePts(cx, cy, rx + 4, ry + 4, 48);
  mineralShape(midPts, rimCol, 255, 0.42, 0.2, null, PAL.GOLD_OCHRE);

  let innerPts = ellipsePts(cx, cy, rx - 4, ry - 4, 48);
  mineralShape(innerPts, innerCol, 255, 0.48, 0.2, {
    brush: "2H", col: PAL.LAPIS_MID, dist: 6, angle: 45, weight: 0.24
  }, PAL.GOLD_BRIGHT);

  // Pearl-beaded gold dots around the register frame
  for (let i = 0; i < 36; i++) {
    let a = (i / 36) * Math.PI * 2;
    let px = cx + Math.cos(a) * rx;
    let py = cy + Math.sin(a) * ry;
    polyWash(ellipsePts(px, py, 2.2, 2.2, 8), PAL.GOLD_CREAM, 255);
  }

  // Bottom lotus-cloud pedestal cushion inside the register
  drawCloudCluster(cx, cy + ry * 0.72, 0.85, 0.62, PAL.MALA_DEEP, PAL.MALA_MID, PAL.MALA_VIVID, PAL.GOLD_OCHRE, false);
}

