  polyWash(ellipsePts(tx, cy + 4, 5, 5, 12), PAL.GOLD_BRIGHT, 255);

  // Tapered metallic shoulder collar (y: cy-54 .. cy-32)
  let shoulderPts = [
    [tx - 24, cy - 54], [tx, cy - 50], [tx + 24, cy - 54],
