  mineralShape(dialWin, PAL.GOLD_CREAM, 255, 0.45, 0.06, null, PAL.GOLD_OCHRE);
  // Warm amber dial glow & frequency scale tick marks
  polyWash([[rx + 10, ry + 9], [rx + rw - 10, ry + 9], [rx + rw - 10, ry + 17], [rx + 10, ry + 17]], PAL.GOLD_LIGHT, 210);
  brush.set("rotring", PAL.LAPIS_ABYSS, 0.32);
  brush.line(rx + 14, ry + 17, rx + rw - 14, ry + 17);
  for (let t = 0; t <= 18; t++) {
    let tx = rx + 14 + (t / 18) * (rw - 28);
    let th = t % 3 === 0 ? 6 : 3.5;
    brush.line(tx, ry + 17 - th, tx, ry + 17 + 2);
  }
  // Red Cinnabar tuning needle indicator
  strokeSpline([[rx + 52, ry + 8], [rx + 52, ry + 25]], PAL.CINN_VIVID, 0.85, 0.05, false, "rotring");

  // Lower-left perforated speaker grille (x: rx+8 .. rx+84, y: ry+32 .. ry+rh-7)
  let grilleBox = [[rx + 8, ry + 32], [rx + 84, ry + 32], [rx + 84, ry + rh - 7], [rx + 8, ry + rh - 7]];
  mineralShape(grilleBox, PAL.LAPIS_DEEP, 255, 0.45, 0.06, null, PAL.GOLD_BRIGHT);

  // High-contrast speaker grille perforation matrix (11 cols x 6 rows)
  for (let gr = 0; gr < 6; gr++) {
    for (let gc = 0; gc < 11; gc++) {
      let hx = rx + 14 + gc * 6.4;
      let hy = ry + 38 + gr * 6.6;
      polyWash(ellipsePts(hx, hy, 2.1, 2.1, 8), PAL.LAPIS_ABYSS, 255);
      strokeSpline([[hx - 2, hy - 2], [hx + 2, hy - 2]], PAL.GOLD_OCHRE, 0.22, 0.05, false, "rotring");
    }
  }

  // Right control panel with two knurled rotary knobs (Tuning & Volume)
  for (let k = 0; k < 2; k++) {
    let kx = rx + 104, ky = ry + 44 + k * 24;
    let kOuter = ellipsePts(kx, ky, 10.5, 10.5, 20);
    mineralShape(kOuter, PAL.CINN_MID, 255, 0.4, 0.2, null, PAL.GOLD_BRIGHT);
    let kInner = ellipsePts(kx, ky, 7, 7, 16);
    mineralShape(kInner, PAL.GOLD_LIGHT, 255, 0.35, 0.2, null, PAL.GOLD_OCHRE);
    // Pointer line on knob
    strokeSpline([[kx, ky], [kx + (k === 0 ? -5 : 4), ky - 4]], PAL.CINN_ABYSS, 0.45, 0.1, false, "rotring");
  }
}

// --- REGISTER 3 (BOTTOM-LEFT): 108 PRAYER BEADS (MALA) ---
function drawRegisterPrayerBeads(cx, cy) {
  drawRegisterMedallion(cx, cy, 106, 108, PAL.LAPIS_ABYSS, PAL.MALA_MID);

  // Coiled figure-eight / undulating path of the mala prayer beads
  let nBeads = 44;
  let beadCoords = [];
  for (let i = 0; i < nBeads; i++) {
    let t = (i / nBeads) * Math.PI * 2;
    // Graceful lemniscate-like double loop inside the medallion
    let bx = cx + Math.sin(t) * 66 + Math.cos(t * 2) * 12;
    let by = cy - 10 + Math.cos(t) * 44 + Math.sin(t * 2) * 16;
    beadCoords.push({ x: bx, y: by, idx: i });
  }

  // Red silk mala cord connecting all beads
  strokeSpline(beadCoords.map(b => [b.x, b.y]), PAL.CINN_BRIGHT, 0.75, 0.25, true, "rotring");
  strokeSpline(beadCoords.map(b => [b.x, b.y]), PAL.GOLD_OCHRE, 0.3, 0.25, true, "rotring");

  // Render each individual spherical Bodhi-seed bead (plus turquoise/coral spacers)
  for (let b of beadCoords) {
    let isTurquoise = (b.idx === 11 || b.idx === 33);
    let isCoral = (b.idx === 22);
    let r = (isTurquoise || isCoral) ? 6.8 : 5.4;

    let bPts = ellipsePts(b.x, b.y, r, r, 16);
    let baseCol = isTurquoise ? PAL.MALA_MID : (isCoral ? PAL.CINN_MID : PAL.SKIN_SHADOW);
    let midCol = isTurquoise ? PAL.MALA_VIVID : (isCoral ? PAL.CINN_VIVID : PAL.CINN_MID);
    let hiCol = isTurquoise ? PAL.MALA_PALE : (isCoral ? PAL.CINN_PALE : PAL.GOLD_LIGHT);

    polyWash(bPts, baseCol, 255);
    polyWash(ellipsePts(b.x - 1, b.y - 1, r * 0.75, r * 0.75, 12), midCol, 245);
    // Specular highlight dot on each bead
    polyWash(ellipsePts(b.x - 1.8, b.y - 1.8, r * 0.32, r * 0.32, 8), hiCol, 250);
    // Seed-pock dimples & gold-ochre contour circle
    strokeSpline(bPts, PAL.GOLD_OCHRE, 0.34, 0.2, true, "rotring");
  }

  // Large Guru Bead (Mother bead) at bottom center (cx, cy + 36) with stupa cap & cinnabar tassel
  let gx = cx, gy = cy + 38;
  let guruPts = ellipsePts(gx, gy, 9.5, 9.5, 20);
  mineralShape(guruPts, PAL.MALA_VIVID, 255, 0.45, 0.2, null, PAL.GOLD_BRIGHT);
  polyWash(ellipsePts(gx - 2.5, gy - 2.5, 3.5, 3.5, 10), PAL.MALA_PALE, 250);

  // Conical stupa bead cap below Guru bead
  let stupaCap = [[gx - 5, gy + 9], [gx + 5, gy + 9], [gx + 3, gy + 18], [gx - 3, gy + 18]];
  mineralShape(stupaCap, PAL.GOLD_BRIGHT, 255, 0.38, 0.15, null, PAL.GOLD_CREAM);

  // Frayed Cinnabar-Red Silk Tassel with fuzzy threads streaming down from the Guru bead
  for (let s = -8; s <= 8; s++) {
    let tx1 = gx + s * 0.3;
    let ty1 = gy + 18;
    let tx2 = gx + s * 1.8 + Math.sin(s) * 2;
    let ty2 = gy + 46 + Math.abs(s) * 0.5;
    let col = s % 3 === 0 ? PAL.GOLD_BRIGHT : (s % 2 === 0 ? PAL.CINN_VIVID : PAL.CINN_LIGHT);
    strokeSpline([[tx1, ty1], [(tx1 + tx2) * 0.5, (ty1 + ty2) * 0.5], [tx2, ty2]], col, 0.36, 0.25, false, "rotring");
  }

  // Two side silver counter strands with tiny flat silver ring counters
  for (let side of [-1, 1]) {
    let cPath = [[cx + side * 48, cy + 16], [cx + side * 66, cy + 36], [cx + side * 72, cy + 56]];
    strokeSpline(cPath, PAL.GOLD_OCHRE, 0.4, 0.25, false, "rotring");
    for (let k = 0; k < 5; k++) {
      let t = (k + 1) / 6;
      let rx = (cx + side * 48) * (1 - t) + (cx + side * 72) * t;
      let ry = (cy + 16) * (1 - t) + (cy + 56) * t;
      let ringPts = ellipsePts(rx, ry, 3.8, 2.2, 10, side * 30);
      mineralShape(ringPts, PAL.GOLD_LIGHT, 255, 0.28, 0.2, null, PAL.GOLD_OCHRE);
    }
  }
}

// --- REGISTER 4 (BOTTOM-RIGHT): THE SLEEPING DOG ---
