    strokeSpline([[px + 3, py + 2], [px + 5, py + 7]], PAL.SKIN_DEEP, 0.3, 0.1, false, "rotring");
  }

  // 4. Woven Cinnabar-Red & Gold Collar around the dog's neck
  let collarPts = [
