  mineralShape(bellPts, PAL.GOLD_LIGHT, 255, 0.35, 0.2, null, PAL.GOLD_OCHRE);

  // 5. Sleeping Head resting peacefully on its front paws (cx - 34, cy + 12)
  let hx = cx - 34, hy = cy + 12;
  let headPts = [
    [hx - 24, hy - 14], [hx - 6, hy - 26], [hx + 18, hy - 18],
    [hx + 34, hy + 2], [hx + 32, hy + 18], [hx + 8, hy + 24],
    [hx - 18, hy + 20], [hx - 28, hy + 4]
  ];
  mineralShape(headPts, PAL.LAPIS_DEEP, 255, 0.48, 0.25, null, PAL.GOLD_OCHRE);

  // Warm tan muzzle & traditional Tibetan "four-eyed" eyebrow spots (dak)
  let muzzleTan = ellipsePts(hx + 18, hy + 10, 15, 11, 20, 12);
  polyWash(muzzleTan, PAL.SKIN_WARM, 240);
  polyWash(ellipsePts(hx - 2, hy - 6, 6, 4, 12, -15), PAL.GOLD_BRIGHT, 245);
  polyWash(ellipsePts(hx + 12, hy - 8, 5.5, 3.8, 12, 15), PAL.GOLD_BRIGHT, 245);

  // Peaceful closed sleeping eyelids with gentle lashes
  strokeSpline([[hx - 10, hy + 2], [hx - 2, hy + 6], [hx + 6, hy + 2]], PAL.GOLD_BRIGHT, 0.45, 0.25, false, "rotring");
  strokeSpline([[hx + 8, hy - 1], [hx + 15, hy + 3], [hx + 21, hy - 1]], PAL.GOLD_BRIGHT, 0.45, 0.25, false, "rotring");

  // Shiny wet black nose with crisp specular catchlight
  let nosePts = ellipsePts(hx + 28, hy + 8, 6.5, 5, 16);
