  polyWash(ellipsePts(hx + 26, hy + 6, 2.5, 1.6, 10), "#FFFFFF", 250);

  // Long floppy feathered ear draping down left side of head
  let earFlop = [
    [hx - 16, hy - 14], [hx - 32, hy - 4], [hx - 36, hy + 18],
    [hx - 24, hy + 26], [hx - 12, hy + 14], [hx - 10, hy - 6]
  ];
  mineralShape(earFlop, PAL.LAPIS_ABYSS, 255, 0.45, 0.28, null, PAL.GOLD_OCHRE);

  // 6. Hyperreal Directional Fur Locks across the sleeping dog's coat, ears & tail
  for (let f = 0; f < 140; f++) {
    let t = (f / 140) * Math.PI * 1.85 - 0.6;
    let r = random(18, 56);
    let fx = cx + 6 + Math.cos(t) * r * 1.15;
    let fy = cy + 6 + Math.sin(t) * r * 0.78;
    let tang = t + Math.PI * 0.5 + random(-0.25, 0.25);
    let len = random(10, 20);
    let mx = fx + Math.cos(tang) * len * 0.5;
    let my = fy + Math.sin(tang) * len * 0.5;
    let ex = fx + Math.cos(tang + 0.2) * len;
    let ey = fy + Math.sin(tang + 0.2) * len;
    let fCol = f % 5 === 0 ? PAL.GOLD_OCHRE : (f % 3 === 0 ? PAL.LAPIS_LIGHT : (f % 2 === 0 ? PAL.LAPIS_MID : PAL.HAIR_SILVER));
    strokeSpline([[fx, fy], [mx, my], [ex, ey]], fCol, 0.28, 0.3, false, "rotring");
  }
}

// ============================================================================
// 7. PAINTED SILK BROCADE MOUNT BORDER (THANGKA FRAMING)
// ============================================================================
function drawSilkBrocadeBorder() {
  // Inner painting window coordinates: x: 140..1060, y: 120..1030
  // Rainbow Border ("Ja") outer coordinates: x: 112..1088, y: 92..1058

  // 1. Deep Lapis Lazuli Silk Mount Panels (Top, Bottom, Left, Right)
  let silkPanels = [
    [[0, 0], [1200, 0], [1088, 92], [112, 92]],       // Top silk panel
    [[0, 1200], [112, 1058], [1088, 1058], [1200, 1200]], // Bottom silk panel (wider)
    [[0, 0], [112, 92], [112, 1058], [0, 1200]],      // Left silk panel
    [[1200, 0], [1200, 1200], [1088, 1058], [1088, 92]] // Right silk panel
  ];
  for (let sp of silkPanels) {
    polyWash(sp, PAL.LAPIS_DEEP, 255);
  }

  // Fine silk damask weave texture across the outer lapis brocade mount
  brush.hatchStyle("2H", PAL.LAPIS_MID, 0.25);
  for (let sp of silkPanels) {
    let p = new brush.Polygon(sp);
    p.hatch(6, 0, { rand: 0.03 });
    p.hatch(8, 90, { rand: 0.03 });
  }
  brush.noHatch();

  // Diagonal miter seams at the 4 corners of the silk brocade mount
  for (let m of [
    [[0, 0], [140, 120]],
    [[1200, 0], [1060, 120]],
    [[0, 1200], [140, 1030]],
    [[1200, 1200], [1060, 1030]]
  ]) {
    strokeSpline(m, PAL.GOLD_BRIGHT, 0.55, 0.05, false, "rotring");
  }

  // 2. The Rainbow Silk Border ("Ja"): Three concentric bands of Cinnabar, Gold-Ochre & Malachite
  let jaBands = [
    // Band 1 (outer): Cinnabar Red
    { x1: 112, y1: 92, x2: 1088, y2: 1058, ix1: 122, iy1: 102, ix2: 1078, iy2: 1048, col: PAL.CINN_BRIGHT },
    // Band 2 (middle): Gold-Ochre
    { x1: 122, y1: 102, x2: 1078, y2: 1048, ix1: 131, iy1: 111, ix2: 1069, iy2: 1039, col: PAL.GOLD_BRIGHT },
    // Band 3 (inner): Malachite Green
    { x1: 131, y1: 111, x2: 1069, y2: 1039, ix1: 140, iy1: 120, ix2: 1060, iy2: 1030, col: PAL.MALA_BRIGHT }
  ];

  for (let b of jaBands) {
    let sides = [
      [[b.x1, b.y1], [b.x2, b.y1], [b.ix2, b.iy1], [b.ix1, b.iy1]], // Top
      [[b.ix1, b.iy2], [b.ix2, b.iy2], [b.x2, b.y2], [b.x1, b.y2]], // Bottom
      [[b.x1, b.y1], [b.ix1, b.iy1], [b.ix1, b.iy2], [b.x1, b.y2]], // Left
      [[b.ix2, b.iy1], [b.x2, b.y1], [b.x2, b.y2], [b.ix2, b.iy2]]  // Right
    ];
    for (let s of sides) {
      polyWash(s, b.col, 255);
      strokeSpline(s, PAL.GOLD_OCHRE, 0.42, 0.05, true, "rotring");
    }
  }
  // Inner crisp double gold-ochre frame around the painting window
  strokeSpline([[140, 120], [1060, 120], [1060, 1030], [140, 1030]], PAL.GOLD_CREAM, 0.65, 0.02, true, "rotring");
  strokeSpline([[112, 92], [1088, 92], [1088, 1058], [112, 1058]], PAL.GOLD_BRIGHT, 0.65, 0.02, true, "rotring");

  // 3. The Sacred Golden Silk Patch ("Thang-go" / Door of the Thangka) at Bottom Center
  let tgOuter = [[472, 1068], [728, 1068], [744, 1188], [456, 1188]];
  let tgMid = [[482, 1076], [718, 1076], [732, 1180], [468, 1180]];
  let tgInner = [[492, 1084], [708, 1084], [720, 1172], [480, 1172]];
  mineralShape(tgOuter, PAL.GOLD_BRIGHT, 255, 0.55, 0.05, null, PAL.GOLD_CREAM);
  mineralShape(tgMid, PAL.MALA_MID, 255, 0.45, 0.05, null, PAL.GOLD_OCHRE);
  mineralShape(tgInner, PAL.CINN_DARK, 255, 0.48, 0.05, {
    brush: "2H", col: PAL.CINN_BRIGHT, dist: 5, angle: 0, weight: 0.25
  }, PAL.GOLD_BRIGHT);

  // Sacred lotus & cloud brocade motif woven inside the Thang-go patch
  drawCloudCluster(600, 1132, 1.05, 0.65, PAL.GOLD_OCHRE, PAL.GOLD_BRIGHT, PAL.GOLD_CREAM, PAL.GOLD_DEEP, false);
  for (let p = -3; p <= 3; p++) {
    let petal = ellipsePts(600 + p * 18, 1126 - Math.abs(p) * 2, 10, 22, 16, p * 14);
    mineralShape(petal, p % 2 === 0 ? PAL.MALA_VIVID : PAL.CINN_VIVID, 250, 0.35, 0.2, null, PAL.GOLD_CREAM);
  }
  polyWash(ellipsePts(600, 1128, 14, 9, 16), PAL.GOLD_CREAM, 255);
  strokeSpline(ellipsePts(600, 1128, 14, 9, 16), PAL.CINN_DARK, 0.35, 0.2, true, "rotring");

  // 4. Woven Golden Brocade Medallions & Fretwork Lattice across the Lapis Silk Mount
  function drawBrocadeMedallion(mx, my, r) {
    let outer = ellipsePts(mx, my, r, r, 32);
    mineralShape(outer, PAL.GOLD_OCHRE, 250, 0.42, 0.2, null, PAL.GOLD_CREAM);
    let inner = ellipsePts(mx, my, r * 0.82, r * 0.82, 28);
    mineralShape(inner, PAL.LAPIS_ABYSS, 250, 0.35, 0.2, null, PAL.GOLD_BRIGHT);
    // 8-petal lotus wheel in malachite & cinnabar inside medallion
    for (let k = 0; k < 8; k++) {
      let a = (k / 8) * Math.PI * 2;
      let px = mx + Math.cos(a) * r * 0.44;
      let py = my + Math.sin(a) * r * 0.44;
      let pet = ellipsePts(px, py, r * 0.28, r * 0.16, 12, k * 45);
      polyWash(pet, k % 2 === 0 ? PAL.CINN_BRIGHT : PAL.MALA_VIVID, 245);
      strokeSpline(pet, PAL.GOLD_LIGHT, 0.28, 0.2, true, "rotring");
    }
    let core = ellipsePts(mx, my, r * 0.22, r * 0.22, 16);
    mineralShape(core, PAL.GOLD_BRIGHT, 255, 0.32, 0.2, null, PAL.GOLD_CREAM);
  }

  // Place 12 auspicious brocade medallions around the silk mount
  let medallions = [
    // Top border
    [220, 46, 30], [410, 46, 30], [600, 46, 34], [790, 46, 30], [980, 46, 30],
    // Left & Right borders
    [56, 240, 32], [56, 465, 32], [56, 690, 32], [56, 915, 32],
    [1144, 240, 32], [1144, 465, 32], [1144, 690, 32], [1144, 915, 32],
    // Bottom border flanking the Thang-go
    [200, 1128, 38], [355, 1128, 38], [845, 1128, 38], [1000, 1128, 38]
  ];
  for (let [mx, my, mr] of medallions) {
    drawBrocadeMedallion(mx, my, mr);
  }

  // Woven gold-ochre geometric diamond lattice between the medallions on Left, Right, Top & Bottom silk
  for (let y = 145; y <= 1015; y += 56) {
    for (let sx of [56, 1144]) {
      if (Math.abs(y - 240) > 36 && Math.abs(y - 465) > 36 && Math.abs(y - 690) > 36 && Math.abs(y - 915) > 36) {
        let dia = [[sx, y - 16], [sx + 18, y], [sx, y + 16], [sx - 18, y]];
        strokeSpline(dia, PAL.GOLD_OCHRE, 0.32, 0.05, true, "rotring");
        polyWash(ellipsePts(sx, y, 4, 4, 8), PAL.GOLD_BRIGHT, 230);
      }
    }
  }
  for (let x = 150; x <= 1050; x += 62) {
    if (Math.abs(x - 220) > 36 && Math.abs(x - 410) > 36 && Math.abs(x - 600) > 40 && Math.abs(x - 790) > 36 && Math.abs(x - 980) > 36) {
      let dia = [[x, 30], [x + 16, 46], [x, 62], [x - 16, 46]];
      strokeSpline(dia, PAL.GOLD_OCHRE, 0.32, 0.05, true, "rotring");
      polyWash(ellipsePts(x, 46, 4, 4, 8), PAL.GOLD_BRIGHT, 230);
    }
  }

  // Outer Cinnabar & Gold silk cord binding around the entire 1200x1200 edge
  let edgeBands = [
    [[0, 0], [1200, 0], [1190, 10], [10, 10]],
    [[10, 1190], [1190, 1190], [1200, 1200], [0, 1200]],
    [[0, 0], [10, 10], [10, 1190], [0, 1200]],
    [[1190, 10], [1200, 0], [1200, 1200], [1190, 1190]]
  ];
  for (let eb of edgeBands) {
    polyWash(eb, PAL.CINN_DARK, 255);
    strokeSpline(eb, PAL.GOLD_BRIGHT, 0.55, 0.02, true, "rotring");
  }
}

