      glow: "#faf7f2",
      light: "#e8e0d5",
      lightAlpha: 70,
      mid: "#cfc4b6",
      midAlpha: 78,
      deep: "#aba092",
      deepAlpha: 85,
      border: "#6e6459",
      needleDark: "#9c9183",
      needleLight: "#ffffff",
      gritDark: "#756b5f",
      gritLight: "#ffffff"
    },
    white_pure: {
      glow: "#ffffff",
      light: "#f0eae1",
      lightAlpha: 65,
      mid: "#d9d0c5",
      midAlpha: 72,
      deep: "#b8aea2",
      deepAlpha: 80,
      border: "#786e63",
      needleDark: "#a69b8e",
      needleLight: "#ffffff",
      gritDark: "#7d7266",
      gritLight: "#ffffff"
    },
    grape: {
      glow: "#eee8f2",
      light: "#93819e",
      lightAlpha: 92,
      mid: "#533f5e",
      midAlpha: 115,
      deep: "#221629",
      deepAlpha: 140,
      border: "#140b1a",
      needleDark: "#362540",
      needleLight: "#f7f3fa",
      gritDark: "#1f1426",
      gritLight: "#e6deed"
    },
    lemon: {
      glow: "#fffdf6",
      light: "#f2e2b3",
      lightAlpha: 85,
      mid: "#d6ba72",
      midAlpha: 102,
      deep: "#9e813c",
      deepAlpha: 115,
      border: "#634f21",
      needleDark: "#b09248",
      needleLight: "#fffffc",
      gritDark: "#786028",
      gritLight: "#fffef7"
    },
    lime: {
      glow: "#f4f7f0",
      light: "#c4d1b8",
      lightAlpha: 86,
      mid: "#8da17d",
      midAlpha: 104,
      deep: "#536647",
      deepAlpha: 118,
      border: "#36452c",
      needleDark: "#697d5b",
      needleLight: "#fafcf8",
      gritDark: "#435438",
      gritLight: "#f2f7ed"
    }
  };

  // Concentric sugar layers from center (k = 0) outward to corners (k = 36)
  const LAYERS = [
    { dr: 35, type: "cherry_hot", isCore: true }, // 0: Central compressed sugar nucleus
    { dr: 9,  type: "white_pure" },               // 1: Dense white crystal core shell
    { dr: 34, type: "cherry_hot" },               // 2: Inner glowing ruby ring
    { dr: 7,  type: "white_pure" },               // 3
    { dr: 19, type: "lemon" },                    // 4: Warm backlit champagne-lemon
    { dr: 6,  type: "white" },                    // 5
    { dr: 25, type: "grape" },                    // 6: Smoky amethyst-grape
    { dr: 8,  type: "white_pure" },               // 7
    { dr: 22, type: "lime" },                     // 8: Celadon-lime sugar layer
    { dr: 6,  type: "white" },                    // 9
    { dr: 5,  type: "cherry" },                   // 10: Thin cherry syrup doublet line
    { dr: 6,  type: "white_pure" },               // 11
    { dr: 52, type: "cherry_hot" },               // 12: Wide incandescent backlit cherry band
    { dr: 11, type: "white_pure" },               // 13: Thick opaque white sugar barrier
    { dr: 32, type: "grape" },                    // 14: Deep smoky grape band
    { dr: 7,  type: "white" },                    // 15
    { dr: 28, type: "lemon" },                    // 16: Luminous lemon-quartz band
    { dr: 6,  type: "white" },                    // 17
    { dr: 6,  type: "grape" },                    // 18: Thin smoky mineral ring
    { dr: 7,  type: "white_pure" },               // 19
    { dr: 38, type: "lime" },                     // 20: Wide glassy celadon-lime band
    { dr: 10, type: "white" },                    // 21
    { dr: 44, type: "lemon" },                    // 22: Broad backlit lemon-ivory band
    { dr: 9,  type: "white_pure" },               // 23
    { dr: 64, type: "cherry" },                   // 24: Hero wide cherry watercolor band
    { dr: 12, type: "white_pure" },               // 25: Crisp opaque white ring
    { dr: 7,  type: "cherry_hot" },               // 26: Vivid cherry echo ring
    { dr: 8,  type: "white" },                    // 27
    { dr: 58, type: "grape" },                    // 28: Major dark smoky grape ring near frame edge
    { dr: 12, type: "white_pure" },               // 29: Crisp white ring tangent to canvas edges
    { dr: 48, type: "lemon" },                    // 30: Backlit lemon band cutting across frame sides
    { dr: 10, type: "white" },                    // 31
    { dr: 54, type: "lime" },                     // 32: Celadon-lime band in corner quadrants
    { dr: 12, type: "white_pure" },               // 33
    { dr: 68, type: "cherry" },                   // 34: Glowing cherry ring in outer corners
    { dr: 14, type: "white" },                    // 35
    { dr: 135, type: "grape" }                    // 36: Deep smoky grape enclosing extreme corners
  ];

  const NUM_LAYERS = LAYERS.length;
  const ringR = [];

  // Build cumulative organic radii from inside out so adjacent layers never cross
  // and naturally inherit the panned sugar nodules of inner layers.
  for (let k = 0; k < NUM_LAYERS; k++) {
    ringR[k] = new Array(N_ANG);
  }

  for (let i = 0; i < N_ANG; i++) {
    let deg = i * STEP_DEG;
    let cxN = cos(deg);
    let cyN = sin(deg);

    // Base angular harmonics simulating hot-pan tumbling over a nodular sugar seed
    let panWave =
      sin(deg * 2 + 25) * 0.035 +
      cos(deg * 3 - 40) * 0.028 +
      sin(deg * 5 + 70) * 0.018;

    let cumR = 0;
    for (let k = 0; k < NUM_LAYERS; k++) {
      let baseDr = LAYERS[k].dr;
      // Smooth accretion variation per layer
      let nVal = noise(2.5 + cxN * 1.4, 2.5 + cyN * 1.4, k * 0.18);
      let nFine = noise(8.0 + cxN * 3.2, 8.0 + cyN * 3.2, k * 0.35);
      // Inner core layers have slightly stronger crystal nodules; outer layers smooth out
      let coreFactor = map(k, 0, NUM_LAYERS - 1, 1.35, 0.55);
      let nodule =
        (sin(deg * 7 + k * 8) * 0.022 + cos(deg * 11 - k * 5) * 0.014) *
        coreFactor;

      let localScale =
        1.0 +
        panWave * coreFactor +
        nodule +
        (nVal - 0.5) * 0.24 +
        (nFine - 0.5) * 0.1;

      cumR += max(baseDr * 0.68, baseDr * localScale);
      ringR[k][i] = cumR;
    }
  }

  // Helper to get (x, y) on ring k at angle index (supports fractional or wrapped indices)
  function getRingPt(k, idx, radiusOffset = 0) {
    let iWrapped = ((idx % N_ANG) + N_ANG) % N_ANG;
    let i0 = floor(iWrapped);
    let i1 = (i0 + 1) % N_ANG;
    let frac = iWrapped - i0;
    let r =
      k < 0
        ? 0
        : lerp(ringR[k][i0], ringR[k][i1], frac) + radiusOffset;
    let deg = idx * STEP_DEG;
    return [CX + r * cos(deg), CY + r * sin(deg), r];
  }

  // Helper to get interpolated radius between inner ring (k-1) and outer ring (k)
  function getBandPt(k, idx, bandFrac) {
    let iWrapped = ((idx % N_ANG) + N_ANG) % N_ANG;
    let i0 = floor(iWrapped);
    let i1 = (i0 + 1) % N_ANG;
    let frac = iWrapped - i0;
    let rIn = k === 0 ? 0 : lerp(ringR[k - 1][i0], ringR[k - 1][i1], frac);
    let rOut = lerp(ringR[k][i0], ringR[k][i1], frac);
    let r = lerp(rIn, rOut, bandFrac);
    let deg = idx * STEP_DEG;
    return [CX + r * cos(deg), CY + r * sin(deg), r, rOut - rIn];
  }

  // Draw a full closed ring polygon for crisp base washes
  function drawFullRingWash(k, col, alpha) {
    brush.noStroke();
    brush.noFill();
    brush.wash(col, alpha);
    brush.beginShape(0.28);
    for (let i = 0; i < N_ANG; i++) {
      let [x, y] = getRingPt(k, i);
      brush.vertex(x, y);
    }
    brush.endShape(true);
    brush.noWash();
  }

  // Draw an annular arc strip within band k for wet watercolor blooms
  function drawAnnularBloom(
    k,
    iStart,
    iEnd,
    fracInFn,
    fracOutFn,
    col,
    alpha,
    bleed,
    texStrength,
    borderInt
  ) {
    brush.noStroke();
    brush.noWash();
    brush.fill(col, alpha);
    brush.fillBleed(bleed, "in");
    brush.fillTexture(texStrength, borderInt);

    brush.beginShape(0.25);
    // Outer contour (clockwise)
    for (let i = iStart; i <= iEnd; i++) {
      let fOut = constrain(fracOutFn(i), 0.04, 0.99);
      let [x, y] = getBandPt(k, i, fOut);
      brush.vertex(x, y);
    }
    // Inner contour (counter-clockwise)
    for (let i = iEnd; i >= iStart; i--) {
      let fIn = constrain(fracInFn(i), 0.01, 0.92);
      let [x, y] = getBandPt(k, i, fIn);
      brush.vertex(x, y);
    }
    brush.endShape(true);
    brush.noFill();
  }

  // Cover entire 1200x1200 frame with outermost deep grape base so zero background exists
  brush.noStroke();
  brush.wash("#1f1524", 255);
  brush.rect(0, 0, width, height, "corner");
  brush.noWash();

  // Store grit and crystal accent points to batch-render by brush/color for speed and crispness
  const gritBatches = {};
  function queueGrit(colorHex, x1, y1, x2, y2, weight = 0.35, brushName = "2H") {
    let key = brushName + "|" + colorHex + "|" + weight;
    if (!gritBatches[key]) {
      gritBatches[key] = { brushName, colorHex, weight, lines: [] };
    }
    gritBatches[key].lines.push([x1, y1, x2, y2]);
  }

  // =========================================================================
  // 1. RENDER CONCENTRIC SUGAR BANDS FROM OUTSIDE (k = NUM_LAYERS-1) TO CORE
  // =========================================================================
  for (let k = NUM_LAYERS - 1; k >= 1; k--) {
    let layer = LAYERS[k];
    let pal = PALETTES[layer.type];
    let dr = layer.dr;
    let isWhite = layer.type === "white" || layer.type === "white_pure";

    // A. Razor-crisp opaque/luminous base wash at outer boundary of band k.
    // This cleanly cuts off any inward bleed from band k+1 and sets the backlit glow.
    drawFullRingWash(k, pal.glow, isWhite ? 252 : 246);

    // B. Wet watercolor blooms inside the ring
    if (!isWhite && dr >= 12) {
      let numArcs = 5;
      let arcSpan = N_ANG / numArcs; // 24 steps = 72 degrees per arc
      let rotOffset = floor(random(N_ANG));

      // Pass 1: Translucent luminous body wash leaving a glowing backlit inner rim
      for (let a = 0; a < numArcs; a++) {
        let i0 = rotOffset + a * arcSpan - 1;
        let i1 = rotOffset + (a + 1) * arcSpan + 1;

        // Directional backlight: upper-left (around 220 deg) glows with a wider luminous inner halo
        drawAnnularBloom(
          k,
          i0,
          i1,
          (idx) => {
            let deg = idx * STEP_DEG;
            let backlightBias = map(cos(deg - 220), -1, 1, 0.04, 0.18);
            let n = noise(k * 3.1, cos(deg) * 1.8 + 4, sin(deg) * 1.8 + 4);
            return backlightBias + n * 0.24;
          },
          (idx) => 0.97,
          pal.light,
          pal.lightAlpha,
          0.14,
          0.68,
          0.74
        );
      }

      // Pass 2: Concentrated wet pigment bloom along outer half of the band,
      // diffusing softly inward with cauliflower backrun edges
      let numMidArcs = dr >= 28 ? 6 : 4;
      let midSpan = floor(N_ANG / numMidArcs);
      let midOffset = floor(random(N_ANG));

      for (let a = 0; a < numMidArcs; a++) {
        let i0 = midOffset + a * midSpan;
        let i1 = i0 + midSpan + 1;

        drawAnnularBloom(
          k,
          i0,
          i1,
          (idx) => {
            let deg = idx * STEP_DEG;
            let backlightBias = map(cos(deg - 220), -1, 1, 0.30, 0.48);
            let n = noise(k * 5.7 + 10, cos(deg) * 2.4 + 2, sin(deg) * 2.4 + 2);
            return backlightBias + n * 0.36;
          },
          (idx) => 0.985,
          pal.mid,
          pal.midAlpha,
          0.20,
          0.80,
          0.88
        );
      }

      // Pass 3: Deep pooled syrup pockets right against the outer boundary on wider bands
      if (dr >= 24) {
        let numPools = 4;
        for (let p = 0; p < numPools; p++) {
          let poolCenter = floor(
            (p * N_ANG) / numPools + random(-6, 6) + k * 11
          );
          let halfW = floor(random(8, 14));
          drawAnnularBloom(
            k,
            poolCenter - halfW,
            poolCenter + halfW,
            (idx) => {
              let t = map(abs(idx - poolCenter), 0, halfW, 0, 1);
              let deg = idx * STEP_DEG;
              let n = noise(k * 9.1, cos(deg) * 3 + 5, sin(deg) * 3 + 5);
              return lerp(0.52 + n * 0.22, 0.88, t * t);
            },
            (idx) => 0.99,
            pal.deep,
            pal.deepAlpha,
            0.22,
            0.85,
            0.92
          );
        }
      }

      // C. Watercolor tidelines (backrun rims) & radial sugar crystal striations inside band k
      brush.set("cpencil", pal.mid, 0.28);
      for (let a = 0; a < 7; a++) {
        let startI = floor(random(N_ANG));
        let lenI = floor(random(8, 18));
        let pts = [];
        for (let i = startI; i <= startI + lenI; i++) {
          let deg = i * STEP_DEG;
          let f =
            0.32 +
            0.35 * noise(k * 5.7 + 10, cos(deg) * 2.4 + 2, sin(deg) * 2.4 + 2);
          let [x, y] = getBandPt(k, i, f);
          pts.push([x, y, random(0.3, 0.8)]);
        }
        if (pts.length >= 3) {
          brush.spline(pts, 0.35);
        }
      }

      // Radial acicular sugar crystal fibers perpendicular to the band boundaries
      let fiberCount = floor(map(dr, 12, 70, 36, 110, true) * map(k, 1, NUM_LAYERS, 0.6, 1.3));
      for (let f = 0; f < fiberCount; f++) {
        let fIdx = random(N_ANG);
        let isLightNeedle = random() < 0.48;
        let fStart = isLightNeedle ? random(0.02, 0.25) : random(0.55, 0.97);
        let fEnd = isLightNeedle
          ? fStart + random(0.25, 0.55)
          : fStart - random(0.25, 0.50);
        let [x1, y1] = getBandPt(k, fIdx, constrain(fStart, 0.02, 0.98));
        let [x2, y2] = getBandPt(k, fIdx, constrain(fEnd, 0.02, 0.98));
        queueGrit(
          isLightNeedle ? pal.needleLight : pal.needleDark,
          x1,
          y1,
          x2,
          y2,
          isLightNeedle ? 0.32 : 0.24,
          isLightNeedle ? "cpencil" : "2H"
        );
      }
    } else if (isWhite) {
      // Subtle mineral shadow along the outer rim of opaque white sugar rings
      brush.set("cpencil", pal.mid, 0.42);
      for (let s = 0; s < 4; s++) {
        let i0 = s * (N_ANG / 4);
        let pts = [];
        for (let i = i0; i <= i0 + N_ANG / 4 + 1; i++) {
          let [x, y] = getBandPt(k, i, 0.78);
          pts.push([x, y, 0.5]);
        }
        brush.spline(pts, 0.3);
      }
    } else {
      // Thin colored micro-ring (dr < 12): crisp concentrated watercolor band
      for (let s = 0; s < 3; s++) {
        let span = N_ANG / 3;
        drawAnnularBloom(
          k,
          s * span,
          (s + 1) * span + 1,
          () => 0.12,
          () => 0.96,
          pal.mid,
          pal.midAlpha + 15,
          0.1,
          0.6,
          0.75
        );
      }
    }

    // D. Queue dry stippled pencil sugar grit along this band
    let gritDensity = isWhite
      ? floor(map(k, 1, NUM_LAYERS, 45, 130))
      : floor(map(dr, 5, 70, 20, 95) * map(k, 1, NUM_LAYERS, 0.5, 1.2));

    for (let g = 0; g < gritDensity; g++) {
      let gIdx = random(N_ANG);
      // Grit concentrates near crystallization boundaries and across white sugar rings
      let u = isWhite
        ? random(0.08, 0.92)
        : random() < 0.65
        ? random(0.03, 0.32)
        : random(0.32, 0.95);
      let [gx, gy] = getBandPt(k, gIdx, u);

      // Only queue grit that falls inside the 1200x1200 frame
      if (gx >= -10 && gx <= width + 10 && gy >= -10 && gy <= height + 10) {
        let ang = random(360);
        let stepLen = random(1.2, 2.8);
        let dx = cos(ang) * stepLen;
        let dy = sin(ang) * stepLen;

        // Dark dry-pencil crystal shadow speck
        queueGrit(
          pal.gritDark,
          gx,
          gy,
          gx + dx,
          gy + dy,
          random(0.24, 0.42),
          random() < 0.6 ? "2H" : "HB"
        );

        // Paired bright crystalline sugar glint offset toward the backlight
        if (random() < (isWhite ? 0.75 : 0.55)) {
          let hx = gx - 1.4;
          let hy = gy - 1.4;
          queueGrit(
            pal.gritLight,
            hx,
            hy,
            hx + dy * 0.85,
            hy - dx * 0.85,
            random(0.30, 0.48),
            "cpencil"
          );
        }
      }
    }

    // E. RAZOR-CRISP BOUNDARY at outer contour of band k
    let startOffset = floor(random(N_ANG));
    let boundaryPts = [];
    let highlightPts = [];
    for (let i = 0; i <= N_ANG + 2; i++) {
      let idx = startOffset + i;
      let [bx, by] = getRingPt(k, idx, 0);
      let [hx, hy] = getRingPt(k, idx, -1.6);
      let p = 0.65 + 0.3 * sin(i * 9 + k * 17);
      boundaryPts.push([bx, by, p]);
      highlightPts.push([hx, hy, p * 0.8]);
    }

    // Crisp outer bevel highlight just inside the cut ring edge
    brush.set("cpencil", "#ffffff", isWhite ? 0.42 : 0.32);
    brush.spline(highlightPts, 0.3);

    // Razor-sharp dark pigment boundary holding the wet layer edge
    brush.set("rotring", pal.border, dr >= 20 ? 0.48 : 0.36);
    brush.spline(boundaryPts, 0.3);

    // Dry graphite reinforcement along segments of the boundary
    brush.set("2H", pal.deep, 0.28);
    let segStart = floor(random(N_ANG * 0.3));
    brush.spline(boundaryPts.slice(segStart, segStart + floor(N_ANG * 0.65)), 0.3);
  }

  // =========================================================================
  // 2. RENDER THE CENTRAL COMPRESSED SUGAR SEED CORE (k = 0)
  // =========================================================================
  {
    let pal = PALETTES.cherry_hot;
    // Incandescent backlit core wash
    drawFullRingWash(0, "#fff8f8", 252);

    // Wet cherry-rose halo blooming inward from the core rim
    for (let s = 0; s < 4; s++) {
      let span = N_ANG / 4;
      drawAnnularBloom(
        0,
        s * span - 1,
        (s + 1) * span + 1,
        (idx) => 0.22 + 0.25 * noise(idx * 0.15, 9.2),
        () => 0.98,
        pal.light,
        105,
        0.2,
        0.75,
        0.85
      );
      drawAnnularBloom(
        0,
        s * span,
        (s + 1) * span,
        (idx) => 0.52 + 0.25 * noise(idx * 0.2, 14.5),
        () => 0.99,
        pal.mid,
        125,
        0.22,
        0.82,
        0.9
      );
    }

    // Blindingly bright backlit heart at the very center
    brush.noStroke();
    brush.wash("#ffffff", 235);
    brush.circle(CX - 2, CY - 2, 15, 0.25);
    brush.noWash();

    // Cleaved polygonal sugar crystals packed inside the central seed nucleus
    const coreCrystals = [
      { x: CX - 5, y: CY - 4, r: 9, sides: 6, rot: 15, col: "#ffffff" },
      { x: CX + 7, y: CY - 3, r: 8, sides: 5, rot: 42, col: "#fff0f2" },
      { x: CX - 2, y: CY + 8, r: 8.5, sides: 6, rot: 8, col: "#ffe3e7" },
      { x: CX - 13, y: CY + 3, r: 7.5, sides: 5, rot: 28, col: "#ffd4da" },
      { x: CX + 9, y: CY + 9, r: 7, sides: 5, rot: 60, col: "#ffc4cc" },
      { x: CX + 2, y: CY - 14, r: 7.5, sides: 6, rot: 19, col: "#ffdbe0" },
      { x: CX - 12, y: CY - 12, r: 6.5, sides: 5, rot: 50, col: "#f7a8b4" },
      { x: CX + 16, y: CY - 9, r: 6, sides: 5, rot: 12, col: "#f28d9c" },
      { x: CX - 10, y: CY + 15, r: 6, sides: 5, rot: 35, col: "#f28d9c" }
    ];

    for (let c = 0; c < coreCrystals.length; c++) {
      let cr = coreCrystals[c];
      let polyPts = [];
      for (let v = 0; v < cr.sides; v++) {
        let a = cr.rot + (v * 360) / cr.sides + random(-8, 8);
        let rad = cr.r * random(0.82, 1.15);
        polyPts.push([cr.x + cos(a) * rad, cr.y + sin(a) * rad]);
      }

      // Subtle crystal facet hatching
      brush.hatchStyle("2H", c < 3 ? "#f5bac2" : "#bd192f", 0.22);
      brush.hatch(2.8, cr.rot + 30, { rand: 0.04 });
      brush.set("2H", "#8a0b1d", 0.26);
      brush.beginShape(0.05);
      for (let pt of polyPts) brush.vertex(pt[0], pt[1]);
      brush.endShape(true);
      brush.noHatch();

      // Specular white crystal facet edge
      brush.set("cpencil", "#ffffff", 0.42);
      brush.line(
        polyPts[0][0],
        polyPts[0][1],
        polyPts[1][0],
        polyPts[1][1]
      );
      brush.line(
        polyPts[1][0],
        polyPts[1][1],
        polyPts[2][0],
        polyPts[2][1]
      );
    }

    // Dense stippled sugar grit inside the central core
    for (let g = 0; g < 140; g++) {
      let r = sqrt(random()) * 32;
      let a = random(360);
      let gx = CX + cos(a) * r;
      let gy = CY + sin(a) * r;
      let step = random(1.0, 2.2);
      let da = random(360);
      queueGrit(
        r < 14 ? "#9e192c" : "#5e0411",
        gx,
        gy,
        gx + cos(da) * step,
        gy + sin(da) * step,
        0.3,
        "2H"
      );
      queueGrit(
        "#ffffff",
        gx - 1,
        gy - 1,
        gx - 1 + sin(da) * step,
        gy - 1 - cos(da) * step,
        0.4,
        "cpencil"
      );
    }

    // Razor-crisp boundary around the core (k = 0)
    let corePts = [];
    for (let i = 0; i <= N_ANG + 2; i++) {
      let [bx, by] = getRingPt(0, i, 0);
      corePts.push([bx, by, 0.7]);
    }
    brush.set("rotring", pal.border, 0.45);
    brush.spline(corePts, 0.3);
  }

  // =========================================================================
  // 3. EXECUTE BATCHED DRY STIPPLED PENCIL GRIT & CRYSTALLINE FIBERS
  // =========================================================================
  const batchKeys = Object.keys(gritBatches);
  for (let key of batchKeys) {
    let b = gritBatches[key];
    brush.set(b.brushName, b.colorHex, b.weight);
    let lines = b.lines;
    for (let i = 0; i < lines.length; i++) {
      let l = lines[i];
      brush.line(l[0], l[1], l[2], l[3]);
    }
  }

  // =========================================================================
  // 4. DRY SPRAY & STIPPLED PENCIL SURFACE GRIT ACROSS THE CUT FACE
  // =========================================================================
  // Fine dry pencil spray grit along concentric zones to unify the sugar grain
  brush.set("spray", "#ffffff", 0.38);
  for (let k = 1; k < NUM_LAYERS - 2; k += 2) {
    let startI = floor(random(N_ANG));
    let arcPts = [];
    for (let i = startI; i <= startI + 22; i += 2) {
      let [x, y] = getBandPt(k, i, 0.45);
      if (x > 20 && x < width - 20 && y > 20 && y < height - 20) {
        arcPts.push([x, y, 0.4]);
      }
    }
    if (arcPts.length >= 3) brush.spline(arcPts, 0.3);
  }

  brush.set("spray", "#4a3347", 0.32);
  for (let k = 2; k < NUM_LAYERS - 2; k += 3) {
    let startI = floor(random(N_ANG));
    let arcPts = [];
    for (let i = startI; i <= startI + 18; i += 2) {
      let [x, y] = getBandPt(k, i, 0.72);
      if (x > 20 && x < width - 20 && y > 20 && y < height - 20) {
        arcPts.push([x, y, 0.35]);
      }
    }
    if (arcPts.length >= 3) brush.spline(arcPts, 0.3);
  }

  // =========================================================================
  // 5. SAW-CUT MICRO-STRIATIONS & RADIAL CLEAVAGE FRACTURE HAIRLINES
  // =========================================================================
  // Subtle parallel blade-cut shear tracks at -24 degrees catching on sugar grit
  let cutAngle = -24;
  let cosC = cos(cutAngle);
  let sinC = sin(cutAngle);
  brush.set("2H", "#ffffff", 0.22);
  for (let s = 0; s < 85; s++) {
    let sx = random(40, width - 40);
    let sy = random(40, height - 40);
    let len = random(8, 26);
    brush.line(sx, sy, sx + cosC * len, sy + sinC * len);
  }

  brush.set("2H", "#594854", 0.18);
  for (let s = 0; s < 65; s++) {
    let sx = random(40, width - 40);
    let sy = random(40, height - 40);
    let len = random(6, 20);
    brush.line(sx, sy, sx + cosC * len, sy + sinC * len);
  }

  // 4 ultra-fine radial cleavage micro-cracks refracting the backlight across rings
  const crackAngles = [38, 142, 232, 314];
  for (let c = 0; c < crackAngles.length; c++) {
    let baseAng = crackAngles[c];
    let rStart = random(24, 65);
    let rEnd = random(340, 560);
    let steps = 18;
    let darkPts = [];
    let lightPts = [];

    let curAng = baseAng;
    for (let s = 0; s <= steps; s++) {
      let r = lerp(rStart, rEnd, s / steps);
      curAng += random(-1.2, 1.2);
      let x = CX + cos(curAng) * r;
      let y = CY + sin(curAng) * r;
      let nx = -sin(curAng) * 1.4;
      let ny = cos(curAng) * 1.4;
      let p = sin((s / steps) * 180) * 0.7 + 0.15;
      darkPts.push([x, y, p]);
      lightPts.push([x + nx, y + ny, p]);
    }

    brush.set("2H", "#3d1e2b", 0.26);
    brush.spline(darkPts, 0.2);
    brush.set("cpencil", "#ffffff", 0.36);
    brush.spline(lightPts, 0.2);
  }

  noLoop();
}

// Hyperreal Botanical Quilt on a Black-Painted Farm Table
// Centre-Diamond-in-a-Square: Black Kale, Deep Plums, Halved Red Cabbage, Glowing Beet Heart

const W = 1200;
const H = 1200;
const CX = 600;
const CY = 600;

// Quilt layout coordinates
const OUTER_MIN = 92;
const OUTER_MAX = 1108;
const INNER_MIN = 244;
const INNER_MAX = 956;
const DIAMOND_R = 332; // Distance from center to diamond vertices along axes
const BEET_R = 96;     // Radius of the central glowing beet

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(83104);

  // Custom fine quilting needle-graphite brush
  brush.add("quilter", {
    type: "default",
    weight: 0.45,
    scatter: 0.08,
    sharpness: 0.85,
    grain: 18,
    opacity: 195,
    spacing: 0.15,
    pressure: [0.65, 1.0, 0.65],
    noise: 0.25
  });

  // Soft pastel bloom duster brush
  brush.add("pastelBloom", {
    type: "spray",
    weight: 7,
    scatter: 1.8,
    opacity: 36,
    spacing: 0.35,
    pressure: [0.4, 1.1, 0.4],
    noise: 0.5
  });

  // Crisp botanical glazing brush
  brush.add("glaze", {
