function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // 1. CHARCOAL-MASS BLACK-PAINTED FARM TABLE GROUND
  drawBlackFarmTable();

  // 2. SUBTLE CHALK & GRAPHITE QUILT LAYOUT UNDER-DRAWING
  drawQuiltGridUnderlay();

  // 3. OUTER BORDER: BLACK KALE (CAVOLO NERO)
  drawBlackKaleBorder();

  // 4. INNER SQUARE & CORNER TRIANGLES: BAND OF DEEP PLUMS
  drawDeepPlumBand();

  // 5. CENTRE DIAMOND: HALVED RED CABBAGE
  drawRedCabbageDiamond();

  // 6. HEART OF THE DIAMOND: SINGLE GLOWING BEET
  drawGlowingBeetHeart();

  // 7. FINE GRAPHITE QUILTING STITCHES & SOBER FINISHING DETAILS
  drawMasterQuiltingOverlay();

  noLoop();
}

// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function drawPoly(pts, curvature = 0.22) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function drawLoopingStitchLine(x1, y1, x2, y2, stepLen, loopAmp, col, weight = 0.55) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let distTotal = sqrt(dx * dx + dy * dy);
  if (distTotal < 4) return;
  let steps = max(3, floor(distTotal / stepLen));
  let ux = dx / distTotal;
  let uy = dy / distTotal;
  let nx = -uy;
  let ny = ux;

  brush.set("quilter", col, weight);
  let pts = [];
  for (let i = 0; i <= steps * 2; i++) {
    let t = i / (steps * 2);
    let baseX = x1 + dx * t;
    let baseY = y1 + dy * t;
    // Regular looping quilting rhythm
    let phase = i * 90;
    let side = sin(phase) * loopAmp + (noise(baseX * 0.03, baseY * 0.03) - 0.5) * 1.2;
    let forward = cos(phase) * (stepLen * 0.22);
    pts.push([baseX + ux * forward + nx * side, baseY + uy * forward + ny * side, 0.75 + 0.25 * sin(phase)]);
  }
  brush.spline(pts, 0.55);
}

function drawRunningStitchCurve(pts, dashLen, gapLen, col, weight = 0.5) {
  brush.set("2H", col, weight);
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[i];
    let p1 = pts[i + 1];
    let d = dist(p0[0], p0[1], p1[0], p1[1]);
    let stride = dashLen + gapLen;
    let n = max(1, floor(d / stride));
    for (let k = 0; k < n; k++) {
      let t0 = (k * stride) / d;
      let t1 = min(1, (k * stride + dashLen) / d);
      if (t0 < 1) {
        brush.line(
          lerp(p0[0], p1[0], t0),
          lerp(p0[1], p1[1], t0),
          lerp(p0[0], p1[0], t1),
          lerp(p0[1], p1[1], t1)
        );
      }
    }
  }
}

// ============================================================================
// 1. BLACK-PAINTED FARM TABLE (CHARCOAL-MASS GROUND)
// ============================================================================

function drawBlackFarmTable() {
  // Base dark washes across 5 wide horizontal timber planks
  let plankHeights = [0, 238, 482, 724, 964, 1200];
  let plankShades = ["#121418", "#15171c", "#111317", "#14161b", "#121317"];

  brush.noStroke();
  for (let i = 0; i < 5; i++) {
    let y0 = plankHeights[i];
    let y1 = plankHeights[i + 1];
    brush.wash(plankShades[i], 235);
    brush.rect(0, y0, W, y1 - y0, "corner");
  }
  brush.noWash();

  // Charcoal-mass patches across the planks for dry pigment density
  let massColors = ["#181b22", "#1f232b", "#14161b", "#221e24", "#182124"];
  for (let i = 0; i < 5; i++) {
    let y0 = plankHeights[i] + 8;
    let y1 = plankHeights[i + 1] - 8;
    for (let k = 0; k < 4; k++) {
      let x0 = k * 300 + random(-20, 20);
      let w0 = 310 + random(-20, 20);
      brush.mass("charcoal", random(massColors), {
        precision: 0.65,
        strength: 0.45,
        gradient: 0.25,
        outline: false
      });
      brush.rect(constrain(x0, 0, W - 50), y0, w0, y1 - y0, "corner");
    }
  }
  brush.noMass();

  // Wood grain striations in charcoal and soft pastel-grey worn paint highlights
  for (let i = 0; i < 5; i++) {
    let y0 = plankHeights[i];
    let y1 = plankHeights[i + 1];
    let knotX = random(180, 1020);
    let knotY = lerp(y0, y1, random(0.3, 0.7));

    for (let y = y0 + 6; y < y1 - 4; y += 7.5) {
      let pts = [];
      for (let x = 0; x <= W; x += 60) {
        let dx = x - knotX;
        let dy = y - knotY;
        let d = sqrt(dx * dx + dy * dy);
        let bend = exp(-d * 0.012) * (dy > 0 ? 14 : -14);
        let n = (noise(x * 0.004, y * 0.03) - 0.5) * 6;
        pts.push([x, constrain(y + bend + n, y0 + 2, y1 - 2)]);
      }
      if (random() < 0.78) {
        brush.set("charcoal", random(["#0b0c0f", "#1d2129", "#252932"]), random(0.4, 0.9));
      } else {
        // Worn paint showing faint dusty pastel slate/lavender undertone
        brush.set("cpencil", random(["#3b424f", "#474352", "#3a4a4d"]), 0.45);
      }
      brush.spline(pts, 0.35);
    }

    // Plank seam crevices
    if (i > 0) {
      brush.set("charcoal", "#07080a", 1.8);
      brush.line(0, y0, W, y0);
      brush.set("2H", "#4d5463", 0.45);
      brush.line(0, y0 + 2.2, W, y0 + 2.2);
    }
  }

  // Deep sober shadow vignette under the quilt footprint
  brush.noStroke();
  brush.fill("#090a0d", 145);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.4, 0.2);
  brush.rect(OUTER_MIN - 14, OUTER_MIN - 14, OUTER_MAX - OUTER_MIN + 28, OUTER_MAX - OUTER_MIN + 28, "corner");
  brush.noFill();
}

// ============================================================================
// 2. QUILT GRID UNDERLAY
// ============================================================================

function drawQuiltGridUnderlay() {
  // Subtle tailor's chalk & graphite layout lines on the black table
  let chalkCol = "#5b6370";
  brush.set("2H", chalkCol, 0.5);

  // Outer square
  brush.line(OUTER_MIN, OUTER_MIN, OUTER_MAX, OUTER_MIN);
  brush.line(OUTER_MAX, OUTER_MIN, OUTER_MAX, OUTER_MAX);
  brush.line(OUTER_MAX, OUTER_MAX, OUTER_MIN, OUTER_MAX);
  brush.line(OUTER_MIN, OUTER_MAX, OUTER_MIN, OUTER_MIN);

  // Inner square
  brush.line(INNER_MIN, INNER_MIN, INNER_MAX, INNER_MIN);
  brush.line(INNER_MAX, INNER_MIN, INNER_MAX, INNER_MAX);
  brush.line(INNER_MAX, INNER_MAX, INNER_MIN, INNER_MAX);
  brush.line(INNER_MIN, INNER_MAX, INNER_MIN, INNER_MIN);
}

// ============================================================================
// 3. OUTER BORDER: BLACK KALE (CAVOLO NERO / LACINATO KALE)
// ============================================================================

function generateKaleLeaves() {
  let leaves = [];
  let midBorder = (OUTER_MIN + INNER_MIN) * 0.5; // 168

  // 4 sides: Top, Bottom, Left, Right — overlapping strap-like leaves
  // Along each side, 9 leaves laid in a disciplined shingle rhythm
  let countPerSide = 9;
  let spanStart = INNER_MIN - 28;
  let spanEnd = INNER_MAX + 28;

  // Top border (y ~ 168), leaves angled slightly outward/along border
  for (let i = 0; i < countPerSide; i++) {
    let t = i / (countPerSide - 1);
    let cx = lerp(spanStart, spanEnd, t);
    let cy = midBorder + (i % 2 === 0 ? -8 : 8);
    let ang = (t - 0.5) * 28 + (i % 2 === 0 ? -98 : -82);
    leaves.push({ cx, cy, len: 146, wid: 54, ang, side: "top" });
  }
  // Bottom border (y ~ 1032)
  for (let i = 0; i < countPerSide; i++) {
    let t = i / (countPerSide - 1);
    let cx = lerp(spanStart, spanEnd, t);
    let cy = W - midBorder + (i % 2 === 0 ? 8 : -8);
    let ang = (0.5 - t) * 28 + (i % 2 === 0 ? 98 : 82);
    leaves.push({ cx, cy, len: 146, wid: 54, ang, side: "bottom" });
  }
  // Left border (x ~ 168)
  for (let i = 0; i < countPerSide; i++) {
    let t = i / (countPerSide - 1);
    let cy = lerp(spanStart, spanEnd, t);
    let cx = midBorder + (i % 2 === 0 ? -8 : 8);
    let ang = (0.5 - t) * 28 + (i % 2 === 0 ? -172 : 172);
    leaves.push({ cx, cy, len: 146, wid: 54, ang, side: "left" });
  }
  // Right border (x ~ 1032)
  for (let i = 0; i < countPerSide; i++) {
    let t = i / (countPerSide - 1);
    let cy = lerp(spanStart, spanEnd, t);
    let cx = W - midBorder + (i % 2 === 0 ? 8 : -8);
    let ang = (t - 0.5) * 28 + (i % 2 === 0 ? 8 : -8);
    leaves.push({ cx, cy, len: 146, wid: 54, ang, side: "right" });
  }

  // 4 Corner Mitered Rosette Leaves (2 paired diagonal leaves per corner)
  let corners = [
    { x: midBorder, y: midBorder, a: -135 },
    { x: W - midBorder, y: midBorder, a: -45 },
    { x: W - midBorder, y: H - midBorder, a: 45 },
    { x: midBorder, y: H - midBorder, a: 135 }
  ];
  for (let c of corners) {
    leaves.push({ cx: c.x - cos(c.a + 90) * 18, cy: c.y - sin(c.a + 90) * 18, len: 162, wid: 56, ang: c.a - 14, side: "corner" });
    leaves.push({ cx: c.x + cos(c.a + 90) * 18, cy: c.y + sin(c.a + 90) * 18, len: 162, wid: 56, ang: c.a + 14, side: "corner" });
    leaves.push({ cx: c.x, cy: c.y, len: 170, wid: 60, ang: c.a, side: "corner" });
  }

  return leaves;
}

function getKaleContour(leaf) {
  let pts = [];
  let steps = 16;
  let ca = cos(leaf.ang);
  let sa = sin(leaf.ang);

  let toWorld = (lx, ly) => [
    leaf.cx + lx * ca - ly * sa,
    leaf.cy + lx * sa + ly * ca
  ];

  // Upper margin from stem (-len/2) to rounded tip (+len/2)
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let lx = lerp(-leaf.len * 0.48, leaf.len * 0.5, t);
    // Strap-like profile narrow at petiole, widest at 65% length, rounded at tip
    let profile = sin(pow(t, 0.75) * 180);
    let scallop = sin(t * 180 * 7) * 3.5 + (noise(leaf.cx * 0.02 + t * 4, 1) - 0.5) * 5;
    let ly = -(leaf.wid * 0.5 * profile + scallop * profile);
    pts.push(toWorld(lx, ly));
  }
  // Lower margin from tip back to stem
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let lx = lerp(-leaf.len * 0.48, leaf.len * 0.5, t);
    let profile = sin(pow(t, 0.75) * 180);
    let scallop = sin(t * 180 * 7 + 45) * 3.5 + (noise(leaf.cx * 0.02 + t * 4, 2) - 0.5) * 5;
    let ly = leaf.wid * 0.5 * profile + scallop * profile;
    pts.push(toWorld(lx, ly));
  }
  return pts;
}

function drawBlackKaleBorder() {
  let leaves = generateKaleLeaves();

  // Pass 1: Deep bed shadow under the kale frame
  brush.noStroke();
  brush.wash("#081112", 185);
  for (let i = 0; i < leaves.length; i += 2) {
    let pts = getKaleContour(leaves[i]);
    drawPoly(pts, 0.25);
  }
  brush.noWash();

  // Pass 2: Saturated Watercolor Leaf Bodies (batched by deep teal-green / slate shades)
  let kaleTones = ["#0f2e30", "#143b38", "#0c2429", "#18423c", "#123036"];
  for (let b = 0; b < kaleTones.length; b++) {
    brush.noStroke();
    brush.fill(kaleTones[b], 175);
    brush.fillBleed(0.18, "in");
    brush.fillTexture(0.65, 0.55);
    for (let i = b; i < leaves.length; i += kaleTones.length) {
      let pts = getKaleContour(leaves[i]);
      drawPoly(pts, 0.28);
    }
    brush.noFill();
  }

  // Pass 3: Savoyed bullate (blistered pebble) cells, waxy pastel bloom, midribs & quilting veins
  for (let idx = 0; idx < leaves.length; idx++) {
    let leaf = leaves[idx];
    let ca = cos(leaf.ang);
    let sa = sin(leaf.ang);
    let toWorld = (lx, ly) => [
      leaf.cx + lx * ca - ly * sa,
      leaf.cy + lx * sa + ly * ca
    ];

    // Dark recessed crease shadows between leaf blisters
    let pts = getKaleContour(leaf);
    brush.set("2B", "#071718", 0.75);
    brush.spline(pts.slice(0, 17), 0.35);

    // Waxy glaucescent soft pastel bloom (celadon-sage & misty slate-blue)
    brush.set("pastelBloom", idx % 2 === 0 ? "#8eb8ad" : "#96adc2", 0.85);
    let pStart = toWorld(-leaf.len * 0.2, 0);
    let pEnd = toWorld(leaf.len * 0.32, 0);
    brush.line(pStart[0], pStart[1], pEnd[0], pEnd[1]);

    // Bullate (blistered) pebble cells on both sides of the midrib
    let veinCount = 7;
    for (let v = 1; v <= veinCount; v++) {
      let t = v / (veinCount + 1);
      let lx0 = lerp(-leaf.len * 0.4, leaf.len * 0.38, t);
      let maxW = leaf.wid * 0.44 * sin(pow(t, 0.75) * 180);

      for (let side of [-1, 1]) {
        // Lateral vein path
        let v0 = toWorld(lx0, side * 1.5);
        let v1 = toWorld(lx0 + 10, side * maxW * 0.55);
        let v2 = toWorld(lx0 + 22, side * maxW * 0.92);

        // Blister dome between veins (raised teal-sage highlight + dark ring)
        let domeC = toWorld(lx0 + 7, side * maxW * 0.48);
        let domeR = maxW * 0.22;
        if (domeR > 2.5) {
          brush.set("glaze", "#1d4f48", 0.9);
          brush.arc(domeC[0], domeC[1], domeR, leaf.ang - 60, leaf.ang + 120);
          // Soft pastel sage highlight on the crown of the blister
          brush.set("cpencil", random(["#9ec7ba", "#b4d6c8", "#8daab8"]), 0.65);
          brush.arc(domeC[0], domeC[1], domeR * 0.65, leaf.ang - 40, leaf.ang + 85);
          // Deep charcoal shadow pocket under blister
          brush.set("2B", "#081719", 0.55);
          brush.arc(domeC[0], domeC[1], domeR, leaf.ang + 130, leaf.ang + 280);
        }

        // Lateral vein in pale pastel celadon
        brush.set("cpencil", "#b8d9c9", 0.55);
        brush.spline([[v0[0], v0[1], 0.9], [v1[0], v1[1], 0.6], [v2[0], v2[1], 0.25]], 0.35);

        // Graphite looping quilting stitch along the lateral vein
        drawLoopingStitchLine(v0[0], v0[1], v2[0], v2[1], 6, 1.3, "#364d4a", 0.4);
      }
    }

    // Prominent central midrib (thick pale pastel celadon tapering to tip)
    let m0 = toWorld(-leaf.len * 0.48, 0);
    let m1 = toWorld(-leaf.len * 0.05, (noise(idx, 1) - 0.5) * 3);
    let m2 = toWorld(leaf.len * 0.44, 0);

    brush.set("glaze", "#8fb8a8", 1.15);
    brush.spline([[m0[0], m0[1], 1.3], [m1[0], m1[1], 0.85], [m2[0], m2[1], 0.2]], 0.3);

    brush.set("cpencil", "#d8ede2", 0.8);
    brush.spline([[m0[0], m0[1], 1.1], [m1[0], m1[1], 0.7], [m2[0], m2[1], 0.15]], 0.3);

    // Fine graphite quilting stitch down the center of the midrib
    drawLoopingStitchLine(m0[0], m0[1], m2[0], m2[1], 7, 1.5, "#2c3d3b", 0.48);
  }
}

// ============================================================================
// 4. INNER SQUARE & CORNER TRIANGLES: BAND OF DEEP PLUMS
// ============================================================================

function generatePlumPositions() {
  let plums = [];
  // Fill the region inside the Inner Square [INNER_MIN..INNER_MAX]
  // and outside the Central Diamond (|x - CX| + |y - CY| > DIAMOND_R + 12)
  // Using a tidy diagonal quilt lattice so plums pack snugly in rows
  let spacing = 54;
  for (let row = -10; row <= 10; row++) {
    for (let col = -10; col <= 10; col++) {
      let x = CX + col * spacing + (abs(row) % 2 === 1 ? spacing * 0.5 : 0);
      let y = CY + row * (spacing * 0.88);

      // Keep inside inner square with margin for plum radius
      let margin = 28;
      if (x < INNER_MIN + margin || x > INNER_MAX - margin) continue;
      if (y < INNER_MIN + margin || y > INNER_MAX - margin) continue;

      // Keep outside the central cabbage diamond
      let manhattan = abs(x - CX) + abs(y - CY);
      if (manhattan < DIAMOND_R + 30) continue;

      // Slight organic jitter while preserving severe quilt order
      let jx = x + (noise(col * 0.4 + 10, row * 0.4 + 10) - 0.5) * 9;
      let jy = y + (noise(col * 0.4 + 20, row * 0.4 + 20) - 0.5) * 9;

      // Orient plum axis to follow the diamond/square quilt geometry
      let baseAng = atan2(jy - CY, jx - CX) + 90 + (noise(col, row) - 0.5) * 28;
      let rx = random(24, 27.5);
      let ry = random(20, 23);
      let shadeIdx = ( abs(row * 3 + col * 5) ) % 4;

      plums.push({ x: jx, y: jy, rx, ry, ang: baseAng, shadeIdx });
    }
  }

  // Also add a dedicated single-file mitered row right along the 4 diagonal edges of the diamond
  // so the transition between the deep plums and the central cabbage diamond is razor-crisp!
  let diagSteps = 8;
  let dOffset = (DIAMOND_R + 25) * 0.5;
  let dirs = [
    { x0: CX, y0: CY - DIAMOND_R - 25, x1: CX + DIAMOND_R + 25, y1: CY, a: 45 },
    { x0: CX + DIAMOND_R + 25, y0: CY, x1: CX, y1: CY + DIAMOND_R + 25, a: 135 },
    { x0: CX, y0: CY + DIAMOND_R + 25, x1: CX - DIAMOND_R - 25, y1: CY, a: -135 },
    { x0: CX - DIAMOND_R - 25, y0: CY, x1: CX, y1: CY - DIAMOND_R - 25, a: -45 }
  ];

  for (let d of dirs) {
    for (let i = 1; i < diagSteps; i++) {
      let t = i / diagSteps;
      let px = lerp(d.x0, d.x1, t);
      let py = lerp(d.y0, d.y1, t);
      // Avoid collision with existing plums
      let tooClose = false;
      for (let p of plums) {
        if (dist(px, py, p.x, p.y) < 42) {
          tooClose = true;
          break;
        }
      }
      if (!tooClose && px > INNER_MIN + 26 && px < INNER_MAX - 26 && py > INNER_MIN + 26 && py < INNER_MAX - 26) {
        plums.push({
          x: px,
          y: py,
          rx: 25.5,
          ry: 21,
          ang: d.a + (noise(i * 2.1) - 0.5) * 14,
          shadeIdx: i % 4
        });
      }
    }
  }

  return plums;
}

function getPlumContour(p) {
  let pts = [];
  let steps = 16;
  let ca = cos(p.ang);
  let sa = sin(p.ang);
  for (let i = 0; i < steps; i++) {
    let theta = (i / steps) * 360;
    // Slight oval damson/plum taper at apex and dimple at stem end
    let taper = 1.0 + 0.06 * cos(theta) - 0.04 * cos(2 * theta);
    let lx = cos(theta) * p.rx * taper;
    let ly = sin(theta) * p.ry;
    pts.push([
      p.x + lx * ca - ly * sa,
      p.y + lx * sa + ly * ca
    ]);
  }
  return pts;
}

function drawDeepPlumBand() {
  let plums = generatePlumPositions();

  // Pass 1: Deep charcoal-aubergine contact shadows between the plums
  brush.noStroke();
  brush.wash("#0a070d", 205);
  for (let p of plums) {
    let pts = getPlumContour({ x: p.x + 3, y: p.y + 4, rx: p.rx * 1.04, ry: p.ry * 1.04, ang: p.ang });
    drawPoly(pts, 0.35);
  }
  brush.noWash();

  // Pass 2: Saturated Watercolor Plum Bodies (Aubergine, Damson, Garnet-Plum, Indigo-Claret)
  let plumWatercolors = ["#2b102f", "#3d1233", "#4c142e", "#221330"];
  for (let b = 0; b < 4; b++) {
    brush.noStroke();
    brush.fill(plumWatercolors[b], 185);
    brush.fillBleed(0.14, "in");
    brush.fillTexture(0.6, 0.5);
    for (let p of plums) {
      if (p.shadeIdx === b) {
        drawPoly(getPlumContour(p), 0.38);
      }
    }
    brush.noFill();
  }

  // Pass 3: Deep garnet & ruby core glow + powdery pastel wax bloom + suture cleft + quilting stitches
  for (let idx = 0; idx < plums.length; idx++) {
    let p = plums[idx];
    let ca = cos(p.ang);
    let sa = sin(p.ang);
    let toWorld = (lx, ly) => [
      p.x + lx * ca - ly * sa,
      p.y + lx * sa + ly * ca
    ];

    // Inner ruby-garnet translucent warmth on one side of the plum
    let warmC = toWorld(-p.rx * 0.18, -p.ry * 0.18);
    brush.set("glaze", idx % 2 === 0 ? "#6e183b" : "#571c4a", 1.5);
    brush.arc(warmC[0], warmC[1], p.ry * 0.55, p.ang - 45, p.ang + 135);

    // Epicuticular powdery wax bloom in SOFT PASTELS (dusty lavender, periwinkle, pale mauve-rose)
    let bloomCols = ["#b8a9c9", "#9fb0cc", "#d1adc2", "#c4b5d6"];
    let bloomCol = bloomCols[idx % 4];
    let b0 = toWorld(-p.rx * 0.38, -p.ry * 0.25);
    let b1 = toWorld(p.rx * 0.28, -p.ry * 0.12);
    brush.set("pastelBloom", bloomCol, 0.95);
    brush.line(b0[0], b0[1], b1[0], b1[1]);

    // Soft pastel colored-pencil frost bloom highlight
    brush.set("cpencil", "#dfd5eb", 0.65);
    brush.arc(warmC[0], warmC[1], p.ry * 0.42, p.ang + 160, p.ang + 310);

    // Dark wiped-bloom shadow crescent along lower belly
    brush.set("2B", "#140818", 0.9);
    brush.arc(p.x, p.y, p.ry * 0.88, p.ang + 15, p.ang + 165);

    // Longitudinal plum cleft / suture line from stem cavity to tip
    let s0 = toWorld(-p.rx * 0.88, 0);
    let sMid = toWorld(0, -p.ry * 0.32);
    let s1 = toWorld(p.rx * 0.92, 0);
    brush.set("2B", "#1d0921", 0.68);
    brush.spline([[s0[0], s0[1], 0.6], [sMid[0], sMid[1], 0.95], [s1[0], s1[1], 0.5]], 0.45);

    // Pastel lavender edge catching light along the cleft lip
    let sMidHi = toWorld(0, -p.ry * 0.24);
    brush.set("cpencil", bloomCol, 0.55);
    brush.spline([[s0[0], s0[1], 0.3], [sMidHi[0], sMidHi[1], 0.8], [s1[0], s1[1], 0.3]], 0.45);

    // Stem cavity dimple & russet scar at s0
    brush.set("pen", "#8c7562", 0.65);
    brush.circle(s0[0], s0[1], 2.2, 0.2);

    // Fine graphite quilting contour rings following the 3D form of the plum
    brush.set("quilter", "#6e6478", 0.42);
    brush.arc(p.x, p.y, p.ry * 0.68, p.ang - 150, p.ang - 20);
    brush.arc(p.x, p.y, p.ry * 0.46, p.ang + 25, p.ang + 155);
  }
}

// ============================================================================
// 5. CENTRE DIAMOND: HALVED RED CABBAGE
// ============================================================================

function drawRedCabbageDiamond() {
  // Vertices of the central diamond
  let vTop = [CX, CY - DIAMOND_R];
  let vRight = [CX + DIAMOND_R, CY];
  let vBottom = [CX, CY + DIAMOND_R];
  let vLeft = [CX - DIAMOND_R, CY];

  let diamondPts = [vTop, vRight, vBottom, vLeft];

  // Pass 1: Deep aubergine-charcoal foundation for the cut cabbage diamond
  brush.noStroke();
  brush.wash("#1f0a1d", 240);
  drawPoly(diamondPts, 0.04);
  brush.noWash();

  // Pass 2: 4 Quadrant Wedges (4 halved/quartered red cabbages fitted into the diamond)
  let quadrants = [
    { name: "N", p1: vLeft, p2: vTop, p3: [CX, CY - DIAMOND_R * 0.02], baseAng: -90, col: "#380f2e" },
    { name: "E", p1: vTop, p2: vRight, p3: [CX + DIAMOND_R * 0.02, CY], baseAng: 0, col: "#2e0d2b" },
    { name: "S", p1: vRight, p2: vBottom, p3: [CX, CY + DIAMOND_R * 0.02], baseAng: 90, col: "#421131" },
    { name: "W", p1: vBottom, p2: vLeft, p3: [CX - DIAMOND_R * 0.02, CY], baseAng: 180, col: "#330e2c" }
  ];

  // Saturated watercolor washes for the 4 triangular wedges of the diamond
  let wedges = [
    [ [CX, CY], vTop, vRight ],
    [ [CX, CY], vRight, vBottom ],
    [ [CX, CY], vBottom, vLeft ],
    [ [CX, CY], vLeft, vTop ]
  ];
  let wedgeCols = ["#360e2c", "#2d0c28", "#3f1130", "#300d2a"];

  for (let q = 0; q < 4; q++) {
    brush.noStroke();
    brush.fill(wedgeCols[q], 195);
    brush.fillBleed(0.16, "in");
    brush.fillTexture(0.7, 0.55);
    drawPoly(wedges[q], 0.05);
    brush.noFill();
  }

  // Pass 3: Hyperreal Red Cabbage Internal Architecture inside each of the 4 diamond wedges
  // Each wedge has:
  // - A tapering pale pastel lilac/blush core stem radiating from near the beet heart toward the outer diamond edge
  // - Thick structural white-lilac & pastel-rose midrib branches (cut leaf ribs)
  // - Tightly packed labyrinthine folded leaf layers (alternating dark aubergine, vivid magenta-plum, and glowing pastel lilac)
  // - Fine graphite looping quilting lines following every convoluted fold!

  for (let q = 0; q < 4; q++) {
    let w = wedges[q];
    let pCenter = w[0];
    let pCorner1 = w[1];
    let pCorner2 = w[2];
    let pMidOuter = [(pCorner1[0] + pCorner2[0]) * 0.5, (pCorner1[1] + pCorner2[1]) * 0.5];

    // Unit vectors in the wedge
    let ux = pMidOuter[0] - CX;
    let uy = pMidOuter[1] - CY;
    let uLen = sqrt(ux * ux + uy * uy);
    ux /= uLen;
    uy /= uLen;
    let vx = -uy; // Along outer diamond edge
    let vy = ux;

    // 3A. Concentric arched cabbage leaf bands filling the wedge from outside-in
    let numBands = 15;
    for (let b = numBands; b >= 1; b--) {
      let t = b / (numBands + 1); // 0 = center, 1 = outer diamond edge
      let rDist = lerp(BEET_R * 0.92, uLen - 8, t);
      let halfSpan = rDist * 0.94; // Since it's a 90-degree right triangle wedge, half-width = rDist

      let bandPts = [];
      let segs = 18;
      let freq = 4 + (b % 3) * 2;
      let amp = lerp(3.5, 9.5, sin(t * 180));

      for (let s = 0; s <= segs; s++) {
        let st = (s / segs) * 2 - 1; // -1 to +1 across the wedge
        let across = st * halfSpan;
        // Arched folding wave characteristic of halved red cabbage
        let arch = (1 - st * st) * 14 * sin(t * 180);
        let foldWave = sin(st * 180 * freq + b * 37) * amp + (noise(q * 10 + st * 3, b * 0.5) - 0.5) * 6;
        let radial = rDist + arch + foldWave * (1 - abs(st) * 0.35);

        let px = CX + ux * radial + vx * across;
        let py = CY + uy * radial + vy * across;

        // Clamp strictly inside the diamond and outside the central beet heart
        let dFromCenter = dist(px, py, CX, CY);
        if (dFromCenter > BEET_R * 0.88) {
          bandPts.push([px, py, 0.55 + 0.45 * sin(s * 30)]);
        }
      }

      if (bandPts.length >= 3) {
        // Dark aubergine shadow cavity between folds
        brush.set("2B", "#160414", 1.15);
        brush.spline(bandPts, 0.45);

        // Saturated plum-garnet or magenta leaf layer
        let midCol = b % 2 === 0 ? "#691749" : "#4f123d";
        brush.set("glaze", midCol, 1.1);
        brush.spline(bandPts, 0.45);

        // Glowing SOFT PASTEL cut cabbage vein (pale lilac, blush pink, icy lavender)
        let pastelVeins = ["#e6d3ed", "#f2e4f7", "#deb8d0", "#c9a7d6"];
        let veinCol = pastelVeins[(b + q) % 4];
        let veinWeight = (b % 3 === 0) ? 1.05 : 0.68;
        brush.set("cpencil", veinCol, veinWeight);
        brush.spline(bandPts, 0.48);

        // Bright crisp core edge on major ribs
        if (b % 3 === 0) {
          brush.set("pen", "#f7f0fa", 0.5);
          brush.spline(bandPts, 0.48);
        }

        // Fine graphite quilting stitch following the folded cabbage grain!
        for (let k = 0; k < bandPts.length - 1; k += 2) {
          drawLoopingStitchLine(
            bandPts[k][0], bandPts[k][1],
            bandPts[k + 1][0], bandPts[k + 1][1],
            5.5, 1.2, "#4a3347", 0.42
          );
        }
      }
    }

    // 3B. Thick branching pale pastel pith & primary midribs radiating from the wedge core
    for (let branch of [-0.45, 0, 0.45]) {
      let rStart = BEET_R * 0.96;
      let rEnd = uLen * (branch === 0 ? 0.88 : 0.78);
      let ribPts = [];
      for (let step = 0; step <= 8; step++) {
        let rt = step / 8;
        let r = lerp(rStart, rEnd, rt);
        let spread = branch * r * 0.82 + sin(rt * 240 + q * 45) * 8;
        ribPts.push([
          CX + ux * r + vx * spread,
          CY + uy * r + vy * spread,
          lerp(1.4, 0.25, rt)
        ]);
      }
      // Thick creamy pastel-lilac rib body
      brush.set("glaze", "#d9c2e3", 1.35);
      brush.spline(ribPts, 0.4);
      brush.set("cpencil", "#f6edf9", 0.95);
      brush.spline(ribPts, 0.4);
      // Graphite quilting seam down the center of the structural rib
      brush.set("quilter", "#523a54", 0.5);
      brush.spline(ribPts, 0.4);
    }
  }

  // Crisp cut outer rind of the red cabbage diamond
  for (let i = 0; i < 4; i++) {
    let p0 = diamondPts[i];
    let p1 = diamondPts[(i + 1) % 4];
    brush.set("glaze", "#24081f", 1.6);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
    brush.set("cpencil", "#d8bee0", 0.75);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
    drawLoopingStitchLine(p0[0], p0[1], p1[0], p1[1], 8, 1.8, "#b8a3c2", 0.55);
  }

  // 4 Cardinal seam lines where the 4 halved cabbage wedges meet
  let cardinals = [vTop, vRight, vBottom, vLeft];
  for (let c of cardinals) {
    brush.set("2B", "#140412", 1.1);
    brush.line(CX, CY, c[0], c[1]);
    drawLoopingStitchLine(CX, CY, c[0], c[1], 7, 1.5, "#9c82a6", 0.48);
  }
}

// ============================================================================
// 6. HEART OF THE DIAMOND: SINGLE GLOWING BEET
// ============================================================================

function drawGlowingBeetHeart() {
  // Subtle wet garnet juice halo bleeding slightly into the central cabbage seams
  brush.noStroke();
  brush.fill("#5c0b24", 110);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.6, 0.4);
  brush.circle(CX, CY, BEET_R * 1.12, 0.12);
  brush.noFill();

  // Dark shadow under the beet's outer rind
  brush.noStroke();
  brush.wash("#17040b", 230);
  brush.circle(CX + 2, CY + 3, BEET_R * 1.03, 0.08);
  brush.noWash();

  // 4 Delicate curling beet rootlet tails extending slightly into the 4 cardinal cabbage seams
  let rootAngles = [-90, 0, 90, 180];
  for (let a of rootAngles) {
    let rPts = [];
    for (let i = 0; i <= 6; i++) {
      let d = BEET_R * 0.95 + i * 7.5;
      let wiggle = sin(i * 55 + a) * 3.2;
      rPts.push([
        CX + cos(a) * d - sin(a) * wiggle,
        CY + sin(a) * d + cos(a) * wiggle,
        lerp(1.1, 0.15, i / 6)
      ]);
    }
    brush.set("2B", "#2b0914", 0.85);
    brush.spline(rPts, 0.45);
    brush.set("cpencil", "#9e5266", 0.45);
    brush.spline(rPts, 0.45);
  }

  // Saturated Watercolor Base of the Beet Heart (Deep Oxblood-Garnet & Luminous Ruby)
  brush.noStroke();
  brush.fill("#4a081c", 220);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.65, 0.55);
  brush.circle(CX, CY, BEET_R, 0.07);
  brush.noFill();

  brush.noStroke();
  brush.fill("#7d0e2f", 190);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.55, 0.45);
  brush.circle(CX, CY, BEET_R * 0.84, 0.06);
  brush.noFill();

  // Concentric Vascular Target Rings (Alternating Saturated Garnet/Crimson & Glowing Soft Pastel Rose/Blush)
  let rings = [
    { r: 0.94, col: "#2e0814", type: "rind", w: 1.4 },
    { r: 0.86, col: "#e090a6", type: "pastel", w: 0.95 },
    { r: 0.77, col: "#690b27", type: "garnet", w: 1.3 },
    { r: 0.68, col: "#f0b4c4", type: "pastel", w: 1.05 },
    { r: 0.58, col: "#851032", type: "garnet", w: 1.25 },
    { r: 0.48, col: "#f7cbd7", type: "pastel", w: 1.1 },
    { r: 0.38, col: "#991339", type: "garnet", w: 1.15 },
    { r: 0.28, col: "#fadce4", type: "pastel", w: 1.05 },
    { r: 0.18, col: "#780d2c", type: "garnet", w: 1.0 },
    { r: 0.09, col: "#fceef2", type: "pastel", w: 0.95 }
  ];

  for (let ring of rings) {
    let rad = BEET_R * ring.r;
    let pts = [];
    let steps = 28;
    for (let i = 0; i <= steps; i++) {
      let ang = (i / steps) * 360;
      let n = (noise(cos(ang) * 1.5 + ring.r * 5, sin(ang) * 1.5 + ring.r * 5) - 0.5) * 3.5;
      let rr = rad + n;
      pts.push([CX + cos(ang) * rr, CY + sin(ang) * rr, 0.8 + 0.2 * sin(ang * 2)]);
    }

    if (ring.type === "pastel") {
      // Glowing soft pastel coral-rose / shell-pink vascular ring
      brush.set("glaze", ring.col, ring.w * 1.15);
      brush.spline(pts, 0.45);
      brush.set("cpencil", "#fff0f3", ring.w * 0.75);
      brush.spline(pts, 0.45);

      // Fine graphite looping quilting stitch right along the glowing ring
      for (let k = 0; k < pts.length - 1; k += 2) {
        drawLoopingStitchLine(
          pts[k][0], pts[k][1],
          pts[k + 1][0], pts[k + 1][1],
          4.5, 1.0, "#5c1a2e", 0.38
        );
      }
    } else {
      brush.set("glaze", ring.col, ring.w * 1.3);
      brush.spline(pts, 0.45);
      brush.set("2B", "#330512", 0.55);
      brush.spline(pts, 0.45);
    }
  }

  // Fine radial cellular vascular rays radiating from the beet's glowing heart
  let numRays = 56;
  for (let i = 0; i < numRays; i++) {
    let ang = (i / numRays) * 360 + random(-2, 2);
    let r0 = BEET_R * random(0.06, 0.25);
    let r1 = BEET_R * random(0.75, 0.95);
    let x0 = CX + cos(ang) * r0;
    let y0 = CY + sin(ang) * r0;
    let x1 = CX + cos(ang) * r1;
    let y1 = CY + sin(ang) * r1;

    if (i % 2 === 0) {
      brush.set("cpencil", "#f2b6c6", 0.38);
    } else {
      brush.set("quilter", "#521024", 0.35);
    }
    brush.line(x0, y0, x1, y1);
  }

  // Central luminous heart point
  brush.set("cpencil", "#fff5f7", 0.9);
  brush.circle(CX, CY, 4.5, 0.15);
  brush.set("quilter", "#4a0c1e", 0.5);
  brush.circle(CX, CY, 7.5, 0.12);
}

// ============================================================================
// 7. MASTER GRAPHITE QUILTING OVERLAY & SOBER BORDER BINDING
// ============================================================================

function drawMasterQuiltingOverlay() {
  // Double-stitched graphite & soft pastel basting lines along all architectural quilt boundaries

  // 1. Outer Square Frame Binding (around the Black Kale border)
  let outerCorners = [
    [OUTER_MIN, OUTER_MIN],
    [OUTER_MAX, OUTER_MIN],
    [OUTER_MAX, OUTER_MAX],
    [OUTER_MIN, OUTER_MAX],
    [OUTER_MIN, OUTER_MIN]
  ];
  drawRunningStitchCurve(outerCorners, 9, 5, "#8fa89e", 0.58);

  let outerInset = 10;
  for (let i = 0; i < 4; i++) {
    let p0 = outerCorners[i];
    let p1 = outerCorners[i + 1];
    drawLoopingStitchLine(p0[0], p0[1], p1[0], p1[1], 9, 2.0, "#6c827b", 0.48);
  }

  // 2. Inner Square Seam (between Black Kale border and Deep Plum band)
  let innerCorners = [
    [INNER_MIN, INNER_MIN],
    [INNER_MAX, INNER_MIN],
    [INNER_MAX, INNER_MAX],
    [INNER_MIN, INNER_MAX],
    [INNER_MIN, INNER_MIN]
  ];
  drawRunningStitchCurve(innerCorners, 8, 4.5, "#a99eb8", 0.55);
  for (let i = 0; i < 4; i++) {
    let p0 = innerCorners[i];
    let p1 = innerCorners[i + 1];
    drawLoopingStitchLine(p0[0], p0[1], p1[0], p1[1], 8.5, 1.8, "#7c738c", 0.45);
  }

  // 3. Subtle diagonal quilting threads across the 4 Plum Corner Triangles
  let cornerBoxes = [
    { cx: INNER_MIN, cy: INNER_MIN, dx: 1, dy: 1 },
    { cx: INNER_MAX, cy: INNER_MIN, dx: -1, dy: 1 },
    { cx: INNER_MAX, cy: INNER_MAX, dx: -1, dy: -1 },
    { cx: INNER_MIN, cy: INNER_MAX, dx: 1, dy: -1 }
  ];
  for (let cb of cornerBoxes) {
    for (let d = 55; d <= 310; d += 54) {
      let x1 = cb.cx + cb.dx * d;
      let y1 = cb.cy;
      let x2 = cb.cx;
      let y2 = cb.cy + cb.dy * d;
      drawLoopingStitchLine(x1, y1, x2, y2, 9, 1.4, "#594e66", 0.36);
    }
  }

  // 4. Outer Table Margin Framing Lines (Sober Draftsman Border)
  let margin = 46;
  brush.set("2H", "#3a3f4a", 0.45);
  brush.line(margin, margin, W - margin, margin);
  brush.line(W - margin, margin, W - margin, H - margin);
  brush.line(W - margin, H - margin, margin, H - margin);
  brush.line(margin, H - margin, margin, margin);

  // Corner registration crosshairs in fine graphite
  let regPts = [
    [margin, margin],
    [W - margin, margin],
    [W - margin, H - margin],
    [margin, H - margin]
  ];
  brush.set("quilter", "#6c7382", 0.5);
  for (let rp of regPts) {
    brush.line(rp[0] - 12, rp[1], rp[0] + 12, rp[1]);
    brush.line(rp[0], rp[1] - 12, rp[0], rp[1] + 12);
    brush.circle(rp[0], rp[1], 5, 0.1);
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7391);
  noiseSeed(7391);

  // Custom fine technical pens and highlight nibs calibrated for 1200x1200 hyperrealism
  brush.add("tech_003", {
    type: "default",
    weight: 0.13,
    scatter: 0.015,
    sharpness: 0.94,
    grain: 0.88,
    opacity: 205,
    spacing: 0.45,
    pressure: [0.85, 1.0, 0.85],
    noise: 0.25
  });

  brush.add("tech_005", {
    type: "default",
    weight: 0.19,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 0.86,
    opacity: 225,
    spacing: 0.45,
    pressure: [0.8, 1.0, 0.8],
