function draw() {
  translate(-width / 2, -height / 2);

  // Warm antique ivory paper ground
  background("#f3ece0");

  // ---------------------------------------------------------------------------
  // 1. BUILD EXACT UNFOLDED ORIGAMI CRANE MESH + FOIL SUB-FACETS
  // ---------------------------------------------------------------------------
  const mesh = buildOrigamiCraneFoilMesh();

  // ---------------------------------------------------------------------------
  // 2. DRAW DARK TABLE GROUND & CAST SHADOW AT TORN / CRUMPLED EDGES
  // ---------------------------------------------------------------------------
  drawTableMarginAndTears(mesh);

  // ---------------------------------------------------------------------------
  // 3. SUBTLE METALLIC BASE WASHES (BATCHED BY TONE FOR PERFORMANCE)
  // ---------------------------------------------------------------------------
  drawBatchedMetallicUnderwashes(mesh);

  // ---------------------------------------------------------------------------
  // 4. TECHNICAL-PEN HATCHING ACROSS ALL FACETS (SHIFTING LIKE A FACETED GEM)
  // ---------------------------------------------------------------------------
  drawFacetTechnicalHatching(mesh);

  // ---------------------------------------------------------------------------
  // 5. ANISOTROPIC FOIL MILL-GRAIN & SURFACE MICRO-SCRATCHES
  // ---------------------------------------------------------------------------
  drawFoilMillGrain(mesh);

  // ---------------------------------------------------------------------------
  // 6. MOUNTAIN & VALLEY CREASE LATTICE, MICRO-BUCKLES & SPECULAR RIDGES
  // ---------------------------------------------------------------------------
  drawCreaseNetworkAndMicroBuckles(mesh);

  // ---------------------------------------------------------------------------
  // 7. TORN & CRUMPLED PERIMETER RIMS AND SERRATED CUTTER EDGE
  // ---------------------------------------------------------------------------
  drawCrumpledAndTornEdges(mesh);

  noLoop();
}

// =============================================================================
// GEOMETRY & PHYSICS: UNFOLDED ORIGAMI CRANE (TSURU) IN ALUMINIUM FOIL
// =============================================================================
function buildOrigamiCraneFoilMesh() {
  const vertices = [];
  const vertMap = new Map();
  const facets = [];
  const creases = [];
  const creaseSet = new Set();

  // Deduplicate vertices in normalized square [-1, 1] x [-1, 1]
  function getVert(u, v) {
    const ku = Math.round(u * 2000);
    const kv = Math.round(v * 2000);
    const key = `${ku}_${kv}`;
    if (vertMap.has(key)) return vertMap.get(key);
    const idx = vertices.length;
    vertices.push({ u, v, x: 0, y: 0, z: 0 });
    vertMap.set(key, idx);
    return idx;
  }

  function addCreaseSeg(i1, i2, type, octantId) {
    if (i1 === i2) return;
    const a = Math.min(i1, i2);
    const b = Math.max(i1, i2);
    const key = `${a}_${b}`;
    if (creaseSet.has(key)) return;
    creaseSet.add(key);
    creases.push({ a: i1, b: i2, type, octantId });
  }

  // Tear definitions around the foil edges:
  // Each tear cuts inward from an edge and parts the foil lips slightly
  const tears = [
    { u0: 0.26, v0: -1.0, u1: 0.23, v1: -0.84, width: 0.042, side: "top" },
    { u0: 1.0, v0: -0.24, u1: 0.85, v1: -0.20, width: 0.040, side: "right" },
    { u0: -1.0, v0: 0.33, u1: -0.84, v1: 0.29, width: 0.046, side: "left" },
    { u0: -0.38, v0: 1.0, u1: -0.35, v1: 0.86, width: 0.038, side: "bottom" }
  ];

  // Bird-base constant: tan(22.5 deg) = sqrt(2) - 1
  const k = Math.SQRT2 - 1; // ~0.41421356
  const kHalf = k * 0.5;    // ~0.20710678
  const k2 = 0.655;         // 11.25 deg neck/tail narrowing crease intercept on axis

  // 8 octants of the square [-1, 1] x [-1, 1]:
  // Quadrant (-1,-1) [Top-Left] = Head & Neck
  // Quadrant (1, 1)  [Bottom-Right] = Tail
  // Quadrants (1,-1) [Top-Right] & (-1,1) [Bottom-Left] = Left & Right Wings
  const octants = [
    { qx: -1, qy: -1, swap: false, role: "head", octId: 0 },
    { qx: -1, qy: -1, swap: true,  role: "head", octId: 1 },
    { qx:  1, qy: -1, swap: false, role: "wing_ur", octId: 2 },
    { qx:  1, qy: -1, swap: true,  role: "wing_ur", octId: 3 },
    { qx:  1, qy:  1, swap: false, role: "tail", octId: 4 },
    { qx:  1, qy:  1, swap: true,  role: "tail", octId: 5 },
    { qx: -1, qy:  1, swap: false, role: "wing_ll", octId: 6 },
    { qx: -1, qy:  1, swap: true,  role: "wing_ll", octId: 7 }
  ];

  for (const oct of octants) {
    // Transform canonical octant (0 <= b <= a <= 1) into square coordinates (u, v)
    function toUV(a, b) {
      const lx = oct.swap ? b : a;
      const ly = oct.swap ? a : b;
      return [oct.qx * lx, oct.qy * ly];
    }

    function V(a, b) {
      const [u, v] = toUV(a, b);
      return getVert(u, v);
    }

    // 1. Axis points (b = 0)
    const A = [
      V(0.0, 0.0),
      V(kHalf, 0.0),
      V(k, 0.0),
      V(0.535, 0.0),
      V(k2, 0.0),
      V(0.78, 0.0),
      V(0.89, 0.0),
      V(0.955, 0.0),
      V(1.0, 0.0)
    ];

    // 2. Diagonal points (b = a)
    const D = [
      V(0.0, 0.0),
      V(0.11, 0.11),
      V(kHalf, kHalf),
      V(0.31, 0.31),
      V(k, k),
      V(0.54, 0.54),
      V(0.66, 0.66),
      V(0.755, 0.755), // Head reverse fold 1
      V(0.835, 0.835), // Head reverse fold 2 (beak crimp)
      V(0.905, 0.905),
      V(0.955, 0.955),
      V(1.0, 1.0)
    ];

    // 3. 22.5-degree Bird-Base main crease: from A[2](k,0) to D[11](1,1)
    const tB = [0, 0.15, 0.31, 0.48, 0.63, 0.75, 0.84, 0.91, 0.96, 1.0];
    const B = tB.map(t => V(k + t * (1 - k), t));

    // 4. Inner petal & 11.25-degree narrowing line:
    // Starts on vertical petal crease (a = k, b = 0.205) and runs to corner (1,1)
    const I0 = V(k, 0.205);
    const tNin = [0, 0.18, 0.37, 0.55, 0.70, 0.81, 0.89, 0.95, 1.0];
    const Nin = tNin.map(t => V(k + t * (1 - k), 0.205 + t * (1 - 0.205)));

    // 5. Outer 11.25-degree narrowing crease: from A[4](k2,0) to D[11](1,1)
    const tNout = [0, 0.18, 0.36, 0.54, 0.70, 0.82, 0.90, 0.96, 1.0];
    const Nout = tNout.map(t => V(k2 + t * (1 - k2), t));

    // 6. Outer flap mid-rib from A[6](0.89, 0) toward outer edge E
    const tMid = [0, 0.22, 0.45, 0.68, 0.85, 0.94, 1.0];
    const M = tMid.map(t => V(0.89 + t * 0.11, t * 0.86));

    // 7. Outer Sheet Edge (a = 1.0, b from 0 to 1)
    const tEdge = [0, 0.13, 0.26, 0.39, 0.52, 0.65, 0.76, 0.86, 0.94, 1.0];
    const E = tEdge.map(t => V(1.0, t));

    // Record structural origami creases
    for (let i = 0; i < A.length - 1; i++) {
      addCreaseSeg(A[i], A[i + 1], i < 2 ? "valley_primary" : "mountain_primary", oct.octId);
    }
    for (let i = 0; i < D.length - 1; i++) {
      const cType = (oct.role === "head" || oct.role === "tail")
        ? (i < 4 ? "mountain_primary" : "valley_primary")
        : "mountain_primary";
      addCreaseSeg(D[i], D[i + 1], cType, oct.octId);
    }
    for (let i = 0; i < B.length - 1; i++) {
      addCreaseSeg(B[i], B[i + 1], "mountain_primary", oct.octId);
    }

    // Central diamond crease & petal fold creases
    addCreaseSeg(A[2], D[2], "valley_primary", oct.octId);
    addCreaseSeg(A[1], D[1], "mountain_secondary", oct.octId);
    addCreaseSeg(A[2], I0, "valley_primary", oct.octId);
    addCreaseSeg(I0, D[4], "valley_primary", oct.octId);
    addCreaseSeg(D[2], I0, "mountain_secondary", oct.octId);

    // Narrowing creases (sharp in head/tail, softer secondary stress in wings)
    const narrowType = (oct.role === "head" || oct.role === "tail") ? "valley_primary" : "valley_secondary";
    const narrowInType = (oct.role === "head" || oct.role === "tail") ? "mountain_primary" : "mountain_secondary";
    for (let i = 0; i < Nout.length - 1; i++) addCreaseSeg(Nout[i], Nout[i + 1], narrowType, oct.octId);
    for (let i = 0; i < Nin.length - 1; i++) addCreaseSeg(Nin[i], Nin[i + 1], narrowInType, oct.octId);

    // Wing-fold / Neck-reverse-fold transverse creases
    if (oct.role === "head" || oct.role === "tail") {
      // Inside reverse fold crease at base of neck/tail
      addCreaseSeg(A[4], B[2], "mountain_primary", oct.octId);
      addCreaseSeg(B[2], Nin[1], "valley_primary", oct.octId);
      addCreaseSeg(Nin[1], D[3], "mountain_primary", oct.octId);
      if (oct.role === "head") {
        // Head reverse-fold crown & beak crimp
        addCreaseSeg(D[7], Nin[5], "valley_primary", oct.octId);
        addCreaseSeg(Nin[5], B[6], "mountain_primary", oct.octId);
        addCreaseSeg(D[8], Nin[6], "mountain_primary", oct.octId);
        addCreaseSeg(Nin[6], B[7], "valley_primary", oct.octId);
      }
    } else {
      // Wing down-fold and secondary wing camber crease
      addCreaseSeg(A[2], B[2], "valley_primary", oct.octId);
      addCreaseSeg(B[2], Nin[2], "valley_primary", oct.octId);
      addCreaseSeg(Nin[2], D[5], "valley_primary", oct.octId);
      addCreaseSeg(A[4], B[4], "mountain_secondary", oct.octId);
      addCreaseSeg(B[4], Nin[4], "mountain_secondary", oct.octId);
      addCreaseSeg(Nin[4], D[6], "mountain_secondary", oct.octId);
    }

    // Helper to add a facet or sub-faceted crinkle cluster
    function addTri(v0, v1, v2, zone, biasAngle, subCrinkle = false) {
      if (v0 === v1 || v1 === v2 || v2 === v0) return;
      const p0 = vertices[v0], p1 = vertices[v1], p2 = vertices[v2];
      const cu = (p0.u + p1.u + p2.u) / 3;
      const cv = (p0.v + p1.v + p2.v) / 3;
      const sideLen = Math.hypot(p1.u - p0.u, p1.v - p0.v) +
                      Math.hypot(p2.u - p1.u, p2.v - p1.v) +
                      Math.hypot(p0.u - p2.u, p0.v - p2.v);

      if (subCrinkle && sideLen > 0.36) {
        // Insert interior foil crinkle vertex to break larger origami planes into sub-facets
        const h1 = Math.sin(cu * 37.3 + cv * 53.7) * 0.08;
        const h2 = Math.cos(cu * 43.1 - cv * 29.9) * 0.08;
        const w0 = 0.34 + h1, w1 = 0.33 + h2, w2 = 1.0 - w0 - w1;
        const mu = p0.u * w0 + p1.u * w1 + p2.u * w2;
        const mv = p0.v * w0 + p1.v * w1 + p2.v * w2;
        const vm = getVert(mu, mv);
        addCreaseSeg(v0, vm, "crinkle", oct.octId);
        addCreaseSeg(v1, vm, "crinkle", oct.octId);
        addCreaseSeg(v2, vm, "crinkle", oct.octId);
        facets.push({ verts: [v0, v1, vm], zone, oct, biasAngle: biasAngle + 14 });
        facets.push({ verts: [v1, v2, vm], zone, oct, biasAngle: biasAngle - 18 });
        facets.push({ verts: [v2, v0, vm], zone, oct, biasAngle: biasAngle + 32 });
      } else {
        facets.push({ verts: [v0, v1, v2], zone, oct, biasAngle });
      }
    }

    function addStrip(chain1, chain2, zone, baseBias, crinkleLarge) {
      let i = 0, j = 0;
      while (i < chain1.length - 1 || j < chain2.length - 1) {
        if (i < chain1.length - 1 && (j === chain2.length - 1 || i * (chain2.length - 1) <= j * (chain1.length - 1))) {
          addTri(chain1[i], chain1[i + 1], chain2[j], zone, baseBias + (i * 23) % 55, crinkleLarge);
          if (j > 0 && j < chain2.length - 1) {
            addCreaseSeg(chain1[i + 1], chain2[j], "crinkle", oct.octId);
          }
          i++;
        } else {
          addTri(chain1[i], chain2[j + 1], chain2[j], zone, baseBias - (j * 29) % 55, crinkleLarge);
          if (i > 0 && i < chain1.length - 1) {
            addCreaseSeg(chain1[i], chain2[j + 1], "crinkle", oct.octId);
          }
          j++;
        }
      }
    }

    // Build Central Diamond & Petal Base triangles
    addTri(A[0], A[1], D[1], "center_diamond", 15, false);
    addTri(A[1], D[2], D[1], "center_diamond", -22, false);
    addTri(A[1], A[2], D[2], "center_diamond", 35, true);

    addTri(D[2], A[2], I0, "petal_base", -40, false);
    addTri(D[2], I0, D[3], "petal_base", 18, false);
    addTri(D[3], I0, D[4], "petal_base", -12, true);

    // Strip between Diagonal (D[4..11]) and Inner Narrowing Line (Nin[0..8])
    addStrip(D.slice(4), Nin, oct.role + "_diag_band", 25, true);

    // Strip between Inner Narrowing Line (Nin[0..8]) and Bird-Base 22.5 Line (B[0..9])
    addStrip(Nin, B, oct.role + "_bird_in", -30, true);

    // Strip between Bird-Base 22.5 Line (B[0..9]) and Axis / Outer Narrowing Line
    addTri(A[2], A[3], B[1], oct.role + "_bird_out", 42, false);
    addTri(A[3], A[4], B[1], oct.role + "_bird_out", -18, false);
    addTri(A[4], B[2], B[1], oct.role + "_bird_out", 12, true);
    addStrip(B.slice(2), Nout, oct.role + "_bird_out", -45, true);

    // Strip between Outer Narrowing Line (Nout[0..8]) and Mid-Rib (A[4..6] + M[0..6])
    const axisToM = [A[4], A[5], A[6], ...M.slice(1)];
    addStrip(Nout, axisToM, oct.role + "_outer_flap", 20, true);

    // Crumpled Perimeter Strip between (A[6..8] + M[0..6]) and Outer Edge (E[0..9])
    const mToEdge = [A[6], A[7], A[8], ...E.slice(1)];
    addStrip(M, mToEdge, "edge_crumple", -35, true);
  }

  // ---------------------------------------------------------------------------
  // APPLY 2D HAND-FLATTENED WARPING, EDGE CRUMPLING & 3D CREASE RELIEF
  // ---------------------------------------------------------------------------
  const margin = 66;
  const halfSpan = (1200 - margin * 2) * 0.5;
  const cx = 600;
  const cy = 600;

  for (let i = 0; i < vertices.length; i++) {
    const v = vertices[i];
    let u = v.u;
    let w = v.v;

    // Slight overall rotation & hand-flattened asymmetry of the square sheet
    const rotRad = 0.018;
    const ru = u * Math.cos(rotRad) - w * Math.sin(rotRad);
    const rw = u * Math.sin(rotRad) + w * Math.cos(rotRad);

    // Edge distance (0 at center, 1 at boundary)
    const edgeMetric = Math.max(Math.abs(u), Math.abs(w));
    const isBoundary = edgeMetric > 0.995;

    // Organic foil pinch near center and along creases
    const n1 = noise(u * 2.4 + 10, w * 2.4 + 10) - 0.5;
    const n2 = noise(u * 6.5 + 30, w * 6.5 + 30) - 0.5;
    const n3 = noise(u * 14.0 + 70, w * 14.0 + 70) - 0.5;

    let du = n1 * 0.018 + n2 * 0.009;
    let dw = n1 * 0.018 - n2 * 0.009;

    // Crumpled outer edge distortion
    if (edgeMetric > 0.82) {
      const tCrumple = (edgeMetric - 0.82) / 0.18;
      const jag = (noise(u * 18 + 120, w * 18 + 120) - 0.5) * 0.038 * tCrumple * tCrumple;
      const pinch = Math.sin(u * 29 + w * 31) * 0.012 * tCrumple;
      du += jag - Math.sign(u) * Math.abs(pinch) * 0.7;
      dw += jag - Math.sign(w) * Math.abs(pinch) * 0.7;
    }

    // Tear separation displacement near the 4 edge tears
    for (const tear of tears) {
      const distToTear = distToSegment(u, w, tear.u0, tear.v0, tear.u1, tear.v1);
      if (distToTear < tear.width * 2.2) {
        const pull = Math.pow(1 - distToTear / (tear.width * 2.2), 2) * 0.018;
        const sideSign = ((u - tear.u1) * (tear.v0 - tear.v1) - (w - tear.v1) * (tear.u0 - tear.u1)) >= 0 ? 1 : -1;
        du += sideSign * (tear.v0 - tear.v1) * pull * 3.5;
        dw -= sideSign * (tear.u0 - tear.u1) * pull * 3.5;
      }
    }

    v.x = cx + (ru + du) * halfSpan;
    v.y = cy + (rw + dw) * halfSpan;
    v.isBoundary = isBoundary;
    v.edgeMetric = edgeMetric;

    // Compute 3D height z(u, w) from origami fold memory + crinkles
    const absU = Math.abs(u), absW = Math.abs(w);
    const diagDist = Math.abs(absU - absW) / Math.SQRT2;
    const axisDist = Math.min(absU, absW);
    const birdDist = Math.abs(absW - (absU - k) / (1 - k) * absW);

    // Sawtooth origami relief waves + high-frequency foil crinkle
    let z = 0;
    z += Math.exp(-diagDist * 9.0) * ((u * w > 0) ? -0.14 : 0.16);
    z -= Math.exp(-axisDist * 10.0) * 0.12;
    z += Math.sin(absU * 14.0 - absW * 11.0) * 0.045;
    z += n2 * 0.09 + n3 * 0.065;
    if (edgeMetric > 0.85) {
      z += Math.sin(u * 35 + w * 35) * 0.09 * ((edgeMetric - 0.85) / 0.15);
    }
    v.z = z;
  }

  // ---------------------------------------------------------------------------
  // COMPUTE FACET NORMALS, RAKING LIGHT, HATCH ANGLES & REFLECTIONS
  // ---------------------------------------------------------------------------
  // Low raking light coming from upper-left at grazing ~17 degree elevation
  const lx = -0.80, ly = -0.53, lz = 0.28;
  const lLen = Math.hypot(lx, ly, lz);
  const L = [lx / lLen, ly / lLen, lz / lLen];

  // View vector straight above [0, 0, 1]; Half-vector H = normalize(L + V)
  const hx = L[0], hy = L[1], hz = L[2] + 1.0;
  const hLen = Math.hypot(hx, hy, hz);
  const H = [hx / hLen, hy / hLen, hz / hLen];

  for (let idx = 0; idx < facets.length; idx++) {
    const f = facets[idx];
    const p0 = vertices[f.verts[0]];
    const p1 = vertices[f.verts[1]];
    const p2 = vertices[f.verts[2]];

    f.pts = [
      [p0.x, p0.y],
      [p1.x, p1.y],
      [p2.x, p2.y]
    ];

    const cu = (p0.u + p1.u + p2.u) / 3;
    const cv = (p0.v + p1.v + p2.v) / 3;
    const cxF = (p0.x + p1.x + p2.x) / 3;
    const cyF = (p0.y + p1.y + p2.y) / 3;
    f.cu = cu;
    f.cv = cv;
    f.cx = cxF;
    f.cy = cyF;

    // Check if facet falls inside one of the V-shaped edge tears
    let inTear = false;
    for (const tear of tears) {
      const dTear = distToSegment(cu, cv, tear.u0, tear.v0, tear.u1, tear.v1);
      const tProj = projOnSegment(cu, cv, tear.u0, tear.v0, tear.u1, tear.v1);
      // V-shaped taper: wider at outer edge (tProj=0), zero at tip (tProj=1)
      const localWidth = tear.width * (1.0 - tProj * 0.85);
      if (dTear < localWidth) {
        inTear = true;
        break;
      }
    }
    f.isTearGap = inTear;

    // Polygon area check
    const area = 0.5 * Math.abs(
      (p1.x - p0.x) * (p2.y - p0.y) - (p2.x - p0.x) * (p1.y - p0.y)
    );
    f.area = area;

    // 3D normal from vertex heights + crisp origami facet tilt discontinuity
    const ux = p1.u - p0.u, uy = p1.v - p0.v, uz = p1.z - p0.z;
    const vx = p2.u - p0.u, vy = p2.v - p0.v, vz = p2.z - p0.z;
    let nx = uy * vz - uz * vy;
    let ny = uz * vx - ux * vz;
    let nz = ux * vy - uy * vx;
    if (nz < 0) {
      nx = -nx;
      ny = -ny;
      nz = -nz;
    }

    // Add deterministic origami ridge slope based on which octant & strip the facet belongs to
    const octSign = (f.oct.swap ? 1 : -1) * f.oct.qx * f.oct.qy;
    const facetHash = Math.sin(idx * 12.9898 + cu * 78.233 - cv * 43.123) * 43758.5453;
    const rand01 = facetHash - Math.floor(facetHash);

    const tiltMag = 0.35 + 0.45 * rand01;
    const tiltAng = (f.biasAngle + octSign * 38 + Math.atan2(cv, cu) * 180 / Math.PI) * Math.PI / 180;
    nx = nx * 2.2 + Math.cos(tiltAng) * tiltMag;
    ny = ny * 2.2 + Math.sin(tiltAng) * tiltMag;
    nz = Math.max(0.25, Math.abs(nz) * 3.5 + 0.42);

    const nLen = Math.hypot(nx, ny, nz);
    nx /= nLen;
    ny /= nLen;
    nz /= nLen;
    f.nx = nx;
    f.ny = ny;
    f.nz = nz;

    // Raking light reflection & metallic BRDF (diffuse + sharp specular lobes)
    const ndotl = Math.max(0, nx * L[0] + ny * L[1] + nz * L[2]);
    const ndoth = Math.max(0, nx * H[0] + ny * H[1] + nz * H[2]);
    const specBroad = Math.pow(ndoth, 6);
    const specSharp = Math.pow(ndoth, 28);

    // Quantize / sharpen contrast across creases for authentic metallic foil snap
    let tone = 0.08 + 0.52 * Math.pow(ndotl, 0.85) + 0.32 * specBroad + 0.25 * specSharp;
    // Slight dark pinch near dense origami vertices (center & bird-base hinges)
    const distCenter = Math.hypot(cu, cv);
    if (distCenter < 0.18) {
      tone *= 0.78 + 0.22 * (distCenter / 0.18);
    }
    f.tone = constrain(tone, 0.03, 0.99);

    // Hatching angle shifts facet by facet like a cut gem, anchored to 3D normal azimuth
    const slopeAngle = Math.atan2(ny, nx) * 180 / Math.PI;
    f.hatchAngle = (slopeAngle + f.biasAngle * 0.85 + (idx % 5) * 19) % 180;

    // -------------------------------------------------------------------------
    // EVALUATE WARPED REFLECTIONS: (1) RED MUG & (2) SUNLIT WINDOW
    // -------------------------------------------------------------------------
    // Reflection projection combines facet position (cu, cv) and normal tilt (nx, ny)
    const rx = cu + nx * 0.36;
    const ry = cv + ny * 0.36;

    // 1. RED MUG REFLECTION (warped across lower-right / mid-right planes)
    // Mug sits off the right-lower side; reflected in facets around u in [0.05..0.78], v in [-0.08..0.68]
    const mugU = 0.43, mugV = 0.29;
    // Rotate into mug's perspective frame
    const mu = (rx - mugU) * 0.92 + (ry - mugV) * 0.38;
    const mv = -(rx - mugU) * 0.38 + (ry - mugV) * 0.92;

    const inMugBody = Math.abs(mu) < 0.21 && mv > -0.24 && mv < 0.25 &&
                      (Math.hypot(mu / 0.21, (mv - 0.22) / 0.08) < 1.0 || mv < 0.22);
    const inMugRim = Math.hypot(mu / 0.205, (mv + 0.22) / 0.075) < 1.05;
    const handleDist = Math.hypot((mu - 0.21) / 0.11, (mv - 0.01) / 0.14);
    const inMugHandle = mu > 0.15 && handleDist < 1.05 && handleDist > 0.48;

    f.reflection = "none";
    f.reflStrength = 0;

    if ((inMugBody || inMugRim || inMugHandle) && cu > -0.02 && cv > -0.18 && f.tone > 0.12 && f.tone < 0.92) {
      if (inMugRim && Math.hypot(mu / 0.16, (mv + 0.22) / 0.05) < 0.85) {
        // Warm porcelain interior rim of the mug
        f.reflection = "mug_rim";
        f.reflStrength = 0.65;
      } else {
        // Warm glazed red ceramic body or handle
        f.reflection = "mug_red";
        // Cylindrical shading across the warped mug reflection
        const cylHighlight = Math.exp(-Math.pow((mu + 0.08) / 0.07, 2));
        f.reflStrength = constrain(0.45 + 0.45 * (1.0 - Math.abs(mu) * 2.2), 0.28, 0.88);
        f.mugSpec = cylHighlight > 0.55;
      }
    }

    // 2. WINDOW REFLECTION (warped across upper-left / center-top planes)
    // Four-pane sunlit window reflected in facets tilting toward upper-left sky
    if (f.reflection === "none" && cu > -0.78 && cu < 0.32 && cv > -0.82 && cv < 0.18) {
      const winU = -0.26, winV = -0.34;
      // Perspective shear of window reflection
      const wu = (rx - winU) * 0.88 - (ry - winV) * 0.32 + 0.12 * cv;
      const wv = (rx - winU) * 0.26 + (ry - winV) * 0.94;

      if (Math.abs(wu) < 0.31 && Math.abs(wv) < 0.26) {
        // Check window mullions (crossbars at wu ~ 0 and wv ~ 0)
        const onMullion = Math.abs(wu) < 0.032 || Math.abs(wv) < 0.030;
        if (onMullion) {
          f.reflection = "window_mullion";
          f.reflStrength = 0.6;
        } else if (f.tone > 0.28) {
          f.reflection = "window_pane";
          f.reflStrength = constrain(0.5 + 0.4 * f.tone, 0.4, 0.9);
        }
      }
    }
  }

  return { vertices, facets, creases, tears };
}

function distToSegment(px, py, x1, y1, x2, y2) {
  const dx = x2 - x1, dy = y2 - y1;
  const len2 = dx * dx + dy * dy;
  if (len2 === 0) return Math.hypot(px - x1, py - y1);
  let t = ((px - x1) * dx + (py - y1) * dy) / len2;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(px - (x1 + t * dx), py - (y1 + t * dy));
}

function projOnSegment(px, py, x1, y1, x2, y2) {
  const dx = x2 - x1, dy = y2 - y1;
  const len2 = dx * dx + dy * dy;
  if (len2 === 0) return 0;
  return Math.max(0, Math.min(1, ((px - x1) * dx + (py - y1) * dy) / len2));
}

// =============================================================================
// 2. DARK TABLE MARGIN & TORN FOIL GAPS (CROSS-HATCHED PEN SHADOWS)
// =============================================================================
function drawTableMarginAndTears(mesh) {
  // Subtle paper vignette wash around the outer edges of the 1200x1200 frame
  brush.noStroke();
  brush.wash("#e6dccb", 75);
  brush.rect(0, 0, 1200, 1200, "corner");
  brush.noWash();

  // Compute outer boundary polygon of the foil to cast a raking drop shadow (towards bottom-right)
  const boundaryFacets = mesh.facets.filter(f => !f.isTearGap && f.area > 3);

  // Draw cast shadow of the crumpled sheet edge onto the table (offset toward lower-right)
  brush.noStroke();
  brush.wash("#4a423b", 55);
  for (const f of boundaryFacets) {
    const p0 = mesh.vertices[f.verts[0]];
    const p1 = mesh.vertices[f.verts[1]];
    const p2 = mesh.vertices[f.verts[2]];
    if (p0.edgeMetric > 0.86 || p1.edgeMetric > 0.86 || p2.edgeMetric > 0.86) {
      const poly = new brush.Polygon([
        [p0.x + 8, p0.y + 7],
        [p1.x + 8, p1.y + 7],
        [p2.x + 8, p2.y + 7]
      ]);
      poly.wash("#423a33", 65);
    }
  }
  brush.noWash();

  // Technical-pen cross-hatching in the narrow table margin around the crumpled foil edges
  const marginStrips = [
    [[18, 18], [1182, 18], [1182, 88], [18, 88]],
    [[18, 1112], [1182, 1112], [1182, 1182], [18, 1182]],
    [[18, 80], [88, 80], [88, 1120], [18, 1120]],
    [[1112, 80], [1182, 80], [1182, 1120], [1112, 1120]]
  ];

  for (const pts of marginStrips) {
    const p = new brush.Polygon(pts);
    p.wash("#d6cbb8", 95);
    brush.hatchStyle("tech_005", "#4a423a", 0.75);
    p.hatch(4.5, 32, { rand: 0.04 });
    brush.hatchStyle("tech_005", "#63594f", 0.65);
    p.hatch(6.5, -42, { rand: 0.05 });
  }
  brush.noHatch();
  brush.noWash();

  // Fill the open V-shaped tear gaps with deep cross-hatched shadow beneath the lifted foil
  for (const f of mesh.facets) {
    if (!f.isTearGap || f.area < 2) continue;
    const poly = new brush.Polygon(f.pts);
    poly.wash("#26211d", 190);
    brush.hatchStyle("tech_01", "#14110f", 0.95);
    poly.hatch(2.2, 40, { rand: 0.03 });
    brush.hatchStyle("tech_01", "#1c1815", 0.9);
    poly.hatch(2.6, -35, { rand: 0.03 });
  }
  brush.noHatch();
  brush.noWash();
}

// =============================================================================
// 3. BATCHED METALLIC UNDERWASHES (WARM STEEL, MERCURY, RED MUG & WINDOW)
// =============================================================================
function drawBatchedMetallicUnderwashes(mesh) {
  // Group facets into warm metallic tonal buckets + reflection buckets for fast wash batching
  const buckets = new Map();

  for (const f of mesh.facets) {
    if (f.isTearGap || f.area < 2.5) continue;

    let hex = "#e8e0d2";
    let alpha = 85;

    if (f.reflection === "mug_red") {
      if (f.mugSpec) {
        hex = "#d88a78";
        alpha = 95;
      } else if (f.tone > 0.55) {
        hex = "#c95b49";
        alpha = 110;
      } else {
        hex = "#8f372c";
        alpha = 125;
      }
    } else if (f.reflection === "mug_rim") {
      hex = "#ebd5c3";
      alpha = 105;
    } else if (f.reflection === "window_pane") {
      hex = f.tone > 0.68 ? "#f7f1df" : "#dfd8c5";
      alpha = 120;
    } else if (f.reflection === "window_mullion") {
      hex = "#878279";
      alpha = 95;
    } else {
      // Pure warm steel-to-mercury tonal ramp
      const t = f.tone;
      if (t < 0.16) { hex = "#524c46"; alpha = 135; }
      else if (t < 0.28) { hex = "#6e675f"; alpha = 120; }
      else if (t < 0.42) { hex = "#8c847a"; alpha = 105; }
      else if (t < 0.56) { hex = "#aba297"; alpha = 95; }
      else if (t < 0.70) { hex = "#c9c0b4"; alpha = 90; }
      else if (t < 0.84) { hex = "#e3dbd0"; alpha = 95; }
      else { hex = "#faf6ee"; alpha = 150; }
    }

    const key = `${hex}_${alpha}`;
    if (!buckets.has(key)) buckets.set(key, { hex, alpha, list: [] });
    buckets.get(key).list.push(f);
  }

  brush.noStroke();
  for (const bucket of buckets.values()) {
    for (const f of bucket.list) {
      const poly = new brush.Polygon(f.pts);
      poly.wash(bucket.hex, bucket.alpha);
    }
  }
  brush.noWash();
}

// =============================================================================
// 4. FACET-BY-FACET TECHNICAL-PEN HATCHING (GEM-LIKE DIRECTIONAL PLANES)
// =============================================================================
function drawFacetTechnicalHatching(mesh) {
  brush.noStroke();
  brush.noFill();
  brush.noWash();

  for (let i = 0; i < mesh.facets.length; i++) {
    const f = mesh.facets[i];
    if (f.isTearGap || f.area < 3.0) continue;

    const poly = new brush.Polygon(f.pts);
    const t = f.tone;
    const ang1 = f.hatchAngle;
    // Acute diamond cross-hatch angle (22 to 34 degrees) creates metallic moire sheen
    const ang2 = (ang1 + 26 + (i % 3) * 5) % 180;
    const ang3 = (ang1 - 24) % 180;

    // -------------------------------------------------------------------------
    // CASE A: WARPED RED MUG REFLECTION FACETS
    // -------------------------------------------------------------------------
    if (f.reflection === "mug_red") {
      // Pass 1: Warm Venetian/carmine technical-pen lines
      const redCol1 = f.mugSpec ? "#b84637" : (t > 0.48 ? "#9e2f24" : "#751f18");
      const distRed = map(t, 0.12, 0.9, 2.3, 5.2, true);
      brush.hatchStyle("tech_01", redCol1, 0.82);
      poly.hatch(distRed, ang1, { rand: 0.025, gradient: 0.18 });

      // Pass 2: Acute cross-hatch blending warm steel-graphite with terracotta
      const steelRedCol = t > 0.5 ? "#7a443c" : "#3d2926";
      brush.hatchStyle("tech_005", steelRedCol, 0.72);
      poly.hatch(distRed * 1.25, ang2, { rand: 0.03 });

      // Pass 3: Deep shadow accent if facet is angled away from raking light
      if (t < 0.38) {
        brush.hatchStyle("tech_005", "#2b1b19", 0.75);
        poly.hatch(3.4, ang3, { rand: 0.03, gradient: 0.35 });
      }
      continue;
    }

    if (f.reflection === "mug_rim") {
      brush.hatchStyle("tech_005", "#9c5547", 0.65);
      poly.hatch(5.8, ang1, { rand: 0.02 });
      brush.hatchStyle("tech_003", "#7d6e63", 0.6);
      poly.hatch(7.5, ang2, { rand: 0.02 });
      continue;
    }

    // -------------------------------------------------------------------------
    // CASE B: WARPED SUNLIT WINDOW REFLECTION FACETS
    // -------------------------------------------------------------------------
    if (f.reflection === "window_pane") {
      // Luminous warm sunlit amber-silver and sky-slate hairlines
      const winCol1 = t > 0.65 ? "#9c8763" : "#756a58";
      const winDist = map(t, 0.28, 0.95, 4.2, 10.5, true);
      brush.hatchStyle("tech_003", winCol1, 0.62);
      poly.hatch(winDist, ang1, { rand: 0.02, gradient: 0.2 });

      if (t < 0.62) {
        brush.hatchStyle("tech_003", "#64737a", 0.58);
        poly.hatch(winDist * 1.35, ang2, { rand: 0.02 });
      }
      continue;
    }

    if (f.reflection === "window_mullion") {
      brush.hatchStyle("tech_005", "#47443e", 0.75);
      poly.hatch(3.2, ang1, { rand: 0.025 });
      brush.hatchStyle("tech_003", "#5c564e", 0.68);
      poly.hatch(4.4, ang2, { rand: 0.03 });
      continue;
    }

    // -------------------------------------------------------------------------
    // CASE C: STEEL-TO-MERCURY & NEAR-GRAPHITE FACETS UNDER RAKING LIGHT
    // -------------------------------------------------------------------------
    if (t < 0.14) {
      // Near-graphite deep shadow facet: 3 dense technical-pen passes
      brush.hatchStyle("tech_01", "#1a1715", 0.92);
      poly.hatch(1.85, ang1, { rand: 0.025, gradient: 0.12 });

      brush.hatchStyle("tech_01", "#26221f", 0.82);
      poly.hatch(2.3, ang2, { rand: 0.03 });

      brush.hatchStyle("tech_005", "#141210", 0.78);
      poly.hatch(3.1, ang3, { rand: 0.03, gradient: 0.25 });
    } else if (t < 0.26) {
      // Dark warm graphite-pewter facet
      brush.hatchStyle("tech_01", "#26221f", 0.85);
      poly.hatch(2.25, ang1, { rand: 0.025, gradient: 0.15 });

      brush.hatchStyle("tech_005", "#36312c", 0.76);
      poly.hatch(2.9, ang2, { rand: 0.03 });

      brush.hatchStyle("tech_003", "#1f1c19", 0.7);
      poly.hatch(4.5, ang3, { rand: 0.03, gradient: 0.35 });
    } else if (t < 0.40) {
      // Medium-dark brushed steel facet
      brush.hatchStyle("tech_005", "#332e2a", 0.82);
      poly.hatch(2.75, ang1, { rand: 0.025, gradient: 0.18 });

      brush.hatchStyle("tech_005", "#4a433d", 0.72);
      poly.hatch(3.7, ang2, { rand: 0.03 });
    } else if (t < 0.55) {
      // Mid-tone titanium / warm nickel facet
      brush.hatchStyle("tech_005", "#47413b", 0.76);
      poly.hatch(3.4, ang1, { rand: 0.025, gradient: 0.22 });

      brush.hatchStyle("tech_003", "#635b53", 0.65);
      poly.hatch(5.0, ang2, { rand: 0.025 });
    } else if (t < 0.70) {
      // Bright silver-steel facet
      brush.hatchStyle("tech_005", "#5e564e", 0.68);
      poly.hatch(4.5, ang1, { rand: 0.02, gradient: 0.28 });

      brush.hatchStyle("tech_003", "#7d746a", 0.58);
      poly.hatch(7.2, ang2, { rand: 0.02 });
    } else if (t < 0.85) {
      // Luminous brushed mercury facet
      brush.hatchStyle("tech_003", "#786f65", 0.62);
      poly.hatch(6.4, ang1, { rand: 0.02, gradient: 0.35 });
    } else {
      // Blazing mercury specular plane: ultra-fine sparse hairline + white mercury sheen
      brush.hatchStyle("tech_003", "#948a7e", 0.52);
      poly.hatch(10.5, ang1, { rand: 0.015, gradient: 0.45 });

      brush.hatchStyle("mercury_nib", "#fffdf9", 0.72);
      poly.hatch(3.8, (ang1 + 90) % 180, { rand: 0.015 });
    }
  }

  brush.noHatch();
}

// =============================================================================
// 5. ANISOTROPIC FOIL MILL-GRAIN & METALLIC SURFACE SHEEN
// =============================================================================
function drawFoilMillGrain(mesh) {
  // Kitchen aluminium foil has a subtle horizontal rolling grain from the mill
  // We draw delicate broken hairline striations across mid-to-bright facets
  for (let i = 0; i < mesh.facets.length; i++) {
    const f = mesh.facets[i];
    if (f.isTearGap || f.area < 18 || f.tone < 0.48) continue;

    // Pick 2 to 4 points inside the triangle and draw short mill-grain hairlines
    const p0 = mesh.vertices[f.verts[0]];
    const p1 = mesh.vertices[f.verts[1]];
    const p2 = mesh.vertices[f.verts[2]];

    const count = f.tone > 0.78 ? 4 : 2;
    const isMercury = f.tone > 0.76;
    brush.set(isMercury ? "mercury_nib" : "tech_003", isMercury ? "#fcfaf5" : "#8a8075", isMercury ? 0.55 : 0.45);

    for (let k = 0; k < count; k++) {
      const r1 = 0.2 + 0.6 * ((i * 17 + k * 31) % 100) / 100;
      const r2 = (1 - r1) * (0.25 + 0.5 * ((i * 23 + k * 13) % 100) / 100);
      const r3 = 1 - r1 - r2;
      const gx = p0.x * r1 + p1.x * r2 + p2.x * r3;
      const gy = p0.y * r1 + p1.y * r2 + p2.y * r3;
      const halfLen = Math.min(11, Math.sqrt(f.area) * 0.26);
      const tilt = f.ny * 6.0;
      brush.line(gx - halfLen, gy - tilt, gx + halfLen, gy + tilt);
    }
  }
}

// =============================================================================
// 6. MOUNTAIN & VALLEY CREASE LATTICE, MICRO-BUCKLES & SPECULAR RIDGES
// =============================================================================
function drawCreaseNetworkAndMicroBuckles(mesh) {
  // Light direction in 2D canvas coordinates (from upper-left)
  const light2D = [-0.83, -0.55];

  for (let i = 0; i < mesh.creases.length; i++) {
    const c = mesh.creases[i];
    const va = mesh.vertices[c.a];
    const vb = mesh.vertices[c.b];

    // Skip segments that fall inside a tear gap
    const midU = (va.u + vb.u) * 0.5;
    const midV = (va.v + vb.v) * 0.5;
    let inTear = false;
    for (const tear of mesh.tears) {
      if (distToSegment(midU, midV, tear.u0, tear.v0, tear.u1, tear.v1) < tear.width * 0.85) {
        inTear = true;
        break;
      }
    }
    if (inTear) continue;

    const dx = vb.x - va.x;
    const dy = vb.y - va.y;
    const segLen = Math.hypot(dx, dy);
    if (segLen < 1.5) continue;

    // Unit normal to the crease segment in 2D
    const nx = -dy / segLen;
    const ny = dx / segLen;
    const facingLight = Math.abs(nx * light2D[0] + ny * light2D[1]);

    // Check if this crease passes through the red mug or window reflection zone
    const inRedZone = midU > 0.10 && midU < 0.72 && midV > -0.05 && midV < 0.62;

    if (c.type === "mountain_primary") {
      // MOUNTAIN FOLD:
      // 1. Sharp shadow bevel on the leeward side (lower-right offset)
      brush.set("tech_01", inRedZone ? "#3d1814" : "#1c1917", 0.88 + 0.25 * facingLight);
      brush.line(va.x + 0.85, va.y + 0.75, vb.x + 0.85, vb.y + 0.75);

      // 2. Secondary tonal transition line along the ridge base
      brush.set("tech_005", "#4a433d", 0.68);
      brush.line(va.x + 1.6, va.y + 1.3, vb.x + 1.6, vb.y + 1.3);

      // 3. Blazing mercury highlight along the light-facing crest of the mountain ridge
      brush.set("mercury_nib", "#fffefa", 0.95 + 0.3 * facingLight);
      brush.line(va.x - 0.65, va.y - 0.55, vb.x - 0.65, vb.y - 0.55);

      // 4. Lateral foil work-hardening micro-buckles (chatter ticks across the ridge)
      const numTicks = Math.floor(segLen / 5.5);
      for (let k = 1; k < numTicks; k++) {
        if ((i * 7 + k * 13) % 3 === 0) continue;
        const t = k / numTicks;
        const tx = va.x + dx * t;
        const ty = va.y + dy * t;
        const tickLen = (2.2 + ((i + k) % 4) * 0.9) * (0.6 + 0.5 * facingLight);
        const angOff = ((k % 2 === 0) ? 0.35 : -0.35);
        const bx = nx + (dx / segLen) * angOff;
        const by = ny + (dy / segLen) * angOff;

        brush.set("tech_003", "#2b2623", 0.62);
        brush.line(tx - bx * tickLen * 0.5, ty - by * tickLen * 0.5, tx + bx * tickLen, ty + by * tickLen);
      }

    } else if (c.type === "valley_primary") {
      // VALLEY FOLD:
      // 1. Deep recessed channel core line
      brush.set("tech_01", inRedZone ? "#331410" : "#171412", 0.92);
      brush.line(va.x, va.y, vb.x, vb.y);

      // 2. Flanking shadow lip on the upper-left side of the valley trough
      brush.set("tech_005", "#423c36", 0.68);
      brush.line(va.x - 0.9, va.y - 0.8, vb.x - 0.9, vb.y - 0.8);

      // 3. Reflected mercury rim on the lower-right lip of the trough (facing the raking light)
      brush.set("mercury_nib", "#fcf8f0", 0.82);
      brush.line(va.x + 0.95, va.y + 0.85, vb.x + 0.95, vb.y + 0.85);

      // 4. Fine pinch-ticks inside the valley channel
      const numTicks = Math.floor(segLen / 6.5);
      for (let k = 1; k < numTicks; k++) {
        if ((i * 11 + k * 5) % 3 !== 0) continue;
        const t = k / numTicks;
        const tx = va.x + dx * t;
        const ty = va.y + dy * t;
        const tickLen = 2.0 + (k % 3) * 0.8;
        brush.set("tech_003", "#26221f", 0.58);
        brush.line(tx - nx * tickLen, ty - ny * tickLen, tx + nx * tickLen, ty + ny * tickLen);
      }

    } else if (c.type === "mountain_secondary" || c.type === "valley_secondary") {
      // SECONDARY ORIGAMI CREASES (11.25 deg wing bisectors, camber folds)
      const isMtn = c.type === "mountain_secondary";
      brush.set("tech_005", "#2e2925", 0.72);
      brush.line(va.x, va.y, vb.x, vb.y);

      const sign = isMtn ? -0.65 : 0.65;
      brush.set("mercury_nib", "#f7f2e8", 0.68);
      brush.line(va.x + sign, va.y + sign, vb.x + sign, vb.y + sign);

    } else if (c.type === "crinkle") {
      // FOIL CRINKLE FACET BOUNDARY: crisp hairline steel jump
      const edgeContrast = facingLight;
      if (edgeContrast > 0.35) {
        brush.set("tech_003", "#3d3732", 0.55 * edgeContrast + 0.25);
        brush.line(va.x, va.y, vb.x, vb.y);
      }
      if (edgeContrast > 0.62 && (i % 2 === 0)) {
        brush.set("mercury_nib", "#faf6ee", 0.52);
        brush.line(va.x - 0.5, va.y - 0.4, vb.x - 0.5, vb.y - 0.4);
      }
    }
  }

  // Draw star-like plastic stress crinkles at the high-order origami vertices:
  // Center (0,0) and the 4 Bird-Base diamond hinges (+/-k, 0), (0, +/-k)
  const k = Math.SQRT2 - 1;
  const stressHubs = [
    [0, 0, 18],
    [k, 0, 12],
    [-k, 0, 12],
    [0, k, 12],
    [0, -k, 12],
    [-0.755, -0.755, 11], // Head reverse-fold crown hub
    [-0.835, -0.835, 10]  // Beak crimp hub
  ];

  for (const [hu, hv, numRays] of stressHubs) {
    // Find closest vertex in mesh
    let bestV = mesh.vertices[0];
    let bestD = 999;
    for (const v of mesh.vertices) {
      const d = Math.hypot(v.u - hu, v.v - hv);
      if (d < bestD) { bestD = d; bestV = v; }
    }

    for (let r = 0; r < numRays; r++) {
      const ang = (r * (360 / numRays) + (hu * 40 + hv * 70)) * Math.PI / 180;
      const len = 6 + (r % 4) * 4.5;
      const mx = bestV.x + Math.cos(ang) * len * 0.5 + Math.sin(ang) * 1.4;
      const my = bestV.y + Math.sin(ang) * len * 0.5 - Math.cos(ang) * 1.4;
      const ex = bestV.x + Math.cos(ang) * len;
      const ey = bestV.y + Math.sin(ang) * len;

      brush.set("tech_005", "#1c1816", 0.75);
      brush.spline([[bestV.x, bestV.y, 1.0], [mx, my, 0.8], [ex, ey, 0.2]], 0.4);

      if (r % 2 === 0) {
        brush.set("mercury_nib", "#fffdf9", 0.65);
        brush.line(bestV.x + Math.cos(ang) * 1.5 - 0.6, bestV.y + Math.sin(ang) * 1.5 - 0.6, mx - 0.6, my - 0.6);
      }
    }
  }
}

// =============================================================================
// 7. CRUMPLED & TORN PERIMETER RIMS AND SERRATED FOIL-CUTTER EDGE
// =============================================================================
function drawCrumpledAndTornEdges(mesh) {
  // 1. Highlight & contour all boundary edges and tear lips
  for (const f of mesh.facets) {
    if (f.isTearGap) continue;
    const vs = f.verts.map(idx => mesh.vertices[idx]);

    for (let e = 0; e < 3; e++) {
      const va = vs[e];
      const vb = vs[(e + 1) % 3];
      const midU = (va.u + vb.u) * 0.5;
      const midV = (va.v + vb.v) * 0.5;

      // Check if this edge borders a tear
      let nearTear = false;
      for (const tear of mesh.tears) {
        if (distToSegment(midU, midV, tear.u0, tear.v0, tear.u1, tear.v1) < tear.width * 1.35) {
          nearTear = true;
          break;
        }
      }

      const isOuterEdge = va.isBoundary && vb.isBoundary;

      if (isOuterEdge || nearTear) {
        // Dark crisp metallic cut shadow under the edge
        brush.set("tech_03", "#14110f", 0.95);
        brush.line(va.x + 1.2, va.y + 1.2, vb.x + 1.2, vb.y + 1.2);

        // Serrated foil-cutter micro-teeth along intact top & bottom edges
        const segLen = Math.hypot(vb.x - va.x, vb.y - va.y);
        if (isOuterEdge && !nearTear && Math.abs(midV) > 0.98 && segLen > 4) {
          const steps = Math.max(3, Math.floor(segLen / 3.2));
          const pts = [];
          const nx = -(vb.y - va.y) / segLen;
          const ny = (vb.x - va.x) / segLen;
          for (let s = 0; s <= steps; s++) {
            const t = s / steps;
            const tooth = (s % 2 === 0 ? 1.1 : -1.1);
            pts.push([
              va.x + (vb.x - va.x) * t + nx * tooth,
              va.y + (vb.y - va.y) * t + ny * tooth
            ]);
          }
          brush.set("tech_01", "#1c1815", 0.85);
          for (let s = 0; s < pts.length - 1; s++) {
            brush.line(pts[s][0], pts[s][1], pts[s + 1][0], pts[s + 1][1]);
          }
          brush.set("mercury_nib", "#fffefa", 0.85);
          for (let s = 0; s < pts.length - 1; s += 2) {
            brush.line(pts[s][0] - 0.5, pts[s][1] - 0.5, pts[s + 1][0] - 0.5, pts[s + 1][1] - 0.5);
          }
        } else {
          // Jagged crumpled or torn foil edge with rolled-up mercury lip
          brush.set("tech_01", "#1c1815", 0.9);
          brush.line(va.x, va.y, vb.x, vb.y);

          brush.set("mercury_nib", "#ffffff", nearTear ? 1.15 : 0.92);
          brush.line(va.x - 0.7, va.y - 0.7, vb.x - 0.7, vb.y - 0.7);
        }
      }
    }
  }

  // 2. Add folded-over foil shards & dense micro-crumple hatching along the 4 corners and tear tips
  for (const tear of mesh.tears) {
    // Find vertex closest to tear tip (u1, v1) where the tear stops and stresses the metal
    let tipV = mesh.vertices[0];
    let minD = 999;
    for (const v of mesh.vertices) {
      const d = Math.hypot(v.u - tear.u1, v.v - tear.v1);
      if (d < minD) { minD = d; tipV = v; }
    }

    // Radiating tear-tip stress lines & bright curled metal flare
    for (let r = 0; r < 9; r++) {
      const ang = (r * 40 + 15) * Math.PI / 180;
      const len = 7 + (r % 3) * 5;
      brush.set("tech_005", "#171412", 0.85);
      brush.line(tipV.x, tipV.y, tipV.x + Math.cos(ang) * len, tipV.y + Math.sin(ang) * len);
      if (r % 2 === 0) {
        brush.set("mercury_nib", "#ffffff", 0.95);
        brush.line(tipV.x - 0.6, tipV.y - 0.6, tipV.x + Math.cos(ang) * len * 0.7 - 0.6, tipV.y + Math.sin(ang) * len * 0.7 - 0.6);
      }
    }
  }
}

