function polyShape(pts, curvature = 0) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(CLOSE);
}

function getOctagonPts(cx, cy, r, rotOffset = 22.5) {
  let pts = [];
  for (let i = 0; i < 8; i++) {
    let a = rotOffset + i * 45;
    pts.push([cx + r * cos(a), cy + r * sin(a)]);
  }
  return pts;
}

// Returns the chamfered polygon for one of the 4 symmetrical quadrant lawns
function getLawnPolygon(qx, qy, inset = 0) {
  // qx, qy in {-1, 1}
  // Base lawn outer box: [236..520] from center -> dist from center: inner = 80, outer = 364
  let dIn = 80 + inset;
  let dOut = 364 - inset;
  let cham = 98 + inset * 0.4; // 45-degree chamfer facing the octagonal fountain

  // In local quadrant coordinates (u, v > 0 from center):
  // Inner corner (dIn, dIn) is chamfered from (dIn + cham, dIn) to (dIn, dIn + cham)
  let local = [
    [dIn + cham, dIn],
    [dOut, dIn],
    [dOut, dOut],
    [dIn, dOut],
    [dIn, dIn + cham]
  ];

  return local.map(([u, v]) => [CX + qx * u, CY + qy * v]);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4219);
  noiseSeed(4219);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.paper);

  // 1. Paper ground texture & architectural margin construction lines
  drawPaperAndConstruction();

  // 2. Limestone courtyard base washes & individual ashlar block tonal variations
  let slabs = generateCourtyardSlabs();
  drawLimestoneBaseAndSlabs(slabs);

  // 3. Four symmetrical clipped lawns (sap green & olive watercolour glazes + blade texture)
  drawFourLawns();

  // 4. Narrow stone water channels & brimming octagonal fountain (cerulean sky & branch reflections)
  drawWaterAndFountain();

  // 5. Crisp graphite stone joints, chipped limestone edges, & architectural cast shadows
  drawStoneJointsAndShadows(slabs);

  // 6. The Four Quadrant Disorders (fallen split pomegranate, sandals, drying footprints)
  drawQuadrantDisorders();

  // 7. Overhanging pomegranate branch in NE corner (cast shadow + foliage + ruby fruit)
  drawOverhangingPomegranateBranch();

  // 8. Final architectural presentation border, ticks, scale bar & title block markings
  drawArchitecturalAnnotations();

  noLoop();
}

// =============================================================================
// 1. PAPER GROUND & ARCHITECTURAL CONSTRUCTION LINES
