function drawPaperAndConstruction() {
  brush.noStroke();
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.55, 0.25);

  // Subtle warm paper rag washes
  brush.fill(PAL.paperWarm, 45);
  brush.rect(80, 80, 1040, 1040, "corner");
  brush.noFill();

  // Fine paper grain stipple
  brush.set("spray", PAL.paperShadow, 0.35);
  for (let i = 0; i < 45; i++) {
    let y = map(i, 0, 44, 60, 1140);
    brush.line(60, y + random(-4, 4), 1140, y + random(-4, 4));
  }

  // Architect's construction / projection lines extending into the margins
  brush.set("2H", PAL.graphite2H, 0.16);
  let keyCoords = [110, 146, 236, 520, 556, 578, 600, 622, 644, 680, 964, 1054, 1090];
  for (let c of keyCoords) {
    // Vertical projection lines at top and bottom margins
    let ext = (c === 600 || c === 110 || c === 1090) ? 42 : 68;
    brush.line(c, ext, c, 120);
    brush.line(c, 1080, c, 1200 - ext);
    // Horizontal projection lines at left and right margins
    brush.line(ext, c, 120, c);
    brush.line(1080, c, 1200 - ext, c);
  }

  // Diagonal 45-degree geometric construction axes through the center
  brush.set("2H", PAL.graphite2H, 0.14);
  brush.line(75, 75, 160, 160);
  brush.line(1125, 75, 1040, 160);
  brush.line(75, 1125, 160, 1040);
  brush.line(1125, 1125, 1040, 1040);

  // Faint construction circles in the margin showing the octagonal geometry
  brush.set("2H", PAL.graphite2H, 0.14);
  brush.circle(CX, CY, 382, 0.01);
  brush.circle(CX, CY, 495, 0.01);
}

// =============================================================================
// 2. GENERATE & RENDER LIMESTONE ASHLAR SLABS
// =============================================================================
function generateCourtyardSlabs() {
  let slabs = [];

  // A. Outer Perimeter Wall Coping Stones (110..146 and 1054..1090)
  let wallStep = 64;
  for (let x = 146; x < 1054; x += wallStep) {
    let w = min(wallStep, 1054 - x);
    slabs.push({ x: x, y: 110, w: w, h: 36, type: "wall" });
    slabs.push({ x: x, y: 1054, w: w, h: 36, type: "wall" });
  }
  for (let y = 146; y < 1054; y += wallStep) {
    let h = min(wallStep, 1054 - y);
    slabs.push({ x: 110, y: y, w: 36, h: h, type: "wall" });
    slabs.push({ x: 1054, y: y, w: 36, h: h, type: "wall" });
  }
  // 4 Corner boss stones
  slabs.push({ x: 110, y: 110, w: 36, h: 36, type: "wall" });
  slabs.push({ x: 1054, y: 110, w: 36, h: 36, type: "wall" });
  slabs.push({ x: 110, y: 1054, w: 36, h: 36, type: "wall" });
  slabs.push({ x: 1054, y: 1054, w: 36, h: 36, type: "wall" });

  // B. Perimeter Flagstone Walkways (146..236 and 964..1054) - 3 courses of 30px
  let courseW = 30;
  for (let c = 0; c < 3; c++) {
    let yTop = 146 + c * courseW;
    let yBot = 964 + c * courseW;
    let offset = (c % 2) * 26;
    // Top & Bottom horizontal bands (between 236 and 964, skipping axial channel 556..644)
    for (let seg of [[236, 556], [644, 964]]) {
      let x = seg[0];
      if (offset > 0 && x + offset < seg[1]) {
        slabs.push({ x: x, y: yTop, w: offset, h: courseW, type: "paving" });
        slabs.push({ x: x, y: yBot, w: offset, h: courseW, type: "paving" });
        x += offset;
      }
      while (x < seg[1]) {
        let step = ( int((x + c * 17) / 40) % 2 === 0 ) ? 52 : 44;
        let w = min(step, seg[1] - x);
        if (seg[1] - (x + w) < 18) w = seg[1] - x;
        slabs.push({ x: x, y: yTop, w: w, h: courseW, type: "paving" });
        slabs.push({ x: x, y: yBot, w: w, h: courseW, type: "paving" });
        x += w;
      }
    }

    // Left & Right vertical bands (between 236 and 964, skipping axial channel 556..644)
    let xLeft = 146 + c * courseW;
    let xRight = 964 + c * courseW;
    for (let seg of [[236, 556], [644, 964]]) {
      let y = seg[0];
      if (offset > 0 && y + offset < seg[1]) {
        slabs.push({ x: xLeft, y: y, w: courseW, h: offset, type: "paving" });
        slabs.push({ x: xRight, y: y, w: courseW, h: offset, type: "paving" });
        y += offset;
      }
      while (y < seg[1]) {
        let step = ( int((y + c * 19) / 40) % 2 === 0 ) ? 52 : 44;
        let h = min(step, seg[1] - y);
        if (seg[1] - (y + h) < 18) h = seg[1] - y;
        slabs.push({ x: xLeft, y: y, w: courseW, h: h, type: "paving" });
        slabs.push({ x: xRight, y: y, w: courseW, h: h, type: "paving" });
        y += h;
      }
    }
  }

  // 4 Corner Courtyard Paving Squares (146..236 x 146..236 etc.)
  let corners = [[146, 146], [964, 146], [146, 964], [964, 964]];
  for (let [cx0, cy0] of corners) {
    for (let r = 0; r < 2; r++) {
      for (let col = 0; col < 2; col++) {
        slabs.push({ x: cx0 + col * 45, y: cy0 + r * 45, w: 45, h: 45, type: "paving" });
      }
    }
  }

  // C. Axial Walkways Alongside the Water Channels (520..556 and 644..680)
  // Running from outer wall (236) to octagonal plaza (422 and 778)
  for (let seg of [[236, 422], [778, 964]]) {
    let p = seg[0];
    while (p < seg[1]) {
      let step = 38;
      let len = min(step, seg[1] - p);
      if (seg[1] - (p + len) < 14) len = seg[1] - p;
      // N & S axial walkways
      slabs.push({ x: 520, y: p, w: 36, h: len, type: "paving" });
      slabs.push({ x: 644, y: p, w: 36, h: len, type: "paving" });
      // W & E axial walkways
      slabs.push({ x: p, y: 520, w: len, h: 36, type: "paving" });
      slabs.push({ x: p, y: 644, w: len, h: 36, type: "paving" });
      p += len;
    }
  }

  // D. Narrow Stone Water Channel Coping Kerbs (556..578 and 622..644, width 22px)
  // Running from outer wall (146) all the way to octagonal fountain step (446 and 754)
  for (let seg of [[146, 446], [754, 1054]]) {
    let p = seg[0];
    while (p < seg[1]) {
      let len = min(50, seg[1] - p);
      if (seg[1] - (p + len) < 16) len = seg[1] - p;
      // N & S channel kerbs
      slabs.push({ x: 556, y: p, w: 22, h: len, type: "kerb" });
      slabs.push({ x: 622, y: p, w: 22, h: len, type: "kerb" });
      // W & E channel kerbs
      slabs.push({ x: p, y: 556, w: len, h: 22, type: "kerb" });
      slabs.push({ x: p, y: 622, w: len, h: 22, type: "kerb" });
      p += len;
    }
  }

  return slabs;
}

function drawLimestoneBaseAndSlabs(slabs) {
  // Base warm limestone wash over the whole courtyard
  brush.noStroke();
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.5, 0.35);
  brush.fill(PAL.stoneMid1, 130);
  brush.rect(110, 110, 980, 980, "corner");

  // Batch slabs into 3 tonal groups for rich ashlar variation without over-taxing fill cache
  let groupLight = [];
  let groupMid = [];
  let groupDark = [];

  for (let i = 0; i < slabs.length; i++) {
    let s = slabs[i];
    let n = noise(s.x * 0.015, s.y * 0.015, i * 0.1);
    if (s.type === "wall") {
      if (n > 0.52) groupLight.push(s);
      else groupMid.push(s);
    } else if (s.type === "kerb") {
      groupLight.push(s);
    } else {
      if (n < 0.36) groupDark.push(s);
      else if (n > 0.66) groupLight.push(s);
      else if (i % 5 === 0) groupMid.push(s);
    }
  }

  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.45, 0.3);

  // Batch 1: Light limestone blocks
  brush.fill(PAL.stoneLight, 110);
  for (let s of groupLight) {
    brush.rect(s.x + 1, s.y + 1, s.w - 2, s.h - 2, "corner");
  }

  // Batch 2: Mid-warm limestone blocks
  brush.fill(PAL.stoneMid2, 95);
  for (let s of groupMid) {
    brush.rect(s.x + 1, s.y + 1, s.w - 2, s.h - 2, "corner");
  }

  // Batch 3: Darker weathered limestone blocks
  brush.fill(PAL.stoneDark1, 105);
  for (let s of groupDark) {
    brush.rect(s.x + 1, s.y + 1, s.w - 2, s.h - 2, "corner");
  }
  brush.noFill();

  // Subtle limestone grain hatching across the paving plaza
  brush.hatchStyle("2H", PAL.graphite2H, 0.16);
  brush.hatch(9, 0, { rand: 0.08 });
  brush.noStroke();
  brush.rect(146, 146, 908, 908, "corner");
  brush.noHatch();
}

// =============================================================================
// 3. THE FOUR SYMMETRICAL CLIPPED LAWNS (SAP GREEN & OLIVE GLAZES)
// =============================================================================
function drawFourLawns() {
  let quadrants = [[-1, -1], [1, -1], [-1, 1], [1, 1]];
  let curbWidth = 14;

  // Step 1: Limestone curb frame around each lawn
  brush.noStroke();
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.4, 0.3);
  brush.fill(PAL.stoneLight, 145);
  for (let [qx, qy] of quadrants) {
    let outerPts = getLawnPolygon(qx, qy, 0);
    polyShape(outerPts, 0);
  }
  brush.noFill();

  // Step 2: Transparent watercolour glazes building the clipped turf in sap green & olive
  brush.noStroke();
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.68, 0.48);

  // Layer A: Luminous Sap Green base glaze
  brush.fill(PAL.sapGreen, 115);
  for (let [qx, qy] of quadrants) {
    let turfPts = getLawnPolygon(qx, qy, curbWidth);
    polyShape(turfPts, 0);
  }

  // Layer B: Warm Sap-Olive second glaze for depth
  brush.fillBleed(0.22, "in");
  brush.fill(PAL.oliveMid, 85);
  for (let [qx, qy] of quadrants) {
    let turfPts = getLawnPolygon(qx, qy, curbWidth + 3);
    polyShape(turfPts, 0);
  }

  // Layer C: Subtle clipped mowing stripes (diagonal bands across each lawn)
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.45, 0.25);
  brush.fill(PAL.oliveDeep, 55);
  for (let [qx, qy] of quadrants) {
    let x0 = qx < 0 ? 250 : 694;
    let y0 = qy < 0 ? 250 : 694;
    let size = 256;
    // Draw 5 clipped diagonal turf bands inside the lawn box
    for (let s = -2; s <= 2; s++) {
      let bandOffset = s * 46;
      let bx1 = constrain(x0 + bandOffset, x0, x0 + size);
      let by1 = constrain(y0 - bandOffset, y0, y0 + size);
      let bx2 = constrain(x0 + size + bandOffset, x0, x0 + size);
      let by2 = constrain(y0 + size - bandOffset, y0, y0 + size);
      // Avoid the chamfered inner corner
      if (dist(bx1, by1, CX, CY) > 210 && dist(bx2, by2, CX, CY) > 210) {
        let stripPts = [
          [bx1, by1],
          [constrain(bx1 + 20, x0, x0 + size), by1],
          [bx2, constrain(by2 - 20, y0, y0 + size)],
          [bx2, by2]
        ];
        polyShape(stripPts, 0);
      }
    }
  }
  brush.noFill();

  // Step 3: Dense botanical turf hatching & blade stippling
  for (let [qx, qy] of quadrants) {
    let turfPts = getLawnPolygon(qx, qy, curbWidth + 1);

    // Fine directional grass hatch
    brush.hatchStyle("cpencil", PAL.oliveDeep, 0.32);
    brush.hatch(4.5, 35, { rand: 0.25 });
    brush.noStroke();
    polyShape(turfPts, 0);
    brush.noHatch();

    // Cross-grain velvet turf texture
    brush.hatchStyle("2H", PAL.sapLight, 0.25);
    brush.hatch(6.5, -55, { rand: 0.3 });
    brush.noStroke();
    polyShape(turfPts, 0);
    brush.noHatch();

    // Individual hyperrealist grass blade clusters & sun-bleached tips
    let minX = qx < 0 ? 252 : 694;
    let maxX = qx < 0 ? 504 : 948;
    let minY = qy < 0 ? 252 : 694;
    let maxY = qy < 0 ? 504 : 948;

    brush.set("cpencil", PAL.oliveShadow, 0.35);
    for (let i = 0; i < 240; i++) {
      let gx = random(minX, maxX);
      let gy = random(minY, maxY);
      // Keep outside the inner octagonal chamfer
      if (abs(gx - CX) + abs(gy - CY) > 286) {
        let ang = random(-110, -70);
        let len = random(2.5, 5.5);
        brush.line(gx, gy, gx + cos(ang) * len, gy + sin(ang) * len);
      }
    }

    brush.set("2H", PAL.turfHighlight, 0.28);
    for (let i = 0; i < 140; i++) {
      let gx = random(minX, maxX);
      let gy = random(minY, maxY);
      if (abs(gx - CX) + abs(gy - CY) > 286) {
        brush.line(gx, gy, gx + random(-1.5, 1.5), gy - random(2, 4.5));
      }
    }
  }

  // Step 4: Recessed turf shadow along the sun-facing (North & West) stone curbs
  brush.noStroke();
  brush.fillBleed(0.04, "in");
  brush.fill(PAL.oliveShadow, 145);
  for (let [qx, qy] of quadrants) {
    let pts = getLawnPolygon(qx, qy, curbWidth);
    // pts order:
    // For qx=-1, qy=-1 (NW): [0]=(406,506), [1]=(250,506), [2]=(250,250), [3]=(506,250), [4]=(506,406)
    // Top edge of lawn is min Y; Left edge of lawn is min X
    let minX = qx < 0 ? 250 : 694;
    let maxX = qx < 0 ? 506 : 950;
    let minY = qy < 0 ? 250 : 694;
    let maxY = qy < 0 ? 506 : 950;

    // North curb shadow on grass (top edge of each lawn)
    let nStart = (qx > 0 && qy > 0) ? minX + 94 : minX;
    brush.rect(nStart, minY, maxX - nStart, 8, "corner");

    // West curb shadow on grass (left edge of each lawn)
    let wStart = (qx > 0 && qy > 0) ? minY + 94 : minY;
    brush.rect(minX, wStart, 8, maxY - wStart, "corner");

    // SE lawn also has its NW chamfered edge casting a diagonal shadow onto the grass!
    if (qx > 0 && qy > 0) {
      let chamShadow = [
        [pts[0][0], pts[0][1]],
        [pts[4][0], pts[4][1]],
        [pts[4][0] + 7, pts[4][1] + 7],
        [pts[0][0] + 7, pts[0][1] + 7]
      ];
      polyShape(chamShadow, 0);
    }
  }
  brush.noFill();

  // Step 5: Crisp graphite outlines & miter joints on the 4 lawn curbs
  for (let [qx, qy] of quadrants) {
    let outerPts = getLawnPolygon(qx, qy, 0);
    let innerPts = getLawnPolygon(qx, qy, curbWidth);

    brush.set("HB", PAL.graphiteHB, 0.32);
    polyShape(outerPts, 0);
    brush.set("2B", PAL.graphite2B, 0.36);
    polyShape(innerPts, 0);

    // Mitered corner joints & intermediate stone curb joints
    brush.set("2H", PAL.graphite2H, 0.24);
    for (let i = 0; i < 5; i++) {
      brush.line(outerPts[i][0], outerPts[i][1], innerPts[i][0], innerPts[i][1]);
      // Subdivide each straight curb segment into 4-5 cut limestone blocks
      let next = (i + 1) % 5;
      let segLen = dist(outerPts[i][0], outerPts[i][1], outerPts[next][0], outerPts[next][1]);
      let steps = max(2, round(segLen / 58));
      for (let k = 1; k < steps; k++) {
        let t = k / steps;
        let ox = lerp(outerPts[i][0], outerPts[next][0], t);
        let oy = lerp(outerPts[i][1], outerPts[next][1], t);
        let ix = lerp(innerPts[i][0], innerPts[next][0], t);
        let iy = lerp(innerPts[i][1], innerPts[next][1], t);
        brush.line(ox, oy, ix, iy);
      }
    }
  }
}

// =============================================================================
// 4. NARROW WATER CHANNELS & BRIMMING OCTAGONAL FOUNTAIN
// =============================================================================
function drawWaterAndFountain() {
  let octStep = getOctagonPts(CX, CY, 166);
  let octRimOut = getOctagonPts(CX, CY, 132);
  let octRimIn = getOctagonPts(CX, CY, 106);
  let octSpoutOut = getOctagonPts(CX, CY, 28);
  let octSpoutIn = getOctagonPts(CX, CY, 13);

  // 4.1 Outer Octagonal Step Plaza (R=166)
  brush.noStroke();
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.45, 0.3);
  brush.fill(PAL.stoneMid1, 140);
  polyShape(octStep, 0);
  brush.noFill();

  // 4.2 Recessed Water Base (4 Narrow Channels + Central Octagonal Basin)
  brush.noStroke();
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.55, 0.4);

  // Deep slate-teal water base
  brush.fill(PAL.waterDeep, 155);
  // N, S, W, E channels (width 44px: 578..622, running from 146 to 1054)
  brush.rect(578, 146, 44, 356, "corner");
  brush.rect(578, 698, 44, 356, "corner");
  brush.rect(146, 578, 356, 44, "corner");
  brush.rect(698, 578, 356, 44, "corner");
  // Central octagonal basin
  polyShape(octRimIn, 0);

  // Luminous Cerulean Sky Reflection Glaze
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.6, 0.35);
  brush.fill(PAL.cerulean, 130);
  brush.rect(582, 152, 36, 348, "corner");
  brush.rect(582, 700, 36, 348, "corner");
  brush.rect(152, 582, 348, 36, "corner");
  brush.rect(700, 582, 348, 36, "corner");
  polyShape(getOctagonPts(CX, CY, 98), 0);

  // Bright broken sky reflection patches
  brush.fill(PAL.ceruleanLight, 115);
  polyShape(getOctagonPts(CX + 6, CY + 6, 74), 0);
  for (let p = 180; p < 460; p += 70) {
    brush.rect(585, p, 30, 42, "corner");
    brush.rect(585, 1200 - p - 42, 30, 42, "corner");
    brush.rect(p, 585, 42, 30, "corner");
    brush.rect(1200 - p - 42, 585, 42, 30, "corner");
  }
  brush.noFill();

  // 4.3 Submerged Limestone Paving Joints (slightly refracted under water)
  brush.set("2H", PAL.waterDeep, 0.22);
  for (let p = 175; p < 490; p += 38) {
    brush.line(579, p, 621, p + 2);
    brush.line(579, 1200 - p, 621, 1200 - p + 2);
    brush.line(p, 579, p + 2, 621);
    brush.line(1200 - p, 579, 1200 - p + 2, 621);
  }
  // Submerged radial joints in octagonal basin
  for (let i = 0; i < 8; i++) {
    brush.line(octSpoutOut[i][0], octSpoutOut[i][1], octRimIn[i][0], octRimIn[i][1]);
  }
  let octSubMid = getOctagonPts(CX, CY, 66);
  polyShape(octSubMid, 0);

  // 4.4 Broken Reflection of the Overhanging Pomegranate Branch in the Water!
  // Reflected in the North channel (y: 260..460), East channel (x: 700..900), and NE edge of basin
  brush.noStroke();
  brush.fillBleed(0.25, "out");
  brush.fill(PAL.oliveDeep, 95);
  // Leaf reflection blobs in North channel & NE basin
  brush.circle(602, 335, 16, 0.3);
  brush.circle(596, 372, 14, 0.3);
  brush.circle(605, 415, 12, 0.3);
  brush.circle(645, 555, 18, 0.3);
  brush.circle(765, 598, 15, 0.3);
  brush.circle(810, 602, 13, 0.3);

  // Broken ruby reflection of a pomegranate fruit in the North channel & basin
  brush.fill(PAL.pomCrimson, 120);
  brush.circle(604, 352, 9, 0.25);
  brush.circle(652, 548, 8, 0.25);
  brush.circle(782, 596, 8, 0.25);
  brush.noFill();

  // Wavering dark woody branch reflection lines broken by ripples
  brush.set("2B", PAL.waterDeep, 0.38);
  for (let y = 310; y <= 445; y += 6) {
    let x1 = 582 + (y - 310) * 0.18 + sin(y * 8) * 3;
    let x2 = x1 + 14 + cos(y * 6) * 2;
    if (x1 < 620) brush.line(constrain(x1, 579, 620), y, constrain(x2, 579, 620), y + 1);
  }
  for (let x = 735; x <= 845; x += 6) {
    let y1 = 582 + (x - 735) * 0.22 + sin(x * 8) * 3;
    let y2 = y1 + 13;
    if (y1 < 620) brush.line(x, constrain(y1, 579, 620), x + 1, constrain(y2, 579, 620));
  }

  // 4.5 Cast Shadow of Channel Kerbs & Octagonal Rim onto the Water (NW sunlight -> SE shadow)
  brush.noStroke();
  brush.fillBleed(0.05, "in");
  brush.fill(PAL.shadowDeep, 115);
  // West wall of N & S channels shades left 10px of water
  brush.rect(578, 146, 10, 352, "corner");
  brush.rect(578, 702, 10, 352, "corner");
  // North wall of W & E channels shades top 10px of water
  brush.rect(146, 578, 352, 10, "corner");
  brush.rect(702, 578, 352, 10, "corner");
  // NW inner faces of octagonal basin shade the NW crescent of water
  let basinShadowPts = [
    octRimIn[4], octRimIn[5], octRimIn[6], octRimIn[7], octRimIn[0],
    [octRimIn[0][0] + 10, octRimIn[0][1] + 10],
    [octRimIn[7][0] + 14, octRimIn[7][1] + 14],
    [octRimIn[6][0] + 14, octRimIn[6][1] + 14],
    [octRimIn[5][0] + 14, octRimIn[5][1] + 14],
    [octRimIn[4][0] + 10, octRimIn[4][1] + 10]
  ];
  polyShape(basinShadowPts, 0);
  brush.noFill();

  // 4.6 Moulded Octagonal Fountain Rim (R_out=132, R_in=106)
  // Draw the 8 trapezoidal coping stones around the basin
  brush.noStroke();
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.4, 0.3);
  for (let i = 0; i < 8; i++) {
    let next = (i + 1) % 8;
    let blockPts = [octRimOut[i], octRimOut[next], octRimIn[next], octRimIn[i]];
    // Alternate slight limestone tone
    brush.fill(i % 2 === 0 ? PAL.stoneLight : PAL.stoneMid1, 210);
    polyShape(blockPts, 0);
  }
  brush.noFill();

  // Carve the 4 brimming weir spillways through the N, S, E, W faces of the octagonal rim!
  // This connects the central octagonal pool seamlessly to the 4 narrow channels
  brush.noStroke();
  brush.fillBleed(0.05, "in");
  brush.fill(PAL.cerulean, 185);
  let weirW = 30;
  // North weir (y: 478..503), South weir (y: 697..722), West weir, East weir
  brush.rect(CX - weirW / 2, CY - 122, weirW, 25, "corner");
  brush.rect(CX - weirW / 2, CY + 97, weirW, 25, "corner");
  brush.rect(CX - 122, CY - weirW / 2, 25, weirW, "corner");
  brush.rect(CX + 97, CY - weirW / 2, 25, weirW, "corner");

  // Dark wet limestone stains on the octagonal rim where brimming water laps over the lip
  brush.fillBleed(0.12, "out");
  brush.fill(PAL.stoneWet, 130);
  // Diagonal faces of rim get realistic wet overflow patches
  polyShape([[672, 502], [696, 526], [682, 540], [658, 516]], 0.2);
  polyShape([[695, 672], [670, 697], [656, 683], [681, 658]], 0.2);
  polyShape([[504, 674], [528, 698], [540, 684], [516, 660]], 0.2);
  brush.noFill();

  // 4.7 Central Carved Stone Lotus Spout (R=28)
  // Cast shadow of spout into the water
  brush.noStroke();
  brush.fillBleed(0.08, "out");
  brush.fill(PAL.shadowDeep, 135);
  polyShape(getOctagonPts(CX + 8, CY + 8, 28), 0);

  // Stone spout body
  brush.fill(PAL.stoneLight, 230);
  polyShape(octSpoutOut, 0);
  brush.fill(PAL.stoneDark1, 200);
  polyShape(octSpoutIn, 0);
  brush.noFill();

  // Spout graphite carvings (8 radial lotus petals + bubbling central nozzle)
  brush.set("HB", PAL.graphiteHB, 0.32);
  polyShape(octSpoutOut, 0);
  polyShape(octSpoutIn, 0);
  for (let i = 0; i < 8; i++) {
    brush.line(octSpoutIn[i][0], octSpoutIn[i][1], octSpoutOut[i][0], octSpoutOut[i][1]);
  }
  brush.set("2B", PAL.inkDark, 0.4);
  brush.circle(CX, CY, 5, 0.05);

  // 4.8 Rippling Water Waves, Concentric Rings & Specular Sky Glints
  // Concentric ripples inside the octagonal basin
  let radii = [33, 41, 50, 60, 71, 82, 92];
  for (let r of radii) {
    // Dark wave trough arcs
    brush.set("2H", PAL.waterDeep, 0.26);
    for (let a = 0; a < 360; a += 45) {
      let span = random(24, 36);
      let startA = a + random(-4, 4);
      brush.arc(CX, CY, r, startA, startA + span);
    }
    // Crisp white / sky-blue sunlit wave crest highlights
    brush.set("rotring", PAL.foam, 0.28);
    for (let a = 15; a < 360; a += 45) {
      let span = random(16, 28);
      let startA = a + random(-5, 5);
      brush.arc(CX, CY, r + 1.5, startA, startA + span);
    }
  }

  // Foaming aeration bubbles right around the central spout & 4 weir spills
  brush.set("rotring", PAL.foam, 0.35);
  for (let i = 0; i < 28; i++) {
    let ang = random(360);
    let rad = random(5, 32);
    brush.circle(CX + cos(ang) * rad, CY + sin(ang) * rad, random(1, 2.8), 0.1);
  }

  // Ripples along the 4 Narrow Water Channels
  for (let distFromCenter = 104; distFromCenter < 448; distFromCenter += 11) {
    let waveW = 14 + sin(distFromCenter * 4) * 3;
    let offset = cos(distFromCenter * 5) * 2.5;

    // Dark ripple troughs
    brush.set("2H", PAL.waterDeep, 0.24);
    // North & South channels
    brush.arc(CX + offset, CY - distFromCenter, waveW, 205, 335);
    brush.arc(CX - offset, CY + distFromCenter, waveW, 25, 155);
    // West & East channels
    brush.arc(CX - distFromCenter, CY - offset, waveW, 115, 245);
    brush.arc(CX + distFromCenter, CY + offset, waveW, -65, 65);

    // Bright specular sky highlight arcs on every second ripple
    if (distFromCenter % 22 === 5) {
      brush.set("rotring", PAL.foam, 0.26);
      brush.arc(CX + offset, CY - distFromCenter + 1.5, waveW - 2, 225, 315);
      brush.arc(CX - offset, CY + distFromCenter + 1.5, waveW - 2, 45, 135);
      brush.arc(CX - distFromCenter + 1.5, CY - offset, waveW - 2, 135, 225);
      brush.arc(CX + distFromCenter + 1.5, CY + offset, waveW - 2, -45, 45);
    }
  }

  // Longitudinal water shimmer lines along the channels
  brush.set("2H", PAL.skyGlint, 0.22);
  for (let i = 0; i < 36; i++) {
    let d = random(130, 440);
    let len = random(14, 34);
    let side = random(-13, 15);
    brush.line(CX + side, CY - d, CX + side, CY - d - len);
    brush.line(CX + side, CY + d, CX + side, CY + d + len);
    brush.line(CX - d, CY + side, CX - d - len, CY + side);
    brush.line(CX + d, CY + side, CX + d + len, CY + side);
  }
}

// =============================================================================
// 5. CRISP GRAPHITE JOINTS, CHIPPED EDGES & ARCHITECTURAL SHADOWS
// =============================================================================
function drawStoneJointsAndShadows(slabs) {
  let octStep = getOctagonPts(CX, CY, 166);
  let octRimOut = getOctagonPts(CX, CY, 132);
  let octRimMid1 = getOctagonPts(CX, CY, 126);
  let octRimMid2 = getOctagonPts(CX, CY, 112);
  let octRimIn = getOctagonPts(CX, CY, 106);

  // 5.1 Architectural Cast Shadows on Paving (Sun from NW -> Shadows cast SE at +45 deg)
  brush.noStroke();
  brush.fillBleed(0.04, "in");
  brush.fill(PAL.shadowWash, 95);

  // Shadow of North & West outer courtyard walls (y=146, x=146) onto the perimeter walkway
  let wallShadowD = 18;
  brush.rect(146, 146, 908, wallShadowD, "corner");
  brush.rect(146, 164, wallShadowD, 890, "corner");

  // Shadow of East & South outer courtyard wall outside onto the margin paper
  brush.fill(PAL.shadowWash, 75);
  polyShape([[1090, 110], [1106, 126], [1106, 1106], [1090, 1090]], 0);
  polyShape([[110, 1090], [1090, 1090], [1106, 1106], [126, 1106]], 0);

  // Shadow of the 4 Lawn Curbs onto the SE limestone paving (South & East edges of each lawn)
  brush.fill(PAL.shadowWash, 90);
  for (let [qx, qy] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
    let pts = getLawnPolygon(qx, qy, 0);
    // Find South-most Y and East-most X of this lawn's outer curb
    let maxX = qx < 0 ? 520 : 964;
    let minX = qx < 0 ? 236 : 680;
    let maxY = qy < 0 ? 520 : 964;
    let minY = qy < 0 ? 236 : 680;

    // East curb shadow
    let eEnd = (qx < 0 && qy < 0) ? maxY - 98 : maxY;
    let eStart = (qx < 0 && qy > 0) ? minY + 98 : minY;
    polyShape([
      [maxX, eStart],
      [maxX + 7, eStart + 7],
      [maxX + 7, eEnd + 7],
      [maxX, eEnd]
    ], 0);

    // South curb shadow
    let sEnd = (qx < 0 && qy < 0) ? maxX - 98 : maxX;
    let sStart = (qx > 0 && qy < 0) ? minX + 98 : minX;
    polyShape([
      [sStart, maxY],
      [sEnd, maxY],
      [sEnd + 7, maxY + 7],
      [sStart + 7, maxY + 7]
    ], 0);

    // NW lawn's chamfered edge faces SE, so it casts a diagonal shadow toward the fountain!
    if (qx < 0 && qy < 0) {
      polyShape([
        pts[0], pts[4],
        [pts[4][0] + 7, pts[4][1] + 7],
        [pts[0][0] + 7, pts[0][1] + 7]
      ], 0);
    }
  }

  // Shadow of the Octagonal Fountain Rim (R=132) onto the Octagonal Step (SE side)
  brush.fill(PAL.shadowWash, 115);
  let rimShadowPts = [
    octRimOut[7], octRimOut[0], octRimOut[1], octRimOut[2], octRimOut[3],
    [octRimOut[3][0] + 13, octRimOut[3][1] + 13],
    [octRimOut[2][0] + 13, octRimOut[2][1] + 13],
    [octRimOut[1][0] + 13, octRimOut[1][1] + 13],
    [octRimOut[0][0] + 13, octRimOut[0][1] + 13],
    [octRimOut[7][0] + 13, octRimOut[7][1] + 13]
  ];
  polyShape(rimShadowPts, 0);

  // Shadow of the Octagonal Step (R=166) onto the SE Plaza Paving
  brush.fill(PAL.shadowWash, 85);
  let stepShadowPts = [
    octStep[7], octStep[0], octStep[1], octStep[2], octStep[3],
    [octStep[3][0] + 7, octStep[3][1] + 7],
    [octStep[2][0] + 7, octStep[2][1] + 7],
    [octStep[1][0] + 7, octStep[1][1] + 7],
    [octStep[0][0] + 7, octStep[0][1] + 7],
    [octStep[7][0] + 7, octStep[7][1] + 7]
  ];
  polyShape(stepShadowPts, 0);
  brush.noFill();

  // Fine architectural 45-degree graphite hatching inside the wall shadows
  brush.hatchStyle("2H", PAL.graphiteHB, 0.18);
  brush.hatch(4.5, 45, { rand: 0.03 });
  brush.noStroke();
  brush.rect(146, 146, 908, wallShadowD, "corner");
  brush.rect(146, 164, wallShadowD, 890, "corner");
  brush.noHatch();

  // 5.2 Crisp Graphite Outlines for Every Limestone Joint & Moulding
  // Draw all slab joints + sunlit bevel highlights
  for (let i = 0; i < slabs.length; i++) {
    let s = slabs[i];
    // Crisp dark graphite joint
    let w = s.type === "wall" ? 0.34 : (s.type === "kerb" ? 0.28 : 0.22);
    brush.set(s.type === "wall" ? "HB" : "2H", PAL.graphiteHB, w);
    brush.rect(s.x, s.y, s.w, s.h, "corner");

    // Sunlit bevel highlight along top & left edge of stone slab
    if (i % 2 === 0) {
      brush.set("2H", PAL.highlight, 0.22);
      brush.line(s.x + 1.2, s.y + 1.2, s.x + s.w - 1.5, s.y + 1.2);
      brush.line(s.x + 1.2, s.y + 1.2, s.x + 1.2, s.y + s.h - 1.5);
    }

    // Chipped edges, spalled corners & hairline cracks on selected limestone slabs
    let n = noise(s.x * 0.03, s.y * 0.03, i);
    if (n > 0.62) {
      drawChippedCorner(s.x, s.y, random(3.5, 7.5), 0);
    } else if (n < 0.28) {
      drawChippedCorner(s.x + s.w, s.y + s.h, random(3.5, 7), 180);
    }
    if (i % 11 === 3 && s.type === "paving") {
      // Hairline fracture across the limestone slab
      brush.set("2H", PAL.graphite2B, 0.18);
      let cx1 = s.x + s.w * random(0.2, 0.8);
      let cy1 = s.y;
      let cxm = cx1 + random(-6, 6);
      let cym = s.y + s.h * 0.5;
      let cx2 = cxm + random(-5, 5);
      let cy2 = s.y + s.h;
      brush.line(cx1, cy1, cxm, cym);
      brush.line(cxm, cym, cx2, cy2);
    }
  }

  // Joints in the diagonal plaza zones between the octagonal step and the 4 chamfered lawns
  brush.set("2H", PAL.graphiteHB, 0.22);
  let octPlazaMid = getOctagonPts(CX, CY, 194);
  for (let i = 0; i < 8; i++) {
    brush.line(octStep[i][0], octStep[i][1], octPlazaMid[i][0], octPlazaMid[i][1]);
  }
  // Connect diagonal octagon corners to the chamfered lawn corners
  for (let [qx, qy] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
    let lPts = getLawnPolygon(qx, qy, 0);
    let midChamX = (lPts[0][0] + lPts[4][0]) * 0.5;
    let midChamY = (lPts[0][1] + lPts[4][1]) * 0.5;
    // Project inward to octagonal step
    let ang = atan2(midChamY - CY, midChamX - CX);
    let stepR = 166 * cos(22.5);
    brush.line(midChamX, midChamY, CX + cos(ang) * stepR, CY + sin(ang) * stepR);
  }

  // Moulded double lines along the 4 narrow stone water channel kerbs
  brush.set("HB", PAL.graphite2B, 0.34);
  for (let seg of [[146, 474], [726, 1054]]) {
    // North & South channel water lips
    brush.line(578, seg[0], 578, seg[1]);
    brush.line(622, seg[0], 622, seg[1]);
    // West & East channel water lips
    brush.line(seg[0], 578, seg[1], 578);
    brush.line(seg[0], 622, seg[1], 622);

    // Carved inner moulding line on kerbs (4px back from water lip)
    brush.set("2H", PAL.graphiteHB, 0.2);
    brush.line(574, seg[0], 574, seg[1]);
    brush.line(626, seg[0], 626, seg[1]);
    brush.line(seg[0], 574, seg[1], 574);
    brush.line(seg[0], 626, seg[1], 626);
    brush.set("HB", PAL.graphite2B, 0.34);
  }

  // 5.3 Octagonal Fountain Step & Moulded Rim Crisp Graphite Detailing
  brush.set("HB", PAL.graphiteHB, 0.34);
  polyShape(octStep, 0);

  // Radial joints on the octagonal step (16 blocks)
  brush.set("2H", PAL.graphiteHB, 0.24);
  for (let i = 0; i < 8; i++) {
    brush.line(octRimOut[i][0], octRimOut[i][1], octStep[i][0], octStep[i][1]);
    let next = (i + 1) % 8;
    let mx1 = (octRimOut[i][0] + octRimOut[next][0]) * 0.5;
    let my1 = (octRimOut[i][1] + octRimOut[next][1]) * 0.5;
    let mx2 = (octStep[i][0] + octStep[next][0]) * 0.5;
    let my2 = (octStep[i][1] + octStep[next][1]) * 0.5;
    brush.line(mx1, my1, mx2, my2);
  }

  // Moulded Octagonal Basin Rim profiles (outer, double torus moulding, inner lip)
  brush.set("2B", PAL.graphite2B, 0.4);
  polyShape(octRimOut, 0);
  polyShape(octRimIn, 0);

  brush.set("2H", PAL.graphiteHB, 0.22);
  polyShape(octRimMid1, 0);
  polyShape(octRimMid2, 0);

  // 8 Radial masonry joints on the octagonal rim + iron dovetail cramp slots!
  for (let i = 0; i < 8; i++) {
    brush.set("HB", PAL.graphite2B, 0.32);
    brush.line(octRimIn[i][0], octRimIn[i][1], octRimOut[i][0], octRimOut[i][1]);

    // Chipped nick along the joint
    let jx = (octRimIn[i][0] + octRimOut[i][0]) * 0.5;
    let jy = (octRimIn[i][1] + octRimOut[i][1]) * 0.5;
    drawChippedCorner(jx, jy, 4.2, i * 45);

    // Traditional architectural iron cramp indent bridging the stone joint
    let ang = 22.5 + i * 45;
    let perp = ang + 90;
    let cx1 = jx + cos(perp) * 5;
    let cy1 = jy + sin(perp) * 5;
    let cx2 = jx - cos(perp) * 5;
    let cy2 = jy - sin(perp) * 5;
    brush.set("rotring", PAL.inkDark, 0.32);
    brush.line(cx1, cy1, cx2, cy2);
    brush.line(cx1 - cos(ang) * 2, cy1 - sin(ang) * 2, cx1 + cos(ang) * 2, cy1 + sin(ang) * 2);
    brush.line(cx2 - cos(ang) * 2, cy2 - sin(ang) * 2, cx2 + cos(ang) * 2, cy2 + sin(ang) * 2);
  }

  // Bold architectural outline around the entire courtyard perimeter wall (110..1090 and 146..1054)
  brush.set("2B", PAL.inkDark, 0.52);
  brush.rect(110, 110, 980, 980, "corner");
  brush.set("HB", PAL.graphite2B, 0.42);
  brush.rect(146, 146, 908, 908, "corner");
  // Inner wall moulding line
  brush.set("2H", PAL.graphiteHB, 0.22);
  brush.rect(116, 116, 968, 968, "corner");
  brush.rect(140, 140, 920, 920, "corner");
}

function drawChippedCorner(x, y, size, baseAng) {
  let a1 = baseAng + 10;
  let a2 = baseAng + 80;
  let pts = [
    [x, y],
    [x + cos(a1) * size, y + sin(a1) * size],
    [x + cos(baseAng + 45) * (size * 0.65), y + sin(baseAng + 45) * (size * 0.65)],
    [x + cos(a2) * size, y + sin(a2) * size]
  ];
  brush.set("rotring", PAL.graphite2B, 0.25);
  polyShape(pts, 0);
  // Highlight on opposite side of chip
  brush.set("2H", PAL.highlight, 0.22);
  brush.line(pts[1][0], pts[1][1], pts[3][0], pts[3][1]);
}

// =============================================================================
// 6. THE FOUR QUADRANT DISORDERS (FRUIT, SANDALS, WET FOOTPRINTS)
// =============================================================================
function drawQuadrantDisorders() {
  // ---------------------------------------------------------------------------
  // QUADRANT 1 (NE): Fallen Split-Open Pomegranate on Lawn Curb & Scattered Arils
  // ---------------------------------------------------------------------------
  let fx = 692, fy = 468;

  // Crimson juice stain bled into the limestone curb
  brush.noStroke();
  brush.fillBleed(0.3, "out");
  brush.fill(PAL.pomCrimson, 75);
  brush.circle(fx + 5, fy + 6, 16, 0.35);

  // Cast shadow of the fallen pomegranate
  brush.fillBleed(0.06, "out");
  brush.fill(PAL.shadowDeep, 140);
  brush.circle(fx + 4.5, fy + 4.5, 13.5, 0.15);

  // Main split pomegranate body
  brush.fill(PAL.pomCrimson, 225);
  brush.circle(fx, fy, 13, 0.12);
  brush.fill(PAL.pomBright, 190);
  brush.circle(fx - 2.5, fy - 2.5, 8.5, 0.1);

  // Split fissure showing creamy pith and jewel-like ruby arils inside
  brush.fill(PAL.pomPith, 230);
  polyShape([
    [fx - 4, fy - 7],
    [fx + 7, fy - 2],
    [fx + 9, fy + 6],
    [fx + 1, fy + 9],
    [fx - 3, fy + 2]
  ], 0.2);

  brush.fill(PAL.pomDeep, 235);
  polyShape([
    [fx - 2, fy - 4],
    [fx + 5, fy - 1],
    [fx + 6, fy + 4],
    [fx + 1, fy + 6]
  ], 0.2);
  brush.noFill();

  // Crisp outline, calyx crown, and scattered ruby seeds (arils) on stone & grass
  brush.set("rotring", PAL.pomDeep, 0.28);
  brush.circle(fx, fy, 13, 0.12);
  // Calyx crown pointing NW
  polyShape([
    [fx - 9, fy - 7],
    [fx - 15, fy - 11],
    [fx - 11, fy - 13],
    [fx - 13, fy - 16],
    [fx - 7, fy - 11]
  ], 0);

  // Scattered ruby arils + pinpoint white specular glints
  let arilOffsets = [
    [1, 0], [3, 2], [4, -1], [2, 4], [0, 3], [5, 3],
    [12, 8], [15, 5], [14, 11], [19, 9], [10, 14], [22, 13], [8, -10], [13, -7]
  ];
  for (let [ax, ay] of arilOffsets) {
    brush.set("rotring", PAL.pomCrimson, 0.45);
    brush.circle(fx + ax, fy + ay, 1.6, 0.05);
    brush.set("rotring", PAL.highlight, 0.22);
    brush.line(fx + ax - 0.5, fy + ay - 0.5, fx + ax, fy + ay - 0.5);
  }

  // ---------------------------------------------------------------------------
  // QUADRANT 2 (NW): Slipped-Off Leather Sandal + Water Splash on Paving
  // ---------------------------------------------------------------------------
  // Damp splash mark beside the North water channel where someone stepped out
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fill(PAL.stoneWet, 115);
  brush.circle(550, 378, 15, 0.4);
  brush.circle(536, 366, 8, 0.35);
  brush.noFill();

  // Draw first leather sandal at (532, 396) angled at -24 deg
  drawLeatherSandal(532, 396, -24, 1);

  // ---------------------------------------------------------------------------
  // QUADRANT 3 (SW): The Second Leather Sandal Kicked Askew + Rolled Small Fruit
  // ---------------------------------------------------------------------------
