  brush.circle(rfx, rfy, 9, 0.1);
  brush.set("2H", PAL.highlight, 0.28);
  brush.arc(rfx - 1, rfy - 1, 5.5, 200, 290);

  // ---------------------------------------------------------------------------
  // QUADRANT 4 (SE): Trail of Wet Bare Footprints Drying on the Limestone Paving
  // ---------------------------------------------------------------------------
  // Stepping diagonally away from the SE octagonal fountain step across the plaza!
  let footprints = [
    { x: 706, y: 702, ang: 42, side: 1, alpha: 155 },   // Right foot (freshest, darkest)
    { x: 734, y: 752, ang: 48, side: -1, alpha: 130 },  // Left foot
    { x: 786, y: 774, ang: 38, side: 1, alpha: 100 },   // Right foot (partially dried)
    { x: 822, y: 824, ang: 45, side: -1, alpha: 70 }    // Left foot (faintest, almost dry)
  ];

  for (let fp of footprints) {
