}

function drawLeatherSandal(x, y, ang, footSide) {
  push();
  translate(x, y);
  rotate(ang);

  // Cast shadow of sandal on limestone
  brush.noStroke();
  brush.fillBleed(0.04, "out");
  brush.fill(PAL.shadowDeep, 140);
  let shadowSole = [
    [-4, -15], [7, -14], [9, -4], [7, 6], [8, 14], [3, 18], [-4, 17], [-6, 8], [-5, -3]
  ];
  polyShape(shadowSole.map(([sx, sy]) => [sx + 3, sy + 3]), 0.35);

  // Leather sole fill
  brush.fill(PAL.sandalSole, 225);
  let solePts = [
    [-4 * footSide, -15], [6 * footSide, -14], [8 * footSide, -4],
    [6 * footSide, 6], [7 * footSide, 14], [2 * footSide, 18],
    [-4 * footSide, 17], [-6 * footSide, 8], [-5 * footSide, -3]
  ];
  polyShape(solePts, 0.35);

  // Darkened heel & forefoot wear mark on insole
  brush.fill(PAL.sandalDark, 150);
  brush.circle(1 * footSide, -7, 5.5, 0.2);
  brush.circle(1 * footSide, 11, 4.5, 0.2);
  brush.noFill();

  // Crisp sole outline & perimeter stitching
  brush.set("rotring", PAL.sandalDark, 0.28);
  polyShape(solePts, 0.35);
  brush.set("2H", PAL.pomPith, 0.18);
  polyShape(solePts.map(([sx, sy]) => [sx * 0.82, sy * 0.88]), 0.35);

  // Crossed leather instep straps & toe loop
  brush.set("HB", PAL.sandalDark, 0.55);
  brush.line(-6 * footSide, 2, 7 * footSide, -5);
  brush.line(-5 * footSide, -5, 6 * footSide, 3);
  brush.set("cpencil", PAL.sandalLeather, 0.45);
  brush.line(-6 * footSide, 1.5, 7 * footSide, -5.5);
  brush.line(-5 * footSide, -5.5, 6 * footSide, 2.5);
  // Toe post ring
  brush.set("rotring", PAL.sandalDark, 0.28);
  brush.circle(-1.5 * footSide, -10, 2.8, 0.1);

  pop();
}

function drawDryingFootprint(x, y, ang, side, alphaVal) {
  // side: 1 = right foot, -1 = left foot
  // Heading direction 'ang' (in degrees, where +45 is SE)
  push();
  translate(x, y);
  rotate(ang - 90); // Local +Y is forward (toe direction)

  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.55, 0.65);

  // Forefoot pad & outer arch bridge
  brush.fill(PAL.stoneWet, alphaVal);
  let archPts = [
    [-3 * side, 2],
    [5 * side, 3],
    [6.5 * side, 9],
    [3 * side, 12.5],
    [-4.5 * side, 11],
    [-5.5 * side, 6]
  ];
  polyShape(archPts, 0.35);

  // Narrow outer bridge connecting heel to forefoot
  let bridgePts = [
    [2 * side, -5],
    [5.5 * side, -4],
    [6 * side, 4],
    [2.5 * side, 4]
  ];
  polyShape(bridgePts, 0.2);

  // Rounded heel pad
  brush.circle(1.5 * side, -8, 4.8, 0.2);

  // 5 Distinct Toe Imprints (from big toe on inner side -side to little toe on outer side +side)
  let toes = [
    { dx: -4.2 * side, dy: 15.5, r: 2.3 }, // Big toe
    { dx: -1.2 * side, dy: 16.2, r: 1.6 }, // 2nd toe
    { dx: 1.4 * side,  dy: 15.6, r: 1.5 }, // 3rd toe
    { dx: 3.8 * side,  dy: 14.5, r: 1.4 }, // 4th toe
    { dx: 5.8 * side,  dy: 12.8, r: 1.2 }  // Little toe
  ];
  for (let t of toes) {
    brush.circle(t.dx, t.dy, t.r, 0.15);
  }

  // Tiny scattered water droplets around the fresher footprints
  if (alphaVal > 110) {
    brush.fill(PAL.stoneWetEdge, alphaVal);
    brush.circle(-7 * side, 4, 1.1, 0.2);
    brush.circle(8 * side, -2, 0.9, 0.2);
    brush.circle(0, 19, 1.0, 0.2);
  }
  brush.noFill();

  // Subtle evaporative drying watermark rim in fine 2H pencil
  brush.set("2H", PAL.stoneWetEdge, 0.18);
  polyShape(archPts, 0.35);
  brush.circle(1.5 * side, -8, 4.8, 0.2);

  pop();
}

// =============================================================================
// 7. OVERHANGING POMEGRANATE BRANCH (NE CORNER)
// =============================================================================
function drawOverhangingPomegranateBranch() {
  // Branch enters from NE margin (1125, 148) and reaches out over the NE lawn & North water channel (618, 355)
  let mainSpine = [
    [1135, 145],
    [1045, 182],
    [945, 215],
    [838, 258],
    [732, 305],
    [618, 352]
  ];
  let subBranch1 = [
    [945, 215],
    [885, 168],
    [805, 152],
    [735, 162]
  ];
  let subBranch2 = [
    [838, 258],
    [808, 345],
    [782, 428],
    [745, 488]
  ];
  let subBranch3 = [
    [732, 305],
    [678, 265],
    [625, 252]
  ];

  // Foliage leaf clusters along the branches: [x, y, angle, length, width]
  let leaves = [];
  function populateLeaves(spine, count) {
    for (let i = 0; i < spine.length - 1; i++) {
      let p1 = spine[i], p2 = spine[i + 1];
      let baseAng = atan2(p2[1] - p1[1], p2[0] - p1[0]);
      for (let k = 0; k < count; k++) {
        let t = (k + 0.5) / count;
        let lx = lerp(p1[0], p2[0], t);
        let ly = lerp(p1[1], p2[1], t);
        // Opposite lance-shaped leaves characteristic of Punica granatum
        leaves.push({ x: lx, y: ly, ang: baseAng + 58 + random(-14, 14), len: random(22, 34), w: random(7, 10) });
        leaves.push({ x: lx, y: ly, ang: baseAng - 58 + random(-14, 14), len: random(22, 34), w: random(7, 10) });
      }
    }
  }
  populateLeaves(mainSpine, 4);
  populateLeaves(subBranch1, 3);
  populateLeaves(subBranch2, 3);
  populateLeaves(subBranch3, 2);

  // Hanging ripe pomegranates on the branch:
  let fruits = [
    { x: 642, y: 342, r: 16.5, crownAng: 215 }, // Hanging right over the North channel & walkway!
    { x: 774, y: 416, r: 18.0, crownAng: 125 }, // Hanging over the NE lawn corner (above the fallen fruit)
    { x: 878, y: 234, r: 15.0, crownAng: 250 }  // Near the upper NE walkway
  ];

  // 7.1 Cast Shadow of the Overhanging Branch onto the Courtyard Below (+42px, +42px)
  let sOffX = 42, sOffY = 42;
  brush.noStroke();
  brush.fillBleed(0.12, "out");
  brush.fill(PAL.shadowDeep, 95);

  for (let lf of leaves) {
    let sx = lf.x + sOffX, sy = lf.y + sOffY;
    if (sx < 1090 && sy < 1090) {
      let rad = lf.ang;
      let tipX = sx + cos(rad) * lf.len;
      let tipY = sy + sin(rad) * lf.len;
      let perpX = -sin(rad) * (lf.w * 0.5);
      let perpY = cos(rad) * (lf.w * 0.5);
      let midX = (sx + tipX) * 0.5;
      let midY = (sy + tipY) * 0.5;
      polyShape([
        [sx, sy],
        [midX + perpX, midY + perpY],
        [tipX, tipY],
        [midX - perpX, midY - perpY]
      ], 0.3);
    }
  }
  for (let fr of fruits) {
    brush.circle(fr.x + sOffX, fr.y + sOffY, fr.r, 0.15);
  }
  brush.noFill();

  // Woody branch shadow splines
  brush.set("charcoal", PAL.shadowDeep, 0.9);
  brush.spline(mainSpine.map(([x, y]) => [min(x + sOffX, 1110), y + sOffY, 0.8]), 0.4);
  brush.spline(subBranch1.map(([x, y]) => [x + sOffX, y + sOffY, 0.5]), 0.4);
  brush.spline(subBranch2.map(([x, y]) => [x + sOffX, y + sOffY, 0.55]), 0.4);
  brush.spline(subBranch3.map(([x, y]) => [x + sOffX, y + sOffY, 0.45]), 0.4);

  // 7.2 Draw the Actual Woody Branches
  function renderBranch(pts, baseW) {
    for (let i = 0; i < pts.length - 1; i++) {
      let w = map(i, 0, pts.length - 1, baseW, baseW * 0.32);
      // Dark shadow underside of branch
      brush.set("2B", PAL.inkDark, w);
      brush.line(pts[i][0] + 1.5, pts[i][1] + 1.5, pts[i + 1][0] + 1.5, pts[i + 1][1] + 1.5);
      // Warm woody core
      brush.set("cpencil", PAL.branchWood, w * 0.9);
      brush.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
      // Sunlit bark highlight on NW edge
      brush.set("2H", PAL.branchLight, w * 0.45);
      brush.line(pts[i][0] - 1.2, pts[i][1] - 1.2, pts[i + 1][0] - 1.2, pts[i + 1][1] - 1.2);
    }
  }
  renderBranch(mainSpine, 1.65);
  renderBranch(subBranch1, 0.95);
  renderBranch(subBranch2, 1.05);
  renderBranch(subBranch3, 0.8);

  // 7.3 Draw the Glossy Pomegranate Foliage (Watercolour Glazes + Crisp Graphite Midribs)
  brush.noStroke();
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.45, 0.35);

  for (let i = 0; i < leaves.length; i++) {
    let lf = leaves[i];
    let tipX = lf.x + cos(lf.ang) * lf.len;
    let tipY = lf.y + sin(lf.ang) * lf.len;
    let perpX = -sin(lf.ang) * (lf.w * 0.5);
    let perpY = cos(lf.ang) * (lf.w * 0.5);
    let midX = (lf.x + tipX) * 0.5;
    let midY = (lf.y + tipY) * 0.5;
    let lPts = [
      [lf.x, lf.y],
      [midX + perpX, midY + perpY],
      [tipX, tipY],
      [midX - perpX, midY - perpY]
    ];

    let col = (i % 3 === 0) ? PAL.oliveDeep : (i % 3 === 1 ? PAL.sapGreen : PAL.sapLight);
    brush.fill(col, 210);
    polyShape(lPts, 0.35);
  }
  brush.noFill();

  // Crisp graphite leaf outlines & pale central midribs
  for (let lf of leaves) {
    let tipX = lf.x + cos(lf.ang) * lf.len;
    let tipY = lf.y + sin(lf.ang) * lf.len;
    let perpX = -sin(lf.ang) * (lf.w * 0.5);
    let perpY = cos(lf.ang) * (lf.w * 0.5);
    let midX = (lf.x + tipX) * 0.5;
    let midY = (lf.y + tipY) * 0.5;

    brush.set("2H", PAL.oliveShadow, 0.22);
    polyShape([
      [lf.x, lf.y],
      [midX + perpX, midY + perpY],
      [tipX, tipY],
      [midX - perpX, midY - perpY]
    ], 0.35);

    brush.set("2H", PAL.turfHighlight, 0.2);
    brush.line(lf.x, lf.y, tipX, tipY);
  }

  // 7.4 Draw the Hanging Ripe Pomegranates (Jewel-like Crimson Focal Accent)
  for (let fr of fruits) {
    // Deep crimson base wash
    brush.noStroke();
    brush.fillBleed(0.08, "in");
    brush.fillTexture(0.5, 0.4);
    brush.fill(PAL.pomDeep, 235);
    brush.circle(fr.x, fr.y, fr.r, 0.12);

    // Rich ruby middle glaze
    brush.fill(PAL.pomRuby, 210);
    brush.circle(fr.x - 2, fr.y - 2, fr.r * 0.82, 0.1);

    // Sunlit vermilion-scarlet shoulder on NW side
    brush.fill(PAL.pomBright, 195);
    brush.circle(fr.x - fr.r * 0.28, fr.y - fr.r * 0.28, fr.r * 0.48, 0.1);
    brush.noFill();

    // Flared 5-pointed calyx crown
    let ca = fr.crownAng;
    let cx0 = fr.x + cos(ca) * (fr.r * 0.85);
    let cy0 = fr.y + sin(ca) * (fr.r * 0.85);
    let crownPts = [
      [cx0 + cos(ca - 55) * 5, cy0 + sin(ca - 55) * 5],
      [cx0 + cos(ca - 35) * 9, cy0 + sin(ca - 35) * 9],
      [cx0 + cos(ca) * 6,      cy0 + sin(ca) * 6],
      [cx0 + cos(ca + 35) * 9, cy0 + sin(ca + 35) * 9],
      [cx0 + cos(ca + 55) * 5, cy0 + sin(ca + 55) * 5]
    ];
    brush.noStroke();
    brush.fill(PAL.pomCrimson, 230);
    polyShape(crownPts, 0);
    brush.noFill();

    // Crisp graphite contour & leathery specular highlight
    brush.set("rotring", PAL.pomDeep, 0.34);
    brush.circle(fr.x, fr.y, fr.r, 0.12);
    polyShape(crownPts, 0);

    // Specular white crescent highlight on NW leathery skin
    brush.set("rotring", PAL.highlight, 0.35);
    brush.arc(fr.x - 2, fr.y - 2, fr.r * 0.62, 195, 265);
    brush.circle(fr.x - fr.r * 0.35, fr.y - fr.r * 0.35, 1.8, 0.05);
  }
}

// =============================================================================
// 8. ARCHITECTURAL PRESENTATION ANNOTATIONS, DATUM MARKS & SCALE BAR
// =============================================================================
function drawArchitecturalAnnotations() {
  // Outer presentation sheet border with double fine rule
  brush.set("2H", PAL.graphite2H, 0.22);
  brush.rect(36, 36, 1128, 1128, "corner");
  brush.set("HB", PAL.graphiteHB, 0.32);
  brush.rect(42, 42, 1116, 1116, "corner");

  // Architectural 45-degree dimension ticks along top and left margin datum lines
  let tickCoords = [110, 146, 236, 520, 578, 600, 622, 680, 964, 1054, 1090];
  brush.set("2H", PAL.graphiteHB, 0.2);
  // Continuous dimension line at y = 78 and x = 78
  brush.line(102, 78, 1098, 78);
  brush.line(78, 102, 78, 1098);

  brush.set("rotring", PAL.inkDark, 0.28);
  for (let c of tickCoords) {
    // Top dimension slash + perpendicular tick
    brush.line(c - 3.5, 81.5, c + 3.5, 74.5);
    brush.line(c, 73, c, 83);
    // Left dimension slash + perpendicular tick
    brush.line(74.5, c + 3.5, 81.5, c - 3.5);
    brush.line(73, c, 83, c);
  }

  // 4 Axis Datum Target Circles at N, S, E, W centerlines
  let datumCenters = [[600, 58], [600, 1142], [58, 600], [1142, 600]];
  for (let [dx, dy] of datumCenters) {
    brush.set("rotring", PAL.graphite2B, 0.26);
    brush.circle(dx, dy, 9, 0.02);
    brush.circle(dx, dy, 4, 0.02);
    brush.line(dx - 13, dy, dx + 13, dy);
    brush.line(dx, dy - 13, dx, dy + 13);
  }

  // Graphic Architectural Scale Bar at Bottom-Left Margin (x: 110..310, y: 1136)
  let sx = 110, sy = 1136;
  brush.set("rotring", PAL.graphite2B, 0.25);
  brush.rect(sx, sy, 200, 5, "corner");
  // Alternating filled segments (20px each)
  for (let i = 0; i < 10; i++) {
    let segX = sx + i * 20;
    brush.line(segX, sy - 3, segX, sy + 5);
    if (i % 2 === 0) {
      brush.line(segX, sy + 1.5, segX + 20, sy + 1.5);
      brush.line(segX, sy + 3.2, segX + 20, sy + 3.2);
    }
  }
  brush.line(sx + 200, sy - 3, sx + 200, sy + 5);

  // Architect's Compass Rose / North Indicator at Bottom-Right Margin (1068, 1136)
  let nx = 1068, ny = 1134;
  brush.set("2H", PAL.graphiteHB, 0.22);
  brush.circle(nx, ny, 14, 0.02);
  brush.circle(nx, ny, 10, 0.02);
  brush.line(nx - 18, ny, nx + 18, ny);
  brush.line(nx, ny - 22, nx, ny + 18);
  // Shaded North pointer
  brush.set("rotring", PAL.inkDark, 0.3);
  polyShape([[nx, ny - 22], [nx - 4, ny - 6], [nx, ny - 9], [nx + 4, ny - 6]], 0);
}

// Bagru Diya Grid — Hyperreal Unglazed Clay Oil Lamps & Hand-Block Impressions
// p5.js 2.x + p5.brush (WEBGL)

const PALETTE = {
  ground: "#d5ddde",        // Cool bleached khadi / river-limestone ground
  trayLight: "#dee5e4",     // Pale split-bamboo highlight
  trayMid: "#96a4a8",       // Cool weathered reed midtone
  trayDark: "#4e606e",      // Cool slate bamboo shadow
  indigoDeep: "#142233",    // Deep Bagru vat indigo shadow
  indigoMid: "#27415c",     // Mid natural indigo wash
  indigoSoft: "#4f6d87",    // Faded cool indigo resist
  indigoPale: "#8aa1b4",    // Mist indigo-slate bleed
  ironBlack: "#14171c",     // Syahi (fermented iron-rust & jaggery black)
  ironPlum: "#292228",      // Oxidized iron-charcoal
  madderDeep: "#6e2028",    // Deep alizarin-madder crimson
  madderMid: "#94323a",     // Bagru madder terracotta red
  madderSoft: "#b3585c",    // Faded madder stamp blush
  clayWet: "#4f342c",       // Oil-darkened porous clay seepage
  ochreDeep: "#786248",     // Dark river-mud dabu ochre
  ochreMid: "#9b8366",      // Unglazed clay ochre
  ochreLight: "#cbbba4",    // Dry chalky clay rim highlight
  gheeDeep: "#8c692c",      // Deep amber clarified butter
  gheeGold: "#c49e50",      // Luminous pool of melted ghee
  gheeLight: "#e3c985",     // Warm oil sheen
  ashGrey: "#b8c2c7",       // Cool wood-ash & soot rim
  specular: "#f5f9fa",      // Crisp overhead skylight reflection
  specularBlue: "#d4e6f0"   // Cool sky-tinted meniscus glint
};

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);

  // Custom woodblock grain & dry mineral stipple brush
  brush.add("woodblock_gouge", {
    type: "custom",
    weight: 3.5,
    scatter: 0.15,
    opacity: 150,
    spacing: 0.45,
    pressure: [0.4, 1.3, 0.3],
    tip: (_m) => {
      _m.rotate(25);
      _m.rect(-2.2, -0.5, 4.4, 1.0);
    },
    rotate: "natural",
    markerTip: false,
    noise: 0.8
  });

  brush.add("clay_pore", {
    type: "spray",
    weight: 6,
    scatter: 1.8,
    opacity: 65,
    spacing: 0.6,
    pressure: [0.6, 1.2, 0.6]
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  randomSeed(4219);
  noiseSeed(8471);

  background(PALETTE.ground);

  const trayMargin = 86;
  const traySize = width - trayMargin * 2;

  // ---------------------------------------------------------------------------
  // 1. BUILD LAMP DATA GRID (4x4 rows of unglazed clay lamps with block quirks)
  // ---------------------------------------------------------------------------
  const lamps = buildLampGrid();

  // ---------------------------------------------------------------------------
  // 2. BATCHED WATERCOLOR FILLS (Mottled edge bleed, grouped by pigment color)
  // ---------------------------------------------------------------------------
  brush.noField();
  drawBackgroundAndTrayWashes(trayMargin, traySize);
  drawBatchedLampWatercolors(lamps);

  // ---------------------------------------------------------------------------
  // 3. WOVEN BAMBOO TRAY TEXTURE & BAGRU REGISTRATION BORDERS
  // ---------------------------------------------------------------------------
  drawWovenTrayStructure(trayMargin, traySize, lamps);
  drawTrayBoundRim(trayMargin, traySize);
  drawBlockRegistrationMarks(trayMargin, traySize, lamps);

  // ---------------------------------------------------------------------------
  // 4. HYPERREAL CLAY LAMPS + HAND-BLOCK DOUBLED / FAINT IMPRESSIONS
  // ---------------------------------------------------------------------------
  for (let i = 0; i < lamps.length; i++) {
    const L = lamps[i];
    if (L.isDoubled) {
      drawGhostBlockImpression(L);
    }
    drawHyperrealLamp(L);
  }

  // ---------------------------------------------------------------------------
  // 5. FINAL SURFACE INCIDENTS: SOOT DRIFT, CLAY DUST & DABU CRACKLE
  // ---------------------------------------------------------------------------
  drawSurfaceIncidents(lamps, trayMargin, traySize);

  noLoop();
}

// =============================================================================
// GEOMETRY & GRID INITIALIZATION
// =============================================================================

function angleDiff(a, b) {
  let d = (a - b) % 360;
  if (d < -180) d += 360;
  if (d > 180) d -= 360;
  return d;
}

function buildLampGrid() {
  const lamps = [];
  const cols = 4;
  const rows = 4;
  const startX = 248;
  const startY = 252;
  const stepX = 236;
  const stepY = 234;

  // Row-level hand-block misregistration shifts
  const rowShiftX = [-10, 13, -7, 11];
  const rowShiftY = [4, -6, 8, -5];
  const rowSkew = [-0.8, 1.1, -0.5, 0.9];

  // Specific cells that behave as fainter impressions or double-struck blocks
  const faintSet = new Set(["0,2", "1,0", "2,3", "3,1"]);
  const doubledSet = new Set(["0,1", "1,3", "2,1", "3,2"]);
  const emberSet = new Set(["0,0", "1,2", "2,2", "3,3"]);

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const key = `${r},${c}`;
      const isFaint = faintSet.has(key);
      const isDoubled = doubledSet.has(key);
      const hasEmber = emberSet.has(key);

      const cx =
        startX +
        c * stepX +
        rowShiftX[r] +
        random(-5, 5);
      const cy =
        startY +
        r * stepY +
        rowShiftY[r] +
        (c - 1.5) * rowSkew[r] * 4 +
        random(-5, 5);

      const strength = isFaint ? random(0.44, 0.58) : random(0.88, 1.0);

      // Generate 10 thumb-pressed indentations around the rim (excluding top spout)
      const thumbCount = 10;
      const thumbs = [];
      for (let t = 0; t < thumbCount; t++) {
        // Distribute from -42 deg around the bottom to +222 deg
        const baseAng = map(t, 0, thumbCount - 1, -40, 220);
        thumbs.push({
          angle: baseAng + random(-4, 4),
          width: random(13, 17),
          depth: random(3.2, 5.2),
          ridgeStrength: random(0.7, 1.15)
        });
      }

      lamps.push({
        row: r,
        col: c,
        cx,
        cy,
        rot: random(-6.5, 6.5) + rowSkew[r],
        outerR: random(87, 92),
        innerR: random(60, 64),
        gheeR: random(44, 49),
        strength,
        isFaint,
        isDoubled,
        hasEmber,
        seed: Math.floor(random(1000, 99999)),
        thumbs,
        // Per-block registration offsets (Bagru multi-block printing)
        indigoShift: { x: random(5, 11), y: random(6, 12) },
        ochreShift: { x: random(-4, 4), y: random(-4, 4) },
        madderShift: { x: random(-7, 6), y: random(-6, 7) },
        syahiShift: { x: random(-3.5, 3.5), y: random(-3.5, 3.5) },
        // Ghost offset if double-stamped
        ghostShift: {
          x: random(15, 22) * (c % 2 === 0 ? 1 : -1),
          y: random(-16, -10),
          rot: random(-5, 5)
        }
      });
    }
  }
  return lamps;
}

/**
 * Evaluates a point on the clay lamp's outer or inner contour at local angle `deg`.
 * `deg = -90` is the pinched top spout (nok) where the cotton wick rests.
 */
function evalLampContour(L, deg, isInner = false, radialOffset = 0, shiftX = 0, shiftY = 0, extraRot = 0) {
  const dSpout = angleDiff(deg, -90);
  const absSpout = abs(dSpout);

  // Pinched beak protrusion at -90 deg
  const beakTip = exp(-pow(dSpout / 21, 2));
  // Thumb-pinched narrowing on either side of the beak (-118 and -62 deg)
  const pinchLeft = exp(-pow(angleDiff(deg, -118) / 16, 2));
  const pinchRight = exp(-pow(angleDiff(deg, -62) / 16, 2));

  let r = (isInner ? L.innerR : L.outerR) + radialOffset;

  if (isInner) {
    // Inner basin narrows into a tight wick channel at the spout
    r += beakTip * 27 - (pinchLeft + pinchRight) * 6.5;
  } else {
    // Outer wall forms a pronounced teardrop beak with lateral thumb-pinches
    r += beakTip * 33 - (pinchLeft + pinchRight) * 7.8;
  }

  // Apply thumb-pressed scalloped indentations around the clay rim
  let thumbWave = 0;
  for (let i = 0; i < L.thumbs.length; i++) {
    const th = L.thumbs[i];
    const dt = angleDiff(deg, th.angle);
    if (abs(dt) < th.width * 1.8) {
      // Thumb press pushes inner rim slightly inward/outward and scallops outer rim
      const bell = exp(-pow(dt / (th.width * 0.65), 2));
      const ridge = exp(-pow((abs(dt) - th.width * 0.72) / 4.5, 2));
      if (isInner) {
        thumbWave += -bell * th.depth * 0.55 + ridge * 1.6;
      } else {
        thumbWave += -bell * th.depth * 0.85 + ridge * 2.2;
      }
    }
  }
  r += thumbWave;

  // Subtle hand-thrown clay asymmetry
  const n = noise(L.seed + cos(deg) * 1.2, L.seed + sin(deg) * 1.2);
  r += (n - 0.5) * 4.5;

  const finalAng = deg + L.rot + extraRot;
  return {
    x: L.cx + shiftX + cos(finalAng) * r,
    y: L.cy + shiftY + sin(finalAng) * r,
    r,
    ang: finalAng
  };
}

// =============================================================================
// LAYER 2: BATCHED WATERCOLOR WASHES (MOTTLED BLEED)
// =============================================================================

function drawBackgroundAndTrayWashes(trayMargin, traySize) {
  brush.noStroke();

  // Batch 1: Cool Indigo-Slate Peripheral Border Wash (outside tray)
  brush.fill(PALETTE.indigoDeep, 95);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.7, 0.6);
  brush.rect(0, 0, width, trayMargin + 10, "corner");
  brush.rect(0, height - trayMargin - 10, width, trayMargin + 10, "corner");
  brush.rect(0, trayMargin, trayMargin + 10, traySize, "corner");
  brush.rect(width - trayMargin - 10, trayMargin, trayMargin + 10, traySize, "corner");

  // Batch 2: Cool Dabu Indigo Horizontal Resist Bands across the tray floor
  brush.fill(PALETTE.indigoPale, 52);
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.65, 0.5);
  const bandY = [252, 486, 720, 954];
  for (let i = 0; i < bandY.length; i++) {
    brush.rect(trayMargin + 22, bandY[i] - 78, traySize - 44, 156, "corner");
  }

  // Batch 3: Subtle River-Mud Ochre Tray UndertonePatches
  brush.fill(PALETTE.ochreMid, 36);
  brush.fillBleed(0.3, "out");
  brush.fillTexture(0.6, 0.45);
  brush.rect(trayMargin + 36, trayMargin + 36, traySize - 72, traySize - 72, "corner");

  brush.noFill();
}

function traceLampWaterPolygon(L, isInner, radialOffset, shiftX, shiftY, extraRot = 0, steps = 20) {
  brush.beginShape(0.35);
  for (let i = 0; i < steps; i++) {
    const deg = map(i, 0, steps, 0, 360);
    const pt = evalLampContour(L, deg, isInner, radialOffset, shiftX, shiftY, extraRot);
    brush.vertex(pt.x, pt.y);
  }
  brush.endShape(true);
}

function drawBatchedLampWatercolors(lamps) {
  brush.noStroke();

  // --- BATCH A1: Ghost Indigo Shadows for Doubled Lamps ---
  brush.fill(PALETTE.indigoSoft, 55);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.65, 0.55);
  for (const L of lamps) {
    if (L.isDoubled) {
      traceLampWaterPolygon(
        L,
        false,
        2,
        L.ghostShift.x + L.indigoShift.x,
        L.ghostShift.y + L.indigoShift.y,
        L.ghostShift.rot,
        18
      );
    }
  }

  // --- BATCH A2: Deep Indigo Cast Shadows (Misregistered Shadow Block) ---
  brush.fill(PALETTE.indigoDeep, 125);
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.7, 0.65);
  for (const L of lamps) {
    if (!L.isFaint) {
      traceLampWaterPolygon(
        L,
        false,
        3,
        L.indigoShift.x + 5,
        L.indigoShift.y + 7,
        0,
        20
      );
    }
  }

  // --- BATCH A3: Fainter Lamp Indigo Shadows ---
  brush.fill(PALETTE.indigoMid, 75);
  brush.fillBleed(0.26, "out");
  brush.fillTexture(0.72, 0.6);
  for (const L of lamps) {
    if (L.isFaint) {
      traceLampWaterPolygon(
        L,
        false,
        2,
        L.indigoShift.x + 4,
        L.indigoShift.y + 6,
        0,
        20
      );
    }
  }

  // --- BATCH B1: Mud-Clay Ochre Outer Body (Full Strength Lamps) ---
  brush.fill(PALETTE.ochreMid, 145);
  brush.fillBleed(0.2, "out");
  brush.fillTexture(0.68, 0.62);
  for (const L of lamps) {
    if (!L.isFaint) {
      traceLampWaterPolygon(L, false, 0, L.ochreShift.x, L.ochreShift.y, 0, 22);
    }
  }

  // --- BATCH B2: Mud-Clay Ochre Outer Body (Fainter & Doubled Ghost Lamps) ---
  brush.fill(PALETTE.ochreMid, 78);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.75, 0.65);
  for (const L of lamps) {
    if (L.isFaint) {
      traceLampWaterPolygon(L, false, 0, L.ochreShift.x, L.ochreShift.y, 0, 20);
    }
    if (L.isDoubled) {
      traceLampWaterPolygon(
        L,
        false,
        -2,
        L.ghostShift.x,
        L.ghostShift.y,
        L.ghostShift.rot,
        18
      );
    }
  }

  // --- BATCH C1: Madder-Alizarin Red Block (Misregistered Rim & Inner Basin) ---
  brush.fill(PALETTE.madderMid, 130);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.7, 0.65);
  for (const L of lamps) {
    if (!L.isFaint) {
      traceLampWaterPolygon(L, false, -5, L.madderShift.x, L.madderShift.y, 0, 20);
    }
  }

  // --- BATCH C2: Madder-Alizarin Red Block (Fainter Lamps + Deep Basin Core) ---
  brush.fill(PALETTE.madderDeep, 105);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.65, 0.6);
  for (const L of lamps) {
    traceLampWaterPolygon(
      L,
      true,
      L.isFaint ? -4 : 2,
      L.madderShift.x * 0.7,
      L.madderShift.y * 0.7,
      0,
      20
    );
  }

  // --- BATCH D: Wet Oil Seepage Ring + Clarified Ghee Pool ---
  brush.fill(PALETTE.clayWet, 120);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.55, 0.5);
  for (const L of lamps) {
    if (!L.isFaint) {
      brush.circle(L.cx, L.cy + 3, L.gheeR + 9, 0.18);
    }
  }

  brush.fill(PALETTE.gheeGold, 155);
  brush.fillBleed(0.14, "out");
  brush.fillTexture(0.5, 0.45);
  for (const L of lamps) {
    // Pool of ghee in the center of the clay basin
    brush.circle(L.cx, L.cy + 4, L.gheeR * (L.isFaint ? 0.88 : 1.0), 0.14);
  }

  // --- BATCH E: Cool Indigo Basin Shadow Crescent & Iron-Black Soot Bloom ---
  brush.fill(PALETTE.indigoDeep, 95);
  brush.fillBleed(0.2, "in");
  brush.fillTexture(0.6, 0.5);
  for (const L of lamps) {
    const spoutPt = evalLampContour(L, -90, false, -6, L.syahiShift.x, L.syahiShift.y);
    brush.circle(spoutPt.x, spoutPt.y + 4, L.isFaint ? 18 : 24, 0.25);
  }

  brush.noFill();
}

// =============================================================================
// LAYER 3: WOVEN BAMBOO TRAY & HAND-BLOCK REGISTRATION BORDERS
// =============================================================================

function isInsideAnyOpaqueLamp(x, y, lamps) {
  for (let i = 0; i < lamps.length; i++) {
    const L = lamps[i];
    if (L.isFaint) continue; // Let tray weave show faintly through starved stamps!
    const dx = x - L.cx;
    const dy = y - L.cy;
    if (dx * dx + dy * dy < (L.outerR - 8) * (L.outerR - 8)) {
      return true;
    }
  }
  return false;
}

function drawWovenTrayStructure(trayMargin, traySize, lamps) {
  const innerStart = trayMargin + 26;
  const innerEnd = trayMargin + traySize - 26;
  const stripW = 24;
  const numStrips = Math.floor((innerEnd - innerStart) / stripW);

  // Draw 2-over-2 twill split-bamboo basketry weave
  for (let r = 0; r < numStrips; r++) {
    const y0 = innerStart + r * stripW;
    const yMid = y0 + stripW * 0.5;

    for (let c = 0; c < numStrips; c++) {
      const x0 = innerStart + c * stripW;
      const xMid = x0 + stripW * 0.5;

      // Skip heavy interior strokes directly underneath opaque clay lamps
      if (isInsideAnyOpaqueLamp(xMid, yMid, lamps)) continue;

      // Twill pattern: (r + c) mod 4 determines whether horizontal or vertical strip is on top
      const horizOnTop = (r + c) % 4 < 2;

      if (horizOnTop) {
        // Horizontal bamboo strip segment
        brush.set("2H", PALETTE.trayMid, 0.9);
        for (let f = -7; f <= 7; f += 4.5) {
          brush.line(x0 + 1, yMid + f, x0 + stripW - 1, yMid + f + random(-0.6, 0.6));
        }
        // Highlight reed fiber along center of strip
        brush.set("cpencil", PALETTE.trayLight, 0.75);
        brush.line(x0 + 3, yMid - 1.5, x0 + stripW - 3, yMid - 1.5);

        // Dark indigo-slate shadow where strip tucks under vertical neighbor
        if ((r + c) % 4 === 1) {
          brush.set("charcoal", PALETTE.indigoDeep, 0.85);
          brush.line(x0 + stripW - 1, y0 + 2, x0 + stripW - 1, y0 + stripW - 2);
        }
      } else {
        // Vertical bamboo strip segment
        brush.set("2H", PALETTE.trayDark, 0.9);
        for (let f = -7; f <= 7; f += 4.5) {
          brush.line(xMid + f, y0 + 1, xMid + f + random(-0.6, 0.6), y0 + stripW - 1);
        }
        // Cool highlight reed fiber
        brush.set("cpencil", PALETTE.indigoPale, 0.65);
        brush.line(xMid - 1.5, y0 + 3, xMid - 1.5, y0 + stripW - 3);

        // Tuck shadow at bottom edge of vertical overlap
        if ((r + c) % 4 === 3) {
          brush.set("charcoal", PALETTE.indigoDeep, 0.85);
          brush.line(x0 + 2, y0 + stripW - 1, x0 + stripW - 2, y0 + stripW - 1);
        }
      }
    }
  }
}

function drawTrayBoundRim(trayMargin, traySize) {
  const x1 = trayMargin;
  const y1 = trayMargin;
  const x2 = trayMargin + traySize;
  const y2 = trayMargin + traySize;
  const rimThick = 28;

  // Deep indigo shadow cast inward by the raised bundled bamboo rim
  brush.set("charcoal", PALETTE.indigoDeep, 2.2);
  brush.rect(x1 + rimThick, y1 + rimThick, traySize - rimThick * 2, traySize - rimThick * 2, "corner");

  // Concentric bundled bamboo rods forming the tray wall
  for (let offset = 0; offset <= rimThick; offset += 4) {
    const col =
      offset < 10
        ? PALETTE.indigoDeep
        : offset < 20
        ? PALETTE.trayDark
        : PALETTE.ochreLight;
    brush.set("HB", col, 1.15);
    brush.rect(x1 + offset, y1 + offset, traySize - offset * 2, traySize - offset * 2, "corner");
  }

  // Diagonal rattan & indigo-cord bindings lashed around the tray rim
  const step = 34;
  for (let pos = x1 + 36; pos < x2 - 36; pos += step) {
    // Top & bottom rim bindings
    for (const [ry, dir] of [
      [y1, 1],
      [y2 - rimThick, -1]
    ]) {
      brush.set("2B", PALETTE.indigoDeep, 1.3);
      brush.line(pos - 6, ry - 2, pos + 8, ry + rimThick + 2);
      brush.line(pos - 2, ry - 2, pos + 12, ry + rimThick + 2);
      brush.set("cpencil", PALETTE.ochreLight, 0.9);
      brush.line(pos - 4, ry, pos + 10, ry + rimThick);
    }

    // Left & right rim bindings
    for (const [rx, dir] of [
      [x1, 1],
      [x2 - rimThick, -1]
    ]) {
      brush.set("2B", PALETTE.indigoDeep, 1.3);
      brush.line(rx - 2, pos - 6, rx + rimThick + 2, pos + 8);
      brush.line(rx - 2, pos - 2, rx + rimThick + 2, pos + 12);
      brush.set("cpencil", PALETTE.ochreLight, 0.9);
      brush.line(rx, pos - 4, rx + rimThick, pos + 10);
    }
  }
}

function drawBlockRegistrationMarks(trayMargin, traySize, lamps) {
  // Bagru woodblock printer's registration crosses & stepped border chevrons
  const corners = [
    [46, 46],
    [width - 46, 46],
    [46, height - 46],
    [width - 46, height - 46]
  ];

  for (const [cx, cy] of corners) {
    // Indigo registration cross
    brush.set("rotring", PALETTE.indigoDeep, 1.1);
    brush.line(cx - 18, cy, cx + 18, cy);
    brush.line(cx, cy - 18, cx, cy + 18);
    brush.circle(cx, cy, 9, 0.1);

    // Slightly misregistered madder-alizarin cross
    brush.set("rotring", PALETTE.madderMid, 0.95);
    brush.line(cx - 14 + 4, cy - 3, cx + 14 + 4, cy - 3);
    brush.line(cx + 4, cy - 14 - 3, cx + 4, cy + 14 - 3);
  }

  // Row alignment ticks on left and right margins showing row-to-row misregistration
  const rowYs = [252, 486, 720, 954];
  const rowShiftX = [-10, 13, -7, 11];
  for (let r = 0; r < 4; r++) {
    const ry = rowYs[r];
    const sx = rowShiftX[r];
    // Left margin carved block comb mark
    brush.set("woodblock_gouge", PALETTE.ironBlack, 0.9);
    for (let k = -24; k <= 24; k += 8) {
      brush.line(28 + sx * 0.5, ry + k, 58 + sx * 0.5, ry + k);
      brush.line(width - 58 + sx * 0.5, ry + k, width - 28 + sx * 0.5, ry + k);
    }
    brush.set("rotring", PALETTE.madderDeep, 0.8);
    brush.line(43 + sx * 0.5, ry - 30, 43 + sx * 0.5, ry + 30);
    brush.line(width - 43 + sx * 0.5, ry - 30, width - 43 + sx * 0.5, ry + 30);
  }
}

// =============================================================================
// LAYER 4: HYPERREAL CLAY LAMP & HAND-BLOCK STAMP RENDERING
// =============================================================================

/**
 * Renders the shifted, ghosted second impression for doubled hand-block lamps.
 */
function drawGhostBlockImpression(L) {
  const gx = L.ghostShift.x;
  const gy = L.ghostShift.y;
  const grot = L.ghostShift.rot;

  // Ghosted woodblock outer and inner contours in faded madder & iron-rust black
  const steps = 48;
  for (let i = 0; i < steps; i++) {
    if (random() < 0.28) continue; // Broken dry block contact
    const deg1 = map(i, 0, steps, 0, 360);
    const deg2 = map(i + 1, 0, steps, 0, 360);

    const p1 = evalLampContour(L, deg1, false, 0, gx, gy, grot);
    const p2 = evalLampContour(L, deg2, false, 0, gx, gy, grot);
    brush.set("2H", PALETTE.madderSoft, 0.85);
    brush.line(p1.x, p1.y, p2.x, p2.y);

    const q1 = evalLampContour(L, deg1, true, 0, gx + 2, gy + 2, grot);
    const q2 = evalLampContour(L, deg2, true, 0, gx + 2, gy + 2, grot);
    brush.set("2H", PALETTE.indigoSoft, 0.75);
    brush.line(q1.x, q1.y, q2.x, q2.y);
  }

  // Ghosted carved woodblock hatch ribs across the ghost rim
  brush.set("rotring", PALETTE.ironPlum, 0.55);
  for (let deg = 0; deg < 360; deg += 12) {
    if (random() < 0.4) continue;
    const pOut = evalLampContour(L, deg, false, -2, gx, gy, grot);
    const pIn = evalLampContour(L, deg, true, 2, gx, gy, grot);
    brush.line(pOut.x, pOut.y, pIn.x, pIn.y);
  }

  // Ghosted wick & soot smudge at the doubled beak
  const beak = evalLampContour(L, -90, false, -8, gx, gy, grot);
  brush.set("charcoal", PALETTE.indigoMid, 1.1);
  brush.circle(beak.x, beak.y + 4, 11, 0.3);
}

/**
 * Renders a single unglazed clay oil lamp with hyperreal detail AND block-print physics.
 */
function drawHyperrealLamp(L) {
  const S = L.strength; // 0.44..0.58 for fainter lamps, 0.88..1.0 for full lamps
  const skipProb = L.isFaint ? 0.42 : 0.05;

  // -------------------------------------------------------------------------
  // A. INDIGO SHADOW BLOCK CARVED CHISEL HATCHING (Underneath bottom-right)
  // -------------------------------------------------------------------------
  brush.set("woodblock_gouge", PALETTE.indigoDeep, 0.85 * S);
  for (let deg = -20; deg <= 165; deg += 6.5) {
    if (random() < skipProb) continue;
    const p1 = evalLampContour(L, deg, false, 1, L.indigoShift.x, L.indigoShift.y);
    const p2 = evalLampContour(
      L,
      deg,
      false,
      random(11, 18),
      L.indigoShift.x + 4,
      L.indigoShift.y + 5
    );
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // -------------------------------------------------------------------------
  // B. CONCENTRIC POTTER'S WHEEL THROWING RINGS (Basin Floor & Rim Bevel)
  // -------------------------------------------------------------------------
  // Basin concentric clay striations (interrupted where fainter block starved)
  const ringCount = 9;
  for (let rIdx = 1; rIdx <= ringCount; rIdx++) {
    const t = rIdx / ringCount;
    const segs = 28;
    for (let s = 0; s < segs; s++) {
      if (random() < skipProb * 1.15) continue;
      const deg1 = map(s, 0, segs, 0, 360);
      const deg2 = map(s + 0.8, 0, segs, 0, 360);

      // Interpolate between center and inner basin edge
      const p1 = evalLampContour(L, deg1, true, 0, L.ochreShift.x, L.ochreShift.y);
      const p2 = evalLampContour(L, deg2, true, 0, L.ochreShift.x, L.ochreShift.y);

      const x1 = lerp(L.cx + L.ochreShift.x, p1.x, t);
      const y1 = lerp(L.cy + L.ochreShift.y, p1.y, t);
      const x2 = lerp(L.cx + L.ochreShift.x, p2.x, t);
      const y2 = lerp(L.cy + L.ochreShift.y, p2.y, t);

      // Inside the ghee pool, wheel grooves look warm dark amber; outside, dry madder-ochre
      const distFromCenter = t * L.innerR;
      if (distFromCenter < L.gheeR - 2) {
        brush.set("2H", PALETTE.gheeDeep, 0.65 * S);
      } else {
        brush.set(
          s % 2 === 0 ? "2H" : "cpencil",
          s % 3 === 0 ? PALETTE.madderDeep : PALETTE.ochreDeep,
          0.75 * S
        );
      }
      brush.line(x1, y1, x2, y2);
    }
  }

  // -------------------------------------------------------------------------
  // C. THUMB-PRESSED RIM MODELING (Hyperreal 3D Scallops & Finger Ridges)
  // -------------------------------------------------------------------------
  // Rim base concentric bevel tracks
  for (const frac of [0.25, 0.52, 0.78]) {
    const segs = 40;
    for (let s = 0; s < segs; s++) {
      if (random() < skipProb) continue;
      const deg1 = map(s, 0, segs, 0, 360);
      const deg2 = map(s + 0.85, 0, segs, 0, 360);
      const out1 = evalLampContour(L, deg1, false, 0, L.ochreShift.x, L.ochreShift.y);
      const in1 = evalLampContour(L, deg1, true, 0, L.ochreShift.x, L.ochreShift.y);
      const out2 = evalLampContour(L, deg2, false, 0, L.ochreShift.x, L.ochreShift.y);
      const in2 = evalLampContour(L, deg2, true, 0, L.ochreShift.x, L.ochreShift.y);

      brush.set("2H", frac > 0.6 ? PALETTE.ochreLight : PALETTE.ochreDeep, 0.7 * S);
      brush.line(
        lerp(in1.x, out1.x, frac),
        lerp(in1.y, out1.y, frac),
        lerp(in2.x, out2.x, frac),
        lerp(in2.y, out2.y, frac)
      );
    }
  }

  // Detailed 3D shading and chalky clay highlights for each thumb-press around the rim
  for (let i = 0; i < L.thumbs.length; i++) {
    if (L.isFaint && random() < 0.3) continue;
    const th = L.thumbs[i];
    const cDeg = th.angle;
    const halfW = th.width * 0.68;

    // 1. Concave shadow crescent inside the upper-left side of each thumb dimple
    for (let a = cDeg - halfW; a <= cDeg + halfW * 0.3; a += 3.5) {
      const pIn = evalLampContour(L, a, true, 3, L.ochreShift.x, L.ochreShift.y);
      const pOut = evalLampContour(L, a, false, -4, L.ochreShift.x, L.ochreShift.y);
      const midX = lerp(pIn.x, pOut.x, 0.45);
      const midY = lerp(pIn.y, pOut.y, 0.45);
      brush.set("2B", PALETTE.indigoDeep, 0.75 * S * th.ridgeStrength);
      brush.line(pIn.x, pIn.y, midX, midY);
    }

    // 2. Curved thumbprint skin-press contour arcs inside the clay indentation
    for (let ring = 0.25; ring <= 0.8; ring += 0.25) {
      const pts = [];
      for (let a = cDeg - halfW * 0.85; a <= cDeg + halfW * 0.85; a += 4) {
        const pIn = evalLampContour(L, a, true, 2, L.ochreShift.x, L.ochreShift.y);
        const pOut = evalLampContour(L, a, false, -2, L.ochreShift.x, L.ochreShift.y);
        // Curve outward into the thumb hollow
        const curveBias = sin(map(a, cDeg - halfW, cDeg + halfW, 0, 180)) * 0.22;
        const f = constrain(ring + curveBias, 0.1, 0.92);
        pts.push([lerp(pIn.x, pOut.x, f), lerp(pIn.y, pOut.y, f), 0.8]);
      }
      if (pts.length >= 3) {
        brush.set("HB", PALETTE.madderDeep, 0.65 * S);
        brush.spline(pts, 0.4);
      }
    }

    // 3. Raised pinched clay ridge between adjacent thumb indentations (bright dry clay highlight)
    const ridgeDeg = cDeg + halfW * 1.18;
    const rIn = evalLampContour(L, ridgeDeg, true, 1, L.ochreShift.x, L.ochreShift.y);
    const rOut = evalLampContour(L, ridgeDeg, false, -1, L.ochreShift.x, L.ochreShift.y);
    brush.set("cpencil", PALETTE.ochreLight, 1.25 * S * th.ridgeStrength);
    brush.line(rIn.x, rIn.y, rOut.x, rOut.y);
    brush.set("rotring", PALETTE.specular, 0.55 * S);
    brush.line(
      lerp(rIn.x, rOut.x, 0.25),
      lerp(rIn.y, rOut.y, 0.25),
      lerp(rIn.x, rOut.x, 0.78),
      lerp(rIn.y, rOut.y, 0.78)
    );
  }

  // Deep thumb-pinch hollows flanking the top spout (-116 deg and -64 deg)
  for (const pinchAng of [-116, -64]) {
    for (let da = -10; da <= 10; da += 3.5) {
      const pIn = evalLampContour(L, pinchAng + da, true, 1, L.ochreShift.x, L.ochreShift.y);
      const pOut = evalLampContour(L, pinchAng + da, false, -1, L.ochreShift.x, L.ochreShift.y);
      brush.set("charcoal", PALETTE.indigoDeep, 0.9 * S);
      brush.line(
        lerp(pIn.x, pOut.x, 0.2),
        lerp(pIn.y, pOut.y, 0.2),
        lerp(pIn.x, pOut.x, 0.85),
        lerp(pIn.y, pOut.y, 0.85)
      );
    }
  }

  // -------------------------------------------------------------------------
  // D. MISREGISTERED MADDER-ALIZARIN & SYAHI IRON-BLACK CONTOUR LINES
  // -------------------------------------------------------------------------
  const contourSteps = 56;
  for (let i = 0; i < contourSteps; i++) {
    if (random() < skipProb) continue;
    const deg1 = map(i, 0, contourSteps, 0, 360);
    const deg2 = map(i + 1, 0, contourSteps, 0, 360);

    // Madder-alizarin red block outline (shifted by madderShift)
    const m1 = evalLampContour(L, deg1, false, -1, L.madderShift.x, L.madderShift.y);
    const m2 = evalLampContour(L, deg2, false, -1, L.madderShift.x, L.madderShift.y);
    brush.set("HB", PALETTE.madderMid, 0.95 * S);
    brush.line(m1.x, m1.y, m2.x, m2.y);

    // Syahi iron-rust black outer & inner carved woodblock keylines
    const sOut1 = evalLampContour(L, deg1, false, 0, L.syahiShift.x, L.syahiShift.y);
    const sOut2 = evalLampContour(L, deg2, false, 0, L.syahiShift.x, L.syahiShift.y);
    brush.set("rotring", PALETTE.ironBlack, 1.05 * S);
    brush.line(sOut1.x, sOut1.y, sOut2.x, sOut2.y);

    const sIn1 = evalLampContour(L, deg1, true, 0, L.syahiShift.x, L.syahiShift.y);
    const sIn2 = evalLampContour(L, deg2, true, 0, L.syahiShift.x, L.syahiShift.y);
    brush.set("rotring", PALETTE.ironPlum, 0.9 * S);
    brush.line(sIn1.x, sIn1.y, sIn2.x, sIn2.y);
  }

  // Deep cool indigo interior rim shadow along the northern/upper-left basin wall
  for (let deg = -165; deg <= -15; deg += 4) {
    if (abs(angleDiff(deg, -90)) < 14) continue; // Leave wick channel open
    if (random() < skipProb) continue;
    const pEdge = evalLampContour(L, deg, true, 0, L.syahiShift.x, L.syahiShift.y);
    const pDeep = evalLampContour(L, deg, true, -11, L.syahiShift.x, L.syahiShift.y);
    brush.set("charcoal", PALETTE.indigoDeep, 0.95 * S);
    brush.line(pEdge.x, pEdge.y, pDeep.x, pDeep.y);
  }

  // Bright chalky clay rim highlight along the lower-right inner lip
  for (let deg = 15; deg <= 155; deg += 4) {
    if (random() < skipProb) continue;
    const p1 = evalLampContour(L, deg, true, 2, L.ochreShift.x, L.ochreShift.y);
    const p2 = evalLampContour(L, deg + 4, true, 2, L.ochreShift.x, L.ochreShift.y);
    brush.set("cpencil", PALETTE.ochreLight, 1.3 * S);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // -------------------------------------------------------------------------
  // E. THE POOL OF GHEE (Clarified Butter, Capillary Seepage & Specular Glint)
  // -------------------------------------------------------------------------
  const gx = L.cx;
  const gy = L.cy + 4;
  const gr = L.gheeR * (L.isFaint ? 0.88 : 1.0);

  // 1. Dark wet oil capillary seepage border where ghee darkens the unglazed terracotta
  brush.set("2B", PALETTE.clayWet, 1.15 * S);
  brush.arc(gx, gy, gr + 4, 0, 360);
  brush.set("HB", PALETTE.madderDeep, 0.9 * S);
  brush.arc(gx, gy, gr + 1.5, 0, 360);

  // 2. Warm luminous golden-amber shading across the liquid pool
  for (let r = gr - 3; r > 6; r -= 5.5) {
    brush.set("cpencil", r > gr * 0.55 ? PALETTE.gheeGold : PALETTE.gheeLight, 0.95 * S);
    brush.arc(gx, gy, r, -30, 210);
    brush.set("2H", PALETTE.gheeDeep, 0.75 * S);
    brush.arc(gx, gy, r, 210, 330);
  }

  // 3. Capillary ghee stream drawn up into the pinched spout channel around the wick
  const spoutBaseX = gx + cos(-90 + L.rot) * (gr * 0.7);
  const spoutBaseY = gy + sin(-90 + L.rot) * (gr * 0.7);
  const spoutTip = evalLampContour(L, -90, true, -6, 0, 0);
  brush.set("cpencil", PALETTE.gheeGold, 1.4 * S);
  brush.line(spoutBaseX, spoutBaseY, spoutTip.x, spoutTip.y);

  // 4. Tiny oil bubbles along the meniscus edge
  const bubbleAngles = [-145, -132, -48, 25, 115, 160];
  for (const bAng of bubbleAngles) {
    if (random() < 0.35) continue;
    const bx = gx + cos(bAng + L.rot) * (gr - 2.5);
    const by = gy + sin(bAng + L.rot) * (gr - 2.5);
    brush.set("rotring", PALETTE.gheeDeep, 0.65 * S);
    brush.circle(bx, by, random(1.8, 3.2), 0.1);
    brush.set("rotring", PALETTE.specular, 0.75 * S);
    brush.line(bx - 0.8, by - 0.8, bx + 0.4, by - 0.4);
  }

  // 5. HYPERREAL SPECULAR LIQUID HIGHLIGHTS (Catching overhead cool skylight)
  // Primary upper-left meniscus crescent reflection
  for (let offset = -1.2; offset <= 1.2; offset += 0.6) {
    brush.set("rotring", PALETTE.specularBlue, 1.3 * S);
    brush.arc(gx, gy, gr - 3.5 + offset, 200 + L.rot, 248 + L.rot);
  }
  brush.set("pen", PALETTE.specular, 1.55 * S);
  brush.arc(gx, gy, gr - 3.5, 205 + L.rot, 243 + L.rot);

  // Detached secondary meniscus bead reflection
  brush.set("pen", PALETTE.specular, 1.45 * S);
  brush.arc(gx, gy, gr - 3.5, 254 + L.rot, 263 + L.rot);

  // Subtle counter-reflection on lower-right liquid meniscus
  brush.set("cpencil", PALETTE.gheeLight, 1.15 * S);
  brush.arc(gx, gy, gr - 2.5, 22 + L.rot, 68 + L.rot);
  brush.set("rotring", PALETTE.specular, 0.85 * S);
  brush.arc(gx, gy, gr - 2.5, 34 + L.rot, 52 + L.rot);

  // -------------------------------------------------------------------------
  // F. TWISTED COTTON WICK (BATTI) & CHARRED SOOT DEPOSIT ON THE BEAK
  // -------------------------------------------------------------------------
  const beakOuter = evalLampContour(L, -90, false, 3, L.syahiShift.x, L.syahiShift.y);
  const beakInner = evalLampContour(L, -90, true, -10, L.syahiShift.x, L.syahiShift.y);

  // 1. Velvety soot deposit fanned across the pinched clay beak
  brush.set("clay_pore", PALETTE.ironBlack, 1.15 * S);
  brush.circle(beakOuter.x, beakOuter.y + 6, 16, 0.3);

  for (let sRay = 0; sRay < 22; sRay++) {
    if (random() < skipProb * 0.7) continue;
    const rayAng = -90 + L.rot + random(-55, 55);
    const rayLen = random(6, 24);
    const sx1 = beakOuter.x + cos(rayAng) * random(1, 5);
    const sy1 = beakOuter.y + 5 + sin(rayAng) * random(1, 5);
    const sx2 = sx1 + cos(rayAng) * rayLen;
    const sy2 = sy1 + sin(rayAng) * rayLen;
    brush.set(
      sRay % 2 === 0 ? "charcoal" : "2B",
      sRay % 3 === 0 ? PALETTE.indigoDeep : PALETTE.ironBlack,
      random(0.65, 1.15) * S
    );
    brush.line(sx1, sy1, sx2, sy2);
  }

  // 2. Submerged wick tail coiled in the center of the golden ghee pool
  const wickStart = [
    gx + random(-5, 5),
    gy + random(8, 15),
    0.5
  ];
  const wickMidPool = [
    gx + cos(-90 + L.rot + 12) * (gr * 0.45),
    gy + sin(-90 + L.rot + 12) * (gr * 0.45),
    0.85
  ];
  const wickChannel = [beakInner.x, beakInner.y, 1.1];
  const wickTip = [
    beakOuter.x + cos(-90 + L.rot) * 4,
    beakOuter.y + sin(-90 + L.rot) * 4,
    0.9
  ];

  // Submerged amber-soaked cotton tail
  brush.set("HB", PALETTE.gheeDeep, 1.5 * S);
  brush.spline([wickStart, wickMidPool, wickChannel], 0.45);
  brush.set("cpencil", PALETTE.gheeLight, 1.1 * S);
  brush.spline([wickStart, wickMidPool, wickChannel], 0.45);

  // Twisted unburned oil-soaked cotton emerging up the spout channel
  brush.set("2B", PALETTE.ochreDeep, 1.6 * S);
  brush.spline([wickMidPool, wickChannel, wickTip], 0.35);
  brush.set("cpencil", PALETTE.ochreLight, 1.35 * S);
  brush.spline([wickMidPool, wickChannel], 0.35);

  // Diagonal twist fibers along the cotton wick
  for (let wf = 0; wf <= 1; wf += 0.22) {
    const wx = lerp(wickMidPool[0], wickChannel[0], wf);
    const wy = lerp(wickMidPool[1], wickChannel[1], wf);
    brush.set("rotring", PALETTE.ochreDeep, 0.65 * S);
    brush.line(wx - 2.5, wy - 1.5, wx + 2.5, wy + 1.5);
  }

  // 3. Charred iron-rust black wick tip, white ash crust & optional dying ember
  const charX = lerp(wickChannel[0], wickTip[0], 0.45);
  const charY = lerp(wickChannel[1], wickTip[1], 0.45);
  brush.set("charcoal", PALETTE.ironBlack, 1.9 * S);
  brush.line(charX, charY, wickTip[0], wickTip[1]);
  brush.set("rotring", PALETTE.ironBlack, 1.4 * S);
  brush.line(charX - 1.5, charY + 1, wickTip[0] + 1, wickTip[1] - 1);

  // Delicate grey-white ash flecks at the very tip of the charred wick
  brush.set("cpencil", PALETTE.ashGrey, 1.1 * S);
  brush.line(
    lerp(charX, wickTip[0], 0.7),
    lerp(charY, wickTip[1], 0.7),
    wickTip[0],
    wickTip[1]
  );

  // On selected lamps, a tiny dying alizarin-amber ember glint at the wick tip
  if (L.hasEmber) {
    brush.set("cpencil", PALETTE.madderMid, 1.6 * S);
    brush.circle(wickTip[0], wickTip[1], 2.5, 0.1);
    brush.set("pen", "#f29b52", 1.3 * S);
    brush.line(wickTip[0] - 1, wickTip[1], wickTip[0] + 1, wickTip[1]);
  }
}

// =============================================================================
// LAYER 5: SURFACE INCIDENTS — DABU CRACKLE, CLAY GROG SPECKLES & SOOT WISP
// =============================================================================

function drawSurfaceIncidents(lamps, trayMargin, traySize) {
  // 1. Clay grog & mineral pores across every lamp rim
  for (const L of lamps) {
    const count = L.isFaint ? 14 : 26;
    for (let i = 0; i < count; i++) {
      const deg = random(360);
      const frac = random(0.15, 0.88);
      const pIn = evalLampContour(L, deg, true, 0, L.ochreShift.x, L.ochreShift.y);
      const pOut = evalLampContour(L, deg, false, 0, L.ochreShift.x, L.ochreShift.y);
      const px = lerp(pIn.x, pOut.x, frac);
      const py = lerp(pIn.y, pOut.y, frac);

      brush.set(
        "rotring",
        i % 3 === 0 ? PALETTE.ochreLight : i % 2 === 0 ? PALETTE.ironPlum : PALETTE.madderDeep,
        random(0.5, 0.9) * L.strength
      );
      brush.line(px, py, px + random(-1.5, 1.5), py + random(-1.5, 1.5));
    }
  }

  // 2. Dabu mud-resist indigo crackle veins & block-print chatter marks across tray
  brush.field("hand");
  brush.wiggle(3);
  for (let i = 0; i < 38; i++) {
    const x = random(trayMargin + 30, width - trayMargin - 30);
    const y = random(trayMargin + 30, height - trayMargin - 30);
    if (isInsideAnyOpaqueLamp(x, y, lamps)) continue;

    brush.set("2H", i % 2 === 0 ? PALETTE.indigoMid : PALETTE.indigoDeep, random(0.45, 0.75));
    brush.flowLine(x, y, random(18, 46), random(360));
  }

  // 3. Faint cool indigo-grey smoke wisps drifting from the ember lamps
  brush.field("waves");
  for (const L of lamps) {
    if (!L.hasEmber) continue;
    const beak = evalLampContour(L, -90, false, 4, L.syahiShift.x, L.syahiShift.y);
    for (let w = 0; w < 3; w++) {
      brush.set("cpencil", w === 0 ? PALETTE.ashGrey : PALETTE.indigoPale, 0.65 - w * 0.15);
      brush.flowLine(
        beak.x + random(-3, 3),
        beak.y - 2,
        random(26, 48),
        -90 + random(-18, 18)
      );
    }
  }
  brush.noField();
}

// ============================================================================
// HYPERREAL GOND SPLIT JACKFRUIT — p5.brush (1200 x 1200 WEBGL)
// ============================================================================

const PALETTE = {
  paper: "#fdf6ec",
  // Vermilion background field + pastel coral/maroon Gond aura
  vermilionDeep: "#b82014",
  vermilionMid: "#e03524",
  vermilionBright: "#f24c38",
  vermilionPastel: "#ff9b87",
  vermilionCream: "#ffe3dc",

  // Chartreuse rind (sunlit side + soft pastel pistachio/lime highlights)
  chartreuseDeep: "#4d7c0f",
  chartreuseMid: "#84cc16",
  chartreuseBright: "#a3e635",
  chartreusePastel: "#d9f99d",
  chartreuseCream: "#f3fee0",

  // Teal transition zone between chartreuse light and cobalt shadow
  tealDeep: "#0f766e",
  tealMid: "#14b8a6",
