// Batched Gond mark renderer to preserve strict layer order while minimizing state switches
class GondLayerBatch {
  constructor() {
    this.lines = new Map();
    this.polylines = new Map();
    this.splines = new Map();
  }

  _key(brushName, color, weight) {
    const qw = Math.round(weight * 40) / 40;
    return `${brushName}|${color}|${qw}`;
  }

  addLine(x1, y1, x2, y2, color = PALETTE.inkBlack, weight = 0.45, brushName = "gond_pen") {
    const k = this._key(brushName, color, weight);
    if (!this.lines.has(k)) this.lines.set(k, { brushName, color, weight: Math.round(weight * 40) / 40, items: [] });
    this.lines.get(k).items.push([x1, y1, x2, y2]);
  }

  addDash(x, y, tx, ty, len, color = PALETTE.inkBlack, weight = 0.45, brushName = "gond_pen") {
    const hl = len * 0.5;
    this.addLine(x - tx * hl, y - ty * hl, x + tx * hl, y + ty * hl, color, weight, brushName);
  }

  addDot(x, y, r, color = PALETTE.inkBlack, brushName = "gond_pen") {
    const a = random(0, 180);
    const dx = cos(a) * r * 0.45;
    const dy = sin(a) * r * 0.45;
    this.addLine(x - dx, y - dy, x + dx, y + dy, color, r * 1.35, brushName);
  }

  addChevron(x, y, tx, ty, nx, ny, len, spread, color = PALETTE.inkBlack, weight = 0.42, brushName = "gond_pen") {
    const k = this._key(brushName, color, weight);
    if (!this.polylines.has(k)) this.polylines.set(k, { brushName, color, weight: Math.round(weight * 40) / 40, items: [] });
    const p1x = x - tx * len + nx * spread;
    const p1y = y - ty * len + ny * spread;
    const p2x = x + tx * (len * 0.35);
    const p2y = y + ty * (len * 0.35);
    const p3x = x - tx * len - nx * spread;
    const p3y = y - ty * len - ny * spread;
    this.polylines.get(k).items.push({ pts: [[p1x, p1y], [p2x, p2y], [p3x, p3y]], curvature: 0.05, closed: false });
  }

  addCrescent(x, y, tx, ty, nx, ny, radius, belly, color = PALETTE.inkBlack, weight = 0.45, brushName = "gond_pen") {
    const k = this._key(brushName, color, weight);
    if (!this.splines.has(k)) this.splines.set(k, { brushName, color, weight: Math.round(weight * 40) / 40, items: [] });
    const p1 = [x - tx * radius, y - ty * radius, 0.35];
    const p2 = [x + nx * belly, y + ny * belly, 1.35];
    const p3 = [x + tx * radius, y + ty * radius, 0.35];
    this.splines.get(k).items.push({ pts: [p1, p2, p3], curvature: 0.65 });
  }

  addPolyline(pts, color = PALETTE.inkBlack, weight = 0.5, curvature = 0.15, closed = false, brushName = "gond_pen") {
    if (!pts || pts.length < 2) return;
    const k = this._key(brushName, color, weight);
    if (!this.polylines.has(k)) this.polylines.set(k, { brushName, color, weight: Math.round(weight * 40) / 40, items: [] });
    this.polylines.get(k).items.push({ pts, curvature, closed });
  }

  addSpline(pts, color = PALETTE.inkBlack, weight = 0.5, curvature = 0.5, brushName = "gond_pen") {
    if (!pts || pts.length < 2) return;
    const k = this._key(brushName, color, weight);
    if (!this.splines.has(k)) this.splines.set(k, { brushName, color, weight: Math.round(weight * 40) / 40, items: [] });
    this.splines.get(k).items.push({ pts, curvature });
  }

  flush() {
    brush.noFill();
    brush.noWash();
    brush.noHatch();
    brush.noMass();

    for (const group of this.lines.values()) {
      brush.set(group.brushName, group.color, group.weight);
      const items = group.items;
      for (let i = 0; i < items.length; i++) {
        const seg = items[i];
        brush.line(seg[0], seg[1], seg[2], seg[3]);
      }
    }

    for (const group of this.polylines.values()) {
      brush.set(group.brushName, group.color, group.weight);
      const items = group.items;
      for (let i = 0; i < items.length; i++) {
        const poly = items[i];
        brush.beginShape(poly.curvature);
        for (let j = 0; j < poly.pts.length; j++) {
          const pt = poly.pts[j];
          if (pt.length > 2) brush.vertex(pt[0], pt[1], pt[2]);
          else brush.vertex(pt[0], pt[1]);
        }
        brush.endShape(poly.closed);
      }
    }

    for (const group of this.splines.values()) {
      brush.set(group.brushName, group.color, group.weight);
      const items = group.items;
      for (let i = 0; i < items.length; i++) {
        const sp = items[i];
        brush.spline(sp.pts, sp.curvature);
      }
    }

    this.lines.clear();
    this.polylines.clear();
    this.splines.clear();
  }
}

// Helper for flat marker wash + marker stroke + optional marker streak underpainting
function drawMarkerPolygon(pts, fillCol, opacity = 235, edgeCol = null, edgeWeight = 0.9, curvature = 0.2, streakAngle = null) {
  if (!pts || pts.length < 3) return;
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.wash(fillCol, opacity);
  brush.set("flat_marker", edgeCol || fillCol, edgeWeight);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();

  // Optional marker texture pass for rich hand-colored marker feel
  if (streakAngle !== null) {
    brush.hatchStyle("flat_marker", fillCol, edgeWeight * 0.85);
    brush.hatch(14, streakAngle, { rand: 0.04, continuous: true });
    brush.set("flat_marker", edgeCol || fillCol, edgeWeight * 0.4);
    brush.beginShape(curvature);
    for (let i = 0; i < pts.length; i++) {
      brush.vertex(pts[i][0], pts[i][1]);
    }
    brush.endShape(true);
    brush.noHatch();
  }
}

// Double Gond border with perpendicular ladder ticks or inner dots
function addGondDoubleBorder(batch, pts, closed, outerCol, innerCol, offsetDist = 4.5, tickSpacing = 7.5, style = "ticks", weight = 0.48) {
  if (pts.length < 3) return;
  const innerPts = [];
  const n = pts.length;

  // Compute centroid to orient inward normal
  let cx = 0, cy = 0;
  for (let i = 0; i < n; i++) { cx += pts[i][0]; cy += pts[i][1]; }
  cx /= n; cy /= n;

  for (let i = 0; i < n; i++) {
    const pPrev = pts[(i - 1 + n) % n];
    const pCurr = pts[i];
    const pNext = pts[(i + 1) % n];
    let tx = pNext[0] - pPrev[0];
    let ty = pNext[1] - pPrev[1];
    const mag = Math.hypot(tx, ty) || 1;
    tx /= mag; ty /= mag;
    let nx = -ty, ny = tx;
    const toCx = cx - pCurr[0], toCy = cy - pCurr[1];
    if (nx * toCx + ny * toCy < 0) { nx = -nx; ny = -ny; }
    innerPts.push([pCurr[0] + nx * offsetDist, pCurr[1] + ny * offsetDist]);
  }

  batch.addPolyline(pts, outerCol, weight, 0.22, closed);
  batch.addPolyline(innerPts, innerCol, weight * 0.82, 0.22, closed);

  // Add Gond ticks or dots between the double lines
  const limit = closed ? n : n - 1;
  let accum = 0;
  for (let i = 0; i < limit; i++) {
    const a = pts[i];
    const b = pts[(i + 1) % n];
    const ia = innerPts[i];
    const ib = innerPts[(i + 1) % n];
    const segLen = Math.hypot(b[0] - a[0], b[1] - a[1]);
    if (segLen < 0.5) continue;
    let d = tickSpacing - accum;
    while (d <= segLen) {
      const t = d / segLen;
      const ox = lerp(a[0], b[0], t);
      const oy = lerp(a[1], b[1], t);
      const ix = lerp(ia[0], ib[0], t);
      const iy = lerp(ia[1], ib[1], t);
      if (style === "ticks") {
        batch.addLine(ox, oy, ix, iy, innerCol, weight * 0.68);
      } else if (style === "dots") {
        batch.addDot((ox + ix) * 0.5, (oy + iy) * 0.5, weight * 0.85, innerCol);
      }
      d += tickSpacing;
    }
    accum = segLen - (d - tickSpacing);
  }
}

