// ============================================================================
// GEOMETRY PARAMETRICS FOR THE LOW-ANGLE MONUMENTAL JACKFRUIT
// ============================================================================

// Evaluates point on the Main Split Face perimeter for angle theta (in degrees)
// Low-angle perspective: bottom half (sin(theta) > 0) swells wide & close to viewer;
// top half (sin(theta) < 0) tapers upward toward the stem.
function getMainFacePoint(theta, scaleMul = 1.0) {
  const cx = 482;
  const cy = 538;
  const tilt = -14; // leaning monumentally from bottom-left to top-right
  const rads = theta;
  const s = sin(rads);
  const c = cos(rads);

  // Perspective foreshortening: wider lower belly, tapered upper crown, organic kidney indentation
  const lowAngleWidth = 1.0 + 0.24 * s - 0.08 * s * s;
  const kidneyIndent = c > 0 ? -18 * Math.pow(s, 2) : 14 * Math.pow(c, 2);
  const rx = (252 * lowAngleWidth + kidneyIndent + 8 * sin(rads * 3)) * scaleMul;
  const ry = (418 * (1.0 + 0.07 * s) + 6 * cos(rads * 2)) * scaleMul;

  const lx = c * rx;
  const ly = s * ry;

  const ct = cos(tilt);
  const st = sin(tilt);
  return [
    cx + lx * ct - ly * st,
    cy + lx * st + ly * ct
  ];
}

// Evaluates point on the Outer Spiny Rind silhouette of the Main Half
// Because we view from a LOW ANGLE, we see a massive foreshortened underside & left belly!
function getMainOuterRindPoint(theta, extraOut = 0) {
  const inner = getMainFacePoint(theta, 1.0);
  const cx = 482, cy = 538;
  let dx = inner[0] - cx;
  let dy = inner[1] - cy;
  const mag = Math.hypot(dx, dy) || 1;
  dx /= mag; dy /= mag;

  // Angle in screen space: left is ~180, bottom is ~90, top is ~-90, right is ~0
  // Huge rind expansion on left (120..240 deg) and bottom-left/bottom (55..120 deg)
  const leftBelly = Math.max(0, -cos(theta - 15)); // peaks around 165 deg (lower-left belly)
  const bottomUnder = Math.max(0, sin(theta - 10)); // peaks around 100 deg (bottom underside)
  const rightRim = Math.max(0, cos(theta));

  const rindThickness =
    42 +
    158 * Math.pow(leftBelly, 1.35) +
    115 * Math.pow(bottomUnder, 1.6) +
    16 * rightRim +
    extraOut;

  // Shift low-angle belly downward and leftward for weighty gravity
  const shiftX = -32 * Math.pow(leftBelly, 1.5);
  const shiftY = 44 * Math.pow(bottomUnder, 1.4);

  return [
    inner[0] + dx * rindThickness + shiftX,
    inner[1] + dy * rindThickness + shiftY
  ];
}

// ============================================================================
// 1. SATURATED VERMILION FIELD, COBALT CAST SHADOW & GOND AURA
// ============================================================================
function drawVermilionFieldAndAura() {
  const batch = new GondLayerBatch();

  // Saturated vermilion flat marker ground
  const canvasPoly = [[0, 0], [1200, 0], [1200, 1200], [0, 1200]];
  drawMarkerPolygon(canvasPoly, PALETTE.vermilionMid, 240, PALETTE.vermilionMid, 2.0, 0, -24);

  // Upper-right warm coral-vermilion glow (sunlit side of field)
  const warmZone = [[380, 0], [1200, 0], [1200, 780], [680, 520]];
  drawMarkerPolygon(warmZone, PALETTE.vermilionBright, 155, PALETTE.vermilionBright, 1.5, 0.1, 66);

  // Lower-left deeper vermilion ground plane
  const deepZone = [[0, 480], [580, 720], [1200, 960], [1200, 1200], [0, 1200]];
  drawMarkerPolygon(deepZone, PALETTE.vermilionDeep, 130, PALETTE.vermilionDeep, 1.5, 0.1, -18);

  // Dramatic Cobalt & Deep Plum Ground Cast Shadow beneath the low-angle jackfruit
  const shadowPts = [];
  for (let a = 35; a <= 215; a += 8) {
    const p = getMainOuterRindPoint(a, 18);
    shadowPts.push([
      p[0] - 48 * sin(a) - 25,
      Math.min(1192, p[1] + 55 + 38 * sin(a))
    ]);
  }
  shadowPts.push([18, 1185], [520, 1195], [1080, 1185], [1155, 1040], [920, 920]);
  drawMarkerPolygon(shadowPts, PALETTE.cobaltAbyss, 210, PALETTE.cobaltDeep, 1.2, 0.25, 12);

  // Inner cobalt shadow core
  const innerShadow = [
    [60, 1020], [280, 980], [640, 1010], [1040, 1040],
    [1090, 1150], [520, 1178], [45, 1140]
  ];
  drawMarkerPolygon(innerShadow, PALETTE.cobaltDeep, 190, PALETTE.cobaltMid, 1.0, 0.2, -15);

  // Gond herringbone & dash bands across the ground cast shadow
  for (let row = 0; row < 11; row++) {
    const yBase = 985 + row * 19;
    const xStart = 25 + row * 12;
    const xEnd = 1140 - row * 8;
    for (let x = xStart; x < xEnd; x += 14) {
      const waveY = yBase + 6 * sin(x * 0.8 + row * 25);
      const col = (row % 3 === 0) ? PALETTE.cobaltPastel : (row % 2 === 0 ? PALETTE.vermilionPastel : PALETTE.inkBlack);
      batch.addChevron(x, waveY, 1, 0, 0, 1, 5.5, 4.2, col, 0.44);
    }
  }

  // Gond Aura Ripple Rings radiating around the monumental silhouette into the vermilion field
  const numRings = 9;
  for (let r = 1; r <= numRings; r++) {
    const distOut = 14 + r * 18;
    const ringPts = [];
    for (let a = 0; a < 360; a += 4) {
      let p = getMainOuterRindPoint(a, distOut);
      // Expand aura around lower-right foreground wedge too
      if (a > 10 && a < 85) {
        const tWedge = map(a, 10, 85, 0, 180);
        const bulge = Math.max(0, sin(tWedge)) * (295 + distOut * 0.85);
        p[0] += bulge * 0.88;
        p[1] += bulge * 0.52;
      }
      ringPts.push(p);
    }

    // Draw Gond dashes, crescents, or dots along each aura contour
    const colA = (r % 3 === 1) ? PALETTE.vermilionPastel : (r % 3 === 2 ? PALETTE.vermilionDeep : PALETTE.vermilionCream);
    const colB = PALETTE.inkCrimson;

    if (r % 2 === 1) {
      batch.addPolyline(ringPts, colB, 0.36, 0.25, true);
    }

    for (let i = 0; i < ringPts.length; i++) {
      const curr = ringPts[i];
      const next = ringPts[(i + 1) % ringPts.length];
      if (curr[0] < -10 || curr[0] > 1210 || curr[1] < -10 || curr[1] > 1210) continue;

      let tx = next[0] - curr[0];
      let ty = next[1] - curr[1];
      const mag = Math.hypot(tx, ty) || 1;
      tx /= mag; ty /= mag;
      const nx = -ty, ny = tx;

      if (r % 3 === 1) {
        batch.addDash(curr[0] + nx * 4, curr[1] + ny * 4, nx, ny, 7.5, colA, 0.48);
      } else if (r % 3 === 2) {
        batch.addDot(curr[0], curr[1], 0.95, colA);
        batch.addDash(curr[0] + nx * 6, curr[1] + ny * 6, tx, ty, 6.0, colB, 0.38);
      } else {
        batch.addCrescent(curr[0], curr[1], tx, ty, nx, ny, 5.2, 3.2, colA, 0.42);
      }
    }
  }

  // Subtle decorative Gond paddy-grain clusters in the upper corners of the vermilion field
  const cornerSeeds = [
    [95, 110], [180, 70], [85, 220],
    [1070, 95], [1135, 195], [985, 70], [1120, 340], [1145, 490]
  ];
  for (let c = 0; c < cornerSeeds.length; c++) {
    const [cx, cy] = cornerSeeds[c];
    for (let ring = 1; ring <= 4; ring++) {
      const rad = ring * 16;
      const count = ring * 7;
      for (let k = 0; k < count; k++) {
        const ang = (k / count) * 360 + ring * 11;
        const px = cx + cos(ang) * rad;
        const py = cy + sin(ang) * rad;
        const tx = -sin(ang), ty = cos(ang);
        const nx = cos(ang), ny = sin(ang);
        const markCol = (ring % 2 === 0) ? PALETTE.vermilionPastel : PALETTE.vermilionDeep;
        batch.addDash(px, py, nx, ny, 6.5, markCol, 0.42);
      }
    }
  }

  batch.flush();
}

// ============================================================================
// 2. MAIN JACKFRUIT HALF — OUTER SPINY RIND (COBALT SHADOW & CHARTREUSE LIGHT)
// ============================================================================
function drawMainFruitOuterRind() {
  const batch = new GondLayerBatch();

  // Base silhouette of the entire outer rind
  const outerSil = [];
  for (let a = 0; a < 360; a += 5) {
    outerSil.push(getMainOuterRindPoint(a, 0));
  }
  drawMarkerPolygon(outerSil, PALETTE.cobaltDeep, 245, PALETTE.inkBlack, 1.1, 0.2, 42);

  // Sunlit Chartreuse Rind Zone (top crown, right flank, and upper-left shoulder)
  const sunlitRind = [];
  for (let a = -125; a <= 70; a += 5) {
    sunlitRind.push(getMainOuterRindPoint((a + 360) % 360, 0));
  }
  for (let a = 70; a >= -125; a -= 8) {
    sunlitRind.push(getMainFacePoint((a + 360) % 360, 0.92));
  }
  drawMarkerPolygon(sunlitRind, PALETTE.chartreuseMid, 240, PALETTE.chartreuseDeep, 1.0, 0.2, -32);

  // Teal-Emerald Transition Zone (between sunlit chartreuse and deep cobalt shadow belly)
  const tealZoneTop = [];
  for (let a = 195; a <= 250; a += 5) tealZoneTop.push(getMainOuterRindPoint(a, 0));
  for (let a = 250; a >= 195; a -= 5) tealZoneTop.push(getMainFacePoint(a, 0.95));
  drawMarkerPolygon(tealZoneTop, PALETTE.tealMid, 225, PALETTE.tealDeep, 0.9, 0.2, 20);

  const tealZoneBot = [];
  for (let a = 50; a <= 105; a += 5) tealZoneBot.push(getMainOuterRindPoint(a, 0));
  for (let a = 105; a >= 50; a -= 5) tealZoneBot.push(getMainFacePoint(a, 0.95));
  drawMarkerPolygon(tealZoneBot, PALETTE.tealMid, 225, PALETTE.tealDeep, 0.9, 0.2, 20);

  // Generate 3D Conical Spines (Tubercles) across the visible outer rind!
  // Arranged in phyllotactic radial & angular bands from outside in so inner spines overlap outer ones
  const spines = [];

  for (let ring = 4; ring >= 0; ring--) {
    const tRing = ring / 4; // 1 = outermost silhouette edge, 0 = near cut face rim
    const stepA = 5.5 + (1 - tRing) * 1.5;
    const offsetA = (ring % 2) * (stepA * 0.5);

    for (let a = 0; a < 360; a += stepA) {
      const theta = (a + offsetA) % 360;
      const pInner = getMainFacePoint(theta, 1.01);
      const pOuter = getMainOuterRindPoint(theta, 4);
      const bandWidth = Math.hypot(pOuter[0] - pInner[0], pOuter[1] - pInner[1]);

      // Skip inner rings where the rind rim is foreshortened and thin (e.g. right edge)
      if (bandWidth < 55 && ring > 1) continue;
      if (bandWidth < 95 && ring > 2) continue;
      if (bandWidth < 135 && ring > 3) continue;

      const u = (ring + 0.5) / (bandWidth > 135 ? 5 : bandWidth > 95 ? 4 : bandWidth > 55 ? 3 : 2);
      if (u > 1.08) continue;

      const bx = lerp(pInner[0], pOuter[0], Math.min(1.0, u));
      const by = lerp(pInner[1], pOuter[1], Math.min(1.0, u));

      // Outward radial direction for cone projection
      let rx = pOuter[0] - pInner[0];
      let ry = pOuter[1] - pInner[1];
      const rMag = Math.hypot(rx, ry) || 1;
      rx /= rMag; ry /= rMag;

      // Cone size scales with low-angle proximity (larger on lower belly, smaller near top)
      const lowAngleScale = 1.0 + 0.28 * sin(theta);
      const baseRadius = (13.5 + 5.5 * sin(theta * 3 + ring)) * lowAngleScale;
      const coneHeight = (15.0 + 9.0 * u) * lowAngleScale;

      spines.push({
        bx, by, rx, ry, theta, u, baseRadius, coneHeight
      });
    }
  }

  // Render every conical spine with flat marker facets + Gond chevron/dot rings
  for (let i = 0; i < spines.length; i++) {
    const sp = spines[i];
    drawConicalSpine(sp, batch);
  }

  batch.flush();
}

// Renders a single 3D conical jackfruit spine with marker facets and Gond contour wraps
function drawConicalSpine(sp, batch) {
  const { bx, by, rx, ry, theta, u, baseRadius, coneHeight } = sp;
  const tx = -ry, ty = rx; // tangent perpendicular to cone axis

  // Apex of the conical tubercle
  const ax = bx + rx * coneHeight;
  const ay = by + ry * coneHeight;

  // Determine color zone: Cobalt Shadow Side (theta ~ 95..225) vs Teal Transition vs Chartreuse Light
  const normTheta = ((theta % 360) + 360) % 360;
  let zone = "chartreuse";
  if (normTheta > 102 && normTheta < 212) {
    zone = "cobalt";
  } else if ((normTheta >= 72 && normTheta <= 102) || (normTheta >= 212 && normTheta <= 245)) {
    zone = "teal";
  }

  let baseCol, litCol, shadowCol, pastelCol, inkCol;
  if (zone === "cobalt") {
    baseCol = PALETTE.cobaltMid;
    litCol = PALETTE.cobaltPastel;
    shadowCol = PALETTE.cobaltAbyss;
    pastelCol = PALETTE.cobaltLavender;
    inkCol = PALETTE.inkBlack;
  } else if (zone === "teal") {
    baseCol = PALETTE.tealMid;
    litCol = PALETTE.chartreusePastel;
    shadowCol = PALETTE.cobaltDeep;
    pastelCol = PALETTE.tealPastel;
    inkCol = PALETTE.inkCobalt;
  } else {
    baseCol = PALETTE.chartreuseMid;
    litCol = PALETTE.chartreusePastel;
    shadowCol = PALETTE.chartreuseDeep;
    pastelCol = PALETTE.chartreuseCream;
    inkCol = PALETTE.inkBlack;
  }

  // Hexagonal base vertices
  const pLeft = [bx - tx * baseRadius, by - ty * baseRadius];
  const pRight = [bx + tx * baseRadius, by + ty * baseRadius];
  const pBackLeft = [bx - tx * baseRadius * 0.65 - rx * baseRadius * 0.55, by - ty * baseRadius * 0.65 - ry * baseRadius * 0.55];
  const pBackRight = [bx + tx * baseRadius * 0.65 - rx * baseRadius * 0.55, by + ty * baseRadius * 0.65 - ry * baseRadius * 0.55];
  const apex = [ax, ay];

  // Light comes from upper-right (vector ~ [0.65, -0.75])
  const dotLeft = (-tx * 0.65 + -ty * -0.75);
  const leftIsLit = dotLeft > 0;

  // Draw two 3D marker facets on the cone
  const facet1 = [pBackLeft, pLeft, apex, [bx, by]];
  const facet2 = [pBackRight, pRight, apex, [bx, by]];
  drawMarkerPolygon(facet1, leftIsLit ? litCol : shadowCol, 225, leftIsLit ? baseCol : shadowCol, 0.55, 0.12);
  drawMarkerPolygon(facet2, leftIsLit ? shadowCol : litCol, 225, leftIsLit ? shadowCol : baseCol, 0.55, 0.12);

  // Gond fine-pen contour around cone base & ridge
  batch.addPolyline([pLeft, pBackLeft, pBackRight, pRight, apex, pLeft], inkCol, 0.44, 0.15, true);
  batch.addLine(bx - rx * baseRadius * 0.45, by - ry * baseRadius * 0.45, ax, ay, inkCol, 0.36);

  // Concentric Gond chevron / scale rings wrapping around the 3D cone from base to apex
  const rings = 4;
  for (let r = 1; r <= rings; r++) {
    const f = r / (rings + 0.6); // 0 = base, 1 = apex
    const ringW = baseRadius * (1 - f * 0.82);
    const rcx = lerp(bx, ax, f);
    const rcy = lerp(by, ay, f);

    const pL = [rcx - tx * ringW, rcy - ty * ringW];
    const pM = [rcx - rx * ringW * 0.32, rcy - ry * ringW * 0.32];
    const pR = [rcx + tx * ringW, rcy + ty * ringW];

    // Dark ink Gond arc on shadow side, luminous pastel dashes/dots on lit side
    batch.addSpline([pL, pM, pR], inkCol, 0.38, 0.45);

    const numTicks = Math.max(2, Math.floor((1 - f) * 5));
    for (let k = 0; k <= numTicks; k++) {
      const kt = k / numTicks;
      const mx = lerp(pL[0], pR[0], kt);
      const my = lerp(pL[1], pR[1], kt) - ry * ringW * 0.18 * sin(kt * 180);
      const isLitTick = (leftIsLit && kt < 0.55) || (!leftIsLit && kt > 0.45);
      batch.addDash(
        mx, my, rx, ry, 3.8 * (1 - f * 0.4),
        isLitTick ? pastelCol : inkCol,
        isLitTick ? 0.42 : 0.36
      );
    }
  }

  // Bright pastel dot at the blunt apex of the spine
  batch.addDot(ax - rx * 1.8, ay - ry * 1.8, 1.1, pastelCol);
  batch.addDot(ax, ay, 0.75, inkCol);
}

