  for (let row = 0; row < 8; row++) {
    const t = (row + 0.5) / 8;
    const y = lerp(26, 112, t);
    const xL = lerp(494, 496, t) - 8 * sin(t * 180);
    const xR = lerp(546, 550, t) + 6 * sin(t * 180);
    for (let k = 0; k <= 6; k++) {
      const kt = k / 6;
      const x = lerp(xL, xR, kt);
      const col = kt < 0.45 ? PALETTE.cobaltPastel : PALETTE.chartreuseCream;
      batch.addChevron(x, y, 0, -1, 1, 0, 4.5, 3.8, col, 0.42);
      batch.addChevron(x, y + 3, 0, -1, 1, 0, 4.2, 3.5, PALETTE.inkBlack, 0.42);
    }
  }

  batch.flush();
}

// ============================================================================
// 4. MAIN SPLIT INTERIOR FACE — CUT RIND RIM & FIBROUS PERIANTH BED
// ============================================================================
function drawMainInteriorBed() {
  const batch = new GondLayerBatch();

  // Outer perimeter of the cut rind rim (Mesocarp)
  const rimOuter = [];
  const rimInner = [];
  for (let a = 0; a < 360; a += 4) {
    rimOuter.push(getMainFacePoint(a, 1.0));
    rimInner.push(getMainFacePoint(a, 0.905));
  }

  // Flat marker fill for the cut rind rim: pastel chartreuse/cream on right, soft pastel blue-cream on shadow left
  drawMarkerPolygon(rimOuter, PALETTE.chartreusePastel, 242, PALETTE.inkBlack, 1.0, 0.22, -14);

  const leftRimShadow = [];
  for (let a = 95; a <= 255; a += 5) leftRimShadow.push(getMainFacePoint(a, 1.0));
  for (let a = 255; a >= 95; a -= 5) leftRimShadow.push(getMainFacePoint(a, 0.905));
  drawMarkerPolygon(leftRimShadow, PALETTE.cobaltPastel, 195, PALETTE.cobaltMid, 0.8, 0.2);

  // Gond comb-striations and vascular dots all around the cut rind rim
  for (let a = 0; a < 360; a += 2.2) {
    const pOut = getMainFacePoint(a, 0.992);
    const pIn = getMainFacePoint(a, 0.912);
    const mx = (pOut[0] + pIn[0]) * 0.5;
    const my = (pOut[1] + pIn[1]) * 0.5;
    let dx = pIn[0] - pOut[0];
    let dy = pIn[1] - pOut[1];
    const mag = Math.hypot(dx, dy) || 1;
    dx /= mag; dy /= mag;

    const isShadowSide = (a > 100 && a < 250);
    const strokeCol = isShadowSide ? PALETTE.inkCobalt : PALETTE.inkBlack;
    const highlightCol = isShadowSide ? PALETTE.cobaltLavender : PALETTE.inkCream;

    batch.addLine(pOut[0], pOut[1], pIn[0], pIn[1], strokeCol, 0.36);
    if (Math.round(a * 10) % 44 === 0) {
      batch.addDot(mx, my, 1.15, highlightCol);
      batch.addDot(pOut[0] + dx * 5, pOut[1] + dy * 5, 0.85, PALETTE.saffronMid);
    }
  }

  addGondDoubleBorder(batch, rimOuter, true, PALETTE.inkBlack, PALETTE.chartreuseDeep, 4.2, 7.0, "ticks", 0.52);

  // Interior Cavity Bed (Perianth Fibrous Rags / "Champak" Strands)
  drawMarkerPolygon(rimInner, PALETTE.saffronDeep, 242, PALETTE.inkCrimson, 1.0, 0.22, 76);

  // Deep cobalt-plum recess on the shadow side of the interior cavity
  const leftCavityShadow = [];
  for (let a = 105; a <= 245; a += 6) leftCavityShadow.push(getMainFacePoint(a, 0.905));
  leftCavityShadow.push([450, 320], [490, 560], [520, 820]);
  drawMarkerPolygon(leftCavityShadow, PALETTE.cobaltDeep, 165, PALETTE.cobaltAbyss, 0.8, 0.2);

  addGondDoubleBorder(batch, rimInner, true, PALETTE.inkBlack, PALETTE.saffronBright, 4.0, 6.5, "dots", 0.48);

  // Radiating Fibrous Perianth Ribbons (unfertilized floral straps between core and rim)
  for (let a = 0; a < 360; a += 5.5) {
    const pCore = getMainFacePoint(a, 0.16);
    const pRim = getMainFacePoint(a, 0.89);
    const ribbonPts = [];
    const steps = 10;
    const wavePhase = a * 4;
    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      const bx = lerp(pCore[0], pRim[0], t);
      const by = lerp(pCore[1], pRim[1], t);
      const perpX = -(pRim[1] - pCore[1]) * 0.04;
      const perpY = (pRim[0] - pCore[0]) * 0.04;
      const wave = sin(t * 360 + wavePhase) * (1 - Math.abs(t - 0.5));
      ribbonPts.push([bx + perpX * wave, by + perpY * wave]);
    }

    const isLeft = (a > 100 && a < 255);
    const ribCol = (Math.round(a) % 11 === 0)
      ? PALETTE.saffronPeach
      : (isLeft ? PALETTE.cobaltPastel : PALETTE.saffronBright);

    batch.addPolyline(ribbonPts, ribCol, 0.62, 0.3, false);
    batch.addPolyline(ribbonPts, PALETTE.inkCrimson, 0.34, 0.3, false);

    // Cross-rungs along each perianth fiber
    for (let s = 1; s < steps; s++) {
      const pt = ribbonPts[s];
      const next = ribbonPts[s + 1];
      let tx = next[0] - pt[0], ty = next[1] - pt[1];
      const m = Math.hypot(tx, ty) || 1;
      tx /= m; ty /= m;
      batch.addDash(pt[0], pt[1], -ty, tx, 5.2, PALETTE.saffronButter, 0.38);
    }
  }

  batch.flush();
}

// ============================================================================
// 5. CENTRAL PITHY CORE (RACHIS)
// ============================================================================
function drawCentralCore() {
  const batch = new GondLayerBatch();

  // Swollen club-shaped central core running along the tilted axis of the split jackfruit
  const corePts = [];
  const leftEdge = [];
  const rightEdge = [];
  const steps = 28;

  for (let i = 0; i <= steps; i++) {
    const t = i / steps; // 0 = top under stem, 1 = lower core tip
    const cx = lerp(522, 468, t) + 12 * sin(t * 180);
    const cy = lerp(136, 865, t);
    // Core swells in the middle-lower section (club-like) and tapers at bottom
    const halfW = (24 + 34 * Math.pow(sin(t * 165), 0.85)) * (1 - 0.55 * Math.pow(Math.max(0, t - 0.72) / 0.28, 2));
    const scallop = 2.8 * sin(t * 180 * 9);
    leftEdge.push([cx - halfW - scallop, cy]);
    rightEdge.push([cx + halfW + scallop, cy]);
  }

  for (let i = 0; i <= steps; i++) corePts.push(leftEdge[i]);
  for (let i = steps; i >= 0; i--) corePts.push(rightEdge[i]);

  // Flat marker base: soft pastel cream & warm biscuit, with cool pastel lavender shadow edge
  drawMarkerPolygon(corePts, PALETTE.coreCream, 245, PALETTE.saffronMid, 0.9, 0.2, -14);

  // Left shadow strip on cylindrical core
  const coreShadowPoly = [];
  for (let i = 0; i <= steps; i++) coreShadowPoly.push(leftEdge[i]);
  for (let i = steps; i >= 0; i--) {
    coreShadowPoly.push([
      lerp(leftEdge[i][0], rightEdge[i][0], 0.36),
      leftEdge[i][1]
    ]);
  }
  drawMarkerPolygon(coreShadowPoly, PALETTE.coreShadow, 185, PALETTE.cobaltPastel, 0.6, 0.2);

  // Warm saffron-butter center-right strip on core
  const coreWarmPoly = [];
  for (let i = 0; i <= steps; i++) {
    coreWarmPoly.push([lerp(leftEdge[i][0], rightEdge[i][0], 0.34), leftEdge[i][1]]);
  }
  for (let i = steps; i >= 0; i--) coreWarmPoly.push(rightEdge[i]);
  drawMarkerPolygon(coreWarmPoly, PALETTE.coreWarm, 150, PALETTE.saffronPastel, 0.6, 0.2);

  // Gond cylindrical cross-contour dot-And-dash rings modeling the 3D volume of the core
  for (let i = 1; i < steps; i++) {
    const t = i / steps;
    const pL = leftEdge[i];
    const pR = rightEdge[i];
    const w = Math.hypot(pR[0] - pL[0], pR[1] - pL[1]);
    const numMarks = Math.max(4, Math.floor(w / 6.5));

    for (let k = 0; k <= numMarks; k++) {
      const u = k / numMarks; // 0 = left shadow, 1 = right highlight
      const mx = lerp(pL[0], pR[0], u);
      const my = lerp(pL[1], pR[1], u) + 9 * sin(u * 180); // 3D cylindrical bow downward toward low-angle viewer

      if (u < 0.35) {
        batch.addDash(mx, my, 1, 0.2, 4.6, PALETTE.inkCobalt, 0.44);
      } else if (u < 0.72) {
        batch.addDot(mx, my, 0.9, PALETTE.saffronDeep);
        batch.addDash(mx, my + 2.5, 0.2, 1, 3.8, PALETTE.inkBlack, 0.35);
      } else {
        batch.addDot(mx, my, 1.05, PALETTE.inkCream);
        batch.addDot(mx + 2, my, 0.7, PALETTE.inkBlack);
      }
    }
  }

  addGondDoubleBorder(batch, corePts, true, PALETTE.inkBlack, PALETTE.saffronDeep, 4.2, 6.0, "ticks", 0.5);
  batch.flush();
}

