// Renders a single 3D plump golden jackfruit bulb (aril) with flat marker layers
// and curvature-following Gond crescents, dashes, chevrons, or sliced seed interior
function drawSingleJackfruitBulb(bulb, batch) {
  const { cx, cy, rx, ry, rot, style, cut, shadowBias = 0, lobes = 2 } = bulb;
  const ct = cos(rot);
  const st = sin(rot);

  // Parametric local-to-world transform for a plump tear-drop / kidney pod
  // u in [-1, 1] across width, v in [-1, 1] from base (near core, v=-1) to plump outer tip (v=1)
  function evalPodPoint(u, v) {
    // Plump tip at v > 0, tapered base at v < 0
    const plumpProfile = Math.sqrt(Math.max(0.01, 1 - v * v)) * (1.0 + 0.24 * v - 0.08 * v * v);
    const kidneyBend = 0.14 * rx * (1 - v * v);
    const lobeIndent = (Math.abs(u) < 0.85) ? 0.04 * Math.cos(u * 180 * lobes) : 0;
    const lx = u * rx * (plumpProfile + lobeIndent) + kidneyBend;
    const ly = v * ry;
    return [
      cx + lx * ct - ly * st,
      cy + lx * st + ly * ct
    ];
  }

  // Outer contour polygon
  const outlinePts = [];
  const numSteps = 32;
  for (let i = 0; i < numSteps; i++) {
    const a = (i / numSteps) * 360;
    const u = cos(a);
    const v = sin(a);
    outlinePts.push(evalPodPoint(u, v));
  }

  // 1. Deep Saffron-Amber Shadow Under-Layer (crevice ambient occlusion)
  const baseShadowCol = shadowBias > 0.3 ? PALETTE.saffronShadow : PALETTE.saffronDeep;
  drawMarkerPolygon(outlinePts, baseShadowCol, 242, PALETTE.inkCrimson, 1.0, 0.22, rot + 90);

  // If on the cobalt shadow side, add a subtle cobalt-indigo rim reflection on the shadow edge
  if (shadowBias > 0.25) {
    const rimShadowPts = [];
    for (let v = -0.85; v <= 0.85; v += 0.15) rimShadowPts.push(evalPodPoint(-0.98, v));
    for (let v = 0.85; v >= -0.85; v -= 0.15) rimShadowPts.push(evalPodPoint(-0.55, v));
    drawMarkerPolygon(rimShadowPts, PALETTE.cobaltDeep, 130, PALETTE.cobaltMid, 0.5, 0.2);
  }

  // 2. Main Vivid Saffron-Gold Marker Body
  const mainBodyPts = [];
  for (let i = 0; i < numSteps; i++) {
    const a = (i / numSteps) * 360;
    const u = cos(a) * 0.90 + 0.05;
    const v = sin(a) * 0.92;
    mainBodyPts.push(evalPodPoint(u, v));
  }
  drawMarkerPolygon(mainBodyPts, PALETTE.saffronMid, 238, PALETTE.saffronDeep, 0.8, 0.22, rot);

  // 3. Upper Lit Dome — Bright Saffron & Soft Pastel Apricot/Butter
  const domePts = [];
  for (let i = 0; i < 24; i++) {
    const a = (i / 24) * 360;
    const u = cos(a) * 0.66 + 0.14;
    const v = sin(a) * 0.78 + 0.05;
    domePts.push(evalPodPoint(u, v));
  }
  drawMarkerPolygon(domePts, PALETTE.saffronBright, 230, PALETTE.saffronMid, 0.65, 0.25);

  const pastelCrownPts = [];
  for (let i = 0; i < 20; i++) {
    const a = (i / 20) * 360;
    const u = cos(a) * 0.42 + 0.22;
    const v = sin(a) * 0.62 + 0.08;
    pastelCrownPts.push(evalPodPoint(u, v));
  }
  drawMarkerPolygon(pastelCrownPts, PALETTE.saffronPastel, 225, PALETTE.saffronButter, 0.55, 0.25);

  // 4. High-Gloss Specular Strip (Flat Pastel Butter-Cream Crescent)
  if (!cut) {
    const specPts = [];
    for (let v = -0.52; v <= 0.65; v += 0.12) specPts.push(evalPodPoint(0.18, v));
    for (let v = 0.65; v >= -0.52; v -= 0.12) specPts.push(evalPodPoint(0.46, v));
    drawMarkerPolygon(specPts, PALETTE.saffronButter, 235, PALETTE.inkCream, 0.45, 0.3);
  }

  // 5. Curvature-Following Gond Mark Field (3D Normal & Specular Lighting Model)
  // Light direction in screen space: from upper-right-front [0.52, -0.58, 0.63]
  const lxDir = 0.52, lyDir = -0.58, lzDir = 0.63;

  const vRows = 17;
  const uCols = 11;

  for (let iv = 1; iv < vRows; iv++) {
    const v = map(iv, 0, vRows, -0.88, 0.88);
    for (let iu = 1; iu < uCols; iu++) {
      const u = map(iu, 0, uCols, -0.86, 0.86);

      // Skip interior if this pod is sliced open to show the seed
      if (cut && Math.hypot(u * 1.35, (v - 0.05) * 1.25) < 0.72) continue;

      // 3D height and surface normal on the plump lobed pod
      const nz = Math.sqrt(Math.max(0.05, (1 - u * u) * (1 - v * v * 0.7)));
      const lobeRipple = 0.18 * sin(u * 180 * lobes);
      const localNx = u + lobeRipple;
      const localNy = v * 0.65;
      // Rotate normal to screen space
      let wx = localNx * ct - localNy * st;
      let wy = localNx * st + localNy * ct;
      let wz = nz;
      const nMag = Math.hypot(wx, wy, wz) || 1;
      wx /= nMag; wy /= nMag; wz /= nMag;

      // Diffuse & Specular illumination
      const ndotl = Math.max(0, wx * lxDir + wy * lyDir + wz * lzDir) * (1 - shadowBias * 0.45);
      const spec = Math.pow(Math.max(0, wx * 0.32 + wy * -0.35 + wz * 0.88), 7) * (1 - shadowBias * 0.3);

      // Screen position and 3D cross-contour tangent (bowing over the plump belly toward v+1)
      const bowV = v + 0.18 * (1 - u * u) * (1 - v * v);
      const pt = evalPodPoint(u, bowV);
      const ptNextU = evalPodPoint(u + 0.06, bowV + 0.03 * (-2 * u));
      const ptNextV = evalPodPoint(u, bowV + 0.06);

      // Cross-contour tangent (across width of pod) & longitudinal tangent (along pod length)
      let ux = ptNextU[0] - pt[0], uy = ptNextU[1] - pt[1];
      const uMag = Math.hypot(ux, uy) || 1;
      ux /= uMag; uy /= uMag;

      let vx = ptNextV[0] - pt[0], vy = ptNextV[1] - pt[1];
      const vMag = Math.hypot(vx, vy) || 1;
      vx /= vMag; vy /= vMag;

      // Choose Gond mark color and weight from 3D illumination (hyperreal modelling without blending!)
      let markCol, markWeight, accentCol = null;
      if (spec > 0.48) {
        markCol = PALETTE.inkCream;
        markWeight = 0.54;
        accentCol = PALETTE.saffronButter;
      } else if (ndotl > 0.62) {
        markCol = PALETTE.saffronButter;
        markWeight = 0.46;
        accentCol = PALETTE.inkCrimson;
      } else if (ndotl > 0.36) {
        markCol = PALETTE.inkCrimson;
        markWeight = 0.44;
        accentCol = PALETTE.saffronPastel;
      } else {
        markCol = shadowBias > 0.3 ? PALETTE.inkCobalt : PALETTE.inkBlack;
        markWeight = 0.52;
        accentCol = PALETTE.saffronShadow;
      }

      const scaleFactor = Math.sqrt(Math.max(0.25, 1 - v * v * 0.65));

      if (style === "crescents") {
        // Curved Gond half-moon scales arching over the plump bulb belly
        batch.addCrescent(pt[0], pt[1], ux, uy, vx, vy, 4.8 * scaleFactor, 2.8 * scaleFactor, markCol, markWeight);
        if (accentCol) {
          batch.addDot(pt[0] - vx * 2.4, pt[1] - vy * 2.4, markWeight * 0.85, accentCol);
        }
      } else if (style === "dashes") {
        // Longitudinal Gond seed-dashes flowing from core attachment to plump tip
        batch.addDash(pt[0], pt[1], vx, vy, 7.2 * scaleFactor, markCol, markWeight);
        if (accentCol) {
          batch.addDash(pt[0] + ux * 3.2, pt[1] + uy * 3.2, vx, vy, 4.8 * scaleFactor, accentCol, markWeight * 0.78);
        }
      } else {
        // Gond chevron herringbone wrapping the longitudinal lobes
        batch.addChevron(pt[0], pt[1], vx, vy, ux, uy, 4.8 * scaleFactor, 3.8 * scaleFactor, markCol, markWeight);
        if (accentCol && (iu + iv) % 2 === 0) {
          batch.addDot(pt[0], pt[1], markWeight * 0.8, accentCol);
        }
      }
    }
  }

  // Longitudinal lobe crease line down the pod belly for extra botanical realism
  if (!cut && lobes >= 3) {
    const creasePts = [];
    for (let v = -0.78; v <= 0.78; v += 0.12) {
      creasePts.push(evalPodPoint(-0.12, v));
    }
    batch.addPolyline(creasePts, PALETTE.inkCrimson, 0.42, 0.25, false);
    for (let i = 1; i < creasePts.length - 1; i++) {
      batch.addDot(creasePts[i][0] + 3.2 * ct, creasePts[i][1] + 3.2 * st, 0.85, PALETTE.inkCream);
    }
  }

  // 6. If Sliced Open: Render Juicy Cut Flesh Rim, Pastel Rose Seed Coat & Glossy Chestnut Seed!
  if (cut) {
    const pocketPts = [];
    const seedPts = [];
    const seedHighlightPts = [];
    for (let i = 0; i < 24; i++) {
      const a = (i / 24) * 360;
      const cu = cos(a), cv = sin(a);
      pocketPts.push(evalPodPoint(cu * 0.56, cv * 0.58 + 0.05));
      seedPts.push(evalPodPoint(cu * 0.42, cv * 0.46 + 0.05));
    }
    for (let i = 0; i < 16; i++) {
      const a = (i / 16) * 360;
      seedHighlightPts.push(evalPodPoint(cos(a) * 0.18 + 0.10, sin(a) * 0.26 + 0.08));
    }

    // Pastel rose-blush papery seed coat (endocarp)
    drawMarkerPolygon(pocketPts, PALETTE.seedCoatRose, 240, PALETTE.seedCoatBlush, 0.65, 0.25);
    addGondDoubleBorder(batch, pocketPts, true, PALETTE.inkCrimson, PALETTE.inkCream, 3.2, 5.5, "ticks", 0.44);

    // Glossy chestnut-plum oval seed interior
    drawMarkerPolygon(seedPts, PALETTE.seedBrownDeep, 245, PALETTE.inkBlack, 0.75, 0.25);
    drawMarkerPolygon(seedHighlightPts, PALETTE.seedPastelLilac, 215, PALETTE.seedPlumMid, 0.5, 0.25);

    // Concentric Gond dot & crescent rings inside the glossy seed
    for (let ring = 1; ring <= 3; ring++) {
      const rf = ring * 0.12;
      const count = 10 + ring * 5;
      for (let k = 0; k < count; k++) {
        const ang = (k / count) * 360;
        const sp = evalPodPoint(cos(ang) * rf, sin(ang) * (rf * 1.1) + 0.05);
        const col = (ring === 1) ? PALETTE.inkCream : (ring === 2 ? PALETTE.seedPastelLilac : PALETTE.seedCoatRose);
        batch.addDot(sp[0], sp[1], 0.9, col);
      }
    }
    batch.addPolyline(seedPts, PALETTE.inkBlack, 0.55, 0.25, true);
  }

  // 7. Crisp Gond Double Contour Around the Entire Golden Pod
  addGondDoubleBorder(batch, outlinePts, true, PALETTE.inkBlack, PALETTE.saffronButter, 4.0, 7.0, "dots", 0.54);
}

// ============================================================================
// 7. FOREGROUND CLEAVED WEDGE (LOWER-RIGHT) — SPINY RIND & GOLDEN BULBS
// ============================================================================
function drawForegroundWedge() {
  const batch = new GondLayerBatch();

  // The cleaved right-hand wedge leaning open in the lower-right foreground
  // Cleft face runs from (605, 1045) up-right to (1105, 650)
  // Spiny rounded outer belly swells down to (1155, 920) and (895, 1160)
  const wedgeFaceCenter = [848, 845];
  const wedgeTilt = 36;

  function getWedgeFacePoint(theta, scaleMul = 1.0) {
    const s = sin(theta);
    const c = cos(theta);
    // D-shaped / crescent cleaved face
    const rx = 148 * scaleMul * (1.0 + 0.15 * c);
    const ry = 258 * scaleMul;
    const lx = c * rx;
    const ly = s * ry;
    const ct = cos(wedgeTilt), st = sin(wedgeTilt);
    return [
      wedgeFaceCenter[0] + lx * ct - ly * st,
      wedgeFaceCenter[1] + lx * st + ly * ct
    ];
  }

  function getWedgeOuterRindPoint(theta, extra = 0) {
    const pIn = getWedgeFacePoint(theta, 1.0);
    // Outer spiny belly bulges out toward bottom-right (theta in -75..85 deg in local space)
    const rightBulge = Math.max(0, cos(theta - 8));
    const botBulge = Math.max(0, sin(theta - 20));
    const dist = 24 + 138 * Math.pow(rightBulge, 1.25) + 65 * Math.pow(botBulge, 1.4) + extra;
    const angWorld = theta + wedgeTilt;
    return [
      pIn[0] + cos(angWorld) * dist,
      pIn[1] + sin(angWorld) * dist
    ];
  }

  // 1. Dark Cleavage Chasm Shadow between Main Half and Foreground Wedge
  const chasmPoly = [
    [520, 1040], [645, 725], [855, 515],
    [1045, 635], [840, 960], [625, 1085]
  ];
  drawMarkerPolygon(chasmPoly, PALETTE.cobaltAbyss, 235, PALETTE.inkBlack, 1.0, 0.2, -48);

  // Gond cross-hatch dashes inside the deep chasm shadow
  for (let i = 0; i < 24; i++) {
    const t = i / 23;
    const x1 = lerp(555, 845, t);
    const y1 = lerp(995, 555, t);
    for (let k = 0; k < 9; k++) {
      const s = k / 8;
      const px = x1 + s * 115;
      const py = y1 + s * 78;
      batch.addDash(px, py, 0.78, 0.62, 8.5, (k % 2 === 0) ? PALETTE.cobaltMid : PALETTE.vermilionDeep, 0.45);
    }
  }
  batch.flush();

  // 2. Foreground Wedge Outer Spiny Rind (Chartreuse upper-right turning to Cobalt lower-right belly)
  const wedgeOuterPts = [];
  for (let a = -95; a <= 105; a += 6) wedgeOuterPts.push(getWedgeOuterRindPoint(a, 0));
  for (let a = 105; a >= -95; a -= 8) wedgeOuterPts.push(getWedgeFacePoint(a, 0.95));
  drawMarkerPolygon(wedgeOuterPts, PALETTE.cobaltDeep, 242, PALETTE.inkBlack, 1.0, 0.2, 35);

  const wedgeSunlitPts = [];
  for (let a = -95; a <= 15; a += 6) wedgeSunlitPts.push(getWedgeOuterRindPoint(a, 0));
  for (let a = 15; a >= -95; a -= 6) wedgeSunlitPts.push(getWedgeFacePoint(a, 0.95));
  drawMarkerPolygon(wedgeSunlitPts, PALETTE.chartreuseMid, 238, PALETTE.chartreuseDeep, 0.9, 0.2, -25);

  // Conical spines on the Foreground Wedge underside
  const wedgeSpineBatch = new GondLayerBatch();
  for (let ring = 3; ring >= 0; ring--) {
    const stepA = 9;
    for (let a = -88; a <= 96; a += stepA) {
      const theta = a + (ring % 2) * 4.5;
      const pIn = getWedgeFacePoint(theta, 1.0);
      const pOut = getWedgeOuterRindPoint(theta, 2);
      const w = Math.hypot(pOut[0] - pIn[0], pOut[1] - pIn[1]);
      if (w < 45 && ring > 1) continue;
      if (w < 85 && ring > 2) continue;

      const u = (ring + 0.5) / 3.8;
      if (u > 1.05) continue;
      const bx = lerp(pIn[0], pOut[0], Math.min(1, u));
      const by = lerp(pIn[1], pOut[1], Math.min(1, u));
      let rx = pOut[0] - pIn[0], ry = pOut[1] - pIn[1];
      const rm = Math.hypot(rx, ry) || 1;
      rx /= rm; ry /= rm;

      // Map local theta to global color zone (upper-right = chartreuse, lower-right = teal/cobalt)
      const pseudoTheta = theta < -10 ? 10 : (theta < 28 ? 85 : 145);
      drawConicalSpine({
        bx, by, rx, ry,
        theta: pseudoTheta,
        u,
        baseRadius: 14.5,
        coneHeight: 16.5 + 7 * u
      }, wedgeSpineBatch);
    }
  }
  wedgeSpineBatch.flush();

  // 3. Foreground Wedge Cut Rind Rim & Interior Cavity Bed
  const wedgeRimOuter = [];
  const wedgeRimInner = [];
  for (let a = 0; a < 360; a += 6) {
    wedgeRimOuter.push(getWedgeFacePoint(a, 1.0));
    wedgeRimInner.push(getWedgeFacePoint(a, 0.89));
  }
  drawMarkerPolygon(wedgeRimOuter, PALETTE.chartreusePastel, 242, PALETTE.inkBlack, 0.9, 0.22);
  drawMarkerPolygon(wedgeRimInner, PALETTE.saffronDeep, 242, PALETTE.inkCrimson, 0.9, 0.22, 42);

  const rimBatch = new GondLayerBatch();
  for (let a = 0; a < 360; a += 4) {
    const pO = getWedgeFacePoint(a, 0.99);
    const pI = getWedgeFacePoint(a, 0.90);
    rimBatch.addLine(pO[0], pO[1], pI[0], pI[1], PALETTE.inkBlack, 0.36);
  }
  addGondDoubleBorder(rimBatch, wedgeRimOuter, true, PALETTE.inkBlack, PALETTE.chartreuseDeep, 3.8, 6.5, "ticks", 0.48);
  addGondDoubleBorder(rimBatch, wedgeRimInner, true, PALETTE.inkBlack, PALETTE.saffronBright, 3.6, 6.5, "dots", 0.45);
  rimBatch.flush();

  // 4. Sliced Core Strip along the inner edge of the Foreground Wedge
  const wedgeCorePts = [
    [935, 650], [965, 672], [755, 965], [722, 940]
  ];
  drawMarkerPolygon(wedgeCorePts, PALETTE.coreCream, 240, PALETTE.saffronMid, 0.8, 0.2);
  const wcBatch = new GondLayerBatch();
  addGondDoubleBorder(wcBatch, wedgeCorePts, true, PALETTE.inkBlack, PALETTE.saffronDeep, 3.5, 6.0, "ticks", 0.46);
  for (let s = 0; s < 16; s++) {
    const t = (s + 0.5) / 16;
    const cx = lerp(948, 738, t);
    const cy = lerp(662, 952, t);
    wcBatch.addDash(cx, cy, 0.8, 0.6, 8.0, PALETTE.saffronDeep, 0.42);
    wcBatch.addDot(cx - 5, cy - 4, 0.95, PALETTE.inkCream);
  }
  wcBatch.flush();

  // 5. Plump Golden Bulbs on the Foreground Wedge
  const wedgeBulbs = [
    { cx: 985, cy: 712, rx: 38, ry: 65, rot: -42, style: "crescents", cut: false, shadowBias: 0.0,  lobes: 2 },
    { cx: 882, cy: 675, rx: 36, ry: 62, rot: 118, style: "dashes",    cut: false, shadowBias: 0.08, lobes: 2 },
    { cx: 938, cy: 805, rx: 44, ry: 75, rot: -52, style: "chevrons",  cut: true,  shadowBias: 0.05, lobes: 3 },
    { cx: 818, cy: 768, rx: 42, ry: 72, rot: 125, style: "crescents", cut: false, shadowBias: 0.12, lobes: 3 },
    { cx: 878, cy: 902, rx: 45, ry: 76, rot: -62, style: "crescents", cut: false, shadowBias: 0.15, lobes: 3 },
    { cx: 752, cy: 862, rx: 42, ry: 72, rot: 132, style: "dashes",    cut: true,  shadowBias: 0.18, lobes: 2 },
    { cx: 798, cy: 982, rx: 40, ry: 68, rot: -75, style: "crescents", cut: false, shadowBias: 0.25, lobes: 2 },
    { cx: 688, cy: 955, rx: 38, ry: 64, rot: 142, style: "chevrons",  cut: false, shadowBias: 0.28, lobes: 2 }
  ];

  const wbBatch = new GondLayerBatch();
  for (let i = 0; i < wedgeBulbs.length; i++) {
    drawSingleJackfruitBulb(wedgeBulbs[i], wbBatch);
  }
  wbBatch.flush();
}

// ============================================================================
// 8. STICKY VISCOELASTIC LATEX THREADS & PEARLY SAP DROPLETS
// ============================================================================
function drawStickyLatexThreads() {
  const batch = new GondLayerBatch();

  // Anchor pairs spanning across the cleavage chasm from the Main Half to the Foreground Wedge
  const latexBridges = [
    { a: [688, 520], b: [962, 658], sag: 34, thick: 4.8, web: true },
    { a: [652, 565], b: [922, 682], sag: 42, thick: 6.2, web: true },
    { a: [668, 608], b: [895, 718], sag: 28, thick: 3.5, web: false },
    { a: [615, 642], b: [865, 745], sag: 48, thick: 7.4, web: true },
    { a: [635, 685], b: [835, 782], sag: 32, thick: 4.2, web: true },
    { a: [585, 718], b: [808, 815], sag: 45, thick: 6.5, web: true },
    { a: [602, 765], b: [778, 852], sag: 25, thick: 3.8, web: false },
    { a: [555, 798], b: [752, 888], sag: 38, thick: 5.8, web: true },
    { a: [565, 845], b: [722, 922], sag: 28, thick: 4.5, web: true },
    { a: [518, 882], b: [695, 955], sag: 35, thick: 6.0, web: true },
    { a: [502, 932], b: [668, 988], sag: 22, thick: 4.2, web: true },
    { a: [478, 968], b: [638, 1015],sag: 18, thick: 5.0, web: true }
  ];

  // 1. Secondary fine criss-crossing cobweb latex filaments in the background of the cleft
  for (let i = 0; i < latexBridges.length - 1; i++) {
    const br1 = latexBridges[i];
    const br2 = latexBridges[i + 1];

    const mid1 = [
      (br1.a[0] + br1.b[0]) * 0.5,
      (br1.a[1] + br1.b[1]) * 0.5 + br1.sag
    ];
    const mid2 = [
      (br2.a[0] + br2.b[0]) * 0.5,
      (br2.a[1] + br2.b[1]) * 0.5 + br2.sag
    ];

    // Diagonal cross-strands connecting adjacent bridges
    batch.addSpline([
      [br1.a[0], br1.a[1], 0.5],
      [(mid1[0] + mid2[0]) * 0.5, (mid1[1] + mid2[1]) * 0.5 + 10, 0.9],
      [br2.b[0], br2.b[1], 0.5]
    ], PALETTE.latexPastelBlue, 0.42, 0.55);

    batch.addSpline([
      [br2.a[0], br2.a[1], 0.5],
      [(mid1[0] + mid2[0]) * 0.5 - 8, (mid1[1] + mid2[1]) * 0.5 - 6, 0.9],
      [br1.b[0], br1.b[1], 0.5]
    ], PALETTE.inkCream, 0.48, 0.55);

    // Webbed Y-junction bridge between midpoints
    batch.addLine(mid1[0], mid1[1], mid2[0], mid2[1], PALETTE.inkCream, 0.42);
  }

  // 2. Primary Viscoelastic Latex Ribbons with Stretched Triangular Meniscus Webs
  for (let i = 0; i < latexBridges.length; i++) {
    const { a, b, sag, thick, web } = latexBridges[i];
    let dx = b[0] - a[0], dy = b[1] - a[1];
    const len = Math.hypot(dx, dy) || 1;
    const nx = -dy / len, ny = dx / len;

    // Build upper and lower catenary edges of the stretched sticky strand
    const topEdge = [];
    const botEdge = [];
    const centerSpine = [];
    const steps = 16;

    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      const catenary = 4 * t * (1 - t) * sag;
      // Viscoelastic waist: wide flared meniscus at ends (t=0, t=1), thin taut waist in center (t=0.5)
      const flare = 0.32 + 1.85 * Math.pow(Math.abs(t - 0.5) * 2, 2.4);
      const halfW = thick * flare * 0.5;

      const cx = lerp(a[0], b[0], t);
      const cy = lerp(a[1], b[1], t) + catenary;
      centerSpine.push([cx, cy]);
      topEdge.push([cx + nx * halfW, cy + ny * halfW]);
      botEdge.push([cx - nx * halfW, cy - ny * halfW]);
    }

    const strandPoly = [...topEdge, ...botEdge.reverse()];
    drawMarkerPolygon(strandPoly, PALETTE.latexWhite, 235, PALETTE.latexPastelBlue, 0.5, 0.25);

    // Bifurcated triangular meniscus roots at both ends (like stretched cheese/sap)
    if (web) {
      const rootA1 = [a[0] + nx * thick * 2.2, a[1] + ny * thick * 2.2];
      const rootA2 = [a[0] - nx * thick * 2.2, a[1] - ny * thick * 2.2];
      const neckA = centerSpine[3];
      drawMarkerPolygon([rootA1, neckA, rootA2], PALETTE.latexPastelPink, 195, PALETTE.inkCream, 0.4, 0.3);
      batch.addPolyline([rootA1, neckA, rootA2], PALETTE.inkBlack, 0.4, 0.3, false);

      const rootB1 = [b[0] + nx * thick * 2.1, b[1] + ny * thick * 2.1];
      const rootB2 = [b[0] - nx * thick * 2.1, b[1] - ny * thick * 2.1];
      const neckB = centerSpine[steps - 3];
      drawMarkerPolygon([rootB1, neckB, rootB2], PALETTE.latexPastelBlue, 195, PALETTE.inkCream, 0.4, 0.3);
      batch.addPolyline([rootB1, neckB, rootB2], PALETTE.inkBlack, 0.4, 0.3, false);
    }

    // Crisp Gond pen outlines along the taut latex strand + micro-beaded tension dots inside
    batch.addPolyline(topEdge, PALETTE.inkBlack, 0.46, 0.25, false);
    batch.addPolyline(botEdge, PALETTE.inkCobalt, 0.42, 0.25, false);
    batch.addPolyline(centerSpine, PALETTE.inkCream, 0.65, 0.25, false);

    for (let s = 1; s < steps; s++) {
      const pt = centerSpine[s];
      batch.addDot(pt[0], pt[1], 0.95, (s % 2 === 0) ? PALETTE.inkBlack : PALETTE.inkCream);

      // Glistening pearly sap droplets hanging from the taut strand
      if (s % 4 === 0) {
        const dropR = 3.2 + (i % 3) * 1.1;
        drawLatexSapDroplet(pt[0], pt[1] + dropR * 0.85, dropR, batch);
      }
    }
  }

  // 3. Oozing Milky Latex Droplets Beading Along the Cut Rind Rim & Central Core
  const cutRimDroplets = [
    [455, 138, 4.8], [585, 145, 5.2], [702, 245, 5.5], [752, 385, 4.6],
    [742, 488, 6.0], [322, 232, 5.0], [252, 395, 5.8], [225, 575, 6.2],
    [255, 755, 5.4], [342, 912, 6.0], [492, 365, 4.8], [485, 588, 5.5],
    [475, 745, 5.2], [955, 635, 5.2], [1028, 765, 5.6], [952, 955, 5.4]
  ];

  for (let i = 0; i < cutRimDroplets.length; i++) {
    const [dx, dy, dr] = cutRimDroplets[i];
    drawLatexSapDroplet(dx, dy, dr, batch);
  }

  batch.flush();
}

// Renders a single pearly, teardrop-shaped sticky latex sap bead with Gond dot-rings
function drawLatexSapDroplet(x, y, r, batch) {
  const dropPts = [];
  for (let a = 0; a < 360; a += 30) {
    const s = sin(a);
    const c = cos(a);
    // Teardrop profile: pinched at top (s = -1), round & full at bottom (s = 1)
    const pinch = s < 0 ? (1 + 0.35 * s) : 1.08;
    dropPts.push([
      x + c * r * pinch,
      y + s * r * 1.25
    ]);
  }

  drawMarkerPolygon(dropPts, PALETTE.latexWhite, 245, PALETTE.latexPastelBlue, 0.45, 0.3);

  // Dark ink contour + crescent shadow at bottom + bright cream dot at top-right
  batch.addPolyline(dropPts, PALETTE.inkBlack, 0.46, 0.3, true);
  batch.addCrescent(x, y + r * 0.45, 1, 0, 0, 1, r * 0.68, r * 0.42, PALETTE.inkCobalt, 0.42);
  batch.addDot(x + r * 0.25, y - r * 0.25, 1.15, PALETTE.inkCream);
  batch.addDot(x, y + r * 0.15, 0.72, PALETTE.inkBlack);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Custom coloured-pencil brushes for heavy burnishing, wood grain, and lifted specks
  brush.add("burnish", {
    type: "default",
    weight: 2.2,
    scatter: 0.35,
    sharpness: 0.32,
    grain: 14,
    opacity: 42,
    spacing: 0.18,
    pressure: [0.6, 1.15, 0.55],
    rotate: "natural",
    noise: 0.45
  });

  brush.add("wax_layer", {
    type: "default",
    weight: 3.4,
    scatter: 0.5,
    sharpness: 0.22,
    grain: 18,
    opacity: 28,
    spacing: 0.22,
    pressure: [0.4, 1.0, 0.4],
    rotate: "natural",
    noise: 0.35
  });

  brush.add("fine_cp", {
    type: "default",
    weight: 0.55,
    scatter: 0.08,
    sharpness: 0.78,
    grain: 22,
    opacity: 85,
    spacing: 0.12,
    pressure: [0.5, 1.1, 0.4],
    rotate: "natural",
    noise: 0.3
  });

  brush.add("needle_cp", {
    type: "default",
    weight: 0.32,
    scatter: 0.03,
    sharpness: 0.92,
    grain: 26,
    opacity: 135,
    spacing: 0.09,
    pressure: [0.7, 1.0, 0.6],
    rotate: "none",
