    opacity: 220,
    spacing: 0.08,
    pressure: [0.9, 1.2, 0.8],
    rotate: "none",
    noise: 0.1
  });
}

// Geometry helpers for the scene
const CX = 620;
const HORIZON_Y = 390;
const RIM_Y = 215;
const MENISCUS_Y = 448;
const BOWL_BOT_Y = 602;
const STEM_BOT_Y = 905;
const FOOT_Y = 938;

// Ship's varnished teak cap-rail sheer curves
function railTopY(x) {
  return 836 - 22 * sin((x / 1200) * 180);
}
function railBevelY(x) {
  return 1086 - 20 * sin((x / 1200) * 180);
}
function railBotY(x) {
  return 1146 - 18 * sin((x / 1200) * 180);
}

// Wine glass profile half-width from rim (215) to foot (938)
function bowlHalfWidth(y) {
  if (y < RIM_Y) return 108;
  if (y <= 445) {
    let t = (y - RIM_Y) / (445 - RIM_Y);
    return 108 + 56 * sin(t * 90);
  }
  if (y <= BOWL_BOT_Y) {
    let t = (y - 445) / (BOWL_BOT_Y - 445);
    return 14 + 150 * pow(cos(t * 90), 0.72);
  }
  return 14;
}

function stemHalfWidth(y) {
  if (y <= 638) {
    let t = (y - BOWL_BOT_Y) / (638 - BOWL_BOT_Y);
    return lerp(14, 9.5, sin(t * 90));
  }
  if (y <= 850) {
    let t = (y - 638) / (850 - 638);
    return 9.5 + 1.5 * t + 0.8 * sin(t * 180);
  }
  if (y <= STEM_BOT_Y) {
    let t = (y - 850) / (STEM_BOT_Y - 850);
    return 11 + 34 * pow(t, 2.1);
  }
  let t = constrain((y - STEM_BOT_Y) / (FOOT_Y - STEM_BOT_Y), 0, 1);
  return 45 + 95 * pow(t, 0.65);
}

// Perspective ellipse vertical radius based on distance from horizon
function ellipseRY(y, rx) {
  return max(2.5, rx * abs(y - HORIZON_Y) * 0.00037);
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#060911");

  brush.noField();
  brush.noClip();

  // 1. UNDERPAINTING WASHES (Heavy pigment saturation on dark toothy rag paper)
  drawUnderpainting();

  // 2. HEAVILY BURNISHED INDIGO & PAYNE'S GREY DUSK SKY
  drawBurnishedSky();

  // 3. TWILIGHT OCEAN & HORIZON GLOW
  drawBurnishedSea();

  // 4. BACKGROUND NAUTICAL RIGGING (Shroud cable & turnbuckle in dusk shadow)
  drawShipRigging();

  // 5. VARNISHED TEAK RAIL (Layered umber grain, bungs, gloss reflection & shadow)
  drawTeakRail();

  // 6. WINE GLASS FOOT & STEM (Crystal refraction & varnish caustics)
  drawGlassFootAndStem();

  // 7. WINE GLASS BOWL & OXBLOOD WINE
  drawGlassBowlAndWine();

  // 8. REFRACTED INVERTED SUN SLIVER & THE EMERALD-GREEN BEAD AT THE MENISCUS RIM
  drawRefractedSunAndEmeraldFlash();

  // 9. CRYSTAL SPECULAR HIGHLIGHTS & LIFTED WHITE VARNISH SPECKS
  drawSpecularAndLiftedHighlights();

  noLoop();
}

// ============================================================================
// 1. UNDERPAINTING BASE
// ============================================================================
function drawUnderpainting() {
  brush.noStroke();

  // Sky strata washes
  const skyBands = [
    { y: 0, h: 110, col: "#060a14", op: 240 },
    { y: 90, h: 110, col: "#0a1120", op: 220 },
    { y: 180, h: 100, col: "#101b2e", op: 210 },
    { y: 260, h: 85, col: "#17253b", op: 205 },
    { y: 325, h: 45, col: "#222c42", op: 200 },
    { y: 358, h: 35, col: "#2e283b", op: 210 }
  ];
  for (let b of skyBands) {
    brush.wash(b.col, b.op);
    brush.rect(0, b.y, 1200, b.h, "corner");
  }

  // Subtle horizon ember glow centered behind the glass bowl
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.65, 0.2);
  brush.fill("#4a272d", 95);
  brush.circle(CX - 35, HORIZON_Y - 4, 260, 0.15);
  brush.fill("#662d28", 70);
  brush.circle(CX - 55, HORIZON_Y, 135, 0.12);

  // Dark sea washes (y = 390 to 840)
  const seaBands = [
    { y: 390, h: 55, col: "#181e2e", op: 235 },
    { y: 440, h: 95, col: "#111929", op: 240 },
    { y: 530, h: 140, col: "#0c1321", op: 245 },
    { y: 660, h: 190, col: "#070d18", op: 250 }
  ];
  brush.noFill();
  for (let b of seaBands) {
    brush.wash(b.col, b.op);
    brush.rect(0, b.y, 1200, b.h, "corner");
  }

  // Teak rail base polygon wash
  brush.wash("#1c0d06", 250);
  brush.beginShape(0);
  for (let x = 0; x <= 1200; x += 60) brush.vertex(x, railTopY(x));
  for (let x = 1200; x >= 0; x -= 60) brush.vertex(x, railBotY(x));
  brush.endShape(true);

  // Deep waterway shadow below the rail bullnose
  brush.wash("#050406", 255);
  brush.beginShape(0);
  for (let x = 0; x <= 1200; x += 60) brush.vertex(x, railBotY(x) - 4);
  brush.vertex(1200, 1200);
  brush.vertex(0, 1200);
  brush.endShape(true);

  brush.noWash();
}

// ============================================================================
// 2. HEAVILY BURNISHED INDIGO & PAYNE'S GREY SKY
// ============================================================================
function drawBurnishedSky() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  const skyPalette = [
    { yMin: 0, yMax: 130, cols: ["#050912", "#080f1d", "#0c1526", "#111c30"] },
    { yMin: 100, yMax: 230, cols: ["#0b1322", "#101b2e", "#16243a", "#1c2d46"] },
    { yMin: 200, yMax: 320, cols: ["#142136", "#1b2b42", "#22344f", "#293c58"] },
    { yMin: 295, yMax: 368, cols: ["#1f2c42", "#28334a", "#303349", "#3a3144"] },
    { yMin: 350, yMax: 390, cols: ["#29273a", "#382938", "#472c36", "#25293a"] }
  ];

  // Pass 1: Dense diagonal cross-burnishing with wax_layer
  for (let band of skyPalette) {
    for (let i = 0; i < 160; i++) {
      let x = random(-40, 1240);
      let y = random(band.yMin, band.yMax);
      let len = random(90, 240);
      let ang = random(-14, 14);
      let col = random(band.cols);
      brush.set("wax_layer", col, random(0.9, 1.5));
      brush.line(
        x - (len * cos(ang)) / 2,
        y - (len * sin(ang)) / 2,
        x + (len * cos(ang)) / 2,
        y + (len * sin(ang)) / 2
      );
    }
  }

  // Pass 2: Horizon twilight warmth (bruised plum, copper-slate, Payne's grey)
  // Concentrated behind the wine glass so the real sun's dying glow sits behind the bowl
  const glowCols = ["#3d2430", "#4f2930", "#612f2e", "#73372c", "#33293a", "#262c3e"];
  for (let i = 0; i < 220; i++) {
    let spreadX = randomGaussian(CX - 40, 185);
    let y = random(335, 390);
    let distFactor = exp(-sq(spreadX - (CX - 40)) / (2 * sq(210)));
    let col = distFactor > 0.45 ? random(glowCols) : random(["#222b3d", "#2c3144", "#362b3b"]);
    let len = random(50, 150);
    brush.set("burnish", col, random(0.7, 1.25));
    brush.line(spreadX - len / 2, y + random(-3, 3), spreadX + len / 2, y + random(-3, 3));
  }

  // Pass 3: Fine coloured-pencil grain strokes across entire sky to create burnished paper tooth
  for (let y = 4; y < HORIZON_Y; y += 2.6) {
    let t = y / HORIZON_Y;
    let baseCol;
    if (t < 0.3) baseCol = random(["#070c18", "#0b1323", "#0f192d"]);
    else if (t < 0.6) baseCol = random(["#111c30", "#17253c", "#1d2e47"]);
    else if (t < 0.85) baseCol = random(["#1c2a40", "#24344d", "#2b3850", "#292f45"]);
    else baseCol = random(["#2b293c", "#372b3b", "#422c37", "#242c3e"]);

    for (let seg = 0; seg < 6; seg++) {
      let x1 = seg * 205 + random(-25, 15);
      let x2 = x1 + random(180, 250);
      brush.set("cpencil", baseCol, random(0.65, 1.1));
      brush.line(x1, y + random(-1.2, 1.2), x2, y + random(-1.2, 1.2));
    }
  }

  // Distant low stratocumulus dusk filaments in Payne's grey & indigo
  const cloudCols = ["#152033", "#1b283e", "#222e44", "#2e2838"];
  for (let i = 0; i < 95; i++) {
    let cx = random(40, 1160);
    let cy = random(245, 382);
    let w = random(80, 260);
    brush.set("burnish", random(cloudCols), random(0.6, 1.1));
    brush.spline([
      [cx - w * 0.5, cy],
      [cx, cy - random(1, 4)],
      [cx + w * 0.5, cy + random(-1, 2)]
    ], 0.3);
  }
}

// ============================================================================
// 3. TWILIGHT OCEAN & HORIZON LINE
// ============================================================================
function drawBurnishedSea() {
  // Crisp, dark Payne's grey & bruised-indigo horizon line
  for (let i = 0; i < 18; i++) {
    let x1 = random(-20, 400);
    let x2 = random(800, 1220);
    let col = random(["#0d1524", "#162133", "#23283b", "#382630"]);
    brush.set("fine_cp", col, random(0.7, 1.2));
    brush.line(x1, HORIZON_Y + random(-1, 1.5), x2, HORIZON_Y + random(-1, 1.5));
  }

  // Layered horizontal pencil burnishing for the dark twilight sea
  for (let y = HORIZON_Y + 2; y < 840; y += 2.8) {
    let t = (y - HORIZON_Y) / (840 - HORIZON_Y);
    let seaCols;
    if (t < 0.15) {
      seaCols = ["#141d2e", "#1b2538", "#24283b", "#2f2533", "#101826"];
    } else if (t < 0.45) {
      seaCols = ["#0e1726", "#142033", "#1b293e", "#151d2d", "#0a111d"];
    } else {
      seaCols = ["#060b14", "#0a1220", "#0f192a", "#131f33", "#080d17"];
    }

    let numStrokes = floor(map(t, 0, 1, 9, 6));
    for (let s = 0; s < numStrokes; s++) {
      let x = random(-30, 1150);
      let len = random(140, 320);
      let col = random(seaCols);
      // Slight warm twilight reflection directly below the glass/horizon center
      if (t < 0.28 && abs(x + len * 0.5 - (CX - 35)) < 170 && random() < 0.35) {
        col = random(["#2d2230", "#3b252e", "#252638"]);
      }
      brush.set("burnish", col, random(0.65, 1.25));
      brush.line(x, y + random(-1, 1), x + len, y + random(-1.5, 1.5));
    }
  }

  // Dark wave-trough contours and twilight swell facets in fine coloured pencil
  for (let i = 0; i < 420; i++) {
    let t = pow(random(), 1.35);
    let y = lerp(HORIZON_Y + 3, 835, t);
    let x = random(20, 1180);
    let w = lerp(28, 150, t) * random(0.6, 1.4);
    let arch = lerp(0.6, 5.5, t) * random(-1, 1);

    let darkWave = random(["#050911", "#080f1c", "#0c1526", "#121e32"]);
    brush.set("fine_cp", darkWave, random(0.6, 1.2));
    brush.spline([
      [x - w * 0.5, y],
      [x, y + arch],
      [x + w * 0.5, y - arch * 0.3]
    ], 0.35);

    // Subtle Payne's grey / slate sky glint on wave crests
    if (random() < 0.42) {
      let glintCol = t < 0.25 && abs(x - (CX - 30)) < 180
        ? random(["#3d2b35", "#4c3138", "#2d3448"])
        : random(["#1d2c42", "#263852", "#30435e"]);
      brush.set("needle_cp", glintCol, random(0.5, 0.9));
      brush.line(x - w * 0.28, y + arch * 0.5 - 1, x + w * 0.28, y + arch * 0.5 - 1);
    }
  }
}

// ============================================================================
// 4. BACKGROUND NAUTICAL RIGGING (Steel Shroud & Turnbuckle on Left)
// ============================================================================
function drawShipRigging() {
  // Taut diagonal shroud cable rising from x = 188, y = 835 to x = 82, y = 0
  let xBot = 188, yBot = railTopY(188);
  let xTop = 82, yTop = 0;
  let dx = xTop - xBot, dy = yTop - yBot;
  let len = sqrt(dx * dx + dy * dy);
  let nx = -dy / len, ny = dx / len; // normal vector

  // Shroud core in dark charcoal & Payne's grey
  for (let offset = -5; offset <= 5; offset += 0.8) {
    let col = offset < -2 ? "#070b12" : (offset > 2.5 ? "#384b63" : "#141e2e");
    brush.set("fine_cp", col, 0.9);
    brush.line(
      xBot + nx * offset, yBot + ny * offset,
      xTop + nx * offset * 0.75, yTop + ny * offset * 0.75
    );
  }

  // Helical wire-strand texture along the shroud
  for (let t = 0; t < 1; t += 0.012) {
    let px = lerp(xBot, xTop, t);
    let py = lerp(yBot, yTop, t);
    let w = lerp(5, 3.8, t);
    brush.set("needle_cp", "#05080e", 0.75);
    brush.line(px - nx * w, py - ny * w, px + nx * w, py + ny * w + 6);
    if (random() < 0.5) {
      brush.set("needle_cp", "#4f6580", 0.65);
      brush.line(px + nx * (w - 1), py + ny * (w - 1), px + nx * w, py + ny * w + 4);
    }
  }

  // Lower turnbuckle sleeve (t = 0.0 to 0.22)
  for (let t = 0.01; t < 0.20; t += 0.003) {
    let px = lerp(xBot, xTop, t);
    let py = lerp(yBot, yTop, t);
    let sleeveW = (t > 0.04 && t < 0.17) ? 9.5 : 6.5;
    let col = random(["#090e17", "#141f30", "#223247", "#2d1d18"]);
    brush.set("fine_cp", col, 0.9);
    brush.line(px - nx * sleeveW, py - ny * sleeveW, px + nx * sleeveW, py + ny * sleeveW);
    // Crisp twilight rim glint on right edge of turnbuckle
    brush.set("needle_cp", "#607894", 0.65);
    brush.line(px + nx * (sleeveW - 1.5), py + ny * (sleeveW - 1.5), px + nx * sleeveW, py + ny * sleeveW);
  }
}

// ============================================================================
// 5. VARNISHED TEAK RAIL (Layered Umber Grain, Joinery, Gloss Reflection)
// ============================================================================
function drawTeakRail() {
  const umberDark = ["#110703", "#1a0b05", "#241007", "#2e150a"];
  const umberMid = ["#3b1c0d", "#4a2411", "#592d15", "#421812"];
  const umberWarm = ["#6b3719", "#7d421e", "#8f4e24", "#5c2614"];

  // Pass 1: Heavy burnished base of raw and burnt umber following the rail sheer
  for (let yOff = 0; yOff < 252; yOff += 2.4) {
    let t = yOff / 252; // 0 = back edge, 1 = front bevel
    for (let x = -20; x < 1200; x += random(110, 210)) {
      let x2 = min(1220, x + random(130, 240));
      let xm = (x + x2) * 0.5;
      let y1 = lerp(railTopY(x), railBevelY(x), t);
      let y2 = lerp(railTopY(x2), railBevelY(x2), t);
      let ym = lerp(railTopY(xm), railBevelY(xm), t);

      // Cathedral wood grain undulation using noise
      let n = noise(xm * 0.004, yOff * 0.035);
      let col;
      if (n < 0.36) col = random(umberDark);
      else if (n < 0.68) col = random(umberMid);
      else col = random(umberWarm);

      // Darken under the wine glass foot shadow and along the front curve
      if (abs(xm - CX) < 150 && yOff > 60 && yOff < 155 && random() < 0.55) {
        col = random(umberDark);
      }

      brush.set("burnish", col, random(0.75, 1.35));
      brush.spline([[x, y1], [xm, ym + (n - 0.5) * 6], [x2, y2]], 0.3);
    }
  }

  // Pass 2: Teak heartwood cathedrals and interlocking grain rings in fine_cp
  const cathedralCenters = [
    { cx: 290, cyOff: 135, rx: 240, ry: 52 },
    { cx: 790, cyOff: 105, rx: 290, ry: 58 },
    { cx: 510, cyOff: 195, rx: 220, ry: 42 }
  ];

  for (let cat of cathedralCenters) {
    for (let ring = 0.15; ring <= 1.35; ring += 0.055) {
      let col = ring % 0.11 < 0.055 ? random(umberDark) : random(umberWarm);
      brush.set("fine_cp", col, random(0.65, 1.1));
      let pts = [];
      for (let a = -165; a <= 165; a += 18) {
        let px = cat.cx + cos(a) * cat.rx * ring + sin(a * 2) * 12;
        if (px < -10 || px > 1210) continue;
        let baseRailY = railTopY(px) + cat.cyOff;
        let py = baseRailY + sin(a) * cat.ry * ring;
        let minY = railTopY(px) + 5;
        let maxY = railBevelY(px) - 4;
        if (py > minY && py < maxY) {
          pts.push([px, py]);
        }
      }
      if (pts.length >= 3) {
        brush.spline(pts, 0.35);
      }
    }
  }

  // Pass 3: Thousands of fine silica pore lines and umber grain fibers
  for (let i = 0; i < 950; i++) {
    let x = random(0, 1180);
    let len = random(35, 145);
    let t = random(0.03, 0.97);
    let y1 = lerp(railTopY(x), railBevelY(x), t);
    let x2 = x + len;
    let y2 = lerp(railTopY(x2), railBevelY(x2), t) + random(-2.5, 2.5);

    let grainChoice = random();
    let col;
    if (grainChoice < 0.45) col = random(["#0d0502", "#160904", "#210e06"]); // dark teak pores
    else if (grainChoice < 0.80) col = random(["#3d1d0e", "#522813", "#663418"]); // mid umber
    else col = random(["#7a411e", "#8f4f25", "#4a1b14"]); // warm golden-umber & mahogany

    brush.set("fine_cp", col, random(0.5, 1.0));
    brush.line(x, y1, x2, y2);
  }

  // Plank seam line & two recessed teak fastener bungs (plugs)
  for (let x = 0; x < 1200; x += 45) {
    let x2 = x + 48;
    let y1 = railTopY(x) + 74;
    let y2 = railTopY(x2) + 74;
    brush.set("needle_cp", "#0b0402", 1.1);
    brush.line(x, y1, x2, y2);
    brush.set("needle_cp", "#633519", 0.7);
    brush.line(x, y1 + 1.8, x2, y2 + 1.8);
  }

  const bungs = [
    { x: 265, yOff: 122, rx: 20, ry: 5.8 },
    { x: 965, yOff: 122, rx: 20, ry: 5.8 }
  ];
  for (let b of bungs) {
    let by = railTopY(b.x) + b.yOff;
    let pts = [];
    for (let a = 0; a <= 360; a += 20) {
      pts.push([b.x + cos(a) * b.rx, by + sin(a) * b.ry]);
    }
    brush.set("needle_cp", "#090402", 1.1);
    brush.spline(pts, 0.4);
    for (let gx = -b.rx + 4; gx < b.rx - 4; gx += 3) {
      brush.set("fine_cp", random(["#2e150a", "#4f2713", "#693619"]), 0.7);
      brush.line(b.x + gx, by - 2, b.x + gx + 5, by + 1.5);
    }
  }

  // Front rounded bullnose face of the teak rail (railBevelY to railBotY)
  for (let yStep = 0; yStep < 60; yStep += 1.8) {
    let t = yStep / 60;
    for (let x = -10; x < 1200; x += random(90, 170)) {
      let x2 = x + random(100, 190);
      let y1 = lerp(railBevelY(x), railBotY(x), t);
      let y2 = lerp(railBevelY(x2), railBotY(x2), t);
      let col;
      if (t < 0.22) col = random(["#592e16", "#703b1c", "#38241c"]); // upper bullnose catches twilight
      else if (t < 0.65) col = random(["#1f0e06", "#2b1409", "#170a04"]);
      else col = random(["#090402", "#0f0703", "#140904"]); // deep underside turn
      brush.set("burnish", col, random(0.7, 1.2));
      brush.line(x, y1, x2, y2);
    }
  }

  // Gloss spar varnish reflection of the Payne's grey sky & wine glass
  // Cool sky sheen along the back camber of the rail and open varnish planes
  for (let i = 0; i < 240; i++) {
    let x = random(10, 1170);
    let len = random(45, 130);
    let t = pow(random(), 1.8) * 0.65; // concentrated toward back/middle of rail
    let y = lerp(railTopY(x) + 3, railBevelY(x), t);
    let col = random(["#1b2738", "#243347", "#2e3f57", "#2a2838"]);
    brush.set("wax_layer", col, random(0.45, 0.85));
    brush.line(x, y, x + len, y + random(-1, 1));
  }

  // Deep reflection of the wine glass & oxblood bowl in the glossy varnish below the foot
  for (let y = FOOT_Y + 12; y < railBotY(CX); y += 2.2) {
    let t = (y - FOOT_Y) / (railBotY(CX) - FOOT_Y);
    let halfW = lerp(45, 118, pow(t, 0.75));
    for (let s = 0; s < 5; s++) {
      let rx1 = CX + random(-halfW, halfW * 0.3);
      let rx2 = rx1 + random(25, 75);
      let col = t < 0.35
        ? random(["#0a0403", "#140705", "#1c0b09"])
        : random(["#1f0407", "#33070c", "#470a11", "#240d09"]);
      brush.set("burnish", col, random(0.7, 1.15));
      brush.line(rx1, y + random(-1, 1), min(CX + halfW, rx2), y + random(-1, 1));
    }
  }

  // Warm ruby-oxblood & amber caustic glow transmitted through the wine onto the varnished teak
  for (let i = 0; i < 110; i++) {
    let ang = random(-35, 145);
    let rad = random(15, 115);
    let cx = CX + 42 + cos(ang) * rad;
    let cy = FOOT_Y + 6 + sin(ang) * rad * 0.28;
    let col = rad < 55
      ? random(["#6e1414", "#8a1e18", "#a6301b", "#541010"])
      : random(["#3d0c0c", "#521410", "#42190e"]);
    brush.set("burnish", col, random(0.5, 0.95));
    brush.line(cx - random(8, 22), cy, cx + random(8, 22), cy + random(-1, 1));
  }
}

// ============================================================================
// 6. WINE GLASS FOOT & STEM
// ============================================================================
function drawGlassFootAndStem() {
  const footRX = 140;
  const footRY = ellipseRY(FOOT_Y, footRX); // ~28px

  // Cast shadow directly under the crystal foot rim
  for (let a = 0; a < 360; a += 3) {
    let x1 = CX + cos(a) * (footRX + 3);
    let y1 = FOOT_Y + 4 + sin(a) * (footRY + 2);
    let x2 = x1 + cos(a) * 10;
    let y2 = y1 + sin(a) * 3;
    brush.set("fine_cp", "#090402", 1.1);
    brush.line(x1, y1, x2, y2);
  }

  // Elliptical crystal base plate: concentric refraction rings of teak umber, Payne's grey, and oxblood tint
  for (let r = 0.12; r <= 1.0; r += 0.028) {
    let rx = footRX * r;
    let ry = footRY * r;
    for (let seg = 0; seg < 24; seg++) {
      let a1 = seg * 15 + random(-3, 3);
      let a2 = a1 + 16;
      let x1 = CX + cos(a1) * rx;
      let y1 = FOOT_Y + sin(a1) * ry;
      let x2 = CX + cos(a2) * rx;
      let y2 = FOOT_Y + sin(a2) * ry;

      let col;
      if (r > 0.91) {
        // Thick rolled glass rim of the foot
        col = (sin(a1) > 0.2 || cos(a1) < -0.4)
          ? random(["#526882", "#758ea8", "#9cb4cc", "#2a394d"])
          : random(["#120805", "#261510", "#3d241c", "#4f1c18"]);
      } else if (r < 0.38) {
        // Conical hub of the foot
        col = random(["#111824", "#1d2a3d", "#361816", "#54221c", "#475a70"]);
      } else {
        // Translucent crystal plate over varnished teak
        col = cos(a1 + 35) > 0.3
          ? random(["#4a1414", "#661b18", "#361910", "#293648"])
          : random(["#1a0d07", "#2b160c", "#161f2e", "#222e40"]);
      }
      brush.set("fine_cp", col, random(0.65, 1.15));
      brush.line(x1, y1, x2, y2);
    }
  }

  // Slender tall crystal stem (y = BOWL_BOT_Y to FOOT_Y)
  // Vertical light-piping reeds inside the solid crystal cylinder
  for (let y = BOWL_BOT_Y; y <= STEM_BOT_Y; y += 3.5) {
    let hw = stemHalfWidth(y);
    let yNext = min(STEM_BOT_Y, y + 18);
    let hwNext = stemHalfWidth(yNext);

    // 7 internal longitudinal optical bands across the width of the stem
    const bands = [
      { f: -0.95, col: "#090f1a", w: 1.0 },
      { f: -0.72, col: "#627b96", w: 0.85 }, // left refracted sky highlight
      { f: -0.38, col: "#141e2e", w: 1.0 },
      { f: 0.0,   col: "#470c12", w: 1.1 },  // central oxblood wine piping down the stem
      { f: 0.35,  col: "#80281d", w: 0.8 },  // warm horizon ember streak
      { f: 0.68,  col: "#0b1220", w: 1.0 },
      { f: 0.92,  col: "#485d75", w: 0.8 }   // right edge reflection
    ];

    for (let b of bands) {
      let x1 = CX + b.f * hw;
      let x2 = CX + b.f * hwNext;
      brush.set("fine_cp", b.col, b.w);
      brush.line(x1, y, x2, yNext);
    }
  }

  // Horizontal ring nodes at the top calyx junction (y = 598..632) and bottom stem flare (y = 865..910)
  const ringZones = [
    { yStart: 598, yEnd: 635, step: 2.5 },
    { yStart: 865, yEnd: 912, step: 2.8 }
  ];
  for (let z of ringZones) {
    for (let y = z.yStart; y <= z.yEnd; y += z.step) {
      let hw = stemHalfWidth(y);
      let ry = ellipseRY(y, hw);
      let col = random(["#0c1320", "#1f2e42", "#4f1016", "#6c849e", "#873222"]);
      brush.set("fine_cp", col, 0.8);
      brush.line(CX - hw * 0.9, y, CX + hw * 0.9, y + ry * 0.25);
    }
  }
}

// ============================================================================
// 7. WINE GLASS BOWL & OXBLOOD WINE
// ============================================================================
function drawGlassBowlAndWine() {
  // --- A. UPPER EMPTY CRYSTAL BOWL (y = RIM_Y to MENISCUS_Y) ---
  // Notice the horizon (y = 390) passes right behind the upper bowl, bent slightly by glass refraction!
  let refractedHorizonY = HORIZON_Y + 7;
  for (let x = CX - bowlHalfWidth(refractedHorizonY) + 4; x < CX + bowlHalfWidth(refractedHorizonY) - 4; x += 12) {
    let t = (x - CX) / bowlHalfWidth(refractedHorizonY);
    let curveY = refractedHorizonY - 6 * (1 - t * t);
    brush.set("fine_cp", random(["#121b2b", "#292334", "#47272c"]), 0.95);
    brush.line(x, curveY, x + 14, curveY + random(-1, 1));
  }

  // Subtle vertical & contour glass wall shading in the upper bowl
  for (let y = RIM_Y + 4; y < MENISCUS_Y; y += 3.2) {
    let hw = bowlHalfWidth(y);
    // Left wall internal refraction bands
    for (let k = 0; k < 5; k++) {
      let offset = lerp(2, 34, k / 4);
      let col = k === 1
        ? random(["#4d637d", "#68809c", "#394b61"])
        : random(["#0d1524", "#162336", "#222c3f"]);
      brush.set("fine_cp", col, 0.75);
      brush.line(CX - hw + offset, y, CX - bowlHalfWidth(y + 10) + offset, y + 10);
    }
    // Right wall internal refraction bands
    for (let k = 0; k < 5; k++) {
      let offset = lerp(2, 30, k / 4);
      let col = k === 1
        ? random(["#3e526b", "#59708a", "#4a2c30"])
        : random(["#0a111e", "#142033", "#1e293b"]);
      brush.set("fine_cp", col, 0.75);
      brush.line(CX + hw - offset, y, CX + bowlHalfWidth(y + 10) - offset, y + 10);
    }
  }

  // --- B. OXBLOOD WINE BODY (y = MENISCUS_Y to BOWL_BOT_Y) ---
  // Under-wash of deep oxblood-black and burgundy inside the bowl below the meniscus
  brush.noStroke();
  brush.wash("#140205", 248);
  brush.beginShape(0);
  for (let y = MENISCUS_Y; y <= BOWL_BOT_Y; y += 8) {
    brush.vertex(CX - bowlHalfWidth(y) + 3, y);
  }
  for (let y = BOWL_BOT_Y; y >= MENISCUS_Y; y -= 8) {
    brush.vertex(CX + bowlHalfWidth(y) - 3, y);
  }
  brush.endShape(true);
  brush.noWash();

  // Heavily burnished coloured-pencil layers of oxblood, claret, and abyssal burgundy
  for (let y = MENISCUS_Y + 2; y <= BOWL_BOT_Y - 3; y += 2.0) {
    let hw = bowlHalfWidth(y) - 3.5;
    let vFrac = (y - MENISCUS_Y) / (BOWL_BOT_Y - MENISCUS_Y); // 0 at top, 1 at bottom

    for (let x = CX - hw; x < CX + hw; x += random(18, 36)) {
      let x2 = min(CX + hw, x + random(22, 44));
      let xm = (x + x2) * 0.5;
      let hFrac = (xm - CX) / hw; // -1 left edge, +1 right edge

      // Determine oxblood tonal value:
      // - Deep velvety black-claret core (#0d0103, #1a0205)
      // - Glowing refracted ruby-oxblood on the left-lower curve and bottom condenser lens
      let distToSolarRefraction = dist(xm, y, CX - 68, MENISCUS_Y + 34);
      let distToBottomCaustic = dist(xm, y, CX + 18, BOWL_BOT_Y - 36);

      let col;
      if (distToSolarRefraction < 58) {
        col = distToSolarRefraction < 28
          ? random(["#7a0e16", "#99171b", "#b8241e", "#610911"])
          : random(["#3d050b", "#540810", "#6b0c14"]);
      } else if (distToBottomCaustic < 52) {
        col = distToBottomCaustic < 25
          ? random(["#6e0d15", "#8c151b", "#a6211e", "#520810"])
          : random(["#360409", "#4a070e", "#5e0a12"]);
      } else if (abs(hFrac) > 0.82) {
        // Glass wall thickness & dark meniscus rim shadow
        col = hFrac < 0
          ? random(["#240408", "#38070d", "#1f2433"])
          : random(["#170205", "#290409", "#181d2b"]);
      } else {
        col = random(["#0b0103", "#130204", "#1d0307", "#280409", "#33050b"]);
      }

      // Curved contour stroke following the 3D bowl geometry
      let dip = (1 - hFrac * hFrac) * 6 * (1 - vFrac * 0.4);
      brush.set("burnish", col, random(0.75, 1.3));
      brush.line(x, y + dip * 0.8, x2, y + dip);
    }
  }

  // Fine cross-hatched coloured pencil burnishing inside the oxblood wine for velvety depth
  for (let i = 0; i < 420; i++) {
    let y = random(MENISCUS_Y + 6, BOWL_BOT_Y - 8);
    let hw = bowlHalfWidth(y) - 6;
    if (hw < 12) continue;
    let x = CX + random(-hw, hw);
    let len = random(16, 42);
    let ang = random(-22, 22);
    let x2 = constrain(x + cos(ang) * len, CX - hw, CX + hw);
    let y2 = constrain(y + sin(ang) * len, MENISCUS_Y + 4, BOWL_BOT_Y - 5);

    let dSolar = dist(x, y, CX - 68, MENISCUS_Y + 30);
    let col = dSolar < 48
      ? random(["#590911", "#781017", "#96181c", "#b5281f"])
      : random(["#090102", "#140205", "#210307", "#30050a", "#40070e"]);
    brush.set("fine_cp", col, random(0.6, 1.05));
    brush.line(x, y, x2, y2);
  }

  // --- C. THE LIQUID MENISCUS ELLIPSE (y = MENISCUS_Y) ---
  const menRX = bowlHalfWidth(MENISCUS_Y) - 3; // ~161px
  const menRY = 12.5;

  // Fill the elliptical top surface of the oxblood wine
  for (let r = 0.08; r <= 1.0; r += 0.04) {
    let rx = menRX * r;
    let ry = menRY * r;
    for (let a = 0; a < 360; a += 12) {
      let x1 = CX + cos(a) * rx;
      let y1 = MENISCUS_Y + sin(a) * ry;
      let x2 = CX + cos(a + 14) * rx;
      let y2 = MENISCUS_Y + sin(a + 14) * ry;

      // Left-front quadrant of the meniscus catches warm sunset refraction; rest is dark mirror oxblood
      let dLeft = dist(x1, y1, CX - 95, MENISCUS_Y + 4);
      let col;
      if (dLeft < 52) {
        col = random(["#4d0810", "#6e0e16", "#8f171b", "#38050b"]);
      } else {
        col = random(["#120205", "#1c0307", "#29050a", "#1a1824", "#241e2b"]);
      }
      brush.set("fine_cp", col, random(0.7, 1.15));
      brush.line(x1, y1, x2, y2);
    }
  }

  // Crisp capillary meniscus rim (double line where wine climbs the inside of the crystal wall)
  for (let a = 0; a < 360; a += 5) {
    let x1 = CX + cos(a) * menRX;
    let y1 = MENISCUS_Y + sin(a) * menRY;
    let x2 = CX + cos(a + 6) * menRX;
    let y2 = MENISCUS_Y + sin(a + 6) * menRY;

    // Back rim arc vs front rim arc
    let isFront = sin(a) >= 0;
    let col = isFront
      ? random(["#3b070d", "#5c0c14", "#78141c", "#403242"])
      : random(["#1f0408", "#33070d", "#2c2838", "#473545"]);
    brush.set("fine_cp", col, isFront ? 1.0 : 0.75);
    brush.line(x1, y1, x2, y2);

    // Capillary upper lip 2.2px above
    brush.set("needle_cp", isFront ? "#632229" : "#382430", 0.65);
    brush.line(x1, y1 - 2.2, x2, y2 - 2.2);
  }

  // --- D. TOP RIM OF THE CRYSTAL GLASS (y = RIM_Y) ---
  const rimRX = bowlHalfWidth(RIM_Y); // 108px
  const rimRY = 8.5;
  for (let a = 0; a < 360; a += 5) {
    let x1 = CX + cos(a) * rimRX;
    let y1 = RIM_Y + sin(a) * rimRY;
    let x2 = CX + cos(a + 6) * rimRX;
    let y2 = RIM_Y + sin(a + 6) * rimRY;
    let isFront = sin(a) >= 0;
    let col = isFront
      ? random(["#4d627a", "#738ba6", "#9eb5cc", "#283648"])
      : random(["#1f2d40", "#34465c", "#526780"]);
    brush.set("fine_cp", col, isFront ? 0.95 : 0.7);
    brush.line(x1, y1, x2, y2);
  }

  // Outer left and right silhouette contours of the crystal bowl
  for (let y = RIM_Y; y < BOWL_BOT_Y; y += 4) {
    let hw1 = bowlHalfWidth(y);
    let hw2 = bowlHalfWidth(y + 5);
    // Left contour
    brush.set("fine_cp", y < MENISCUS_Y ? "#4f6580" : "#3d1822", 0.95);
    brush.line(CX - hw1, y, CX - hw2, y + 5);
    brush.set("needle_cp", "#070b14", 0.85);
    brush.line(CX - hw1 - 1.2, y, CX - hw2 - 1.2, y + 5);

    // Right contour
    brush.set("fine_cp", y < MENISCUS_Y ? "#384b63" : "#2e121a", 0.9);
    brush.line(CX + hw1, y, CX + hw2, y + 5);
    brush.set("needle_cp", "#060a12", 0.85);
    brush.line(CX + hw1 + 1.2, y, CX + hw2 + 1.2, y + 5);
  }
}

// ============================================================================
// 8. REFRACTED INVERTED SUN SLIVER & THE EMERALD-GREEN BEAD AT THE MENISCUS RIM
// ============================================================================
function drawRefractedSunAndEmeraldFlash() {
  const menRX = bowlHalfWidth(MENISCUS_Y) - 3;
  const menRY = 12.5;

  // 1. THE REFRACTED & INVERTED FINAL SLIVER OF THE SUN
  // Caught inside the bowl right along the front-left curve of the liquid meniscus
  // Spanning angles a = 128° to 166° along the meniscus ellipse, inverted (curving upward at its cusps)
  const sunCenterX = CX + cos(147) * (menRX * 0.72); // ~ 507
  const sunCenterY = MENISCUS_Y + sin(147) * menRY + 4; // ~ 458

  // Deep crimson-vermilion optical bloom around the inverted solar sliver
  brush.noStroke();
  brush.fillBleed(0.2, "out");
  brush.fillTexture(0.5, 0.2);
  brush.fill("#8c1118", 110);
  brush.circle(sunCenterX + 8, sunCenterY + 4, 42, 0.1);
  brush.fill("#c92818", 95);
  brush.circle(sunCenterX + 4, sunCenterY + 1, 24, 0.08);
  brush.noFill();

  // Layered coloured-pencil strokes building the inverted solar crescent
  // Outer vermilion-blood orange sheath
  for (let i = 0; i < 45; i++) {
    let t1 = random(-1, 1);
    let t2 = constrain(t1 + random(-0.45, 0.45), -1, 1);
    let x1 = sunCenterX + t1 * 34;
    let y1 = sunCenterY - pow(t1, 2) * 8 + random(-3.5, 4.5); // inverted arch!
    let x2 = sunCenterX + t2 * 34;
    let y2 = sunCenterY - pow(t2, 2) * 8 + random(-3.5, 4.5);
    let col = random(["#9e1616", "#c42418", "#e03c18", "#f25c19"]);
    brush.set("fine_cp", col, random(0.7, 1.15));
    brush.line(x1, y1, x2, y2);
  }

  // Intense cadmium-amber & solar gold inverted sliver core
  for (let i = 0; i < 36; i++) {
    let t1 = random(-0.88, 0.82);
    let t2 = constrain(t1 + random(-0.35, 0.35), -0.92, 0.85);
    let x1 = sunCenterX + t1 * 27;
    let y1 = sunCenterY - pow(t1, 2) * 7.5 + random(-1.6, 1.6);
    let x2 = sunCenterX + t2 * 27;
    let y2 = sunCenterY - pow(t2, 2) * 7.5 + random(-1.6, 1.6);
    let col = random(["#ff771a", "#ff9e24", "#ffc438", "#ffe066"]);
    brush.set("needle_cp", col, random(0.75, 1.15));
    brush.line(x1, y1, x2, y2);
  }

  // Razor-sharp incandescent solar filament at the heart of the inverted sliver
  brush.set("lifted_speck", "#fff4c2", 0.95);
  brush.spline([
    [sunCenterX - 18, sunCenterY - 5.2],
    [sunCenterX - 2, sunCenterY - 0.5],
    [sunCenterX + 15, sunCenterY - 3.8]
  ], 0.35);

  // Secondary inverted horizontal refraction ripples just below the solar sliver inside the wine
  for (let r = 1; r <= 5; r++) {
    let ry = sunCenterY + 5 + r * 4.2;
    let rw = 26 - r * 3.5;
    let col = r <= 2
      ? random(["#e85218", "#ff8524", "#c72818"])
      : random(["#7d1116", "#9e191a", "#5c0910"]);
    brush.set("needle_cp", col, 0.8);
    brush.line(sunCenterX - rw + r * 2, ry, sunCenterX + rw + r * 2, ry - 1.2);
  }

  // 2. THE SHARP EMERALD-GREEN BEAD AT THE RIM OF THE LIQUID
  // Positioned right where the upper-left cusp of the refracted sun meets the meniscus rim!
  // Coordinate: (x = 474, y = 450.5) right on the elliptical rim of the liquid meniscus
  const flashX = CX + cos(162) * (menRX - 4); // ~ 470
  const flashY = MENISCUS_Y + sin(162) * menRY; // ~ 451.8

  // Dark contrast cradle around the bead so the pure emerald pops with maximum optical intensity
  for (let a = 0; a < 360; a += 20) {
    let rx = flashX + cos(a) * random(10, 17);
    let ry = flashY + sin(a) * random(5, 9);
    brush.set("fine_cp", "#0d0205", 0.9);
    brush.line(rx - 4, ry, rx + 4, ry);
  }

  // Layer 1: Tight deep-viridian / emerald refraction halo in the meniscus capillary rim
  for (let i = 0; i < 32; i++) {
    let ang = random(0, 360);
    let r1 = random(2.5, 9.5);
    let r2 = random(2.5, 9.5);
    let col = random(["#003d1e", "#00592b", "#007539"]);
    brush.set("fine_cp", col, random(0.65, 1.0));
    brush.line(
      flashX + cos(ang) * r1,
      flashY + sin(ang) * r1 * 0.55,
      flashX + cos(ang + 35) * r2,
      flashY + sin(ang + 35) * r2 * 0.55
    );
  }

  // Layer 2: Pure, saturated emerald-green bead body (THE ONLY PURE GREEN IN THE ENTIRE IMAGE)
  for (let i = 0; i < 40; i++) {
    let ang = random(0, 360);
    let rx = random(0.8, 5.2);
    let ry = random(0.6, 3.2);
    let col = random(["#009e4c", "#00c45e", "#00e670", "#14ff82"]);
    brush.set("needle_cp", col, random(0.75, 1.15));
    brush.line(
      flashX - cos(ang) * rx,
      flashY - sin(ang) * ry,
      flashX + cos(ang) * rx,
      flashY + sin(ang) * ry
    );
  }

  // Layer 3: Razor-sharp meniscus flare spikes (following the meniscus tangent + tiny vertical glint)
  brush.set("lifted_speck", "#00eb72", 0.95);
  brush.line(flashX - 9.5, flashY - 2.2, flashX + 10.5, flashY + 2.4);
  brush.set("lifted_speck", "#2eff93", 0.9);
  brush.line(flashX - 6.0, flashY - 1.4, flashX + 6.5, flashY + 1.5);
  brush.set("lifted_speck", "#1aff88", 0.75);
  brush.line(flashX, flashY - 4.2, flashX, flashY + 4.2);

  // Layer 4: Incandescent white-emerald jewel core at the center of the bead
  for (let i = 0; i < 12; i++) {
    let ox = random(-1.6, 1.6);
    let oy = random(-1.1, 1.1);
    brush.set("lifted_speck", i < 6 ? "#9effc8" : "#eafff2", 1.05);
    brush.line(flashX + ox - 1.2, flashY + oy, flashX + ox + 1.2, flashY + oy);
  }

  // Tiny secondary internal glass-wall reflection of the emerald bead 6.5px to the left
  const ghostX = flashX - 7.2;
  const ghostY = flashY - 1.2;
  brush.set("needle_cp", "#006633", 0.85);
  brush.line(ghostX - 2.5, ghostY - 0.6, ghostX + 2.5, ghostY + 0.6);
  brush.set("lifted_speck", "#00cc66", 0.7);
  brush.line(ghostX - 1.2, ghostY - 0.3, ghostX + 1.2, ghostY + 0.3);
}

// ============================================================================
// 9. CRYSTAL SPECULAR HIGHLIGHTS & LIFTED WHITE VARNISH SPECKS
// ============================================================================
function drawSpecularAndLiftedHighlights() {
  // --- A. CRISP SPECULAR ARCS ON THE CRYSTAL WINE GLASS ---
  // Left meridional reflection ribbon running down the glass bowl
  let leftRibbonPts = [];
  for (let y = RIM_Y + 12; y <= BOWL_BOT_Y - 22; y += 16) {
    let hw = bowlHalfWidth(y);
    leftRibbonPts.push([CX - hw + 13, y]);
  }
  brush.set("fine_cp", "#7c96b2", 0.9);
  brush.spline(leftRibbonPts, 0.35);

  let leftInnerPts = [];
  for (let y = RIM_Y + 20; y <= MENISCUS_Y - 10; y += 14) {
    let hw = bowlHalfWidth(y);
    leftInnerPts.push([CX - hw + 16.5, y]);
  }
  brush.set("lifted_speck", "#d8e8f8", 0.85);
  brush.spline(leftInnerPts, 0.35);

  // Right meridional reflection ribbon
  let rightRibbonPts = [];
  for (let y = RIM_Y + 25; y <= BOWL_BOT_Y - 35; y += 18) {
    let hw = bowlHalfWidth(y);
    rightRibbonPts.push([CX + hw - 11, y]);
  }
  brush.set("fine_cp", "#5b738f", 0.8);
  brush.spline(rightRibbonPts, 0.35);

  // Sharp white/ice-blue glints on the top rim of the glass, stem nodes, and foot rim
  const rimRX = bowlHalfWidth(RIM_Y);
  const rimRY = 8.5;
  for (let a = 15; a <= 65; a += 4) {
    let x1 = CX + cos(a) * rimRX;
    let y1 = RIM_Y + sin(a) * rimRY;
    let x2 = CX + cos(a + 4) * rimRX;
    let y2 = RIM_Y + sin(a + 4) * rimRY;
    brush.set("lifted_speck", "#e6f0fa", 0.85);
    brush.line(x1, y1, x2, y2);
  }
  for (let a = 135; a <= 172; a += 4) {
    let x1 = CX + cos(a) * rimRX;
    let y1 = RIM_Y + sin(a) * rimRY;
    let x2 = CX + cos(a + 4) * rimRX;
    let y2 = RIM_Y + sin(a + 4) * rimRY;
    brush.set("lifted_speck", "#ffffff", 0.95);
    brush.line(x1, y1, x2, y2);
  }

  // Stem vertical specular hairline
  for (let y = BOWL_BOT_Y + 12; y < STEM_BOT_Y - 15; y += 22) {
    let hw = stemHalfWidth(y);
    brush.set("lifted_speck", "#cdddf0", 0.75);
    brush.line(CX - hw * 0.62, y, CX - stemHalfWidth(y + 16) * 0.62, y + 16);
  }

  // Foot rim specular arcs (left-front and right-back rolled crystal edge)
  const footRX = 140;
  const footRY = ellipseRY(FOOT_Y, footRX);
  for (let a = 118; a <= 168; a += 3) {
    let x1 = CX + cos(a) * footRX;
    let y1 = FOOT_Y + sin(a) * footRY;
    let x2 = CX + cos(a + 3.5) * footRX;
    let y2 = FOOT_Y + sin(a + 3.5) * footRY;
    brush.set("lifted_speck", "#e8f2fc", 0.95);
    brush.line(x1, y1, x2, y2);
  }
  for (let a = -45; a <= 22; a += 4) {
    let x1 = CX + cos(a) * footRX;
    let y1 = FOOT_Y + sin(a) * footRY;
    let x2 = CX + cos(a + 4) * footRX;
    let y2 = FOOT_Y + sin(a + 4) * footRY;
    brush.set("lifted_speck", "#bfd2e6", 0.8);
    brush.line(x1, y1, x2, y2);
  }

  // --- B. VARNISH HIGHLIGHTS LIFTED BACK AS HARD WHITE SPECKS ---
  // Clustered along the rounded front bevel of the teak rail, the back sheer edge,
  // and across the open wood-pore ripples of the glossy marine spar varnish
  const speckColors = ["#ffffff", "#f2f7ff", "#dce8f7", "#c5d6eb"];

  // 1. Front bullnose bevel ridge (where the overhead dusk sky catches the curve of the varnish)
  for (let i = 0; i < 310; i++) {
    let x = random(15, 1185);
    // Avoid placing bright white specks inside the dark cast shadow directly in front of the glass foot
    if (abs(x - CX) < 95 && random() < 0.75) continue;

    let yBase = railBevelY(x) + random(-7, 9);
    let speckLen = random(0.8, 3.2);
    let col = random(speckColors);

    // Subtle dark varnish pore rim immediately adjacent to the lifted white speck
    brush.set("needle_cp", "#0d0603", 0.8);
    brush.line(x - speckLen * 0.6, yBase + 1.2, x + speckLen * 0.6, yBase + 1.2);

    brush.set("lifted_speck", col, random(0.8, 1.25));
    brush.line(x - speckLen * 0.5, yBase, x + speckLen * 0.5, yBase + random(-0.4, 0.4));
  }

  // 2. Back sheer edge of the teak rail (catching the horizon & twilight sky reflection)
  for (let i = 0; i < 220; i++) {
    let x = random(15, 1185);
    let yBase = railTopY(x) + random(1.5, 14);
    let speckLen = random(0.7, 2.8);
    let col = random(speckColors);

    brush.set("lifted_speck", col, random(0.75, 1.15));
    brush.line(x - speckLen * 0.5, yBase, x + speckLen * 0.5, yBase);
  }

  // 3. Wood-pore specular micro-specks scattered across the glossy teak surface
  // Following the grain ridges and cathedral pores where varnish pools slightly
  for (let i = 0; i < 380; i++) {
    let x = random(20, 1180);
    let t = random(0.06, 0.94);
    let y = lerp(railTopY(x), railBevelY(x), t);

    // Fewer specks deep inside the wine glass reflection shadow
    let inGlassShadow = abs(x - CX) < 115 && y > FOOT_Y - 10;
    if (inGlassShadow && random() < 0.85) continue;

    // Cluster specks along grain lines using noise
    let n = noise(x * 0.015, y * 0.08);
    if (n > 0.46) {
      let speckLen = random(0.6, 2.4);
      let col = random() < 0.65 ? "#ffffff" : random(speckColors);
      brush.set("lifted_speck", col, random(0.7, 1.2));
      brush.line(x, y, x + speckLen, y + random(-0.3, 0.3));

      // Occasional paired micro-speck along the same wood pore
      if (random() < 0.35) {
        brush.set("lifted_speck", "#e8f1fc", random(0.6, 1.0));
        brush.line(x + speckLen + 2.2, y + 0.3, x + speckLen + 3.6, y + 0.3);
      }
    }
  }
}

// Hyperreal Anaglyph Pencil Drawing: Tall Glass of Fizzing Cola Over Ice
// Cyan & Red Pencil with Warm Near-Black Coincidence on Cool Newsprint Grey

const PALETTE = {
  paperBase: "#cfd5da",
  paperLight: "#e0e5e9",
  paperMid: "#c2c9cf",
  paperDark: "#b3bbc2",

  cyanLight: "#45adc9",
  cyanMid: "#0d84a6",
  cyanDark: "#005b75",
  cyanDeep: "#004257",

  redLight: "#dc5260",
  redMid: "#c22334",
  redDark: "#8f1220",
  redDeep: "#660a14",

  blackWarmLight: "#423638",
  blackWarmMid: "#292022",
  blackWarmDark: "#181214",
  blackWarmAbyss: "#0e0a0b"
};

// Glass geometry constants (1200x1200 canvas)
const GLASS = {
  cx: 585,
  topY: 255,
  meniscusY: 330,
  shamTopY: 925,
  baseY: 1025,
  topRX: 186,
  topRY: 42,
  meniscusRX: 178,
  meniscusRY: 40,
  shamRX: 137,
  shamRY: 32,
  baseRX: 132,
  baseRY: 31
};

// Depth (z) to horizontal offset (dx) in pixels
// z ≈ 0.08 at back of glass (nearly converges, dx ≈ 2px)
// z ≈ 1.05 at front of glass (dx ≈ 26px)
// z ≈ 1.35 at foreground lemon slice (dx ≈ 34px)
// z ≈ 1.75 at foreground straw tip (dx ≈ 44px)
function getDX(z) {
  return z * 25.0;
}

// Interpolate glass outer horizontal radius at any y
function glassRX(y) {
  if (y <= GLASS.topY) return GLASS.topRX;
  if (y <= GLASS.shamTopY) {
    let t = (y - GLASS.topY) / (GLASS.shamTopY - GLASS.topY);
    return lerp(GLASS.topRX, GLASS.shamRX, t);
  }
  let t = constrain((y - GLASS.shamTopY) / (GLASS.baseY - GLASS.shamTopY), 0, 1);
  return lerp(GLASS.shamRX, GLASS.baseRX, t);
}

// Interpolate glass vertical ellipse radius at any y
function glassRY(y) {
  if (y <= GLASS.topY) return GLASS.topRY;
  if (y <= GLASS.shamTopY) {
    let t = (y - GLASS.topY) / (GLASS.shamTopY - GLASS.topY);
    return lerp(GLASS.topRY, GLASS.shamRY, t);
  }
  let t = constrain((y - GLASS.shamTopY) / (GLASS.baseY - GLASS.shamTopY), 0, 1);
  return lerp(GLASS.shamRY, GLASS.baseRY, t);
}

// Wall thickness increases toward bottom sham
function glassWall(y) {
  let t = constrain((y - GLASS.topY) / (GLASS.shamTopY - GLASS.topY), 0, 1);
  return lerp(7, 17, t * t);
}

// Surface depth z on the cylinder at normalized horizontal coordinate u in [-1, 1]
function cylinderFrontZ(u) {
  let clamped = constrain(u, -1, 1);
  return 0.56 + 0.49 * sqrt(max(0, 1 - clamped * clamped));
}

function cylinderBackZ(u) {
  let clamped = constrain(u, -1, 1);
  return 0.56 - 0.48 * sqrt(max(0, 1 - clamped * clamped));
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4219);
  noiseSeed(4219);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.paperBase);

  // 1. Cool newsprint grey paper texture & subtle surface tone
  drawNewsprintGround();

  // 2. Tabletop horizon & refractive cast shadow with caustics
  drawCastShadowAndCaustics();

  // 3. Back rim of glass & far interior glass wall (near-zero offset convergence)
  drawBackGlassStructure();

  // 4. Cola liquid body: foundational washes + dense anaglyph pencil hatching + warm-black core
  drawColaLiquidBody();

  // 5. Fractured ice cubes (submerged & emerging at meniscus)
  drawIceCubes();

  // 6. Submerged lemon slice pressed inside front-left glass wall
  drawSubmergedLemonSlice();

  // 7. Straw: submerged refracted shaft + emerging foreground bent straw (widest offset)
  drawAnaglyphStraw();

  // 8. Carbonation bubble trails, meniscus foam collar & airborne fizz spray
  drawCarbonationAndFizz();

  // 9. Foreground lemon slice wedged on front-right rim
  drawForegroundRimLemon();

  // 10. Front glass wall, heavy crystal sham flutes, front rim & specular highlights
  drawFrontGlassAndSham();

  // 11. Hyperreal condensation beads & weeping runnels across the cold glass exterior
  drawCondensationAndRunnels();

  noLoop();
}

// ============================================================================
// 1. NEWSPRINT PAPER GROUND
// ============================================================================
function drawNewsprintGround() {
  brush.noStroke();

  // Subtle cool grey tonal mottling in paper
  brush.fill(PALETTE.paperMid, 38);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.7, 0.15);
  brush.rect(60, 60, 1080, 1080, "corner");

  brush.fill(PALETTE.paperLight, 32);
  brush.fillBleed(0.4, "out");
  brush.circle(550, 480, 460, 0.2);
  brush.noFill();

  // Fine newsprint fiber grain (cool grey 2H pencil micro-strokes)
  brush.set("2H", PALETTE.paperMid, 0.35);
  for (let i = 0; i < 420; i++) {
    let x = random(20, 1180);
    let y = random(20, 1180);
    let len = random(18, 85);
    let ang = random(-4, 4);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  brush.set("2H", PALETTE.paperLight, 0.3);
  for (let i = 0; i < 260; i++) {
    let x = random(20, 1180);
    let y = random(20, 1180);
    let len = random(14, 65);
    let ang = random(86, 94);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // Subtle tabletop plane indication behind the glass (z ≈ 0.05, almost converged)
  let horizonY = 915;
  for (let i = 0; i < 38; i++) {
    let y = horizonY + pow(i / 38, 1.35) * 240;
    let z = lerp(0.04, 0.45, i / 38);
    let dx = getDX(z);
    let x1 = random(70, 260);
    let x2 = random(940, 1130);

    brush.set("2H", PALETTE.cyanLight, 0.22);
    brush.line(x1 - dx, y, x2 - dx, y + random(-1.5, 1.5));

    brush.set("2H", PALETTE.redLight, 0.22);
    brush.line(x1 + dx, y + 0.5, x2 + dx, y + random(-1.5, 1.5));
  }
}

// ============================================================================
// 2. CAST SHADOW & REFRACTIVE CAUSTICS ON TABLETOP
// ============================================================================
function drawCastShadowAndCaustics() {
  let baseCX = GLASS.cx;
  let baseCY = GLASS.baseY;

  // Elliptical shadow stretching to the right
  let shCX = baseCX + 185;
  let shCY = baseCY + 12;
  let shRX = 250;
  let shRY = 46;
  let zShadow = 0.22; // Near the table plane toward back/side of glass
  let dx = getDX(zShadow);

  // Under-wash for Cyan, Red, and Coincident Warm-Black core
  brush.noStroke();
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.55, 0.25);

  brush.fill(PALETTE.cyanDark, 42);
  drawEllipseShape(shCX - dx, shCY, shRX, shRY, 28);

  brush.fill(PALETTE.redDark, 42);
  drawEllipseShape(shCX + dx, shCY, shRX, shRY, 28);

  brush.fill(PALETTE.blackWarmDark, 68);
  drawEllipseShape(shCX, shCY, shRX - dx * 1.1, shRY * 0.88, 28);
  brush.noFill();

  // Horizontal pencil shading across cast shadow with caustic light gaps
  for (let i = -42; i <= 42; i += 2.2) {
    let normY = i / 44;
    let y = shCY + i;
    let halfW = shRX * sqrt(max(0, 1 - normY * normY));
    if (halfW < 15) continue;

    // Depth increases slightly from back edge of shadow to front edge
    let localZ = lerp(0.09, 0.36, (normY + 1) * 0.5);
    let ldx = getDX(localZ);

    let xStart = baseCX - GLASS.baseRX * 0.65;
    let xEnd = shCX + halfW;

    // Leave caustic light bands inside the shadow (refracted light rings)
    let caustic1X = baseCX + 155 + normY * 28;
    let caustic2X = baseCX + 245 - normY * 35;

    // Cyan shadow pass
    brush.set("HB", PALETTE.cyanDark, 0.45);
    brush.line(xStart - ldx, y, caustic1X - 18 - ldx, y);
    brush.line(caustic1X + 18 - ldx, y, caustic2X - 14 - ldx, y);
    brush.line(caustic2X + 14 - ldx, y, xEnd - ldx, y);

    // Red shadow pass
    brush.set("HB", PALETTE.redDark, 0.45);
    brush.line(xStart + ldx, y + 0.3, caustic1X - 18 + ldx, y + 0.3);
    brush.line(caustic1X + 18 + ldx, y + 0.3, caustic2X - 14 + ldx, y + 0.3);
    brush.line(caustic2X + 14 + ldx, y + 0.3, xEnd + ldx, y + 0.3);

    // Warm near-black coincidence where Cyan and Red shadow segments overlap
    if (caustic1X - 18 - ldx > xStart + ldx) {
      brush.set("2B", PALETTE.blackWarmDark, 0.55);
      brush.line(xStart + ldx, y, caustic1X - 18 - ldx, y);
    }
    if (caustic2X - 14 - ldx > caustic1X + 18 + ldx) {
      brush.set("2B", PALETTE.blackWarmMid, 0.5);
      brush.line(caustic1X + 18 + ldx, y, caustic2X - 14 - ldx, y);
    }
    if (xEnd - ldx > caustic2X + 14 + ldx) {
      brush.set("HB", PALETTE.blackWarmMid, 0.45);
      brush.line(caustic2X + 14 + ldx, y, xEnd - ldx, y);
    }
  }

  // Crisp refractive caustic arcs inside the shadow
  for (let c = 0; c < 5; c++) {
    let arcX = baseCX + 140 + c * 32;
    let ptsC = [];
    let ptsR = [];
    let ptsK = [];
    for (let a = -38; a <= 38; a += 8) {
      let localZ = lerp(0.11, 0.32, (a + 38) / 76);
      let ldx = getDX(localZ);
      let px = arcX + cos(a * 1.6) * (34 + c * 6);
      let py = shCY + sin(a) * 38;
      ptsC.push([px - ldx, py]);
      ptsR.push([px + ldx, py]);
      ptsK.push([px, py]);
    }
    brush.set("2H", PALETTE.cyanMid, 0.5);
    brush.spline(ptsC, 0.5);
    brush.set("2H", PALETTE.redMid, 0.5);
    brush.spline(ptsR, 0.5);
    if (c % 2 === 0) {
      brush.set("2H", PALETTE.blackWarmMid, 0.4);
      brush.spline(ptsK, 0.5);
    }
  }
}

// ============================================================================
// 3. BACK RIM & FAR GLASS STRUCTURE (CONVERGING DEPTH z ≈ 0.08)
// ============================================================================
function drawBackGlassStructure() {
  // Back half of the top rim: theta from 180 to 360 degrees
  // At theta = 270 (back center), z = 0.08 -> dx ≈ 2px (nearly converges!)
  let rimPtsC = [];
  let rimPtsR = [];
  let rimPtsK = [];
  let innerRimPtsC = [];
  let innerRimPtsR = [];
  let innerRimPtsK = [];

  for (let a = 180; a <= 360; a += 5) {
    let z = 0.56 + 0.48 * sin(a); // 0.08 at a=270, 0.56 at a=180,360
    let dx = getDX(z);
    let x = GLASS.cx + GLASS.topRX * cos(a);
    let y = GLASS.topY + GLASS.topRY * sin(a);
    rimPtsC.push([x - dx, y]);
    rimPtsR.push([x + dx, y]);

    let ix = GLASS.cx + (GLASS.topRX - 7) * cos(a);
    let iy = GLASS.topY + (GLASS.topRY - 3) * sin(a) + 2;
    innerRimPtsC.push([ix - dx, iy]);
    innerRimPtsR.push([ix + dx, iy]);

    // Near the back of the glass (a in 215..325), cyan and red lines nearly converge
    if (a >= 210 && a <= 330) {
      rimPtsK.push([x, y]);
      innerRimPtsK.push([ix, iy]);
    }
  }

  brush.set("HB", PALETTE.cyanDark, 0.75);
  brush.spline(rimPtsC, 0.5);
  brush.set("2H", PALETTE.cyanMid, 0.55);
  brush.spline(innerRimPtsC, 0.5);

  brush.set("HB", PALETTE.redDark, 0.75);
  brush.spline(rimPtsR, 0.5);
  brush.set("2H", PALETTE.redMid, 0.55);
  brush.spline(innerRimPtsR, 0.5);

  // Coincident warm near-black along the converged back rim
  brush.set("2B", PALETTE.blackWarmDark, 0.8);
  brush.spline(rimPtsK, 0.5);
  brush.set("HB", PALETTE.blackWarmMid, 0.55);
  brush.spline(innerRimPtsK, 0.5);

  // Subtle vertical shading on the far upper interior wall (between topY and meniscusY)
  for (let a = 195; a <= 345; a += 4) {
    let z = 0.56 + 0.48 * sin(a);
    let dx = getDX(z);
    let xTop = GLASS.cx + (GLASS.topRX - 7) * cos(a);
    let yTop = GLASS.topY + (GLASS.topRY - 3) * sin(a) + 2;
    let xBot = GLASS.cx + (GLASS.meniscusRX - 7) * cos(a);
    let yBot = GLASS.meniscusY + (GLASS.meniscusRY - 3) * sin(a);

    // Leave central highlight gap on the back wall
    if (abs(a - 255) < 16) continue;

    brush.set("2H", PALETTE.cyanLight, 0.35);
    brush.line(xTop - dx, yTop, xBot - dx, yBot);
    brush.set("2H", PALETTE.redLight, 0.35);
    brush.line(xTop + dx, yTop, xBot + dx, yBot);

    if (z < 0.22) {
      brush.set("2H", PALETTE.blackWarmLight, 0.35);
      brush.line(xTop, yTop, xBot, yBot);
    }
  }
}

// ============================================================================
// 4. COLA LIQUID BODY & MENISCUS (TONAL WASHES + DENSE ANAGLYPH PENCIL)
// ============================================================================
function drawColaLiquidBody() {
  // Build the liquid polygon for Cyan (-dx), Red (+dx), and Coincident Warm-Black Core
  let zColaMid = 0.52;
  let dxMid = getDX(zColaMid);

  let polyC = [];
  let polyR = [];
  let polyK = [];

  // Top meniscus curve (back to front or left to right)
  for (let a = 180; a >= 0; a -= 12) {
    let x = GLASS.cx + (GLASS.meniscusRX - 8) * cos(a);
    let y = GLASS.meniscusY + GLASS.meniscusRY * sin(a) * 0.7;
    polyC.push([x - dxMid, y]);
    polyR.push([x + dxMid, y]);
    let kX = GLASS.cx + max(10, GLASS.meniscusRX - 8 - dxMid) * cos(a);
    polyK.push([kX, y]);
  }
  // Right inner wall down to shamTopY
  for (let y = GLASS.meniscusY + 20; y <= GLASS.shamTopY; y += 45) {
    let rx = glassRX(y) - glassWall(y);
    polyC.push([GLASS.cx + rx - dxMid, y]);
    polyR.push([GLASS.cx + rx + dxMid, y]);
    polyK.push([GLASS.cx + max(10, rx - dxMid), y]);
  }
  // Bottom sham meniscus curve
  for (let a = 0; a <= 180; a += 12) {
    let rx = GLASS.shamRX - glassWall(GLASS.shamTopY);
    let x = GLASS.cx + rx * cos(a);
    let y = GLASS.shamTopY + GLASS.shamRY * sin(a) * 0.85;
    polyC.push([x - dxMid, y]);
    polyR.push([x + dxMid, y]);
    let kX = GLASS.cx + max(10, rx - dxMid) * cos(a);
    polyK.push([kX, y]);
  }
  // Left inner wall back up to meniscusY
  for (let y = GLASS.shamTopY - 20; y >= GLASS.meniscusY + 20; y -= 45) {
    let rx = glassRX(y) - glassWall(y);
    polyC.push([GLASS.cx - rx - dxMid, y]);
    polyR.push([GLASS.cx - rx + dxMid, y]);
    polyK.push([GLASS.cx - max(10, rx - dxMid), y]);
  }

  // Foundational translucent watercolor washes for Cyan, Red, and Coincident Warm-Black
  brush.noStroke();
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.55, 0.3);

  brush.fill(PALETTE.cyanDark, 68);
  drawPolyShape(polyC);

  brush.fill(PALETTE.redDark, 68);
  drawPolyShape(polyR);

  // Deep warm near-black where the cyan and red cola columns coincide
  brush.fill(PALETTE.blackWarmDark, 125);
  drawPolyShape(polyK);

  // Extra deep upper-mid cola core wash (where ice shadows concentrate)
  let corePoly = [];
  for (let a = 0; a < 360; a += 20) {
    let rx = 118 - 18 * sin(a);
    let ry = 215;
    corePoly.push([GLASS.cx + rx * cos(a), 565 + ry * sin(a)]);
  }
  brush.fill(PALETTE.blackWarmAbyss, 95);
  drawPolyShape(corePoly);
  brush.noFill();

  // Dense horizontal/elliptical contour pencil shading across the entire cola column
  for (let y = GLASS.meniscusY + 4; y <= GLASS.shamTopY + 18; y += 3.2) {
    let tY = (y - GLASS.meniscusY) / (GLASS.shamTopY - GLASS.meniscusY);
    let rx = glassRX(y) - glassWall(y);
    let ry = glassRY(y) * 0.78;

    // Depth of the liquid body varies from 0.42 near bottom/back to 0.58 near upper front
    let rowZ = lerp(0.56, 0.44, tY * 0.6);
    let dx = getDX(rowZ);

    // Left and right specular/refractive light windows near the glass edges and lower third
    let leftInset = lerp(4, 14, sin(tY * 180));
    let rightInset = lerp(4, 18, sin(tY * 180));

    let xL = GLASS.cx - rx + leftInset;
    let xR = GLASS.cx + rx - rightInset;

    // Modulate line weight: heaviest in upper-mid cola, slightly lighter near bottom glow
    let baseW = tY < 0.72 ? lerp(0.85, 0.7, tY) : lerp(0.7, 0.42, (tY - 0.72) / 0.28);

    // 1. Cyan contour stroke (shifted left by -dx)
    brush.set("2B", tY < 0.75 ? PALETTE.cyanDeep : PALETTE.cyanDark, baseW);
    drawCurvedRow(xL - dx, xR - dx, y, ry * 0.45);

    // 2. Red contour stroke (shifted right by +dx)
    brush.set("2B", tY < 0.75 ? PALETTE.redDeep : PALETTE.redDark, baseW);
    drawCurvedRow(xL + dx, xR + dx, y + 0.4, ry * 0.45);

    // 3. Coincident Warm Near-Black core stroke (where [xL-dx, xR-dx] and [xL+dx, xR+dx] overlap: [xL+dx, xR-dx])
    let overlapL = xL + dx;
    let overlapR = xR - dx;
    if (overlapR > overlapL + 8) {
      // Leave refractive glow pockets near the bottom third of the cola
      let hasBottomGlow = tY > 0.74 && abs(sin(y * 1.7)) > 0.35;
      let kColor = tY < 0.68 ? PALETTE.blackWarmAbyss : PALETTE.blackWarmDark;
      let kWeight = hasBottomGlow ? baseW * 0.65 : baseW * 1.15;

      brush.set("2B", kColor, kWeight);
      if (hasBottomGlow) {
        // Split around a glowing refractive pocket on the right-center
        let glowL = GLASS.cx + 10;
        let glowR = GLASS.cx + 68;
        if (glowL > overlapL) drawCurvedRow(overlapL, glowL, y, ry * 0.32);
        if (overlapR > glowR) drawCurvedRow(glowR, overlapR, y, ry * 0.25);
      } else {
        drawCurvedRow(overlapL, overlapR, y, ry * 0.38);
      }
    }
  }

  // Vertical cross-hatching in the deep cola core to build hyperreal velvety density
  for (let xOff = -135; xOff <= 135; xOff += 5.5) {
    let u = xOff / 160;
    let z = lerp(0.38, 0.68, 1 - u * u);
    let dx = getDX(z);

    let yStart = GLASS.meniscusY + 18 + abs(xOff) * 0.15;
    let yEnd = GLASS.shamTopY - 25 - abs(xOff) * 0.35;
    if (yEnd <= yStart + 30) continue;

    // Cyan vertical shading
    brush.set("HB", PALETTE.cyanDark, 0.48);
    brush.line(GLASS.cx + xOff - dx, yStart, GLASS.cx + xOff * 0.82 - dx, yEnd);

    // Red vertical shading
    brush.set("HB", PALETTE.redDark, 0.48);
    brush.line(GLASS.cx + xOff + dx, yStart, GLASS.cx + xOff * 0.82 + dx, yEnd);

    // Warm near-black vertical cross-hatching in the central coincidence band
    if (abs(xOff) < 105) {
      let yCoreEnd = abs(xOff) < 55 ? yEnd - 40 : yEnd - 110;
      brush.set("2B", PALETTE.blackWarmAbyss, 0.62);
      brush.line(GLASS.cx + xOff, yStart + 10, GLASS.cx + xOff * 0.84, yCoreEnd);
    }
  }

  // Meniscus elliptical rings (back arc nearly converged, front arc widely split)
  drawAnaglyphEllipseRing(
    GLASS.cx,
    GLASS.meniscusY,
    GLASS.meniscusRX - 8,
    GLASS.meniscusRY,
    0.55,
    0.45,
    0.8
  );
}

// ============================================================================
// 5. FRACTURED ICE CUBES (SUBMERGED & FLOATING AT MENISCUS)
// ============================================================================
function drawIceCubes() {
  const cubes = [
    // Floating / crowning ice cubes breaking through the meniscus
    { cx: 525, cy: 318, rx: 56, ry: 44, rot: -14, z: 0.72, emerging: true },
    { cx: 632, cy: 325, rx: 58, ry: 46, rot: 18, z: 0.64, emerging: true },
    { cx: 578, cy: 348, rx: 52, ry: 42, rot: 6, z: 0.92, emerging: true },

    // Upper-mid submerged ice cubes
    { cx: 642, cy: 455, rx: 64, ry: 54, rot: -22, z: 0.82, emerging: false },
    { cx: 565, cy: 525, rx: 68, ry: 56, rot: 15, z: 0.88, emerging: false },

    // Mid-lower submerged ice cubes
    { cx: 495, cy: 615, rx: 58, ry: 50, rot: -18, z: 0.74, emerging: false },
    { cx: 628, cy: 650, rx: 62, ry: 54, rot: 24, z: 0.78, emerging: false },

    // Deep bottom ice cubes resting near the crystal sham
    { cx: 540, cy: 785, rx: 60, ry: 48, rot: -11, z: 0.66, emerging: false },
    { cx: 618, cy: 825, rx: 56, ry: 46, rot: 16, z: 0.62, emerging: false }
  ];

  for (let idx = 0; idx < cubes.length; idx++) {
    let c = cubes[idx];
    let dx = getDX(c.z);

    // Construct hex/octagonal polyhedral vertices for this ice cube
    let verts = [];
    let angles = [-145, -90, -32, 25, 85, 148];
    for (let i = 0; i < angles.length; i++) {
      let a = angles[i] + c.rot;
      let rMod = 0.88 + 0.22 * noise(idx * 10 + i * 2.3);
      let vx = c.cx + cos(a) * c.rx * rMod;
      let vy = c.cy + sin(a) * c.ry * rMod;
      verts.push([vx, vy]);
    }

    // For emerging cubes at the top, lift paper-grey highlights on their top facets
    if (c.emerging) {
      let topFacet = [verts[0], verts[1], verts[2], [c.cx, c.cy - 4]];
      brush.noStroke();
      brush.fillBleed(0.08, "in");
      brush.fillTexture(0.35, 0.2);
      brush.fill(PALETTE.paperLight, 155);
      drawPolyShape(shiftPoly(topFacet, -dx * 0.4, 0));
      drawPolyShape(shiftPoly(topFacet, dx * 0.4, 0));
      brush.noFill();
    } else {
      // Submerged cubes have bright refractive edges lifting slightly against the dark cola
      let rimFacet = [verts[0], verts[1], [c.cx, c.cy - c.ry * 0.25]];
      brush.noStroke();
      brush.fill(PALETTE.paperBase, 92);
      drawPolyShape(shiftPoly(rimFacet, -dx * 0.5, 0));
      drawPolyShape(shiftPoly(rimFacet, dx * 0.5, 0));
      brush.noFill();
    }

    // Draw outer polyhedral bevel contours in Cyan (-dx), Red (+dx), and Coincident Warm-Black
    let polyC = shiftPoly(verts, -dx, 0);
    let polyR = shiftPoly(verts, dx, 0);

    brush.set("HB", PALETTE.cyanLight, 0.65);
    drawClosedSpline(polyC, 0.2);
    brush.set("2B", PALETTE.cyanDark, 0.75);
    drawOpenSpline([polyC[2], polyC[3], polyC[4], polyC[5]], 0.2);

    brush.set("HB", PALETTE.redLight, 0.65);
    drawClosedSpline(polyR, 0.2);
    brush.set("2B", PALETTE.redDark, 0.75);
    drawOpenSpline([polyR[2], polyR[3], polyR[4], polyR[5]], 0.2);

    // Internal dark refracted cola traps inside each ice cube
    let trapPoly = [
      [c.cx - c.rx * 0.35, c.cy + c.ry * 0.05],
      [c.cx + c.rx * 0.28, c.cy - c.ry * 0.15],
      [c.cx + c.rx * 0.42, c.cy + c.ry * 0.35],
      [c.cx - c.rx * 0.18, c.cy + c.ry * 0.48]
    ];

    // Hatch the internal refraction trap in Cyan, Red, and Warm Near-Black overlap
    hatchIceFacet(shiftPoly(trapPoly, -dx, 0), PALETTE.cyanDeep, 4.2, 35 + c.rot, 0.55);
    hatchIceFacet(shiftPoly(trapPoly, dx, 0), PALETTE.redDeep, 4.2, -35 + c.rot, 0.55);

    // Coincident center of the dark ice trap deepens to warm near-black
    let trapCore = [
      [c.cx - c.rx * 0.18, c.cy + c.ry * 0.08],
      [c.cx + c.rx * 0.16, c.cy - c.ry * 0.08],
      [c.cx + c.rx * 0.24, c.cy + c.ry * 0.32],
      [c.cx - c.rx * 0.10, c.cy + c.ry * 0.38]
    ];
    hatchIceFacet(trapCore, PALETTE.blackWarmAbyss, 3.4, 15 + c.rot, 0.75);

    // Internal crystal fracture planes & crazing cracks (double into vivid cyan/red fringes!)
    for (let f = 0; f < 9; f++) {
      let fz = c.z + random(-0.08, 0.08);
      let fdx = getDX(fz);
      let fx1 = c.cx + random(-c.rx * 0.55, c.rx * 0.35);
      let fy1 = c.cy + random(-c.ry * 0.55, c.ry * 0.35);
      let fx2 = fx1 + random(-28, 32);
      let fy2 = fy1 + random(-22, 26);
      let fx3 = fx2 + random(-24, 24);
      let fy3 = fy2 + random(-18, 22);

      // Crisp fracture line in Cyan
      brush.set("rotring", f % 2 === 0 ? PALETTE.cyanLight : PALETTE.cyanDark, 0.48);
      brush.spline([[fx1 - fdx, fy1], [fx2 - fdx, fy2], [fx3 - fdx, fy3]], 0.15);

      // Crisp fracture line in Red
      brush.set("rotring", f % 2 === 0 ? PALETTE.redLight : PALETTE.redDark, 0.48);
      brush.spline([[fx1 + fdx, fy1], [fx2 + fdx, fy2], [fx3 + fdx, fy3]], 0.15);

      // Crisp paper-white glint next to fracture
      if (f < 4) {
        brush.set("2H", PALETTE.paperLight, 0.65);
        brush.line(fx1 - fdx + 1, fy1 - 1, fx2 - fdx + 1, fy2 - 1);
        brush.line(fx1 + fdx + 1, fy1 - 1, fx2 + fdx + 1, fy2 - 1);
      }
    }
  }
}

function hatchIceFacet(pts, col, spacing, angle, weight) {
  brush.noStroke();
  brush.noFill();
  brush.hatchStyle("HB", col, weight);
  brush.hatch(spacing, angle, { rand: 0.08 });
  drawPolyShape(pts);
  brush.noHatch();
}

