// Shared hyperreal botanical renderer for lemon wheels in Cyan, Red & Warm Near-Black
function drawDetailedLemonWheel(cx, cy, rx, ry, rotDeg, zCenter, isSubmerged) {
  let dxCenter = getDX(zCenter);
  let rindThick = isSubmerged ? 12 : 16;
  let startAng = isSubmerged ? -105 : -155;
  let endAng = isSubmerged ? 105 : 165;

  // 1. Pith ring paper-light lift (clean cool newsprint grey so the pith reads bright)
  let pithPoly = [];
  for (let a = startAng; a <= endAng; a += 10) {
    let ang = a + rotDeg;
    pithPoly.push([cx + cos(ang) * (rx - 4), cy + sin(ang) * (ry - 4)]);
  }
  pithPoly.push([cx, cy]);

  brush.noStroke();
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.25, 0.15);
  brush.fill(PALETTE.paperLight, isSubmerged ? 135 : 195);
  drawPolyShape(shiftPoly(pithPoly, -dxCenter * 0.45, 0));
  drawPolyShape(shiftPoly(pithPoly, dxCenter * 0.45, 0));
  brush.noFill();

  // 2. Radial citrus segments (carpels) with individual teardrop juice vesicles!
  let numSegs = isSubmerged ? 6 : 8;
  let segSpan = (endAng - startAng) / numSegs;

  for (let s = 0; s < numSegs; s++) {
    let a1 = startAng + s * segSpan + 3.5 + rotDeg;
    let a2 = startAng + (s + 1) * segSpan - 3.5 + rotDeg;
    let aMid = (a1 + a2) * 0.5;

    // Depth varies across the face of the lemon slice
    let segZ = zCenter + 0.09 * sin(aMid);
    let sdx = getDX(segZ);

    let rInner = 11;
    let rOuter = rx - rindThick;
    let ryOuter = ry - rindThick;

    let segPoly = [
      [cx + cos(aMid) * rInner, cy + sin(aMid) * rInner],
      [cx + cos(a1) * rOuter * 0.6, cy + sin(a1) * ryOuter * 0.6],
      [cx + cos(a1) * rOuter, cy + sin(a1) * ryOuter],
      [cx + cos(aMid) * (rOuter + 3), cy + sin(aMid) * (ryOuter + 3)],
      [cx + cos(a2) * rOuter, cy + sin(a2) * ryOuter],
      [cx + cos(a2) * rOuter * 0.6, cy + sin(a2) * ryOuter * 0.6]
    ];

    // Subtle tonal wash for each segment
    brush.noStroke();
    brush.fill(PALETTE.cyanMid, isSubmerged ? 45 : 35);
    drawPolyShape(shiftPoly(segPoly, -sdx, 0));
    brush.fill(PALETTE.redMid, isSubmerged ? 45 : 35);
    drawPolyShape(shiftPoly(segPoly, sdx, 0));
    brush.noFill();

    // Segment outline in Cyan and Red
    brush.set("HB", PALETTE.cyanDark, 0.55);
    drawClosedSpline(shiftPoly(segPoly, -sdx, 0), 0.35);
    brush.set("HB", PALETTE.redDark, 0.55);
    drawClosedSpline(shiftPoly(segPoly, sdx, 0), 0.35);

    // Individual radial juice vesicles (pulp sacs) inside the segment
    for (let rFrac = 0.22; rFrac <= 0.92; rFrac += 0.13) {
      let subSteps = floor(map(rFrac, 0.2, 0.95, 2, 5));
      for (let k = 0; k <= subSteps; k++) {
        let ang = lerp(a1 + 2, a2 - 2, (k + 0.5) / (subSteps + 1));
        let vx1 = cx + cos(ang) * rOuter * (rFrac - 0.05);
        let vy1 = cy + sin(ang) * ryOuter * (rFrac - 0.05);
        let vx2 = cx + cos(ang) * rOuter * (rFrac + 0.07);
        let vy2 = cy + sin(ang) * ryOuter * (rFrac + 0.07);

        let perpX = -sin(ang) * 2.4;
        let perpY = cos(ang) * 2.4;

        // Cyan vesicle teardrop
        brush.set("2H", PALETTE.cyanDark, 0.42);
        brush.spline([
          [vx1 - sdx, vy1],
          [ (vx1 + vx2) * 0.5 + perpX - sdx, (vy1 + vy2) * 0.5 + perpY ],
          [vx2 - sdx, vy2]
        ], 0.5);

        // Red vesicle teardrop
        brush.set("2H", PALETTE.redDark, 0.42);
        brush.spline([
          [vx1 + sdx, vy1],
          [ (vx1 + vx2) * 0.5 + perpX + sdx, (vy1 + vy2) * 0.5 + perpY ],
          [vx2 + sdx, vy2]
        ], 0.5);

        // Where cyan & red pulp shadows overlap between segments, deepen to warm near-black
        if ((k === 0 || k === subSteps) && rFrac > 0.38) {
          brush.set("HB", PALETTE.blackWarmDark, 0.52);
          brush.line(vx1, vy1, vx2, vy2);
        }
      }
    }
  }

  // 3. Outer rind bevel (3D rind thickness & dimpled oil glands)
  let rindWidth = isSubmerged ? 14 : 22;
  for (let a = startAng; a <= endAng; a += 3.5) {
    let ang = a + rotDeg;
    let zRind = zCenter + 0.1 * sin(ang);
    let rdx = getDX(zRind);

    let x1 = cx + cos(ang) * rx;
    let y1 = cy + sin(ang) * ry;
    let x2 = x1 + cos(ang) * rindWidth * (0.55 + 0.45 * max(0, sin(ang - 25)));
    let y2 = y1 + sin(ang) * rindWidth * (0.55 + 0.45 * max(0, sin(ang - 25)));

    // Cross-contour rind shading
    brush.set("HB", PALETTE.cyanDark, 0.52);
    brush.line(x1 - rdx, y1, x2 - rdx, y2);

    brush.set("HB", PALETTE.redDark, 0.52);
    brush.line(x1 + rdx, y1, x2 + rdx, y2);

    // Oil gland dimples (tiny stippled ticks)
    let mx = lerp(x1, x2, random(0.2, 0.85));
    let my = lerp(y1, y2, random(0.2, 0.85));
    brush.set("rotring", PALETTE.cyanDeep, 0.55);
    brush.circle(mx - rdx, my, 1.4, 0.2);
    brush.set("rotring", PALETTE.redDeep, 0.55);
    brush.circle(mx + rdx, my, 1.4, 0.2);

    // Warm near-black coincidence on the shaded lower rind
    if (sin(ang) > 0.15) {
      brush.set("2B", PALETTE.blackWarmDark, 0.6);
      brush.line(x1, y1, lerp(x1, x2, 0.7), lerp(y1, y2, 0.7));
    }
  }
}

// ============================================================================
// 8. THE STRAW: SUBMERGED REFRACTED SHAFT & FOREGROUND BENDY STRAW
// ============================================================================
function drawAnaglyphStraw() {
  // Part A: Submerged straw shaft (broken/offset by optical refraction at meniscusY = 330)
  // Goes from (548, 330, z=0.86) down to (625, 760, z=0.52)
  let subSteps = 65;
  for (let i = 0; i <= subSteps; i++) {
    let t = i / subSteps;
    let y = lerp(GLASS.meniscusY + 2, 760, t);
    let x = lerp(548, 622, t);
    let z = lerp(0.86, 0.52, t);
    let dx = getDX(z);
    let rStraw = 13.5;

    // Perpendicular direction to submerged straw
    let nx = 0.985;
    let ny = -0.17;

    // Shaded side of submerged straw in Cyan, Red, and Warm-Black overlap
    brush.set("HB", PALETTE.cyanDark, 0.5);
    brush.line(x - nx * rStraw - dx, y - ny * rStraw, x + nx * rStraw * 0.4 - dx, y + ny * rStraw * 0.4);

    brush.set("HB", PALETTE.redDark, 0.5);
    brush.line(x - nx * rStraw + dx, y - ny * rStraw, x + nx * rStraw * 0.4 + dx, y + ny * rStraw * 0.4);

    // Highlight edge on right side of submerged straw
    brush.set("2H", PALETTE.paperLight, 0.55);
    brush.line(x + nx * (rStraw - 2) - dx, y + ny * (rStraw - 2), x + nx * rStraw - dx, y + ny * rStraw);
    brush.line(x + nx * (rStraw - 2) + dx, y + ny * (rStraw - 2), x + nx * rStraw + dx, y + ny * rStraw);
  }

  // Part B: Emerging straw above meniscus -> accordion bend -> foreground mouth
  // Spine control points with depth z ramping up to 1.76 at the foreground tip!
  // Segment 1: Meniscus (532, 330, z=0.88) to Bend start (496, 198, z=1.28)
  // Segment 2: Accordion Bend (496, 198, z=1.28) to (466, 162, z=1.44)
  // Segment 3: Upper foreground shaft (466, 162, z=1.44) to Mouth (352, 92, z=1.76)

  // First lift paper-light background along the emerging straw paths so they pop over the rim
  drawStrawSegment(532, 330, 0.88, 496, 198, 1.28, 14.5, false);
  drawStrawAccordion(496, 198, 1.28, 466, 162, 1.44, 15.2);
  drawStrawSegment(466, 162, 1.44, 352, 92, 1.76, 16.0, true);

  // Foreground elliptical straw mouth opening at (352, 92), z = 1.76 (widest offset: dx = ±44px!)
  let mouthX = 352;
  let mouthY = 92;
  let mouthZ = 1.76;
  let mdx = getDX(mouthZ);

  // Draw the hollow dark interior and crisp double-rim of the straw mouth in Cyan and Red
  for (let ch of [-1, 1]) {
    let shiftX = ch * mdx;
    let colDark = ch === -1 ? PALETTE.cyanDeep : PALETTE.redDeep;
    let colMid = ch === -1 ? PALETTE.cyanMid : PALETTE.redMid;

    //Rotated elliptical opening at mouth
    let mouthPts = [];
    let innerPts = [];
    for (let a = 0; a <= 360; a += 15) {
      let ang = a;
      let ex = cos(ang) * 10.5;
      let ey = sin(ang) * 16.5;
      // Rotate ellipse by 32 degrees to face along straw axis
      let rx = ex * cos(32) - ey * sin(32);
      let ry = ex * sin(32) + ey * cos(32);
      mouthPts.push([mouthX + shiftX + rx, mouthY + ry]);
      innerPts.push([mouthX + shiftX + rx * 0.78, mouthY + ry * 0.78]);
    }

    // Dark interior hollow hatch
    hatchIceFacet(innerPts, colDark, 2.5, 45 * ch, 0.65);

    brush.set("2B", colDark, 0.85);
    brush.spline(mouthPts, 0.5);
    brush.set("HB", colMid, 0.65);
    brush.spline(innerPts, 0.5);
  }
}

function drawStrawSegment(x1, y1, z1, x2, y2, z2, radius, isUpper) {
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang);
  let ny = cos(ang);

  let steps = 58;
  let leftC = [], rightC = [];
  let leftR = [], rightR = [];
  let leftK = [], rightK = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = lerp(x1, x2, t);
    let y = lerp(y1, y2, t);
    let z = lerp(z1, z2, t);
    let dx = getDX(z);
    let r = lerp(radius * 0.96, radius * 1.04, t);

    let lx = x - nx * r;
    let ly = y - ny * r;
    let rx = x + nx * r;
    let ry = y + ny * r;

    leftC.push([lx - dx, ly]);
    rightC.push([rx - dx, ry]);
    leftR.push([lx + dx, ly]);
    rightR.push([rx + dx, ry]);

    // Clean paper highlight along the upper/right tubular edge
    brush.set("2H", PALETTE.paperLight, 0.75);
    brush.line(x + nx * r * 0.25 - dx, y + ny * r * 0.25, x + nx * r * 0.8 - dx, y + ny * r * 0.8);
    brush.line(x + nx * r * 0.25 + dx, y + ny * r * 0.25, x + nx * r * 0.8 + dx, y + ny * r * 0.8);

    // Cylindrical cross-contour shading on the underside of the straw
    let isStripe = sin(t * 540 + (isUpper ? 80 : 0)) > 0.35;
    let wMod = isStripe ? 0.72 : 0.38;

    brush.set("HB", isStripe ? PALETTE.cyanDeep : PALETTE.cyanMid, wMod);
    brush.line(lx - dx, ly, x + nx * r * 0.2 - dx, y + ny * r * 0.2);

    brush.set("HB", isStripe ? PALETTE.redDeep : PALETTE.redMid, wMod);
    brush.line(lx + dx, ly, x + nx * r * 0.2 + dx, y + ny * r * 0.2);

    // Where the cyan right edge and red left edge overlap (or cross the glass rim), warm near-black!
    if (rx - dx > lx + dx - 4) {
      brush.set("2B", PALETTE.blackWarmDark, 0.58);
      brush.line(lx + dx, ly, min(rx - dx, x + nx * r * 0.35 - dx), ry);
    }
  }

  // Crisp outer wall contours of the straw in Cyan and Red
  brush.set("2B", PALETTE.cyanDark, 0.75);
  brush.spline(leftC, 0.3);
  brush.set("HB", PALETTE.cyanMid, 0.6);
  brush.spline(rightC, 0.3);

  brush.set("2B", PALETTE.redDark, 0.75);
  brush.spline(leftR, 0.3);
  brush.set("HB", PALETTE.redMid, 0.6);
  brush.spline(rightR, 0.3);
}

function drawStrawAccordion(x1, y1, z1, x2, y2, z2, radius) {
  let numRings = 6;
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang);
  let ny = cos(ang);

  for (let i = 0; i < numRings; i++) {
    let tA = i / numRings;
    let tMid = (i + 0.5) / numRings;
    let tB = (i + 1) / numRings;

    let xA = lerp(x1, x2, tA), yA = lerp(y1, y2, tA);
    let xM = lerp(x1, x2, tMid), yM = lerp(y1, y2, tMid);
    let xB = lerp(x1, x2, tB), yB = lerp(y1, y2, tB);

    let zM = lerp(z1, z2, tMid);
    let dx = getDX(zM);

    let rIn = radius * 0.84;
    let rOut = radius * 1.18;

    // Corrugated diamond pleat profile in Cyan (-dx) and Red (+dx)
    for (let ch of [-1, 1]) {
      let s = ch * dx;
      let colDark = ch === -1 ? PALETTE.cyanDeep : PALETTE.redDeep;
      let colMid = ch === -1 ? PALETTE.cyanMid : PALETTE.redMid;

      // Outer ridge ring
      brush.set("2B", colDark, 0.7);
      brush.line(xM - nx * rOut + s, yM - ny * rOut, xM + nx * rOut + s, yM + ny * rOut);

      // Inner valley ring
      brush.set("HB", colMid, 0.5);
      brush.line(xA - nx * rIn + s, yA - ny * rIn, xA + nx * rIn + s, yA + ny * rIn);

      // Zig-zag side pleats
      brush.set("2B", colDark, 0.68);
      brush.line(xA - nx * rIn + s, yA - ny * rIn, xM - nx * rOut + s, yM - ny * rOut);
      brush.line(xM - nx * rOut + s, yM - ny * rOut, xB - nx * rIn + s, yB - ny * rIn);
      brush.line(xA + nx * rIn + s, yA + ny * rIn, xM + nx * rOut + s, yM + ny * rOut);
      brush.line(xM + nx * rOut + s, yM + ny * rOut, xB + nx * rIn + s, yB + ny * rIn);
    }
  }
}

// ============================================================================
// 9. CARBONATION TRAILS, MENISCUS FOAM COLLAR & FIZZ SPRAY
// ============================================================================
function drawCarbonationAndFizz() {
  // A. 24 Rising Carbonation Bubble Trails inside the Cola
  for (let tIdx = 0; tIdx < 24; tIdx++) {
    let startY = random(460, GLASS.shamTopY - 12);
    let endY = GLASS.meniscusY + random(-6, 12);
    let baseU = random(-0.82, 0.82);
    // Depth of this bubble stream inside the glass
    let streamZ = lerp(0.32, 0.96, pow(random(), 0.75));
    let numBubbles = floor((startY - endY) / random(9, 15));

    for (let b = 0; b < numBubbles; b++) {
      let frac = b / numBubbles;
      let y = lerp(startY, endY, frac);
      let rx = glassRX(y) - glassWall(y) - 6;
      let wobble = sin(frac * 360 * 1.8 + tIdx * 37) * 9;
      let x = GLASS.cx + baseU * rx + wobble;

      let bZ = streamZ + 0.04 * sin(frac * 180);
      let dx = getDX(bZ);
      let bRad = random(1.4, 4.6) * lerp(0.75, 1.25, frac);

      // Draw twin stereo carbonation bubble in Cyan (-dx) and Red (+dx)
      brush.set("rotring", PALETTE.cyanLight, 0.5);
      brush.circle(x - dx, y, bRad, 0.15);

      brush.set("rotring", PALETTE.redLight, 0.5);
      brush.circle(x + dx, y, bRad, 0.15);

      // Pinpoint paper-light glint on larger bubbles
      if (bRad > 3.1) {
        brush.set("2H", PALETTE.paperLight, 0.6);
        brush.line(x - dx - 1, y - 1, x - dx + 1, y - 1);
        brush.line(x + dx - 1, y - 1, x + dx + 1, y - 1);
      }
    }
  }

  // B. Fizzing Meniscus Foam Collar around the liquid surface (y ≈ 330)
  for (let a = 0; a < 360; a += 2.2) {
    let isFront = sin(a) >= 0;
    let z = 0.56 + 0.45 * sin(a);
    let dx = getDX(z);

    let rSpread = random(-16, 4);
    let x = GLASS.cx + (GLASS.meniscusRX - 9 + rSpread) * cos(a);
    let y = GLASS.meniscusY + (GLASS.meniscusRY + rSpread * 0.25) * sin(a) + random(-4, 4);
    let bRad = random(1.8, 5.2);

    brush.set("2H", isFront ? PALETTE.cyanMid : PALETTE.cyanLight, 0.48);
    brush.circle(x - dx, y, bRad, 0.2);

    brush.set("2H", isFront ? PALETTE.redMid : PALETTE.redLight, 0.48);
    brush.circle(x + dx, y, bRad, 0.2);

    // Where the foam ring converges near the back/sides or clusters tightly, warm near-black ticks
    if (z < 0.35 || random() < 0.28) {
      brush.set("rotring", PALETTE.blackWarmDark, 0.45);
      brush.circle(x, y + 1, bRad * 0.65, 0.15);
    }
  }

  // C. Effervescent Airborne Fizz Spray leaping above the meniscus & rim!
  for (let s = 0; s < 78; s++) {
    let ang = random(0, 360);
    let radFrac = random(0.15, 0.95);
    let x = GLASS.cx + cos(ang) * GLASS.meniscusRX * radFrac;
    let baseM = GLASS.meniscusY + sin(ang) * GLASS.meniscusRY * radFrac;
    let leapH = pow(random(), 1.6) * 95 + 8;
    let y = baseM - leapH;

    let z = 0.56 + 0.44 * sin(ang) * radFrac;
    let dx = getDX(z);
    let r = random(1.0, 3.2);

    // Tiny parabolic motion tick + droplet in Cyan and Red
    brush.set("rotring", PALETTE.cyanDark, 0.52);
    brush.circle(x - dx, y, r, 0.1);
    if (leapH > 35) {
      brush.set("2H", PALETTE.cyanLight, 0.35);
      brush.line(x - dx, y + 2, x - dx + random(-3, 3), y + 9);
    }

    brush.set("rotring", PALETTE.redDark, 0.52);
    brush.circle(x + dx, y, r, 0.1);
    if (leapH > 35) {
      brush.set("2H", PALETTE.redLight, 0.35);
      brush.line(x + dx, y + 2, x + dx + random(-3, 3), y + 9);
    }

    // Near the back rim where z is small, overlapping spray specks darken to warm near-black
    if (z < 0.24) {
      brush.set("rotring", PALETTE.blackWarmDark, 0.5);
      brush.circle(x, y, r * 0.8, 0.1);
    }
  }
}

// ============================================================================
// 10. FRONT GLASS WALL, HEAVY CRYSTAL SHAM FLUTES & FRONT RIM
// ============================================================================
function drawFrontGlassAndSham() {
  // A. Left and Right Outer/Inner Glass Profiles (z ≈ 0.56 along the silhouette)
  let zSide = 0.56;
  let dxSide = getDX(zSide);

  for (let side of [-1, 1]) {
    let outerC = [], innerC = [];
    let outerR = [], innerR = [];
    let outerK = [];

    for (let y = GLASS.topY; y <= GLASS.baseY; y += 25) {
      let rx = glassRX(y);
      let wall = glassWall(y);
      let ox = GLASS.cx + side * rx;
      let ix = GLASS.cx + side * (rx - wall);

      outerC.push([ox - dxSide, y]);
      innerC.push([ix - dxSide, y]);
      outerR.push([ox + dxSide, y]);
      innerR.push([ix + dxSide, y]);

      // Where the thick glass wall causes inner/outer cyan & red edges to cross, warm-black!
      outerK.push([GLASS.cx + side * (rx - wall * 0.5), y]);
    }

    brush.set("2B", PALETTE.cyanDark, 0.82);
    brush.spline(outerC, 0.25);
    brush.set("HB", PALETTE.cyanMid, 0.55);
    brush.spline(innerC, 0.25);

    brush.set("2B", PALETTE.redDark, 0.82);
    brush.spline(outerR, 0.25);
    brush.set("HB", PALETTE.redMid, 0.55);
    brush.spline(innerR, 0.25);

    // Refractive dark core line inside the glass wall thickness
    brush.set("HB", PALETTE.blackWarmDark, 0.6);
    brush.spline(outerK, 0.25);
  }

  // B. Heavy Crystal Sham Base (between shamTopY = 925 and baseY = 1025)
  // Elliptical refractive rings & vertical fluted facets in the thick glass bottom
  drawAnaglyphEllipseRing(GLASS.cx, GLASS.shamTopY, GLASS.shamRX, GLASS.shamRY, 0.55, 0.46, 0.75);
  drawAnaglyphEllipseRing(GLASS.cx, GLASS.shamTopY + 34, GLASS.shamRX - 3, GLASS.shamRY, 0.55, 0.46, 0.9);
  drawAnaglyphEllipseRing(GLASS.cx, GLASS.baseY - 14, GLASS.baseRX + 1, GLASS.baseRY, 0.55, 0.46, 0.85);
  drawAnaglyphEllipseRing(GLASS.cx, GLASS.baseY, GLASS.baseRX, GLASS.baseRY, 0.55, 0.46, 1.05);

  // Vertical crystal flutes and dark internal cola reflections in the heavy glass sham
  for (let a = -165; a <= 165; a += 9) {
    let radA = a;
    let isFront = sin(radA) >= 0;
    let z = 0.56 + 0.46 * sin(radA);
    let dx = getDX(z);

    let xTop = GLASS.cx + (GLASS.shamRX - 6) * cos(radA);
    let yTop = GLASS.shamTopY + GLASS.shamRY * sin(radA) * 0.8;
    let xBot = GLASS.cx + (GLASS.baseRX - 6) * cos(radA);
    let yBot = GLASS.baseY + GLASS.baseRY * sin(radA) * 0.85;

    // Alternating fluted refraction bands
    let isDarkBand = sin(a * 4) > 0.1;
    let w = isDarkBand ? (isFront ? 0.75 : 0.45) : 0.28;

    brush.set("HB", isDarkBand ? PALETTE.cyanDeep : PALETTE.cyanLight, w);
    brush.line(xTop - dx, yTop, xBot - dx, yBot);

    brush.set("HB", isDarkBand ? PALETTE.redDeep : PALETTE.redLight, w);
    brush.line(xTop + dx, yTop, xBot + dx, yBot);

    // Where dark sham reflections overlap (especially near back & left/right base corners), warm near-black
    if (isDarkBand && (z < 0.35 || abs(cos(radA)) > 0.65)) {
      brush.set("2B", PALETTE.blackWarmAbyss, 0.85);
      brush.line(xTop, yTop, xBot, yBot);
    }
  }

  // C. Front Half of Top Rim (theta from 0 to 180, z from 0.56 up to 1.04 at front center!)
  let frontRimC = [], frontRimR = [];
  let frontInnerC = [], frontInnerR = [];

  for (let a = 0; a <= 180; a += 5) {
    let z = 0.56 + 0.48 * sin(a);
    let dx = getDX(z);
    let x = GLASS.cx + GLASS.topRX * cos(a);
    let y = GLASS.topY + GLASS.topRY * sin(a);
    frontRimC.push([x - dx, y]);
    frontRimR.push([x + dx, y]);

    let ix = GLASS.cx + (GLASS.topRX - 7) * cos(a);
    let iy = GLASS.topY + (GLASS.topRY - 3) * sin(a) - 2.5;
    frontInnerC.push([ix - dx, iy]);
    frontInnerR.push([ix + dx, iy]);
  }

  // Paper-bright specular lip highlight on the front rim
  brush.set("2B", PALETTE.paperLight, 0.95);
  brush.spline(frontInnerC, 0.5);
  brush.spline(frontInnerR, 0.5);

  brush.set("2B", PALETTE.cyanDeep, 0.9);
  brush.spline(frontRimC, 0.5);
  brush.set("HB", PALETTE.cyanMid, 0.65);
  brush.spline(frontInnerC, 0.5);

  brush.set("2B", PALETTE.redDeep, 0.9);
  brush.spline(frontRimR, 0.5);
  brush.set("HB", PALETTE.redMid, 0.65);
  brush.spline(frontInnerR, 0.5);

  // D. Vertical Specular Reflection Ribbons down the front cylinder of the glass
  for (let y = GLASS.topY + 38; y <= GLASS.baseY - 25; y += 6) {
    let rx = glassRX(y);
    // Left-front specular window (u ≈ -0.62)
    let uL = -0.62;
    let zL = cylinderFrontZ(uL);
    let dxL = getDX(zL);
    let xL = GLASS.cx + uL * rx;

    brush.set("2H", PALETTE.paperLight, 0.85);
    brush.line(xL - dxL, y, xL + 11 - dxL, y);
    brush.line(xL + dxL, y, xL + 11 + dxL, y);

    // Right-front secondary specular streak (u ≈ 0.72)
    let uR = 0.72;
    let zR = cylinderFrontZ(uR);
    let dxR = getDX(zR);
    let xR = GLASS.cx + uR * rx;

    brush.set("2H", PALETTE.paperLight, 0.75);
    brush.line(xR - dxR, y, xR + 7 - dxR, y);
    brush.line(xR + dxR, y, xR + 7 + dxR, y);
  }
}

// ============================================================================
// 11. HYPERREAL CONDENSATION BEADS & WEEPING RUNNELS
// ============================================================================
function drawCondensationAndRunnels() {
  // A. 6 Weeping Vertical Sweat Runnels where heavy droplets have slid down the cold glass
  let runnels = [
    { u: -0.42, yStart: 355, yEnd: 685 },
    { u: -0.12, yStart: 390, yEnd: 835 },
    { u: 0.18, yStart: 345, yEnd: 740 },
    { u: 0.48, yStart: 420, yEnd: 880 },
    { u: -0.68, yStart: 480, yEnd: 810 },
    { u: 0.34, yStart: 560, yEnd: 910 }
  ];

  for (let rIdx = 0; rIdx < runnels.length; rIdx++) {
    let rn = runnels[rIdx];
    let z = cylinderFrontZ(rn.u);
    let dx = getDX(z);

    let trackC = [], trackR = [];
    let lastX = 0, lastY = 0;

    for (let y = rn.yStart; y <= rn.yEnd; y += 16) {
      let rx = glassRX(y);
      let wiggle = (noise(rIdx * 20 + y * 0.025) - 0.5) * 14;
      let x = GLASS.cx + rn.u * rx + wiggle;
      trackC.push([x - dx, y]);
      trackR.push([x + dx, y]);
      lastX = x;
      lastY = y;
    }

    // Faint double-edged sweat trail in Cyan and Red
    brush.set("2H", PALETTE.cyanLight, 0.45);
    brush.spline(trackC, 0.4);
    brush.set("2H", PALETTE.redLight, 0.45);
    brush.spline(trackR, 0.4);

    // Heavy pendant drop at the bottom of the runnel
    drawAnaglyphBead(lastX, lastY, random(6.2, 8.8), z, true);
  }

  // B. 270+ Individual Condensation Beads across the cold exterior cylinder
  for (let i = 0; i < 275; i++) {
    let y = random(GLASS.topY + 42, GLASS.shamTopY + 15);
    let rx = glassRX(y);
    // Distribute across front cylinder u in [-0.94, 0.94]
    let u = sin(random(-82, 82));
    let x = GLASS.cx + u * (rx - 4);
    let z = cylinderFrontZ(u);

    // Bead radius distribution: mostly fine/medium beads, some large swollen drops
    let p = random();
    let rad = p < 0.62 ? random(1.8, 3.8) : (p < 0.9 ? random(4.0, 6.4) : random(6.5, 9.2));

    drawAnaglyphBead(x, y, rad, z, rad > 4.2);
  }
}

// Render a single optical condensation bead in Cyan (-dx), Red (+dx), and Coincident Warm-Black
function drawAnaglyphBead(x, y, r, z, isDetailed) {
  let dx = getDX(z);

  // Cyan condensation bead at x - dx
  brush.set("rotring", PALETTE.cyanDeep, isDetailed ? 0.65 : 0.48);
  brush.arc(x - dx, y, r, 185, 355); // Dark upper refractive cap
  brush.set("2H", PALETTE.cyanMid, 0.42);
  brush.arc(x - dx, y, r, 5, 175);   // Lower edge

  // Red condensation bead at x + dx
  brush.set("rotring", PALETTE.redDeep, isDetailed ? 0.65 : 0.48);
  brush.arc(x + dx, y, r, 185, 355);
  brush.set("2H", PALETTE.redMid, 0.42);
  brush.arc(x + dx, y, r, 5, 175);

  if (isDetailed) {
    // Cast shadow crescent directly underneath each stereo bead
    brush.set("HB", PALETTE.cyanDark, 0.55);
    brush.line(x - dx - r * 0.6, y + r + 1.5, x - dx + r * 0.6, y + r + 1.5);

    brush.set("HB", PALETTE.redDark, 0.55);
    brush.line(x + dx - r * 0.6, y + r + 1.5, x + dx + r * 0.6, y + r + 1.5);

    // Bright paper-grey lower crescent highlight inside the bead
    brush.set("2H", PALETTE.paperLight, 0.78);
    brush.line(x - dx - r * 0.45, y + r * 0.45, x - dx + r * 0.45, y + r * 0.45);
    brush.line(x + dx - r * 0.45, y + r * 0.45, x + dx + r * 0.45, y + r * 0.45);

    // Dark warm near-black core dot where the bead refracts the dark cola behind it
    brush.set("2B", PALETTE.blackWarmAbyss, 0.62);
    brush.line(x - dx - r * 0.35, y - r * 0.35, x - dx + r * 0.35, y - r * 0.35);
    brush.line(x + dx - r * 0.35, y - r * 0.35, x + dx + r * 0.35, y - r * 0.35);
  }
}

