// GEOMETRY & PRIMITIVE HELPERS
// ============================================================================

// Draw a 3D horizontal ellipse ring where depth z varies with sin(theta)
// Nearly converges at back (theta=270), widens at front (theta=90)
function drawAnaglyphEllipseRing(cx, cy, rx, ry, zCenter, zAmp, weight) {
  let ptsC = [];
  let ptsR = [];
  let backPtsK = [];

  for (let a = 0; a <= 360; a += 8) {
    let z = zCenter + zAmp * sin(a);
    let dx = getDX(z);
    let x = cx + rx * cos(a);
    let y = cy + ry * sin(a);
    ptsC.push([x - dx, y]);
    ptsR.push([x + dx, y]);

    // Back arc where Cyan and Red converge (a in 205..335)
    if (a >= 205 && a <= 335) {
      backPtsK.push([x, y]);
    }
  }

  brush.set("HB", PALETTE.cyanDark, weight);
  brush.spline(ptsC, 0.5);

  brush.set("HB", PALETTE.redDark, weight);
  brush.spline(ptsR, 0.5);

  if (backPtsK.length > 2) {
    brush.set("2B", PALETTE.blackWarmDark, weight * 1.05);
    brush.spline(backPtsK, 0.5);
  }
}

// Draw a slightly curved horizontal contour stroke between x1 and x2 at y
function drawCurvedRow(x1, x2, y, sag) {
  if (x2 <= x1 + 2) return;
  let xm = (x1 + x2) * 0.5;
  brush.spline([
    [x1, y],
    [xm, y + sag],
    [x2, y]
  ], 0.45);
}

function shiftPoly(pts, dx, dy) {
  let out = [];
  for (let i = 0; i < pts.length; i++) {
    out.push([pts[i][0] + dx, pts[i][1] + dy]);
  }
  return out;
}

function drawPolyShape(pts) {
  if (pts.length < 3) return;
  brush.beginShape(0.2);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function drawEllipseShape(cx, cy, rx, ry, steps) {
  brush.beginShape(0.45);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    brush.vertex(cx + cos(a) * rx, cy + sin(a) * ry);
  }
  brush.endShape(true);
}

function drawClosedSpline(pts, curv) {
  if (pts.length < 3) return;
  let closed = pts.slice();
  closed.push(pts[0]);
  closed.push(pts[1]);
  brush.spline(closed, curv);
}

function drawOpenSpline(pts, curv) {
  if (pts.length < 2) return;
  brush.spline(pts, curv);
}

