// ============================================================================
// GEOMETRY & INTERPOLATION HELPERS
// ============================================================================

function evalBezier(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let tt = t * t, uu = u * u;
  let uuu = uu * u, ttt = tt * t;
  return [
    uuu * p0[0] + 3 * uu * t * p1[0] + 3 * u * tt * p2[0] + ttt * p3[0],
    uuu * p0[1] + 3 * uu * t * p1[1] + 3 * u * tt * p2[1] + ttt * p3[1]
  ];
}

function evalBezierTangent(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let dx = 3 * u * u * (p1[0] - p0[0]) + 6 * u * t * (p2[0] - p1[0]) + 3 * t * t * (p3[0] - p2[0]);
  let dy = 3 * u * u * (p1[1] - p0[1]) + 6 * u * t * (p2[1] - p1[1]) + 3 * t * t * (p3[1] - p2[1]);
  let len = Math.hypot(dx, dy) || 1;
  return [dx / len, dy / len];
}

function lerpHex(c1, c2, t) {
  t = constrain(t, 0, 1);
  let r1 = parseInt(c1.slice(1, 3), 16), g1 = parseInt(c1.slice(3, 5), 16), b1 = parseInt(c1.slice(5, 7), 16);
  let r2 = parseInt(c2.slice(1, 3), 16), g2 = parseInt(c2.slice(3, 5), 16), b2 = parseInt(c2.slice(5, 7), 16);
  let r = Math.round(lerp(r1, r2, t));
  let g = Math.round(lerp(g1, g2, t));
  let b = Math.round(lerp(b1, b2, t));
  return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
}

function drawFilledPoly(pts, curvature = 0.35) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(CLOSE);
}

// Anatomical contour functions for the nape and shoulder
function getLeftNeckX(y) {
  if (y < 435) return 506;
  if (y < 615) {
    let t = (y - 435) / 180;
    return evalBezier([506, 435], [528, 495], [538, 560], [516, 615], t)[0];
  }
  if (y < 770) {
    let t = (y - 615) / 155;
    return evalBezier([516, 615], [488, 672], [385, 718], [248, 770], t)[0];
  }
  let t = constrain((y - 770) / 230, 0, 1);
  return evalBezier([248, 770], [165, 808], [128, 885], [118, 1000], t)[0];
}

function getRightNeckX(y) {
  if (y < 485) return 792;
  if (y < 645) {
    let t = (y - 485) / 160;
    return evalBezier([792, 485], [776, 540], [778, 595], [806, 645], t)[0];
  }
  let t = constrain((y - 645) / 245, 0, 1);
  return evalBezier([806, 645], [848, 702], [975, 742], [1105, 890], t)[0];
}

function getSpineX(y) {
  let t = constrain((y - 460) / 480, 0, 1);
  return evalBezier([656, 460], [646, 565], [662, 695], [674, 940], t)[0];
}

