// ============================================================================
// 3. HYPERREAL SKIN MODELING, ANATOMY, LEFT EAR & PEACH FUZZ
// ============================================================================

function drawSkinModelingAndFuzz() {
  // A. Volumetric pastel & colored-pencil cross-contour modeling across the neck and back
  for (let y = 445; y <= 975; y += 3.5) {
    let lx = getLeftNeckX(y);
    let rx = getRightNeckX(y);
    let sx = getSpineX(y);
    let span = rx - lx;

    // Draw 5 overlapping micro-contour segments across the width of the neck/back at height y
    let steps = 7;
    for (let s = 0; s < steps; s++) {
      let u0 = s / steps;
      let u1 = (s + 1.35) / steps;
      let x0 = lerp(lx + 4, rx - 4, u0) + random(-3, 3);
      let x1 = lerp(lx + 4, rx - 4, min(1, u1)) + random(-3, 3);
      let xm = (x0 + x1) * 0.5;

      // Calculate anatomical surface normal / light value across the neck & shoulder
      let normPos = (xm - lx) / span; // 0 = left backlit edge, ~0.48 = spine furrow, 1 = right shadow edge
      let spineDist = (xm - sx) / (span * 0.5);

      // Dip along the central nuchal furrow (spine) and bump on the left cervical muscle / scapula
      let sag = sin(normPos * 180) * 14 + exp(- spineDist * spineDist * 18) * 7;
      let ym = y + sag + random(-2, 2);

      let col;
      let bName = random() < 0.45 ? "velvet_pastel" : "cpencil";
      let wt = bName === "velvet_pastel" ? random(0.55, 1.15) : random(0.45, 0.9);

      if (normPos < 0.09) {
        // Backlit rim highlight (buttercream + warm talc)
        col = lerpHex("#fdf7eb", "#f3decb", normPos / 0.09);
      } else if (normPos < 0.36) {
        // Luminous buttercream to rose-blush highlight on left neck & shoulder dome
        let localT = (normPos - 0.09) / 0.27;
        col = lerpHex("#fbf1df", "#e6b8aa", localT);
      } else if (normPos < 0.54) {
        // Transition into central nuchal groove (rose-blush to soft lilac-rose)
        let localT = (normPos - 0.36) / 0.18;
        col = lerpHex("#e0afa2", "#b397a2", localT);
      } else if (normPos < 0.82) {
        // Lilac-mauve core shadow on right side of neck & right scapula
        let localT = (normPos - 0.54) / 0.28;
        col = lerpHex("#a88e9b", "#826d7a", localT);
      } else {
        // Warm earth-umber reflected light along right margin
        let localT = (normPos - 0.82) / 0.18;
        col = lerpHex("#856f79", "#9e7f70", localT);
      }

      // Darken slightly directly beneath the hairline (y < 515)
      if (y < 515) {
        col = lerpHex(col, "#78626e", map(y, 445, 515, 0.55, 0));
      }

      brush.set(bName, col, wt);
      brush.spline([[x0, y], [xm, ym], [x1, y + random(-3, 3)]], 0.45);
    }
  }

  // B. Fine diagonal skin pore / dermatoglyphic cross-hatching in 2H and cpencil
  for (let i = 0; i < 650; i++) {
    let y = random(455, 955);
    let lx = getLeftNeckX(y);
    let rx = getRightNeckX(y);
    let u = random(0.03, 0.96);
    let x = lerp(lx, rx, u);

    let len = random(14, 34);
    let ang = u < 0.5 ? random(18, 48) : random(-48, -18);
    let dx = cos(ang) * len;
    let dy = sin(ang) * len;

    let col;
    if (u < 0.35) col = random(["#f9EFE0", "#edd0c2", "#e2b4a6"]);
    else if (u < 0.58) col = random(["#d4a094", "#be969e", "#c99e95"]);
    else col = random(["#9a828f", "#7e6875", "#8f756a"]);

    brush.set("2H", col, random(0.3, 0.65));
    brush.spline([
      [x - dx * 0.5, y - dy * 0.5],
      [x + random(-2, 2), y + 3],
      [x + dx * 0.5, y + dy * 0.5]
    ], 0.35);
  }

  // C. Accentuate the nuchal furrow (central spine line) and C7 vertebra prominens at (660, 705)
  for (let i = 0; i < 65; i++) {
    let y = random(475, 860);
    let sx = getSpineX(y);
    // Soft lilac-rose shadow inside the furrow
    brush.set("cpencil", random(["#a68b96", "#947a86", "#bc9ca4"]), random(0.4, 0.8));
    brush.spline([
      [sx - random(8, 22), y - random(4, 10)],
      [sx + random(-3, 3), y + random(2, 6)],
      [sx + random(10, 24), y - random(2, 8)]
    ], 0.45);
  }
  // Subtle buttercream catchlight on the C7 vertebra prominence & left scapular ridge
  for (let i = 0; i < 45; i++) {
    let cx = random(632, 658) + random(-8, 8);
    let cy = random(685, 725) + random(-6, 6);
    brush.set("cpencil", "#fbf2e2", random(0.45, 0.85));
    brush.spline([[cx - 12, cy - 3], [cx, cy + 2], [cx + 12, cy - 1]], 0.4);
  }

  // D. Hyperreal Left Ear (seen from behind, x: 468..515, y: 355..450)
  // Retroauricular crease (deep warm rose-umber line where ear attaches to skull)
  for (let i = 0; i < 28; i++) {
    let ox = random(-2, 2);
    brush.set("cpencil", i < 16 ? "#9e6d68" : "#755154", random(0.45, 0.85));
    brush.spline([
      [504 + ox, 365],
      [500 + ox, 395],
      [498 + ox, 422],
      [492 + ox, 442]
    ], 0.45);
  }
  // Glowing rose-blush & carmine translucency on the outer helix and earlobe
  for (let i = 0; i < 45; i++) {
    let t = i / 45;
    let hx = lerp(471, 498, t);
    let col = t < 0.3 ? "#fdf4e4" : (t < 0.7 ? "#e39e93" : "#c77e78");
    brush.set("cpencil", col, random(0.4, 0.8));
    brush.spline([
      [hx, 360 + t * 8],
      [hx - 5, 392],
      [hx - 2, 424],
      [hx + 6, 444 - t * 4]
    ], 0.5);
  }
  // Baroque Pearl Drop Earring hanging from the left lobe at (488, 462)
  brush.noStroke();
  brush.fillBleed(0.08, "in");
  brush.fill("#d8cfc8", 210);
  brush.circle(486, 464, 9, 0.15);
  brush.fill("#fbf6ec", 230);
  brush.circle(483, 461, 4.5, 0.1);
  // Gold wire & tiny rose-gold shadow on pearl
  brush.set("fine_hair", "#b89352", 0.75);
  brush.line(490, 443, 487, 455);
  brush.set("cpencil", "#7d6870", 0.55);
  brush.arc(486, 464, 9, 15, 165);
  brush.set("fine_hair", "#ffffff", 0.85);
  brush.line(481, 459, 483, 462);

  // E. Soft spray pastel bloom across skin transitions
  for (let i = 0; i < 85; i++) {
    let y = random(465, 920);
    let lx = getLeftNeckX(y);
    let rx = getRightNeckX(y);
    let u = random(0.05, 0.92);
    let x = lerp(lx, rx, u);
    let col = u < 0.42 ? "#fcf3e3" : (u < 0.65 ? "#e3b3a6" : "#9c8491");
    brush.set("talc_stipple", col, random(0.7, 1.4));
    brush.line(x, y, x + random(-18, 18), y + random(-12, 12));
  }

  // F. HYPERREAL PEACH FUZZ (Vellus Hair) catching the raking light
  // 1. Along the backlit left contour of the neck and trapezius slope
  for (let y = 442; y <= 845; y += 1.6) {
    let cx = getLeftNeckX(y);
    let dy = 4;
    let dx = getLeftNeckX(y + dy) - cx;
    let normAng = atan2(dy, dx) + 90; // outward normal pointing left/up-left

    // Fine vellus hairs protruding 5-15px into the backlit halo
    let len = random(6, 15) * (y > 620 && y < 760 ? 1.25 : 0.95);
    let fuzzAng = normAng + random(-22, 18);
    let x0 = cx + random(-2, 4);
    let y0 = y + random(-1.5, 1.5);
    let x1 = x0 + cos(fuzzAng) * len;
    let y1 = y0 + sin(fuzzAng) * len;

    let col = random() < 0.7 ? "#fdf7ea" : "#f5e3cf";
    brush.set("fine_hair", col, random(0.26, 0.48));
    brush.spline([
      [x0, y0],
      [(x0 + x1) * 0.5 + random(-1, 1), (y0 + y1) * 0.5 - 1.5],
      [x1, y1]
    ], 0.35);
  }

  // 2. Surface peach fuzz across the illuminated left cheek/nape swell and shoulder dome
  for (let i = 0; i < 380; i++) {
    let y = random(455, 860);
    let lx = getLeftNeckX(y);
    let rx = getRightNeckX(y);
    // Concentrate vellus hair where raking light grazes the skin (left 45% of neck/shoulder)
    let u = Math.pow(random(), 1.6) * 0.52;
    let x = lerp(lx + 3, rx, u);
    let len = random(6, 14);
    // Vellus hair streams gently downward and outward toward the shoulder
    let ang = lerp(145, 105, u) + random(-14, 14);
    let col = u < 0.25 ? "#fef9ef" : "#f6e5d4";
    brush.set("fine_hair", col, random(0.22, 0.4));
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
}

