function drawChemiseEdge() {
  // Sweeping asymmetric C-scroll neckline of the chemise low on the back
  let p0 = [110, 940], p1 = [360, 1065], p2 = [760, 1055], p3 = [1115, 875];

  brush.noStroke();
  brush.fillBleed(0.2, "out");
  brush.fill("#e8dfd2", 160);
  let chemisePoly = [];
  for (let t = 0; t <= 1.01; t += 0.08) {
    chemisePoly.push(evalBezier(p0, p1, p2, p3, t));
  }
  chemisePoly.push([1140, 1040], [720, 1150], [280, 1140], [95, 1040]);
  drawFilledPoly(chemisePoly, 0.35);

  // Soft lilac-umber shadow cast by the chemise fold and lace froth
  for (let i = 0; i < 90; i++) {
    let t = i / 90;
    let pt = evalBezier(p0, p1, p2, p3, t);
    let tan = evalBezierTangent(p0, p1, p2, p3, t);
    let nx = -tan[1], ny = tan[0];

    // Delicate ruffled lace loops along the top edge of the chemise
    let ruffleR = random(8, 18);
    let rx = pt[0] + nx * random(-6, 6);
    let ry = pt[1] + ny * random(-6, 6);

    brush.set("cpencil", t < 0.55 ? "#fbf4e6" : "#d8ccb8", random(0.45, 0.85));
    brush.arc(rx, ry, ruffleR, 190, 350);

    // Tiny gather pleats descending into the silk
    let foldLen = random(25, 65);
    brush.set("velvet_pastel", t < 0.5 ? "#f5ecdc" : "#b8a89a", random(0.6, 1.2));
    brush.spline([
      [pt[0], pt[1]],
      [pt[0] - nx * foldLen * 0.5 + random(-6, 6), pt[1] - ny * foldLen * 0.5 + 12],
      [pt[0] - nx * foldLen, pt[1] - ny * foldLen + 25]
    ], 0.4);
  }
}

// ============================================================================
// 5. POWDERED CURLS IN ASYMMETRIC C-SCROLLS & ESCAPING TENDRILS
// ============================================================================

function drawCurlScroll(ctrlPts, wStart, wEnd, darkCol, midCol, lightCol, talcCol, strandCount) {
  let [p0, p1, p2, p3] = ctrlPts;

  // 1. Soft pastel base mass along the C-scroll lock
  for (let i = 0; i < 18; i++) {
    let v = map(i, 0, 17, -0.45, 0.45);
    let pts = [];
    for (let s = 0; s <= 10; s++) {
      let t = s / 10;
      let c = evalBezier(p0, p1, p2, p3, t);
      let tan = evalBezierTangent(p0, p1, p2, p3, t);
      let nx = -tan[1], ny = tan[0];
      let w = lerp(wStart, wEnd, sin(t * 150) * 0.35 + (1 - t * 0.35));
      pts.push([c[0] + nx * v * w, c[1] + ny * v * w]);
    }
    let col = v > 0.15 ? darkCol : (v < -0.1 ? lightCol : midCol);
    brush.set("velvet_pastel", col, random(0.9, 1.6));
    brush.spline(pts, 0.5);
  }

  // 2. Hundreds of individual flowing hair strands with specular C-scroll crests
  for (let i = 0; i < strandCount; i++) {
    let v = random(-0.5, 0.5);
    let wavePhase = random(360);
    let waveAmp = random(1.5, 5.5);
    let tStart = random(0, 0.12);
    let tEnd = random(0.88, 1.0);

    let pts = [];
    let steps = 9;
    for (let s = 0; s <= steps; s++) {
      let t = lerp(tStart, tEnd, s / steps);
      let c = evalBezier(p0, p1, p2, p3, t);
      let tan = evalBezierTangent(p0, p1, p2, p3, t);
      let nx = -tan[1], ny = tan[0];
      let w = lerp(wStart, wEnd, t) * sin(constrain(t * 165 + 10, 15, 170));
      let offset = v * w + sin(t * 240 + wavePhase) * waveAmp;
      pts.push([c[0] + nx * offset, c[1] + ny * offset]);
    }

    // Color across the lock's cylinder + longitudinal specular highlight at crest (t ~ 0.35..0.65)
    let col;
    if (v > 0.25) {
      col = lerpHex(midCol, darkCol, map(v, 0.25, 0.5, 0, 1));
    } else if (v < -0.12 && v > -0.38) {
      col = random() < 0.55 ? talcCol : lightCol;
    } else {
      col = lerpHex(lightCol, midCol, abs(v) * 1.8);
    }

    let bName = random() < 0.65 ? "fine_hair" : "cpencil";
    let wt = bName === "fine_hair" ? random(0.35, 0.75) : random(0.35, 0.65);
    brush.set(bName, col, wt);
    brush.spline(pts, 0.5);
  }

  // 3. Extra bright powdered talc highlights on the C-scroll turn
  for (let i = 0; i < Math.floor(strandCount * 0.22); i++) {
    let v = random(-0.32, -0.05);
    let t0 = random(0.22, 0.45);
    let t1 = t0 + random(0.22, 0.38);
    let pts = [];
    for (let s = 0; s <= 5; s++) {
      let t = lerp(t0, t1, s / 5);
      let c = evalBezier(p0, p1, p2, p3, t);
      let tan = evalBezierTangent(p0, p1, p2, p3, t);
      let nx = -tan[1], ny = tan[0];
      let w = lerp(wStart, wEnd, t);
      pts.push([c[0] + nx * v * w, c[1] + ny * v * w]);
    }
    brush.set("fine_hair", talcCol, random(0.4, 0.8));
    brush.spline(pts, 0.5);
  }
}

