// ============================================================================
// 6. PALE CELADON / PISTACHIO SILK RIBBON (LOOPING & TRAILING OFF TOP EDGE)
// ============================================================================

function drawSilkRibbonPiece(leftCurve, rightCurve, lightFunc, castShadowOffset = null) {
  let [l0, l1, l2, l3] = leftCurve;
  let [r0, r1, r2, r3] = rightCurve;

  // 1. Optional soft shadow cast onto the powdered hair or background beneath the ribbon
  if (castShadowOffset) {
    let sx = castShadowOffset[0], sy = castShadowOffset[1];
    let shadowPoly = [];
    for (let s = 0; s <= 10; s++) {
      let p = evalBezier(l0, l1, l2, l3, s / 10);
      shadowPoly.push([p[0] + sx, p[1] + sy]);
    }
    for (let s = 10; s >= 0; s--) {
      let p = evalBezier(r0, r1, r2, r3, s / 10);
      shadowPoly.push([p[0] + sx, p[1] + sy]);
    }
    brush.noStroke();
    brush.fillBleed(0.25, "out");
    brush.fill("#5e534e", 85);
    drawFilledPoly(shadowPoly, 0.35);
  }

  // 2. Watercolor base wash of pale celadon / pistachio silk
  let ribbonPoly = [];
  for (let s = 0; s <= 12; s++) ribbonPoly.push(evalBezier(l0, l1, l2, l3, s / 12));
  for (let s = 12; s >= 0; s--) ribbonPoly.push(evalBezier(r0, r1, r2, r3, s / 12));

  brush.noStroke();
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.28, 0.15);
  brush.fill("#b8c8b2", 185);
  drawFilledPoly(ribbonPoly, 0.3);

  // 3. Longitudinal silk warp threads (smooth tonal transitions from moss-shadow to buttercream-celadon sheen)
  let warpCount = 38;
  for (let i = 0; i <= warpCount; i++) {
    let u = i / warpCount;
    let subSegs = 6;
    for (let seg = 0; seg < subSegs; seg++) {
      let t0 = seg / subSegs;
      let t1 = (seg + 1.05) / subSegs;
      let tm = (t0 + t1) * 0.5;

      let pL0 = evalBezier(l0, l1, l2, l3, t0), pR0 = evalBezier(r0, r1, r2, r3, t0);
      let pLm = evalBezier(l0, l1, l2, l3, tm), pRm = evalBezier(r0, r1, r2, r3, tm);
      let pL1 = evalBezier(l0, l1, l2, l3, min(1, t1)), pR1 = evalBezier(r0, r1, r2, r3, min(1, t1));

      let pt0 = [lerp(pL0[0], pR0[0], u), lerp(pL0[1], pR0[1], u)];
      let ptm = [lerp(pLm[0], pRm[0], u), lerp(pLm[1], pRm[1], u)];
      let pt1 = [lerp(pL1[0], pR1[0], u), lerp(pL1[1], pR1[1], u)];

      // Evaluate silk specular reflection (0 = deep crease shadow, 0.5 = pistachio midtone, 1 = crisp sheen)
      let lum = lightFunc(tm, u);
      let col;
      if (lum < 0.35) {
        col = lerpHex("#5b6b56", "#8ea188", lum / 0.35);
      } else if (lum < 0.72) {
        col = lerpHex("#8ea188", "#c8d6c2", (lum - 0.35) / 0.37);
      } else {
        col = lerpHex("#c8d6c2", "#f6f9f0", (lum - 0.72) / 0.28);
      }

      brush.set("silk_filament", col, random(0.65, 1.15));
      brush.spline([pt0, ptm, pt1], 0.4);
    }
  }

  // 4. Transverse taffeta weave lines (hyperreal woven silk sheen catching light across the folds)
  let weftSteps = 82;
  for (let s = 0; s <= weftSteps; s++) {
    let t = s / weftSteps;
    let pL = evalBezier(l0, l1, l2, l3, t);
    let pR = evalBezier(r0, r1, r2, r3, t);
    let xm = (pL[0] + pR[0]) * 0.5 + random(-1.5, 1.5);
    let ym = (pL[1] + pR[1]) * 0.5 + random(-1.5, 1.5);

    let lum = lightFunc(t, 0.5);
    let col;
    if (lum > 0.74) {
      col = random() < 0.65 ? "#fbfcf5" : "#e5efe0";
    } else if (lum < 0.32) {
      col = "#54634f";
    } else {
      col = random(["#a7b8a1", "#bfd0b9", "#8d9f87"]);
    }

    let bName = lum > 0.74 ? "fine_hair" : "2H";
    brush.set(bName, col, lum > 0.74 ? random(0.45, 0.8) : random(0.3, 0.55));
    brush.spline([pL, [xm, ym], pR], 0.25);

    // Extra intense specular flash right at the fold crest for hyperreal taffeta reflection
    if (lum > 0.82) {
      let uA = 0.15, uB = 0.85;
      let fA = [lerp(pL[0], pR[0], uA), lerp(pL[1], pR[1], uA)];
      let fB = [lerp(pL[0], pR[0], uB), lerp(pL[1], pR[1], uB)];
      brush.set("fine_hair", "#ffffff", random(0.5, 0.85));
      brush.line(fA[0], fA[1], fB[0], fB[1]);
    }
  }

  // 5. Crisp woven selvedge border along both edges of the silk ribbon
  for (let side of [leftCurve, rightCurve]) {
    let [s0, s1, s2, s3] = side;
    let edgePts = [];
    for (let k = 0; k <= 14; k++) edgePts.push(evalBezier(s0, s1, s2, s3, k / 14));
    brush.set("2H", "#63735e", 0.55);
    brush.spline(edgePts, 0.45);

    // Inner bright picot / selvedge highlight line 2.5px inside the border
    let innerPts = [];
    for (let k = 0; k <= 14; k++) {
      let t = k / 14;
      let pL = evalBezier(l0, l1, l2, l3, t);
      let pR = evalBezier(r0, r1, r2, r3, t);
      let u = side === leftCurve ? 0.06 : 0.94;
      innerPts.push([lerp(pL[0], pR[0], u), lerp(pL[1], pR[1], u)]);
    }
    brush.set("fine_hair", "#eef5ea", 0.5);
    brush.spline(innerPts, 0.45);
  }
}

function drawCeladonSilkRibbon() {
  // 1. Secondary Trailing Streamer (rising from behind the right curls and trailing off the top edge at x ~ 915..965)
  drawSilkRibbonPiece(
    [[745, 225], [805, 145], [845, 70], [912, -18]],
    [[792, 240], [852, 160], [898, 78], [964, -18]],
    (t, u) => {
      let foldWave = 0.5 + 0.42 * sin(t * 340 - 40) + 0.15 * cos(u * 180);
      return constrain(foldWave, 0.1, 0.96);
    },
    [10, 12]
  );

  // 2. Lower Ribbon Anchor (tucked into the C-scroll curls near the central hairpin)
  drawSilkRibbonPiece(
    [[618, 355], [635, 305], [662, 272], [688, 245]],
    [[662, 372], [678, 318], [702, 282], [718, 255]],
    (t, u) => {
      let crease = sin(t * 210) * 0.5 + 0.35 - abs(u - 0.45) * 0.4;
      return constrain(crease, 0.12, 0.92);
    },
    [8, 10]
  );

  // 3. Left Asymmetric Bow Loop (sweeping out toward upper-left in a lush Rococo curve)
  // Underside of left loop (darker moss-celadon interior)
  drawSilkRibbonPiece(
    [[522, 165], [555, 118], [635, 155], [692, 232]],
    [[548, 205], [582, 155], [652, 185], [705, 248]],
    (t, u) => constrain(0.22 + 0.35 * sin(t * 180) + (1 - u) * 0.18, 0.1, 0.72),
    [12, 14]
  );
  // Front/upper side of left loop (catching bright buttercream-celadon light at the turn)
  drawSilkRibbonPiece(
    [[688, 238], [605, 248], [515, 225], [522, 165]],
    [[702, 268], [618, 292], [532, 265], [548, 205]],
    (t, u) => {
      let highlight = 0.45 + 0.5 * sin(t * 200 - 15) - abs(u - 0.35) * 0.25;
      return constrain(highlight, 0.18, 0.98);
    },
    [9, 12]
  );

  // 4. Right Asymmetric Bow Loop (curving out over the upper-right curls)
  // Underside of right loop
  drawSilkRibbonPiece(
    [[708, 235], [795, 185], [888, 195], [902, 248]],
    [[722, 258], [805, 222], [872, 232], [878, 278]],
    (t, u) => constrain(0.2 + 0.32 * sin(t * 180), 0.12, 0.68),
    [10, 14]
  );
  // Front folded face of right loop
  drawSilkRibbonPiece(
    [[705, 252], [785, 298], [885, 305], [902, 248]],
    [[718, 228], [795, 255], [868, 265], [878, 278]],
    (t, u) => {
      let sheen = 0.42 + 0.52 * sin(t * 220 + 10) + (1 - u) * 0.15;
      return constrain(sheen, 0.15, 0.96);
    },
    [8, 11]
  );

  // 5. MAIN GRAND TRAILING STREAMER (undulating upward in an S/C-scroll and trailing right off the top edge at y = -18)
  drawSilkRibbonPiece(
    [[678, 232], [612, 145], [648, 62], [728, -18]],
    [[726, 238], [674, 152], [716, 68], [796, -18]],
    (t, u) => {
      // Crisp double taffeta fold catching brilliant celadon-buttercream light at t ~ 0.28 and t ~ 0.78
      let wave = 0.52 + 0.46 * sin(t * 420 - 35) - abs(u - 0.42) * 0.22;
      return constrain(wave, 0.12, 0.99);
    },
    [14, 12]
  );

  // 6. Central Gathered Silk Knot at (682..732, 218..268)
  drawSilkRibbonPiece(
    [[672, 224], [695, 212], [722, 218], [734, 242]],
    [[676, 262], [698, 272], [724, 266], [732, 252]],
    (t, u) => {
      // Deeply pinched gather folds in the knot
      let gather = 0.48 + 0.48 * sin(u * 540 + t * 180);
      return constrain(gather, 0.1, 0.98);
    },
    [5, 7]
  );

  // Sharp crease accents & micro-highlights inside the silk knot and fold turns
  for (let i = 0; i < 24; i++) {
    let y = lerp(222, 265, i / 24);
    let x0 = 676 + sin(i * 35) * 4;
    let x1 = 730 + cos(i * 35) * 4;
    let isCrest = i % 4 === 0;
    brush.set("fine_hair", isCrest ? "#fafdf6" : "#4a5946", isCrest ? 0.65 : 0.5);
    brush.spline([[x0, y], [(x0 + x1) * 0.5, y + sin(i * 50) * 5], [x1, y]], 0.4);
  }
}

