// 7. LOOSE TALC POWDER, MICRO-DETAILS & UNSEEN GILT CARTOUCHE VIGNETTE
// ============================================================================

function drawTalcAndFinalTouches() {
  // A. Loose Talc Powder dusting the coiffure and drifting onto the nape & left shoulder
  // 1. Stippled spray cloud of talc
  for (let i = 0; i < 210; i++) {
    let zone = random();
    let x, y, col;
    if (zone < 0.55) {
      // Over the powdered curls and hairline
      x = random(490, 860);
      y = random(165, 495);
      col = random(["#fcf9f2", "#f4ede2", "#e8dfd3"]);
    } else if (zone < 0.85) {
      // Drifting down onto the upper nape and illuminated left trapezius / shoulder dome
      y = random(460, 860);
      let lx = getLeftNeckX(y);
      let rx = getRightNeckX(y);
      x = lerp(lx + 6, rx - 20, Math.pow(random(), 1.4) * 0.75);
      col = random(["#fdf8ec", "#f7efe0", "#efe3d5"]);
    } else {
      // Floating talc motes in the backlit air beside the left neck & curls
      x = random(280, 520);
      y = random(320, 760);
      col = "#fbf5e8";
    }
    brush.set("talc_stipple", col, random(0.45, 1.15));
    brush.line(x, y, x + random(-14, 14), y + random(-10, 10));
  }

  // 2. Pinpoint individual talc grains (hyperreal chalk/powder specks on skin and hair)
  for (let i = 0; i < 340; i++) {
    let x, y;
    if (random() < 0.6) {
      // On the nape and left shoulder dome
      y = random(445, 840);
      let lx = getLeftNeckX(y);
      let rx = getRightNeckX(y);
      x = lerp(lx + 3, rx - 15, random(0.02, 0.72));
    } else {
      // On the curls
      x = random(495, 855);
      y = random(180, 485);
    }
    let col = random(["#ffffff", "#fdf8ed", "#f3eadb"]);
    brush.set("fine_hair", col, random(0.35, 0.75));
    brush.line(x, y, x + random(0.8, 2.2), y + random(-0.8, 1.2));
  }

  // B. Unseen Gilt Cartouche Framing (whispered C-scroll arabesques in muted earth & antique gold)
  let cartoucheScrolls = [
    // Left sweeping C-scroll cradling the backlit shoulder and neck
    [[290, 80], [115, 240], [85, 530], [210, 720]],
    [[185, 580], [65, 760], [95, 995], [340, 1095]],
    // Lower-right C-scroll cradling the lower back
    [[310, 1085], [640, 1165], [990, 1085], [1125, 845]],
    // Upper-right C-scroll framing the ribbon and curls
    [[965, 65], [1125, 235], [1145, 525], [1035, 745]]
  ];

  for (let sc of cartoucheScrolls) {
    let [p0, p1, p2, p3] = sc;
    // Soft muted-earth & antique-gilt chalk strokes
    for (let i = 0; i < 28; i++) {
      let offset = random(-28, 28);
      let t0 = random(0, 0.35);
      let t1 = t0 + random(0.35, 0.62);
      let pts = [];
      for (let s = 0; s <= 6; s++) {
        let t = lerp(t0, t1, s / 6);
        let c = evalBezier(p0, p1, p2, p3, t);
        let tan = evalBezierTangent(p0, p1, p2, p3, t);
        let nx = -tan[1], ny = tan[0];
        pts.push([c[0] + nx * offset, c[1] + ny * offset]);
      }
      let isGold = random() < 0.42;
      let col = isGold
        ? random(["#c8ad76", "#dcc696", "#b0935d"])
        : random(["#9e8b7b", "#b8a594", "#877567", "#dfd4c4"]);
      let bName = isGold && random() < 0.5 ? "cpencil" : "velvet_pastel";
      brush.set(bName, col, bName === "cpencil" ? random(0.45, 0.9) : random(0.8, 1.8));
      brush.spline(pts, 0.5);
    }
  }
}

