function draw() {
  translate(-width / 2, -height / 2);

  // 1. Cream Paint-by-Numbers Cardboard Ground
  drawCreamCardGround();

  // 2. Construct Feature-Snapped Topological Grid (200 x 200 micro-cells)
  const NX = 200;
