}

// ============================================================================
// 1. CREAM ILLUSTRATION BOARD GROUND
// ============================================================================
function drawCreamCardGround() {
  background("#f4ede0");
  brush.noField();
  brush.noStroke();

  // Subtle warm vintage board tonal variations
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.35, 0.15);
  brush.fill("#efe5d2", 42);
  brush.rect(0, 0, 1200, 1200, "corner");

  brush.fill("#eadfc9", 28);
  brush.circle(850, 880, 420, 0.2);
  brush.circle(260, 960, 360, 0.2);
  brush.noFill();

  // Fine matte card tooth across the bare lower-right board
  brush.set("2H", "#e5dac3", 0.35);
  for (let i = 0; i < 160; i++) {
    let x1 = random(0, 1200);
    let y1 = random(200, 1200);
    if (y1 > getCutLineY(x1) - 40) {
      let len = random(18, 65);
      brush.line(x1, y1, x1 + len, y1 + random(-1.5, 1.5));
    }
  }
}

// The straight boundary between finished and blank cuts straight across the headlamp (435, 565)
function getCutLineY(x) {
  return 760 - 0.448275 * x;
}

// ============================================================================
// 2. HYPERREALIST TRUCK SCENE EVALUATOR & FEATURE-SNAPPED MESH BUILDER
// ============================================================================
function fbm(x, y, octaves = 4) {
  let v = 0;
  let amp = 0.5;
  let freq = 1;
  for (let i = 0; i < octaves; i++) {
    v += amp * noise(x * freq, y * freq);
    freq *= 2.07;
    amp *= 0.5;
  }
  return v;
}

function evaluateBugSpatter(x, y) {
  for (let i = 0; i < BUG_SPATTERS.length; i++) {
    let b = BUG_SPATTERS[i];
    let dx = x - b.x;
    let dy = y - b.y;
    let d = Math.hypot(dx, dy);
    if (d > b.r * 1.65) continue;

    let ang = Math.atan2(dy, dx);
    // Directional splatter lobes & wind-streaked rays
    let rayNoise = noise(b.seed + Math.cos(ang) * 2.8, b.seed + Math.sin(ang) * 2.8);
    let fineRays = Math.pow(Math.abs(Math.sin(ang * 5 + b.seed)), 1.6) * 0.38;
    let windStretch = 1.0 + 0.42 * ((dx * b.dx + dy * b.dy) / (d + 1));
    let effR = b.r * (0.55 + 0.65 * rayNoise + fineRays) * windStretch;

    // Satellite droplets along wind direction
    let satD = Math.hypot(dx - b.dx * b.r * 1.15, dy - b.dy * b.r * 1.15);
    if (satD < 4.5) {
      return { pal: (i % 2 === 0) ? 28 : 18, maxArea: 3, isBug: true };
    }

    if (d < effR) {
      if (d < b.coreR * (0.75 + 0.4 * rayNoise)) {
        // Crushed chitin thorax & bright wing-scale highlight speck
        if (dx < -1.5 && dy < -1.5 && d < b.coreR * 0.55) {
          return { pal: 27, maxArea: 3, isBug: true };
        }
        return { pal: (d < b.coreR * 0.5) ? 1 : 18, maxArea: 4, isBug: true };
      } else if (d < effR * 0.68) {
        // Vivid amber/yellow haemolymph ring
        let n2 = noise(x * 0.12 + b.seed, y * 0.12);
        return { pal: (n2 > 0.52) ? 27 : 28, maxArea: 5, isBug: true };
      } else {
        // Outer dried amber-rust crust
        return { pal: (rayNoise > 0.5) ? 23 : 20, maxArea: 6, isBug: true };
      }
    }
  }
  return null;
}

function evaluateRustIntensity(x, y) {
  let wx = x + 28 * (fbm(x * 0.008, y * 0.008, 3) - 0.5);
  let wy = y + 28 * (fbm(x * 0.008 + 31, y * 0.008 + 17, 3) - 0.5);
  let n = fbm(wx * 0.018, wy * 0.018, 4);
  let detail = fbm(x * 0.055 + 90, y * 0.055 + 40, 3);

  let mask = 0;

  // 1. Hood lip & headlamp brow rust bloom (y ~ 170..275, x ~ 180..720)
  let hoodSeamY = 226 + 14 * Math.sin((x - 100) * 0.0032);
  let dSeam = Math.abs(y - hoodSeamY);
  if (x > 140 && x < 760 && dSeam < 68) {
    let browBoost = (x > 290 && x < 610) ? 1.25 : 0.85;
    mask = Math.max(mask, browBoost * Math.pow(1 - dSeam / 68, 0.75));
  }

  // 2. Left fender blistered rust patch (x ~ 0..175, y ~ 340..680)
  let dLeft = Math.hypot((x - 75) * 0.85, (y - 495) * 0.55);
  if (dLeft < 135) {
    mask = Math.max(mask, 1.22 * Math.pow(1 - dLeft / 135, 0.7));
  }

  // 3. Fender-to-grille pinch seam rust (x ~ 685..748, y ~ 390..720)
  let dPinch = Math.hypot((x - 722) * 1.4, (y - 545) * 0.55);
  if (dPinch < 85) {
    mask = Math.max(mask, 1.15 * (1 - dPinch / 85));
  }

  // 4. Lower valance & apron rust rot (in the blank half: x ~ 140..720, y ~ 825..1025)
  let dLow = Math.hypot((x - 560) * 0.5, (y - 875) * 0.9);
  if (dLow < 110) {
    mask = Math.max(mask, 1.2 * Math.pow(1 - dLow / 110, 0.75));
  }
  let dLowLeft = Math.hypot((x - 210) * 0.7, (y - 960) * 0.9);
  if (dLowLeft < 95) {
    mask = Math.max(mask, 1.15 * (1 - dLowLeft / 95));
  }

  return mask * (0.55 * n + 0.45 * detail);
}

function sampleTruckScene(x, y) {
  // Check bug spatters first (on glass, bezel, and leading grille bar)
  let dx = x - HX;
  let dy = y - HY;
  let r = Math.hypot(dx, dy);
  let ang = Math.atan2(dy, dx) * (180 / Math.PI); // -180..180

  if (r < R_BEZEL_OUT || (x > 740 && y > 310 && y < 460)) {
    let bug = evaluateBugSpatter(x, y);
    if (bug) return bug;
  }

  // -------------------------------------------------------------------------
  // ZONE 1: SEALED-BEAM GLASS HEADLAMP LENS (r < 196)
  // -------------------------------------------------------------------------
  if (r < R_LENS) {
    // Outer thick molded glass prism bevel (182..196)
    if (r >= R_LENS_INNER) {
      let rimT = (r - R_LENS_INNER) / (R_LENS - R_LENS_INNER);
      let ribWave = Math.sin(ang * 12 * (Math.PI / 180));
      if (ang > -155 && ang < -35) {
        return { pal: (rimT < 0.55 || ribWave > 0.3) ? 9 : 7, maxArea: 10 };
      } else if (ang >= -35 && ang < 55) {
        return { pal: (rimT > 0.6) ? 2 : (ribWave > 0 ? 6 : 4), maxArea: 10 };
      } else if (ang >= 55 && ang < 145) {
        return { pal: (rimT < 0.45) ? 8 : (ribWave > 0.2 ? 24 : 5), maxArea: 10 };
      } else {
        return { pal: (rimT > 0.5) ? 1 : 4, maxArea: 10 };
      }
    }

    // Center metallic/glass parabolic bulb shield (r < 48)
    if (r < R_BULB) {
      if (r > 41) {
        // Dark chrome mounting ring around bulb cap
        return { pal: (ang < -30 && ang > -150) ? 7 : 1, maxArea: 8 };
      }
      // Specular crescent glint on upper-left of bulb cap
      let dGlint = Math.hypot(dx + 14, dy + 15);
      if (dGlint < 13) return { pal: 9, maxArea: 6 };
      if (dGlint < 22) return { pal: 7, maxArea: 8 };
      // Dark horizon reflection across center of bulb cap
      if (dy > -5 && dy < 14) return { pal: (dx < 0) ? 1 : 2, maxArea: 8 };
      if (dy >= 14) return { pal: (dy > 26) ? 24 : 25, maxArea: 8 };
      return { pal: 4, maxArea: 8 };
    }

    // Main Fluted Prismatic Lens (48 <= r < 182)
    // Horizontal molded glass structural ribs
    const hRibs = [-118, -58, 0, 58, 118];
    for (let k = 0; k < hRibs.length; k++) {
      let dRib = dy - hRibs[k];
      if (Math.abs(dRib) < 4.2) {
        if (dRib < 0) {
          return { pal: (dx < 40) ? 9 : 7, maxArea: 9 };
        } else {
          return { pal: (Math.abs(dx) < 90) ? 2 : 4, maxArea: 9 };
        }
      }
    }

    // Vertical prismatic glass flutes (width = 22 px)
    let fluteW = 22;
    let u = ((dx + 220) % fluteW) / fluteW; // 0..1 across each vertical flute
    let fluteCol = Math.floor((dx + 220) / fluteW);

    // Macroscopic parabolic reflector light distribution behind the glass
    let skyGlint = Math.hypot((dx + 58) * 0.85, (dy + 68) * 1.05);
    let lowerBounce = Math.hypot((dx - 52) * 0.9, (dy - 72) * 1.0);
    let horizonBand = Math.abs(dy - (12 - 0.12 * dx + 8 * Math.sin(fluteCol * 0.9)));

    // Sharp vertical flute boundary crease
    if (u < 0.16) {
      if (skyGlint < 68) return { pal: 6, maxArea: 8 };
      if (horizonBand < 36) return { pal: 1, maxArea: 9 };
      return { pal: 2, maxArea: 9 };
    }

    // Refracted vertical highlight bar inside each flute (0.16 <= u < 0.52)
    if (u < 0.52) {
      if (skyGlint < 62) return { pal: 9, maxArea: 10 };
      if (skyGlint < 108) return { pal: 8, maxArea: 11 };
      if (horizonBand < 24) return { pal: 3, maxArea: 10 };
      if (lowerBounce < 78) return { pal: (u < 0.34) ? 9 : 7, maxArea: 10 };
      return { pal: (dy < 0) ? 7 : 6, maxArea: 11 };
    }

    // Refracted shadow/midtone half of each flute (0.52 <= u < 1.0)
    if (skyGlint < 52) return { pal: 8, maxArea: 10 };
    if (skyGlint < 95) return { pal: 6, maxArea: 11 };
    if (horizonBand < 28) return { pal: (u > 0.78) ? 1 : 2, maxArea: 10 };
    if (dy > 20 && lowerBounce < 85) {
      return { pal: (u > 0.76) ? 24 : 5, maxArea: 11 };
    }
    return { pal: (dy < 0) ? 4 : 3, maxArea: 11 };
  }

  // -------------------------------------------------------------------------
  // ZONE 2: WIDE SCULPTED CHROME HEADLAMP BEZEL (196 <= r < 286)
  // -------------------------------------------------------------------------
  let bezelOuterR = R_BEZEL_OUT + 6 * Math.cos((ang + 90) * (Math.PI / 180));
  if (r < bezelOuterR) {
    // Check small pitted chrome rust blisters on bezel
    let dPit1 = Math.hypot(x - 342, y - 314);
    let dPit2 = Math.hypot(x - 678, y - 472);
    if (dPit1 < 14 || dPit2 < 12) {
      let dP = Math.min(dPit1, dPit2);
      return { pal: (dP < 5) ? 19 : (dP < 9 ? 21 : 23), maxArea: 5 };
    }

    // Inner retaining ring & deep shadow groove (196..210)
    if (r < R_RIM) {
      if (r < 202.5) {
        return { pal: (ang > -135 && ang < -45) ? 2 : 1, maxArea: 10 };
      }
      if (ang > -150 && ang < -25) return { pal: 9, maxArea: 11 };
      if (ang >= -25 && ang < 65) return { pal: 6, maxArea: 11 };
      if (ang >= 65 && ang < 145) return { pal: 24, maxArea: 11 };
      return { pal: 3, maxArea: 11 };
    }

    // Three recessed bezel mounting screw notches (at ang = -145, -35, 90)
    const screwAngs = [-145, -35, 90];
    for (let s = 0; s < screwAngs.length; s++) {
      let sa = screwAngs[s] * (Math.PI / 180);
      let sx = HX + (bezelOuterR - 10) * Math.cos(sa);
      let sy = HY + (bezelOuterR - 10) * Math.sin(sa);
      if (Math.hypot(x - sx, y - sy) < 9.5) {
        return { pal: (Math.hypot(x - sx, y - sy) < 4.5) ? 1 : 19, maxArea: 4 };
      }
    }

    // Normalized radial coordinate across main chrome bezel (0..1)
    let t = (r - R_RIM) / (bezelOuterR - R_RIM);
    let warp = 0.04 * Math.sin(ang * 3 * (Math.PI / 180));

    // Outer lip reflecting the pale-turquoise fender & dark rubber gasket
    if (t > 0.91) {
      return { pal: (ang > -30 && ang < 150) ? 1 : 10, maxArea: 14 };
    }
    if (t > 0.78) {
      // Turquoise body reflection in the outer curved rim of the chrome bezel!
      if (ang < -20 && ang > -160) return { pal: 14, maxArea: 18 };
      if (ang >= -20 && ang < 50) return { pal: 12, maxArea: 18 };
      return { pal: 11, maxArea: 18 };
    }

    // Upper Bezel (Sky & Sun Reflections + Dramatic Dark Horizon Band)
    if (ang < -10 && ang > -170) {
      // Blazing sun highlight on upper-left bezel crown
      if (ang > -148 && ang < -82 && t > 0.24 && t < 0.66) {
        return { pal: (t > 0.34 && t < 0.54) ? 9 : 8, maxArea: 16 };
      }
      // Crisp sky reflection along crown
      if (t > 0.30 + warp && t < 0.68 + warp) {
        return { pal: (ang > -82 && ang < -35) ? 7 : 6, maxArea: 18 };
      }
      // Inner bevel dark horizon reflection ribbon
      if (t <= 0.30 + warp) {
        return { pal: (t < 0.16) ? 1 : 3, maxArea: 16 };
      }
      return { pal: 5, maxArea: 18 };
    }

    // Left & Right Horizon Transition on Bezel (ang near 0 or 180)
    if (ang >= -10 && ang < 28) {
      if (t > 0.32 && t < 0.58) return { pal: 1, maxArea: 15 };
      if (t <= 0.32) return { pal: 26, maxArea: 15 };
      return { pal: 7, maxArea: 16 };
    }
    if (ang <= -170 || ang > 152) {
      if (t > 0.28 && t < 0.56) return { pal: 1, maxArea: 15 };
      if (t <= 0.28) return { pal: 3, maxArea: 15 };
      return { pal: 25, maxArea: 16 };
    }

    // Lower Bezel (Warm Desert Road Reflection + Secondary Sky Glint)
    if (t < 0.24) return { pal: 2, maxArea: 16 };
    if (t < 0.44) return { pal: (ang > 60 && ang < 120) ? 9 : 8, maxArea: 16 };
    if (t < 0.62) return { pal: (ang > 45 && ang < 135) ? 24 : 25, maxArea: 18 };
    return { pal: 26, maxArea: 18 };
  }

  // -------------------------------------------------------------------------
  // ZONE 3: SLOTTED CHROME GRILLE & SURROUND (x >= 728, y: 252..932)
  // -------------------------------------------------------------------------
  // Curved left boundary of the grille surround molding
  let grilleLeftX = 732 + ((y < 340) ? Math.pow((340 - y) / 88, 2) * 38 : 0)
                        + ((y > 840) ? Math.pow((y - 840) / 92, 2) * 38 : 0);

  if (x >= grilleLeftX && y >= 252 && y <= 932) {
    // Outer dark recessed seam between turquoise fender and chrome grille surround
    if (x < grilleLeftX + 7 || y < 259 || y > 925) {
      return { pal: 1, maxArea: 14 };
    }

    // Inner boundary of the wide chrome grille surround molding
    let cavityLeftX = 808;
    let cavityTopY = 324;
    let cavityBotY = 864;

    let inCavity = (x >= cavityLeftX && y >= cavityTopY && y <= cavityBotY);

    if (!inCavity) {
      // Sculpted Chrome Grille Surround Frame
      // Top horizontal chrome molding (y: 259..324)
      if (y < cavityTopY && x > grilleLeftX + 42) {
        let ty = (y - 259) / (cavityTopY - 259);
        if (ty < 0.22) return { pal: 14, maxArea: 22 }; // Turquoise hood reflection
        if (ty < 0.52) return { pal: (x < 980) ? 9 : 8, maxArea: 22 };
        if (ty < 0.72) return { pal: 1, maxArea: 20 }; // Horizon core
        return { pal: 24, maxArea: 22 };
      }
      // Bottom horizontal chrome molding (y: 864..925)
      if (y > cavityBotY && x > grilleLeftX + 42) {
        let ty = (y - cavityBotY) / (925 - cavityBotY);
        if (ty < 0.28) return { pal: 8, maxArea: 22 };
        if (ty < 0.55) return { pal: 2, maxArea: 20 };
        if (ty < 0.82) return { pal: 25, maxArea: 22 };
        return { pal: 26, maxArea: 22 };
      }
      // Left vertical-curved chrome pillar (x: grilleLeftX+7 .. cavityLeftX)
      let tx = (x - (grilleLeftX + 7)) / (cavityLeftX - (grilleLeftX + 7));
      // Horizon reflection cutting across the vertical pillar around y = 550
      if (Math.abs(y - 545 - tx * 18) < 22) return { pal: 1, maxArea: 16 };
      if (tx < 0.22) return { pal: 13, maxArea: 20 }; // Turquoise fender reflection
      if (tx < 0.54) return { pal: (y < 545) ? ((y < 410) ? 9 : 7) : 24, maxArea: 22 };
      if (tx < 0.78) return { pal: (y < 545) ? 4 : 26, maxArea: 20 };
      return { pal: 2, maxArea: 18 };
    }

    // Inside Grille Cavity (x >= 808, y: 324..864)
    // Vertical Chrome Center Tooth / Strut (x: 1036..1096)
    let inVertTooth = (x >= 1036 && x <= 1096);

    // Three Massive Horizontal Chrome Grille Bars
    const barCenters = [414, 594, 774];
    const barHalfH = 34;
    let activeBar = -1;
    let barLocalY = 0;
    for (let b = 0; b < barCenters.length; b++) {
      if (Math.abs(y - barCenters[b]) <= barHalfH) {
        activeBar = b;
        barLocalY = (y - barCenters[b]) / barHalfH; // -1..+1
        break;
      }
    }

    if (activeBar !== -1) {
      // Stone-chip rust speck on top bar
      if (activeBar === 0 && Math.hypot(x - 948, y - 404) < 10) {
        return { pal: (Math.hypot(x - 948, y - 404) < 5) ? 19 : 21, maxArea: 5 };
      }
      // Boss intersection where horizontal bar crosses vertical chrome tooth
      if (inVertTooth) {
        let vx = (x - 1036) / 60;
        if (Math.abs(barLocalY) < 0.28 && vx > 0.2 && vx < 0.8) {
          return { pal: 21, maxArea: 8 }; // Red/orange recessed emblem detail
        }
        if (barLocalY < -0.3) return { pal: 9, maxArea: 14 };
        if (barLocalY < 0.2) return { pal: (vx < 0.5) ? 7 : 3, maxArea: 14 };
        return { pal: 24, maxArea: 14 };
      }

      // Horizontal Chrome Grille Bar Profile (-1..+1)
      if (barLocalY < -0.78) return { pal: 6, maxArea: 20 };
      if (barLocalY < -0.26) {
        // Upper sky-facing bevel of chrome bar
        return { pal: ((x + activeBar * 70) % 260 < 140) ? 9 : 8, maxArea: 24 };
      }
      if (barLocalY < 0.16) {
        // Central stamped dark horizon/turquoise groove
        return { pal: (barLocalY < -0.04) ? 1 : 12, maxArea: 18 };
      }
      if (barLocalY < 0.64) {
        // Lower warm earth-reflecting bevel of chrome bar
        return { pal: (x < 960) ? 24 : 25, maxArea: 24 };
      }
      return { pal: 26, maxArea: 20 };
    }

    // Vertical tooth between horizontal bars
    if (inVertTooth) {
      let vx = (x - 1036) / 60;
      if (vx < 0.18 || vx > 0.84) return { pal: 2, maxArea: 14 };
      if (vx < 0.48) return { pal: 8, maxArea: 16 };
      if (vx < 0.64) return { pal: 1, maxArea: 14 };
      return { pal: 25, maxArea: 16 };
    }

    // Deep Recessed Dark Radiator Slots Behind Grille!
    // Subtle vertical brass/steel radiator fins + diagonal support brace
    let dBrace = Math.abs((x - 830) * 0.65 - (y - 330) * 0.48);
    if (dBrace < 14) {
      return { pal: (dBrace < 6) ? 3 : 2, maxArea: 18 };
    }
    let finPhase = (x - 808) % 28;
    if (finPhase < 5 && ((y % 54) < 34)) {
      return { pal: 2, maxArea: 24 };
    }
    return { pal: 1, maxArea: 38 };
  }

  // -------------------------------------------------------------------------
  // ZONE 4: LOWER OVAL PARKING LAMP (cx = 435, cy = 946)
  // -------------------------------------------------------------------------
  let pdx = (x - 435) / 1.45;
  let pdy = (y - 946) * 1.15;
  let pr = Math.hypot(pdx, pdy);
  if (pr < 64) {
    if (pr > 58) return { pal: 1, maxArea: 10 }; // Outer gasket
    if (pr > 44) {
      // Chrome oval bezel
      if (pdy < -10) return { pal: (pdx < 0) ? 9 : 7, maxArea: 12 };
      if (pdy < 12) return { pal: 2, maxArea: 12 };
      return { pal: 24, maxArea: 12 };
    }
    // Waffle-patterned amber glass lens inside parking lamp
    let wf = ((Math.floor((x - 350) / 16) + Math.floor((y - 900) / 16)) % 2 === 0);
    if (pr < 16) return { pal: wf ? 27 : 9, maxArea: 8 };
    if (pdy < 0) return { pal: wf ? 23 : 28, maxArea: 10 };
    return { pal: wf ? 28 : 20, maxArea: 10 };
  }

  // -------------------------------------------------------------------------
  // ZONE 5: HEAVY CHROME FRONT BUMPER (y >= 1032)
  // -------------------------------------------------------------------------
  let bumperTopY = 1036 + 10 * Math.sin(x * 0.0026);
  if (y >= bumperTopY) {
    // Recessed dark shadow gap above bumper blade
    if (y < bumperTopY + 12) return { pal: 1, maxArea: 24 };

    // Large carriage bolt at (255, 1122) with weeping rust streak
    let dBolt = Math.hypot(x - 255, y - 1122);
    if (dBolt < 24) {
      if (dBolt > 18) return { pal: 19, maxArea: 8 };
      if (x < 252 && y < 1120) return { pal: 9, maxArea: 8 };
      return { pal: (y < 1122) ? 6 : 25, maxArea: 8 };
    }
    if (Math.abs(x - 255) < 12 && y > 1140) {
      return { pal: 21, maxArea: 12 }; // Rust drip below bumper bolt
    }

    let by = (y - (bumperTopY + 12)) / (1200 - (bumperTopY + 12));
    if (by < 0.16) return { pal: 14, maxArea: 32 }; // Turquoise apron reflection on bumper top lip
    if (by < 0.42) return { pal: (x > 180 && x < 760) ? 9 : 8, maxArea: 36 };
    if (by < 0.58) return { pal: 1, maxArea: 30 }; // Sharp dark horizon core across bumper
    if (by < 0.82) return { pal: (by < 0.70) ? 24 : 25, maxArea: 36 };
    return { pal: 2, maxArea: 34 };
  }

  // -------------------------------------------------------------------------
  // ZONE 6: CHROME HOOD SIDE-TRIM SPEAR (Upper-Left y: 52..92, x: 0..355)
  // -------------------------------------------------------------------------
  let trimY = 72 + 0.035 * x;
  let trimHalfH = (x < 280) ? 17 : Math.max(0, 17 * (1 - (x - 280) / 78));
  if (x < 358 && Math.abs(y - trimY) < trimHalfH) {
    let dyTrim = (y - trimY) / (trimHalfH + 0.01);
    if (Math.abs(dyTrim) > 0.82) return { pal: 10, maxArea: 12 };
    if (dyTrim < -0.15) return { pal: 9, maxArea: 16 };
    if (dyTrim < 0.25) return { pal: 1, maxArea: 14 };
    return { pal: 24, maxArea: 16 };
  }

  // -------------------------------------------------------------------------
  // ZONE 7: WEATHERED PALE-TURQUOISE HOOD, FENDER & RUST BLOOMS
  // -------------------------------------------------------------------------
  // Check heavy rust blooms first!
  let rust = evaluateRustIntensity(x, y);
  let hoodSeamY = 226 + 14 * Math.sin((x - 100) * 0.0032);

  // Deep hood-to-fender recessed gap (y ~ 226)
  if (Math.abs(y - hoodSeamY) < 6.5) {
    return { pal: (rust > 0.42) ? 18 : 1, maxArea: 14 };
  }
  if (Math.abs(y - hoodSeamY) < 12.5) {
    return { pal: (rust > 0.36) ? 19 : 10, maxArea: 16 };
  }

  // Vertical fender-to-apron stamped seam on lower-left (x ~ 142, y > 680)
  if (y > 670 && Math.abs(x - 142) < 5.5) {
    return { pal: 10, maxArea: 16 };
  }

  // Multi-tiered crusty rust bloom palette mapping
  if (rust > 0.62) return { pal: 18, maxArea: 8 };  // Pitted dark iron core
  if (rust > 0.53) return { pal: 19, maxArea: 10 }; // Dark mahogany rust
  if (rust > 0.45) return { pal: 20, maxArea: 12 }; // Burnt umber oxide
  if (rust > 0.38) return { pal: 21, maxArea: 14 }; // Fiery red-orange rust
  if (rust > 0.32) return { pal: 22, maxArea: 15 }; // Bright ochre-orange rust
  if (rust > 0.26) return { pal: 23, maxArea: 16 }; // Weeping saffron rust halo
  if (rust > 0.21) return { pal: 17, maxArea: 22 }; // Oxidized dusty sage patina halo

  // Recessed stamped sheet-metal bowl immediately around the headlamp bezel (286..314)
  if (r >= bezelOuterR && r < R_SOCKET) {
    let st = (r - bezelOuterR) / (R_SOCKET - bezelOuterR);
    if (st < 0.24) return { pal: 10, maxArea: 16 }; // Deep shadow ring around chrome bezel
    if (ang > -145 && ang < -35) {
      return { pal: (st > 0.72) ? 16 : 11, maxArea: 22 };
    }
    if (ang >= 35 && ang < 145) {
      return { pal: (st < 0.65) ? 15 : 12, maxArea: 22 };
    }
    return { pal: 12, maxArea: 22 };
  }

  // Sculpted 3D Lighting across the Pale-Turquoise Hood & Fender
  let patNoise = (fbm(x * 0.012, y * 0.012, 3) - 0.5) * 0.16;

  // Upper Hood (y < hoodSeamY)
  if (y < hoodSeamY) {
    // Sunlit cylindrical crown sweeping across the bulbous 1950s hood
    let crownDist = Math.abs(y - (105 - 0.03 * x)) / 135;
    let horizFalloff = Math.abs(x - 520) / 680;
    let shade = 1.0 - 0.65 * crownDist - 0.35 * horizFalloff + patNoise;

    if (shade > 0.78) return { pal: 16, maxArea: 42 }; // Sun-washed aqua glint
    if (shade > 0.64) return { pal: 15, maxArea: 48 }; // Bleached seafoam
    if (shade > 0.48) return { pal: 14, maxArea: 52 }; // Pale turquoise midtone
    if (shade > 0.34) return { pal: 13, maxArea: 48 }; // Classic pickup turquoise
    if (shade > 0.20) return { pal: 12, maxArea: 42 }; // Rich vintage teal
    return { pal: 11, maxArea: 38 };
  }

  // Main Fender & Lower Valance Apron (y > hoodSeamY)
  // Upper fender eyebrow ridge catching sky light around r ~ 314..385
  let browHighlight = (r >= R_SOCKET && r < 395 && ang > -155 && ang < -25)
    ? (1 - (r - R_SOCKET) / 81) * 0.42
    : 0;
  let verticalGrad = 1.0 - (y - 240) / 860;
  let leftCurvature = (x < 180) ? -0.28 * Math.pow((180 - x) / 180, 1.4) : 0;
  let valleyShadow = (x > 650 && x < 745 && y > 320 && y < 780) ? -0.32 : 0;

  let bodyLight = 0.42 + 0.45 * verticalGrad + browHighlight + leftCurvature + valleyShadow + patNoise;

  if (bodyLight > 0.80) return { pal: 16, maxArea: 38 };
  if (bodyLight > 0.67) return { pal: 15, maxArea: 46 };
  if (bodyLight > 0.53) return { pal: 14, maxArea: 52 };
  if (bodyLight > 0.39) return { pal: 13, maxArea: 50 };
  if (bodyLight > 0.26) return { pal: 12, maxArea: 44 };
  if (bodyLight > 0.14) return { pal: 11, maxArea: 38 };
  return { pal: 10, maxArea: 32 };
}

// ============================================================================
// 3. TOPOLOGICAL GRID CONSTRUCTION, FEATURE SNAPPING & REGION MERGING
// ============================================================================
function buildPaintByNumbersGrid(NX, NY) {
  const stepX = 1200 / NX;
  const stepY = 1200 / NY;
  const NVX = NX + 1;
  const NVY = NY + 1;

  const VX = new Float32Array(NVX * NVY);
  const VY = new Float32Array(NVX * NVY);

  // Step A: Initialize vertices & snap nearby vertices onto exact analytical truck curves
  const circleRadii = [R_BULB, R_LENS_INNER, R_LENS, R_RIM, R_BEZEL_PEAK, R_BEZEL_OUT, R_SOCKET];
  const hRibYs = [HY - 118, HY - 58, HY, HY + 58, HY + 118];
  const grilleYs = [252, 259, 324, 380, 448, 560, 628, 740, 808, 864, 925, 932];

  for (let iy = 0; iy <= NY; iy++) {
    for (let ix = 0; ix <= NX; ix++) {
      let idx = iy * NVX + ix;
      let x = ix * stepX;
      let y = iy * stepY;

      if (ix > 0 && ix < NX && iy > 0 && iy < NY) {
        let dx = x - HX;
        let dy = y - HY;
        let r = Math.hypot(dx, dy);
        let ang = Math.atan2(dy, dx) * (180 / Math.PI);

        // Snap to concentric headlamp & bezel circles
        let snappedCircle = false;
        let bezelOutLocal = R_BEZEL_OUT + 6 * Math.cos((ang + 90) * (Math.PI / 180));
        for (let c = 0; c < circleRadii.length; c++) {
          let targetR = (circleRadii[c] === R_BEZEL_OUT) ? bezelOutLocal : circleRadii[c];
          if (Math.abs(r - targetR) < 2.85 && r > 1) {
            x = HX + (dx / r) * targetR;
            y = HY + (dy / r) * targetR;
            snappedCircle = true;
            break;
          }
        }

        // Inside glass lens: snap to vertical flute lines & horizontal prism ribs
        if (!snappedCircle && r > R_BULB + 2 && r < R_LENS_INNER - 2) {
          let nearestFluteX = HX - 220 + Math.round((x - (HX - 220)) / 22) * 22;
          if (Math.abs(x - nearestFluteX) < 2.3) x = nearestFluteX;

          for (let k = 0; k < hRibYs.length; k++) {
            if (Math.abs(y - hRibYs[k]) < 2.3) {
              y = hRibYs[k];
              break;
            }
          }
        }

        // In grille zone: snap to horizontal chrome bar edges
        if (!snappedCircle && x > 730 && y > 245 && y < 940) {
          for (let k = 0; k < grilleYs.length; k++) {
            if (Math.abs(y - grilleYs[k]) < 2.5) {
              y = grilleYs[k];
              break;
            }
          }
        }

        // Subtle organic curl in body/rust areas away from mechanical circles
        if (!snappedCircle && r > R_SOCKET + 6 && x < 728 && y < 1030) {
          x += (noise(ix * 0.14, iy * 0.14) - 0.5) * 2.2;
          y += (noise(ix * 0.14 + 50, iy * 0.14 + 50) - 0.5) * 2.2;
        }
      }

      VX[idx] = x;
      VY[idx] = y;
    }
  }

  // Step B: Sample hyperrealist truck scene at each micro-cell center
  const NCELLS = NX * NY;
  const cellPal = new Uint8Array(NCELLS);
  const cellMaxArea = new Uint16Array(NCELLS);
  const cellIsBug = new Uint8Array(NCELLS);
  const cellFinished = new Uint8Array(NCELLS);

  for (let iy = 0; iy < NY; iy++) {
    for (let ix = 0; ix < NX; ix++) {
      let cIdx = iy * NX + ix;
      let v00 = iy * NVX + ix;
      let cx = 0.25 * (VX[v00] + VX[v00 + 1] + VX[v00 + NVX] + VX[v00 + NVX + 1]);
      let cy = 0.25 * (VY[v00] + VY[v00 + 1] + VY[v00 + NVX] + VY[v00 + NVX + 1]);

      let sample = sampleTruckScene(cx, cy);
      cellPal[cIdx] = sample.pal;
      cellIsBug[cIdx] = sample.isBug ? 1 : 0;

      // Straight diagonal boundary cutting right through headlamp center (435, 565)
      let cutY = getCutLineY(cx);
      let distToCut = Math.abs(cy - cutY);

      // Keep cells near the cut line compact so the cut across the headlamp is crisp
      let maxA = sample.maxArea;
      if (distToCut < 24) maxA = Math.min(maxA, 12);
      cellMaxArea[cIdx] = maxA;

      cellFinished[cIdx] = (cy < cutY) ? 1 : 0;
    }
  }

  // Step C: Despeckle isolated 1-quad noise (preserving bug spatters & rust pits)
  const palCopy = new Uint8Array(cellPal);
  const d4x = [1, -1, 0, 0];
  const d4y = [0, 0, 1, -1];
  for (let iy = 1; iy < NY - 1; iy++) {
    for (let ix = 1; ix < NX - 1; ix++) {
      let cIdx = iy * NX + ix;
      if (cellIsBug[cIdx]) continue;
      let p = palCopy[cIdx];
      let sameCount = 0;
      for (let d = 0; d < 4; d++) {
        let nIdx = (iy + d4y[d]) * NX + (ix + d4x[d]);
        if (palCopy[nIdx] === p && cellFinished[nIdx] === cellFinished[cIdx]) {
          sameCount++;
        }
      }
      if (sameCount === 0) {
        // Adopt the palette of a neighbor on the same side of the cut
        for (let d = 0; d < 4; d++) {
          let nIdx = (iy + d4y[d]) * NX + (ix + d4x[d]);
          if (cellFinished[nIdx] === cellFinished[cIdx]) {
            cellPal[cIdx] = palCopy[nIdx];
            break;
          }
        }
      }
    }
  }

  // Step D: Simplicial Disk-Preserving BFS Region Merger
  // Guarantees every merged Paint-by-Numbers cell has a single, simple, hole-free boundary loop!
  const compId = new Int32Array(NCELLS).fill(-1);
  const compPal = [];
  const compFinished = [];
  const compCells = [];

  // Clockwise 8-neighborhood offsets for simple-point topology test
  const n8x = [0, 1, 1, 1, 0, -1, -1, -1];
  const n8y = [-1, -1, 0, 1, 1, 1, 0, -1];

  function canAddSimplicial(ix, iy, cid) {
    let inC = [false, false, false, false, false, false, false, false];
    let countTrue = 0;
    for (let k = 0; k < 8; k++) {
      let nx = ix + n8x[k];
      let ny = iy + n8y[k];
      if (nx >= 0 && nx < NX && ny >= 0 && ny < NY) {
        if (compId[ny * NX + nx] === cid) {
          inC[k] = true;
          countTrue++;
        }
      }
    }
    if (countTrue === 0) return true;
    if (countTrue === 8) return false;

    // Prevent diagonal pinch vertices
    if (inC[1] && !inC[0] && !inC[2]) return false;
    if (inC[3] && !inC[2] && !inC[4]) return false;
    if (inC[5] && !inC[4] && !inC[6]) return false;
    if (inC[7] && !inC[6] && !inC[0]) return false;

    // Ensure 8-neighborhood intersection with cid is a single contiguous arc (no holes!)
    let transitions = 0;
    for (let k = 0; k < 8; k++) {
      if (!inC[k] && inC[(k + 1) & 7]) transitions++;
    }
    return transitions === 1;
  }

  const queue = new Int32Array(NCELLS);

  for (let iy = 0; iy < NY; iy++) {
    for (let ix = 0; ix < NX; ix++) {
      let seedIdx = iy * NX + ix;
      if (compId[seedIdx] !== -1) continue;

      let cid = compPal.length;
      let targetPal = cellPal[seedIdx];
      let targetFin = cellFinished[seedIdx];
      let maxA = cellMaxArea[seedIdx];

      compId[seedIdx] = cid;
      compPal.push(targetPal);
      compFinished.push(targetFin);
      let cellsList = [seedIdx];

      let qHead = 0;
      let qTail = 0;
      queue[qTail++] = seedIdx;

      while (qHead < qTail && cellsList.length < maxA) {
        let cur = queue[qHead++];
        let cx = cur % NX;
        let cy = (cur / NX) | 0;

        for (let d = 0; d < 4; d++) {
          if (cellsList.length >= maxA) break;
          let nx = cx + d4x[d];
          let ny = cy + d4y[d];
          if (nx < 0 || nx >= NX || ny < 0 || ny >= NY) continue;
          let nIdx = ny * NX + nx;
          if (compId[nIdx] !== -1) continue;
          if (cellPal[nIdx] !== targetPal || cellFinished[nIdx] !== targetFin) continue;

          if (canAddSimplicial(nx, ny, cid)) {
            compId[nIdx] = cid;
            cellsList.push(nIdx);
            queue[qTail++] = nIdx;
            maxA = Math.min(maxA, cellMaxArea[nIdx]);
          }
        }
      }

      compCells.push(cellsList);
    }
  }

  // Absorb tiny 1-quad non-bug orphans on the blank side into a valid neighbor so every blank cell is printable
  for (let cid = 0; cid < compCells.length; cid++) {
    if (compCells[cid].length === 1 && !cellIsBug[compCells[cid][0]]) {
      let cIdx = compCells[cid][0];
      let ix = cIdx % NX;
      let iy = (cIdx / NX) | 0;
      for (let d = 0; d < 4; d++) {
        let nx = ix + d4x[d];
        let ny = iy + d4y[d];
        if (nx < 0 || nx >= NX || ny < 0 || ny >= NY) continue;
        let nCid = compId[ny * NX + nx];
        if (nCid !== cid && compFinished[nCid] === compFinished[cid]) {
          compId[cIdx] = -1;
          if (canAddSimplicial(ix, iy, nCid)) {
            compId[cIdx] = nCid;
            compCells[nCid].push(cIdx);
            compCells[cid] = [];
            break;
          } else {
            compId[cIdx] = cid;
          }
        }
      }
    }
  }

  // Step E: Build Global Active Boundary Graph & Smooth Contour Chains Simultaneously
  // Every vertex shared by 2 components moves identically so zero gaps ever open!
  const vAdj = Array.from({ length: NVX * NVY }, () => []);
  const boundarySegments = []; // For single-pass crisp cyan line rendering

  // Horizontal grid edges
  for (let iy = 0; iy <= NY; iy++) {
    for (let ix = 0; ix < NX; ix++) {
      let cAbove = (iy > 0) ? compId[(iy - 1) * NX + ix] : -1;
      let cBelow = (iy < NY) ? compId[iy * NX + ix] : -2;
      if (cAbove !== cBelow) {
        let u = iy * NVX + ix;
        let v = iy * NVX + (ix + 1);
        vAdj[u].push(v);
        vAdj[v].push(u);
        if (iy > 0 && iy < NY) {
          boundarySegments.push({ u, v, c1: cAbove, c2: cBelow });
        }
      }
    }
  }

  // Vertical grid edges
  for (let iy = 0; iy < NY; iy++) {
    for (let ix = 0; ix <= NX; ix++) {
      let cLeft = (ix > 0) ? compId[iy * NX + (ix - 1)] : -1;
      let cRight = (ix < NX) ? compId[iy * NX + ix] : -2;
      if (cLeft !== cRight) {
        let u = iy * NVX + ix;
        let v = (iy + 1) * NVX + ix;
        vAdj[u].push(v);
        vAdj[v].push(u);
        if (ix > 0 && ix < NX) {
          boundarySegments.push({ u, v, c1: cLeft, c2: cRight });
        }
      }
    }
  }

  // 4 passes of Laplacian contour smoothing on the boundary graph
  const nextVX = new Float32Array(VX);
  const nextVY = new Float32Array(VY);
  for (let pass = 0; pass < 4; pass++) {
    for (let iy = 1; iy < NY; iy++) {
      for (let ix = 1; ix < NX; ix++) {
        let v = iy * NVX + ix;
        let nbrs = vAdj[v];
        if (nbrs.length === 2) {
          let u = nbrs[0];
          let w = nbrs[1];
          nextVX[v] = 0.25 * VX[u] + 0.5 * VX[v] + 0.25 * VX[w];
          nextVY[v] = 0.25 * VY[u] + 0.5 * VY[v] + 0.25 * VY[w];
        } else if (nbrs.length >= 3 && pass < 2) {
          let sx = 0, sy = 0;
          for (let k = 0; k < nbrs.length; k++) {
            sx += VX[nbrs[k]];
            sy += VY[nbrs[k]];
          }
          nextVX[v] = 0.65 * VX[v] + 0.35 * (sx / nbrs.length);
          nextVY[v] = 0.65 * VY[v] + 0.35 * (sy / nbrs.length);
        }
      }
    }
    VX.set(nextVX);
    VY.set(nextVY);
  }

  // Step F: Compute Interior Distance Transform for Pole of Inaccessibility (Numeral Placement)
  const cellDist = new Float32Array(NCELLS).fill(1);
  for (let iter = 0; iter < 4; iter++) {
    for (let iy = 0; iy < NY; iy++) {
      for (let ix = 0; ix < NX; ix++) {
        let cIdx = iy * NX + ix;
        let cid = compId[cIdx];
        let minN = 100;
        for (let k = 0; k < 8; k++) {
          let nx = ix + n8x[k];
          let ny = iy + n8y[k];
          let stepCost = (k & 1) ? 1.414 : 1.0;
          if (nx < 0 || nx >= NX || ny < 0 || ny >= NY || compId[ny * NX + nx] !== cid) {
            minN = Math.min(minN, stepCost * 0.5);
          } else {
            minN = Math.min(minN, cellDist[ny * NX + nx] + stepCost);
          }
        }
        cellDist[cIdx] = minN;
      }
    }
  }

  // Step G: Extract Closed Polygon Loops & Pole of Inaccessibility for Every Region
  const regions = [];
  const nextVertMap = new Int32Array(NVX * NVY).fill(-1);

  for (let cid = 0; cid < compCells.length; cid++) {
    let cells = compCells[cid];
    if (cells.length === 0) {
      regions.push(null);
      continue;
    }

    let startV = -1;
    let sumX = 0, sumY = 0;

    for (let i = 0; i < cells.length; i++) {
      let cIdx = cells[i];
      let ix = cIdx % NX;
      let iy = (cIdx / NX) | 0;

      let vTL = iy * NVX + ix;
      let vTR = iy * NVX + (ix + 1);
      let vBR = (iy + 1) * NVX + (ix + 1);
      let vBL = (iy + 1) * NVX + ix;

      sumX += 0.5 * (VX[vTL] + VX[vBR]);
      sumY += 0.5 * (VY[vTL] + VY[vBR]);

      // Top directed edge: vTL -> vTR
      if (iy === 0 || compId[(iy - 1) * NX + ix] !== cid) {
        nextVertMap[vTL] = vTR;
        startV = vTL;
      }
      // Right directed edge: vTR -> vBR
      if (ix === NX - 1 || compId[iy * NX + (ix + 1)] !== cid) {
        nextVertMap[vTR] = vBR;
        startV = vTR;
      }
      // Bottom directed edge: vBR -> vBL
      if (iy === NY - 1 || compId[(iy + 1) * NX + ix] !== cid) {
        nextVertMap[vBR] = vBL;
        startV = vBR;
      }
      // Left directed edge: vBL -> vTL
      if (ix === 0 || compId[iy * NX + (ix - 1)] !== cid) {
        nextVertMap[vBL] = vTL;
        startV = vBL;
      }
    }

    let cx = sumX / cells.length;
    let cy = sumY / cells.length;

    // Find Pole of Inaccessibility (deepest interior quad for numeral label)
    let bestScore = -1e9;
    let labelX = cx, labelY = cy, maxInradius = 0;
    for (let i = 0; i < cells.length; i++) {
      let cIdx = cells[i];
      let ix = cIdx % NX;
      let iy = (cIdx / NX) | 0;
      let vTL = iy * NVX + ix;
      let vBR = (iy + 1) * NVX + (ix + 1);
      let qx = 0.5 * (VX[vTL] + VX[vBR]);
      let qy = 0.5 * (VY[vTL] + VY[vBR]);
      let d = cellDist[cIdx];
      if (d > maxInradius) maxInradius = d;
      let score = d * 12 - Math.hypot(qx - cx, qy - cy) * 0.08;
      if (score > bestScore) {
        bestScore = score;
        labelX = qx;
        labelY = qy;
      }
    }

    // Walk closed directed loop
    let rawPts = [];
    let cur = startV;
    let guard = 0;
    while (cur !== -1 && guard < 2000) {
      rawPts.push([VX[cur], VY[cur]]);
      let nxt = nextVertMap[cur];
      nextVertMap[cur] = -1;
      cur = nxt;
      guard++;
      if (cur === startV) break;
    }

    // Clean nearly-collinear points while preserving curve fidelity
    let pts = [];
    for (let i = 0; i < rawPts.length; i++) {
      let prev = rawPts[(i - 1 + rawPts.length) % rawPts.length];
      let curr = rawPts[i];
      let next = rawPts[(i + 1) % rawPts.length];
      if (Math.hypot(curr[0] - prev[0], curr[1] - prev[1]) < 0.4) continue;
      let cross = Math.abs((curr[0] - prev[0]) * (next[1] - curr[1]) - (curr[1] - prev[1]) * (next[0] - curr[0]));
      let len = Math.hypot(next[0] - prev[0], next[1] - prev[1]);
      if (len > 0.1 && (cross / len) < 0.18 && pts.length > 4) continue;
      pts.push(curr);
    }

    if (pts.length < 3) pts = rawPts;

    regions.push({
      id: cid,
      pal: compPal[cid],
      finished: compFinished[cid] === 1,
      area: cells.length,
      pts,
      cx,
      cy,
      labelX,
      labelY,
      inradius: maxInradius,
      wrongPal: 0,
      partialFill: false
    });
  }

  // Step H: Select 5 "Wrong Colour, Slightly Over the Line" Cells & 3 Half-Painted Boundary Cells
  const wrongTargets = [
    { x: 454, y: 618, wrongPal: 21, dx: 4.5, dy: 3.5, bloat: 5.5 },  // 1: Blank lower glass headlamp filled with Fiery Rust Orange!
    { x: 282, y: 722, wrongPal: 14, dx: -4.0, dy: 4.5, bloat: 6.0 }, // 2: Blank lower-left chrome bezel filled with Pale Turquoise!
    { x: 522, y: 472, wrongPal: 14, dx: 3.5, dy: -3.0, bloat: 4.8 }, // 3: Finished upper-right glass lens cell mistakenly painted Turquoise!
    { x: 888, y: 418, wrongPal: 21, dx: 5.0, dy: 3.5, bloat: 5.5 },  // 4: Blank grille bar cell just below cut filled with Rust Orange!
    { x: 192, y: 702, wrongPal: 27, dx: -3.5, dy: 4.0, bloat: 5.2 }  // 5: Blank left turquoise fender cell filled with Bug Yellow!
  ];

  const wrongRegions = [];
  for (let t = 0; t < wrongTargets.length; t++) {
    let wt = wrongTargets[t];
    let bestReg = null;
    let bestD = 1e9;
    for (let r = 0; r < regions.length; r++) {
      let reg = regions[r];
      if (!reg || reg.area < 4 || reg.area > 45 || reg.wrongPal !== 0) continue;
      let d = Math.hypot(reg.cx - wt.x, reg.cy - wt.y);
      if (d < bestD) {
        bestD = d;
        bestReg = reg;
      }
    }
    if (bestReg && bestD < 55) {
      bestReg.wrongPal = wt.wrongPal;
      bestReg.wrongSpec = wt;
      wrongRegions.push(bestReg);
    }
  }

  // Select 3 cells right along the headlamp cut line that the painter left half-colored
  const partialTargets = [
    { x: 355, y: 602 },
    { x: 438, y: 566 },
    { x: 545, y: 516 }
  ];
  const partialRegions = [];
  for (let p = 0; p < partialTargets.length; p++) {
    let pt = partialTargets[p];
    let bestReg = null;
    let bestD = 1e9;
    for (let r = 0; r < regions.length; r++) {
      let reg = regions[r];
      if (!reg || reg.finished || reg.area < 6 || reg.wrongPal !== 0 || reg.partialFill) continue;
      let d = Math.hypot(reg.cx - pt.x, reg.cy - pt.y);
      if (d < bestD) {
        bestD = d;
        bestReg = reg;
      }
    }
    if (bestReg && bestD < 40) {
      bestReg.partialFill = true;
      partialRegions.push(bestReg);
    }
  }

  return {
    NX, NY, NVX, NVY, VX, VY,
    compId, regions, boundarySegments,
    wrongRegions, partialRegions
  };
}

// ============================================================================
// 4. RENDER FINISHED MARKER CELLS (BATCHED BY PALETTE COLOR)
// ============================================================================
function renderFinishedCells(grid) {
  const { regions } = grid;

  // Group finished regions by palette index (1..28) for fast color-cached wash batching
  const byColor = Array.from({ length: PALETTE.length }, () => []);
  for (let i = 0; i < regions.length; i++) {
    let reg = regions[i];
    if (!reg || !reg.finished || reg.wrongPal !== 0) continue;
    byColor[reg.pal].push(reg);
  }

  brush.noField();
  brush.noStroke();
  brush.noFill();

  // Pass 1: Dense flat marker wash per color batch
  for (let p = 1; p < PALETTE.length; p++) {
    let list = byColor[p];
    if (list.length === 0) continue;
    let col = PALETTE[p];

    for (let i = 0; i < list.length; i++) {
      let reg = list[i];
      if (reg.pts.length < 3) continue;
      let poly = new brush.Polygon(reg.pts);
      poly.wash(col, 255);
    }
  }
  brush.noWash();

  // Pass 2: Precision felt-tip marker rim & directional marker fill streaks
  // Gives each cell authentic physical marker density & seamless photographic coverage
  for (let p = 1; p < PALETTE.length; p++) {
    let list = byColor[p];
    if (list.length === 0) continue;
    let col = PALETTE[p];
    let rimCol = MARKER_RIM_COL[p];

    // Seal cell edges with fine marker pass in the exact palette color
    brush.set("marker", col, 0.42);
    for (let i = 0; i < list.length; i++) {
      let pts = list[i].pts;
      let n = pts.length;
      if (n < 3) continue;
      let step = (n > 24) ? 2 : 1;
      for (let k = 0; k < n; k += step) {
        let a = pts[k];
        let b = pts[(k + step) % n];
        brush.line(a[0], a[1], b[0], b[1]);
      }
    }

    // Subtle darker marker overlap rim on medium/large cells (classic marker pooling at cell border)
    brush.set("marker", rimCol, 0.28);
    for (let i = 0; i < list.length; i++) {
      let reg = list[i];
      if (reg.area < 8) continue;
      let pts = reg.pts;
      let n = pts.length;
      for (let k = 0; k < n; k += 3) {
        let a = pts[k];
        let b = pts[(k + 2) % n];
        let ax = a[0] + (reg.cx - a[0]) * 0.12;
        let ay = a[1] + (reg.cy - a[1]) * 0.12;
        let bx = b[0] + (reg.cx - b[0]) * 0.12;
        let by = b[1] + (reg.cy - b[1]) * 0.12;
        brush.line(ax, ay, bx, by);
      }
    }
  }
}

// ============================================================================
// 5. RENDER BARE CREAM CARD CYAN OUTLINES & TINY NUMERALS
// ============================================================================
function renderBlankCyanCells(grid) {
  const { VX, VY, regions, boundarySegments } = grid;

  brush.noField();
  brush.noFill();
  brush.noWash();

  // Pass 1: Crisp printed cyan outlines across all blank cells (and along the cut boundary)
  brush.set("rotring", "#4b9ac6", 0.50);
  for (let i = 0; i < boundarySegments.length; i++) {
    let seg = boundarySegments[i];
    let r1 = regions[seg.c1];
    let r2 = regions[seg.c2];
    if (!r1 || !r2) continue;

    // Draw if at least one adjacent cell is in the unpainted blank half
    if (!r1.finished || !r2.finished) {
      brush.line(VX[seg.u], VY[seg.u], VX[seg.v], VY[seg.v]);
    }
  }

  // Slightly bolder cyan along major structural transitions (cut line & distinct feature jumps)
  brush.set("rotring", "#3382b0", 0.65);
  for (let i = 0; i < boundarySegments.length; i++) {
    let seg = boundarySegments[i];
    let r1 = regions[seg.c1];
    let r2 = regions[seg.c2];
    if (!r1 || !r2) continue;
    if (r1.finished !== r2.finished || (!r1.finished && !r2.finished && Math.abs(r1.pal - r2.pal) >= 8)) {
      brush.line(VX[seg.u], VY[seg.u], VX[seg.v], VY[seg.v]);
    }
  }

  // Pass 2: Tiny printed cyan numerals inside every unpainted cell with sufficient room
  brush.set("rotring", "#3988b5", 0.42);
  for (let i = 0; i < regions.length; i++) {
    let reg = regions[i];
    if (!reg || reg.finished) continue;
    if (reg.inradius < 1.15 && reg.area < 4) continue;

    // Scale numeral size cleanly to fit cell inradius
    let h = constrain(reg.inradius * 3.1, 6.2, 10.5);
    drawTinyNumeral(reg.pal, reg.labelX, reg.labelY, h);
  }
}

// ============================================================================
// 6. WRONG-COLOUR OVER-THE-LINE CELLS & HALF-FINISHED BOUNDARY CELLS
// ============================================================================
function renderMistakeAndPartialCells(grid) {
  const { wrongRegions, partialRegions } = grid;

  brush.noField();

  // A. Render 3 Half-Painted Cells right on the headlamp cut boundary
  for (let i = 0; i < partialRegions.length; i++) {
    let reg = partialRegions[i];
    let col = PALETTE[reg.pal];
    let rimCol = MARKER_RIM_COL[reg.pal];

    // Clip or fill only the upper-left half of the cell with marker strokes
    let halfPts = [];
    for (let k = 0; k < reg.pts.length; k++) {
      let p = reg.pts[k];
      let mx = 0.55 * p[0] + 0.45 * reg.pts[0][0];
      let my = 0.55 * p[1] + 0.45 * reg.pts[0][1];
      halfPts.push([mx, my]);
    }
    if (halfPts.length >= 3) {
      let poly = new brush.Polygon(halfPts);
      poly.wash(col, 245);
      brush.noWash();
    }

    // Visible diagonal felt-tip marker strokes stopping mid-cell
    brush.set("marker", col, 0.72);
    for (let s = -3; s <= 3; s++) {
      let sx = reg.cx - 8 + s * 2.5;
      let sy = reg.cy - 6 + s * 1.8;
      brush.line(sx - 6, sy + 3, sx + 5, sy - 4);
    }
    brush.set("marker", rimCol, 0.35);
    brush.line(reg.cx - 9, reg.cy - 2, reg.cx + 4, reg.cy - 8);
  }

  // B. Render the 5 "Wrong Colour, Slightly Over the Line" Cells
  for (let i = 0; i < wrongRegions.length; i++) {
    let reg = wrongRegions[i];
    let spec = reg.wrongSpec;
    let wrongCol = PALETTE[reg.wrongPal];
    let wrongRim = MARKER_RIM_COL[reg.wrongPal];

    // Build an expanded/shifted polygon that sloppily crosses over the printed cyan outline!
    let overPts = [];
    for (let k = 0; k < reg.pts.length; k++) {
      let p = reg.pts[k];
      let vx = p[0] - reg.cx;
      let vy = p[1] - reg.cy;
      let vLen = Math.hypot(vx, vy) + 0.01;
      // Asymmetric outward bulge + directional hand slip (dx, dy)
      let angle = Math.atan2(vy, vx);
      let slipFactor = Math.max(0, Math.cos(angle - Math.atan2(spec.dy, spec.dx)));
      let expand = 1.0 + spec.bloat * (0.35 + 0.85 * slipFactor);
      overPts.push([
        p[0] + (vx / vLen) * expand + spec.dx * 0.65,
        p[1] + (vy / vLen) * expand + spec.dy * 0.65
      ]);
    }

    if (overPts.length >= 3) {
      let poly = new brush.Polygon(overPts);
      poly.wash(wrongCol, 248);
      brush.noWash();
    }

    // Sloppy marker edge strokes going visibly outside the cell line
    brush.set("marker", wrongCol, 0.85);
    for (let k = 0; k < overPts.length; k++) {
      let a = overPts[k];
      let b = overPts[(k + 1) % overPts.length];
      brush.line(a[0], a[1], b[0], b[1]);
    }

    // Darker marker overlap rim where the marker tip lingered over the line
    brush.set("marker", wrongRim, 0.45);
    for (let k = 0; k < overPts.length; k += 2) {
      let a = overPts[k];
      let b = overPts[(k + 1) % overPts.length];
      brush.line(a[0], a[1], b[0], b[1]);
    }

    // Faintly re-trace the true printed cyan outline & numeral peeking through the marker mistake!
    brush.set("rotring", "#2b6f96", 0.48);
    for (let k = 0; k < reg.pts.length; k++) {
      let a = reg.pts[k];
      let b = reg.pts[(k + 1) % reg.pts.length];
      brush.line(a[0], a[1], b[0], b[1]);
    }
    if (!reg.finished) {
      brush.set("rotring", "#245e80", 0.38);
      drawTinyNumeral(reg.pal, reg.labelX, reg.labelY, 7.5);
    }
  }
}

// ============================================================================
// 7. HYPERREALIST MICRO-ACCENTS ON FINISHED HALF
// ============================================================================
function renderHyperrealistAccents(grid) {
  brush.noField();
  brush.noFill();
  brush.noWash();

  // Crisp blazing specular glints on the finished glass headlamp flutes & chrome bezel
  brush.set("rotring", "#ffffff", 0.58);
  for (let col = -7; col <= 7; col++) {
    let fx = HX + col * 22 + 6;
    for (let row = -2; row <= 1; row++) {
      let fy = HY + row * 58;
      if (fy < getCutLineY(fx) - 8 && Math.hypot(fx - HX, fy - HY) < R_LENS_INNER - 8) {
        if (Math.hypot(fx - HX, fy - HY) > R_BULB + 6) {
          brush.line(fx - 5, fy - 3, fx + 5, fy - 3);
        }
      }
    }
  }

  // Specular sun-arc gleam along the upper-left chrome bezel peak
  brush.set("marker", "#fbfaf5", 0.55);
  for (let a = -142; a < -86; a += 4) {
    let r1 = R_BEZEL_PEAK - 4;
    let x1 = HX + r1 * Math.cos(a * Math.PI / 180);
    let y1 = HY + r1 * Math.sin(a * Math.PI / 180);
    let x2 = HX + r1 * Math.cos((a + 4) * Math.PI / 180);
    let y2 = HY + r1 * Math.sin((a + 4) * Math.PI / 180);
    brush.line(x1, y1, x2, y2);
  }

  // Fine crusty iron-oxide stipple inside the finished rust blooms
  brush.set("rotring", "#28110b", 0.45);
  for (let i = 0; i < 85; i++) {
    let rx = random(40, 745);
    let ry = random(165, 620);
    if (ry < getCutLineY(rx) - 10 && evaluateRustIntensity(rx, ry) > 0.42) {
      brush.line(rx, ry, rx + random(-2.5, 2.5), ry + random(-2.5, 2.5));
    }
  }
}

