function drawTinyNumeral(num, cx, cy, h) {
  let str = String(num);
  let charW = h * 0.56;
  let gap = h * 0.18;
  let totalW = str.length * charW + (str.length - 1) * gap;
  let startX = cx - totalW * 0.5;
  let startY = cy - h * 0.5;

  for (let c = 0; c < str.length; c++) {
    let ch = str[c];
    let paths = DIGIT_STROKES[ch];
    if (!paths) continue;
    let ox = startX + c * (charW + gap);
    for (let p = 0; p < paths.length; p++) {
      let pts = paths[p];
      for (let i = 0; i < pts.length - 1; i++) {
        brush.line(
          ox + pts[i][0] * charW,
          startY + pts[i][1] * h,
          ox + pts[i + 1][0] * charW,
          startY + pts[i + 1][1] * h
        );
      }
    }
  }
}

