function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // 1. Pale warm-grey plaster wall
  drawPlasterWall();

  // 2. Faint, offset shadows on the wall in soft smudged charcoal
  drawWallShadows();

  // 3. Black roofing slate (upper-left drift, -34 deg)
  drawBlackSlate(425, 325, -34);

  // 4. Red clay brick (lower-left drift, +52 deg)
  drawRedBrick(280, 650, 52);

  // 5. Cadmium-yellow sticky note with 3D curl (center-right drift, -56 deg)
  drawYellowStickyNote(735, 380, -56);

