// ---------------------------------------------------------------------------
// HELPERS FOR SHAPES
// ---------------------------------------------------------------------------
function drawPolyShape(pts, curvature = 0) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(CLOSE);
}

// ---------------------------------------------------------------------------
// 1. PALE PLASTER WALL (NEAR-FLAT WARM GREY)
// ---------------------------------------------------------------------------
function drawPlasterWall() {
  background("#dcd8d0");

  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Subtle gallery light gradient: slightly warmer/brighter upper-left, deeper lower-right
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.35, 0.1);

  brush.fill("#e6e3dc", 42);
  drawPolyShape([
    [0, 0],
    [820, 0],
    [520, 620],
    [0, 780]
  ]);

  brush.fill("#cbc6bc", 36);
  drawPolyShape([
    [420, 480],
    [1200, 260],
    [1200, 1200],
    [180, 1200]
  ]);

  brush.fill("#c2bdb2", 28);
  drawPolyShape([
    [680, 720],
    [1200, 580],
    [1200, 1200],
    [540, 1200]
  ]);
  brush.noFill();

  // Skim-coat trowel sweeps across the plaster
  let plasterTones = ["#e5e2db", "#d0cbc1", "#c7c2b8", "#e9e6df"];
  for (let i = 0; i < 160; i++) {
    let x = random(-40, 1240);
    let y = random(-40, 1240);
    let len = random(90, 280);
    let ang = random(-18, 12) + (noise(x * 0.003, y * 0.003) - 0.5) * 25;
    let col = random(plasterTones);
    brush.set("plaster_skim", col, random(0.8, 1.8));
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // Ultra-fine mineral grain, faint trowel ridges, and microscopic plaster pinholes
  for (let i = 0; i < 240; i++) {
    let x = random(20, 1180);
    let y = random(20, 1180);
    if (random() < 0.65) {
      brush.set("2H", random() < 0.5 ? "#c5c0b6" : "#e8e5de", random(0.3, 0.6));
      let a = random(-15, 15);
      let l = random(8, 34);
      brush.line(x, y, x + cos(a) * l, y + sin(a) * l);
    } else {
      // Tiny plaster sand speck or micro-pit
      brush.set("2B", random() < 0.5 ? "#b5afa4" : "#ece9e2", random(0.25, 0.45));
      brush.line(x, y, x + random(-1.5, 1.5), y + random(-1.5, 1.5));
    }
  }
}

// ---------------------------------------------------------------------------
// 2. SOFT SMUDGED CHARCOAL SHADOWS ON THE WALL
// ---------------------------------------------------------------------------
function drawSmudgedShadowPolygon(pts, layers = 4, baseAlpha = 20, hatchAngle = 35, bounceCol = null) {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Multi-pass diffused charcoal watercolor/wash core for penumbra
  for (let layer = layers; layer >= 1; layer--) {
    let expand = layer * 5.5;
    let cx = 0, cy = 0;
    for (let p of pts) { cx += p[0]; cy += p[1]; }
    cx /= pts.length;
    cy /= pts.length;

    let expandedPts = pts.map(p => {
      let dx = p[0] - cx;
      let dy = p[1] - cy;
      let d = sqrt(dx * dx + dy * dy) || 1;
      return [
        p[0] + (dx / d) * expand + random(-2.5, 2.5),
        p[1] + (dy / d) * expand + random(-2.5, 2.5)
      ];
    });

    brush.fillBleed(0.38, "out");
    brush.fillTexture(0.55, 0.12);
    brush.fill("#282522", baseAlpha);
    drawPolyShape(expandedPts, 0.15);
  }

  // Optional warm chromatic bounce light inside the shadow
  if (bounceCol) {
    brush.fillBleed(0.45, "out");
    brush.fill(bounceCol, 28);
    drawPolyShape(pts, 0.15);
  }
  brush.noFill();

  // Dry charcoal hatching inside the shadow body
  brush.hatchStyle("charcoal", "#322e2b", 0.75);
  brush.hatch(9, hatchAngle, { rand: 0.18 });
  drawPolyShape(pts, 0.1);
  brush.noHatch();

  brush.hatchStyle("2B", "#3d3935", 0.55);
  brush.hatch(13, hatchAngle + 28, { rand: 0.22 });
  drawPolyShape(pts, 0.1);
  brush.noHatch();

  // Soft smudged charcoal perimeter strokes
  for (let i = 0; i < pts.length; i++) {
    let p1 = pts[i];
    let p2 = pts[(i + 1) % pts.length];
    let steps = max(3, int(dist(p1[0], p1[1], p2[0], p2[1]) / 18));
    for (let s = 0; s < steps; s++) {
      let t1 = s / steps;
      let t2 = (s + 1) / steps;
      let x1 = lerp(p1[0], p2[0], t1) + random(-5, 5);
      let y1 = lerp(p1[1], p2[1], t1) + random(-5, 5);
      let x2 = lerp(p1[0], p2[0], t2) + random(-5, 5);
      let y2 = lerp(p1[1], p2[1], t2) + random(-5, 5);
      brush.set("charcoal_smudge", "#2b2825", random(0.8, 1.5));
      brush.line(x1, y1, x2, y2);
    }
  }
}

