// ---------------------------------------------------------------------------
// 3. THE BLACK ROOFING SLATE
// ---------------------------------------------------------------------------
function drawBlackSlate(cx, cy, tilt) {
  push();
  translate(cx, cy);
  rotate(tilt);

  let w = 360;
  let h = 240;
  let hw = w / 2;
  let hh = h / 2;

  // Outer irregular riven perimeter points
  let outerPts = [
    [-hw + 2, -hh + 1],
    [-hw * 0.4, -hh - 2],
    [hw * 0.3, -hh + 1],
    [hw - 4, -hh + 3],
    [hw + 1, -hh * 0.3],
    [hw - 1, hh * 0.4],
    [hw - 5, hh - 2],
    [hw * 0.25, hh + 2],
    [-hw * 0.45, hh - 1],
    [-hw + 3, hh - 3],
    [-hw - 2, hh * 0.3],
    [-hw + 1, -hh * 0.4]
  ];

  // Stepped 3D thickness edge (bottom and right sides in shadow, top and left chamfered in light)
  let edgeThickness = [
    [-hw + 3, hh - 3],
    [hw - 5, hh - 2],
    [hw - 1, hh * 0.4],
    [hw + 1, -hh * 0.3],
    [hw - 4, -hh + 3],
    [hw + 5, -hh + 11],
    [hw + 10, -hh * 0.3 + 8],
    [hw + 8, hh * 0.4 + 8],
    [hw + 3, hh + 7],
    [-hw + 11, hh + 6]
  ];

  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.wash("#0d0f13", 250);
  drawPolyShape(edgeThickness);
  brush.noWash();

  // Flaked outer bevel shelf around top & left edges (catching raking gallery light)
  let bevelPts = outerPts.map((p, idx) => {
    let shiftX = p[0] < 0 ? -5 : 2;
    let shiftY = p[1] < 0 ? -5 : 2;
    return [p[0] + shiftX, p[1] + shiftY];
  });
  brush.wash("#3c4452", 240);
  drawPolyShape(bevelPts);
  brush.noWash();

  // Main slate body solid base
  brush.wash("#171b22", 252);
  drawPolyShape(outerPts);
  brush.noWash();

  // Layered slate mineral washes (plumbago blue-black, deep charcoal, subtle iron-oxide warmth)
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.65, 0.3);

  brush.fill("#232934", 85);
  drawPolyShape([
    [-hw + 10, -hh + 8],
    [hw - 30, -hh + 12],
    [hw - 60, hh - 35],
    [-hw + 14, hh - 20]
  ]);

  brush.fill("#0e1015", 95);
  drawPolyShape([
    [-hw + 50, -10],
    [hw - 8, -hh + 25],
    [hw - 6, hh - 6],
    [-hw + 25, hh - 8]
  ]);

  // Subtle rusty iron-sulfide mineral blush on the lower-left cleavage plane
  brush.fill("#593e2e", 46);
  drawPolyShape([
    [-hw + 18, 15],
    [-25, 32],
    [15, hh - 12],
    [-hw + 12, hh - 10]
  ]);
  brush.noFill();

  // Fine mineral grain foliation across the entire slate surface
  for (let i = 0; i < 220; i++) {
    let y = random(-hh + 8, hh - 8);
    let x1 = random(-hw + 10, hw - 50);
    let len = random(25, 130);
    let x2 = min(hw - 10, x1 + len);
    let dy = random(-3, 3);
    let col = random(["#0c0e12", "#1f252f", "#2b3340", "#13171d", "#36404f"]);
    brush.set("2H", col, random(0.35, 0.85));
    brush.line(x1, y, x2, y + dy);
  }

  // Stepped lamellar cleavage terraces (the hallmark of riven roofing slate)
  let cleavageLedges = [
    { yBase: -82, xStart: -hw + 6, xEnd: hw - 18, stepDown: true },
    { yBase: -44, xStart: -hw + 22, xEnd: hw - 8, stepDown: false },
    { yBase: -8, xStart: -hw + 8, xEnd: hw - 35, stepDown: true },
    { yBase: 28, xStart: -hw + 40, xEnd: hw - 6, stepDown: true },
    { yBase: 64, xStart: -hw + 10, xEnd: hw - 14, stepDown: false },
    { yBase: 94, xStart: -hw + 16, xEnd: hw - 45, stepDown: true }
  ];

  for (let ledge of cleavageLedges) {
    let pts = [];
    let steps = 14;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let lx = lerp(ledge.xStart, ledge.xEnd, t);
      let ly = ledge.yBase + (noise(lx * 0.015, ledge.yBase * 0.05) - 0.5) * 26;
      pts.push([lx, ly]);
    }

    // Soft shading band along the terrace step
    for (let s = 0; s < pts.length - 1; s++) {
      let p1 = pts[s];
      let p2 = pts[s + 1];
      brush.set("charcoal", ledge.stepDown ? "#07080b" : "#2e3644", random(0.9, 1.5));
      brush.line(p1[0], p1[1] + 2, p2[0], p2[1] + 2);

      // Razor-sharp cleaved mineral edge
      brush.set("slate_cleave", ledge.stepDown ? "#050608" : "#7c8b9e", random(0.55, 1.0));
      brush.line(p1[0], p1[1], p2[0], p2[1]);

      if (!ledge.stepDown && random() < 0.75) {
        brush.set("steel_hairline", "#a6b6c9", random(0.45, 0.8));
        brush.line(p1[0], p1[1] - 1, p2[0], p2[1] - 1);
      }
    }
  }

  // Delaminated, flaky, scalloped edges around the perimeter
  for (let i = 0; i < outerPts.length; i++) {
    let p1 = outerPts[i];
    let p2 = outerPts[(i + 1) % outerPts.length];
    let isLitEdge = (p1[1] + p2[1] < 20) || (p1[0] + p2[0] < -40);

    let sub = 6;
    for (let s = 0; s < sub; s++) {
      let ax = lerp(p1[0], p2[0], s / sub) + random(-2, 2);
      let ay = lerp(p1[1], p2[1], s / sub) + random(-2, 2);
      let bx = lerp(p1[0], p2[0], (s + 1) / sub) + random(-2, 2);
      let by = lerp(p1[1], p2[1], (s + 1) / sub) + random(-2, 2);

      // Flaked bevel step
      brush.set("slate_cleave", isLitEdge ? "#69778a" : "#080a0d", random(0.8, 1.4));
      brush.line(ax, ay, bx, by);

      if (isLitEdge) {
        brush.set("steel_hairline", "#b8c7d9", random(0.5, 0.9));
        brush.line(ax - 1.5, ay - 1.5, bx - 1.5, by - 1.5);
      } else {
        // Stepped lamina lines on the dark 3D thickness edge
        brush.set("steel_hairline", "#2c3440", 0.55);
        brush.line(ax + 3, ay + 3, bx + 3, by + 3);
        brush.set("steel_hairline", "#050608", 0.65);
        brush.line(ax + 6, ay + 5, bx + 6, by + 5);
      }
    }
  }

  // Two countersunk nail holes near the left edge
  let holeYs = [-54, 54];
  let holeX = -hw + 36;
  for (let hy of holeYs) {
    // Spalled, pulverized grey slate crater around the punched hole
    brush.noStroke();
    brush.wash("#4d5663", 235);
    brush.circle(holeX, hy, 14, 0.35);
    brush.wash("#6c7787", 210);
    brush.circle(holeX - 1.5, hy - 1.5, 10.5, 0.3);
    brush.noWash();

    // Inner hole revealing the pale warm-grey plaster wall behind the slate
    brush.wash("#cfc9be", 255);
    brush.circle(holeX, hy, 6.5, 0.12);
    brush.noWash();

    // Inner thickness shadow inside the top-left of the hole
    brush.set("slate_cleave", "#090b0e", 1.1);
    brush.arc(holeX + 1, hy + 1, 6.8, 155, 345);

    // Bright crushed-mineral rim highlight on lower-right of the spalled bevel
    brush.set("steel_hairline", "#c4d2e3", 0.75);
    brush.arc(holeX, hy, 11.5, -35, 125);
    brush.set("steel_hairline", "#202630", 0.65);
    brush.arc(holeX, hy, 13.5, 130, 325);
  }

  pop();
}

// ---------------------------------------------------------------------------
// 4. THE RED CLAY BRICK
// ---------------------------------------------------------------------------
function drawRedBrick(cx, cy, tilt) {
  push();
  translate(cx, cy);
  rotate(tilt);

  let w = 296;
  let h = 142;
  let hw = w / 2;
  let hh = h / 2;

  // 3D foreshortened side vectors (showing upper-left header face and top stretcher edge)
  let dx = -28;
  let dy = -20;

  let frontFace = [
    [-hw, -hh],
    [hw, -hh],
    [hw, hh],
    [-hw, hh]
  ];

  let topSideFace = [
    [-hw + dx, -hh + dy],
    [hw + dx, -hh + dy],
    [hw, -hh],
    [-hw, -hh]
  ];

  let leftEndFace = [
    [-hw + dx, -hh + dy],
    [-hw, -hh],
    [-hw, hh],
    [-hw + dx, hh + dy]
  ];

  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // 1. Draw Top Side Face (catching warm raking light)
  brush.wash("#e34b2b", 252);
  drawPolyShape(topSideFace);
  brush.noWash();

  brush.fillBleed(0.2, "in");
  brush.fillTexture(0.65, 0.25);
  brush.fill("#f76e47", 110);
  drawPolyShape(topSideFace);
  brush.noFill();

  // 2. Draw Left Header End Face (brightest sunlit terracotta plane)
  brush.wash("#ee5a38", 252);
  drawPolyShape(leftEndFace);
  brush.noWash();

  brush.fill("#ff835c", 115);
  drawPolyShape(leftEndFace);
  brush.noFill();

  // 3. Draw Main Broad Bed Face (deep, vivid saturated terracotta & vermilion)
  brush.wash("#bf2919", 254);
  drawPolyShape(frontFace);
  brush.noWash();

  // Vivid terracotta saturation variations and kiln-kissed dark flash patch
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.7, 0.35);

  // Vivid cadmium-vermilion glow on upper-left half of main face
  brush.fill("#e03c24", 120);
  drawPolyShape([
    [-hw + 4, -hh + 4],
    [40, -hh + 6],
    [-20, hh - 8],
    [-hw + 4, hh - 4]
  ]);

  // Deep roasted iron-red kiln flash mark across center-right
  brush.fill("#78170f", 105);
  drawPolyShape([
    [-35, -hh + 18],
    [hw - 22, -hh + 12],
    [hw - 10, hh - 16],
    [10, hh - 22]
  ]);

  // Rich orange-red lower-right corner warmth
  brush.fill("#d4351f", 95);
  drawPolyShape([
    [30, -10],
    [hw - 4, -hh + 20],
    [hw - 4, hh - 4],
    [-15, hh - 4]
  ]);
  brush.noFill();

  // Wire-cut drag striations across the clay face
  for (let i = 0; i < 110; i++) {
    let x = random(-hw + 8, hw - 8);
    let y1 = random(-hh + 6, hh - 28);
    let y2 = y1 + random(14, 38);
    let curveX = x + random(-4, 4);
    let col = random(["#941b10", "#de4428", "#6b120a", "#f06141"]);
    brush.set("2H", col, random(0.4, 0.85));
    brush.spline([[x, y1], [curveX, (y1 + y2) * 0.5], [x, y2]], 0.4);
  }

  // Texture on the two 3D side faces
  for (let i = 0; i < 45; i++) {
    let t = random(0.04, 0.96);
    let s = random(0.1, 0.9);
    // Top face mark
    let tx = lerp(-hw, hw, t) + dx * s;
    let ty = -hh + dy * s;
    brush.set("2B", random() < 0.5 ? "#b52d18" : "#ff9d7a", random(0.35, 0.7));
    brush.line(tx, ty, tx + random(-6, 6), ty + random(-2, 2));

    // Left face mark
    let lx = -hw + dx * s;
    let ly = lerp(-hh, hh, t) + dy * s;
    brush.set("2B", random() < 0.5 ? "#c4351d" : "#ffa887", random(0.35, 0.7));
    brush.line(lx, ly, lx + random(-2, 2), ly + random(-6, 6));
  }

  // Three deep cylindrical core holes (extruded perforated brick detail)
  let coreXs = [-88, 0, 88];
  let coreR = 23;
  for (let cxHole of coreXs) {
    // Extruded clay rim lip around each hole
    brush.noStroke();
    brush.wash("#d63d24", 220);
    brush.circle(cxHole, 0, coreR + 3.5, 0.25);

    // Deep dark terracotta interior cylinder wall
    brush.wash("#2e0704", 252);
    brush.circle(cxHole, 0, coreR, 0.18);

    // Warm reflected terracotta glow on lower-right interior wall of cylinder
    brush.fillBleed(0.18, "in");
    brush.fill("#8c1e11", 150);
    drawPolyShape([
      [cxHole - 4, -coreR + 6],
      [cxHole + coreR - 2, -8],
      [cxHole + coreR - 3, coreR - 4],
      [cxHole - 8, coreR - 2],
      [cxHole - 2, 4]
    ], 0.3);
    brush.noFill();

    // Oblique sliver of shadowed plaster wall visible through the bottom-right of the core tunnel
    brush.wash("#59534c", 240);
    drawPolyShape([
      [cxHole + 3, 2],
      [cxHole + 13, -4],
      [cxHole + 16, 6],
      [cxHole + 9, 14],
      [cxHole + 1, 10]
    ], 0.35);
    brush.noWash();

    // Crisp ragged clay shadow on upper-left lip and sunlit lower-right bevel of hole
    brush.set("slate_cleave", "#1c0302", 1.15);
    brush.arc(cxHole + 0.5, 0.5, coreR, 140, 330);

    brush.set("slate_cleave", "#ff8c69", 0.95);
    brush.arc(cxHole - 0.5, -0.5, coreR + 1.5, -35, 130);

    // Crumbly clay lip notches around hole
    for (let a = 0; a < 360; a += 28) {
      let rx = cxHole + cos(a) * (coreR + random(-1.5, 2));
      let ry = sin(a) * (coreR + random(-1.5, 2));
      let isLit = (a > -40 && a < 135);
      brush.set("2B", isLit ? "#ffa88a" : "#3b0905", random(0.4, 0.8));
      brush.line(rx, ry, rx + random(-2.5, 2.5), ry + random(-2.5, 2.5));
    }
  }

  // Hundreds of hyperreal brick pores, voids, fissures, and embedded quartz sand grains
  for (let i = 0; i < 380; i++) {
    let px = random(-hw + 5, hw - 5);
    let py = random(-hh + 5, hh - 5);

    // Skip interior of the 3 core holes
    if (
      dist(px, py, -88, 0) < coreR + 2 ||
      dist(px, py, 0, 0) < coreR + 2 ||
      dist(px, py, 88, 0) < coreR + 2
    ) {
      continue;
    }

    let r = random();
    if (r < 0.58) {
      // Dark clay pore pit with tiny sunlit lower-right rim highlight
      let pSize = random(0.45, 1.35);
      brush.set("2B", random() < 0.5 ? "#380704" : "#5c1009", pSize);
      let dxP = random(-2.5, 2.5);
      let dyP = random(-1.8, 1.8);
      brush.line(px, py, px + dxP, py + dyP);

      if (pSize > 0.75) {
        brush.set("steel_hairline", "#ff9d7d", random(0.45, 0.8));
        brush.line(px + 1, py + 1.2, px + dxP + 1, py + dyP + 1.2);
      }
    } else if (r < 0.82) {
      // Spray stipple cluster of microscopic terracotta pores
      brush.set("clay_pore", random() < 0.5 ? "#4a0b06" : "#f25f3d", random(0.5, 1.1));
      brush.line(px, py, px + random(-3, 3), py + random(-3, 3));
    } else {
      // Embedded white/buff silica sand grain or dark ironstone fleck
      let isQuartz = random() < 0.65;
      brush.set("steel_hairline", isQuartz ? "#fae6d4" : "#240705", random(0.55, 1.0));
      brush.line(px, py, px + random(-1.5, 1.5), py + random(-1.5, 1.5));
    }
  }

  // Micro-fissures (shrinkage cracks from firing)
  let cracks = [
    [[-125, -45], [-112, -28], [-104, -18]],
    [[-45, 32], [-34, 46], [-22, 54]],
    [[42, -52], [51, -36], [48, -22]],
    [[122, 18], [134, 29], [144, 33]]
  ];
  for (let cr of cracks) {
    brush.set("slate_cleave", "#2b0503", 0.7);
    brush.spline(cr, 0.35);
    brush.set("steel_hairline", "#ff9473", 0.5);
    brush.spline(cr.map(p => [p[0] + 1.2, p[1] + 1.2]), 0.35);
  }

  // Crumbly, weathered arris edges (where the 3 planes meet and around the perimeter)
  let arrisEdges = [
    { p1: [-hw, -hh], p2: [hw, -hh], colLit: "#ffa685", colDark: "#7a160c" },
    { p1: [-hw, -hh], p2: [-hw, hh], colLit: "#ffb294", colDark: "#871a0f" },
    { p1: [-hw + dx, -hh + dy], p2: [hw + dx, -hh + dy], colLit: "#ffc4ad", colDark: "#b82e18" },
    { p1: [-hw + dx, -hh + dy], p2: [-hw + dx, hh + dy], colLit: "#ffc4ad", colDark: "#b82e18" },
    { p1: [-hw + dx, -hh + dy], p2: [-hw, -hh], colLit: "#ffcab5", colDark: "#9e2412" },
    { p1: [hw, -hh], p2: [hw, hh], colLit: "#9e2113", colDark: "#380704" },
    { p1: [-hw, hh], p2: [hw, hh], colLit: "#8f1c10", colDark: "#330603" }
  ];

  for (let edge of arrisEdges) {
    let segs = max(6, int(dist(edge.p1[0], edge.p1[1], edge.p2[0], edge.p2[1]) / 16));
    for (let s = 0; s < segs; s++) {
      let ax = lerp(edge.p1[0], edge.p2[0], s / segs) + random(-1.4, 1.4);
      let ay = lerp(edge.p1[1], edge.p2[1], s / segs) + random(-1.4, 1.4);
      let bx = lerp(edge.p1[0], edge.p2[0], (s + 1) / segs) + random(-1.4, 1.4);
      let by = lerp(edge.p1[1], edge.p2[1], (s + 1) / segs) + random(-1.4, 1.4);

      brush.set("slate_cleave", edge.colDark, random(0.7, 1.2));
      brush.line(ax, ay, bx, by);
      brush.set("steel_hairline", edge.colLit, random(0.6, 1.0));
      brush.line(ax - 1, ay - 1, bx - 1, by - 1);
    }
  }

  // Chipped corner divot at bottom-left exposing bright orange-terracotta interior clay
  brush.noStroke();
  brush.wash("#f56a42", 240);
  drawPolyShape([
    [-hw - 1, hh - 14],
    [-hw + 12, hh - 6],
    [-hw + 7, hh + 1],
    [-hw - 3, hh - 3]
  ]);
  brush.noWash();

  pop();
}

// ---------------------------------------------------------------------------
// 5. THE CADMIUM-YELLOW STICKY NOTE (WITH 3D CURL)
// ---------------------------------------------------------------------------
function drawYellowStickyNote(cx, cy, tilt) {
  push();
  translate(cx, cy);
  rotate(tilt);

  // A 172x172 square sticky note whose top strip (-86 to -52) stays flat while
  // the lower sheet curls gracefully upward/outward toward the viewer.
  let topFlatPts = [
    [-86, -86],
    [86, -86],
    [86, -50],
    [-86, -50]
  ];

  let fullNotePts = [
    [-86, -86],
    [86, -86],
    [86, -50],
    [84, -8],
    [79, 34],
    [72, 60],
    [18, 69],
    [-38, 76],
    [-81, 73],
    [-85, 22],
    [-86, -50]
  ];

  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // 1. Shaded underside crescent visible beneath the strongly curled lower-right edge
  let undersideCrescent = [
    [84, -4],
    [88, 28],
    [83, 66],
    [34, 74],
    [18, 69],
    [72, 60],
    [79, 34]
  ];
  brush.wash("#a85c00", 248);
  drawPolyShape(undersideCrescent, 0.25);
  brush.noWash();

  // 2. Solid vivid cadmium-yellow paper base
  brush.wash("#ffca00", 254);
  drawPolyShape(fullNotePts, 0.15);
  brush.noWash();

  // 3. Tonal sculpting of the 3D curl:
  // (a) Flat adhesive band at the top (-86 to -50)
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.35, 0.12);
  brush.fill("#f2b600", 95);
  drawPolyShape(topFlatPts);

  // (b) Concave inflection trough just below the adhesive strip (-52 to -8)
  // where the paper bends away from the light before sweeping outward
  brush.fill("#d97f00", 115);
  drawPolyShape([
    [-86, -52],
    [86, -52],
    [85, -6],
    [-85, -2]
  ], 0.1);

  brush.fill("#c46800", 75);
  drawPolyShape([
    [-85, -42],
    [85, -42],
    [85, -18],
    [-85, -14]
  ], 0.1);

  // (c) Convex belly of the curl (-6 to +58) catching brilliant cadmium-lemon light
  brush.fill("#ffe81f", 145);
  drawPolyShape([
    [-85, -4],
    [84, -8],
    [76, 52],
    [16, 62],
    [-82, 62]
  ], 0.25);

  brush.fill("#fff76b", 130);
  drawPolyShape([
    [-78, 12],
    [80, 6],
    [74, 46],
    [12, 55],
    [-76, 50]
  ], 0.3);

  // (d) Warm amber roll-off right at the very bottom curled lip
  brush.fill("#e08b00", 85);
  drawPolyShape([
    [-81, 58],
    [16, 56],
    [72, 48],
    [72, 60],
    [18, 69],
    [-38, 76],
    [-81, 73]
  ], 0.25);
  brush.noFill();

  // 4. Smooth hyperreal dry-pastel/paper shading strokes following the curl contour
  for (let i = 0; i < 95; i++) {
    let t = i / 95;
    let yLeft = lerp(-84, 71, t);
    let yRight = lerp(-84, 58, t);
    let xLeft = lerp(-85, -80, t * t);
    let xRight = lerp(85, 72, t * t);
    let midY = lerp(yLeft, yRight, 0.5) + (t > 0.35 ? sin((t - 0.35) * 180) * 7 : 0);

    let col;
    if (t < 0.2) {
      col = "#f5bd00"; // flat adhesive zone
    } else if (t < 0.44) {
      col = random() < 0.6 ? "#d47800" : "#e68e00"; // concave shadow trough
    } else if (t < 0.84) {
      col = random() < 0.65 ? "#fff44f" : "#ffdf00"; // bright convex curl highlight
    } else {
      col = "#e89600"; // bottom lip turn
    }

    brush.set("paper_velvet", col, random(0.7, 1.3));
    brush.spline([
      [xLeft + 2, yLeft],
      [0, midY],
      [xRight - 2, yRight]
    ], 0.35);
  }

  // Intense specular sheen band across the crest of the paper curl
  for (let i = 0; i < 28; i++) {
    let y = random(18, 44);
    let x1 = random(-74, -10);
    let x2 = random(15, 74);
    brush.set("2H", "#fffbe0", random(0.55, 1.1));
    brush.spline([
      [x1, y + 3],
      [(x1 + x2) * 0.5, y + 7],
      [x2, y - 2]
    ], 0.35);
  }

  // Subtle horizontal line where the adhesive backing strip ends (y = -50)
  brush.set("2H", "#bd6800", 0.55);
  brush.line(-85, -50, 85, -50);
  brush.set("steel_hairline", "#ffe659", 0.5);
  brush.line(-85, -48.8, 85, -48.8);

  // Fine paper fiber grain
  for (let i = 0; i < 90; i++) {
    let px = random(-78, 74);
    let py = random(-80, 56);
    brush.set("2H", random() < 0.5 ? "#fff799" : "#d98200", 0.35);
    brush.line(px, py, px + random(-5, 5), py + random(-2, 2));
  }

  // Crisp sunlit paper thickness rim along top, left, and curled bottom edge
  brush.set("steel_hairline", "#fffef2", 0.95);
  brush.line(-86, -86, 86, -86);
  brush.spline([[-86, -86], [-85, -20], [-81, 73]], 0.25);

  // Sweeping bottom curled edge highlight and dark underside separation line
  brush.set("slate_cleave", "#854500", 0.75);
  brush.spline([[-81, 74], [-38, 77], [18, 70], [72, 61]], 0.35);

  brush.set("steel_hairline", "#fffef5", 1.05);
  brush.spline([[-81, 72.5], [-38, 75.5], [18, 68.5], [72, 59.5]], 0.35);

  // Right edge curling up
  brush.set("slate_cleave", "#9e5400", 0.7);
  brush.spline([[86, -86], [84, -8], [79, 34], [72, 60]], 0.3);

  pop();
}

// ---------------------------------------------------------------------------
// 6. THE LONG THIN STEEL RULER
// ---------------------------------------------------------------------------
function drawSteelRuler(cx, cy, tilt) {
  let L = 850;
  let W = 44;
  let hL = L / 2;
  let hW = W / 2;

  // First: cast shadow of the steel ruler across the Black Roofing Slate
  // where the ruler hovers ~14px above the lower portion of the slate
  push();
  translate(cx + 11, cy + 14);
  rotate(tilt);
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.fillBleed(0.18, "out");
  brush.fill("#050608", 125);
  drawPolyShape([
    [-255, -hW - 2],
    [-18, -hW - 2],
    [-8, hW + 2],
    [-245, hW + 2]
  ]);
  brush.noFill();

  brush.set("charcoal_smudge", "#06070a", 0.9);
  brush.line(-250, 0, -15, 0);
  pop();

  // Now draw the Steel Ruler itself
  push();
  translate(cx, cy);
  rotate(tilt);

  let rulerRect = [
    [-hL, -hW],
    [hL, -hW],
    [hL, hW],
    [-hL, hW]
  ];

  // 1. Solid metallic base
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.wash("#9ca7b5", 254);
  drawPolyShape(rulerRect);
  brush.noWash();

  // 2. Anisotropic specular reflection bands & dark graphite-steel reflection troughs
  let bands = [
    { x1: -hL, x2: -310, col: "#7d8896", alpha: 140 },
    { x1: -320, x2: -195, col: "#e6eef7", alpha: 175 }, // bright glint 1
    { x1: -210, x2: -85, col: "#555f6b", alpha: 155 },  // dark reflection trough
    { x1: -100, x2: 35, col: "#b8c3d1", alpha: 135 },
    { x1: 20, x2: 145, col: "#eef5fc", alpha: 185 },    // bright glint 2
    { x1: 130, x2: 265, col: "#5d6775", alpha: 145 },   // dark trough 2
    { x1: 250, x2: hL, col: "#c4cfdc", alpha: 140 }
  ];

  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.25, 0.1);
  for (let b of bands) {
    brush.fill(b.col, b.alpha);
    drawPolyShape([
      [b.x1, -hW],
      [b.x2, -hW],
      [b.x2 - 18, hW],
      [b.x1 - 18, hW]
    ]);
  }

  // Subtle chromatic reflections on the brushed steel from nearby vivid objects:
  // Warm terracotta reflection near the brick (-290 to -140)
  brush.fill("#d46a59", 52);
  drawPolyShape([
    [-290, -4],
    [-140, -4],
    [-155, hW],
    [-305, hW]
  ]);

  // Warm cadmium-yellow reflection near the sticky note (+50 to +220)
  brush.fill("#f5dc64", 58);
  drawPolyShape([
    [50, -hW],
    [220, -hW],
    [205, 4],
    [35, 4]
  ]);
  brush.noFill();

  // 3. Longitudinal brushed stainless-steel micro-grain lines
  for (let i = 0; i < 190; i++) {
    let y = random(-hW + 1.5, hW - 1.5);
    let x1 = random(-hL + 4, hL - 90);
    let x2 = min(hL - 4, x1 + random(45, 240));
    let r = random();
    let col = r < 0.4 ? "#ffffff" : (r < 0.75 ? "#697382" : "#cfd9e6");
    brush.set("steel_hairline", col, random(0.28, 0.55));
    brush.line(x1, y, x2, y);
  }

  // Intense mirror-white diagonal specular highlights
  for (let gx of [-255, 82, 345]) {
    for (let i = -8; i <= 8; i++) {
      let y1 = -hW + 2;
      let y2 = hW - 2;
      brush.set("steel_hairline", "#ffffff", 0.55);
      brush.line(gx + i * 1.8, y1, gx - 14 + i * 1.8, y2);
    }
  }

  // 4. Precision photo-etched metric graduations along top edge (-hW)
  // and imperial graduations along bottom edge (+hW)
  let startX = -hL + 64;
  let endX = hL - 22;

  // Metric ticks (top edge): 1mm = 2.6px
  let mmStep = 2.6;
  let mmCount = int((endX - startX) / mmStep);
  for (let m = 0; m <= mmCount; m++) {
    let tx = startX + m * mmStep;
    let tickLen = 5.5;
    let wMult = 0.42;
    let col = "#1d2229";

    if (m % 10 === 0) {
      tickLen = 14.5;
      wMult = 0.62;
    } else if (m % 5 === 0) {
      tickLen = 9.5;
      wMult = 0.5;
    }

    brush.set("steel_hairline", col, wMult);
    brush.line(tx, -hW + 0.8, tx, -hW + tickLen);

    // Engraved micro-numerals every 10mm (1cm)
    if (m > 0 && m % 10 === 0) {
      let cmVal = m / 10;
      drawEngravedNumber(tx - 3, -hW + 18.5, cmVal);
    }
  }

  // Imperial ticks (bottom edge): 1/16 inch = 4.1px
  let inStep = 4.1;
  let inCount = int((endX - startX) / inStep);
  for (let k = 0; k <= inCount; k++) {
    let tx = startX + k * inStep;
    let tickLen = 4.5;
    let wMult = 0.4;

    if (k % 16 === 0) {
      tickLen = 13.5;
      wMult = 0.62;
    } else if (k % 8 === 0) {
      tickLen = 10.0;
      wMult = 0.52;
    } else if (k % 4 === 0) {
      tickLen = 7.2;
      wMult = 0.45;
    }

    brush.set("steel_hairline", "#1d2229", wMult);
    brush.line(tx, hW - 0.8, tx, hW - tickLen);
  }

  // Center longitudinal etched calibration line near left end
  brush.set("steel_hairline", "#2b323b", 0.45);
  brush.line(-hL + 16, 0, -hL + 54, 0);

  // 5. Circular hanging hole near the upper-left end (-hL + 34, 0)
  let holeX = -hL + 34;
  brush.noStroke();
  // Reveal the pale warm-grey plaster wall through the hole
  brush.wash("#dbd6ce", 255);
  brush.circle(holeX, 0, 8.5, 0.08);
  brush.noWash();

  // Inner metallic thickness rim of the punched hole
  brush.set("slate_cleave", "#20262e", 0.95);
  brush.arc(holeX + 0.8, 0.8, 8.6, 145, 335);

  brush.set("steel_hairline", "#ffffff", 0.95);
  brush.arc(holeX - 0.5, -0.5, 8.8, -35, 140);

  // 6. 3D razor-thin metallic edge bevels of the steel rule
  // Sunlit top & left edges
  brush.set("steel_hairline", "#ffffff", 1.15);
  brush.line(-hL, -hW, hL, -hW);
  brush.line(-hL, -hW, -hL, hW);

  // Dark steel thickness bottom & right edges
  brush.set("slate_cleave", "#181d24", 1.05);
  brush.line(-hL, hW, hL, hW);
  brush.line(hL, -hW, hL, hW);

  brush.set("steel_hairline", "#626d7a", 0.65);
  brush.line(-hL + 1, hW + 1.2, hL, hW + 1.2);

  pop();
}

// Micro vector-stroke numerals for the engraved steel ruler
function drawEngravedNumber(x, y, num) {
  let str = String(num);
  for (let c = 0; c < str.length; c++) {
    let d = str[c];
    let ox = x + c * 4.2;
    let oy = y;
    brush.set("steel_hairline", "#1e232a", 0.38);

    if (d === "0") {
      brush.rect(ox, oy - 2.5, 2.6, 5.0);
    } else if (d === "1") {
      brush.line(ox + 1.3, oy - 2.5, ox + 1.3, oy + 2.5);
    } else if (d === "2") {
      brush.line(ox, oy - 2.5, ox + 2.5, oy - 2.5);
      brush.line(ox + 2.5, oy - 2.5, ox + 2.5, oy);
      brush.line(ox + 2.5, oy, ox, oy);
      brush.line(ox, oy, ox, oy + 2.5);
      brush.line(ox, oy + 2.5, ox + 2.5, oy + 2.5);
    } else if (d === "3") {
      brush.line(ox, oy - 2.5, ox + 2.5, oy - 2.5);
      brush.line(ox + 2.5, oy - 2.5, ox + 2.5, oy + 2.5);
      brush.line(ox, oy, ox + 2.5, oy);
      brush.line(ox, oy + 2.5, ox + 2.5, oy + 2.5);
    } else if (d === "4") {
      brush.line(ox, oy - 2.5, ox, oy);
      brush.line(ox, oy, ox + 2.5, oy);
      brush.line(ox + 2.2, oy - 2.5, ox + 2.2, oy + 2.5);
    } else if (d === "5") {
      brush.line(ox + 2.5, oy - 2.5, ox, oy - 2.5);
      brush.line(ox, oy - 2.5, ox, oy);
      brush.line(ox, oy, ox + 2.5, oy);
      brush.line(ox + 2.5, oy, ox + 2.5, oy + 2.5);
      brush.line(ox + 2.5, oy + 2.5, ox, oy + 2.5);
    } else if (d === "6") {
      brush.line(ox + 2.5, oy - 2.5, ox, oy - 2.5);
      brush.line(ox, oy - 2.5, ox, oy + 2.5);
      brush.line(ox, oy + 2.5, ox + 2.5, oy + 2.5);
      brush.line(ox + 2.5, oy + 2.5, ox + 2.5, oy);
      brush.line(ox + 2.5, oy, ox, oy);
    } else if (d === "7") {
      brush.line(ox, oy - 2.5, ox + 2.5, oy - 2.5);
      brush.line(ox + 2.5, oy - 2.5, ox + 0.8, oy + 2.5);
    } else if (d === "8") {
      brush.rect(ox, oy - 2.5, 2.5, 5.0);
      brush.line(ox, oy, ox + 2.5, oy);
    } else if (d === "9") {
      brush.rect(ox, oy - 2.5, 2.5, 2.5);
      brush.line(ox + 2.5, oy, ox + 2.5, oy + 2.5);
    }
  }
}

