async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4077);
  noiseSeed(4077);

  // Custom alcohol chisel marker for flat matte fields
  brush.add("chisel_marker", {
    type: "marker",
    weight: 4.8,
    scatter: 0.04,
    opacity: 16,
    spacing: 0.28,
    pressure: [0.95, 1.0, 0.95],
    rotate: "none",
    markerTip: false,
    noise: 0.12
  });

  // Ultra-soft shader glaze for 3D volumetric form modeling & cast shadows
  brush.add("shader_glaze", {
    type: "default",
    weight: 2.2,
    scatter: 0.22,
    sharpness: 0.08,
    grain: 0.22,
    opacity: 14,
    spacing: 0.22,
    pressure: [0.3, 1.0, 0.3],
    rotate: "natural",
    noise: 0.2
  });

  // Fine felt-tip micro nib for pore-level dots and shadow stippling
  brush.add("felttip_micro", {
    type: "custom",
    weight: 0.42,
    scatter: 0.02,
    opacity: 175,
    spacing: 0.5,
    pressure: [1.0, 1.0],
    tip: (_m) => {
      _m.circle(0, 0, 1.1);
    },
    rotate: "none",
    markerTip: false,
    noise: 0.05
  });

  // Medium felt-tip nib for protoporphyrin pigment speckles
  brush.add("felttip_dot", {
    type: "custom",
    weight: 0.72,
    scatter: 0.04,
    opacity: 195,
    spacing: 0.45,
    pressure: [0.9, 1.1, 0.9],
    tip: (_m) => {
      _m.circle(0, 0, 1.65);
    },
    rotate: "random",
    markerTip: false,
    noise: 0.1
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // 1. Studio Drafting Table Ground
  background("#DBD8D0");
  drawStudioSurface();

  // Card geometry
  const cardX = 272;
  const cardY = 30;
  const cardW = 656;
  const cardH = 1140;

  // 2. Trompe-l'oeil Drop Shadow & Card Stock Body
  drawCardShadowAndStock(cardX, cardY, cardW, cardH);

  // 3. Card Header & Registration Marks
  drawCardHeader(cardX, cardY, cardW);

  // 4. Seven Stacked Paint-Sample Bands + Hyperreal Eggs + Ruled Captions
  const chipX = cardX + 30; // 302
  const chipW = cardW - 60; // 596
  const startY = cardY + 56; // 86
  const unitH = 152;
  const chipH = 124;
  const capH = 28;

  for (let i = 0; i < SWATCHES.length; i++) {
    const sw = SWATCHES[i];
    const chipY = startY + i * unitH;
    const capY = chipY + chipH;

    // A. Flat Alcohol-Marker Swatch Band (knife-clean clipped edges)
    drawAlcoholMarkerChip(sw, chipX, chipY, chipW, chipH);

    // B. Hyperreal Egg + Soft Cast Shadow + Pore-level Felt-tip Speckling
    const eggCX = chipX + chipW * 0.5 + sw.eggOffsetX;
    const eggCY = chipY + chipH * 0.475;
    const eggA = 73.5; // horizontal semi-axis
    const eggB = 53.5; // vertical semi-axis (height ~107px inside 124px band)
    drawHyperrealEgg(sw, eggCX, eggCY, eggA, eggB, chipX, chipY, chipW, chipH, i);

    // C. Knife-clean Chip Frame & Ruled Pen Caption Strip
    drawCaptionStrip(sw, chipX, chipY, chipW, chipH, capY, capH);
  }

  // 5. Final Knife-Clean Outer Card Bevel
  drawCardBevel(cardX, cardY, cardW, cardH);

  noLoop();
}

// ============================================================================
// COLOR HELPERS
// ============================================================================
function hexToRgb(hex) {
  let h = hex.replace("#", "");
  if (h.length === 3) {
    h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  }
  const num = parseInt(h, 16);
  return [(num >> 16) & 255, (num >> 8) & 255, num & 255];
}

function rgbToHex(r, g, b) {
  const clamp = (v) => Math.max(0, Math.min(255, Math.round(v)));
  return (
    "#" +
    [clamp(r), clamp(g), clamp(b)]
      .map((x) => x.toString(16).padStart(2, "0"))
      .join("")
  );
}

function mixHex(h1, h2, t) {
  const c1 = hexToRgb(h1);
  const c2 = hexToRgb(h2);
  const u = Math.max(0, Math.min(1, t));
  return rgbToHex(
    c1[0] + (c2[0] - c1[0]) * u,
    c1[1] + (c2[1] - c1[1]) * u,
    c1[2] + (c2[2] - c1[2]) * u
  );
}

function shiftHex(hex, delta) {
  const c = hexToRgb(hex);
  return rgbToHex(c[0] + delta, c[1] + delta, c[2] + delta);
}

// ============================================================================
// STUDIO SURFACE, CARD STOCK & HEADER
// ============================================================================
function drawStudioSurface() {
  brush.noField();
  brush.noStroke();
  // Subtle ambient vignette on left and right studio table margins
  brush.fill("#CFCBC2", 45);
  brush.fillBleed(0.35);
  brush.fillTexture(0.35, 0.15);
  brush.rect(0, 0, 250, 1200, "corner");
  brush.rect(950, 0, 250, 1200, "corner");
  brush.noFill();

  // Sparse architectural drafting table grain on exposed left/right margins
  brush.set("2H", "#C4C0B6", 0.2);
  for (let i = 0; i < 180; i++) {
    const onLeft = i % 2 === 0;
    const x = onLeft ? random(14, 262) : random(938, 1186);
    const y = random(16, 1184);
    const len = random(8, 28);
    brush.line(x, y, x + len, y + random(-0.5, 0.5));
  }
}

function drawCardShadowAndStock(cardX, cardY, cardW, cardH) {
  brush.noField();
  brush.noStroke();

  // Multi-layered soft cast shadow under right and bottom edges of card stock
  for (let pass = 7; pass >= 1; pass--) {
    const ox = pass * 2.1;
    const oy = pass * 2.4;
    const alpha = map(pass, 1, 7, 36, 9);
    brush.wash("#9E998F", alpha);
    brush.rect(cardX + ox, cardY + oy, cardW, cardH, "corner");
  }
  brush.noWash();

  // Tight dark ambient occlusion crevice right along right and bottom edges
  brush.set("shader_glaze", "#6E6960", 0.55);
  brush.line(cardX + cardW + 1.5, cardY + 4, cardX + cardW + 1.5, cardY + cardH + 2);
  brush.line(cardX + 4, cardY + cardH + 1.5, cardX + cardW + 2, cardY + cardH + 1.5);

  // Heavy matte archival card stock base
  brush.noStroke();
  brush.wash("#F7F4EC", 255);
  brush.rect(cardX, cardY, cardW, cardH, "corner");
  brush.noWash();

  // Ultra-subtle printed card stock tooth along the side margins
  brush.clip([cardX, cardY, cardX + cardW, cardY + cardH]);
  brush.set("chisel_marker", "#F2EFE6", 1.1);
  for (let y = cardY + 8; y < cardY + cardH; y += 22) {
    brush.line(cardX, y, cardX + cardW, y);
  }
  brush.noClip();
}

function drawCardHeader(cardX, cardY, cardW) {
  const centerX = cardX + cardW * 0.5;
  const holeY = cardY + 24;
  const holeR = 9.5;

  // Die-cut swatch-card hanging hole showing studio table beneath
  brush.noStroke();
  brush.wash("#CECAC1", 255);
  brush.circle(centerX, holeY, holeR, 0.02);
  brush.noWash();

  // Inner card-stock thickness crescent inside the punched hole
  brush.set("rotring", "#8F8A80", 0.35);
  brush.arc(centerX, holeY, holeR, 195, 345);
  brush.set("rotring", "#FFFFFF", 0.32);
  brush.arc(centerX, holeY, holeR, 15, 165);

  // Header ruled lines
  const leftX = cardX + 30;
  const rightX = cardX + cardW - 30;
  brush.set("2H", "#D4CDC0", 0.22);
  brush.line(leftX, cardY + 21, centerX - 24, cardY + 21);
  brush.line(leftX, cardY + 28, centerX - 24, cardY + 28);
  brush.line(centerX + 24, cardY + 21, rightX - 22, cardY + 21);
  brush.line(centerX + 24, cardY + 28, rightX - 22, cardY + 28);

  // Header micro-typography
  drawMicroText(
    "CHROMATIC ARCHIVE  /  GALLUS SHELL STUDY",
    leftX,
    cardY + 21,
    6.5,
    1.8,
    "#4A433B",
    0.26
  );

  drawMicroText(
    "SERIES IV  -  CALCIUM OXIDE",
    centerX + 56,
    cardY + 21,
    6.5,
    1.8,
    "#4A433B",
    0.26
  );

  // Terracotta accent calibration dot & registration crosshair in top-right header
  const regX = rightX - 8;
  const regY = cardY + 24.5;
  brush.noStroke();
  brush.wash("#B85A38", 255);
  brush.circle(regX, regY, 4.2, 0.02);
  brush.noWash();

  brush.set("rotring", "#4A433B", 0.24);
  brush.line(regX - 7, regY, regX - 4.8, regY);
  brush.line(regX + 4.8, regY, regX + 7, regY);
  brush.line(regX, regY - 7, regX, regY - 4.8);
  brush.line(regX, regY + 4.8, regX, regY + 7);

  // Top divider rule above Chip 01
  brush.set("rotring", "#B5ADA0", 0.26);
  brush.line(leftX, cardY + 46, rightX, cardY + 46);
}

function drawCardBevel(cardX, cardY, cardW, cardH) {
  brush.noField();
  // Lit top and left cut paper edges
  brush.set("rotring", "#FFFFFF", 0.38);
  brush.line(cardX, cardY, cardX + cardW, cardY);
  brush.line(cardX, cardY, cardX, cardY + cardH);

  // Shaded right and bottom cut paper edges
  brush.set("rotring", "#9E978C", 0.34);
  brush.line(cardX + cardW, cardY, cardX + cardW, cardY + cardH);
  brush.line(cardX, cardY + cardH, cardX + cardW, cardY + cardH);
}

// ============================================================================
// ALCOHOL-MARKER SWATCH BAND
// ============================================================================
function drawAlcoholMarkerChip(sw, chipX, chipY, chipW, chipH) {
  brush.noField();
  brush.clip([chipX, chipY, chipX + chipW, chipY + chipH]);

  // 1. Exact solid base pigment pass
  brush.noStroke();
  brush.wash(sw.base, 255);
  brush.rect(chipX - 2, chipY - 2, chipW + 4, chipH + 4, "corner");
  brush.noWash();

  // 2. Flat alcohol-marker horizontal chisel strokes (characteristic overlapping bands)
  const warmPass = shiftHex(sw.base, 3);
  const coolPass = shiftHex(sw.base, -3);
  let row = 0;
  for (let y = chipY + 2; y <= chipY + chipH - 2; y += 5.2) {
    const col = row % 2 === 0 ? warmPass : coolPass;
    brush.set("chisel_marker", col, 0.92);
    brush.line(chipX - 18, y, chipX + chipW + 18, y + random(-0.35, 0.35));
    row++;
  }

  // 3. Subtle alcohol-ink edge pooling along the knife-clean perimeter of the swatch
  brush.set("shader_glaze", sw.coreShadow, 0.38);
  brush.line(chipX, chipY + 1, chipX + chipW, chipY + 1);
  brush.line(chipX, chipY + chipH - 1, chipX + chipW, chipY + chipH - 1);

  brush.noClip();
}

// ============================================================================
// 3D EGG GEOMETRY, VOLUMETRIC SHADING, CAST SHADOW & PORE SPECKLING
// ============================================================================
// Asymmetric hen egg radius profile R(u) for u in [-a, a]
function eggRadiusAt(u, a, b, flipEnd) {
  const t = constrain(u / a, -1, 1);
  const asym = 1 - 0.135 * t * flipEnd;
  return b * Math.sqrt(Math.max(0, 1 - t * t)) * asym;
}

// Transform local (u, v) to canvas (x, y)
function eggLocalToWorld(u, v, cx, cy, cosT, sinT) {
  return [cx + u * cosT - v * sinT, cy + u * sinT + v * cosT];
}

// Compute 3D unit normal (nx, ny, nz) at local (u, v) on egg surface
function eggNormalAt(u, v, a, b, flipEnd, cosT, sinT) {
  const R = eggRadiusAt(u, a, b, flipEnd);
  if (R <= 0.001) return [0, 0, 1];
  const z2 = Math.max(0, R * R - v * v);
  const z = Math.sqrt(z2);

  // Derivative dR/du
  const eps = 0.5;
  const Rplus = eggRadiusAt(Math.min(a * 0.999, u + eps), a, b, flipEnd);
  const Rminus = eggRadiusAt(Math.max(-a * 0.999, u - eps), a, b, flipEnd);
  const dRdu = (Rplus - Rminus) / (2 * eps);

  // Unnormalized normal in local coordinates: (-R * dR/du, v, z)
  const lnx = -R * dRdu;
  const lny = v;
  const lnz = z;
  const mag = Math.sqrt(lnx * lnx + lny * lny + lnz * lnz) || 1;
  const unx = lnx / mag;
  const uny = lny / mag;
  const unz = lnz / mag;

  // Rotate (unx, uny) by egg tilt
  const wnx = unx * cosT - uny * sinT;
  const wny = unx * sinT + uny * cosT;
  return [wnx, wny, unz];
}

function drawHyperrealEgg(sw, cx, cy, a, b, chipX, chipY, chipW, chipH, eggIdx) {
  const tiltRad = (sw.eggTilt * Math.PI) / 180;
  const cosT = Math.cos(tiltRad);
  const sinT = Math.sin(tiltRad);
  const hiColor = sw.highlightHex || sw.highlight;

  // Light vector (from upper-left studio softbox)
  const Lx = -0.51;
  const Ly = -0.57;
  const Lz = 0.644; // normalized

  // Half-vector H for specular sheen (viewer at (0, 0, 1))
  const Hmag = Math.sqrt(Lx * Lx + Ly * Ly + (Lz + 1) * (Lz + 1));
  const Hx = Lx / Hmag;
  const Hy = Ly / Hmag;
  const Hz = (Lz + 1) / Hmag;

  // Clip egg + shadow to the horizontal swatch band so edges stay knife-clean
  brush.clip([chipX, chipY, chipX + chipW, chipY + chipH]);

  // --------------------------------------------------------------------------
  // STEP 1: SOFT CAST SHADOW ON THE SWATCH BAND
  // --------------------------------------------------------------------------
  const shCenterX = cx + 26;
  const shCenterY = cy + 25;
  const shA = a * 0.96;
  const shB = b * 0.72;
  const shAngle = sw.eggTilt + 9;
  const shRad = (shAngle * Math.PI) / 180;
  const shCos = Math.cos(shRad);
  const shSin = Math.sin(shRad);

  // Layered soft penumbra rings using shader_glaze
  for (let ring = 26; ring >= 1; ring--) {
    const frac = ring / 26;
    const ra = shA * (0.32 + 0.86 * frac);
    const rb = shB * (0.28 + 0.88 * frac);
    const col = frac > 0.55 ? sw.castShadow : mixHex(sw.castDeep, sw.castShadow, frac / 0.55);
    const weight = map(frac, 0, 1, 0.85, 1.35);

    brush.set("shader_glaze", col, weight);
    brush.beginShape(0.45);
    const steps = 28;
    for (let s = 0; s <= steps; s++) {
      const ang = (s / steps) * Math.PI * 2;
      const su = Math.cos(ang) * ra * (1 - 0.1 * Math.cos(ang) * sw.flipEnd);
      const sv = Math.sin(ang) * rb;
      // Offset deeper shadow toward bottom-right contact zone
      const px = shCenterX + su * shCos - sv * shSin;
      const py = shCenterY + su * shSin + sv * shCos;
      brush.vertex(px, py);
    }
    brush.endShape(true);
  }

  // Fine felt-tip dot stippling across the cast shadow & penumbra
  // (Pulls the shadow forward with tactile felt-tip grain)
  const shadowDots = 560;
  for (let d = 0; d < shadowDots; d++) {
    // Concentrate dots near the umbra and feather out into the swatch penumbra
    const rNorm = Math.pow(random(), 0.72) * 1.22;
    const ang = random(0, 360) * (Math.PI / 180);
    const su = Math.cos(ang) * shA * rNorm * (1 - 0.1 * Math.cos(ang) * sw.flipEnd);
    const sv = Math.sin(ang) * shB * rNorm;
    const px = shCenterX + su * shCos - sv * shSin;
    const py = shCenterY + su * shSin + sv * shCos;

    // Skip dots that land well inside the upper-left lit half of the egg
    const dx = px - cx;
    const dy = py - cy;
    const lu = dx * cosT + dy * sinT;
    const lv = -dx * sinT + dy * cosT;
    const rEgg = eggRadiusAt(lu, a, b, sw.flipEnd);
    if (Math.abs(lu) < a * 0.96 && Math.abs(lv) < rEgg * 0.95) continue;

    const dotCol = rNorm < 0.65 ? sw.castDeep : (rNorm < 0.95 ? sw.castShadow : sw.coreShadow);
    const w = map(rNorm, 0, 1.22, 0.44, 0.24);
    brush.set("felttip_micro", dotCol, w);
    brush.line(px, py, px + 0.35, py + 0.25);
  }

  // --------------------------------------------------------------------------
  // STEP 2: EGG BASE SILHOUETTE (Exact Swatch Match so Mid-Tones Dissolve)
  // --------------------------------------------------------------------------
  // Re-establish the clean egg interior over the inner half of the cast shadow
  brush.noStroke();
  brush.wash(sw.base, 255);
  brush.beginShape(0.35);
  const silSteps = 64;
  for (let s = 0; s < silSteps; s++) {
    const ang = (s / silSteps) * Math.PI * 2;
    const u = Math.cos(ang) * a;
    const R = eggRadiusAt(u, a, b, sw.flipEnd);
    const v = Math.sin(ang) * R;
    const [wx, wy] = eggLocalToWorld(u, v, cx, cy, cosT, sinT);
    brush.vertex(wx, wy);
  }
  brush.endShape(true);
  brush.noWash();

  // Re-lay matching horizontal alcohol-marker passes inside the egg silhouette
  // so its mid-tone texture is 100% continuous with its background swatch!
  const warmPass = shiftHex(sw.base, 3);
  const coolPass = shiftHex(sw.base, -3);
  let mRow = 0;
  for (let y = cy - b; y <= cy + b; y += 5.2) {
    // Approximate horizontal chord across egg at this y
    const dy = y - cy;
    if (Math.abs(dy) >= b * 0.98) continue;
    const halfSpan = a * Math.sqrt(Math.max(0, 1 - (dy / b) * (dy / b)));
    const col = mRow % 2 === 0 ? warmPass : coolPass;
    brush.set("chisel_marker", col, 0.85);
    brush.line(cx - halfSpan * 0.94, y, cx + halfSpan * 0.94, y);
    mRow++;
  }

  // --------------------------------------------------------------------------
  // STEP 3: 3D VOLUMETRIC FORM MODELING (Highlight, Terminator, Bounce Light)
  // --------------------------------------------------------------------------
  // Illumination level that equals the flat background swatch is ~0.50.
  // We leave the mid-tone band (0.45..0.55) untouched so the egg dissolves into its chip!
  const uSlices = 46;
  const vSegs = 26;

  for (let iu = 1; iu < uSlices; iu++) {
    const u = map(iu, 0, uSlices, -a * 0.97, a * 0.97);
    const R = eggRadiusAt(u, a, b, sw.flipEnd);
    if (R < 3) continue;

    for (let iv = 0; iv < vSegs; iv++) {
      const v0 = map(iv, 0, vSegs, -R * 0.985, R * 0.985);
      const v1 = map(iv + 1, 0, vSegs, -R * 0.985, R * 0.985);
      const vMid = 0.5 * (v0 + v1);

      const [nx, ny, nz] = eggNormalAt(u, vMid, a, b, sw.flipEnd, cosT, sinT);
      const ndotl = Math.max(0, nx * Lx + ny * Ly + nz * Lz);
      const ndoth = Math.max(0, nx * Hx + ny * Hy + nz * Hz);
      const spec = Math.pow(ndoth, 18) * sw.sheenStrength;

      // Reflected light from the colored swatch card along the lower-right rim
      const bounceFactor =
        Math.pow(1 - nz, 1.8) * Math.max(0, 0.55 * ny + 0.45 * nx);

      // Effective illumination metric
      const illum = ndotl * 0.86 + 0.10 + spec * 0.38;

      // Skip the camouflaged mid-tone zone where egg dissolves into the swatch!
      if (illum > 0.44 && illum < 0.56 && nz > 0.28) continue;

      let strokeCol;
      let strokeW;

      if (illum >= 0.56) {
        // Upper-left lit crown & satin cuticle sheen
        const t = constrain((illum - 0.56) / 0.48, 0, 1);
        strokeCol = mixHex(sw.base, hiColor, Math.pow(t, 0.82));
        if (spec > 0.12) {
          strokeCol = mixHex(strokeCol, sw.sheen, constrain(spec * 1.3, 0, 0.85));
        }
        strokeW = map(t, 0, 1, 0.45, 0.95);
      } else {
        // Core shadow terminator & lower-right bounce light
        const shadowDepth = constrain((0.44 - illum) / 0.36, 0, 1);
        strokeCol = mixHex(sw.base, sw.coreShadow, Math.pow(shadowDepth, 0.85));
        // Blend in reflected bounce light near the lower rim
        if (bounceFactor > 0.08) {
          strokeCol = mixHex(
            strokeCol,
            sw.reflected,
            constrain(bounceFactor * 0.72, 0, 0.58)
          );
        }
        // Deepen grazing shadow near the bottom occlusion crevice
        if (nz < 0.26 && ny > 0.15) {
          strokeCol = mixHex(strokeCol, sw.rimDark, constrain((0.26 - nz) * 2.8, 0, 0.75));
        }
        strokeW = map(shadowDepth, 0, 1, 0.48, 0.92);
      }

      const [x0, y0] = eggLocalToWorld(u, v0, cx, cy, cosT, sinT);
      const [x1, y1] = eggLocalToWorld(u, v1, cx, cy, cosT, sinT);

      brush.set("shader_glaze", strokeCol, strokeW);
      brush.line(x0, y0, x1, y1);
    }
  }

  // Longitudinal meridian glazes along the crown and terminator for seamless smoothness
  const mRings = 16;
  for (let ir = 1; ir <= mRings; ir++) {
    const vFrac = map(ir, 1, mRings, -0.94, 0.94);
    // Focus meridian passes on the upper crown (vFrac < -0.25) and lower terminator (vFrac > 0.2)
    if (vFrac > -0.22 && vFrac < 0.18) continue;

    const isLit = vFrac < 0;
    const col = isLit
      ? mixHex(sw.base, hiColor, map(vFrac, -0.22, -0.94, 0.25, 0.82))
      : mixHex(sw.base, sw.coreShadow, map(vFrac, 0.18, 0.94, 0.25, 0.88));

    brush.set("shader_glaze", col, 0.62);
    brush.beginShape(0.4);
    const uSteps = 20;
    for (let s = 0; s <= uSteps; s++) {
      const u = map(s, 0, uSteps, -a * 0.92, a * 0.92);
      const R = eggRadiusAt(u, a, b, sw.flipEnd);
      const v = vFrac * R;
      const [wx, wy] = eggLocalToWorld(u, v, cx, cy, cosT, sinT);
      brush.vertex(wx, wy);
    }
    brush.endShape(false);
  }

  // --------------------------------------------------------------------------
  // STEP 4: AMBIENT OCCLUSION CREVICE & LOST-AND-FOUND RIM CONTOUR
  // --------------------------------------------------------------------------
  // Tight contact shadow directly beneath the lower belly of the egg
  brush.set("rotring", sw.castDeep, 0.34);
  brush.beginShape(0.35);
  for (let angDeg = 18; angDeg <= 152; angDeg += 6) {
    const ang = (angDeg * Math.PI) / 180;
    const u = Math.cos(ang) * a;
    const R = eggRadiusAt(u, a, b, sw.flipEnd);
    const v = Math.sin(ang) * (R + 0.6);
    const [wx, wy] = eggLocalToWorld(u, v, cx, cy, cosT, sinT);
    brush.vertex(wx, wy);
  }
  brush.endShape(false);

  // Softer secondary occlusion feather line
  brush.set("shader_glaze", sw.castShadow, 0.55);
  brush.beginShape(0.35);
  for (let angDeg = 8; angDeg <= 165; angDeg += 7) {
    const ang = (angDeg * Math.PI) / 180;
    const u = Math.cos(ang) * a;
    const R = eggRadiusAt(u, a, b, sw.flipEnd);
    const v = Math.sin(ang) * (R + 1.5);
    const [wx, wy] = eggLocalToWorld(u, v, cx, cy, cosT, sinT);
    brush.vertex(wx, wy);
  }
  brush.endShape(false);

  // Delicate grazing rim-light along the upper-left curve (fades into lost edge at poles)
  brush.set("2H", hiColor, 0.32);
  brush.beginShape(0.35);
  for (let angDeg = 202; angDeg <= 292; angDeg += 6) {
    const ang = (angDeg * Math.PI) / 180;
    const u = Math.cos(ang) * a;
    const R = eggRadiusAt(u, a, b, sw.flipEnd);
    const v = Math.sin(ang) * (R - 0.3);
    const [wx, wy] = eggLocalToWorld(u, v, cx, cy, cosT, sinT);
    brush.vertex(wx, wy);
  }
  brush.endShape(false);

  // --------------------------------------------------------------------------
  // STEP 5: PORE-LEVEL FELT-TIP SPECKLING (Pulling the 3D Egg Forward)
  // --------------------------------------------------------------------------
  // A. Microscopic respiratory pores across the entire 3D hemisphere
  // Sampled with 3D surface foreshortening so density increases naturally near the curved limb!
  const poreCount = Math.round(920 + sw.speckleDensity * 420);
  for (let p = 0; p < poreCount; p++) {
    // Sample on 3D hemisphere so projection onto (u, v) foreshortens near edges
    const theta = random(0, 360) * (Math.PI / 180);
    // Slight bias toward grazing angles (sin(phi)) creates natural optical limb density
    const sinPhi = Math.pow(random(), 0.56);
    const u = Math.cos(theta) * a * sinPhi;
    const R = eggRadiusAt(u, a, b, sw.flipEnd);
    const v = Math.sin(theta) * R * sinPhi;

    const [nx, ny, nz] = eggNormalAt(u, v, a, b, sw.flipEnd, cosT, sinT);
    const ndotl = Math.max(0, nx * Lx + ny * Ly + nz * Lz);
    const [wx, wy] = eggLocalToWorld(u, v, cx, cy, cosT, sinT);

    // Local noise for organic pore clustering
    const nVal = noise(
      (u + a) * 0.055 + eggIdx * 13.1,
      (v + b) * 0.055 + eggIdx * 7.7
    );
    if (nVal < 0.24 && random() < 0.65) continue;

    // Modulate pore color by 3D illumination zone
    let poreCol;
    if (ndotl > 0.62) {
      poreCol = sw.speckleMid;
    } else if (ndotl > 0.34) {
      poreCol = mixHex(sw.speckleDark, sw.speckleMid, 0.45);
    } else {
      poreCol = sw.speckleDark;
    }

    const poreW = random(0.24, 0.44) * (0.7 + 0.3 * nz);
    brush.set("felttip_micro", poreCol, poreW);
    brush.line(wx, wy, wx + 0.32, wy + 0.25);

    // In raking light near the crown/terminator, add a microscopic sunlit pore rim fleck
    if (ndotl > 0.48 && ndotl < 0.78 && random() < 0.22) {
      brush.set("felttip_micro", sw.speckleLight, 0.24);
      brush.line(wx + 0.55, wy + 0.55, wx + 0.8, wy + 0.75);
    }
  }

  // B. Protoporphyrin Pigment Speckles & Felt-Tip Clusters (Grading from subtle to rich chocolate)
  const clusterCount = Math.round(140 * sw.clusterStrength + 30);
  for (let c = 0; c < clusterCount; c++) {
    const theta = random(0, 360) * (Math.PI / 180);
    const rad = Math.pow(random(), 0.62);
    let u = Math.cos(theta) * a * rad;

    // Biological detail: hen eggs often have a slightly denser crown of speckles toward the blunt end
    if (random() < 0.35) {
      u = lerp(u, -sw.flipEnd * a * random(0.25, 0.78), 0.55);
    }
    const R = eggRadiusAt(u, a, b, sw.flipEnd);
    const v = Math.sin(theta) * R * rad;
    if (Math.abs(v) >= R * 0.97) continue;

    // 3D noise mask for realistic constellation patterns
    const patchNoise = noise(
      u * 0.04 + eggIdx * 23.4,
      v * 0.04 + eggIdx * 19.1
    );
    if (patchNoise < 0.36) continue;

    const [nx, ny, nz] = eggNormalAt(u, v, a, b, sw.flipEnd, cosT, sinT);
    const ndotl = Math.max(0, nx * Lx + ny * Ly + nz * Lz);
    const [wx, wy] = eggLocalToWorld(u, v, cx, cy, cosT, sinT);

    // Choose speckle pigment tone modulated by 3D lighting
    const spCol =
      ndotl > 0.65
        ? mixHex(sw.speckleDark, sw.speckleMid, 0.5)
        : ndotl < 0.28
        ? mixHex(sw.speckleDark, sw.castDeep, 0.4)
        : sw.speckleDark;

    // Build each larger speckle from a tight cluster of fine felt-tip dots
    // Foreshorten cluster spread perpendicular to the limb when nz is small
    const dotsInCluster = Math.floor(random(2, 4 + sw.clusterStrength * 6));
    const spread = random(0.45, 1.35 + sw.clusterStrength * 1.1);

    for (let k = 0; k < dotsInCluster; k++) {
      const ox = random(-spread, spread) * (0.45 + 0.55 * Math.abs(ny));
      const oy = random(-spread, spread) * (0.45 + 0.55 * nz);
      const dw = random(0.28, 0.56) * (0.65 + 0.35 * nz);
      const brushName = k === 0 && sw.clusterStrength > 0.45 ? "felttip_dot" : "felttip_micro";
      brush.set(brushName, spCol, dw);
      brush.line(wx + ox, wy + oy, wx + ox + 0.35, wy + oy + 0.28);
    }
  }

  // C. Calcified Lilac-Cream Cuticle Pinpricks & Micro-Specular Sheen Glints
  const calciumCount = Math.round(55 + sw.speckleDensity * 75);
  for (let m = 0; m < calciumCount; m++) {
    const theta = random(0, 360) * (Math.PI / 180);
    const rad = Math.pow(random(), 0.65);
    const u = Math.cos(theta) * a * rad;
    const R = eggRadiusAt(u, a, b, sw.flipEnd);
    const v = Math.sin(theta) * R * rad;

    const [nx, ny, nz] = eggNormalAt(u, v, a, b, sw.flipEnd, cosT, sinT);
    const ndotl = Math.max(0, nx * Lx + ny * Ly + nz * Lz);
    const ndoth = Math.max(0, nx * Hx + ny * Hy + nz * Hz);
    const [wx, wy] = eggLocalToWorld(u, v, cx, cy, cosT, sinT);

    if (ndoth > 0.91) {
      // Crisp micro-cuticle specular glint in the upper-left highlight zone
      brush.set("felttip_micro", sw.sheen, random(0.28, 0.48));
      brush.line(wx, wy, wx + 0.35, wy + 0.25);
    } else if (ndotl > 0.28) {
      // Tiny calcified deposit dot
      brush.set("felttip_micro", sw.calcium, random(0.22, 0.36));
      brush.line(wx, wy, wx + 0.28, wy + 0.22);
    }
  }

  brush.noClip();
}

// ============================================================================
// KNIFE-CLEAN CHIP BORDER & RULED PEN CAPTION STRIP
// ============================================================================
function drawCaptionStrip(sw, chipX, chipY, chipW, chipH, capY, capH) {
  brush.noField();

  // 1. Knife-clean hairline frame around the alcohol-marker chip
  const frameCol = mixHex(sw.coreShadow, "#8C8478", 0.45);
  brush.set("rotring", frameCol, 0.26);
  brush.line(chipX, chipY, chipX + chipW, chipY);
  brush.line(chipX, chipY + chipH, chipX + chipW, chipY + chipH);
  brush.line(chipX, chipY, chipX, chipY + chipH);
  brush.line(chipX + chipW, chipY, chipX + chipW, chipY + chipH);

  // 2. Architect's faint ruled pencil guidelines inside the caption strip
  const ruleTop = capY + 8.5;
  const ruleBot = capY + 15.0;
  brush.set("2H", "#D6CFC3", 0.20);
  brush.line(chipX, ruleTop, chipX + chipW, ruleTop);
  brush.line(chipX, ruleBot, chipX + chipW, ruleBot);

  // Tiny vertical registration ticks at left, middle, and right of the ruled line
  brush.set("rotring", "#ACA498", 0.22);
  brush.line(chipX, ruleTop - 2, chipX, ruleBot + 2);
  brush.line(chipX + 36, ruleTop - 1.5, chipX + 36, ruleBot + 1.5);
  brush.line(chipX + chipW, ruleTop - 2, chipX + chipW, ruleBot + 2);

  // 3. Tiny Ruled Pen Caption (Index + Invented Paint Name + Pigment/LRV Spec)
  const textY = ruleTop + 0.3;
  const capHeight = 6.0;

  // Swatch number on the far left
  drawMicroText(
    "NO. " + sw.id,
    chipX + 5,
    textY,
    capHeight,
    1.5,
    "#36302A",
    0.27
  );

  // If this is the Terracotta Accent band (Chip 05), place a tiny crisp accent dot beside the name
  let nameStartX = chipX + 46;
  if (sw.isAccent) {
    brush.noStroke();
    brush.wash(sw.base, 255);
    brush.circle(nameStartX + 3, ruleTop + 3.2, 2.7, 0.02);
    brush.noWash();
    nameStartX += 11;
  }

  // Invented Paint Name
  drawMicroText(
    sw.name,
    nameStartX,
    textY,
    capHeight,
    1.95,
    sw.isAccent ? "#8C3519" : "#2B2520",
    0.29
  );

  // Center-right matching note
  drawMicroText(
    "ALCOHOL MARKER MATCH 1:1",
    chipX + 246,
    textY,
    5.6,
    1.5,
    "#7A7167",
    0.23
  );

  // Right-aligned technical pigment & LRV code
  const codeWidth = measureMicroText(sw.code, 5.6, 1.5);
  drawMicroText(
    sw.code,
    chipX + chipW - codeWidth - 5,
    textY,
    5.6,
    1.5,
    "#524A42",
    0.25
  );
}

// ============================================================================
// VECTOR TECHNICAL PEN MICRO-TYPOGRAPHY ENGINE
// ============================================================================
function measureMicroText(str, capH, tracking) {
  const charW = capH * 0.66;
  return str.length * (charW + tracking) - tracking;
}

function drawMicroText(str, startX, startY, capH, tracking, col, weight) {
  brush.noField();
  brush.set("rotring", col, weight);

  const charW = capH * 0.66;
  let curX = startX;

  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    if (ch === " ") {
      curX += charW * 0.72 + tracking;
      continue;
    }
    const strokes = GLYPHS[ch] || GLYPHS[ch.toUpperCase()];
    if (strokes) {
      for (let s = 0; s < strokes.length; s++) {
        const pts = strokes[s];
        if (pts.length === 4) {
          brush.line(
            curX + pts[0] * charW,
            startY + pts[1] * capH,
            curX + pts[2] * charW,
            startY + pts[3] * capH
          );
        } else {
          for (let k = 0; k < pts.length - 2; k += 2) {
            brush.line(
              curX + pts[k] * charW,
              startY + pts[k + 1] * capH,
              curX + pts[k + 2] * charW,
              startY + pts[k + 3] * capH
            );
          }
        }
      }
    }
    curX += charW + tracking;
  }
}
